		public override void OnApplyTemplate()
		{
			_gc = GetTemplateChild("PART_GridControl") as GridControl;
			if (_gc != null)
			{
				if (AllowColumnChooser.HasValue)
				{
					_gc.AllowColumnChooser = AllowColumnChooser.Value;
				}
				RequestRebuild();
				RegisterEventsForGridControl();
			}
			base.OnApplyTemplate();
		}

		public void UpdateDataGrid()
