				finally
				{
					_rebuildOperation = null;
				}
			});
		}

		private void RebuildAll()
		{
			if (_gc != null)
			{
				RebuildGridDataSource();
				RefreshGridData();
				PopulateColumnHeaderUnits();
			}
		}

		public string GetCellCxsDataPath(DataCellInfo cell)
		{
			IDataCell data = cell.Data;
			if (data != null && data.Tag is NewCellDataPackage newCellDataPackage)
			{
				return newCellDataPackage.DataPath;
			}
			return null;
		}

		public void OnHideInvolvedRows(int startColumnIndex)
		{
			base.Dispatcher.BeginInvoke((Action)delegate
			{
				if (_gc.DataSource == null)
				{
					return;
				}
				foreach (DataRow row in _gc.DataSource.Rows)
				{
					bool flag = true;
					for (int i = startColumnIndex; i < _gc.DataSource.Columns.Count; i++)
					{
						if (row[i] != null && row[i].Value != null)
						{
							string text = row[i].Value.ToString();
							if (!string.IsNullOrEmpty(text) && !string.Equals(text, "0"))
							{
								flag = false;
								break;
							}
						}
					}
					if (flag)
					{
						row.Visibility = Visibility.Collapsed;
					}
					else
					{
						row.Visibility = Visibility.Visible;
					}
				}
			});
		}

		private void RegisterEventsForGridControl()
		{
			_gc.CellValueQueried += _gc_CellValueQueried;
			_gc.DataCopying += _gc_DataCopying;
			_gc.DataDragging += _gc_DataDragging;
			_gc.DefaultContextMenuOpening += _gc_DefaultContextMenuOpening;
			_gc.CellValueChanged += _gc_CellValueChanged;
		}

		private void _gc_CellValueChanged(object sender, CellValueChangedEventArgs e)
		{
			(e.Data.Column.Tag as AdsField).CellValueChanged(sender, e, _unitsProvider);
		}

		private void RebuildGridDataSource()
		{
			List<DataColumn> list = new List<DataColumn>();
			foreach (AdsField field in Fields)
			{
				if (!field.IsPickedOut)
				{
					list.Add(GenerateDataColumn(field));
				}
			}
			_gc.DataSource = new DataTable(list);
		}

		private void AdsDataGrid_Loaded(object sender, RoutedEventArgs e)
		{
			if (!_firstTimeLoaded)
			{
				_firstTimeLoaded = true;
				OnFirstTimeLoaded();
			}
		}

		private void Fields_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			if (e.OldItems != null)
			{
				foreach (AdsField oldItem in e.OldItems)
				{
					oldItem.Container = null;
					oldItem.IsPickedOutPropertyChanged -= Field_IsPickedOutPropertyChanged;
				}
			}
			if (e.NewItems == null)
			{
				return;
			}
			foreach (AdsField newItem in e.NewItems)
			{
				newItem.Container = this;
				newItem.IsPickedOutPropertyChanged += Field_IsPickedOutPropertyChanged;
			}
		}

		private void Field_IsPickedOutPropertyChanged(object sender, EventArgs e)
		{
			RequestRebuild();
		}

		private void _gc_CellValueQueried(object sender, CellValueQueriedEventArgs e)
		{
			if (_accessor != null && _rowsElement != null)
			{
				int rowIndex = (int)e.Row.Tag;
				bool isLastRow = _gc.DataSource != null && _gc.DataSource.Rows.Count() > 0 && _gc.DataSource.Rows.Last() == e.Row;
				AdsField adsField = e.Column.Tag as AdsField;
				if (!string.IsNullOrEmpty(adsField.PropertyPath))
				{
					e.Data = adsField.GetDataCell(e, _accessor, _rowsElement, AdbTopProvider, rowIndex, baseIndex, ContainerViewModel, AutoFillUnitsInColumnHeader, isLastRow, ConvertToZeroThreshold);
					ProcessColumnHeaderUnitsRelated(adsField, e.Column);
				}
			}
		}

		private void _gc_DataCopying(object sender, GridControlCopyEventArgs e)
		{
			AdsDataGridClipboardHelper.DoDataCopy(this, e);
		}

		private void _gc_DataDragging(object sender, GridControlDataDraggingEventArgs e)
		{
			AdsDataGridClipboardHelper.DoDataDrag(this, e);
		}

		private void _gc_DefaultContextMenuOpening(object sender, DefaultContextMenuEventArgs e)
		{
			if (e.DefaultContextMenu.Items.Count > 0)
			{
				e.DefaultContextMenu.Items.Add(new Separator());
			}
			e.DefaultContextMenu.Items.Add(new MenuItem
			{
				Icon = new System.Windows.Controls.Image
				{
					Source = ImageSourceHelper.Copy16
				},
				Command = ApplicationCommands.Copy,
				CommandTarget = e.GridControl
			});
		}

		private void RefreshGridData()
		{
			if (_gc == null || _gc.DataSource == null || AdbTopProvider == null || ContainerViewModel == null || string.IsNullOrEmpty(IndexerPath))
			{
				return;
			}
			IAdbTop activeAdbTop = AdbTopProvider.GetActiveAdbTop();
			if (activeAdbTop == null)
			{
				_gc.DataSource.Rows.Clear();
				return;
			}
			string adsIndexerPath = PathGenerator.GetAdsIndexerPath(activeAdbTop, ContainerViewModel, IndexerPath);
			if (string.IsNullOrEmpty(adsIndexerPath))
			{
				return;
			}
			_accessor = new Accessor(activeAdbTop);
			_rowsElement = _accessor.ObjectAtPath(null, adsIndexerPath);
			if (_rowsElement != null && _rowsElement.success && HasDataToDisplay)
			{
				int updatedRowsCount = _accessor.NumberOfChildren(_rowsElement);
				_gc.DataSource.UpdateRows(updatedRowsCount, GenerateDataRow);
				if (HideInvolvedRows)
				{
					OnHideInvolvedRows(BeginHideColumnIndex);
				}
			}
			else
			{
				_gc.DataSource.Rows.Clear();
			}
		}

		public void InvalidateGridData()
		{
			if (_invalidateFlag)
			{
				return;
			}
			_invalidateFlag = true;
			base.Dispatcher.BeginInvoke((Action)delegate
			{
				try
				{
					RefreshGridData();
					PopulateColumnHeaderUnits();
				}
				finally
				{
					_invalidateFlag = false;
				}
			});
		}

		private void PopulateColumnHeaderUnits()
		{
			if (_gc == null || _gc.DataSource == null)
			{
				return;
			}
			if (_unitsProvider == null && ContainerViewModel != null && ContainerViewModel.UnityContainer != null)
			{
				_unitsProvider = CxvUnityContainerExtensions.TryResolve<IAdbUnitsProvider>(ContainerViewModel.UnityContainer);
			}
			if (_unitsProvider == null)
			{
				return;
			}
			foreach (DataColumn column in _gc.DataSource.Columns)
			{
				ProcessColumnHeaderUnitsRelated(column.Tag as AdsField, column);
			}
			if (_gc != null && _gc.DataSource != null)
			{
				InternalGridControl.InvalidateData();
			}
		}

		private void ProcessColumnHeaderUnitsRelated(AdsField field, DataColumn column)
		{
			if (_unitsProvider == null || field.DataAttribute != "value")
			{
				return;
			}
			object finalUnitsKind = field.FinalUnitsKind;
			if (finalUnitsKind == null)
			{
				return;
			}
			if (_gc == null || _gc.DataSource.Rows.Count == 0)
			{
				column.HeaderContentTemplate = null;
				return;
			}
			string defaultDisplayUnits = _unitsProvider.GetDefaultDisplayUnits(finalUnitsKind);
			if (defaultDisplayUnits != null && (!string.Equals(field.DefaultDisplayUnits, defaultDisplayUnits) || column.HeaderContentTemplate == null) && !defaultDisplayUnits.Equals("Unitless", StringComparison.CurrentCultureIgnoreCase))
			{
				string currentHeaderUnits = (field.DefaultDisplayUnits = defaultDisplayUnits);
				field.CurrentHeaderUnits = currentHeaderUnits;
				if (field.HeaderUnitsList == null)
				{
					field.HeaderUnitsList = _unitsProvider.GetUnitsList(finalUnitsKind);
				}
				if (column.HeaderContentTemplate == null)
				{
					column.HeaderContentTemplate = field.GenerateUnitsComboHeaderTemplate();
					field.SelectedHeaderUnitsChanged += field_SelectedHeaderUnitsChanged;
				}
			}
		}

		private void field_SelectedHeaderUnitsChanged(object sender, EventArgs e)
		{
			if (_gc == null || _gc.DataSource == null || _unitsProvider == null)
			{
				return;
			}
			AdsField field = sender as AdsField;
			DataTable dataSource = _gc.DataSource;
			DataColumn dataColumn = _gc.DataSource.Columns.FirstOrDefault((DataColumn x) => x.Tag == field);
			if (dataColumn == null)
			{
				return;
			}
			foreach (DataRow row in dataSource.Rows)
			{
				if (row.IsDataLoaded(dataColumn))
				{
					UpdateCellValueOnUnitsChanged(row[dataColumn], field, dataColumn);
				}
			}
		}

		private void OnUpdateDisplayEvent(UpdateDisplayEventArgs e)
		{
			InvalidateGridData();
		}

		private async void OnResultGridRefreshEvent(ResultGridRefreshEventEventArgs e)
		{
			if (e.BlockPath != null)
			{
				string blockPath = PathGenerator.GetBlockPath(ContainerViewModel);
				if (e.BlockPath.Equals(blockPath, StringComparison.CurrentCultureIgnoreCase))
				{
					await Task.Delay(1000);
					InvalidateGridData();
				}
			}
		}

		private void UpdateCellValueOnUnitsChanged(IDataCell dc, AdsField field, DataColumn column)
		{
			if (dc.Value == null || !(dc.ValueType == DataRow.NullableDoubleType))
			{
				return;
			}
			double sourceValue = (double)(dc.Tag as NewCellDataPackage).Value;
			double? num = _unitsProvider.ConvertFromSI(field.FinalUnitsKind, sourceValue, field.CurrentHeaderUnits);
			if (num.HasValue)
			{
				if (field.Converter != null)
				{
					dc.Value = field.Converter.Convert(num.Value, typeof(object), null, null);
				}
				else if (Math.Abs(num.Value) < 1E-15)
				{
					dc.Value = 0.0;
				}
				else if (Math.Abs(num.Value) == 1E+35)
				{
					dc.Value = null;
				}
				else
				{
					dc.Value = num.Value;
				}
			}
		}

