		protected virtual void OnContainerViewModelChanged(CxvViewModel oldValue, CxvViewModel newValue)
		{
			RefreshGridData();
			PopulateColumnHeaderUnits();
			if (oldValue != null && oldValue.UnityContainer != null)
			{
				oldValue.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ViewUpdateDisplayEvent>().Unsubscribe(OnUpdateDisplayEvent);
				oldValue.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ResultGridRefreshEvent>().Unsubscribe(OnResultGridRefreshEvent);
				oldValue.UnityContainer.Resolve<CxsCase>(Array.Empty<ResolverOverride>()).Message -= CxsCase_Message;
			}
			if (newValue != null && newValue.UnityContainer != null)
			{
				newValue.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ViewUpdateDisplayEvent>().Subscribe(OnUpdateDisplayEvent);
				newValue.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ResultGridRefreshEvent>().Subscribe(OnResultGridRefreshEvent);
				newValue.UnityContainer.Resolve<CxsCase>(Array.Empty<ResolverOverride>()).Message += CxsCase_Message;
			}
		}

		private void CxsCase_Message(object sender, CxsMessageEventArgs e)
		{
			foreach (CxsMessage message in e.Messages)
			{
				if (message.MessageType == CxsMessageType.Custom)
				{
					if (message.Number != 1373)
					{
						continue;
					}
					if (Dispatcher.CurrentDispatcher != base.Dispatcher)
					{
						base.Dispatcher.BeginInvoke((Action)delegate
						{
							if (UpdateWithSimulationIntegrationStep)
							{
								InvalidateGridData();
							}
						});
					}
					else if (UpdateWithSimulationIntegrationStep)
					{
						InvalidateGridData();
					}
				}
				else if (message.MessageType == CxsMessageType.RunPaused)
				{
					if (Dispatcher.CurrentDispatcher != base.Dispatcher)
					{
						base.Dispatcher.BeginInvoke((Action)delegate
						{
							InvalidateGridData();
						});
					}
					else
					{
						InvalidateGridData();
					}
				}
				else
				{
					if (message.MessageType != CxsMessageType.RunCompleted)
					{
						continue;
					}
					if (Dispatcher.CurrentDispatcher != base.Dispatcher)
					{
						base.Dispatcher.BeginInvoke((Action)delegate
						{
							InvalidateGridData();
						});
					}
					else
					{
						InvalidateGridData();
					}
				}
			}
		}

