		Dictionary<int, string> IMMScrollAreaPlot.GetVisibleFieldInfo()
		{
			try
			{
				if (_gc == null || _gc.DataSource == null || _gc.DataSource.Rows.Count <= 1)
				{
					return null;
				}
				Dictionary<int, string> dictionary = new Dictionary<int, string>();
				_ = _gc.DataSource.Rows[0];
				foreach (DataColumn column in _gc.DataSource.Columns)
				{
					if (column.Visibility == Visibility.Visible && column.DisplayIndex >= 0)
					{
						string label = Fields[column.DisplayIndex].Label;
						string propertyPath = Fields[column.DisplayIndex].PropertyPath;
						string value = label + "," + propertyPath;
						dictionary.Add(column.DisplayIndex, value);
					}
				}
				if (dictionary.Count == 0)
				{
					return null;
				}
				return dictionary;
			}
			catch (Exception)
			{
			}
			return null;
		}

		Dictionary<int, string> IMMScrollAreaPlot.GetVisibleFields()
		{
			return ((IMMScrollAreaPlot)this).DoGetVisibleFields(isListRequested: true);
		}

		Dictionary<int, string> IMMScrollAreaPlot.DoGetVisibleFields(bool isListRequested)
		{
			try
			{
				if (_gc == null || _gc.DataSource == null || _gc.DataSource.Rows.Count <= 1)
				{
					return null;
				}
				Dictionary<int, string> dictionary = new Dictionary<int, string>();
				DataTable dataSource = _gc.DataSource;
				DataRow dataRow = dataSource.Rows[0];
				foreach (DataColumn column in _gc.DataSource.Columns)
				{
					if (column.Visibility != Visibility.Visible)
					{
						continue;
					}
					IDataCell dataCell = dataRow[column];
					bool flag = false;
					if (dataCell == null || dataCell.Value == null)
					{
						for (int i = 1; i < dataSource.Rows.Count; i++)
						{
							dataCell = dataSource.Rows[i][column];
							if (dataCell != null && dataCell.Value != null)
							{
								flag = true;
								break;
							}
						}
					}
					else
					{
						flag = true;
					}
					if (flag && double.TryParse(dataCell.Value.ToString(), out var _))
					{
						if (!isListRequested)
						{
							return dictionary;
						}
						if (column.DisplayIndex >= 0)
						{
							dictionary.Add(column.DisplayIndex, GetColumnHeader(column).Replace(Environment.NewLine, " "));
						}
					}
				}
				if (!isListRequested && dictionary.Count == 0)
				{
					return null;
				}
				return dictionary;
			}
			catch (Exception)
			{
			}
			return null;
		}

		IEnumerable<Tuple<int, string>> IMMScrollAreaPlot.EnumerateVisibleFields()
		{
			if (_gc == null || _gc.DataSource == null || _gc.DataSource.Rows.Count <= 1)
			{
				yield break;
			}
			DataTable table = _gc.DataSource;
			DataRow firstRow = table.Rows[0];
			foreach (DataColumn column in _gc.DataSource.Columns)
			{
				if (column.Visibility != Visibility.Visible)
				{
					continue;
				}
				IDataCell dataCell = firstRow[column];
				bool flag = false;
				if (dataCell == null || dataCell.Value == null)
				{
					for (int i = 1; i < table.Rows.Count; i++)
					{
						dataCell = table.Rows[i][column];
						if (dataCell != null && dataCell.Value != null)
						{
							flag = true;
							break;
						}
					}
				}
				else
				{
					flag = true;
				}
				if (flag && double.TryParse(dataCell.Value.ToString(), out var _) && column.DisplayIndex >= 0)
				{
					yield return new Tuple<int, string>(column.DisplayIndex, GetColumnHeader(column).Replace(Environment.NewLine, " "));
				}
			}
		}

