		void IMMScrollAreaPlot.SelectField(int displayId, bool clearCurrentSelection)
		{
			if (_gc == null)
			{
				return;
			}
			DataColumn dataColumn = _gc.ColumnFromDisplayIndex(displayId);
			if (dataColumn == null)
			{
				return;
			}
			_gc.SupressSelectionChangedEvent = true;
			try
			{
				if (clearCurrentSelection)
				{
					_gc.DeselectAll();
				}
				_gc.SelectColumn(dataColumn);
			}
			finally
			{
				_gc.SupressSelectionChangedEvent = false;
			}
		}

