		List<string> IMMScrollAreaPlot.GetSelectedFields()
		{
			List<string> list = new List<string>();
			if (_gc != null && _gc.DataSource != null)
			{
				foreach (DataColumn item in _gc.TotalSelectedCells.Select((DataCellInfo x) => x.Column).Distinct())
				{
					if (item.Visibility == Visibility.Visible)
					{
						string columnHeader = GetColumnHeader(item);
						if (columnHeader == null)
						{
							list.Add(string.Empty);
						}
