		private void EnsurePlotValue()
		{
			if (_plotValues == null && ContainerViewModel != null && ContainerViewModel.UnityContainer != null)
			{
				_plotValues = ContainerViewModel.UnityContainer.Resolve<AdhocPlot>(Array.Empty<ResolverOverride>());
				ContainerViewModel.UnityContainer.RegisterInstance(base.Name, (IAdhocPlot)_plotValues, (LifetimeManager)new ExternallyControlledLifetimeManager());
