		private List<PlotVariableDescriptor> PlotVariablesFromSelection(GridControl gc)
		{
			List<PlotVariableDescriptor> list = new List<PlotVariableDescriptor>();
			List<DataCellInfo> list2 = gc.TotalSelectedCells.ToList();
			if (list2.Count >= 2)
			{
				foreach (DataCellInfo item in list2)
				{
					IDataCell data = item.Data;
					if (data != null)
					{
						string cellCxsDataPath = GetCellCxsDataPath(item);
						string dimension = ContainerViewModel.ExpandDataPathAndGet(cellCxsDataPath, "dimension") as string;
						list.Add(new PlotVariableDescriptor
						{
							Path = cellCxsDataPath,
							CurrentValue = data.Value,
							ExposeAs = GetVariableTypeCode(data.ValueType),
							Column = item.Column.DisplayIndex,
							Location = item.Row.DataTable.Rows.IndexOf(item.Row),
							Dimension = dimension,
							Units = (item.Column.Tag as AdsField).CurrentHeaderUnits,
							Decorated_name = item.Column.Header
						});
					}
				}
			}
			return list;
		}

		private static CxvVariableTypeCode GetVariableTypeCode(Type valueType)
		{
			if (valueType == typeof(double?))
			{
				return CxvVariableTypeCode.Real;
			}
			if (valueType == typeof(int?))
			{
				return CxvVariableTypeCode.Integer;
			}
			if (valueType == typeof(bool))
			{
				return CxvVariableTypeCode.Boolean;
			}
			if (valueType == typeof(string))
			{
				return CxvVariableTypeCode.String;
			}
			return CxvVariableTypeCode.Unknown;
		}

		private static string GetColumnHeader(DataColumn column)
		{
			string text = column.Header;
			if (column.Tag is AdsField adsField && !string.IsNullOrEmpty(adsField.CurrentHeaderUnits) && !string.Equals(adsField.CurrentHeaderUnits, "fraction"))
			{
				text = $"{text} {adsField.CurrentHeaderUnits}";
			}
			return text;
		}

