		IEnumerable<string> IVariableControl.GetVariableMonikers()
		{
			List<string> list = new List<string>();
			if (InternalGridControl != null && InternalGridControl.DataSource != null)
			{
				foreach (DataRow row in InternalGridControl.DataSource.Rows)
				{
					if (row.Visibility != Visibility.Visible)
					{
						continue;
					}
					foreach (DataColumn column in InternalGridControl.DataSource.Columns)
					{
						if (column.Visibility == Visibility.Visible)
						{
							DataCellInfo cell = new DataCellInfo(row, column);
							string text = GetCellCxsDataPath(cell);
							if (!string.IsNullOrEmpty(text))
							{
								text = "cxs:" + text.Replace("Top.appModelV8", "Top.appModel");
							}
							if (!list.Contains(text))
							{
								list.Add(text);
							}
						}
					}
				}
			}
			return list;
		}

