		protected virtual (AccessorElement valueElement, int unitRow, string variableName) ResolveAdsElementProperty(string elementPath, IAccessor accessor, AccessorElement rowsElement, IAdbTopProvider adbTopProvider, int rowIndex, int baseIndex, CxvViewModel containerViewModel)
		{
			if (elementPath.StartsWith("@main."))
			{
				int num = elementPath.LastIndexOf(".");
				string indexer = elementPath.Substring(0, num).Replace("@rowid", $"#{rowIndex}");
				string text = elementPath.Substring(num + 1);
				IAdbTop activeAdbTop = adbTopProvider.GetActiveAdbTop();
				string adsIndexerPath = PathGenerator.GetAdsIndexerPath(activeAdbTop, containerViewModel, indexer);
				if (string.IsNullOrEmpty(adsIndexerPath))
				{
					return (valueElement: null, unitRow: 0, variableName: null);
				}
				AccessorElement start = accessor.ObjectAtPath(null, adsIndexerPath);
				if (text.Equals("@rowid"))
				{
					AccessorElement accessorElement = accessor.ObjectAtPath(start, $"#{rowIndex}");
					return (valueElement: accessorElement, unitRow: accessorElement.unitrow, variableName: accessorElement.attribute);
				}
				string indexer2 = elementPath.Replace("@rowid", $"#{rowIndex}");
				start = accessor.ObjectAtPath(null, PathGenerator.GetAdsIndexerPath(activeAdbTop, containerViewModel, indexer2));
				if (start != null && start.success)
				{
					return (valueElement: start, unitRow: start.unitrow, variableName: start.attribute);
				}
				return (valueElement: null, unitRow: 0, variableName: null);
			}
			if (elementPath.Contains('@'))
			{
				string indexer3 = null;
				if (elementPath.Contains("@rowid"))
				{
					AccessorElement accessorElement2 = accessor.ObjectAtPath(rowsElement, $"#{rowIndex}");
					if (elementPath.Equals("@rowid"))
					{
						return (valueElement: accessorElement2, unitRow: accessorElement2.unitrow, variableName: accessorElement2.attribute);
					}
					if (accessorElement2.attribute != null)
					{
						indexer3 = elementPath.Replace("@rowid", accessorElement2.attribute.ToString());
						if (indexer3 != null)
						{
							string adsIndexerPath2 = PathGenerator.GetAdsIndexerPath(adbTopProvider.GetActiveAdbTop(), containerViewModel, indexer3);
							AccessorElement accessorElement3 = accessor.ObjectAtPath(null, adsIndexerPath2);
							if (accessorElement3 != null)
							{
								return (valueElement: accessorElement3, unitRow: accessorElement3.unitrow, variableName: accessorElement3.attribute);
							}
						}
						return (valueElement: null, unitRow: 0, variableName: null);
					}
				}
				else
				{
					indexer3 = elementPath.Replace("@y", $"#{rowIndex}");
				}
				string adsIndexerPath3 = PathGenerator.GetAdsIndexerPath(adbTopProvider.GetActiveAdbTop(), containerViewModel, indexer3);
				if (string.IsNullOrEmpty(adsIndexerPath3))
				{
					return (valueElement: null, unitRow: 0, variableName: null);
				}
				AccessorElement accessorElement4 = accessor.ObjectAt(null, new string[1] { adsIndexerPath3 });
				if (accessorElement4 != null)
				{
					return (valueElement: accessorElement4, unitRow: accessorElement4.unitrow, variableName: accessorElement4.attribute);
				}
			}
			else if (elementPath.Contains('.'))
			{
				AccessorElement accessorElement5 = accessor.ObjectAtPath(rowsElement, "#" + (baseIndex + rowIndex) + "." + elementPath);
				if (accessorElement5.success)
				{
					return (valueElement: accessorElement5, unitRow: accessorElement5.unitrow, variableName: accessorElement5.attribute);
				}
			}
			else
			{
				AccessorElement accessorElement6 = accessor.ObjectAt(rowsElement, new string[2]
				{
					$"#{baseIndex + rowIndex}",
					elementPath
				});
				if (accessorElement6.success)
				{
					return (valueElement: accessorElement6, unitRow: accessorElement6.unitrow, variableName: accessorElement6.attribute);
				}
			}
			return (valueElement: null, unitRow: 0, variableName: null);
		}

		public virtual IDataCell GetDataCell(CellValueQueriedEventArgs e, IAccessor accessor, AccessorElement rowsElement, IAdbTopProvider adbTopProvider, int rowIndex, int baseIndex, CxvViewModel containerViewModel, bool autoFillUnitsInColumnHeader, bool isLastRow, double convertToZeroThreshold)
		{
			if (_unitsProvider == null && containerViewModel != null && containerViewModel.UnityContainer != null)
			{
				_unitsProvider = CxvUnityContainerExtensions.TryResolve<IAdbUnitsProvider>(containerViewModel.UnityContainer);
			}
			if (_unitsProvider != null)
			{
				(AccessorElement, int, string) peData = ResolveAdsElementProperty(PropertyPath, accessor, rowsElement, adbTopProvider, rowIndex, baseIndex, containerViewModel);
				if (peData.Item1 != null)
				{
					UpdataFiledUnit(peData, autoFillUnitsInColumnHeader);
					return CreatDataCell(e, peData, isLastRow, convertToZeroThreshold);
				}
				AccessorElement accessorElement = accessor.ObjectAt(rowsElement, new string[2]
				{
					$"#{rowIndex}",
					PropertyPath
				});
				if (accessorElement != null)
				{
					UpdataFiledUnit((valueElement: accessorElement, unitRow: accessorElement.unitrow, variableName: accessorElement.attribute), autoFillUnitsInColumnHeader);
					return CreatDataCell(e, (valueElement: accessorElement, unitRow: accessorElement.unitrow, variableName: accessorElement.attribute), isLastRow, convertToZeroThreshold);
				}
			}
			return DataRow.CreateDataCell(string.Empty);
		}

		private void UpdataFiledUnit((AccessorElement valueElement, int unitRow, string variableName) peData, bool autoFillUnitsInColumnHeader)
		{
			if (autoFillUnitsInColumnHeader)
			{
				if (peData.unitRow > 0 && UnitsKind == null && InternalUnitsKind == null)
				{
					InternalUnitsKind = peData.unitRow;
				}
				else if (UnitsKind != null && InternalUnitsKind == null)
				{
					InternalUnitsKind = UnitsKind;
				}
				if (CurrentHeaderUnits == null && InternalUnitsKind != null)
				{
					string defaultDisplayUnits = _unitsProvider.GetDefaultDisplayUnits(InternalUnitsKind);
					string currentHeaderUnits = (DefaultDisplayUnits = defaultDisplayUnits);
					CurrentHeaderUnits = currentHeaderUnits;
				}
			}
		}

		private IDataCell CreatDataCell(CellValueQueriedEventArgs e, (AccessorElement valueElement, int unitRow, string variableName) peData, bool isLastRow, double convertToZeroThreshold)
		{
			if (DataAttribute == "attribute")
			{
				object value = peData.variableName;
				if (Converter != null)
				{
					value = Converter.Convert(peData.variableName, typeof(object), isLastRow, null);
				}
				IDataCell dataCell = DataRow.CreateDataCell(value);
				if (dataCell != null)
				{
					dataCell.Tag = new NewCellDataPackage(value, PathGenerator.SimplyConvertAdsPathToCxsPath(peData.valueElement.cxsPath));
				}
				return dataCell;
			}
			if (peData.valueElement.value != null)
			{
				object value2 = peData.valueElement.value;
				int num = CxsConverter.ValueToInt32(FinalUnitsKind) ?? 0;
				object obj = value2;
				if (_unitsProvider != null && num > 0 && obj != null && Math.Abs((double)obj) != 1E+35)
				{
					double? num2 = _unitsProvider.ConvertFromSI(num, Convert.ToDouble(obj), CurrentHeaderUnits);
					if (num2.HasValue)
					{
						obj = num2.Value;
					}
				}
				if (convert != null)
				{
					obj = convert(obj);
				}
				if (Converter != null)
				{
					obj = Converter.Convert(obj, typeof(object), isLastRow, null);
				}
				if (obj is double)
				{
					if (Math.Abs((double)obj) < convertToZeroThreshold)
					{
						obj = 0.0;
					}
					else if (Math.Abs((double)obj) == 1E+35)
					{
						obj = null;
					}
				}
				IDataCell dataCell2 = DataRow.CreateDataCell(obj);
				if (dataCell2 != null)
				{
					dataCell2.Tag = new NewCellDataPackage(value2, PathGenerator.SimplyConvertAdsPathToCxsPath(peData.valueElement.cxsPath));
				}
				return dataCell2;
			}
			return DataRow.CreateDataCell(string.Empty);
		}

