			frameworkElementFactory2.SetValue(Grid.RowProperty, 1);
			FrameworkElementFactory frameworkElementFactory3 = new FrameworkElementFactory(typeof(Grid));
			FrameworkElementFactory frameworkElementFactory4 = new FrameworkElementFactory(typeof(RowDefinition));
			frameworkElementFactory4.SetValue(RowDefinition.HeightProperty, new GridLength(100.0, GridUnitType.Star));
			frameworkElementFactory3.AppendChild(frameworkElementFactory4);
			FrameworkElementFactory frameworkElementFactory5 = new FrameworkElementFactory(typeof(RowDefinition));
			frameworkElementFactory5.SetValue(RowDefinition.HeightProperty, new GridLength(16.0, GridUnitType.Auto));
			frameworkElementFactory3.AppendChild(frameworkElementFactory5);
