				if (tuple.Item1 == null)
				{
					return DataRow.CreateDataCell(string.Empty);
				}
				(string, IEnumerable<string>) tuple2 = ResolveUnitElement(tuple.Item1.value);
				IDataCell dataCell = DataRow.CreateDataCell(tuple2.Item1, isReadOnly: false, tuple2.Item2, CellUIType.ComboBox);
				if (dataCell != null)
