		private (string displayUnit, IEnumerable<string> units) ResolveUnitElement(object unitRow)
		{
			if (_unitsProvider == null)
			{
				return (displayUnit: null, units: null);
			}
			string defaultDisplayUnits = _unitsProvider.GetDefaultDisplayUnits(unitRow);
			IEnumerable<string> unitsList = _unitsProvider.GetUnitsList(unitRow);
			return (displayUnit: defaultDisplayUnits, units: unitsList);
		}

		public override void CellValueChanged(object sender, CellValueChangedEventArgs e, IAdbUnitsProvider unitsProvider)
		{
			if (unitsProvider == null || !(sender is GridControl { DataSource: not null } gridControl) || !(e.Data.Tag is NewCellDataPackage newCellDataPackage))
			{
				return;
			}
			int index = (int)e.Data.Row.Tag;
			string[] array = CellColumnIndexString.Split(new char[1] { ',' }, StringSplitOptions.RemoveEmptyEntries);
			object unitValue = newCellDataPackage.UnitValue;
			string[] array2 = array;
			foreach (string index2 in array2)
			{
				IDataCell dataCell = gridControl.DataSource.Rows[index][index2];
				NewCellDataPackage newCellDataPackage2 = dataCell.Tag as NewCellDataPackage;
				if (dataCell.Value == null || !(dataCell.ValueType == DataRow.NullableDoubleType))
				{
					continue;
				}
				double? num = unitsProvider.ConvertFromSI(unitValue, (double)newCellDataPackage2.Value, (string)e.NewValue);
				if (num.HasValue)
				{
					if (base.Converter != null)
					{
						dataCell.Value = base.Converter.Convert(num.Value, typeof(object), null, null);
					}
					else if (Math.Abs(num.Value) < 1E-15)
					{
						dataCell.Value = 0.0;
					}
					else if (num.Value == 1E+35)
					{
						dataCell.Value = null;
					}
					else
					{
						dataCell.Value = num.Value;
					}
				}
			}
		}
	}
