		protected override (AccessorElement valueElement, int unitRow, string variableName) ResolveAdsElementProperty(string elementPath, IAccessor accessor, AccessorElement rowsElement, IAdbTopProvider adbTopProvider, int rowIndex, int baseIndex, CxvViewModel containerViewModel)
		{
			if (!string.IsNullOrEmpty(elementPath))
			{
				if (elementPath.StartsWith("@main"))
				{
					return base.ResolveAdsElementProperty(elementPath, accessor, rowsElement, adbTopProvider, rowIndex, baseIndex, containerViewModel);
				}
				StringBuilder stringBuilder;
				if (elementPath.Contains("@"))
				{
					stringBuilder = new StringBuilder();
