					foreach (string parameter in array)
					{
						stringBuilder.Append(containerViewModel.ResolveParameter(parameter)?.ToString());
					}
				}
				else
				{
					stringBuilder = new StringBuilder(elementPath);
				}
				string text = string.Empty;
				AccessorElement accessorElement = accessor.ObjectAtPath(rowsElement, string.Format("#{0}.{1}", rowIndex, "VariableNames"));
