			return null;
		}

		private string GetIdByName(string variableName, AccessorElement parentElement, IAccessor accessor)
		{
			int num = accessor.NumberOfChildren(parentElement);
			for (int i = 0; i < num; i++)
			{
				int num2 = 0;
				AccessorElement accessorElement;
				do
				{
					accessorElement = accessor.ObjectAtPath(parentElement, $"#{i}");
				}
				while (accessorElement.value == null && num2++ < 10);
				if (accessorElement.success && accessorElement.value.Equals(variableName))
				{
					return accessorElement.attribute;
				}
			}
			return null;
		}
