			}
			if (adsFlowsheetPath == null)
			{
				throw new ArgumentNullException("adsFlowsheetPath");
			}
			string text = adsFlowsheetPath;
			while (text.EndsWith(".SubFlowsheets.Simulation"))
			{
				if (provider.GetAccessorElement(text + ".IsBatch").GetBooleanValue() == true)
				{
					return true;
				}
				text = text.Substring(0, text.Length - ".SubFlowsheets.Simulation".Length);
				int num = text.LastIndexOf(".SubFlowsheets.Simulation.");
				if (num <= 0)
				{
					break;
				}
				text = text.Substring(0, num + ".SubFlowsheets.Simulation".Length);
			}
			return provider.GetAccessorElement("Flowsheet.IsBatch").GetBooleanValue() == true;
		}

