						val3 = Math.Max(val3, internalChild2.DesiredSize.Height);
					}
				}
				double val4 = availableSize.Width - num2;
				autoFitElement.Measure(new System.Windows.Size(Math.Max(val4, AutoFitMinLength), availableSize.Height));
				return new System.Windows.Size(num2 + autoFitElement.DesiredSize.Width, Math.Max(val3, autoFitElement.DesiredSize.Height));
