	{
		public static readonly DependencyProperty SelectedColorProperty = DependencyProperty.Register("SelectedColor", typeof(System.Windows.Media.Color), typeof(ColorPicker), new FrameworkPropertyMetadata(OnSelectedColorPropertyChanged)
		{
			BindsTwoWayByDefault = true,
			DefaultValue = Colors.Black
		});

		public static readonly DependencyProperty SelectedColorIndexProperty = DependencyProperty.Register("SelectedColorIndex", typeof(int), typeof(ColorPicker), new FrameworkPropertyMetadata(OnSelectedColorIndexPropertyChanged)
		{
