		public ColorPicker()
		{
			InitializeComponent();
		}

		private static void OnSelectedColorPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			(d as ColorPicker).OnSelectedColorChanged((System.Windows.Media.Color)e.OldValue, (System.Windows.Media.Color)e.NewValue);
		}

		private void OnSelectedColorChanged(System.Windows.Media.Color oldValue, System.Windows.Media.Color newValue)
		{
			foreach (object child in (FindName("grdContainer") as Grid).Children)
			{
				if (!(child is ToggleButton toggleButton))
				{
					continue;
				}
				System.Windows.Media.Color color = (System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(toggleButton.Background.ToString());
				if (color == newValue)
				{
					if (color == Colors.Red)
					{
						toggleButton.BorderBrush = System.Windows.Media.Brushes.Blue;
					}
					else
					{
						toggleButton.BorderBrush = System.Windows.Media.Brushes.Red;
					}
					toggleButton.BorderThickness = new Thickness(2.0);
				}
				else
				{
					toggleButton.IsChecked = false;
					toggleButton.BorderThickness = new Thickness(0.0);
				}
			}
		}

		private static void OnSelectedColorIndexPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			(d as ColorPicker).OnSelectedColorIndexChanged((int)e.OldValue, (int)e.NewValue);
		}

		private void OnSelectedColorIndexChanged(int oldValue, int newValue)
		{
			if (oldValue == newValue || !(FindName("grdContainer") is Grid grid) || newValue < 0 || newValue > 15)
			{
				return;
			}
			ToggleButton toggleButton = null;
			foreach (ToggleButton child in grid.Children)
			{
				if (child.Tag != null && child.Tag.ToString() == newValue.ToString())
				{
					toggleButton = child;
					break;
				}
			}
			if (toggleButton != null)
			{
				SelectedColor = (System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(toggleButton.Background.ToString());
			}
		}

		private void ToggleButton_Click(object sender, RoutedEventArgs e)
		{
			if (!(sender is ToggleButton { IsChecked: not null, IsChecked: var isChecked } toggleButton) || !isChecked.Value)
			{
				return;
			}
			SelectedColor = (System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(toggleButton.Background.ToString());
