	public enum FormClosingCause
	{
		NotClosing,
		UserManuallyClosing,
		MainWindowClosing,
		CurrentDocumentClosing,
		EnvironmentSwitching
	}
	public static class FormClosingCauseHelper
	{
		private static FormClosingCause _explicitAssigned;

		public static void UpdateClosingCause(FormClosingCause cause)
		{
			if (_explicitAssigned != cause && (_explicitAssigned == FormClosingCause.NotClosing || cause == FormClosingCause.NotClosing))
			{
				_explicitAssigned = cause;
			}
		}

		public static FormClosingCause GetClosingCause(bool allowNotClosing)
		{
			if (allowNotClosing)
			{
				return _explicitAssigned;
			}
			if (_explicitAssigned != FormClosingCause.NotClosing)
			{
				return _explicitAssigned;
			}
			return FormClosingCause.UserManuallyClosing;
		}
	}
	public static class FormsManager
	{
		private class AssemblyFileInfo
		{
			public string AssemblyFullName { get; private set; }

			public DateTime LastAccessTime { get; private set; }

			private AssemblyFileInfo(string assemblyFullName, DateTime lastAccessTime)
			{
				AssemblyFullName = assemblyFullName;
				LastAccessTime = lastAccessTime;
			}

			public IList<FormInfo> ReflectionOnlyReadForms(string parentDirectory)
			{
				List<FormInfo> list = new List<FormInfo>();
				string assemblyFile = System.IO.Path.Combine(parentDirectory, AssemblyFullName);
				try
				{
					Type[] exportedTypes = Assembly.ReflectionOnlyLoadFrom(assemblyFile).GetExportedTypes();
					for (int i = 0; i < exportedTypes.Length; i++)
					{
						FormInfo formInfo = FormInfo.ReadFromType(exportedTypes[i], AssemblyFullName);
						if (formInfo != null)
						{
							list.Add(formInfo);
						}
					}
				}
				catch (FileLoadException)
				{
				}
				return list;
			}

			public XElement SaveToXElement()
			{
				XElement xElement = new XElement("File");
				xElement.SetAttributeValue("Name", AssemblyFullName);
				xElement.SetElementValue("LastAccessTime", XmlConvert.ToString(LastAccessTime, XmlDateTimeSerializationMode.Unspecified));
				return xElement;
			}

			public static AssemblyFileInfo ReadFromXElement(XElement element, string parentDirectory)
			{
				if (element == null)
				{
					throw new ArgumentNullException("element");
				}
				if (parentDirectory == null)
				{
					throw new ArgumentNullException("parentDirectory");
				}
				XAttribute xAttribute = element.Attribute("Name");
				if (xAttribute == null || string.IsNullOrEmpty(xAttribute.Value))
				{
					return null;
				}
				XElement xElement = element.Element("LastAccessTime");
				if (xElement == null || string.IsNullOrEmpty(xElement.Value))
				{
					return null;
				}
				if (!File.Exists(System.IO.Path.Combine(parentDirectory, xAttribute.Value)))
				{
					return null;
				}
				return new AssemblyFileInfo(xAttribute.Value, XmlConvert.ToDateTime(xElement.Value, XmlDateTimeSerializationMode.Unspecified));
			}

			public static AssemblyFileInfo ReadFromFile(string fullFilePath)
			{
				if (!File.Exists(fullFilePath))
				{
					return null;
				}
				FileInfo fileInfo = new FileInfo(fullFilePath);
				return new AssemblyFileInfo(fileInfo.Name, fileInfo.LastWriteTime);
			}
		}

		private class FormInfo
		{
			public string ProgId { get; private set; }

			public string AssemblyFilePath { get; private set; }

			public string TypeFullName { get; private set; }

			private FormInfo(string progId, string assemblyFullName, string typeFullName)
			{
				ProgId = progId;
				AssemblyFilePath = assemblyFullName;
				TypeFullName = typeFullName;
			}

			public Type ResolveFormType(string formsDirectory)
			{
				string text = System.IO.Path.Combine(formsDirectory, AssemblyFilePath);
				if (File.Exists(text))
				{
					return Assembly.LoadFrom(text).GetType(TypeFullName);
				}
				return null;
			}

			public XElement SaveToXElement()
			{
				XElement xElement = new XElement("Form");
				xElement.SetAttributeValue("ProgId", ProgId);
				xElement.SetElementValue("Assembly", AssemblyFilePath);
				xElement.SetElementValue("Type", TypeFullName);
				return xElement;
			}

			public static FormInfo ReadFromXElement(XElement element)
			{
				if (element == null)
				{
					throw new ArgumentNullException("element");
				}
				XAttribute xAttribute = element.Attribute("ProgId");
				if (xAttribute == null || string.IsNullOrEmpty(xAttribute.Value))
				{
					return null;
				}
				XElement xElement = element.Element("Assembly");
				if (xElement == null || string.IsNullOrEmpty(xElement.Value))
				{
					return null;
				}
				XElement xElement2 = element.Element("Type");
				if (xElement2 == null || string.IsNullOrEmpty(xElement2.Value))
				{
					return null;
				}
				return new FormInfo(xAttribute.Value, xElement.Value, xElement2.Value);
			}

			public static FormInfo ReadFromType(Type type, string assemblyName)
			{
				if (type == null)
				{
					throw new ArgumentNullException("type");
				}
				if (assemblyName == null)
				{
					throw new ArgumentNullException("assemblyName");
				}
				if (type.BaseType == null)
				{
					return null;
				}
				if (!IsDerivedFromViewModelContainer(type))
				{
					return null;
				}
				IList<CustomAttributeData> customAttributesData = type.GetCustomAttributesData();
				if (customAttributesData == null || customAttributesData.Count == 0)
				{
					return null;
				}
				CustomAttributeData customAttributeData = customAttributesData.FirstOrDefault((CustomAttributeData x) => x.Constructor.ReflectedType.Name == "ProgIdAttribute");
				if (customAttributeData == null)
				{
					return null;
				}
				string text = customAttributeData.ConstructorArguments[0].Value as string;
				if (string.IsNullOrEmpty(text))
				{
					return null;
				}
				return new FormInfo(text, assemblyName, type.FullName);
			}

			private static bool IsDerivedFromViewModelContainer(Type type)
			{
				if (type == null)
				{
					return false;
				}
				if (string.Equals(type.FullName, "AspenTech.AspenPlus.MMControls.MMViewModelContainer"))
				{
					return true;
				}
				return IsDerivedFromViewModelContainer(type.BaseType);
			}
		}

		private static readonly List<FormInfo> _formInfos = new List<FormInfo>();

		private static readonly Dictionary<string, Type> _progIdToTypes = new Dictionary<string, Type>();

		private static bool _reflectionOnlyLoadPrepared;

		private static string FormsDirectory { get; set; }

		public static bool IsInitialized { get; private set; }

		public static void Initialize(string formsDirectory, string cacheFilePath = null, string searchPattern = null, Func<string, bool> fileFilter = null)
		{
			if (string.IsNullOrEmpty(formsDirectory))
			{
				throw new ArgumentException("Parameter formsDirectory cannot be null or empty.");
			}
			_formInfos.Clear();
			_progIdToTypes.Clear();
			if (!Directory.Exists(formsDirectory))
			{
				return;
			}
			XElement xElement = null;
			if (!string.IsNullOrEmpty(cacheFilePath))
			{
				xElement = OpenCacheFile(cacheFilePath);
			}
			List<AssemblyFileInfo> list = ReadAssemblyFileInfos(formsDirectory, searchPattern, fileFilter);
			List<AssemblyFileInfo> list2 = null;
			if (xElement == null)
			{
				list2 = list;
			}
			else
			{
				List<AssemblyFileInfo> source = ReadAssemblyFileInfos(xElement, formsDirectory);
				list2 = new List<AssemblyFileInfo>();
				foreach (AssemblyFileInfo afi in list)
				{
					AssemblyFileInfo assemblyFileInfo = source.FirstOrDefault((AssemblyFileInfo x) => string.Equals(x.AssemblyFullName, afi.AssemblyFullName, StringComparison.InvariantCultureIgnoreCase));
					if (assemblyFileInfo == null || assemblyFileInfo.LastAccessTime != afi.LastAccessTime)
					{
						list2.Add(afi);
					}
				}
			}
			if (list2.Count > 0)
			{
				PrepareReflectionOnlyLoading();
				foreach (AssemblyFileInfo item in list2)
				{
					_formInfos.AddRange(item.ReflectionOnlyReadForms(formsDirectory));
				}
			}
			if (xElement != null)
			{
				XElement xElement2 = xElement.Element("Forms");
				if (xElement2 != null)
				{
					bool flag = list2.Count > 0;
					foreach (XElement item2 in xElement2.Elements())
					{
						FormInfo formInfo = FormInfo.ReadFromXElement(item2);
						if (formInfo == null)
						{
							continue;
						}
						if (flag)
						{
							if (!list2.Any((AssemblyFileInfo assemblyFileInfo2) => string.Equals(assemblyFileInfo2.AssemblyFullName, formInfo.AssemblyFilePath, StringComparison.InvariantCultureIgnoreCase)))
							{
								_formInfos.Add(formInfo);
							}
						}
						else
						{
							_formInfos.Add(formInfo);
						}
					}
				}
			}
			FormsDirectory = formsDirectory;
			if (list2.Count > 0 && !string.IsNullOrEmpty(cacheFilePath))
			{
				SaveCacheFile(cacheFilePath, list, _formInfos);
			}
			IsInitialized = true;
		}

		public static Type LookupTypeByProgId(string progId)
		{
			if (string.IsNullOrEmpty(progId))
			{
				throw new ArgumentException("Parameter progId cannot be null or empty.");
			}
			string key = progId.ToLowerInvariant();
			if (_progIdToTypes.ContainsKey(key))
			{
				return _progIdToTypes[key];
			}
			FormInfo formInfo = _formInfos.FirstOrDefault((FormInfo x) => string.Equals(x.ProgId, progId, StringComparison.InvariantCultureIgnoreCase));
			if (formInfo != null)
			{
				Type type = formInfo.ResolveFormType(FormsDirectory);
				if (type != null)
				{
					_progIdToTypes.Add(key, type);
					return type;
				}
			}
			return null;
		}

		public static void PrepareReflectionOnlyLoading()
		{
			if (_reflectionOnlyLoadPrepared)
			{
				return;
			}
			_reflectionOnlyLoadPrepared = true;
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			foreach (Assembly assembly in assemblies)
			{
				if (assembly is AssemblyBuilder)
				{
					continue;
				}
				string text = string.Empty;
				try
				{
					text = assembly.Location;
				}
				catch (Exception)
				{
				}
				if (!string.IsNullOrEmpty(text))
				{
					try
					{
						Assembly.ReflectionOnlyLoadFrom(text);
					}
					catch (Exception)
					{
					}
				}
			}
		}

		private static XElement OpenCacheFile(string cacheFilePath)
		{
			if (File.Exists(cacheFilePath))
			{
				try
				{
					string text = File.ReadAllText(cacheFilePath);
					if (!string.IsNullOrEmpty(text))
					{
						return XElement.Parse(text);
					}
				}
				catch (Exception)
				{
					File.Delete(cacheFilePath);
				}
				return null;
			}
			return null;
		}

		private static void SaveCacheFile(string cacheFilePath, List<AssemblyFileInfo> availableFiles, List<FormInfo> formInfos)
		{
			XElement xElement = new XElement("Root");
			if (availableFiles != null && availableFiles.Count > 0)
			{
				XElement xElement2 = new XElement("Files");
				foreach (AssemblyFileInfo availableFile in availableFiles)
				{
					xElement2.Add(availableFile.SaveToXElement());
				}
				xElement.Add(xElement2);
			}
			if (formInfos != null && formInfos.Count > 0)
			{
				XElement xElement3 = new XElement("Forms");
				foreach (FormInfo formInfo in formInfos)
				{
					xElement3.Add(formInfo.SaveToXElement());
				}
				xElement.Add(xElement3);
			}
			try
			{
				File.WriteAllText(cacheFilePath, xElement.ToString());
			}
			catch (Exception)
			{
			}
		}

		private static List<AssemblyFileInfo> ReadAssemblyFileInfos(string formsDirectory, string searchPattern, Func<string, bool> fileFilter)
		{
			List<AssemblyFileInfo> list = new List<AssemblyFileInfo>();
			string[] files = Directory.GetFiles(formsDirectory, searchPattern, SearchOption.TopDirectoryOnly);
			foreach (string text in files)
			{
				if (fileFilter == null || fileFilter(text))
				{
					AssemblyFileInfo assemblyFileInfo = AssemblyFileInfo.ReadFromFile(text);
					if (assemblyFileInfo != null)
					{
						list.Add(assemblyFileInfo);
					}
				}
			}
			return list;
		}

		private static List<AssemblyFileInfo> ReadAssemblyFileInfos(XElement rootNode, string formsDirectory)
		{
			List<AssemblyFileInfo> list = new List<AssemblyFileInfo>();
			if (rootNode != null)
			{
				XElement xElement = rootNode.Element("Files");
				if (xElement != null)
				{
					foreach (XElement item in xElement.Elements())
					{
						AssemblyFileInfo assemblyFileInfo = AssemblyFileInfo.ReadFromXElement(item, formsDirectory);
						if (assemblyFileInfo != null)
						{
							list.Add(assemblyFileInfo);
						}
					}
				}
			}
			return list;
		}
	}
	public static class GridControlClipboardHelper
	{
		public static void DoDataCopy(GridControl gc, CxvViewModel vm, GridControlCopyEventArgs e, Func<DataCellInfo, string> cxsPathProvider, Func<DataCellInfo, string> cellTextProvider = null)
		{
			if (gc == null)
			{
				throw new ArgumentNullException("gc");
			}
			if (vm == null)
			{
				throw new ArgumentNullException("vm");
			}
			if (e == null)
			{
				throw new ArgumentNullException("e");
			}
			if (cxsPathProvider == null)
			{
				throw new ArgumentNullException("cxsPathProvider");
			}
			if (gc.DataSource != null && gc.HasSelection)
			{
				StringBuilder stringBuilder = new StringBuilder();
				int columnHeaderLines = 0;
				if (e.ResolvedIncludeHeader)
				{
					GetLabelOfNonHeaderOnlyFields(stringBuilder, e.GridControl.SelectedColumns);
					columnHeaderLines = 1;
				}
				stringBuilder.Append(e.GenerateTextToCopy(null, false));
				string text = stringBuilder.ToString();
				string text2 = vm.ResolveViewPropertyPath("ResolvedCxsProvider.Case.CaseFullFilePath") as string;
				string applicationName = vm.ResolveViewPropertyPath("ResolvedCxsProvider.Case.ApplicationName") as string;
				e.ClipboardContents.Add(DataFormats.Text, text);
				e.ClipboardContents.Add("CSV", ConvertToDefaultStream(GenerateCsvFormatContent(text)));
				e.ClipboardContents.Add("DatagridMetadata", ConvertToStream(GenerateDatagridMetadataFormatContent(e, columnHeaderLines)));
				e.ClipboardContents.Add("ASI Format", ConvertToStream(GenerateAsiFormatContent(gc, e.ResolvedIncludeHeader, text2, applicationName, cxsPathProvider, cellTextProvider)));
				MemoryStream asiFileXml = ClipboardHelper.GetAsiFileXml(text2, applicationName);
				if (asiFileXml != null)
				{
					e.ClipboardContents.Add("ASI File Format", asiFileXml);
				}
				e.Handled = true;
			}
		}

		public static void DoDataDrag(GridControl gc, CxvViewModel vm, GridControlDataDraggingEventArgs e, Func<DataCellInfo, string> cxsPathProvider, Func<DataCellInfo, string> cellTextProvider = null)
		{
			if (gc == null)
			{
				throw new ArgumentNullException("gc");
			}
			if (vm == null)
			{
				throw new ArgumentNullException("vm");
			}
			if (e == null)
			{
				throw new ArgumentNullException("e");
			}
			if (cxsPathProvider == null)
			{
				throw new ArgumentNullException("cxsPathProvider");
			}
			if (gc.DataSource != null && gc.HasSelection)
			{
				string data = e.GenerateTextToCopy();
				e.DataObject.SetData(DataFormats.Text, data);
				string caseFullFileName = vm.ResolveViewPropertyPath("ResolvedCxsProvider.Case.CaseFullFilePath") as string;
				string applicationName = vm.ResolveViewPropertyPath("ResolvedCxsProvider.Case.ApplicationName") as string;
				string data2 = GenerateAsiFormatContent(gc, includesHeader: false, caseFullFileName, applicationName, cxsPathProvider, cellTextProvider);
				e.DataObject.SetData(DataFormats.GetDataFormat("ASI Format").Name, data2);
			}
		}

		public static IDataObject CloneClipboardDataObject()
		{
			DataObject dataObject = new DataObject();
			IDataObject oldDataObject = TimesExecution.TryExecute((Func<IDataObject>)Clipboard.GetDataObject);
			if (oldDataObject != null)
			{
				string[] array = TimesExecution.TryExecute((Func<string[]>)oldDataObject.GetFormats);
				if (array != null)
				{
					string[] array2 = array;
					foreach (string cf in array2)
					{
						if (TimesExecution.TryExecute(() => oldDataObject.GetDataPresent(cf)))
						{
							object obj = TimesExecution.TryExecute(() => oldDataObject.GetData(cf));
							if (obj != null)
							{
								dataObject.SetData(cf, obj);
							}
						}
					}
				}
			}
			return dataObject;
		}

		public static IDataObject CombineDataObjects(IDataObject first, IDataObject second)
		{
			if (first == null)
			{
				throw new ArgumentNullException("first");
			}
			if (second == null)
			{
				throw new ArgumentNullException("second");
			}
			DataObject dataObject = new DataObject();
			string[] formats = first.GetFormats();
			if (formats != null)
			{
				string[] array = formats;
				foreach (string format in array)
				{
					if (first.GetDataPresent(format))
					{
						dataObject.SetData(format, first.GetData(format));
					}
				}
			}
			List<string> list = ((formats == null) ? new List<string>() : formats.ToList());
			string[] formats2 = second.GetFormats();
			if (formats2 != null)
			{
				string[] array = formats2;
				foreach (string text in array)
				{
					if (!list.Contains(text) && second.GetDataPresent(text))
					{
						dataObject.SetData(text, second.GetData(text));
					}
				}
			}
			return dataObject;
		}

		private static void GetLabelOfNonHeaderOnlyFields(StringBuilder sb, IEnumerable<DataColumn> selectedFields)
		{
			if (sb == null || selectedFields == null)
