			List<DataColumn> list = selectedFields.ToList();
			for (int i = 0; i < list.Count; i++)
			{
				DataColumn dataColumn = list[i];
				string value = "\"" + dataColumn.Header + "\"";
				sb.Append(value);
				if (i < list.Count - 1)
				{
					sb.Append('\t');
				}
			}
			sb.AppendLine();
		}

