		private static List<IGridCellData> CreateCellDataPackage(GridControl gc, bool includesHeader, Func<DataCellInfo, string> cxsPathProvider, Func<DataCellInfo, string> cellTextProvider = null)
		{
			List<IGridCellData> list = new List<IGridCellData>();
			if (includesHeader)
			{
				foreach (DataColumn item3 in gc.SelectedColumns.Where((DataColumn x) => x.Visibility == Visibility.Visible))
				{
					CxsGridCellData item = new CxsGridCellData
					{
						TextValue = item3.Header,
						ColumnIndex = item3.DisplayIndex,
						RowIndex = 0
					};
					list.Add(item);
				}
			}
			List<DataRow> list2 = gc.DataSource?.Rows.Where((DataRow p) => p.Visibility == Visibility.Visible).ToList();
			int num = -1;
			foreach (DataCellInfo totalOrderedSelectedCell in gc.TotalOrderedSelectedCells)
			{
				int num2 = list2.IndexOf(totalOrderedSelectedCell.Row);
				if (num == -1)
				{
					num = num2;
				}
				if (includesHeader)
				{
					num2++;
				}
				string moniker = cxsPathProvider(totalOrderedSelectedCell);
				string textValue = null;
				if (cellTextProvider != null)
				{
					textValue = cellTextProvider(totalOrderedSelectedCell);
				}
				else if (totalOrderedSelectedCell.Data != null)
				{
					textValue = totalOrderedSelectedCell.Data.ValueAsString;
				}
				CxsGridCellData item2 = new CxsGridCellData
				{
					Moniker = moniker,
					RowIndex = num2,
					ColumnIndex = totalOrderedSelectedCell.Column.DisplayIndex,
					TextValue = textValue
				};
				list.Add(item2);
			}
			FixRowAndColumnIndexes(list, num);
			return list;
		}

		private static void FixRowAndColumnIndexes(List<IGridCellData> results, int firstRowIndex)
		{
			int num = -1;
			int num2 = 0;
			foreach (IGridCellData result in results)
			{
				if (result.RowIndex > num2)
				{
					num2 = result.RowIndex;
					num = 0;
				}
				else
				{
					num++;
				}
				if (result.RowIndex > 0)
				{
					result.RowIndex -= firstRowIndex;
				}
				result.ColumnIndex = num;
			}
		}

