	public class HelpFilesMap
	{
		private readonly Dictionary<string, string> _mapItems = new Dictionary<string, string>();

		private readonly string _rootFolder;

		public HelpFilesMap(string rootFolder)
		{
			if (!string.IsNullOrWhiteSpace(rootFolder))
			{
				if (rootFolder.Contains("file:///"))
				{
					rootFolder = rootFolder.Substring(8).Replace('/', '\\');
				}
				if (File.Exists(rootFolder))
				{
					_rootFolder = System.IO.Path.GetDirectoryName(rootFolder);
				}
				else if (Directory.Exists(rootFolder))
				{
					_rootFolder = rootFolder;
				}
			}
		}

		public async void PrepareAsync()
		{
			await Task.Run((Action)CollectMappings);
		}

		public string FindLink(int resolvedId)
		{
			return FindLink(resolvedId.ToString(CultureInfo.InvariantCulture));
		}

		public string FindLink(string resolvedId)
		{
			if (_mapItems.TryGetValue(resolvedId, out var value))
			{
				return value;
			}
			return null;
		}

		private void CollectMappings()
		{
			List<XElement> list = ReadAliasXmls().ToList();
			lock (_mapItems)
			{
				_mapItems.Clear();
				foreach (XElement item in list)
				{
					string text = (string)item.Attribute("RelativePath");
					foreach (XElement item2 in item.Elements("Map"))
					{
						string text2 = (string)item2.Attribute("Link");
						string text3 = (string)item2.Attribute("ResolvedId");
						if (!string.IsNullOrWhiteSpace(text2) && !string.IsNullOrWhiteSpace(text3) && !_mapItems.ContainsKey(text3))
						{
							string value = ((text.Length == 1) ? ("HtmlHelp" + text + "Content/" + text2) : ("HtmlHelp" + text + "/Content/" + text2));
							_mapItems[text3] = value;
						}
					}
				}
			}
		}

		private IEnumerable<XElement> ReadAliasXmls()
		{
			if (string.IsNullOrWhiteSpace(_rootFolder) || !Directory.Exists(_rootFolder))
			{
				yield break;
			}
			string[] files = Directory.GetFiles(_rootFolder, "Alias.xml", SearchOption.AllDirectories);
			foreach (string text in files)
			{
				XElement xElement = TryParseToXml(File.ReadAllText(text));
				if (xElement != null)
				{
					xElement.SetAttributeValue("RelativePath", GetRelativePath(text));
					yield return xElement;
				}
			}
			string GetRelativePath(string aliasFilePath)
			{
				string directoryName = System.IO.Path.GetDirectoryName(aliasFilePath);
				if (directoryName.EndsWith("\\Data", StringComparison.CurrentCultureIgnoreCase))
				{
					directoryName = System.IO.Path.GetDirectoryName(directoryName);
				}
				string text2 = directoryName.Replace(_rootFolder, string.Empty).Replace('\\', '/');
				if (text2.FirstOrDefault() != '/')
				{
					text2 = "/" + text2;
				}
				return text2;
			}
			static XElement TryParseToXml(string textToConvert)
			{
				if (!string.IsNullOrWhiteSpace(textToConvert))
				{
					try
					{
						return XElement.Parse(textToConvert);
					}
					catch
					{
						return null;
					}
				}
				return null;
			}
		}

		public static string ReadLocalMachineRegistryKey(string path, string key)
		{
			using (RegistryKey registryKey = Registry.LocalMachine.OpenSubKey(path))
			{
				if (registryKey != null)
				{
					return registryKey.GetValue(key) as string;
				}
			}
			return null;
		}
	}
