	public static class MMInContextGuidance
	{
		private static class InContextGuidanceInjector
		{
			public static void CheckToInjectInContextGuidance(DependencyObject d)
			{
				if (d is FrameworkElement frameworkElement && IsCorrectTargetToInject(frameworkElement) && !MMInContextGuidanceButton.GetSuppressAutoInjection(frameworkElement) && !MMInContextGuidanceButton.GetUsedInTemplate(frameworkElement).HasValue)
				{
					if (!frameworkElement.IsLoaded)
					{
						frameworkElement.Loaded += Element_Loaded;
					}
					else
					{
						TryInjectInContextGuidance(frameworkElement);
					}
				}
			}

			private static void Element_Loaded(object sender, RoutedEventArgs e)
			{
				FrameworkElement obj = sender as FrameworkElement;
				TryInjectInContextGuidance(obj);
				obj.Loaded -= Element_Loaded;
			}

			private static bool IsCorrectTargetToInject(FrameworkElement element)
			{
				if (element is Window window && !(window is CommonShellWindow))
				{
					return true;
				}
				if (element is ScreenContentControl)
				{
					return true;
				}
				if (MMInContextGuidanceButton.IsAllowedContentControl(element.GetType()))
				{
					return true;
				}
				return false;
			}

			private static void TryInjectInContextGuidance(FrameworkElement fe)
			{
				if (Infragistics.Windows.Utilities.GetDescendantFromType<MMInContextGuidanceButton>(fe, allowSubclassOfType: true, null) == null && !MMInContextGuidanceButton.GetSuppressAutoInjection(fe) && !MMInContextGuidanceButton.GetUsedInTemplate(fe).HasValue)
				{
					GetHelpFile(fe);
					int? helpId = GetHelpId(fe);
					if (helpId.HasValue && helpId.Value != 0 && helpId.Value != 1)
					{
						MMInContextGuidanceButton.SetUsedInTemplate(fe, true);
					}
				}
			}
		}

		public static readonly DependencyProperty HelpIdProperty = DependencyProperty.RegisterAttached("HelpId", typeof(int?), typeof(MMInContextGuidance), new FrameworkPropertyMetadata(null, FrameworkPropertyMetadataOptions.Inherits, OnHelpIdPropertyChanged));

		public static readonly DependencyProperty HelpFileProperty = DependencyProperty.RegisterAttached("HelpFile", typeof(string), typeof(MMInContextGuidance), new FrameworkPropertyMetadata(null, FrameworkPropertyMetadataOptions.Inherits, OnHelpFilePropertyChanged));

		public static readonly DependencyProperty HelpContextProperty = DependencyProperty.RegisterAttached("HelpContext", typeof(object), typeof(MMInContextGuidance), new FrameworkPropertyMetadata(null, FrameworkPropertyMetadataOptions.Inherits));

		public static int? GetHelpId(DependencyObject obj)
		{
			return (int?)obj.GetValue(HelpIdProperty);
		}

		public static void SetHelpId(DependencyObject obj, int? value)
		{
			obj.SetValue(HelpIdProperty, value);
		}

		public static string GetHelpFile(DependencyObject obj)
		{
			return (string)obj.GetValue(HelpFileProperty);
		}

		public static void SetHelpFile(DependencyObject obj, string value)
		{
			obj.SetValue(HelpFileProperty, value);
		}

		public static object GetHelpContext(DependencyObject obj)
		{
			return obj.GetValue(HelpContextProperty);
		}

		public static void SetHelpContext(DependencyObject obj, object value)
		{
			obj.SetValue(HelpContextProperty, value);
		}

		public static bool IsAssignedByInheritance(DependencyObject d, DependencyProperty dp)
		{
			return DependencyPropertyHelper.GetValueSource(d, dp).BaseValueSource == BaseValueSource.Inherited;
		}

		private static void OnHelpIdPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			BaseValueSource baseValueSource = DependencyPropertyHelper.GetValueSource(d, e.Property).BaseValueSource;
			if (baseValueSource != BaseValueSource.Default && baseValueSource != BaseValueSource.Inherited)
			{
				InContextGuidanceInjector.CheckToInjectInContextGuidance(d);
			}
		}

		private static void OnHelpFilePropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			BaseValueSource baseValueSource = DependencyPropertyHelper.GetValueSource(d, e.Property).BaseValueSource;
			if (baseValueSource != BaseValueSource.Default && baseValueSource != BaseValueSource.Inherited)
			{
				InContextGuidanceInjector.CheckToInjectInContextGuidance(d);
			}
		}
