		public void UpdateEventHandler(object oldContent, object newContent)
		{
			if (oldContent is IShellContextualRibbonEnabled shellContextualRibbonEnabled)
			{
				shellContextualRibbonEnabled.ContextualRibbonTabsChanged -= Content_ContextualRibbonTabsChanged;
			}
			if (newContent is IShellContextualRibbonEnabled shellContextualRibbonEnabled2)
			{
				shellContextualRibbonEnabled2.ContextualRibbonTabsChanged += Content_ContextualRibbonTabsChanged;
			}
			_host.RaiseContextualRibbonTabsChanged();
		}

		public ObservableCollection<RibbonTabItem> GetContextualRibbonTabs(ref ObservableCollection<RibbonTabItem> defaultContextualRibbonTabs)
		{
			if (_host is ContentControl && ((ContentControl)_host).Content is IShellContextualRibbonEnabled shellContextualRibbonEnabled)
			{
				return shellContextualRibbonEnabled.ContextualRibbonTabs;
			}
			if (defaultContextualRibbonTabs == null)
			{
				defaultContextualRibbonTabs = new ObservableCollection<RibbonTabItem>();
			}
			if (!_hasRegisteredDefault)
			{
				defaultContextualRibbonTabs.CollectionChanged += ContextualRibbonTabs_CollectionChanged;
				_hasRegisteredDefault = true;
			}
			return defaultContextualRibbonTabs;
		}

		public string GetContextualRibbonHeader(string defaultHeader)
		{
			if (!string.IsNullOrWhiteSpace(defaultHeader))
			{
				return defaultHeader;
			}
			if (_host is ContentControl && ((ContentControl)_host).Content is IShellContextualRibbonEnabled shellContextualRibbonEnabled)
			{
				return shellContextualRibbonEnabled.ContextualRibbonHeader;
			}
			return null;
		}

		public void DetachContextualRibbonTabsChanged(object content)
		{
			if (content is IShellContextualRibbonEnabled shellContextualRibbonEnabled)
			{
				shellContextualRibbonEnabled.DetachContextualRibbonTabsChanged();
				shellContextualRibbonEnabled.ContextualRibbonTabsChanged -= Content_ContextualRibbonTabsChanged;
			}
			if (_host.ContextualRibbonTabs != null)
			{
				_host.ContextualRibbonTabs.CollectionChanged -= ContextualRibbonTabs_CollectionChanged;
			}
		}

		private void Content_ContextualRibbonTabsChanged(object sender, EventArgs e)
		{
			_host.RaiseContextualRibbonTabsChanged();
		}

		private void ContextualRibbonTabs_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			_host.RaiseContextualRibbonTabsChanged();
		}
	}
