		public static IEnumerable<FrameworkElement> GenerateGenericPrintPages(this MMTabPage tabPage, MMScrollAreaMS scrollArea, System.Windows.Size availablePrintSize, int frozenRows = 0, int frozenColumns = 0, string title = null, bool ignoreLastColumn = false, bool ignoreLastRow = false)
		{
			if (tabPage == null)
			{
				throw new ArgumentNullException("tabPage");
			}
			if (scrollArea == null)
			{
				throw new ArgumentNullException("scrollArea");
			}
			CxvViewModel viewModel = tabPage.ViewModel;
			string caseName = GetCaseName(viewModel);
			string additionalFooter = "Run: " + caseName;
			Func<DataColumn, string> columnHeaderTextFunc = delegate(DataColumn f)
			{
				if (f.HeaderContentTemplate != null && !string.IsNullOrEmpty(f.Header))
				{
					object obj = viewModel.ResolveViewPropertyPath(f.Header);
					if (obj != null)
					{
						return obj.ToString();
					}
				}
				return (!string.IsNullOrEmpty(f.Header)) ? f.Header : string.Empty;
			};
			return scrollArea.DataGrid.GenerateGenericPrintPages(availablePrintSize, frozenRows, frozenColumns, title, additionalFooter, ignoreLastColumn, ignoreLastRow, columnHeaderTextFunc);
		}

		public static IEnumerable<FrameworkElement> GenerateGenericPrintPages(this MMTabPage tabPage, MMScrollArea scrollArea, System.Windows.Size availablePrintSize, int frozenRows = 0, int frozenColumns = 0, string title = null, bool ignoreLastColumn = false)
		{
			if (tabPage == null)
			{
				throw new ArgumentNullException("tabPage");
			}
			if (scrollArea == null)
			{
				throw new ArgumentNullException("scrollArea");
			}
			CxvViewModel viewModel = tabPage.ViewModel;
			string caseName = GetCaseName(viewModel);
			string additionalFooter = "Run: " + caseName;
			Func<Field, string> fieldLabelFunc = delegate(Field f)
			{
				if (f.Label is LabelHeader labelHeader && !string.IsNullOrEmpty(labelHeader.LabelText))
				{
					return labelHeader.LabelText;
				}
				if (f.Tag is MMScrollAreaField mMScrollAreaField && !string.IsNullOrEmpty(mMScrollAreaField.HeaderUnitsProperty))
				{
					object obj = viewModel.ResolveViewPropertyPath(mMScrollAreaField.HeaderUnitsProperty + ".Value");
					if (obj != null)
					{
						return obj.ToString();
					}
				}
				return string.Empty;
			};
			return GenerateGenericPrintPages(scrollArea.DataGrid, availablePrintSize, frozenRows, frozenColumns, title, additionalFooter, ignoreLastColumn, fieldLabelFunc);
		}

		public static IEnumerable<FrameworkElement> GenerateGenericPrintPages(XamDataGrid dg, System.Windows.Size availablePrintSize, int frozenRows = 0, int frozenColumns = 0, string title = null, string additionalFooter = null, bool ignoreLastColumn = false, Func<Field, string> fieldLabelFunc = null)
		{
			if (dg == null)
			{
				throw new ArgumentNullException("dg");
			}
			if (dg.DefaultFieldLayout == null)
			{
				return null;
			}
			List<Field> list = dg.DefaultFieldLayout.Fields.OrderBy((Field f) => f.ActualPosition.Column).ToList();
			if (ignoreLastColumn)
			{
				list = list.Take(list.Count - 1).ToList();
			}
			List<DataRecord> rows = dg.Records.OfType<DataRecord>().ToList();
			double num = 25.0;
			double headerHeight = num + 5.0;
			System.Windows.Size size = new System.Windows.Size(availablePrintSize.Width, availablePrintSize.Height - 90.0);
			List<List<Field>> list2 = GenerateFieldGroups(list, size.Width, frozenColumns);
			List<List<DataRecord>> list3 = GenerateRowGroups(rows, size.Height, num, headerHeight, frozenRows);
			int pageCount = list2.Count * list3.Count;
			DateTime now = DateTime.Now;
			List<FrameworkElement> list4 = new List<FrameworkElement>();
			for (int num2 = 0; num2 < list3.Count; num2++)
			{
				List<DataRecord> rows2 = list3[num2];
				for (int num3 = 0; num3 < list2.Count; num3++)
				{
					int pageIndex = num2 * list2.Count + num3 + 1;
					FrameworkElement frameworkElement = CreateStreamResultsPage(dg, rows2, list2[num3], headerHeight, num, title, additionalFooter, pageIndex, pageCount, now, fieldLabelFunc);
					frameworkElement.Width = availablePrintSize.Width;
					frameworkElement.Height = availablePrintSize.Height;
					list4.Add(frameworkElement);
				}
			}
			return list4;
		}

		private static FrameworkElement CreateStreamResultsPage(XamDataGrid dg, List<DataRecord> rows, List<Field> fields, double headerHeight, double rowHeight, string title, string additionalFooter, int pageIndex, int pageCount, DateTime printTime, Func<Field, string> fieldLabelFunc = null)
		{
			Border element = new Border
			{
				Child = new TextBlock
				{
					HorizontalAlignment = HorizontalAlignment.Center,
					VerticalAlignment = VerticalAlignment.Center,
					FontWeight = FontWeights.Bold,
					Text = title
				},
				Height = 40.0,
				BorderBrush = System.Windows.Media.Brushes.Gray,
				BorderThickness = new Thickness(0.0, 0.0, 0.0, 1.0)
			};
			Border element2 = new Border
			{
				Child = CreateStreamResultsPageBody(dg, rows, fields, headerHeight, rowHeight, fieldLabelFunc),
				Padding = new Thickness(0.0, 10.0, 0.0, 10.0)
			};
			Grid.SetRow(element2, 1);
			TextBlock textBlock = new TextBlock
			{
				HorizontalAlignment = HorizontalAlignment.Center,
				VerticalAlignment = VerticalAlignment.Center,
				MinWidth = 80.0,
				Text = $"Page {pageIndex}/{pageCount}"
			};
			TextBlock element3 = new TextBlock
			{
				HorizontalAlignment = HorizontalAlignment.Right,
				VerticalAlignment = VerticalAlignment.Center,
				TextWrapping = TextWrapping.Wrap,
				Text = printTime.ToString("yyyy-MM-dd hh:mm:ss")
			};
			Grid grid = new Grid();
			if (!string.IsNullOrEmpty(additionalFooter))
			{
				grid.ColumnDefinitions.Add(new ColumnDefinition
				{
					Width = new GridLength(50.0, GridUnitType.Star)
				});
				grid.ColumnDefinitions.Add(new ColumnDefinition
				{
					Width = new GridLength(10.0, GridUnitType.Auto)
				});
				grid.ColumnDefinitions.Add(new ColumnDefinition
				{
					Width = new GridLength(50.0, GridUnitType.Star)
				});
				TextBlock element4 = new TextBlock
				{
					HorizontalAlignment = HorizontalAlignment.Left,
					VerticalAlignment = VerticalAlignment.Center,
					TextWrapping = TextWrapping.Wrap,
					Text = additionalFooter
				};
				grid.Children.Add(element4);
				Grid.SetColumn(textBlock, 1);
				grid.Children.Add(textBlock);
				Grid.SetColumn(element3, 2);
				grid.Children.Add(element3);
			}
			else
			{
				grid.ColumnDefinitions.Add(new ColumnDefinition
				{
					Width = new GridLength(50.0, GridUnitType.Star)
				});
				grid.ColumnDefinitions.Add(new ColumnDefinition
				{
					Width = new GridLength(50.0, GridUnitType.Star)
				});
				textBlock.HorizontalAlignment = HorizontalAlignment.Left;
				Grid.SetColumn(textBlock, 0);
				grid.Children.Add(textBlock);
				Grid.SetColumn(element3, 1);
				grid.Children.Add(element3);
			}
			Border element5 = new Border
			{
				Child = grid,
				Height = 30.0,
				BorderBrush = System.Windows.Media.Brushes.Gray,
				BorderThickness = new Thickness(0.0, 1.0, 0.0, 0.0)
			};
			Grid.SetRow(element5, 2);
			return new Grid
			{
				RowDefinitions = 
				{
					new RowDefinition
					{
						Height = new GridLength(0.0, GridUnitType.Auto)
					},
					new RowDefinition
					{
						Height = new GridLength(100.0, GridUnitType.Star)
					},
					new RowDefinition
					{
						Height = new GridLength(0.0, GridUnitType.Auto)
					}
				},
				Children = 
				{
					(UIElement)element,
					(UIElement)element2,
					(UIElement)element5
				}
			};
		}

		private static FrameworkElement CreateStreamResultsPageBody(XamDataGrid dg, List<DataRecord> rows, List<Field> fields, double headerHeight, double rowHeight, Func<Field, string> fieldLabelFunc)
		{
			Grid grid = new Grid
			{
				VerticalAlignment = VerticalAlignment.Top,
				HorizontalAlignment = HorizontalAlignment.Left
			};
			foreach (Field field in fields)
			{
				grid.ColumnDefinitions.Add(new ColumnDefinition
				{
					Width = new GridLength(GetFieldWidth(field))
				});
			}
			for (int i = 0; i < rows.Count + 1; i++)
			{
				grid.RowDefinitions.Add(new RowDefinition());
			}
			foreach (Field field2 in fields)
			{
				grid.Children.Add(CreateStreamResultsCellElement(GetFieldLabelText(field2, fieldLabelFunc), headerHeight, HorizontalAlignment.Left, 0, fields.IndexOf(field2)));
			}
			for (int j = 0; j < rows.Count; j++)
			{
				DataRecord dataRecord = rows[j];
				for (int k = 0; k < fields.Count; k++)
				{
					string cellText = dataRecord.GetCellText(fields[k]);
					grid.Children.Add(CreateStreamResultsCellElement(cellText, rowHeight, HorizontalAlignment.Left, j + 1, k));
				}
			}
			return grid;
		}

		private static UIElement CreateStreamResultsCellElement(string text, double height, HorizontalAlignment horizontalAlignment, int rowIndex, int columnIndex)
		{
			TextBlock obj = new TextBlock
			{
				Text = text,
				Height = height,
				HorizontalAlignment = horizontalAlignment
			};
			Grid.SetRow(obj, rowIndex);
			Grid.SetColumn(obj, columnIndex);
			return obj;
		}

		private static string GetFieldLabelText(Field field, Func<Field, string> fieldLabelFunc)
		{
			if (fieldLabelFunc != null)
			{
				return fieldLabelFunc(field);
			}
			if (field.Label != null)
			{
				return field.Label.ToString();
			}
			return string.Empty;
		}

		private static string GetCaseName(CxvViewModel viewModel)
		{
			if (viewModel != null && viewModel.ResolvedCxsProvider != null && viewModel.ResolvedCxsProvider.Case != null)
			{
				return viewModel.ResolvedCxsProvider.Case.CaseFileName;
			}
			return string.Empty;
		}

		private static double GetFieldWidth(Field field)
		{
			if (field.Width.HasValue && field.Width.Value.IsAbsolute)
			{
				return field.Width.Value.Value;
			}
			return field.LabelWidthResolved;
		}

		private static List<Field> GetFrozenFields(IList<Field> fields, double unitWidth, int frozenColumns, out double frozenWidth)
		{
			frozenWidth = 0.0;
			List<Field> list = new List<Field>();
			for (int i = 0; i < frozenColumns && i < fields.Count - 1; i++)
			{
				Field field = fields[i];
				double fieldWidth = GetFieldWidth(field);
				double fieldWidth2 = GetFieldWidth(fields[i + 1]);
				if (frozenWidth + fieldWidth + fieldWidth2 > unitWidth)
				{
					break;
				}
				frozenWidth += fieldWidth;
				list.Add(field);
			}
			return list;
		}

		private static List<DataRecord> GetFrozenRecords(IList<DataRecord> rows, double unitHeight, double rowHeight, double headerHeight, int frozenRows, out double frozenHeight)
		{
			frozenHeight = headerHeight;
			List<DataRecord> list = new List<DataRecord>();
			for (int i = 0; i < frozenRows && i < rows.Count - 1; i++)
			{
				if (frozenHeight + rowHeight * 2.0 > unitHeight)
				{
					break;
				}
				frozenHeight += rowHeight;
				list.Add(rows[i]);
			}
			return list;
		}

		private static List<List<Field>> GenerateFieldGroups(IList<Field> fields, double unitWidth, int frozenColumns)
		{
			double frozenWidth = 0.0;
			List<Field> frozenFields = GetFrozenFields(fields, unitWidth, frozenColumns, out frozenWidth);
			double num = frozenWidth;
			List<List<Field>> list = new List<List<Field>>();
			List<Field> list2 = null;
			for (int i = frozenFields.Count; i < fields.Count; i++)
			{
				Field field = fields[i];
				if (list2 == null)
				{
					list2 = new List<Field>(frozenFields);
				}
				list2.Add(field);
				num += GetFieldWidth(field);
				bool flag = i == fields.Count - 1;
				if (!flag)
				{
					Field field2 = fields[i + 1];
					if (num + GetFieldWidth(field2) > unitWidth)
					{
						flag = true;
					}
				}
				if (flag)
				{
					list.Add(list2);
					list2 = null;
					num = frozenWidth;
				}
			}
			return list;
		}

		private static List<List<DataRecord>> GenerateRowGroups(IList<DataRecord> rows, double unitHeight, double rowHeight, double headerHeight, int frozenRows)
		{
			double frozenHeight = 0.0;
			List<DataRecord> frozenRecords = GetFrozenRecords(rows, unitHeight, rowHeight, headerHeight, frozenRows, out frozenHeight);
			List<List<DataRecord>> list = new List<List<DataRecord>>();
			double num = frozenHeight;
			List<DataRecord> list2 = null;
			for (int i = frozenRecords.Count; i < rows.Count; i++)
			{
				DataRecord item = rows[i];
				if (list2 == null)
				{
					list2 = new List<DataRecord>(frozenRecords);
				}
				list2.Add(item);
				num += rowHeight;
				bool flag = i == rows.Count - 1;
				if (!flag && num + rowHeight > unitHeight)
				{
					flag = true;
				}
				if (flag)
				{
					list.Add(list2);
					list2 = null;
					num = frozenHeight;
				}
			}
			return list;
		}
	}
