		private static void FixScrollProblemPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			XamTabControl sender = d as XamTabControl;
			if (d == null || !(bool)e.NewValue || !(sender.TemplatedParent is MMTabStrip mMTabStrip) || !(mMTabStrip.Parent is MMTabTemplate))
			{
				return;
			}
			CleanFixSize(mMTabStrip.Parent as MMTabTemplate);
			if (sender.SelectedContent is MMTabPage)
			{
				CleanFixSize(sender.SelectedContent as MMTabPage);
			}
			sender.SizeChanged += delegate
			{
				if (sender.SelectedContent is MMTabPage)
				{
					CleanFixSize(sender.SelectedContent as MMTabPage);
				}
			};
		}

		private static void CleanFixSize(FrameworkElement target)
		{
			if (target != null && (!double.IsNaN(target.Width) || !double.IsNaN(target.Height) || target.MinWidth != 0.0 || target.MinHeight != 0.0))
			{
				target.Width = double.NaN;
				target.Height = double.NaN;
				target.MinWidth = 0.0;
				target.MinHeight = 0.0;
				target.InvalidateVisual();
			}
		}

