		private static void FixMMScrollAreaBaseScrollPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			if (d is MMScrollAreaBase mMScrollAreaBase && (bool)e.NewValue && mMScrollAreaBase.Parent is Grid)
			{
				Grid grid = mMScrollAreaBase.Parent as Grid;
				if (grid.RowDefinitions.Count != 0)
				{
					grid.RowDefinitions[Grid.GetRow(mMScrollAreaBase)].Height = new GridLength(1.0, GridUnitType.Star);
				}
				if (grid.ColumnDefinitions.Count != 0)
				{
					grid.ColumnDefinitions[Grid.GetColumn(mMScrollAreaBase)].Width = new GridLength(1.0, GridUnitType.Star);
				}
				Binding binding = new Binding("ActualHeight");
				binding.Source = grid;
				mMScrollAreaBase.SetBinding(FrameworkElement.HeightProperty, binding);
				Binding binding2 = new Binding("ActualWidth");
				binding2.Source = grid;
				mMScrollAreaBase.SetBinding(FrameworkElement.WidthProperty, binding2);
			}
		}

