		public static bool IsRegistryOpen(IUnityContainer container, string registryKey)
		{
			if (container == null)
			{
				throw new ArgumentNullException("container");
			}
			IAppConfig appConfig = UnityContainerHelper.TryResolve<IAppConfig>(container);
			if (appConfig != null)
			{
				try
				{
					return appConfig.IsRegistryOpen(registryKey);
				}
				catch (Exception)
				{
					return false;
				}
			}
			return false;
		}
	}
	public class AttachedCommand : DependencyObject
	{
		public static readonly DependencyProperty CommandProperty = DependencyProperty.RegisterAttached("Command", typeof(ICommand), typeof(AttachedCommand), new PropertyMetadata(null, Connect));

		public static readonly DependencyProperty TargetTypeProperty = DependencyProperty.RegisterAttached("TargetType", typeof(Type), typeof(AttachedCommand), new PropertyMetadata(null, Connect));

		public static readonly DependencyProperty GestureProperty = DependencyProperty.RegisterAttached("Gesture", typeof(InputGesture), typeof(AttachedCommand), new PropertyMetadata(null, Connect));

		public static readonly DependencyProperty RelativeEventProperty = DependencyProperty.RegisterAttached("RelativeEvent", typeof(string), typeof(AttachedCommand), new PropertyMetadata(null, Connect));

		public static ICommand GetCommand(DependencyObject obj)
		{
			return (ICommand)obj.GetValue(CommandProperty);
		}

		public static void SetCommand(DependencyObject obj, ICommand value)
		{
			obj.SetValue(CommandProperty, value);
		}

		public static Type GetTargetType(DependencyObject obj)
		{
			return (Type)obj.GetValue(TargetTypeProperty);
		}

		public static void SetTargetType(DependencyObject obj, Type value)
		{
			obj.SetValue(TargetTypeProperty, value);
		}

		public static InputGesture GetGesture(DependencyObject obj)
		{
			return (InputGesture)obj.GetValue(GestureProperty);
		}

		public static void SetGesture(DependencyObject obj, InputGesture value)
		{
			obj.SetValue(GestureProperty, value);
		}

		public static string GetRelativeEvent(DependencyObject obj)
		{
			return (string)obj.GetValue(RelativeEventProperty);
		}

		public static void SetRelativeEvent(DependencyObject obj, RoutedEvent value)
		{
			obj.SetValue(RelativeEventProperty, value);
		}

		private static void Connect(DependencyObject sender, DependencyPropertyChangedEventArgs e)
		{
			if (!(sender is FrameworkElement frameworkElement))
			{
				return;
			}
			ICommand command = GetCommand(frameworkElement);
			InputGesture gesture = GetGesture(frameworkElement);
			Type targetType = GetTargetType(frameworkElement);
			string relativeEvent = GetRelativeEvent(frameworkElement);
			if (command == null)
			{
				return;
			}
			FrameworkElement frameworkElement2 = ((!(targetType != null) || !typeof(FrameworkElement).IsAssignableFrom(targetType)) ? frameworkElement : ((FrameworkElement)Infragistics.Windows.Utilities.GetDescendantFromType(frameworkElement, targetType, allowSubclassOfType: true)));
			if (frameworkElement2 == null)
			{
				return;
			}
			if (gesture != null)
			{
				InputBinding inputBinding = new InputBinding(command, gesture);
				frameworkElement2.InputBindings.Add(inputBinding);
			}
			if (relativeEvent != null)
			{
				EventInfo eventInfo = frameworkElement2.GetType().GetEvent(relativeEvent);
				MethodInfo method = command.GetType().GetMethod("Execute");
				if (eventInfo != null)
				{
					Delegate handler = Delegate.CreateDelegate(eventInfo.EventHandlerType, method);
					eventInfo.RemoveEventHandler(frameworkElement2, handler);
					eventInfo.AddEventHandler(frameworkElement2, handler);
				}
			}
		}
	}
