	public class MMFortran : AesTextBoxWithStatusBar
	{
		private TextBox richTextBox;

		private static readonly RoutedUICommand _variableListCommand;

		public static RoutedUICommand VariableListCommand => _variableListCommand;

		public MMFortran()
		{
			System.Windows.Media.FontFamily fontFamily = Fonts.SystemFontFamilies.FirstOrDefault((System.Windows.Media.FontFamily p) => p.Source == "Courier New");
			if (fontFamily != null)
			{
				base.FontFamily = fontFamily;
			}
		}

		static MMFortran()
		{
			_variableListCommand = new RoutedUICommand(AspenTech.AspenPlus.MMControls.Properties.Resources.VariableList, "Variable List", typeof(MMFortran));
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(MMFortran), new FrameworkPropertyMetadata(typeof(MMFortran)));
			AesTextEdit.AcceptsReturnProperty.OverrideMetadata(typeof(MMFortran), new FrameworkPropertyMetadata(true));
			AesTextBoxWithStatusBar.HideStatusBarProperty.OverrideMetadata(typeof(MMFortran), new FrameworkPropertyMetadata(false));
			AesTextEdit.VerticalScrollBarVisibilityProperty.OverrideMetadata(typeof(MMFortran), new FrameworkPropertyMetadata(ScrollBarVisibility.Visible));
			AesTextEdit.HorizontalScrollBarVisibilityProperty.OverrideMetadata(typeof(MMFortran), new FrameworkPropertyMetadata(ScrollBarVisibility.Auto));
			CommandManager.RegisterClassCommandBinding(typeof(MMFortran), new CommandBinding(VariableListCommand, VariableList_Executed, VariableList_CanExecute));
		}

		protected override void BuildDefaultContextMenu(ContextMenu menu)
		{
			base.BuildDefaultContextMenu(menu);
			AddVarListMenuItem(menu, richTextBox);
			CorrectCommandTarget(menu, richTextBox);
		}

		internal static void AddVarListMenuItem(ContextMenu menu, FrameworkElement fortranControl)
		{
			if (menu != null)
			{
				menu.Items.Add(new Separator());
				menu.Items.Add(new MenuItem
				{
					Command = VariableListCommand,
					CommandTarget = fortranControl
				});
			}
		}

		public override void OnApplyTemplate()
		{
			base.OnApplyTemplate();
			richTextBox = GetTemplateChild("PART_TextBoxControl") as TextBox;
			if (richTextBox == null)
			{
				return;
			}
			richTextBox.PreviewKeyDown += delegate(object o, KeyEventArgs e)
			{
				if (e.Key == Key.Tab)
				{
					string text = richTextBox.Text.Clone().ToString();
					int caretIndex = richTextBox.CaretIndex;
					richTextBox.Text = text.Insert(richTextBox.CaretIndex, "    ");
					richTextBox.Select(caretIndex + 4, 0);
					e.Handled = true;
				}
				if (e.Key == Key.Return)
				{
					int caretIndex2 = richTextBox.CaretIndex;
					string text2 = "\r\n      ";
					double verticalOffset = richTextBox.VerticalOffset;
					richTextBox.Text = richTextBox.Text.Insert(caretIndex2, text2);
					richTextBox.ScrollToVerticalOffset(verticalOffset);
					richTextBox.CaretIndex = caretIndex2 + text2.Length;
					e.Handled = true;
				}
			};
			richTextBox.PreviewDragEnter += richTextBox_PreviewDragEnter;
			richTextBox.PreviewDragOver += richTextBox_PreviewDragEnter;
			richTextBox.PreviewDrop += richTextBox_PreviewDrop;
		}

		protected override void OnPreviewGotKeyboardFocus(KeyboardFocusChangedEventArgs e)
		{
			if (richTextBox != null && string.IsNullOrEmpty(richTextBox.Text))
			{
				richTextBox.Text = "      ";
			}
			base.OnPreviewGotKeyboardFocus(e);
		}

		protected override void OnPreviewLostKeyboardFocus(KeyboardFocusChangedEventArgs e)
		{
			System.Windows.Point position = Mouse.GetPosition(this);
			if ((!(e.NewFocus is ContextMenu) || !(position.X <= base.ActualWidth) || !(position.Y <= base.ActualHeight) || !(position.X >= 0.0) || !(position.Y >= 0.0)) && !(e.NewFocus is MenuItem) && richTextBox.Text == "      ")
			{
				richTextBox.Text = string.Empty;
			}
			base.OnPreviewLostKeyboardFocus(e);
		}

		private void richTextBox_PreviewDrop(object sender, DragEventArgs e)
		{
			if (e.Data.GetData(typeof(DataRecord)) is DataRecord dataRecord)
			{
				e.Data.SetData(DataFormats.Text, dataRecord.Cells[0].Value.ToString());
			}
		}

		private void richTextBox_PreviewDragEnter(object sender, DragEventArgs e)
		{
			e.Effects = DragDropEffects.All;
			e.Handled = true;
		}

		private void richTextBox_ContextMenuOpening(object sender, ContextMenuEventArgs e)
		{
			AddVarListToRTB(this, e);
		}

		internal static void AddVarListToRTB(FrameworkElement fortranControl, ContextMenuEventArgs e)
		{
			if (!(e.Source is FrameworkElement { ContextMenu: { } contextMenu }))
			{
				return;
			}
			foreach (object item in (IEnumerable)contextMenu.Items)
			{
				if (item is MenuItem menuItem && menuItem.Command == VariableListCommand)
				{
					contextMenu.IsOpen = true;
					e.Handled = true;
					return;
				}
			}
			contextMenu.Items.Add(new Separator());
			contextMenu.Items.Add(new MenuItem
			{
				Command = VariableListCommand,
				CommandTarget = fortranControl
			});
			contextMenu.IsOpen = true;
			e.Handled = true;
		}

		protected virtual void OnVariableList(ExecutedRoutedEventArgs e)
		{
			IUnityContainer unityContainer = (IUnityContainer)GetValue(MMViewModelContainer.UnityContainerProperty);
			if (unityContainer == null)
			{
				return;
			}
			string shortName = AspenTech.AspenPlus.MMControls.Properties.Resources.DefinedVariableList;
			CxvParameter cxvParameter = unityContainer.Resolve<CxvSharedParameters>(Array.Empty<ResolverOverride>()).Parameters.Find("main");
			if (cxvParameter != null && !string.IsNullOrEmpty(cxvParameter.Value as string))
			{
				string[] array = (cxvParameter.Value as string).Split('.');
				if (array.Count() > 1)
				{
					shortName = string.Format(AspenTech.AspenPlus.MMControls.Properties.Resources.DefinedVariableListFor, array[array.Count() - 2], array[array.Count() - 1]);
				}
			}
			unityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<DisplayFormEvent>().Publish(new DisplayFormEventArgs
			{
				FormProgId = "MMCalcul.MMCalcul_VarList",
				ShortName = shortName,
				IsRunInModalMode = false,
				ResizeMode = ResizeMode.CanResize
			});
		}

		protected virtual void OnCanVariableList(CanExecuteRoutedEventArgs e)
		{
			e.CanExecute = false;
			if (!base.IsLoaded || !(base.Variable is CxvVariableData { ValueOptions: not null } cxvVariableData))
			{
				return;
			}
			IEnumerator enumerator = cxvVariableData.ValueOptions.GetEnumerator();
			enumerator.Reset();
			try
			{
				if (enumerator.MoveNext())
				{
					e.CanExecute = true;
				}
			}
			catch (InvalidOperationException)
			{
			}
		}

		private static void VariableList_Executed(object sender, ExecutedRoutedEventArgs e)
		{
			(sender as MMFortran).OnVariableList(e);
			e.Handled = true;
		}

		private static void VariableList_CanExecute(object sender, CanExecuteRoutedEventArgs e)
		{
			(sender as MMFortran).OnCanVariableList(e);
			e.Handled = true;
		}
	}
