		public override void OnApplyTemplate()
		{
			base.OnApplyTemplate();
			richTextBox = GetTemplateChild("PART_TextBoxControl") as TextBox;
			if (richTextBox == null)
			{
				return;
			}
			richTextBox.PreviewDragEnter += richTextBox_PreviewDragEnter;
			richTextBox.PreviewDragOver += richTextBox_PreviewDragEnter;
			richTextBox.PreviewDrop += richTextBox_PreviewDrop;
			richTextBox.KeyDown += richTextBox_KeyDown;
			richTextBox.PreviewKeyDown += richTextBox_PreviewKeyDown;
			BindingExpression bindingExpression = richTextBox.GetBindingExpression(TextBox.TextProperty);
			if (bindingExpression != null && bindingExpression.ParentBinding != null)
			{
				Binding binding = new Binding
				{
					Path = bindingExpression.ParentBinding.Path,
					Mode = BindingMode.TwoWay,
					UpdateSourceTrigger = UpdateSourceTrigger.LostFocus,
					BindingGroupName = bindingExpression.ParentBinding.BindingGroupName,
					Converter = new FortranLineCvt()
				};
				if (bindingExpression.ParentBinding.Source != null)
				{
					binding.Source = bindingExpression.ParentBinding.Source;
				}
				else if (!string.IsNullOrEmpty(bindingExpression.ParentBinding.ElementName))
				{
					binding.ElementName = bindingExpression.ParentBinding.ElementName;
				}
				else if (bindingExpression.ParentBinding.RelativeSource != null)
				{
					binding.RelativeSource = bindingExpression.ParentBinding.RelativeSource;
				}
				richTextBox.SetBinding(TextBox.TextProperty, binding);
			}
			richTextBox.CommandBindings.Add(new CommandBinding(ApplicationCommands.Copy, Copy_Executed, Copy_CanExecute));
		}

		private void richTextBox_PreviewKeyDown(object sender, KeyEventArgs e)
		{
			if (e.Key == Key.Oem7 && (Keyboard.Modifiers & ModifierKeys.Shift) == ModifierKeys.Shift)
			{
				e.Handled = true;
			}
		}

		private void richTextBox_KeyDown(object sender, KeyEventArgs e)
		{
