	[TemplatePart(Name = "PART_Border", Type = typeof(Border))]
	public class MMInContextGuidanceButton : Control
	{
		private static class InjectionHelper
		{
			public static void CheckInjectionPoint(ContentControl injectionTarget, out bool? isTopRightCornerAvailable, out bool isWindowsFormsHostOverlapped)
			{
				if (injectionTarget.Content is FrameworkElement frameworkElement)
				{
					Thickness marginInTemplate = GetMarginInTemplate(injectionTarget);
					System.Windows.Point point = new System.Windows.Point(injectionTarget.ActualWidth - marginInTemplate.Left - marginInTemplate.Right - 24.0, marginInTemplate.Top + marginInTemplate.Bottom + 24.0);
					System.Windows.Point point2 = new System.Windows.Point(injectionTarget.ActualWidth, 0.0);
					System.Windows.Point point3 = frameworkElement.TranslatePoint(default(System.Windows.Point), injectionTarget);
					UIElement uIElement = FindElementAtPosition(frameworkElement, new Rect(point - (Vector)point3, point2 - (Vector)point3), frameworkElement);
					while (uIElement != null && uIElement != injectionTarget)
					{
						if (uIElement is HwndHost)
						{
							if (!(uIElement is WindowsFormsHost))
							{
								isTopRightCornerAvailable = false;
							}
							else
							{
								isTopRightCornerAvailable = null;
							}
							isWindowsFormsHostOverlapped = true;
							return;
						}
						if (IsPotentialOverlappedControl(uIElement))
						{
							isTopRightCornerAvailable = false;
							isWindowsFormsHostOverlapped = false;
							return;
						}
						uIElement = VisualTreeHelper.GetParent(uIElement) as UIElement;
					}
				}
				isTopRightCornerAvailable = true;
				isWindowsFormsHostOverlapped = false;
			}

			private static UIElement FindElementAtPosition(UIElement element, Rect relativeCheckRect, UIElement relativeTarget)
			{
				if (!(element is FrameworkElement { Visibility: Visibility.Visible } frameworkElement))
				{
					return null;
				}
				System.Windows.Point location = frameworkElement.TranslatePoint(default(System.Windows.Point), relativeTarget);
				if (!new Rect(location, frameworkElement.RenderSize).IntersectsWith(relativeCheckRect))
				{
					return null;
				}
				if (frameworkElement is HwndHost || IsPotentialOverlappedControl(frameworkElement))
				{
					return frameworkElement;
				}
				int childrenCount = VisualTreeHelper.GetChildrenCount(element);
				for (int i = 0; i < childrenCount; i++)
				{
					UIElement uIElement = FindElementAtPosition(VisualTreeHelper.GetChild(element, i) as UIElement, relativeCheckRect, relativeTarget);
					if (uIElement != null)
					{
						return uIElement;
					}
				}
				return null;
			}

			private static bool IsPotentialOverlappedControl(UIElement temp)
			{
				if (temp is TextBox || temp is TextBlock || temp is ButtonBase || temp is GroupBox || temp is MMGroupBox || temp is DataGrid)
				{
					return true;
				}
				if (temp is ContentPresenter || temp is ContentControl || temp is Border)
				{
					return false;
				}
				if (temp is TabControl { TabStripPlacement: Dock.Top })
				{
					return false;
				}
				if (temp is Control)
				{
					return true;
				}
				return false;
			}
		}

