		private void ReInitializeContent()
		{
			if (_border == null || !base.IsLoaded)
			{
				return;
			}
			_internalButton = CreateInContextGuidanceButton();
			if (StaysInElementHost == true)
			{
				_internalButton.HorizontalAlignment = HorizontalAlignment.Center;
				_internalButton.VerticalAlignment = VerticalAlignment.Center;
				_border.Child = new WindowsFormsHost
				{
					Child = new ElementHost
					{
						Child = _internalButton
					}
				};
				if (_everLoaded)
				{
					base.Dispatcher.BeginInvoke(DispatcherPriority.Input, new Action(base.InvalidateMeasure));
				}
			}
			else
			{
				_border.Child = _internalButton;
			}
		}

