		private void InctxButton_InContextGuidancePropertiesRequested(object sender, InContextGuidancePropertiesRequestedEventArgs e)
		{
			e.ContextId = ResolveContextId();
		}

		private string ResolveContextId()
		{
			string contextId = ContextIdGenerator?.Invoke();
			ContextIdRequestedEventArgs e = new ContextIdRequestedEventArgs
			{
				ContextId = contextId
			};
			OnContextIdRequested(e);
			if (!string.IsNullOrWhiteSpace(e.ContextId))
			{
				return e.ContextId;
			}
			return GetContextIdFromLocalHelp();
		}

		protected virtual void OnContextIdRequested(ContextIdRequestedEventArgs args)
		{
			args.RoutedEvent = ContextIdRequestedEvent;
			args.Source = this;
			RaiseEvent(args);
		}

		private string GetContextIdFromLocalHelp()
		{
			if (!string.IsNullOrEmpty(_inContextGuidanceContextId))
			{
				return _inContextGuidanceContextId;
			}
			return _inContextGuidanceContextId = GenerateContextId();
		}

		protected virtual string GenerateContextId()
		{
			int? helpId = MMInContextGuidance.GetHelpId(this);
			if (helpId.HasValue)
			{
				return AppLevelControlSettings.Default.InContextGuidanceContextIdGenerator?.Invoke(new InContextGuidanceContextIdGenerationArgs(helpId, MMInContextGuidance.GetHelpFile(this), MMInContextGuidance.GetHelpContext(this)));
			}
			return null;
		}

		private void ResetInContextGuidanceContextId()
		{
			_inContextGuidanceContextId = null;
			_internalButton?.TryRequeryContextProperties();
		}

