		private static void OnUsedInTemplatePropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			if (!(d is UIElement uIElement))
			{
				return;
			}
			bool? flag = (bool?)e.NewValue;
			if (uIElement is ContentControl contentControl)
			{
				if (flag == true)
				{
					contentControl.ContentTemplate = ResolveContentDataTemplate(uIElement.GetType());
					InvalidateInjectionPosition(contentControl);
				}
				else
				{
					contentControl.ClearValue(ContentControl.ContentTemplateProperty);
				}
			}
		}

		private static DataTemplate ResolveContentDataTemplate(Type targetType)
		{
			if (_contentTemplates.ContainsKey(targetType))
			{
				return _contentTemplates[targetType];
			}
			DataTemplate dataTemplate = GenerateDataTemplateForInContextButton(targetType);
			_contentTemplates[targetType] = dataTemplate;
			return dataTemplate;
		}

		private static DataTemplate GenerateDataTemplateForInContextButton(Type targetType)
		{
			FrameworkElementFactory frameworkElementFactory = new FrameworkElementFactory(typeof(Grid));
			FrameworkElementFactory frameworkElementFactory2 = new FrameworkElementFactory(typeof(ColumnDefinition));
			frameworkElementFactory2.SetValue(ColumnDefinition.WidthProperty, new GridLength(1.0, GridUnitType.Star));
			FrameworkElementFactory frameworkElementFactory3 = new FrameworkElementFactory(typeof(ColumnDefinition));
			frameworkElementFactory3.SetValue(ColumnDefinition.WidthProperty, new GridLength(1.0, GridUnitType.Auto));
			frameworkElementFactory.AppendChild(frameworkElementFactory2);
			frameworkElementFactory.AppendChild(frameworkElementFactory3);
			FrameworkElementFactory frameworkElementFactory4 = new FrameworkElementFactory(typeof(ContentPresenter));
			frameworkElementFactory4.SetBinding(ContentPresenter.ContentProperty, new Binding());
			frameworkElementFactory.AppendChild(frameworkElementFactory4);
			FrameworkElementFactory frameworkElementFactory5 = new FrameworkElementFactory(typeof(MMInContextGuidanceButton));
			frameworkElementFactory5.SetBinding(FrameworkElement.MarginProperty, new Binding
			{
				RelativeSource = new RelativeSource(RelativeSourceMode.FindAncestor, targetType, 1),
				Path = new PropertyPath(MarginInTemplateProperty),
				Mode = BindingMode.OneWay
			});
			frameworkElementFactory5.SetBinding(Grid.ColumnProperty, new Binding
			{
				RelativeSource = new RelativeSource(RelativeSourceMode.FindAncestor, targetType, 1),
				Path = new PropertyPath(StaysInIsolatedColumnProperty),
				Converter = new InContextGuidanceButtonGridColumnConverter(),
				Mode = BindingMode.OneWay
			});
			frameworkElementFactory5.SetBinding(StaysInElementHostProperty, new Binding
			{
				RelativeSource = new RelativeSource(RelativeSourceMode.FindAncestor, targetType, 1),
				Path = new PropertyPath(StaysInElementHostProperty),
				Mode = BindingMode.OneWay
			});
			frameworkElementFactory.AppendChild(frameworkElementFactory5);
			return new DataTemplate
			{
				VisualTree = frameworkElementFactory
			};
		}

