		public static DependencyObject FindAncestorElement(DependencyObject from, Func<DependencyObject, bool> filter, DependencyObject upperLimit = null)
		{
			if (from == null)
			{
				throw new ArgumentNullException("from");
			}
			if (filter == null)
			{
				throw new ArgumentNullException("filter");
			}
			for (DependencyObject dependencyObject = from; dependencyObject != null; dependencyObject = FindParent(dependencyObject))
			{
				if (filter(dependencyObject))
				{
					return dependencyObject;
				}
				if (dependencyObject == upperLimit)
				{
					break;
				}
			}
			return null;
			static DependencyObject FindParent(DependencyObject target)
			{
				return VisualTreeHelper.GetParent(target) ?? LogicalTreeHelper.GetParent(target);
			}
		}

		public static DependencyObject FindDescendantElement(DependencyObject from, Func<DependencyObject, bool> filter, int detectionLayersLimit = 40)
		{
			if (from == null)
			{
				throw new ArgumentNullException("from");
			}
			if (filter == null)
			{
				throw new ArgumentNullException("filter");
			}
			Queue<(DependencyObject, int)> queue = new Queue<(DependencyObject, int)>();
			queue.Enqueue((from, 0));
			return InternalFindDescendantElement(queue, filter, Math.Max(1, detectionLayersLimit));
		}

		private static DependencyObject InternalFindDescendantElement(Queue<(DependencyObject, int)> layeredObjects, Func<DependencyObject, bool> filter, int detectionLayersLimit)
		{
			if (layeredObjects.Count > 0)
			{
				var (dependencyObject, num) = layeredObjects.Dequeue();
				if (filter(dependencyObject))
				{
					return dependencyObject;
				}
				if (num < detectionLayersLimit && !GetSuppressDescendantSearch(dependencyObject))
				{
					int childrenCount = VisualTreeHelper.GetChildrenCount(dependencyObject);
					for (int i = 0; i < childrenCount; i++)
					{
						layeredObjects.Enqueue((VisualTreeHelper.GetChild(dependencyObject, i), num + 1));
					}
				}
				return InternalFindDescendantElement(layeredObjects, filter, detectionLayersLimit);
			}
			return null;
		}

		public static bool InjectIntoXamTabControl(XamTabControl tc)
		{
			if (tc == null)
