			frameworkElementFactory.SetValue(StackPanel.OrientationProperty, Orientation.Horizontal);
			frameworkElementFactory.SetValue(FrameworkElement.MarginProperty, new Thickness(0.0, 0.0, 0.0, -4.0));
			FrameworkElementFactory frameworkElementFactory2 = new FrameworkElementFactory(typeof(ContentPresenter));
			frameworkElementFactory2.SetBinding(ContentPresenter.ContentProperty, new Binding());
			frameworkElementFactory.AppendChild(frameworkElementFactory2);
			FrameworkElementFactory frameworkElementFactory3 = new FrameworkElementFactory(typeof(MMInContextGuidanceButton));
			frameworkElementFactory3.SetValue(FrameworkElement.VerticalAlignmentProperty, VerticalAlignment.Center);
			frameworkElementFactory3.SetValue(FrameworkElement.MarginProperty, new Thickness(4.0, 0.0, 0.0, 0.0));
			frameworkElementFactory3.SetBinding(FrameworkElement.DataContextProperty, new Binding
			{
				RelativeSource = new RelativeSource(RelativeSourceMode.FindAncestor, typeof(XamTabControl), 1),
				Path = new PropertyPath(TabControl.SelectedContentProperty),
				Mode = BindingMode.OneWay
			});
			frameworkElementFactory3.SetBinding(MMInContextGuidance.HelpIdProperty, new Binding
