		public static void RegisterContentControlToAllowInjection(Type contentControlType)
		{
			if (contentControlType != null && !_allowedInjectionTypes.Contains(contentControlType))
			{
				_allowedInjectionTypes.Add(contentControlType);
			}
		}

		public static bool IsAllowedContentControl(Type contentControlType)
		{
			if (contentControlType != null)
			{
				if (!_allowedInjectionTypes.Contains(contentControlType))
				{
					return _allowedInjectionTypes.Any((Type x) => x.IsAssignableFrom(contentControlType));
				}
				return true;
			}
			return false;
		}

		public static void InvalidateInjectionPosition(ContentControl cc)
		{
			if (cc == null)
			{
				throw new ArgumentNullException("cc");
			}
			cc.Dispatcher.BeginInvokeOnce(delegate
			{
				UpdateInjectionPosition(cc);
			}, DispatcherPriority.Loaded);
		}

		private static void UpdateInjectionPosition(ContentControl injectionTarget)
		{
			if (injectionTarget == null)
			{
				throw new ArgumentNullException("injectionTarget");
			}
			bool? staysInIsolatedColumn = GetStaysInIsolatedColumn(injectionTarget);
			bool? staysInElementHost = GetStaysInElementHost(injectionTarget);
			if (!staysInIsolatedColumn.HasValue || !staysInElementHost.HasValue)
			{
				InjectionHelper.CheckInjectionPoint(injectionTarget, out var isTopRightCornerAvailable, out var isWindowsFormsHostOverlapped);
				if (!staysInIsolatedColumn.HasValue && isTopRightCornerAvailable.HasValue)
				{
					SetStaysInIsolatedColumn(injectionTarget, !isTopRightCornerAvailable.Value);
				}
				if (!staysInElementHost.HasValue)
				{
					SetStaysInElementHost(injectionTarget, isWindowsFormsHostOverlapped);
				}
			}
		}
	}
