	public class MMUnitsLabel : AesUnitsLabel
	{
		private IUnityContainer _unityContainer;

		private bool _registered;

		public static readonly DependencyProperty ShowUnitForGlobalUnitSetProperty = DependencyProperty.Register("ShowUnitForGlobalUnitSet", typeof(bool), typeof(MMUnitsLabel), new FrameworkPropertyMetadata(OnShowUnitForGlobalUnitSetPropertyChanged));

		public bool ShowUnitForGlobalUnitSet
		{
			get
			{
				return (bool)GetValue(ShowUnitForGlobalUnitSetProperty);
			}
			set
			{
				SetValue(ShowUnitForGlobalUnitSetProperty, value);
			}
		}

		public MMUnitsLabel()
		{
			base.Loaded += MMUnitsLabel_Loaded;
			base.Unloaded += MMUnitsLabel_Unloaded;
		}

		private void MMUnitsLabel_Loaded(object sender, RoutedEventArgs e)
		{
			SubscribeGlobalUnitSetChangedEvent();
		}

		private void MMUnitsLabel_Unloaded(object sender, RoutedEventArgs e)
		{
			UnsubscribeGlobalUnitSetChangedEvent();
		}

		protected override string CalculateResolvedUnitToDisplay()
		{
			if (ShowUnitForGlobalUnitSet && base.UnitRow != 0 && base.Variable is CxvPropertyData cxvPropertyData)
			{
				ICxvViewDataContainer dataContainer = cxvPropertyData.DataContainer;
				object obj;
				if (dataContainer == null)
				{
					obj = null;
				}
				else
				{
					IUnityContainer unityContainer = dataContainer.UnityContainer;
					obj = ((unityContainer != null) ? UnityContainerHelper.TryResolve<IAdbUnitsProvider>(unityContainer) : null);
				}
				IAdbUnitsProvider adbUnitsProvider = (IAdbUnitsProvider)obj;
				if (adbUnitsProvider != null)
				{
					return adbUnitsProvider.GetDefaultDisplayUnits(base.UnitRow);
				}
			}
			return base.CalculateResolvedUnitToDisplay();
		}

		protected override void OnVariableChanged(object oldValue, object newValue)
		{
			PrepareForGlobalUnitSet();
			base.OnVariableChanged(oldValue, newValue);
		}

		private void PrepareForGlobalUnitSet()
		{
			if (ShowUnitForGlobalUnitSet && base.Variable is CxvPropertyData cxvPropertyData)
			{
				_unityContainer = cxvPropertyData.DataContainer?.UnityContainer;
				SubscribeGlobalUnitSetChangedEvent();
			}
		}

		private void SubscribeGlobalUnitSetChangedEvent()
		{
			if (_unityContainer != null && !_registered)
			{
				_unityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<AplusGlobalUnitSetChangedEvent>().Subscribe(OnAplusGlobalUnitSetChangedEvent);
				_registered = true;
			}
		}

		private void UnsubscribeGlobalUnitSetChangedEvent()
		{
			if (_unityContainer != null && _registered)
			{
				_unityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<AplusGlobalUnitSetChangedEvent>().Unsubscribe(OnAplusGlobalUnitSetChangedEvent);
				_registered = false;
			}
		}

		private void OnAplusGlobalUnitSetChangedEvent(AplusGlobalUnitSetChangedEventArgs e)
		{
			RefreshResolvedUnitToDisplay();
		}

		private static void OnShowUnitForGlobalUnitSetPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			MMUnitsLabel obj = d as MMUnitsLabel;
			obj.PrepareForGlobalUnitSet();
			obj.RefreshResolvedUnitToDisplay();
		}
	}
	public class ObjectNameComparer : IComparer<string>
	{
		public class ObjectNameParser
		{
			public enum DataType
			{
				None,
				Number,
				Character
			}

			private string _name;

			private int _length;

			private int _currentIndex;

			private char _currentChar;

			public DataType TokenType { get; set; }

			public string StringValue { get; private set; }

			public ulong IntegerValue { get; private set; }

			public ObjectNameParser(string name)
			{
				_name = name;
				_length = name.Length;
				NextChar();
				NextToken();
			}

			private void NextChar()
			{
				if (_currentIndex >= _length)
				{
					_currentChar = '\0';
					return;
				}
				_currentChar = _name[_currentIndex];
				_currentIndex++;
			}

			public void NextToken()
			{
				if (_currentChar == '\0')
				{
					TokenType = DataType.None;
					StringValue = null;
				}
				else if (char.IsDigit(_currentChar))
				{
					int currentIndex = _currentIndex;
					while (char.IsDigit(_currentChar))
					{
						NextChar();
					}
					string text = _name.Substring(currentIndex - 1, ((_currentChar == '\0') ? (_length + 1) : _currentIndex) - currentIndex);
					if (ulong.TryParse(text, out var result))
					{
						IntegerValue = result;
						TokenType = DataType.Number;
					}
					else
					{
						TokenType = DataType.Character;
					}
					StringValue = text;
				}
				else if (char.IsLetter(_currentChar))
				{
					TokenType = DataType.Character;
					int currentIndex = _currentIndex;
					while (char.IsLetter(_currentChar))
					{
						NextChar();
					}
					StringValue = _name.Substring(currentIndex - 1, _currentIndex - currentIndex);
				}
				else
				{
					NextChar();
				}
			}
		}

		public int Compare(string name1, string name2)
		{
			ObjectNameParser objectNameParser = new ObjectNameParser(name1);
			ObjectNameParser objectNameParser2 = new ObjectNameParser(name2);
			while (objectNameParser.TokenType != ObjectNameParser.DataType.None || objectNameParser2.TokenType != ObjectNameParser.DataType.None)
			{
				if (objectNameParser.TokenType == ObjectNameParser.DataType.Number && objectNameParser2.TokenType == ObjectNameParser.DataType.Number)
				{
					if (objectNameParser.IntegerValue.CompareTo(objectNameParser2.IntegerValue) != 0)
					{
						return objectNameParser.IntegerValue.CompareTo(objectNameParser2.IntegerValue);
					}
					objectNameParser.NextToken();
					objectNameParser2.NextToken();
				}
				else
				{
					if (string.Compare(objectNameParser.StringValue, objectNameParser2.StringValue) != 0)
					{
						return string.Compare(objectNameParser.StringValue, objectNameParser2.StringValue);
					}
					objectNameParser.NextToken();
					objectNameParser2.NextToken();
				}
			}
			return 0;
		}
	}
