			topThumb = GetTemplateChild("Part_TopThumb") as Thumb;
			topRightThumb = GetTemplateChild("Part_TopRightThumb") as Thumb;
			rightThumb = GetTemplateChild("Part_RightThumb") as Thumb;
			rightBottomThumb = GetTemplateChild("Part_RightBottomThumb") as Thumb;
			bottomThumb = GetTemplateChild("Part_BottomThumb") as Thumb;
			bottomLeftThumb = GetTemplateChild("Part_BottomLeftThumb") as Thumb;
			if (leftThumb != null && leftTopThumb != null && topThumb != null && topRightThumb != null && rightThumb != null && rightBottomThumb != null && bottomThumb != null && bottomLeftThumb != null)
			{
				leftThumb.Cursor = Cursors.SizeWE;
				rightThumb.Cursor = Cursors.SizeWE;
				topThumb.Cursor = Cursors.SizeNS;
				bottomThumb.Cursor = Cursors.SizeNS;
				leftTopThumb.Cursor = Cursors.SizeNWSE;
				rightBottomThumb.Cursor = Cursors.SizeNWSE;
				topRightThumb.Cursor = Cursors.SizeNESW;
				bottomLeftThumb.Cursor = Cursors.SizeNESW;
				leftThumb.DragDelta += thumb_DragDelta;
				rightThumb.DragDelta += thumb_DragDelta;
				topThumb.DragDelta += thumb_DragDelta;
				bottomThumb.DragDelta += thumb_DragDelta;
				leftTopThumb.DragDelta += thumb_DragDelta;
				rightBottomThumb.DragDelta += thumb_DragDelta;
				topRightThumb.DragDelta += thumb_DragDelta;
				bottomLeftThumb.DragDelta += thumb_DragDelta;
			}
		}

		private void thumb_DragDelta(object sender, DragDeltaEventArgs e)
		{
			Thumb obj = sender as Thumb;
			double num = base.ActualWidth;
			double num2 = base.ActualHeight;
			switch (obj.Name)
			{
			case "Part_LeftThumb":
				num -= e.HorizontalChange;
				break;
			case "Part_LeftTopThumb":
				num -= e.HorizontalChange;
				num2 -= e.VerticalChange;
				break;
			case "Part_TopThumb":
				num2 -= e.VerticalChange;
				break;
			case "Part_TopRightThumb":
				num += e.HorizontalChange;
				num2 -= e.VerticalChange;
				break;
			case "Part_RightThumb":
				num += e.HorizontalChange;
				break;
			case "Part_RightBottomThumb":
				num += e.HorizontalChange;
				num2 += e.VerticalChange;
				break;
			case "Part_BottomThumb":
				num2 += e.VerticalChange;
				break;
			case "Part_BottomLeftThumb":
				num -= e.HorizontalChange;
				num2 += e.VerticalChange;
				break;
			}
			if (num <= base.MaxWidth && num >= base.MinWidth && (IsLeftResizable || IsRightResizable))
			{
				base.Width = num;
			}
			if (num2 <= base.MaxHeight && num2 >= base.MinHeight && (IsTopResizable || IsBottomResizable))
			{
				base.Height = num2;
			}
		}
	}
	public sealed class RibbonAwareness : DependencyObject
	{
		public static readonly DependencyProperty ContextualScreenProperty = DependencyProperty.RegisterAttached("ContextualScreen", typeof(ScreenContentControl), typeof(RibbonAwareness), new PropertyMetadata(OnContextualScreenPropertyChanged));

		public static readonly DependencyProperty ContextualRibbonTabProperty = DependencyProperty.RegisterAttached("ContextualRibbonTab", typeof(string), typeof(RibbonAwareness), new PropertyMetadata(OnContextualRibbonTabPropertyChanged));

		private static readonly DependencyPropertyKey ActiveRibbonLinkedElementPropertyKey = DependencyProperty.RegisterAttachedReadOnly("ActiveRibbonLinkedElement", typeof(UIElement), typeof(RibbonAwareness), null);

		public static readonly DependencyProperty ActiveRibbonLinkedElementProperty = ActiveRibbonLinkedElementPropertyKey.DependencyProperty;

		public static void SetContextualScreen(UIElement target, ScreenContentControl screen)
		{
			if (target == null)
			{
				throw new ArgumentNullException("target");
			}
			target.SetValue(ContextualScreenProperty, screen);
		}

		public static ScreenContentControl GetContextualScreen(UIElement target)
		{
			if (target == null)
			{
				throw new ArgumentNullException("target");
			}
			return (ScreenContentControl)target.GetValue(ContextualScreenProperty);
		}

		private static void OnContextualScreenPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			UpdateContextualInformation(d as UIElement);
		}

		public static void SetContextualRibbonTab(UIElement target, string contextualRibbonTabKey)
		{
			if (target == null)
			{
				throw new ArgumentNullException("target");
			}
			target.SetValue(ContextualRibbonTabProperty, contextualRibbonTabKey);
		}

		public static string GetContextualRibbonTab(UIElement target)
		{
			if (target == null)
			{
				throw new ArgumentNullException("target");
			}
			return (string)target.GetValue(ContextualRibbonTabProperty);
		}

		private static void OnContextualRibbonTabPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			UpdateContextualInformation(d as UIElement);
		}

		private static void SetActiveRibbonLinkedElement(ScreenContentControl target, UIElement element)
		{
			if (target == null)
			{
				throw new ArgumentNullException("target");
			}
			target.SetValue(ActiveRibbonLinkedElementPropertyKey, element);
		}

		public static UIElement GetActiveRibbonLinkedElement(ScreenContentControl target)
		{
			if (target == null)
			{
				throw new ArgumentNullException("target");
			}
			return (UIElement)target.GetValue(ActiveRibbonLinkedElementProperty);
		}

		private static void UpdateContextualInformation(UIElement target)
		{
			if (target == null)
			{
				return;
			}
			ScreenContentControl contextualScreen = GetContextualScreen(target);
			if (contextualScreen != null)
			{
				string contextualRibbonTab = GetContextualRibbonTab(target);
				if (!string.IsNullOrWhiteSpace(contextualRibbonTab))
				{
					ShowOrHideContextualRibbonTab(contextualScreen, target, contextualRibbonTab);
					target.IsKeyboardFocusWithinChanged += target_IsKeyboardFocusWithinChanged;
				}
			}
		}

		private static void target_IsKeyboardFocusWithinChanged(object sender, DependencyPropertyChangedEventArgs e)
		{
			UIElement target = sender as UIElement;
			string contextualRibbonTab = GetContextualRibbonTab(target);
			if (!string.IsNullOrWhiteSpace(contextualRibbonTab))
			{
				ScreenContentControl contextualScreen = GetContextualScreen(target);
				if (contextualScreen != null)
				{
					ShowOrHideContextualRibbonTab(contextualScreen, target, contextualRibbonTab);
				}
			}
		}

		private static void ShowOrHideContextualRibbonTab(ScreenContentControl screen, UIElement target, string tab)
		{
			if (target.IsKeyboardFocusWithin)
			{
				if (!screen.RequiredContextualTabs.Contains(tab))
				{
					screen.RequiredContextualTabs.Add(tab);
				}
				SetActiveRibbonLinkedElement(screen, target);
				PublishRibbonLinkedElementChangedEvent(screen, target);
				target.Dispatcher.BeginInvoke(new Action<ScreenContentControl, UIElement, string>(EnsureContextualTabSelected), DispatcherPriority.Loaded, screen, target, tab);
			}
			else
			{
				if (screen.RequiredContextualTabs.Contains(tab))
				{
					screen.RequiredContextualTabs.Remove(tab);
				}
				PublishRibbonLinkedElementChangedEvent(screen, null);
			}
		}

		private static void EnsureContextualTabSelected(ScreenContentControl screen, UIElement target, string tab)
		{
			if (string.IsNullOrWhiteSpace(tab) || screen.RequiredContextualTabs.Count == 0)
			{
				return;
			}
			XamRibbon ribbon = (screen.UnityContainer.Resolve<IShellApplication>(Array.Empty<ResolverOverride>()).ActiveWindow as CommonShellWindow).Ribbon;
			if (ribbon != null)
			{
				ContextualTabGroup contextualTabGroup = ribbon.ContextualTabGroups.FirstOrDefault((ContextualTabGroup x) => x.IsVisible && x.Tabs.Count > 0 && string.Equals(x.Key, tab));
				if (contextualTabGroup != null && !contextualTabGroup.Tabs.Any((RibbonTabItem x) => x.IsSelected))
				{
					contextualTabGroup.Tabs.First().IsSelected = true;
				}
			}
		}

		private static void PublishRibbonLinkedElementChangedEvent(ScreenContentControl screen, UIElement target)
		{
			if (screen != null && screen.UnityContainer != null)
			{
				screen.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<RibbonLinkedElementChangedEvent>().Publish(new RibbonLinkedElementChangedEventArgs(screen, target));
			}
		}
	}
	public class RibbonLinkedElementChangedEventArgs
	{
		public ScreenContentControl ActiveScreen { get; private set; }

		public UIElement ActiveElement { get; private set; }

		public RibbonLinkedElementChangedEventArgs(ScreenContentControl screen, UIElement element)
		{
			ActiveScreen = screen;
			ActiveElement = element;
		}
	}
	public class RibbonLinkedElementChangedEvent : RoutedCompositePresentationEvent<RibbonLinkedElementChangedEventArgs>
	{
		public RibbonLinkedElementChangedEvent()
		{
			base.RoutingStrategy = CompositeEventRoutingStrategy.AllTopDown;
		}
	}
	public class MMHorizontalGrid : Control
	{
