		private void MMHorizontalGrid_DataContextChanged(object sender, DependencyPropertyChangedEventArgs e)
		{
			_vm = e.NewValue as CxvViewModel;
			if (_vm != null)
			{
				if (_listValuesData != null)
				{
					_listValuesData.CollectionChanged -= listValuesData_CollectionChanged;
				}
				_listValuesData = _vm.ResolveViewPropertyPath(DataProperty) as CxvListValuesPropertyData;
				if (_listValuesData != null)
				{
					_listValuesData.CollectionChanged += listValuesData_CollectionChanged;
					RefreshData();
				}
			}
		}

		private void RefreshData()
		{
			if (_listValuesData == null || _vm == null || !(_listValuesData.Property is CxvListValuesProperty { CellProperty: { } cellProperty }) || !(_listValuesData.IndexBasis is CxvChildCountIndexBasisData cxvChildCountIndexBasisData))
			{
				return;
			}
			if (cxvChildCountIndexBasisData.Count == _wrapPanel.Children.Count + 1 && !IsInsertingColumn)
			{
				MMHorizontalGridCell element = CreateOneCell(_vm, cellProperty, cxvChildCountIndexBasisData.ChildIdsVector[cxvChildCountIndexBasisData.ChildIdsVector.Count() - 1]);
				_wrapPanel.Children.Add(element);
			}
			else
			{
				if (_wrapPanel.Children.Count > 0)
				{
					_wrapPanel.Children.Clear();
				}
				for (int i = 0; i < cxvChildCountIndexBasisData.Count; i++)
				{
					MMHorizontalGridCell element2 = CreateOneCell(_vm, cellProperty, cxvChildCountIndexBasisData.ChildIdsVector[i]);
					_wrapPanel.Children.Add(element2);
				}
			}
			if (IsInsertingColumn)
			{
				IsInsertingColumn = false;
			}
		}

		private MMHorizontalGridCell CreateOneCell(CxvViewModel vm, CxvVariableProperty property, string idInPath)
		{
			MMHorizontalGridCell mMHorizontalGridCell = new MMHorizontalGridCell();
			mMHorizontalGridCell.Variable = new CxvVariableData(vm, new CxvVariableProperty
			{
				DataPath = property.DataPath + "." + idInPath,
				VariablePrompt = property.VariablePrompt,
				VariablePromptResourceKey = property.VariablePromptResourceKey
			});
			mMHorizontalGridCell.PreviewKeyDown += cell_PreviewKeyDown;
			return mMHorizontalGridCell;
		}

		private void listValuesData_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			if (e.Action != NotifyCollectionChangedAction.Reset)
			{
				return;
			}
			RefreshData();
			if (_resetFocusAfterDataRest)
			{
				if (_wrapPanel.Children.Count > _indexToFocused && _indexToFocused > -1)
				{
					MMHorizontalGridCell edit = _wrapPanel.Children[_indexToFocused] as MMHorizontalGridCell;
					SetCellFocusedAndSelected(edit, runSync: false);
				}
				_resetFocusAfterDataRest = false;
				_indexToFocused = -1;
			}
		}

		private void cell_PreviewKeyDown(object sender, KeyEventArgs e)
		{
			MMHorizontalGridCell mMHorizontalGridCell = sender as MMHorizontalGridCell;
			MMValueEdit valueEdit = mMHorizontalGridCell.ValueEdit;
			bool flag = false;
			AesXamValueEdit aesXamValueEdit = Infragistics.Windows.Utilities.GetDescendantFromType(mMHorizontalGridCell, typeof(AesXamValueEdit), allowSubclassOfType: false) as AesXamValueEdit;
			if (aesXamValueEdit != null)
			{
				flag = aesXamValueEdit.IsInEditMode;
			}
			bool handled = false;
			if (e.Key == Key.Return)
			{
				int num = _wrapPanel.Children.IndexOf(mMHorizontalGridCell);
				if (num == _wrapPanel.Children.Count - 1)
				{
					if (valueEdit.Value != null && valueEdit.Value != DBNull.Value)
					{
						_resetFocusAfterDataRest = true;
						_indexToFocused = num + 1;
					}
				}
				else if (valueEdit.Value != null && valueEdit.Value != DBNull.Value)
				{
					MMHorizontalGridCell edit = _wrapPanel.Children[num + 1] as MMHorizontalGridCell;
					SetCellFocusedAndSelected(edit, runSync: true);
				}
				else
				{
					_resetFocusAfterDataRest = true;
					_indexToFocused = num;
				}
			}
			else if (e.Key == Key.A)
			{
				if ((Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control && aesXamValueEdit != null && !flag)
				{
					for (int i = 0; i < _wrapPanel.Children.Count; i++)
					{
						(_wrapPanel.Children[i] as MMHorizontalGridCell).IsSelected = true;
					}
					handled = true;
				}
			}
			else if (e.Key == Key.C)
			{
				if ((Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control && aesXamValueEdit != null && !flag)
				{
					SetClipboardData(_vm, this);
					handled = true;
				}
			}
			else if (e.Key == Key.V)
			{
				if ((Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control && aesXamValueEdit != null && !flag)
				{
					DoPaste(mMHorizontalGridCell);
					handled = true;
				}
			}
			else if (e.Key == Key.Escape)
			{
				if (aesXamValueEdit != null && flag)
				{
					aesXamValueEdit.EndEditMode(acceptChanges: true, force: false);
					handled = true;
				}
			}
			else if (e.Key == Key.F2)
			{
				if (aesXamValueEdit != null && !flag)
				{
					aesXamValueEdit.StartEditMode();
					handled = true;
				}
			}
			else if (e.Key == Key.Tab)
			{
				int num2 = _wrapPanel.Children.IndexOf(mMHorizontalGridCell);
				if (num2 == _wrapPanel.Children.Count - 1)
				{
					if (valueEdit.Value != null && valueEdit.Value != DBNull.Value)
					{
						_resetFocusAfterDataRest = true;
						_indexToFocused = num2 + 1;
						handled = true;
					}
					else
					{
						handled = false;
					}
				}
				else if (valueEdit.Value != null && valueEdit.Value != DBNull.Value)
				{
					MMHorizontalGridCell edit2 = _wrapPanel.Children[num2 + 1] as MMHorizontalGridCell;
					SetCellFocusedAndSelected(edit2, runSync: true);
					handled = true;
				}
				else
				{
					_resetFocusAfterDataRest = true;
					_indexToFocused = num2;
					handled = true;
				}
			}
			else if (e.Key == Key.Home)
			{
				if (!flag)
				{
					if ((Keyboard.Modifiers & ModifierKeys.Shift) == ModifierKeys.Shift)
					{
						int num3 = SelectedCells.Min((MMHorizontalGridCell element) => _wrapPanel.Children.IndexOf(element));
						foreach (MMHorizontalGridCell item in _wrapPanel.Children.OfType<MMHorizontalGridCell>())
						{
							if (_wrapPanel.Children.IndexOf(item) <= num3)
							{
								item.IsSelected = true;
							}
							else
							{
								item.IsSelected = false;
							}
						}
					}
					else
					{
						for (int num4 = 0; num4 < _wrapPanel.Children.Count; num4++)
						{
							MMHorizontalGridCell mMHorizontalGridCell2 = _wrapPanel.Children[num4] as MMHorizontalGridCell;
							if (num4 == 0)
							{
								mMHorizontalGridCell2.IsSelected = true;
								mMHorizontalGridCell2.BringIntoView();
							}
							else
							{
								mMHorizontalGridCell2.IsSelected = false;
							}
						}
					}
					handled = true;
				}
			}
			else if (e.Key == Key.End)
			{
				if (!flag)
				{
					if ((Keyboard.Modifiers & ModifierKeys.Shift) == ModifierKeys.Shift)
					{
						int num5 = SelectedCells.Min((MMHorizontalGridCell element) => _wrapPanel.Children.IndexOf(element));
						foreach (MMHorizontalGridCell item2 in _wrapPanel.Children.OfType<MMHorizontalGridCell>())
						{
							if (_wrapPanel.Children.IndexOf(item2) >= num5)
							{
								item2.IsSelected = true;
							}
							else
							{
								item2.IsSelected = false;
							}
						}
					}
					else
					{
						for (int num6 = 0; num6 < _wrapPanel.Children.Count; num6++)
						{
							MMHorizontalGridCell mMHorizontalGridCell3 = _wrapPanel.Children[num6] as MMHorizontalGridCell;
							if (num6 == _wrapPanel.Children.Count - 1)
							{
								mMHorizontalGridCell3.IsSelected = true;
								mMHorizontalGridCell3.BringIntoView();
							}
							else
							{
								mMHorizontalGridCell3.IsSelected = false;
							}
						}
					}
					handled = true;
				}
			}
			else if (e.Key == Key.Delete)
			{
				if (!flag)
				{
					DeleteFields(this);
					handled = true;
				}
			}
			else if (e.Key == Key.Left)
			{
				if (!flag)
				{
					int num7 = _wrapPanel.Children.IndexOf(mMHorizontalGridCell);
					if (num7 > 0)
					{
						SetCellFocusedAndSelected(_wrapPanel.Children[num7 - 1] as MMHorizontalGridCell, runSync: true);
					}
					handled = true;
				}
			}
			else if (e.Key == Key.Right)
			{
				if (!flag)
				{
					int num8 = _wrapPanel.Children.IndexOf(mMHorizontalGridCell);
					if (num8 < _wrapPanel.Children.Count - 1)
					{
						SetCellFocusedAndSelected(_wrapPanel.Children[num8 + 1] as MMHorizontalGridCell, runSync: true);
					}
					handled = true;
				}
			}
			else if (ShouldSkipKey(e.Key))
			{
				handled = false;
			}
			else if (aesXamValueEdit != null && !flag)
			{
				aesXamValueEdit.StartEditMode();
				handled = false;
			}
			e.Handled = handled;
		}

		private void SetCellFocusedAndSelected(MMHorizontalGridCell edit, bool runSync)
		{
			Action action = delegate
			{
				if (!edit.IsFocused)
				{
					edit.Focus();
				}
				edit.IsSelected = true;
				foreach (MMHorizontalGridCell item in _wrapPanel.Children.OfType<MMHorizontalGridCell>())
				{
					if (item != edit)
					{
						item.IsSelected = false;
					}
				}
			};
			if (runSync)
			{
				action();
			}
			else
			{
				base.Dispatcher.BeginInvoke(DispatcherPriority.Input, action);
			}
		}

