		private static void OnMMValueEditPreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs arg)
		{
			if (arg.ClickCount != 1 || !(sender is MMValueEdit mMValueEdit) || !(Infragistics.Windows.Utilities.GetAncestorFromType(mMValueEdit, typeof(MMHorizontalGridCell), allowSubclassOfType: false) is MMHorizontalGridCell mMHorizontalGridCell) || !(Infragistics.Windows.Utilities.GetDescendantFromType(mMValueEdit, typeof(AesXamValueEdit), allowSubclassOfType: false) is AesXamValueEdit { IsInEditMode: false }))
			{
				return;
			}
			arg.Handled = true;
			if ((Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control)
			{
				mMHorizontalGridCell.IsSelected = true;
				return;
			}
			MMHorizontalGrid hg = Infragistics.Windows.Utilities.GetAncestorFromType(mMValueEdit, typeof(MMHorizontalGrid), allowSubclassOfType: false) as MMHorizontalGrid;
			if ((Keyboard.Modifiers & ModifierKeys.Shift) == ModifierKeys.Shift)
			{
				int num = hg.SelectedCells.Min((MMHorizontalGridCell i) => hg.WrapPanel.Children.IndexOf(i));
				int num2 = hg.WrapPanel.Children.IndexOf(mMHorizontalGridCell);
				foreach (MMHorizontalGridCell item in hg.WrapPanel.Children.OfType<MMHorizontalGridCell>())
				{
					int num3 = hg.WrapPanel.Children.IndexOf(item);
					if ((num3 >= num && num3 <= num2) || (num3 <= num && num3 >= num2))
					{
						item.IsSelected = true;
					}
					else
					{
						item.IsSelected = false;
					}
				}
			}
			else if (hg != null)
			{
				foreach (object child in hg.WrapPanel.Children)
				{
					if (child is MMHorizontalGridCell mMHorizontalGridCell2)
					{
						mMHorizontalGridCell2.IsSelected = false;
					}
				}
				mMHorizontalGridCell.IsSelected = true;
			}
			mMHorizontalGridCell.Focus();
		}

