		private static void SetClipboardData(CxvViewModel viewModel, MMHorizontalGrid hg)
		{
			string fullCasePath = viewModel.ResolveViewPropertyPath("ResolvedCxsProvider.Case.CaseFullFilePath").ToString();
			string applicationName = viewModel.ResolveViewPropertyPath("ResolvedCxsProvider.Case.ApplicationName").ToString();
			StringBuilder stringBuilder = new StringBuilder();
			Collection<string> collection = new Collection<string>();
			foreach (MMHorizontalGridCell selectedCell in hg.SelectedCells)
			{
				MMValueEdit valueEdit = selectedCell.ValueEdit;
				stringBuilder.Append((valueEdit.Value == null) ? "" : (valueEdit.Value.ToString() + "\t"));
				if (valueEdit.Variable is CxvVariableData cxvVariableData)
				{
					collection.Add("cxs:" + cxvVariableData.DataPath);
				}
			}
			string text = stringBuilder.ToString();
			if (text.EndsWith("\t"))
			{
				text = text.Substring(0, text.Length - 1);
			}
			ClipboardHelper.CreateClipboard(collection, text, fullCasePath, applicationName);
		}

