		{
			System.Windows.Controls.Image image = new System.Windows.Controls.Image();
			string text = "pack://application:,,,/" + typeof(MMHorizontalGrid).Assembly.FullName + ";component/Images/";
			image.Source = new BitmapImage(new Uri(text + strImage));
			return image;
		}

		private static void DoPaste(MMHorizontalGridCell editor)
		{
			if (!(Infragistics.Windows.Utilities.GetAncestorFromType(editor, typeof(MMHorizontalGrid), allowSubclassOfType: false) is MMHorizontalGrid { DataContext: CxvViewModel dataContext } mMHorizontalGrid))
			{
				return;
			}
			string text = null;
			try
			{
				text = ClipboardWrapper.GetText();
			}
			catch
			{
			}
			if (string.IsNullOrWhiteSpace(text))
			{
				return;
			}
			text = text.Trim('\r', '\n').Trim('\t');
			string[] array = text.Split('\n');
			if (array == null || array.Length == 0)
			{
				return;
			}
			List<string> list = new List<string>();
			for (int i = 0; i < array.Length; i++)
			{
				string[] array2 = array[i].Split('\t');
				for (int j = 0; j < array2.Length; j++)
				{
					string text2 = array2[j].Replace("\r", "");
					if (!string.IsNullOrWhiteSpace(text2))
					{
						list.Add(text2);
					}
				}
			}
			string[] array3 = list.ToArray();
			if (array3.Length == 0)
			{
				return;
			}
			CxsDataProvider resolvedCxsProvider = dataContext.ResolvedCxsProvider;
			int num = mMHorizontalGrid.WrapPanel.Children.IndexOf(editor);
			for (int k = 0; k < array3.Length; k++)
			{
				if (!string.IsNullOrEmpty(array3[k]) && mMHorizontalGrid.WrapPanel.Children.Count > num + k && (mMHorizontalGrid.WrapPanel.Children[num + k] as MMHorizontalGridCell).Variable is CxvVariableData cxvVariableData)
				{
					cxvVariableData.Value = array3[k];
					resolvedCxsProvider?.UpdateDataCache();
				}
			}
		}

		internal static void OnPasteCell(object sender, ExecutedRoutedEventArgs arg)
		{
			if (arg.Parameter is MMValueEdit descendant)
			{
				DoPaste(Infragistics.Windows.Utilities.GetAncestorFromType(descendant, typeof(MMHorizontalGridCell), allowSubclassOfType: false) as MMHorizontalGridCell);
			}
		}

