		private static bool CanClearCells(MMHorizontalGrid hg)
		{
			bool result = true;
			if (hg == null || hg.SelectedCells.Count() == 0)
			{
				return false;
			}
			if (hg.SelectedCells.Count() == 1 && hg.WrapPanel.Children.IndexOf(hg.SelectedCells.FirstOrDefault()) == hg.WrapPanel.Children.Count - 1)
			{
				return false;
			}
			foreach (MMHorizontalGridCell selectedCell in hg.SelectedCells)
			{
				MMValueEdit valueEdit = selectedCell.ValueEdit;
				if (valueEdit.IsReadOnly || !valueEdit.IsMMEnabled || !valueEdit.IsEnabled)
				{
					result = false;
					break;
				}
				if (valueEdit.Variable is CxvVariableData { IsCalculated: var isCalculated } && (isCalculated ?? false))
				{
					result = false;
					break;
				}
			}
			return result;
		}

