		private static bool ShouldSkipKey(Key key)
		{
			switch (key)
			{
			case Key.Back:
			case Key.Pause:
			case Key.Capital:
			case Key.Space:
			case Key.Prior:
			case Key.Next:
			case Key.Up:
			case Key.Down:
			case Key.Snapshot:
			case Key.Insert:
			case Key.LWin:
			case Key.RWin:
			case Key.F1:
			case Key.F3:
			case Key.F4:
			case Key.F5:
			case Key.F6:
			case Key.F7:
			case Key.F8:
			case Key.F9:
			case Key.F10:
			case Key.F11:
			case Key.F12:
			case Key.NumLock:
			case Key.Scroll:
			case Key.LeftShift:
			case Key.RightShift:
			case Key.LeftCtrl:
			case Key.RightCtrl:
			case Key.LeftAlt:
			case Key.RightAlt:
			case Key.System:
				return true;
			default:
				return false;
			}
		}
	}
