	{
		public static readonly DependencyProperty TextProperty = DependencyProperty.Register("Text", typeof(string), typeof(MMRichTextBox), new PropertyMetadata(null, OnTextPropertyChanged));

		public static readonly DependencyProperty CommandProperty = DependencyProperty.Register("Command", typeof(ICommand), typeof(MMRichTextBox), new PropertyMetadata(null, OnCommandPropertyChanged));

