		public MMRichTextBox()
		{
			base.IsDocumentEnabled = true;
			base.Document = new FlowDocument();
			base.Loaded += MMRichTextBox_Loaded;
		}

		private void MMRichTextBox_Loaded(object sender, RoutedEventArgs e)
		{
		}

		private static void OnTextPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			if (d is MMRichTextBox mMRichTextBox)
			{
				mMRichTextBox.OnTextChanged(e.OldValue as string, e.NewValue as string);
			}
		}

		private void OnTextChanged(string oldText, string newText)
		{
			if (!(oldText != newText))
			{
				return;
			}
			base.Document.Blocks.Clear();
			if (string.IsNullOrEmpty(newText))
			{
				return;
			}
			string[] array = newText.Split(new string[1] { "\n" }, int.MaxValue, StringSplitOptions.None);
			foreach (string text in array)
			{
				if (text.StartsWith("<ErrorObjects", StringComparison.InvariantCultureIgnoreCase))
				{
					Paragraph paragraph = new Paragraph();
					paragraph.Margin = new Thickness(0.0, 0.0, 0.0, 0.0);
					string[] array2 = text.Split('\t');
					XmlDocument xmlDocument = new XmlDocument();
					string[] array3 = array2;
					foreach (string xml in array3)
					{
						try
						{
							xmlDocument.LoadXml(xml);
							XmlNodeList elementsByTagName = xmlDocument.GetElementsByTagName("ErrorObjects");
							string value = elementsByTagName.Item(0).Attributes["Type"].Value;
							string value2 = elementsByTagName.Item(0).Attributes["RecordType"].Value;
							string innerText = elementsByTagName.Item(0).InnerText;
							Hyperlink hyperlink = new Hyperlink();
							hyperlink.Inlines.Add(innerText);
							hyperlink.Command = Command;
							hyperlink.CommandParameter = new DescriptionHyperlinkArgs(value, innerText, value2);
							Binding binding = new Binding();
							binding.Source = this;
							binding.UpdateSourceTrigger = UpdateSourceTrigger.PropertyChanged;
							binding.Path = new PropertyPath("Command");
							binding.Mode = BindingMode.OneWay;
							hyperlink.SetBinding(Hyperlink.CommandProperty, binding);
							paragraph.Inlines.Add(hyperlink);
							paragraph.Inlines.Add(" ");
						}
						catch (Exception)
						{
						}
					}
					base.Document.Blocks.Add(paragraph);
				}
				else
				{
					Paragraph paragraph2 = new Paragraph();
					paragraph2.Margin = new Thickness(0.0, 0.0, 0.0, 0.0);
					paragraph2.Inlines.Add(text);
					base.Document.Blocks.Add(paragraph2);
				}
			}
		}

		private static void OnCommandPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			if (d is MMRichTextBox mMRichTextBox)
			{
				mMRichTextBox.HookUpCommand((ICommand)e.OldValue, (ICommand)e.NewValue);
			}
		}

		private void HookUpCommand(ICommand oldCommand, ICommand newCommand)
		{
		}
	}
