	public class MMStretchGrid : Grid
	{
		private System.Windows.Size _measured;

		protected override System.Windows.Size MeasureOverride(System.Windows.Size constraint)
		{
			_measured = base.MeasureOverride(constraint);
			return _measured;
		}

		protected override System.Windows.Size ArrangeOverride(System.Windows.Size arrangeSize)
		{
			if (base.ColumnDefinitions.Count < 1)
			{
				return base.ArrangeOverride(arrangeSize);
			}
			if (_measured.Height < arrangeSize.Height)
			{
				double num = 0.0;
				{
					foreach (UIElement internalChild in base.InternalChildren)
					{
						double x = 0.0;
						double width = internalChild.DesiredSize.Width;
						if (internalChild is FrameworkElement frameworkElement)
						{
							switch (frameworkElement.HorizontalAlignment)
							{
							case HorizontalAlignment.Right:
								x = arrangeSize.Width - internalChild.DesiredSize.Width;
								break;
							case HorizontalAlignment.Center:
								x = (arrangeSize.Width - internalChild.DesiredSize.Width) / 2.0;
								break;
							case HorizontalAlignment.Stretch:
								width = arrangeSize.Width;
								break;
							}
						}
						Rect finalRect = new Rect(x, num, width, internalChild.DesiredSize.Height);
						internalChild.Arrange(finalRect);
						num += finalRect.Height;
					}
					return arrangeSize;
				}
			}
			return base.ArrangeOverride(arrangeSize);
		}
	}
