		private void RefreshIsEnabled()
		{
			base.Dispatcher.BeginInvoke(DispatcherPriority.Loaded, (Action)delegate
			{
				if (IsInputPage)
				{
					if (IsSimulatorRunning)
					{
						base.IsEnabled = false;
