		private bool IsAllowedPaste(object source)
		{
			if (source is TextBox || source is ComboBox)
			{
				return false;
			}
			if (source is MMScrollAreaBase)
			{
				return false;
			}
			DependencyObject descendant = source as DependencyObject;
			if (Infragistics.Windows.Utilities.GetAncestorFromType(descendant, typeof(AesVariableControlBase), allowSubclassOfType: true) is AesVariableControlBase aesVariableControlBase && !(aesVariableControlBase is AesGroupBox) && !(aesVariableControlBase is AesOptionGroup) && !(aesVariableControlBase is AesExpander))
			{
				return false;
			}
			if (Infragistics.Windows.Utilities.GetAncestorFromType(descendant, typeof(MMScrollAreaBase), allowSubclassOfType: true) is MMScrollAreaBase)
			{
				return false;
			}
			if (Infragistics.Windows.Utilities.GetAncestorFromType(descendant, typeof(MMScrollAreaMS), allowSubclassOfType: true) is MMScrollAreaMS)
			{
				return false;
			}
			if (Infragistics.Windows.Utilities.GetAncestorFromType(descendant, typeof(MMOptionButton), allowSubclassOfType: true) is MMOptionButton)
			{
				return false;
			}
			return true;
		}

		protected virtual bool IsAllowedPasteTarget(RoutedEventArgs e)
		{
			if (e == null)
			{
				throw new ArgumentNullException("e cannot be null.");
			}
			return IsAllowedPaste(e.OriginalSource);
		}

		protected virtual bool IsAllowedPasteTarget(DragEventArgs e)
		{
			if (e == null)
			{
				throw new ArgumentNullException("e cannot be null.");
			}
			return IsAllowedPaste(e.OriginalSource);
		}

		private void UpdateDragDropEffects(DragEventArgs e)
		{
			if (!e.Handled)
			{
				if (IsAllowedPasteTarget(e))
				{
					e.Effects = DragDropEffects.Copy;
					e.Handled = true;
				}
				else
				{
					e.Effects = DragDropEffects.None;
				}
			}
		}

		private static void Paste_Executed(object sender, ExecutedRoutedEventArgs e)
		{
		}

		private static void Paste_CanExecute(object sender, CanExecuteRoutedEventArgs e)
		{
			if (sender is MMViewModelContainer mMViewModelContainer)
			{
				e.CanExecute = (mMViewModelContainer.ViewModel as MMViewModel)?.CanPasteVariable() ?? false;
			}
			else
			{
				e.CanExecute = false;
			}
		}

		private static IEnumerable<T> GetVisualChildren<T>(DependencyObject parent) where T : DependencyObject
		{
			List<T> list = new List<T>();
			if (parent != null)
			{
				int childrenCount = VisualTreeHelper.GetChildrenCount(parent);
				for (int i = 0; i < childrenCount; i++)
				{
					DependencyObject child = VisualTreeHelper.GetChild(parent, i);
					if (child != null)
					{
						if (child is T item)
						{
							list.Add(item);
						}
						else
						{
							list.AddRange(GetVisualChildren<T>(child));
						}
					}
				}
			}
			return list;
		}
	}
