		public List<IGridCellData> SetDataBatchGet(string format, object data, bool autoConvert, bool isAllSelected = false)
		{
			List<IGridCellData> list = null;
			try
			{
				Clear();
				if (_ASISelectionXml != null)
				{
					_ASISelectionXml.Dispose();
					_ASISelectionXml = null;
				}
				if (format != typeof(MMScrollAreaMS).Name)
				{
					throw new ArgumentException("Supports MMScrollAreaMS only", "format");
				}
				_saro = data as MMScrollAreaMS;
				_selectedCells = new List<DataCellInfo>();
				_selectedCells.AddRange(_saro.DataGrid.TotalOrderedSelectedCells);
				Collection<string> collection = null;
				if (_selectedCells.Find((DataCellInfo x) => x.Data != null && (MMScrollAreaMS.GetCellBindingVariable(x) is CxvManualVariableData || MMScrollAreaMS.GetCellBindingVariable(x) is AdsVariableData)).Data == null && _saro.DataRetriever == null)
				{
					if (_selectedCells.Count >= 2000 && isAllSelected)
					{
						collection = _saro.GetSelectedCellCopyValuesCXS(generateCXSPathsFromFields: true);
						if (collection == null)
						{
							collection = _saro.GetSelectedCellCopyValuesCXS();
						}
					}
					else if (_selectedCells.Count >= 1000)
					{
						collection = _saro.GetSelectedCellCopyValuesCXS();
					}
				}
				Dictionary<MMScrollAreaField, CxvMultiMapOptionCollection> dictionary = new Dictionary<MMScrollAreaField, CxvMultiMapOptionCollection>();
				list = new List<IGridCellData>(_selectedCells.Count);
				int num = 0;
				int num2 = -1;
				int num3 = -1;
				if (IncludeColumnHeader)
				{
					List<MMScrollAreaField> selectedFields = GetSelectedFields(_saro);
					if (selectedFields != null)
					{
						foreach (MMScrollAreaField item2 in selectedFields)
						{
							if (item2 != null)
							{
								StringBuilder stringBuilder = new StringBuilder();
								List<MMScrollAreaField> selectedFields2 = new List<MMScrollAreaField> { item2 };
								GetLabelOfNonHeaderOnlyFields(stringBuilder, selectedFields2, _saro, ViewModel, setHeaderLineCount: false);
								CxsGridCellData item = new CxsGridCellData
								{
									TextValue = stringBuilder.ToString(),
									ColumnIndex = ((item2.DataColumn != null) ? item2.DataColumn.DisplayIndex : item2.Id),
									RowIndex = 0
								};
								list.Add(item);
								num2 = 0;
							}
						}
					}
				}
				if (_selectedCells != null)
				{
					foreach (DataCellInfo selectedCell in _selectedCells)
					{
						if (selectedCell.Row == null || selectedCell.Row.DataTable == null || selectedCell.Row.DataTable.Rows == null || selectedCell.Column == null)
						{
							continue;
						}
						int num4 = selectedCell.Row.DataTable.Rows.IndexOf(selectedCell.Row);
						int displayIndex = selectedCell.Column.DisplayIndex;
						if (IncludeColumnHeader && _saro.DataOrientation != Orientation.Horizontal)
						{
							num4++;
						}
						MMScrollAreaField mMScrollAreaField = null;
						if (_saro.DataOrientation == Orientation.Horizontal)
						{
							if (num4 > _saro.MMFields.Count - 1)
							{
								num4 = _saro.MMFields.Count - 1;
							}
							mMScrollAreaField = _saro.MMFields[num4];
						}
						else if (_saro.DataColumnMap.ContainsKey(selectedCell.Column as BindingDataColumn))
						{
							MMScrollAreaField mMScrollAreaField2 = _saro.DataColumnMap[selectedCell.Column as BindingDataColumn];
							if (mMScrollAreaField2 != null)
							{
								mMScrollAreaField = mMScrollAreaField2;
							}
						}
						if (mMScrollAreaField == null)
						{
							continue;
						}
						CxvMultiMapOptionCollection cxvMultiMapOptionCollection = null;
						if (!dictionary.ContainsKey(mMScrollAreaField))
						{
							try
							{
								if ((((_saro.DataContext as MMViewModel).ResolveViewPropertyPath(_saro.DataProperty) as CxvVectorPropertyData)[0] as MMViewModel).ResolveViewPropertyPath(mMScrollAreaField.PropertyPath) is CxvMultiMapPropertyData cxvMultiMapPropertyData)
								{
									CxvMultiMapProperty cxvMultiMapProperty = cxvMultiMapPropertyData.Property as CxvMultiMapProperty;
									dictionary.Add(mMScrollAreaField, cxvMultiMapProperty.Options);
								}
								else
								{
									dictionary.Add(mMScrollAreaField, null);
								}
							}
							catch
							{
								dictionary.Add(mMScrollAreaField, null);
							}
						}
						cxvMultiMapOptionCollection = dictionary[mMScrollAreaField];
						if (collection != null && collection[num] != "" && cxvMultiMapOptionCollection != null)
						{
							foreach (CxvMultiMapOption item3 in cxvMultiMapOptionCollection)
							{
								bool flag = false;
								foreach (CxvMultiMapValue value in item3.Values)
								{
									if (value.Value as string == collection[num])
									{
										flag = true;
										break;
									}
								}
								if (flag)
								{
									collection[num] = item3.Display;
									break;
								}
							}
						}
						bool flag2 = false;
						Type type = mMScrollAreaField.GetType();
						if (type == typeof(MMScrollAreaUnitsField) || type == typeof(MMScrollAreaTextField))
						{
							flag2 = true;
						}
						if (num2 == -1 || num4 < num2)
						{
							num2 = num4;
						}
						if (num3 == -1 || displayIndex < num3)
						{
							num3 = displayIndex;
						}
						CxsGridCellData cxsGridCellData = new CxsGridCellData
						{
							Moniker = ((!flag2 && Monikers.Count > num) ? Monikers[num] : string.Empty),
							RowIndex = num4,
							ColumnIndex = displayIndex
						};
						if (collection != null)
						{
							cxsGridCellData.TextValue = collection[num];
						}
						else if (selectedCell.Data != null && selectedCell.Data.Value != null)
						{
							cxsGridCellData.TextValue = selectedCell.Data.Value.ToString();
						}
						else
						{
							cxsGridCellData.TextValue = string.Empty;
						}
						if (_selectedCells.Count == 1 && selectedCell.Data.HostControl != null && selectedCell.Data.HostControl.IsInEditMode && Infragistics.Windows.Utilities.GetDescendantFromType(selectedCell.Data.HostControl, typeof(TextBox), allowSubclassOfType: true) is TextBox textBox && !string.IsNullOrEmpty(textBox.SelectedText))
						{
							cxsGridCellData.TextValue = textBox.SelectedText;
						}
						list.Add(cxsGridCellData);
						num++;
					}
				}
				foreach (IGridCellData item4 in list)
				{
					item4.RowIndex -= num2;
					item4.ColumnIndex -= num3;
				}
				_ASISelectionXml = ClipboardHelper.GetAsiSelectionXmlGridFormatStream(list, CaseFullFileName, ApplicationName);
				return list;
			}
			catch (Exception)
			{
				return null;
			}
		}

