		private string GetPropPath(DataCellInfo cell)
		{
			StringBuilder stringBuilder = new StringBuilder();
			if (_saro.DataOrientation == Orientation.Vertical)
			{
				int num = cell.Row.DataTable.Rows.IndexOf(cell.Row);
				stringBuilder.Append(_saro.DataProperty).Append("[").Append(num.ToString(CultureInfo.InvariantCulture))
					.Append("]");
				BindingDataColumn key = cell.Column as BindingDataColumn;
				if (!_saro.DataColumnMap.ContainsKey(key))
				{
					return null;
				}
				MMScrollAreaField mMScrollAreaField = _saro.DataColumnMap[key];
				if (mMScrollAreaField == null)
				{
					return null;
				}
				if (!string.IsNullOrEmpty(mMScrollAreaField.PropertyPath))
				{
					stringBuilder.Append(".").Append(mMScrollAreaField.PropertyPath);
				}
			}
			else
			{
				int num2 = _saro.DataGrid.DataSource.Columns.IndexOf(cell.Column);
				if (num2 == 0)
				{
					return null;
				}
				stringBuilder.Append(_saro.DataProperty).Append("[").Append((num2 - 1).ToString(CultureInfo.InvariantCulture))
					.Append("]");
				if (!(cell.Row is TransposedDataRow transposedDataRow))
				{
					return null;
				}
				if (!(transposedDataRow.Label is MMScrollAreaField mMScrollAreaField2))
				{
					return null;
				}
				if (!string.IsNullOrEmpty(mMScrollAreaField2.PropertyPath))
				{
					stringBuilder.Append(".").Append(mMScrollAreaField2.PropertyPath);
				}
			}
			return stringBuilder.ToString();
		}

