		public static int ParseHeaderLineCount(MemoryStream dataGridMetaData)
		{
			if (dataGridMetaData != null)
			{
				using StreamReader streamReader = new StreamReader(dataGridMetaData);
				string text = streamReader.ReadToEnd();
				if (!string.IsNullOrEmpty(text))
				{
					int num = text.IndexOf('=');
					if (num > 0)
					{
						string s = text.Substring(num + 1);
						int result = 0;
						if (int.TryParse(s, out result))
						{
							return result;
						}
					}
				}
			}
			return 0;
		}

		private void EnsureAppInfo()
		{
			_saro.Dispatcher.Invoke((Action)delegate
			{
				if (ViewModel != null)
				{
					_caseFullFileName = ViewModel.ResolveViewPropertyPath("ResolvedCxsProvider.Case.CaseFullFilePath").ToString();
					_applicationName = ViewModel.ResolveViewPropertyPath("ResolvedCxsProvider.Case.ApplicationName").ToString();
				}
			}, null);
		}

		private static string GetColumnHeader(List<DataCellInfo> selectedCells, CxvViewModel viewModel, MMScrollAreaMS saro)
		{
			if (selectedCells == null || selectedCells.Count == 0)
			{
				return null;
			}
			StringBuilder stringBuilder = new StringBuilder();
			List<MMScrollAreaField> selectedFields = GetSelectedFields(saro);
			GetLabelOfNonHeaderOnlyFields(stringBuilder, selectedFields, saro, viewModel, setHeaderLineCount: true);
			if (stringBuilder.ToString().Trim().Length > 0)
			{
				stringBuilder.Append("\r\n");
				return stringBuilder.ToString();
			}
			return string.Empty;
		}

		private static List<MMScrollAreaField> GetSelectedFields(MMScrollAreaMS saro)
		{
			List<MMScrollAreaField> list = new List<MMScrollAreaField>();
			if (saro.DataOrientation == Orientation.Horizontal)
			{
				DataRow[] array = saro.DataGrid.BoundRows.ToArray();
				foreach (DataRow selectedRow in saro.DataGrid.SelectedRows)
				{
					for (int i = 0; i < array.Count(); i++)
					{
						if (array[i] == selectedRow)
						{
							list.Add(saro.MMFields[i]);
							break;
						}
					}
				}
				if (saro.DataGrid.SelectedRows.Count() == saro.MMFields.Count)
				{
					return saro.MMFields.ToList();
				}
			}
			else
			{
				foreach (BindingDataColumn selectedColumn in saro.DataGrid.SelectedColumns)
				{
					if (saro.DataColumnMap.ContainsKey(selectedColumn))
					{
						MMScrollAreaField mMScrollAreaField = saro.DataColumnMap[selectedColumn];
						if (mMScrollAreaField != null)
						{
							list.Add(mMScrollAreaField);
						}
					}
				}
			}
			return list;
		}

		internal static void GetLabelOfNonHeaderOnlyFields(StringBuilder value, IEnumerable<MMScrollAreaField> selectedFields, MMScrollAreaMS saro, CxvViewModel viewModel, bool setHeaderLineCount)
		{
			if (value == null || selectedFields == null || saro == null || viewModel == null)
			{
				return;
			}
			bool flag = true;
			int maxRowIdInColumnHeader = GetMaxRowIdInColumnHeader(selectedFields);
			if (setHeaderLineCount)
			{
				saro.ClipboardDataObject._columnHeaderLineCount = maxRowIdInColumnHeader;
			}
			for (int i = 0; i < maxRowIdInColumnHeader; i++)
			{
				flag = true;
				StringBuilder stringBuilder = new StringBuilder();
				int num = -1;
				foreach (MMScrollAreaField selectedField in selectedFields)
				{
					if (flag)
					{
						flag = false;
					}
					else
					{
						stringBuilder.Append("\t");
						if (selectedField.DataColumn != null)
						{
							int num2 = selectedField.DataColumn.DisplayIndex - num;
							if (num2 > 1 && num >= 0)
							{
								for (int j = 0; j < num2 - 1; j++)
								{
									stringBuilder.Append("\t");
								}
							}
						}
					}
					if (selectedField.DataColumn != null)
					{
						num = selectedField.DataColumn.DisplayIndex;
					}
					if (selectedField.ColumnHeaderCopyValue != null)
					{
						if (i < selectedField.ColumnHeaderCopyValue.Count)
						{
							stringBuilder.Append(selectedField.ColumnHeaderCopyValue[i]);
						}
						continue;
					}
					if (!string.IsNullOrEmpty(selectedField.ColumnHeaderCopyValueBindingPath))
					{
						stringBuilder.Append(viewModel.ResolveViewPropertyPath(selectedField.ColumnHeaderCopyValueBindingPath));
						continue;
					}
					if (i == 0 && selectedField.LabelDockResolved == Dock.Top)
					{
						AppendLabel(stringBuilder, selectedField);
						continue;
					}
					int num3 = 0;
					if (!string.IsNullOrEmpty(selectedField.HeaderUnitsProperty))
					{
						string[] array = selectedField.HeaderUnitsProperty.Split(',');
						string[] array2 = null;
						if (!string.IsNullOrEmpty(selectedField.HeaderTypeProperty))
						{
							array2 = selectedField.HeaderTypeProperty.Split(',');
						}
						num3 = ((array2 != null) ? array2.Length : array.Length);
						int num4 = 0;
						num4 = ((selectedField.LabelDockResolved != Dock.Top) ? i : (i - 1));
						if (num3 > num4 && num4 >= 0)
						{
							AppendHeaderElementToCurrentRow(viewModel, stringBuilder, array, array2, num4);
							continue;
						}
					}
					if (selectedField.LabelDockResolved == Dock.Bottom && i == num3)
					{
						AppendLabel(stringBuilder, selectedField);
					}
				}
				if (i > 0)
				{
					value.Append(Environment.NewLine);
				}
				string text = stringBuilder.ToString();
				if (text.EndsWith("\t") && text.Length > 0)
				{
					text = text.Substring(0, text.Length - 1);
				}
				value.Append(text);
			}
		}

		private static int GetMaxRowIdInColumnHeader(IEnumerable<MMScrollAreaField> selectedFields)
		{
			int num = 1;
			foreach (MMScrollAreaField selectedField in selectedFields)
			{
				BindingOperations.GetBindingExpression(selectedField, MMScrollAreaField.ColumnHeaderCopyValueProperty)?.UpdateTarget();
				if (selectedField.ColumnHeaderCopyValue != null)
				{
					if (selectedField.ColumnHeaderCopyValue.Count > num)
					{
						num = selectedField.ColumnHeaderCopyValue.Count;
					}
				}
				else if (!string.IsNullOrEmpty(selectedField.HeaderUnitsProperty))
				{
					string[] array = selectedField.HeaderUnitsProperty.Split(',');
					if (array != null && array.Length + 1 > num)
					{
						num = array.Length + 1;
					}
				}
			}
			return num;
		}

		private static void AppendLabel(StringBuilder currentRow, MMScrollAreaField field)
		{
			string text = field.Label;
			if (field.LabelTextConverter != null)
			{
				object obj = field.LabelTextConverter.Convert(text, typeof(string), null, CultureInfo.CurrentCulture);
				if (obj != null)
				{
					text = obj.ToString();
				}
			}
			if (text != null)
			{
				if (text.Contains('\r') || text.Contains('\n'))
				{
					currentRow.Append("\"").Append(text).Append("\"");
				}
				else
				{
					currentRow.Append(text);
				}
			}
		}

		private static void AppendHeaderElementToCurrentRow(CxvViewModel viewModel, StringBuilder currentRow, string[] headers, string[] headertypes, int headerPropertyId)
		{
			string text = null;
			((headers.Length <= headerPropertyId) ? headers[headers.Length - 1] : headers[headerPropertyId]).Trim();
			string text2 = ((headertypes == null) ? "" : ((headertypes.Length > headerPropertyId) ? headertypes[headerPropertyId] : ""));
			text2 = text2.Trim().ToLowerInvariant();
			if (string.IsNullOrEmpty(text2))
			{
				text2 = "units";
			}
			switch (text2)
			{
			case "units":
				text = "Units";
				break;
			case "id":
			case "value":
			case "textuppercase":
				text = "Value";
				break;
			case "selecteditem":
				text = "SelectedItem";
				break;
			case "basis":
				text = "Basis";
				break;
			}
			object obj = viewModel.ResolveViewPropertyPath(headers[headerPropertyId].Trim() + "." + text);
			if (obj != null && !string.IsNullOrEmpty(obj.ToString()))
			{
				currentRow.Append(obj);
			}
		}

		internal static string GetValueFromSelection(List<DataCellInfo> selectedCells, CxvViewModel viewModel, bool includeColumnHeader, MMScrollAreaMS saro)
		{
			StringBuilder stringBuilder = new StringBuilder();
			BindingDataRow bindingDataRow = null;
			string text = "\r\n";
			string text2 = "\t";
			foreach (DataCellInfo selectedCell in selectedCells)
			{
				IDataCell data = selectedCell.Data;
				if (data == null)
				{
					continue;
				}
				BindingDataColumn key = data.Column as BindingDataColumn;
				BindingDataRow bindingDataRow2 = data.Row as BindingDataRow;
				object obj = data.Value;
				if (saro.DataColumnMap.ContainsKey(key) && saro.DataColumnMap[key] is MMScrollAreaValueField { TrimCopy: not false } && obj != null && obj.GetType() == typeof(string))
				{
					obj = obj.ToString().Trim();
				}
				string text3 = "";
				if (bindingDataRow2 == bindingDataRow)
				{
					text3 = text2;
				}
				else
				{
					bindingDataRow = bindingDataRow2;
					text3 = text;
				}
				stringBuilder.Append(text3);
				if (obj != null)
				{
					string text4 = obj.ToString();
					if (text4.Contains('\r') || text4.Contains('\n'))
					{
						text4 = "\"" + text4 + "\"";
					}
					stringBuilder.Append(text4);
				}
			}
			stringBuilder.Append(text);
			stringBuilder.Remove(0, text.Length);
			if (includeColumnHeader)
			{
				stringBuilder.Insert(0, GetColumnHeader(selectedCells, viewModel, saro));
			}
			if (stringBuilder.Length > 1 && stringBuilder[stringBuilder.Length - 2] == '\r' && stringBuilder[stringBuilder.Length - 1] == '\n')
			{
				stringBuilder.Remove(stringBuilder.Length - 2, 2);
			}
			return stringBuilder.ToString();
		}

		internal static Collection<string> GetMonikersFromSelection(List<DataCellInfo> selectedCells, CxvViewModel viewModel, GetPropPathDelegate getPropPath, bool ignoreWithoutAlternatePath, bool returnValueifMonikerMissing = false, bool indicateNonValueAttributes = false)
		{
			Collection<string> collection = new Collection<string>();
			foreach (DataCellInfo selectedCell in selectedCells)
			{
				if (ignoreWithoutAlternatePath)
				{
					object obj = viewModel.ResolveViewPropertyPath(getPropPath(selectedCell) + ".AlternatePath");
					if (obj == null || string.IsNullOrEmpty(obj.ToString()))
					{
						collection.Add(string.Empty);
						continue;
					}
				}
				object obj2 = viewModel.ResolveViewPropertyPath(getPropPath(selectedCell) + ".CxsItemMoniker");
				if (obj2 != null)
				{
					if (indicateNonValueAttributes)
					{
						if (viewModel.ResolveViewPropertyPath(getPropPath(selectedCell)) is CxvVariableData cxvVariableData && (cxvVariableData.ResolvedExposeAs == CxvVariableTypeCode.IdWithOptions || cxvVariableData.ResolvedExposeAs == CxvVariableTypeCode.Id))
						{
							collection.Add("ID:" + cxvVariableData.CxsItemMoniker);
						}
						else
						{
							collection.Add(obj2.ToString());
						}
					}
					else
					{
						collection.Add(obj2.ToString());
					}
					continue;
				}
				if (returnValueifMonikerMissing)
				{
					object obj3 = viewModel.ResolveViewPropertyPath(getPropPath(selectedCell));
					if (obj3 != null)
					{
						if (obj3 is CxvParameterPropertyData cxvParameterPropertyData)
						{
							collection.Add((cxvParameterPropertyData.Value != null) ? cxvParameterPropertyData.Value.ToString() : string.Empty);
							continue;
						}
					}
					else if (selectedCell.Data != null && selectedCell.Data.Value is string)
					{
						collection.Add((string)selectedCell.Data.Value);
						continue;
					}
				}
				object obj4 = viewModel.ResolveViewPropertyPath(getPropPath(selectedCell) + ".CxsItemMonikerCollection");
				if (obj4 != null)
				{
					foreach (string item in obj4 as Collection<string>)
					{
						collection.Add(item);
					}
				}
				else
				{
					collection.Add(string.Empty);
				}
			}
			return collection;
		}

		internal Collection<string> GetMonikersForCopyVariables(MMScrollAreaMS sa)
		{
			if (_saro == null)
			{
				_saro = sa;
			}
			List<DataCellInfo> list = new List<DataCellInfo>();
			_saro.DataGrid.SelectAll();
			if (sa.FirstLevelVectorData != null && sa.FirstLevelVectorData.IndexBasis is CxvChildCountIndexBasisData { HasProxyRow: not false })
			{
				foreach (DataCellInfo totalOrderedSelectedCell in _saro.DataGrid.TotalOrderedSelectedCells)
				{
					if (_saro.DataGrid.DataSource.Rows.IndexOf(totalOrderedSelectedCell.Row) != _saro.DataGrid.BoundRows.Count() - 1)
					{
						list.Add(totalOrderedSelectedCell);
					}
				}
			}
			else
			{
				list.AddRange(_saro.DataGrid.TotalOrderedSelectedCells);
			}
			_saro.DataGrid.DeselectAll();
			return GetMonikersFromSelection(list, ViewModel, GetPropPath, _saro.IgnoreMonikerWithoutAlternatePath);
		}

		internal bool PasteVariableDataToSelection(MMScrollAreaMS sa, IList<IList<string>> cbText, int topleftRowID, int topLeftColID, bool copyUnitless = false, bool updateFirstRowIndependent = true)
		{
			if (_saro == null)
			{
				_saro = sa;
			}
			CxsBatchRequestData cxsBatchRequestData = new CxsBatchRequestData();
			new CxsBatchRequestData();
			DataTable dataSource = sa.DataGrid.DataSource;
			int count = dataSource.Columns.Count;
			int count2 = dataSource.Rows.Count;
			List<DataCellInfo> list = new List<DataCellInfo>();
			bool flag = false;
			int num = topleftRowID - 1;
			int num2 = topLeftColID - 1;
			for (int i = 0; i < cbText.Count; i++)
			{
				num++;
				if (count2 < num + 1)
				{
					break;
				}
				num2 = topLeftColID - 1;
				for (int j = 0; j < cbText[i].Count; j++)
				{
					num2++;
					if (count < num2 + 1)
					{
						break;
					}
					if (sa.DataOrientation == Orientation.Horizontal)
					{
						if (i == 0 && j == 0)
						{
							int k = 0;
							flag = true;
							for (; k + topleftRowID < sa.MMFields.Count && k < cbText.Count; k++)
							{
								if (cbText[k][0] != sa.MMFields[k + topleftRowID].Label)
								{
									flag = false;
									break;
								}
							}
						}
						if (j == 0 && flag)
						{
							continue;
						}
						if (dataSource.Columns[num2].DisplayIndex == 0)
						{
							num2++;
							if (count < num + 1)
							{
								break;
							}
						}
					}
					DataCellInfo dataCellInfo = new DataCellInfo(dataSource.Rows[num], dataSource.Columns[num2]);
					list.Add(dataCellInfo);
					if (!(ViewModel.ResolveViewPropertyPath(GetPropPath(dataCellInfo)) is CxvVariableData cxvVariableData))
					{
						continue;
					}
					string dataAttributeResolved = ((CxvVariableProperty)cxvVariableData.Property).DataAttributeResolved;
					if (cxvVariableData.DataPath.Contains("VAL"))
					{
						if (double.TryParse(cbText[i][j].ToString(), out var result))
						{
							cxsBatchRequestData.AddRequest(cxvVariableData.DataPath, dataAttributeResolved, copyUnitless ? null : cxvVariableData.Units, result);
						}
						else
						{
							cxsBatchRequestData.AddRequest(cxvVariableData.DataPath, dataAttributeResolved, copyUnitless ? null : cxvVariableData.Units, cbText[i][j]);
						}
					}
					else
					{
						cxsBatchRequestData.AddRequest(cxvVariableData.DataPath, dataAttributeResolved, copyUnitless ? null : cxvVariableData.Units, cbText[i][j]);
					}
				}
				if (num == 0 && updateFirstRowIndependent && cxsBatchRequestData.RequestsCount > 0)
				{
					ViewModel.ResolvedCxsProvider.StartBatchPaste();
					ViewModel.ResolvedCxsProvider.BatchSet(cxsBatchRequestData);
					cxsBatchRequestData = new CxsBatchRequestData();
					sa.UpdateDataCache();
				}
			}
			if (cxsBatchRequestData.RequestsCount < 1)
			{
				return false;
			}
			ViewModel.ResolvedCxsProvider.StartBatchPaste();
			ViewModel.ResolvedCxsProvider.BatchSet(cxsBatchRequestData);
			ViewModel.ResolvedCxsProvider.EndBatchPaste();
			sa.DataGrid.DeselectAll();
			return true;
		}

		internal Collection<string> GetMonikersForSelectedCopyVariables(MMScrollAreaMS sa)
		{
			if (_saro == null)
			{
				_saro = sa;
			}
			List<DataCellInfo> list = new List<DataCellInfo>();
			list.AddRange(_saro.DataGrid.TotalOrderedSelectedCells);
			return GetMonikersFromSelection(list, ViewModel, GetPropPath, _saro.IgnoreMonikerWithoutAlternatePath, returnValueifMonikerMissing: true, indicateNonValueAttributes: true);
		}

