		internal void SetPlainTextAsCopyResult(GridControlCopyEventArgs e, List<IGridCellData> cellData, bool removeProxyRow = false)
		{
			StringBuilder stringBuilder = new StringBuilder();
			if (_saro.DataGrid.SelectedColumns.FirstOrDefault() != null && _saro.DataOrientation == Orientation.Vertical)
			{
				string text = GetColumnHeaderString(_saro, ViewModel);
				try
				{
					if (!string.IsNullOrWhiteSpace(text))
					{
						int num = text.IndexOf("\r\n");
						if (num > -1 && string.IsNullOrWhiteSpace(text.Substring(0, num)) && text.Length > num + 2)
						{
							text = text.Substring(num + 2);
						}
					}
				}
				catch (ArgumentOutOfRangeException)
				{
				}
				catch (NullReferenceException)
				{
				}
				catch (Exception)
				{
				}
				stringBuilder.Append(text);
			}
			_saro.DataGrid.ClipboardCopyMode = GridControlClipboardCopyMode.ExcludeHeader;
			stringBuilder.Append(e.GenerateTextToCopy(cellData, false, removeProxyRow));
			_plainTextAsCopyResult = stringBuilder.ToString();
		}

		internal static string GetColumnHeaderString(MMScrollAreaMS saro, CxvViewModel viewModel)
		{
			StringBuilder stringBuilder = new StringBuilder();
			List<MMScrollAreaField> selectionIncludedFields = GetSelectionIncludedFields(saro);
			GetLabelOfNonHeaderOnlyFields(stringBuilder, selectionIncludedFields, saro, viewModel, setHeaderLineCount: true);
			List<string> list = new List<string>();
			bool flag = false;
			foreach (MMScrollAreaField item in selectionIncludedFields)
			{
				if (string.IsNullOrEmpty(item.LabelForCopy))
				{
					list.Add("");
					continue;
				}
				list.Add(item.LabelForCopy);
				flag = true;
			}
			string text = "";
			if (flag && list.Count > 0)
			{
				text = string.Join("\t", list.ToArray());
			}
			if (text.Trim().Length > 0)
			{
				if (text.EndsWith("\t"))
				{
					text = text.Substring(0, text.Length - 1);
				}
				if (stringBuilder.ToString().Trim().Length > 0)
				{
					stringBuilder.Append("\r\n").Append(text);
				}
				else
				{
					stringBuilder.Append(text);
				}
			}
			if (stringBuilder.ToString().Trim().Length > 0)
			{
				stringBuilder.Append("\r\n");
				return stringBuilder.ToString();
			}
			return string.Empty;
		}

		private static List<MMScrollAreaField> GetSelectionIncludedFields(MMScrollAreaMS saro)
		{
			GridControl dataGrid = saro.DataGrid;
			List<DataColumn> orderedIncludedColumns = GridControlCopyEventArgs.GetOrderedIncludedColumns(dataGrid.DataSource, dataGrid.SelectedRows.ToList(), dataGrid.SelectedColumns.ToList(), dataGrid.SelectedCells.ToList());
			List<MMScrollAreaField> list = new List<MMScrollAreaField>();
			foreach (BindingDataColumn item in orderedIncludedColumns)
			{
				if (saro.DataColumnMap.ContainsKey(item))
				{
					MMScrollAreaField mMScrollAreaField = saro.DataColumnMap[item];
					if (mMScrollAreaField != null)
					{
						list.Add(mMScrollAreaField);
					}
				}
			}
			return list;
		}
	}
