		internal virtual bool IsAllSelected
		{
			get
			{
				if (DataGrid.FieldLayouts.Count > 0)
				{
					IEnumerable<Field> enumerable = DataGrid.DefaultFieldLayout.Fields.Where((Field f) => !f.IsExpandableResolved);
					if (enumerable != null)
					{
						foreach (Field item in enumerable)
						{
							if (!DataGrid.SelectedItems.Fields.Contains(item))
							{
								return false;
							}
						}
					}
					return true;
				}
				return false;
			}
		}

