		private void DataGrid_PreviewMouseDoubleClick(object sender, MouseButtonEventArgs e)
		{
			if (e == null || !(e.OriginalSource is DependencyObject descendant) || (Infragistics.Windows.Utilities.GetAncestorFromType(descendant, typeof(AesXamValueEdit), allowSubclassOfType: true) is AesXamValueEdit { SpinVisibility: Visibility.Visible } && Infragistics.Windows.Utilities.GetAncestorFromType(descendant, typeof(RepeatButton), allowSubclassOfType: true) is RepeatButton) || !(Infragistics.Windows.Utilities.GetAncestorFromType(descendant, typeof(DataRecordPresenter), allowSubclassOfType: true) is DataRecordPresenter { Record: not null } dataRecordPresenter) || dataRecordPresenter.Record.Index < 0)
			{
				return;
			}
			if (this.RowDoubleClick != null)
			{
				RowDoubleClickEventArgs e2 = new RowDoubleClickEventArgs
				{
					RowId = dataRecordPresenter.Record.Index
				};
				if (dataRecordPresenter.Record is DataRecord dataRecord)
				{
					e2.DataItem = dataRecord.DataItem;
				}
				this.RowDoubleClick(dataRecordPresenter, e2);
				e.Handled = true;
			}
			if (RowDoubleClickCommand != null && RowDoubleClickCommand.CanExecute(dataRecordPresenter.Record.Index))
			{
				RowDoubleClickCommand.Execute(dataRecordPresenter.Record.Index);
				e.Handled = true;
			}
		}

		protected bool ShouldSkipKey(Key key)
		{
			switch (key)
			{
			case Key.Pause:
			case Key.Capital:
			case Key.Space:
			case Key.Prior:
			case Key.Next:
			case Key.Snapshot:
			case Key.Insert:
			case Key.F1:
			case Key.F2:
			case Key.F3:
			case Key.F4:
			case Key.F5:
			case Key.F6:
			case Key.F7:
			case Key.F8:
			case Key.F9:
			case Key.F10:
			case Key.F11:
			case Key.F12:
			case Key.NumLock:
			case Key.Scroll:
			case Key.LeftShift:
			case Key.RightShift:
			case Key.LeftCtrl:
			case Key.RightCtrl:
			case Key.LeftAlt:
			case Key.RightAlt:
			case Key.System:
				return true;
			default:
				return false;
			}
		}

		protected virtual void CVP_PreviewMouseDown(CellValuePresenter cvp, MouseButtonEventArgs arg)
		{
			LastKeyPressed = null;
			if (cvp.Record.Index >= 0 && cvp.Field.Index >= 0)
			{
				PreviousActivePosition = CurrentActivePosition;
				CurrentActivePosition = new CellLocation(cvp.Record.Index, cvp.Field.ActualPosition.Column, ContainsHierachy ? (cvp.Record.ParentRecord as ExpandableFieldRecord) : null);
			}
			if (arg.ChangedButton != MouseButton.Left)
			{
				return;
			}
			if (arg.ClickCount == 2)
			{
				ValueEditor valueEditor = StartEditInActiveCell(clearText: false);
				if (valueEditor != null && valueEditor.IsInEditMode)
				{
					arg.Handled = true;
				}
			}
			try
			{
				if (!cvp.IsKeyboardFocusWithin)
				{
					cvp.Focus();
				}
			}
			catch (Exception)
			{
			}
		}

		private bool IsStrEqual(object o1, object o2)
		{
			if (o1 == null && o2 == null)
			{
				return true;
			}
			if (o1 == null || o2 == null)
			{
				return false;
			}
			if (o1.ToString() == o2.ToString())
			{
				return true;
			}
			return false;
		}

		private static bool IsDoubleEqual(ValueEditor editor, object o1, object o2)
		{
			if (o1 != null && o2 != null && editor is AesXamValueEdit aesXamValueEdit && (aesXamValueEdit.Mask == AesMaskOption.Percentage || aesXamValueEdit.Mask == AesMaskOption.Integer || aesXamValueEdit.Mask == AesMaskOption.Double) && double.TryParse(o1.ToString(), out var result) && double.TryParse(o2.ToString(), out var result2) && result == result2)
			{
				return true;
			}
			return false;
		}

		protected virtual void CVP_PreviewKeyDown(KeyEventArgs arg)
		{
			LastKeyPressed = arg.Key;
			if (arg == null || ShouldSkipKey(arg.Key))
			{
				return;
			}
			ValueEditor activeEditor = GetActiveEditor();
			bool flag = false;
			if (activeEditor == null || !activeEditor.IsInEditMode)
			{
				flag = true;
			}
			else if (arg.Key == Key.Return)
			{
				if (arg.OriginalSource != null && arg.OriginalSource.GetType() == typeof(ComboBoxItem) && activeEditor is AesXamComboEdit)
				{
					flag = false;
				}
				else
				{
					object value = activeEditor.Value;
					activeEditor.EndEditMode(acceptChanges: true, force: false);
					if (IsStrEqual(value, activeEditor.Value))
					{
						flag = true;
					}
					else if (IsDoubleEqual(activeEditor, value, activeEditor.Value))
					{
						flag = true;
					}
				}
			}
			else if (arg.Key == Key.Tab)
			{
				if (activeEditor is AesXamValueEdit || activeEditor is AesXamComboEdit)
				{
					object value2 = activeEditor.Value;
					activeEditor.EndEditMode(acceptChanges: true, force: false);
					if (IsStrEqual(value2, activeEditor.Value))
					{
						flag = true;
					}
					else if (IsDoubleEqual(activeEditor, value2, activeEditor.Value))
					{
						flag = true;
					}
					else
					{
						arg.Handled = true;
					}
				}
			}
			else if (arg.Key == Key.Escape)
			{
				activeEditor.EndEditMode(acceptChanges: false, force: true);
			}
			else if (arg.Key == Key.Delete)
			{
				flag = true;
			}
			if (flag)
			{
				CellValuePresenter cellValuePresenter = arg.Source as CellValuePresenter;
				bool flag2 = false;
				if (cellValuePresenter != null && Infragistics.Windows.Utilities.GetAncestorFromType(cellValuePresenter, typeof(MMHorizontalListEdit), allowSubclassOfType: true) is MMHorizontalListEdit)
				{
					flag2 = true;
				}
				bool handled = arg.Handled;
				switch (arg.Key)
				{
				case Key.Home:
					if ((Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control)
					{
						DataGrid.ExecuteCommand(DataPresenterCommands.CellFirstOverall);
					}
					else if ((Keyboard.Modifiers & ModifierKeys.Control) == 0)
					{
						DataGrid.ExecuteCommand(DataPresenterCommands.CellFirstInRecord);
					}
					handled = true;
					break;
				case Key.End:
					if ((Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control)
					{
						DataGrid.ExecuteCommand(DataPresenterCommands.CellLastOverall);
					}
					else if ((Keyboard.Modifiers & ModifierKeys.Control) == 0)
					{
						DataGrid.ExecuteCommand(DataPresenterCommands.CellLastInRecord);
					}
					handled = true;
					break;
				case Key.Left:
					DataGrid.ExecuteCommand(DataPresenterCommands.CellLeft);
					handled = true;
					break;
				case Key.Right:
					DataGrid.ExecuteCommand(DataPresenterCommands.CellRight);
					handled = true;
					break;
				case Key.Up:
					if ((Keyboard.Modifiers & ModifierKeys.Control) == 0)
					{
						DataGrid.ExecuteCommand(DataPresenterCommands.CellAbove);
					}
					else if ((Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control)
					{
						if (activeEditor is AesXamValueEdit { SpinVisibility: Visibility.Visible } aesXamValueEdit)
						{
							AesControls.SpinUpCommand.Execute(null, aesXamValueEdit);
						}
						else if (activeEditor is AesXamComboEdit aesXamComboEdit)
						{
							aesXamComboEdit.StartEditMode();
						}
					}
					handled = true;
					break;
				case Key.Down:
					if ((Keyboard.Modifiers & ModifierKeys.Control) == 0)
					{
						DataGrid.ExecuteCommand(DataPresenterCommands.CellBelow);
					}
					else if ((Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control)
					{
						if (activeEditor is AesXamValueEdit { SpinVisibility: Visibility.Visible } aesXamValueEdit2)
						{
							AesControls.SpinDownCommand.Execute(null, aesXamValueEdit2);
						}
						else if (activeEditor is AesXamComboEdit aesXamComboEdit2)
						{
							aesXamComboEdit2.StartEditMode();
						}
					}
					handled = true;
					break;
				case Key.Return:
					if ((Keyboard.Modifiers & ModifierKeys.Shift) == ModifierKeys.Shift)
					{
						MoveToNextCell(1);
					}
					else
					{
						MoveToNextCell(3);
					}
					break;
				case Key.Tab:
					if (!flag2 && (Keyboard.Modifiers & ModifierKeys.Control) != ModifierKeys.Control)
					{
						handled = (((Keyboard.Modifiers & ModifierKeys.Shift) != ModifierKeys.Shift) ? MoveToNextCell(2) : MoveToNextCell(0));
						if (Keyboard.FocusedElement is AesXamValueEdit)
						{
							(Keyboard.FocusedElement as AesXamValueEdit).StartEditMode();
						}
					}
					else if (flag2 && cellValuePresenter.Record.Index < 0)
					{
						handled = true;
					}
					break;
				case Key.Delete:
					ClearSelectedCells(cellOnly: false);
					break;
				case Key.A:
					if ((Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control)
					{
						DoSelectAll();
						handled = true;
					}
					else if (DataGrid.ActiveCell != null && !DataGrid.ActiveCell.IsInEditMode)
					{
						StartEditInActiveCell(clearText: true);
					}
					break;
				default:
					if (DataGrid.ActiveCell != null && !DataGrid.ActiveCell.IsInEditMode && char.IsLetterOrDigit(arg.Key.ToString(), 0) && arg.Key != Key.Escape)
					{
						StartEditInActiveCell(clearText: true);
					}
					break;
				}
				arg.Handled = handled;
			}
			if (this is IManualLayout manualLayout)
			{
				ValueEditor activeEditor2 = GetActiveEditor();
				if (activeEditor2 != activeEditor)
				{
					manualLayout.ActiveEditor = activeEditor2;
				}
			}
		}

