		private static void CanCutCommandExecute(object sender, CanExecuteRoutedEventArgs e)
		{
			if (e.Command == ApplicationCommands.Cut && sender is FrameworkElement descendant && Infragistics.Windows.Utilities.GetAncestorFromType(descendant, typeof(XamDataGrid), allowSubclassOfType: true) is XamDataGrid parent)
			{
				DataRecordPresenter descendantFromType = Infragistics.Windows.Utilities.GetDescendantFromType<DataRecordPresenter>(parent, allowSubclassOfType: true, null);
				if (descendantFromType != null && descendantFromType.ExpansionIndicatorVisibility == Visibility.Visible)
