		protected virtual void DataGrid_Loaded(object sender, RoutedEventArgs e)
		{
			if (!_isDataGridLoaded)
			{
				SuppressPreviewGotKeyboardFocus = false;
				_isDataGridLoaded = true;
				SetIsColumnHeaderVisible();
			}
			if (Infragistics.Windows.Utilities.GetAncestorFromType(this, typeof(MMTabPage), allowSubclassOfType: true) is MMTabPage mMTabPage && !mMTabPage.LayoutSettingControls.Contains(this))
			{
				mMTabPage.LayoutSettingControls.Add(this);
			}
		}

		private void DataGrid_GotKeyboardFocus(object sender, KeyboardFocusChangedEventArgs e)
		{
			if (!IsMMEnabled)
			{
				return;
			}
			ClearSelectionOfOtherScrollArea();
			int isTabbing = MMNavigationHelper.GetIsTabbing(this);
			if (!SuppressPreviewGotKeyboardFocus && e.OldFocus != DataGrid && e.NewFocus == DataGrid && DataGrid.Records.Count > 0 && DataGrid.DefaultFieldLayout.Fields.Count > 0 && ((DataGrid.ActiveCell == null && DataGrid.SelectedItems.Cells.Count == 0 && DataGrid.SelectedItems.Records.Count == 0 && DataGrid.SelectedItems.Fields.Count == 0) || isTabbing != 0) && isTabbing != 2)
			{
				base.Dispatcher.BeginInvoke(DispatcherPriority.Loaded, (Action)delegate
				{
					XamDataGrid dataGrid = DataGrid;
					bool flag = dataGrid != null && dataGrid.SelectedItems?.Records?.Count > 0;
					if (DataGrid.ActiveCell == null && !flag)
					{
						SetInitialCellFocus();
					}
				});
				if (isTabbing == 3)
				{
					if (DataGrid.ActiveCell != null && (GetCellStatus(DataGrid.ActiveCell, "IsCalculated") ?? false))
					{
						DataGrid.ActiveCell = null;
						ClearSelection();
					}
					else if (Keyboard.FocusedElement is AesXamValueEdit)
					{
						(Keyboard.FocusedElement as AesXamValueEdit).StartEditMode();
					}
				}
				else
				{
					if (Keyboard.FocusedElement is AesXamValueEdit)
					{
						(Keyboard.FocusedElement as AesXamValueEdit).StartEditMode();
					}
					if (Keyboard.FocusedElement is AesXamComboEdit)
					{
						(Keyboard.FocusedElement as AesXamComboEdit).StartEditMode();
					}
				}
			}
			if (isTabbing != 0 && DataGrid.Records.Count == 0 && DataGrid.DataSource == null)
			{
				_retryFirstCell = 0;
				base.Dispatcher.BeginInvoke(new Action(OnRetryMoveTo), DispatcherPriority.DataBind);
			}
			OnScriptingVariablePathDisplayed(GetActiveScriptingPath());
		}

		private void ClearSelectionOfOtherScrollArea()
		{
			if (!(Infragistics.Windows.Utilities.GetAncestorFromType(this, typeof(MMTabPage), allowSubclassOfType: true) is MMTabPage { ScrollAreas: not null } mMTabPage))
			{
				return;
			}
			foreach (IMMScrollAreaPlot scrollArea in mMTabPage.ScrollAreas)
			{
				if (scrollArea != this)
				{
					scrollArea.ClearSelection();
				}
			}
		}

		private void SetInitialCellFocus()
		{
			if (DataGrid.Records.Count > 0)
			{
				CellCollection cells = (DataGrid.Records[0] as DataRecord).Cells;
				if (cells.Count > 0)
				{
					DataGrid.ActiveCell = cells[0];
					MoveToNextCell(2, startWithCurrentActiveCell: true);
				}
			}
		}

		private void OnRetryMoveTo()
		{
			if (DataGrid.Records.Count == 0 && DataGrid.DataSource == null && _retryFirstCell < 4)
			{
				_retryFirstCell++;
				base.Dispatcher.BeginInvoke(new Action(OnRetryMoveTo), DispatcherPriority.DataBind);
			}
			else if (DataGrid.Records.Count > 0 && DataGrid.DefaultFieldLayout.Fields.Count > 0)
			{
				SetInitialCellFocus();
			}
		}

