				CurrentActivePosition = new CellLocation(e.Cell.Record.Index, e.Cell.Field.ActualPosition.Column, ContainsHierachy ? (e.Cell.Record.ParentRecord as ExpandableFieldRecord) : null);
				DataGrid.SelectedItems.Fields.Clear();
				DataGrid.SelectedItems.Records.Clear();
			}
		}

		protected bool ShouldCVPRespondKeyDown(KeyEventArgs e)
		{
			if (e.Key == Key.Delete && (e.OriginalSource.GetType() == typeof(ComboBox) || e.OriginalSource.GetType() == typeof(ComboBoxItem)))
			{
				return true;
			}
			if (e == null || ShouldSkipKey(e.Key) || IsBoundToPlainDataSource)
			{
				return false;
			}
			if (Infragistics.Windows.Utilities.GetAncestorFromType(e.OriginalSource as Control, typeof(MMFortranLine), allowSubclassOfType: true) != null)
			{
				return false;
			}
			ValueEditor activeEditor = GetActiveEditor();
			bool result = true;
			if (activeEditor != null && activeEditor.IsInEditMode)
			{
				if (e.Key == Key.Tab || e.Key == Key.Return)
				{
					if (activeEditor.InvalidValueErrorInfo != null && activeEditor.InvalidValueErrorInfo.Exception != null)
					{
						result = false;
					}
				}
				else if (e.Key == Key.Escape)
				{
					activeEditor.EndEditMode(acceptChanges: false, force: true);
					result = false;
				}
				else
				{
					result = false;
				}
			}
			return result;
		}

		protected bool ShouldDataGridRespondKeyDown(KeyEventArgs e)
		{
			if (e == null || e.OriginalSource.GetType() == typeof(ComboBoxItem) || ShouldSkipKey(e.Key) || e.OriginalSource.GetType() == typeof(CellValuePresenter) || IsBoundToPlainDataSource)
			{
				return false;
			}
			if (Infragistics.Windows.Utilities.GetAncestorFromType(e.OriginalSource as Control, typeof(MMFortranLine), allowSubclassOfType: true) != null || Infragistics.Windows.Utilities.GetAncestorFromType(e.OriginalSource as Control, typeof(MMComboEdit), allowSubclassOfType: true) != null || Infragistics.Windows.Utilities.GetAncestorFromType(e.OriginalSource as Control, typeof(MMValueEdit), allowSubclassOfType: true) != null)
			{
				return false;
			}
			ValueEditor activeEditor = GetActiveEditor();
			if (activeEditor != null && activeEditor.IsInEditMode)
			{
				if (e.Key == Key.Return && (activeEditor.InvalidValueErrorInfo == null || activeEditor.InvalidValueErrorInfo.Exception == null) && GetType() != typeof(MMScrollArea) && GetType() != typeof(MMScrollAreaManualLayout))
				{
					activeEditor.EndEditMode(acceptChanges: true, force: false);
				}
				return false;
			}
			if (e.OriginalSource is FrameworkElement descendant && Infragistics.Windows.Utilities.GetAncestorFromType(descendant, typeof(LabelPresenter), allowSubclassOfType: false) != null)
			{
				return false;
			}
			return true;
		}

