		private static void OnMMScrollAreaBasePreviewMouseMove(object sender, MouseEventArgs arg)
		{
			if (_mouseDownCVP != null)
			{
				Vector vector = arg.GetPosition(_mouseDownCVP) - dragStartPoint;
				if ((Math.Abs(vector.X) > SystemParameters.MinimumHorizontalDragDistance || Math.Abs(vector.Y) > SystemParameters.MinimumVerticalDragDistance) && sender is MMScrollAreaBase sa)
				{
					DoDrag(sa, arg);
				}
			}
		}

		private static void DoDrag(MMScrollAreaBase sa, RoutedEventArgs e)
		{
			if (isDraging)
			{
				return;
			}
			isDraging = true;
			DataObject dataObject = new DataObject();
			using (DataObjectLateGen dataObjectLateGen = new DataObjectLateGen())
			{
				dataObjectLateGen.SetData(typeof(MMScrollAreaBase), sa);
				MemoryStream asiFileXml = ClipboardHelper.GetAsiFileXml(dataObjectLateGen.CaseFullFileName, dataObjectLateGen.ApplicationName);
				if (asiFileXml != null)
				{
					dataObject.SetData(DataFormats.GetDataFormat("ASI File Format").Name, asiFileXml);
				}
				string asiSelectionXml = ClipboardHelper.GetAsiSelectionXml(dataObjectLateGen.Monikers, dataObjectLateGen.CaseFullFileName, dataObjectLateGen.ApplicationName);
				if (asiSelectionXml != null)
				{
					dataObject.SetData(DataFormats.GetDataFormat("ASI Format").Name, asiSelectionXml);
				}
				dataObject.SetData(DataFormats.Text, dataObjectLateGen.Value);
			}
			DragDrop.DoDragDrop(sa, dataObject, DragDropEffects.Copy);
			_mouseDownCVP = null;
			isDraging = false;
		}

		internal void CollectSelectedCellFromCells(List<MMScrollAreaSelectedCell> list)
		{
			foreach (Cell cell in DataGrid.SelectedItems.Cells)
			{
				if (cell.Field.VisibilityResolved == Visibility.Visible && cell.Record.VisibilityResolved == Visibility.Visible && cell.Field.CellContentAlignmentResolved != CellContentAlignment.LabelOnly)
				{
					list.Add(new MMScrollAreaSelectedCell
					{
						Field = GetLinkedMMField(cell.Field),
						Record = new MMScrollAreaSelectedRecord
						{
							Index = cell.Record.DataItemIndex,
							DisplayIndex = cell.Record.VisibleIndex
						}
					});
				}
			}
		}

		internal void CollectSelectedCellFromRecords(List<MMScrollAreaSelectedCell> list)
		{
			foreach (Record record in DataGrid.SelectedItems.Records)
			{
				if (record.VisibilityResolved != Visibility.Visible)
				{
					continue;
				}
				foreach (Field field in DataGrid.DefaultFieldLayout.Fields)
				{
					if (field.VisibilityResolved == Visibility.Visible && field.CellContentAlignmentResolved != CellContentAlignment.LabelOnly)
					{
						MMScrollAreaSelectedCell item = new MMScrollAreaSelectedCell
						{
							Field = GetLinkedMMField(field),
							Record = new MMScrollAreaSelectedRecord
							{
								Index = (record as DataRecord).DataItemIndex,
								DisplayIndex = (record as DataRecord).VisibleIndex
							}
						};
						if (!list.Contains(item))
						{
							list.Add(item);
						}
					}
				}
			}
		}

		internal void CollectSelectedCellFromFields(List<MMScrollAreaSelectedCell> list)
		{
			foreach (Field field in DataGrid.SelectedItems.Fields)
			{
				if (field.VisibilityResolved != Visibility.Visible || field.CellContentAlignmentResolved == CellContentAlignment.LabelOnly)
				{
					continue;
				}
				MMScrollAreaField linkedMMField = GetLinkedMMField(field);
				foreach (Record item2 in (IEnumerable<Record>)DataGrid.Records)
				{
					if (item2.VisibilityResolved == Visibility.Visible)
					{
						MMScrollAreaSelectedCell item = new MMScrollAreaSelectedCell
						{
							Field = linkedMMField,
							Record = new MMScrollAreaSelectedRecord
							{
								Index = (item2 as DataRecord).DataItemIndex,
								DisplayIndex = (item2 as DataRecord).VisibleIndex
							}
						};
						if (!list.Contains(item))
						{
							list.Add(item);
						}
					}
				}
			}
		}

