		internal void SetSelection(Cell editingCell)
		{
			if (editingCell == null)
			{
				SelectedFieldsCount = Selection.SelectedFieldsCount;
			}
			else
			{
				SelectedFieldsCount = 1;
			}
			_suppressSetSelectedRow = true;
			if (SelectedRowIndexes == null)
			{
				_suppressSetSelectedRow = true;
				SelectedRowIndexes = new ObservableCollection<int>();
				_suppressSetSelectedRow = false;
			}
			else
			{
				SelectedRowIndexes.Clear();
			}
			if (editingCell == null)
			{
				foreach (MMScrollAreaSelectedRecord allSelectedRecord in Selection.AllSelectedRecords)
				{
					if (allSelectedRecord.Index >= 0)
					{
						SelectedRowIndexes.Add(allSelectedRecord.Index);
					}
				}
			}
			else
			{
				SelectedRowIndexes.Add(DataGrid.RecordManager.Unsorted.IndexOf(editingCell.Record));
			}
			AllSelectedRecordsCount = SelectedRowIndexes.Count;
			_suppressSetSelectedRow = false;
			if (DataGrid.DefaultFieldLayout != null && ShouldHighlightHeaderOnSelection)
			{
				foreach (Field field in DataGrid.DefaultFieldLayout.Fields)
				{
					if (field.IsSelected)
					{
						field.SetValue(IsFieldCellSelectedProperty, true);
					}
					else
					{
						field.ClearValue(IsFieldCellSelectedProperty);
					}
				}
			}
			_suppressSetSelectedField = true;
			if (SelectedFieldIds == null)
			{
				_suppressSetSelectedField = true;
				SelectedFieldIds = new ObservableCollection<int>();
				_suppressSetSelectedField = false;
			}
			else
			{
				SelectedFieldIds.Clear();
			}
			if (ShouldHighlightHeaderOnSelection)
			{
				if (editingCell == null)
				{
					foreach (Field allSelectedField in Selection.AllSelectedFields)
					{
						SelectedFieldIds.Add(allSelectedField.Index);
						allSelectedField.SetValue(IsFieldCellSelectedProperty, true);
					}
				}
				else
				{
					SelectedFieldIds.Add(editingCell.Field.Index);
					editingCell.Field.SetValue(IsFieldCellSelectedProperty, true);
				}
			}
			_suppressSetSelectedField = false;
			EnsureRecordsInView();
			RefreshRecordSelectors(isClearingAllHighlight: false);
		}

