		protected void SetSelectedRow()
		{
			if (_suppressSetSelectedRow || SelectedRowIndexes == null || SelectedRowIndexes.Count == 0)
			{
				return;
			}
			_suppressSetSelectedRow = true;
			List<int> list = SelectedRowIndexes.ToList();
			foreach (Record item in (IEnumerable<Record>)DataGrid.Records)
			{
				item.IsSelected = false;
				item.IsActive = false;
			}
			foreach (int item2 in list)
			{
				if (item2 < DataGrid.Records.Count)
				{
					DataGrid.RecordManager.Sorted[item2].IsSelected = true;
					DataGrid.RecordManager.Sorted[item2].IsActive = true;
				}
			}
			try
			{
				if (list.Count > 0 && list[0] < DataGrid.Records.Count)
				{
					DataGrid.BringRecordIntoView(DataGrid.RecordManager.Sorted[list[0]]);
				}
			}
			catch (Exception)
			{
			}
			_suppressSetSelectedRow = false;
			RefreshRecordSelectors(isClearingAllHighlight: false);
		}

