		private void SetSelectedField()
		{
			if (_suppressSetSelectedField || SelectedFieldIds == null || SelectedFieldIds.Count == 0 || DataGrid.DefaultFieldLayout == null)
			{
				return;
			}
			_suppressSetSelectedField = true;
			List<int> list = SelectedFieldIds.ToList();
			ClearSelection();
			foreach (int item in list)
			{
				if (item < DataGrid.DefaultFieldLayout.Fields.Count)
				{
					DataGrid.DefaultFieldLayout.Fields[item].IsSelected = true;
				}
			}
			if (list.Count > 0 && list[0] < DataGrid.DefaultFieldLayout.Fields.Count && DataGrid.Records.Count > 0)
			{
				DataGrid.BringCellIntoView((DataGrid.Records[0] as DataRecord).Cells[list[0]]);
			}
			_suppressSetSelectedField = false;
		}

		protected virtual void RestoreActivePositionAfterReset(bool shouldStartEditMode)
		{
			if (!_isJustReset || !IsMMEnabled || DataGrid.SelectedItems.Records.Count != 0 || DataGrid.SelectedItems.Fields.Count != 0)
			{
				return;
			}
			int num = Math.Min(DataGrid.Records.Count - 1, CurrentActivePosition.RecordId);
			int num2 = Math.Min(DataGrid.DefaultFieldLayout.Fields.Count - 1, CurrentActivePosition.FieldId);
			if (num >= 0 && num2 >= 0)
			{
				try
				{
					int targetRecordId = num;
					int targetFieldId = num2;
					if (LastKeyPressed == Key.Return && num < DataGrid.Records.Count - 1)
					{
						targetRecordId++;
					}
					else if (LastKeyPressed == Key.Tab)
					{
						if (num2 < DataGrid.DefaultFieldLayout.Fields.Count - 1)
						{
							targetFieldId++;
						}
						else
						{
							targetFieldId = 0;
							targetRecordId++;
						}
					}
					LastKeyPressed = null;
					int actualFieldId = targetFieldId;
					Cell cell = (DataGrid.Records[targetRecordId] as DataRecord).Cells.Where((Cell cell2) => cell2.Field.ActualPosition.Column == targetFieldId).FirstOrDefault();
					if (cell != null)
					{
						actualFieldId = cell.Field.Index;
					}
					base.Dispatcher.BeginInvoke(DispatcherPriority.Input, (Action)delegate
					{
						if (targetRecordId < DataGrid.Records.Count && DataGrid.Records[targetRecordId] is DataRecord dataRecord && actualFieldId < dataRecord.Cells.Count)
						{
							DataGrid.ActiveCell = dataRecord.Cells[actualFieldId];
							if (DataGrid.ActiveCell != null)
							{
								DataGrid.ActiveCell.IsActive = true;
							}
						}
					});
				}
				catch (Exception)
				{
				}
			}
			if (shouldStartEditMode)
			{
				StartEditInActiveCell(clearText: false);
			}
			_isJustReset = false;
		}

