		protected virtual void DoClearCell(Cell cell)
		{
			if (cell == null)
			{
				return;
			}
			CellValuePresenter cellValuePresenter = CellValuePresenter.FromCell(cell);
			if (cellValuePresenter == null)
			{
				DataGrid.BringCellIntoView(cell);
				cellValuePresenter = CellValuePresenter.FromCell(cell);
			}
			if (cellValuePresenter != null && IsCellEditable(cellValuePresenter) && MMScrollAreaCommand.IsCellClearable(cellValuePresenter) && cellValuePresenter.Editor != null && cell.Value != null)
			{
				bool flag = false;
				if (cellValuePresenter.Editor is AesXamValueEdit { Variable: CxvVariableData { IsEntered: not null, IsEntered: var isEntered } } && !isEntered.Value)
				{
					flag = true;
				}
				if (!flag)
				{
					cellValuePresenter.Value = null;
				}
			}
		}

		internal virtual void ClearSelectedCells(bool cellOnly)
		{
			CxsDataProvider resolvedCxsProvider = (base.DataContext as CxvViewModel).ResolvedCxsProvider;
			resolvedCxsProvider?.SuspendNotifications();
			ValueEditor activeEditor = GetActiveEditor();
			if (activeEditor != null && activeEditor.IsInEditMode && !(activeEditor is AesXamComboEdit))
			{
				return;
			}
			try
			{
				if (DataGrid.SelectedItems.Cells.Count == 0 && DataGrid.SelectedItems.Fields.Count == 0 && DataGrid.SelectedItems.Records.Count == 0 && DataGrid.ActiveCell != null)
				{
					DoClearCell(DataGrid.ActiveCell);
					return;
				}
				List<Cell> list = new List<Cell>();
				foreach (Cell cell in DataGrid.SelectedItems.Cells)
				{
					list.Add(cell);
				}
				if (!cellOnly)
				{
					foreach (Field field in DataGrid.SelectedItems.Fields)
					{
						foreach (DataRecord item in (IEnumerable<Record>)DataGrid.Records)
						{
							if (item.Cells.Count > field.Index && !list.Contains(item.Cells[field]))
							{
								list.Add(item.Cells[field]);
							}
						}
					}
					foreach (DataRecord record in DataGrid.SelectedItems.Records)
					{
						foreach (Field field2 in DataGrid.DefaultFieldLayout.Fields)
						{
							if (record.Cells.Count > field2.Index && !list.Contains(record.Cells[field2]))
							{
								list.Add(record.Cells[field2]);
							}
						}
					}
				}
				foreach (Cell item2 in list.OrderByDescending((Cell cell) => cell, new CellComparer()))
				{
					DoClearCell(item2);
				}
			}
			catch (Exception)
			{
			}
			finally
			{
				resolvedCxsProvider?.ResumeNotifications();
			}
		}

		internal static bool IsCellEditable(CellValuePresenter cvp)
		{
			if (cvp == null)
			{
				return false;
			}
			bool flag = false;
			if (cvp.Editor != null)
			{
				if (cvp.Editor is AesXamValueEdit aesXamValueEdit)
				{
					flag = aesXamValueEdit.IsMMEnabled && !aesXamValueEdit.IsReadOnly;
				}
				else if (cvp.Editor is AesXamCheckEdit aesXamCheckEdit)
				{
					flag = aesXamCheckEdit.IsEnabled && !aesXamCheckEdit.IsReadOnly;
				}
				else if (cvp.Editor is AesXamComboEdit aesXamComboEdit)
				{
					flag = aesXamComboEdit.IsMMEnabled && !aesXamComboEdit.IsReadOnly && aesXamComboEdit.VariableDataMember != "Basis" && aesXamComboEdit.VariableDataMember != "Units";
				}
			}
			else if (Infragistics.Windows.Utilities.GetDescendantFromType(cvp, typeof(AesVariableControlBase), allowSubclassOfType: true) is AesVariableControlBase aesVariableControlBase)
			{
				if (aesVariableControlBase is MMCmdButton)
				{
					flag = false;
				}
				else if (aesVariableControlBase.IsEnabled && !aesVariableControlBase.IsReadOnly)
				{
					flag = true;
				}
				if (flag && aesVariableControlBase is AesComboEdit aesComboEdit && (aesComboEdit.VariableDataMember == "Basis" || aesComboEdit.VariableDataMember == "Units"))
				{
					flag = false;
				}
			}
			return flag;
		}

		private static bool IsNullOrTrue(bool? val)
		{
			if (val.HasValue)
			{
				if (val.HasValue)
				{
					return val.Value;
				}
				return false;
			}
			return true;
		}

		private static bool IsNullOrFalse(bool? val)
		{
			if (val.HasValue)
			{
				if (val.HasValue)
				{
					return !val.Value;
				}
				return false;
			}
			return true;
		}

		private static bool IsFalse(bool? val)
		{
			if (val.HasValue)
			{
				return !val.Value;
			}
			return false;
		}

		protected virtual object GetCellDataSource(Cell cell)
		{
			if (cell == null)
			{
