			}
			if (!(cell.Record.DataItem is MMScrollAreaRecord mMScrollAreaRecord))
			{
				return null;
			}
			if (cell.Field.Index >= mMScrollAreaRecord.Fields.Count)
			{
				return null;
			}
			return mMScrollAreaRecord.Fields[cell.Field.Index].Data;
		}

