		protected virtual bool MoveToNextCell(int direction, bool startWithCurrentActiveCell = false)
		{
			if (doNotMoveCell)
			{
				return false;
			}
			if ((AllowEdit.HasValue && !AllowEdit.Value) || !IsMMEnabled)
			{
				return false;
			}
			if (DataGrid.ActiveCell == null)
			{
				return false;
			}
			Cell activeCell = DataGrid.ActiveCell;
			activeCell.EndEditMode();
			RecordCollectionBase parentCollection = activeCell.Record.ParentCollection;
			int rowId = activeCell.Record.Index;
			int colId = ((DataOrientation == Orientation.Vertical) ? activeCell.Field.ActualPosition.Column : activeCell.Field.ActualPosition.Row);
			if (rowId < 0 || colId < 0)
			{
				return false;
			}
			if (base.DataContext is MMViewModel mMViewModel)
			{
				mMViewModel.ResolvedCxsProvider.UpdateDataCache();
			}
			List<Field> list = (from dr in activeCell.Field.Owner.Fields
				where dr.Visibility == Visibility.Visible && dr.CellContentAlignmentResolved != CellContentAlignment.LabelOnly
				orderby dr.ActualPosition.Column
				select dr).ToList();
			bool isFinished = false;
			bool flag = false;
			Cell cell = null;
			bool flag2 = true;
			do
			{
				bool flag3 = false;
				if (flag2 && startWithCurrentActiveCell)
				{
					flag2 = false;
					flag3 = true;
				}
				else
				{
					switch (direction)
					{
					case 0:
						flag3 = ((DataOrientation != Orientation.Vertical) ? FindCellUp(ref rowId, ref colId, ref isFinished, list, parentCollection) : FindCellLeft(ref rowId, ref colId, ref isFinished, list));
						break;
					case 1:
						flag3 = ((DataOrientation != Orientation.Vertical) ? FindCellLeft(ref rowId, ref colId, ref isFinished, list) : FindCellUp(ref rowId, ref colId, ref isFinished, list, parentCollection));
						break;
					case 2:
						flag3 = ((DataOrientation != Orientation.Vertical) ? FindCellDown(ref rowId, ref colId, ref isFinished, list, parentCollection) : FindCellRight(ref rowId, ref colId, ref isFinished, list, parentCollection));
						break;
					case 3:
						flag3 = ((DataOrientation != Orientation.Vertical) ? FindCellRight(ref rowId, ref colId, ref isFinished, list, parentCollection) : FindCellDown(ref rowId, ref colId, ref isFinished, list, parentCollection));
						break;
					}
				}
				if (!flag3)
				{
					break;
				}
				DataRecord dataRecord = parentCollection[rowId] as DataRecord;
				if (colId < 0 || colId >= list.Count || list[colId].Index < 0 || list[colId].Index >= dataRecord.Cells.Count)
				{
					continue;
				}
				cell = dataRecord.Cells[list[colId].Index];
				if (CellValuePresenter.FromCell(cell) == null)
				{
					DataGrid.BringCellIntoView(cell);
					DataGrid.UpdateLayout();
				}
				if (ContainsHierachy)
				{
					flag = true;
					break;
				}
				object cellDataSource = GetCellDataSource(cell);
				if (cellDataSource == null || cellDataSource is CxvCmdButtonPropertyData)
				{
					cell = null;
					continue;
				}
				if (NotComboOrHasOptions(cell) && (!IsFalse(GetCellStatus(cell, "IsCalculated")) || (IsNullOrTrue(GetCellStatus(cell, "IsEnabled")) && IsNullOrFalse(GetCellStatus(cell, "IsReadOnly")))))
				{
					flag = true;
					break;
				}
				if (direction == 1 || direction == 3 || ((direction == 0 || direction == 2) && !isFinished))
				{
					cell = null;
				}
			}
			while (cell == null && !isFinished);
			if (cell != null && flag)
			{
				PreviousActivePosition = CurrentActivePosition;
				DataGrid.SelectedItems.Cells.Clear();
				DataGrid.ActiveCell = cell;
				if (DataGrid.ActiveCell != null)
				{
					DataGrid.ActiveCell.IsSelected = true;
				}
				LastKeyPressed = null;
			}
			else if (isFinished && !flag)
			{
				DataGrid.SelectedItems.Cells.Clear();
				DataGrid.ActiveCell = null;
			}
			else if (!isFinished && rowId == -1)
			{
				return TabToColumnHeader();
			}
			return flag;
		}

		protected virtual bool TabToColumnHeader()
		{
			return false;
		}

		private bool FindCellDown(ref int rowId, ref int colId, ref bool isFinished, List<Field> fields, RecordCollectionBase records)
		{
			int count = fields.Count;
			int count2 = records.Count;
			if (rowId < count2 - 1)
			{
				do
				{
					rowId++;
				}
				while (rowId < count2 && records[rowId].Visibility != Visibility.Visible);
				if (rowId == count2)
				{
					return false;
				}
			}
			else if (colId < count - 1)
			{
				rowId = 0;
				do
				{
					colId++;
				}
				while (colId < count && IsFieldLabelOnly(colId, fields));
				if (colId == count)
				{
					return false;
				}
			}
			if (rowId == records.Count - 1 && colId == count - 1)
			{
				isFinished = true;
			}
			return true;
		}

		private bool FindCellUp(ref int rowId, ref int colId, ref bool isFinished, List<Field> fields, RecordCollectionBase records)
		{
			_ = fields.Count;
			if (rowId > 0)
			{
				rowId--;
			}
			else if (colId > 0)
			{
				rowId = records.Count - 1;
				do
				{
					colId--;
				}
				while (colId >= 0 && IsFieldLabelOnly(colId, fields));
				if (colId < 0)
				{
					return false;
				}
			}
			if (rowId == 0 && colId == 0)
			{
				isFinished = true;
			}
			return true;
		}

		private bool FindCellRight(ref int rowId, ref int colId, ref bool isFinished, List<Field> fields, RecordCollectionBase records)
		{
			int count = fields.Count;
			bool flag = false;
			if (colId < count - 1)
			{
				do
				{
					colId++;
				}
				while (colId < count && IsFieldLabelOnly(colId, fields));
			}
			else
			{
				flag = true;
			}
			if (colId == count || flag)
			{
				colId = 0;
				rowId++;
				if (rowId >= records.Count)
				{
					return false;
				}
				while (colId < count && IsFieldLabelOnly(colId, fields))
				{
					colId++;
				}
			}
			if (rowId == records.Count - 1 && colId == count - 1)
			{
				isFinished = true;
			}
			return true;
		}

		private bool FindCellLeft(ref int rowId, ref int colId, ref bool isFinished, List<Field> fields)
		{
			int count = fields.Count;
			bool flag = false;
			if (colId > 0)
			{
				do
				{
					colId--;
				}
				while (colId >= 0 && IsFieldLabelOnly(colId, fields));
			}
			else
			{
				flag = true;
			}
			if (colId < 0 || flag)
			{
				colId = count - 1;
				while (colId >= 0 && IsFieldLabelOnly(colId, fields))
				{
					colId--;
				}
				rowId--;
				if (rowId < 0)
				{
					return false;
				}
				while (colId >= 0 && IsFieldLabelOnly(colId, fields))
				{
					colId--;
				}
			}
			if (rowId == 0 && colId == 0)
			{
				isFinished = true;
			}
			return true;
		}

		private bool IsFieldLabelOnly(int colId, List<Field> fields)
		{
			return fields[colId].CellContentAlignmentResolved == CellContentAlignment.LabelOnly;
		}

		private List<Field> GetCurrentVisualFields()
		{
			return (from dr in DataGrid.ActiveCell.Field.Owner.Fields
				where dr.Visibility == Visibility.Visible && dr.CellContentAlignmentResolved != CellContentAlignment.LabelOnly
				orderby dr.ActualPosition.Column
				select dr).ToList();
		}

