		public ValueEditor GetActiveEditor()
		{
			if (DataGrid.ActiveCell == null)
			{
				return null;
			}
			CellValuePresenter cellValuePresenter = CellValuePresenter.FromCell(DataGrid.ActiveCell);
			if (cellValuePresenter == null)
			{
				return null;
			}
			ValueEditor valueEditor = cellValuePresenter.Editor;
			if (valueEditor == null)
			{
				valueEditor = Infragistics.Windows.Utilities.GetDescendantFromType(cellValuePresenter, typeof(AesXamValueEdit), allowSubclassOfType: true) as AesXamValueEdit;
				if (valueEditor == null)
				{
					valueEditor = Infragistics.Windows.Utilities.GetDescendantFromType(cellValuePresenter, typeof(AesXamComboEdit), allowSubclassOfType: true) as AesXamComboEdit;
				}
				else if (!valueEditor.IsFocusWithin)
				{
					DependencyObject descendantFromType = Infragistics.Windows.Utilities.GetDescendantFromType(cellValuePresenter, typeof(AesUnitsEdit), allowSubclassOfType: false);
					if (descendantFromType != null && Infragistics.Windows.Utilities.GetDescendantFromType(descendantFromType, typeof(AesXamComboEdit), allowSubclassOfType: false) is AesXamComboEdit { IsFocusWithin: not false } aesXamComboEdit)
					{
						valueEditor = aesXamComboEdit;
					}
				}
			}
			return valueEditor;
		}

		protected void RefreshRecordSelectors(bool isClearingAllHighlight)
		{
			if ((isClearingAllHighlight && !_isRecordSelectorHighlighted) || !ShouldHighlightHeaderOnSelection)
			{
				return;
			}
			EnsureRecordsInView();
			if (_recordsInView != null)
			{
				Record[] recordsInView = _recordsInView;
				foreach (Record record in recordsInView)
				{
					RecordPresenter recordPresenter = RecordPresenter.FromRecord(record);
					if (recordPresenter != null && Infragistics.Windows.Utilities.GetDescendantFromType(recordPresenter, typeof(RecordSelector), allowSubclassOfType: false) is RecordSelector recordSelector)
					{
						if (isClearingAllHighlight)
						{
							recordSelector.Background = System.Windows.Media.Brushes.White;
						}
						else if (SelectedRowIndexes != null && SelectedRowIndexes.Contains((record as DataRecord).DataItemIndex))
						{
							recordSelector.Background = SelectedRecordSelectorBrush;
							_isRecordSelectorHighlighted = true;
						}
						else
						{
							recordSelector.Background = System.Windows.Media.Brushes.White;
						}
					}
				}
			}
			if (isClearingAllHighlight)
			{
				_isRecordSelectorHighlighted = false;
			}
		}

