	internal class CellComparer : IComparer<Cell>
	{
		public int Compare(Cell x, Cell y)
		{
			if ((x.Record == null || x.Field == null) && (y.Record == null || y.Field == null))
			{
				return 0;
			}
			if (x.Record == null || x.Field == null)
			{
				return -1;
			}
			if (y.Record == null || y.Field == null)
			{
				return 1;
			}
			if (x.Record.DataItemIndex != y.Record.DataItemIndex)
			{
				if (x.Record.DataItemIndex < y.Record.DataItemIndex)
				{
					return -1;
				}
				return 1;
			}
			if (x.Field.Index == y.Field.Index)
			{
				return 0;
			}
			if (x.Field.Index < y.Field.Index)
			{
				return -1;
			}
			return 1;
		}
	}
