		public object GetData(string format, bool autoConvert)
		{
			object result = new object();
			try
			{
				if (format == DataFormats.Text)
				{
					result = Value;
				}
				else
				{
					switch (format)
					{
					case "ASI File Format":
						if (_ASIFileXml == null)
						{
							_ASIFileXml = ClipboardHelper.GetAsiFileXml(CaseFullFileName, ApplicationName);
						}
						result = _ASIFileXml;
						break;
					case "ASI Format":
						if (_ASISelectionXml == null)
						{
							_ASISelectionXml = ClipboardHelper.GetAsiSelectionXmlStream(Monikers, CaseFullFileName, ApplicationName);
						}
						result = _ASISelectionXml;
						break;
					case "CSV":
						result = Csv;
						break;
					case "DatagridMetadata":
						result = DatagridMetadata;
						break;
					}
				}
			}
			catch (Exception)
			{
			}
			return result;
		}

