		private static string GetColumnHeader(List<MMScrollAreaSelectedCell> selectedCells, CxvViewModel viewModel)
		{
			if (selectedCells == null || selectedCells.Count == 0)
			{
				return null;
			}
			StringBuilder stringBuilder = new StringBuilder();
			if (!(selectedCells[0].Field.ParentScrollArea is MMScrollAreaManualLayout manualLayout))
			{
				MMScrollArea mMScrollArea = selectedCells[0].Field.ParentScrollArea as MMScrollArea;
				if (mMScrollArea.MMFields != null)
				{
					mMScrollArea.ClipboardDataObject._columnHeaderLineCount = 0;
					List<MMScrollAreaField> selectedFields = GetSelectedFields(selectedCells);
					GetLabelOfNonHeaderOnlyFields(stringBuilder, selectedFields, mMScrollArea, viewModel, setHeaderLineCount: true);
					GetLabelOfHeaderOnlyFields(stringBuilder, selectedFields, mMScrollArea);
				}
			}
			else
			{
				PopulateManualLayoutHeader(selectedCells, stringBuilder, manualLayout, viewModel);
			}
			if (stringBuilder.ToString().Trim().Length > 0)
			{
				stringBuilder.Append("\r\n");
				return stringBuilder.ToString();
			}
			return string.Empty;
		}

		private static void GetLabelOfHeaderOnlyFields(StringBuilder value, List<MMScrollAreaField> selectedFields, MMScrollArea sa)
		{
			if (value == null || selectedFields == null || sa == null)
			{
				return;
			}
			string[] array = new string[sa.DataGrid.DefaultFieldLayout.Fields.Count];
			bool flag = false;
			foreach (MMScrollAreaField mMField in sa.MMFields)
			{
				if (!(mMField is MMScrollAreaHeaderOnlyField mMScrollAreaHeaderOnlyField))
				{
					continue;
				}
				int num = -1;
				foreach (MMScrollAreaField mMField2 in mMScrollAreaHeaderOnlyField.MMFields)
				{
					foreach (MMScrollAreaField selectedField in selectedFields)
					{
						if (selectedField == mMField2 || selectedField.ExpandedFromRepeater == mMField2)
						{
							flag = true;
							if (num == -1 || selectedField.Field.ActualPosition.Column < num)
							{
								num = selectedField.Field.ActualPosition.Column;
							}
						}
					}
				}
				if (num >= 0)
				{
					array[num] = mMScrollAreaHeaderOnlyField.Label;
				}
			}
			if (!flag)
			{
				return;
			}
			int num2 = sa.DataGrid.DefaultFieldLayout.Fields.Count;
			foreach (MMScrollAreaField selectedField2 in selectedFields)
			{
				if (selectedField2.Field.ActualPosition.Column < num2)
				{
					num2 = selectedField2.Field.ActualPosition.Column;
				}
			}
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = num2; i < array.Length; i++)
			{
				if (array[i] != null)
				{
					stringBuilder.Append(array[i]);
				}
				stringBuilder.Append("\t");
			}
			if (!string.IsNullOrEmpty(value.ToString().Replace("\t", "").Trim()))
			{
				value.Insert(0, Environment.NewLine);
			}
			value.Insert(0, stringBuilder.ToString().TrimEnd('\t'));
			sa.ClipboardDataObject._columnHeaderLineCount++;
		}

		private static void PopulateManualLayoutHeader(List<MMScrollAreaSelectedCell> selectedCells, StringBuilder value, MMScrollAreaManualLayout manualLayout, CxvViewModel viewModel)
		{
			bool flag = true;
			int num = -1;
			int lastFieldIdId = -1;
			StringBuilder stringBuilder = new StringBuilder();
			foreach (MMScrollAreaSelectedCell selectedCell in selectedCells)
			{
				if (selectedCell.Field.Id <= num)
				{
					continue;
				}
				lastFieldIdId = num;
				num = selectedCell.Field.Id;
				if (flag)
				{
					flag = false;
				}
				else if (lastFieldIdId > -1)
				{
					int i;
					for (i = 0; i < num - lastFieldIdId; i++)
					{
						MMScrollAreaColumn mMScrollAreaColumn = manualLayout.MMColumns.FirstOrDefault((MMScrollAreaColumn p) => p.LinkedMMField.Id == lastFieldIdId + i + 1);
						if (mMScrollAreaColumn == null || mMScrollAreaColumn.IsVisible)
						{
							value.Append("\t");
							stringBuilder.Append("\t");
						}
					}
				}
				value.Append(manualLayout.MMColumns[selectedCell.Field.Id].Label);
				stringBuilder.Append(GetManualLayoutColumnUnit(manualLayout.MMColumns[selectedCell.Field.Id], viewModel));
			}
			if (!string.IsNullOrEmpty(stringBuilder.ToString().Replace("\t", "")))
			{
				value.Append("\r\n" + stringBuilder.ToString());
			}
		}

		private static string GetManualLayoutColumnUnit(MMScrollAreaColumn column, CxvViewModel viewModel)
		{
			if (!string.IsNullOrEmpty(column.HeaderUnitsProperty))
			{
				object obj = viewModel.ResolveViewPropertyPath(column.HeaderUnitsProperty.Trim() + ".Units");
				if (obj != null && !string.IsNullOrEmpty(obj.ToString()))
				{
					return obj.ToString();
				}
			}
			return string.Empty;
		}

		private static List<MMScrollAreaField> GetSelectedFields(List<MMScrollAreaSelectedCell> selectedCells)
		{
			List<MMScrollAreaField> list = new List<MMScrollAreaField>();
			foreach (MMScrollAreaSelectedCell selectedCell in selectedCells)
			{
				if (selectedCell.Field.Field != null && !list.Contains(selectedCell.Field))
				{
					list.Add(selectedCell.Field);
				}
			}
			return list;
		}

		internal static void GetLabelOfNonHeaderOnlyFields(StringBuilder value, List<MMScrollAreaField> selectedFields, MMScrollArea sa, CxvViewModel viewModel, bool setHeaderLineCount)
		{
			if (value == null || selectedFields == null || sa == null || viewModel == null)
			{
				return;
			}
			IOrderedEnumerable<MMScrollAreaField> orderedEnumerable = selectedFields.OrderBy((MMScrollAreaField f) => f.Field.ActualPosition.Column);
			bool flag = true;
			int maxRowIdInColumnHeader = GetMaxRowIdInColumnHeader(orderedEnumerable);
			if (setHeaderLineCount)
			{
				sa.ClipboardDataObject._columnHeaderLineCount = maxRowIdInColumnHeader;
			}
			for (int num = 0; num < maxRowIdInColumnHeader; num++)
			{
				flag = true;
				StringBuilder stringBuilder = new StringBuilder();
				foreach (MMScrollAreaField item in orderedEnumerable)
				{
					_ = item.Field.ActualPosition.Column;
					if (flag)
					{
						flag = false;
					}
					else
					{
						stringBuilder.Append("\t");
					}
					if (item.ColumnHeaderCopyValue != null)
					{
						if (num < item.ColumnHeaderCopyValue.Count)
						{
							stringBuilder.Append(item.ColumnHeaderCopyValue[num]);
						}
						continue;
					}
					if (num == 0 && item.LabelDockResolved == Dock.Top)
					{
						AppendLabel(stringBuilder, item);
						continue;
					}
					int num2 = 0;
					if (!string.IsNullOrEmpty(item.HeaderUnitsProperty))
					{
						string[] array = item.HeaderUnitsProperty.Split(',');
						string[] array2 = null;
						if (!string.IsNullOrEmpty(item.HeaderTypeProperty))
						{
							array2 = item.HeaderTypeProperty.Split(',');
						}
						num2 = ((array2 != null) ? array2.Length : array.Length);
						int num3 = 0;
						num3 = ((item.LabelDockResolved != Dock.Top) ? (num2 - 1 - num) : (num - 1));
						if (num2 > num3 && num3 >= 0)
						{
							AppendHeaderElementToCurrentRow(viewModel, stringBuilder, array, array2, num3);
							continue;
						}
					}
					if (item.LabelDockResolved == Dock.Bottom && num == num2)
					{
						AppendLabel(stringBuilder, item);
					}
				}
				if (num > 0)
				{
					value.Append(Environment.NewLine);
				}
				value.Append(stringBuilder);
			}
		}

		private static int GetMaxRowIdInColumnHeader(IOrderedEnumerable<MMScrollAreaField> q)
		{
			int num = 1;
			foreach (MMScrollAreaField item in q)
			{
				BindingOperations.GetBindingExpression(item, MMScrollAreaField.ColumnHeaderCopyValueProperty)?.UpdateTarget();
				if (item.ColumnHeaderCopyValue != null)
				{
					if (item.ColumnHeaderCopyValue.Count > num)
					{
						num = item.ColumnHeaderCopyValue.Count;
					}
				}
				else if (!string.IsNullOrEmpty(item.HeaderUnitsProperty))
				{
					string[] array = item.HeaderUnitsProperty.Split(',');
					if (array != null && array.Length + 1 > num)
					{
						num = array.Length + 1;
					}
				}
			}
			return num;
		}

		private static void AppendLabel(StringBuilder currentRow, MMScrollAreaField field)
		{
			string text = field.Label;
			if (field.LabelTextConverter != null)
			{
				object obj = field.LabelTextConverter.Convert(text, typeof(string), null, CultureInfo.CurrentCulture);
				if (obj != null)
				{
					text = obj.ToString();
				}
			}
			if (text != null)
			{
				if (text.Contains('\r') || text.Contains('\n'))
				{
					currentRow.Append("\"").Append(text).Append("\"");
				}
				else
				{
					currentRow.Append(text);
				}
			}
		}

		private static void AppendHeaderElementToCurrentRow(CxvViewModel viewModel, StringBuilder currentRow, string[] headers, string[] headertypes, int headerPropertyId)
		{
			string text = null;
			((headers.Length <= headerPropertyId) ? headers[headers.Length - 1] : headers[headerPropertyId]).Trim();
			string text2 = ((headertypes == null) ? "" : ((headertypes.Length > headerPropertyId) ? headertypes[headerPropertyId] : ""));
			text2 = text2.Trim().ToLowerInvariant();
			if (string.IsNullOrEmpty(text2))
			{
				text2 = "units";
			}
			switch (text2)
			{
			case "units":
				text = "Units";
				break;
			case "id":
			case "value":
			case "textuppercase":
				text = "Value";
				break;
			case "selecteditem":
				text = "SelectedItem";
				break;
			case "basis":
				text = "Basis";
				break;
			}
			object obj = viewModel.ResolveViewPropertyPath(headers[headerPropertyId].Trim() + "." + text);
			if (obj != null && !string.IsNullOrEmpty(obj.ToString()))
			{
				currentRow.Append(obj);
			}
		}

		internal static string GetCellValue(MMScrollAreaSelectedCell cell, CxvViewModel viewModel, GetPropPathDelegate getPropPath)
		{
			if (cell == null || viewModel == null || getPropPath == null)
			{
				return string.Empty;
			}
			object obj = null;
			Type type = cell.Field.GetType();
			if (type == typeof(MMScrollAreaButtonField) || type == typeof(MMScrollAreaDeleteButtonField) || type == typeof(MMScrollAreaLineFormatField))
			{
				obj = "";
			}
			else if (type == typeof(MMScrollAreaCheckBoxField))
			{
				_ = cell.Field;
				object obj2 = viewModel.ResolveViewPropertyPath(getPropPath(cell) + ".Value");
				if (obj2 != null)
				{
					obj = obj2.ToString();
				}
			}
			else if (typeof(MMScrollAreaBrowseField).IsAssignableFrom(type))
			{
				obj = viewModel.ResolveViewPropertyPath(getPropPath(cell) + "." + (cell.Field as MMScrollAreaBrowseField).VariableDataMemberResolved);
			}
			else if (type == typeof(MMScrollAreaTextField))
			{
				MMScrollAreaTextField mMScrollAreaTextField = cell.Field as MMScrollAreaTextField;
				obj = (string.IsNullOrEmpty(mMScrollAreaTextField.Text) ? viewModel.ResolveViewPropertyPath(getPropPath(cell) + "." + mMScrollAreaTextField.VariableDataMemberResolved) : mMScrollAreaTextField.Text);
			}
			else if (type == typeof(MMScrollAreaComboValueField))
			{
				MMScrollAreaComboValueField mMScrollAreaComboValueField = cell.Field as MMScrollAreaComboValueField;
				MMScrollArea mMScrollArea = mMScrollAreaComboValueField.ParentScrollArea as MMScrollArea;
				if (!string.IsNullOrEmpty(mMScrollAreaComboValueField.ValuePath))
				{
					StringBuilder stringBuilder = new StringBuilder();
					stringBuilder.Append(mMScrollArea.DataProperty).Append("[").Append(cell.Record.Index.ToString(CultureInfo.InvariantCulture))
						.Append("]");
					stringBuilder.Append(".").Append(mMScrollAreaComboValueField.ValuePath);
					obj = viewModel.ResolveViewPropertyPath(stringBuilder.ToString());
				}
				else
				{
					obj = viewModel.ResolveViewPropertyPath(getPropPath(cell) + "." + (cell.Field as MMScrollAreaComboValueField).VariableDataMemberResolved);
				}
			}
			else if (type == typeof(MMScrollAreaReadOnlyComboField))
			{
				MMScrollAreaReadOnlyComboField mMScrollAreaReadOnlyComboField = cell.Field as MMScrollAreaReadOnlyComboField;
				obj = viewModel.ResolveViewPropertyPath(getPropPath(cell) + "." + mMScrollAreaReadOnlyComboField.VariableDataMemberResolved);
			}
			else if (type == typeof(MMScrollAreaVariableField))
			{
				StringBuilder stringBuilder2 = new StringBuilder();
				MMScrollAreaVariableField mMScrollAreaVariableField = cell.Field as MMScrollAreaVariableField;
				string value = (mMScrollAreaVariableField.CopyAsOneField ? " " : "\t");
				if (!mMScrollAreaVariableField.IsBasisVisible.HasValue || mMScrollAreaVariableField.IsBasisVisible.Value)
				{
					stringBuilder2.Append(viewModel.ResolveViewPropertyPath(getPropPath(cell) + ".Basis"));
				}
				if (!mMScrollAreaVariableField.IsValueVisible.HasValue || mMScrollAreaVariableField.IsValueVisible.Value)
				{
					if (stringBuilder2.Length > 0)
					{
						stringBuilder2.Append(value);
					}
					stringBuilder2.Append(viewModel.ResolveViewPropertyPath(getPropPath(cell) + "." + mMScrollAreaVariableField.VariableDataMemberResolved));
				}
				if (!mMScrollAreaVariableField.IsUnitsVisible.HasValue || mMScrollAreaVariableField.IsUnitsVisible.Value)
				{
					if (stringBuilder2.Length > 0)
					{
						stringBuilder2.Append(value);
					}
					stringBuilder2.Append(viewModel.ResolveViewPropertyPath(getPropPath(cell) + ".Units"));
				}
				obj = stringBuilder2.ToString();
			}
			else if (type == typeof(MMScrollAreaFortranLineField))
			{
				MMScrollAreaFortranLineField mMScrollAreaFortranLineField = cell.Field as MMScrollAreaFortranLineField;
				obj = viewModel.ResolveViewPropertyPath(getPropPath(cell) + "." + mMScrollAreaFortranLineField.VariableDataMemberResolved);
			}
			else
			{
				bool flag = false;
				string text = null;
				if (type == typeof(MMScrollAreaBasisField))
				{
					text = ".Basis";
				}
				else if (type == typeof(MMScrollAreaUnitsField))
				{
					text = ".Units";
				}
				else if (type == typeof(MMScrollAreaReadOnlyValueField))
				{
					string variableDataMemberResolved = ((MMScrollAreaValueField)cell.Field).VariableDataMemberResolved;
					text = "." + (string.IsNullOrEmpty(variableDataMemberResolved) ? "Value" : variableDataMemberResolved);
					flag = ((MMScrollAreaValueField)cell.Field).TrimCopy;
				}
				else if (type == typeof(MMScrollAreaValueField) || type == typeof(MMScrollAreaSpinField))
				{
					MMScrollAreaValueField mMScrollAreaValueField = cell.Field as MMScrollAreaValueField;
					text = "." + mMScrollAreaValueField.VariableDataMemberResolved;
					flag = mMScrollAreaValueField.TrimCopy;
				}
				if (string.IsNullOrEmpty(getPropPath(cell)))
				{
					if (cell.Field.Data is CxvVariableData cxvVariableData)
					{
						if (type == typeof(MMScrollAreaUnitsField))
						{
							obj = cxvVariableData.Units;
						}
					}
					else if (cell.Field.Data is AdsVariableData adsVariableData && type == typeof(MMScrollAreaUnitsField))
					{
						obj = adsVariableData.Units;
					}
				}
				else
				{
					obj = viewModel.ResolveViewPropertyPath(getPropPath(cell) + text);
					if (flag && obj != null && obj.GetType() == typeof(string))
					{
						obj = obj.ToString().Trim();
					}
				}
			}
			return obj?.ToString();
		}

		internal static string GetValueFromSelection(List<MMScrollAreaSelectedCell> selectedCells, CxvViewModel viewModel, GetPropPathDelegate getPropPath, bool includeColumnHeader, bool isHorizontal, FieldCollection allFields)
		{
			StringBuilder stringBuilder = new StringBuilder();
			int num = -1;
			string text = "\r\n";
			string text2 = "\t";
			int num2 = -1;
			int? lastCellFieldIdIndex = null;
			foreach (MMScrollAreaSelectedCell selectedCell in selectedCells)
			{
				string cellValue = GetCellValue(selectedCell, viewModel, getPropPath);
				string text3 = "";
				bool flag = false;
				if ((!isHorizontal && selectedCell.Record.DisplayIndex == num) || (isHorizontal && GetFieldId(selectedCell) == num))
				{
					text3 = text2;
				}
				else
				{
					if (isHorizontal)
					{
						num = GetFieldId(selectedCell);
						if (includeColumnHeader)
						{
							flag = true;
						}
					}
					else
					{
						num = selectedCell.Record.DisplayIndex;
					}
					text3 = text;
				}
				if (text3 == text)
				{
					string text4 = stringBuilder.ToString();
					if (text4.EndsWith("\t"))
					{
						stringBuilder.Remove(text4.Length - 1, 1);
					}
				}
				stringBuilder.Append(text3);
				if (num2 != -1)
				{
					int num3 = selectedCell.Record.DisplayIndex - num2;
					for (int i = 0; i < num3 - 1; i++)
					{
						stringBuilder.Append(text3);
					}
				}
				num2 = selectedCell.Record.DisplayIndex;
				if (lastCellFieldIdIndex.HasValue)
				{
					MMScrollAreaField field = selectedCell.Field;
					if (field != null)
					{
						_ = field.Id;
						if (true && allFields != null)
						{
							int? num4 = selectedCell.Field.Id - lastCellFieldIdIndex;
							int j;
							for (j = 0; j < num4 - 1; j++)
							{
								Field field2 = allFields.FirstOrDefault((Field p) => p.Index == lastCellFieldIdIndex + j + 1);
								if (field2 == null || field2.Visibility == Visibility.Visible)
								{
									stringBuilder.Append('\t');
								}
							}
						}
					}
				}
				lastCellFieldIdIndex = selectedCell.Field?.Id;
				if (flag)
				{
					if (!string.IsNullOrEmpty(selectedCell.Field.LabelForCopy))
					{
						stringBuilder.Append(selectedCell.Field.LabelForCopy).Append(text2);
					}
					else
					{
						stringBuilder.Append(selectedCell.Field.Label).Append(text2);
					}
					(selectedCell.Field.ParentScrollArea as MMScrollArea).ClipboardDataObject._columnHeaderLineCount = 1;
				}
				if (cellValue == null)
				{
					continue;
				}
				string text5 = cellValue.ToString();
				if (!string.IsNullOrEmpty(text5))
				{
					bool flag2 = text5.EndsWith("%");
					if (double.TryParse((flag2 ? text5.Substring(0, text5.Length - 1) : text5).Replace(".", MaskingAndValidatingHelper.GetSystemDecimalSymbol()), out var result))
					{
						text5 = result + (flag2 ? "%" : string.Empty);
					}
				}
				if (text5.Contains('\r') || text5.Contains('\n'))
				{
					text5 = "\"" + text5 + "\"";
				}
				stringBuilder.Append(text5);
			}
			string text6 = stringBuilder.ToString();
			if (text6.EndsWith("\t"))
			{
				stringBuilder.Remove(text6.Length - 1, 1);
			}
			stringBuilder.Append(text);
			stringBuilder.Remove(0, text.Length);
			if (includeColumnHeader && !isHorizontal)
			{
				stringBuilder.Insert(0, GetColumnHeader(selectedCells, viewModel));
			}
			if (stringBuilder.Length > 1 && stringBuilder.ToString().EndsWith("\r\n"))
			{
				stringBuilder.Remove(stringBuilder.Length - 2, 2);
			}
			return stringBuilder.ToString();
		}

		private static int GetFieldId(MMScrollAreaSelectedCell cell)
		{
			MMScrollArea mMScrollArea = cell.Field.ParentScrollArea as MMScrollArea;
			if (cell.Field.Field == null)
			{
				return cell.Field.Id;
			}
			if (mMScrollArea == null || mMScrollArea.DataOrientation == Orientation.Vertical)
			{
				return cell.Field.Field.ActualPosition.Column;
			}
			return cell.Field.Field.ActualPosition.Row;
		}

		internal static void SetValueForSelection(MMScrollAreaSelectedCell cell, CxvViewModel viewModel, GetPropPathDelegate getPropPath, object value)
		{
			Type type = cell.Field.GetType();
			string text = getPropPath(cell);
			if (type == typeof(MMScrollAreaComboValueField))
			{
				viewModel.ResolveUpdateViewPropertyPath(text + "." + (cell.Field as MMScrollAreaComboValueField).VariableDataMemberResolved, value);
			}
			else if (type == typeof(MMScrollAreaVariableField))
			{
				string[] array = value.ToString().Trim().Split(' ');
				string value2 = null;
				string value3 = null;
				if (array.Length == 3)
				{
					_ = array[0];
					value2 = array[1];
					value3 = array[2];
				}
				else if (array.Length == 2)
				{
					if (char.IsLetter(array[0], 0))
					{
						_ = array[0];
						value2 = array[1];
					}
					else
					{
						value2 = array[0];
						value3 = array[1];
					}
				}
				else if (array.Length == 1)
				{
					if (char.IsLetter(array[0], 0))
					{
						value3 = array[0];
					}
					else
					{
						value2 = array[0];
					}
				}
				viewModel.ResolveUpdateViewPropertyPath(text + ".Value", value2);
				viewModel.ResolveUpdateViewPropertyPath(text + ".Units", value3);
			}
			else
			{
				string text2 = null;
				text2 = ((type == typeof(MMScrollAreaBasisField)) ? ".Basis" : ((!(type == typeof(MMScrollAreaUnitsField))) ? ".Value" : ".Units"));
				viewModel.ResolveUpdateViewPropertyPath(text + text2, value);
			}
		}

		internal static Collection<string> GetMonikersFromSelection(List<MMScrollAreaSelectedCell> selectedCells, CxvViewModel viewModel, GetPropPathDelegate getPropPath, bool ignoreWithoutAlternatePath, bool isMMScrollAreaHorizontal = false)
		{
			Collection<string> collection = new Collection<string>();
