			{
				if (ignoreWithoutAlternatePath)
				{
					object obj = viewModel.ResolveViewPropertyPath(getPropPath(selectedCell) + ".AlternatePath");
					if (obj == null || string.IsNullOrEmpty(obj.ToString()))
					{
						continue;
					}
				}
				object obj2 = viewModel.ResolveViewPropertyPath(getPropPath(selectedCell) + ".CxsItemMoniker");
				if (obj2 != null)
				{
					collection.Add(obj2.ToString());
				}
				else if (obj2 == null && isMMScrollAreaHorizontal)
				{
					collection.Add(string.Empty);
				}
			}
			return collection;
