		internal static Collection<(string moniker, string exposeAs)> GetMonikersExposeAsFromSelection(List<MMScrollAreaSelectedCell> selectedCells, CxvViewModel viewModel, GetPropPathDelegate getPropPath, bool ignoreWithoutAlternatePath, bool isMMScrollAreaHorizontal = false)
		{
			Collection<(string, string)> collection = new Collection<(string, string)>();
			foreach (MMScrollAreaSelectedCell selectedCell in selectedCells)
			{
				if (ignoreWithoutAlternatePath)
				{
					object obj = viewModel.ResolveViewPropertyPath(getPropPath(selectedCell) + ".AlternatePath");
					if (obj == null || string.IsNullOrEmpty(obj.ToString()))
					{
						continue;
					}
				}
				object obj2 = viewModel.ResolveViewPropertyPath(getPropPath(selectedCell) + ".CxsItemMoniker");
				object obj3 = viewModel.ResolveViewPropertyPath(getPropPath(selectedCell) + ".ResolvedExposeAs");
				if (obj3 == null)
				{
					obj3 = "Real";
				}
				if (obj2 != null)
				{
					collection.Add((obj2.ToString(), obj3.ToString()));
				}
				else if (obj2 == null && isMMScrollAreaHorizontal)
				{
					collection.Add((string.Empty, string.Empty));
