		internal static Collection<string> GetMonikersWithValueFromSelection(List<MMScrollAreaSelectedCell> selectedCells, CxvViewModel viewModel, GetPropPathDelegate getPropPath, bool ignoreWithoutAlternatePath, FieldCollection allFields)
		{
			Collection<string> collection = new Collection<string>();
			foreach (MMScrollAreaSelectedCell selectedCell in selectedCells)
			{
				if (ignoreWithoutAlternatePath)
				{
					object obj = viewModel.ResolveViewPropertyPath(getPropPath(selectedCell) + ".AlternatePath");
					if (obj == null || string.IsNullOrEmpty(obj.ToString()))
					{
						continue;
					}
				}
				if (!string.IsNullOrWhiteSpace(GetValueFromSelection(new List<MMScrollAreaSelectedCell> { selectedCell }, viewModel, getPropPath, includeColumnHeader: false, isHorizontal: false, allFields)))
				{
					object obj2 = viewModel.ResolveViewPropertyPath(getPropPath(selectedCell) + ".CxsItemMoniker");
					if (obj2 != null)
					{
						collection.Add(obj2.ToString());
					}
				}
			}
			return collection;
		}

