	public class MMComboEdit : AesComboEdit
	{
		private const int MAX_VERBS = 6;

		private static RoutedUICommand[] VerbCommands;

		private string[] _verbList;

		[DefaultValue(null)]
		public bool? UseDefaultContextMenu { get; set; }

		[DefaultValue(null)]
		public bool? SuppressContextMenu { get; set; }

		static MMComboEdit()
		{
			VerbCommands = new RoutedUICommand[6]
			{
				new RoutedUICommand("Verb0", "Verb0", typeof(MMComboEdit)),
				new RoutedUICommand("Verb1", "Verb1", typeof(MMComboEdit)),
				new RoutedUICommand("Verb2", "Verb2", typeof(MMComboEdit)),
				new RoutedUICommand("Verb3", "Verb3", typeof(MMComboEdit)),
				new RoutedUICommand("Verb4", "Verb4", typeof(MMComboEdit)),
				new RoutedUICommand("Verb5", "Verb5", typeof(MMComboEdit))
			};
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(MMComboEdit), new FrameworkPropertyMetadata(typeof(MMComboEdit)));
			CommandManager.RegisterClassCommandBinding(typeof(MMComboEdit), new CommandBinding(ApplicationCommands.New, New_Executed, New_CanExecute));
		}

		private static void OnVerbCommand(object sender, ExecutedRoutedEventArgs arg)
		{
			MMComboEdit mMComboEdit = arg.Parameter as MMComboEdit;
			RoutedUICommand routedUICommand = arg.Command as RoutedUICommand;
			mMComboEdit?.ExecuteVerb(routedUICommand.Name);
		}

		protected override void OnContextMenuOpening(ContextMenuEventArgs e)
		{
			if (SuppressContextMenu ?? false)
			{
				e.Handled = true;
			}
			else if (UseDefaultContextMenu ?? false)
			{
				base.OnContextMenuOpening(e);
			}
			else if (base.Variable is ICxvObjectVerbs cxvObjectVerbs)
			{
				ContextMenu contextMenu = null;
				_verbList = new string[6];
				contextMenu = new ContextMenu();
				int num = 0;
				foreach (CxvVerbDescriptor item in cxvObjectVerbs.EnumerateVerbs())
				{
					contextMenu.CommandBindings.Add(new CommandBinding(VerbCommands[num], OnVerbCommand));
					contextMenu.Items.Add(new MenuItem
					{
						Header = item.VerbDisplayName,
						Command = VerbCommands[num],
						CommandParameter = this,
						IsEnabled = (item.Enabled && base.IsEnabled && base.IsMMEnabled && !base.IsReadOnly)
					});
					_verbList[num] = item.Verb;
					num++;
					if (num == 6)
					{
						break;
					}
				}
				contextMenu.PlacementTarget = this;
				contextMenu.IsOpen = true;
				e.Handled = true;
			}
			else
			{
				base.OnContextMenuOpening(e);
			}
		}

		protected void ExecuteVerb(string commandName)
		{
			if (!(base.Variable is ICxvObjectVerbs cxvObjectVerbs))
			{
				return;
			}
			int num = Convert.ToInt32(commandName.Substring(4));
			if (num > -1 && num < 6)
			{
				if (base.Template.FindName("PART_editControl", this) is AesXamComboEdit { IsInEditMode: not false } aesXamComboEdit)
				{
					aesXamComboEdit.EndEditMode(acceptChanges: true, force: false);
				}
				cxvObjectVerbs.DoVerb(_verbList[num], base.Value);
			}
		}

		protected override void BuildDefaultContextMenu(ContextMenu menu)
		{
			base.BuildDefaultContextMenu(menu);
			if (base.ValueOptions != null && base.ValueOptions is ObservableCollection<string> observableCollection && observableCollection.Contains(CxvVariableData.NewItem))
			{
				string text = "pack://application:,,,/" + typeof(AesControlBase).Assembly.FullName + ";component/Images/";
				System.Windows.Controls.Image image = new System.Windows.Controls.Image();
				image.Source = new BitmapImage(new Uri(text + "New16.ico"));
				menu.Items.Add(new MenuItem
				{
					Header = AspenTech.AspenPlus.MMControls.Properties.Resources.ContextMenuHeaderNew,
					InputGestureText = "",
					Command = ApplicationCommands.New,
					CommandTarget = this,
					Icon = image,
					IsEnabled = !base.IsReadOnly
				});
			}
		}

		private static void New_Executed(object sender, ExecutedRoutedEventArgs e)
		{
			(sender as MMComboEdit).OnNew(e);
			e.Handled = true;
		}

		private static void New_CanExecute(object sender, CanExecuteRoutedEventArgs e)
		{
			MMComboEdit mMComboEdit = sender as MMComboEdit;
			if (SimulatorStatusHelperForControls.Default.IsRunning || SimulatorStatusHelperForControls.Default.IsPausedByUser)
			{
				e.CanExecute = false;
			}
			else
			{
				mMComboEdit.OnCanNew(e);
			}
			e.Handled = true;
		}

		protected void OnNew(ExecutedRoutedEventArgs e)
		{
			base.Value = CxvVariableData.NewItem;
		}

		protected virtual void OnCanNew(CanExecuteRoutedEventArgs e)
		{
			e.CanExecute = false;
			if (base.ValueOptions != null && base.ValueOptions is ObservableCollection<string> observableCollection && observableCollection.Contains(CxvVariableData.NewItem) && base.IsMMEnabled)
			{
				e.CanExecute = true;
			}
		}

		protected override void OnPreviewKeyDown(KeyEventArgs e)
		{
			base.OnPreviewKeyDown(e);
			if (e.Key != Key.Delete || !(base.Variable is ICxvObjectVerbs cxvObjectVerbs))
			{
				return;
			}
			CxvVerbDescriptor cxvVerbDescriptor = cxvObjectVerbs.FindVerb("Delete");
			if (cxvVerbDescriptor != null && cxvVerbDescriptor.Enabled && base.Template.FindName("PART_editControl", this) is AesXamComboEdit { IsDropDownOpen: not false } aesXamComboEdit)
			{
				cxvObjectVerbs.DoVerb("Delete", aesXamComboEdit.HighlightedItem);
				e.Handled = true;
				if (aesXamComboEdit.IsInEditMode)
				{
					aesXamComboEdit.EndEditMode(acceptChanges: true, force: false);
				}
			}
		}
	}
