	[TemplatePart(Name = "PART_editControl", Type = typeof(TextBox))]
	public class MMDescription : AesTextEdit
	{
		public static readonly DependencyProperty MaxLineLengthProperty;

		private TextBox _editor;

		public int? MaxLineLength
		{
			get
			{
				return (int?)GetValue(MaxLineLengthProperty);
			}
			set
			{
				SetValue(MaxLineLengthProperty, value);
			}
		}

		public new TextBox Editor
		{
			get
			{
				if (_editor == null && base.Template != null)
				{
					_editor = base.Template.FindName("PART_editControl", this) as TextBox;
				}
				return _editor;
			}
		}

		static MMDescription()
		{
			MaxLineLengthProperty = DependencyProperty.Register("MaxLineLength", typeof(int?), typeof(MMDescription), new FrameworkPropertyMetadata(120));
			AesTextEdit.AcceptsReturnProperty.OverrideMetadata(typeof(MMDescription), new FrameworkPropertyMetadata(true));
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(MMDescription), new FrameworkPropertyMetadata(typeof(MMDescription)));
			AesTextEdit.HorizontalScrollBarVisibilityProperty.OverrideMetadata(typeof(MMDescription), new FrameworkPropertyMetadata(ScrollBarVisibility.Visible));
			AesTextEdit.VerticalScrollBarVisibilityProperty.OverrideMetadata(typeof(MMDescription), new FrameworkPropertyMetadata(ScrollBarVisibility.Visible));
		}

		public override void OnApplyTemplate()
		{
			base.OnApplyTemplate();
			Editor.TextChanged += Editor_TextChanged;
			Editor.PreviewTextInput += Editor_PreviewTextInput;
		}

		private void Editor_PreviewTextInput(object sender, TextCompositionEventArgs e)
		{
			if (base.Mask == AesMaskOption.Description && !string.IsNullOrEmpty(e.Text) && e.Text[0] == '"')
			{
				e.Handled = true;
			}
		}

		private void Editor_TextChanged(object sender, TextChangedEventArgs e)
		{
			if (!MaxLineLength.HasValue || MaxLineLength.Value <= 0 || _editor == null)
			{
				return;
			}
			int caretIndex = _editor.CaretIndex;
			bool flag = false;
			string[] linesFromTextBox = GetLinesFromTextBox(_editor.Text);
			Collection<string> collection = new Collection<string>();
			for (int i = 0; i < linesFromTextBox.Length; i++)
			{
				bool flag2 = false;
				string text = linesFromTextBox[i];
				string text2 = null;
				int num = linesFromTextBox[i].Length;
				if (linesFromTextBox[i].Contains('\r'))
				{
					num--;
				}
				if (num > MaxLineLength)
				{
					flag = true;
					text2 = text.Substring(MaxLineLength.Value, num - MaxLineLength.Value);
					text = text.Substring(0, MaxLineLength.Value);
					text += "\n";
					if (i + 1 != linesFromTextBox.Length)
					{
						linesFromTextBox[i + 1] = linesFromTextBox[i + 1].Insert(0, text2);
						flag2 = false;
					}
					else
					{
						flag2 = true;
					}
				}
				else if (linesFromTextBox[i] != linesFromTextBox.Last())
				{
					text += "\n";
				}
				collection.Add(text);
				if (flag2)
				{
					collection.Add(text2);
				}
			}
			if (!flag)
			{
				return;
			}
			string text3 = "";
			foreach (string item in collection)
			{
				text3 += item;
			}
			int lineCount = _editor.LineCount;
			_editor.Text = text3;
			int num2 = _editor.LineCount - lineCount;
			if (num2 < 0)
			{
				num2 = 0;
			}
			_editor.Select(caretIndex + num2, 0);
		}

		public static string[] GetLinesFromTextBox(string text)
		{
			if (!string.IsNullOrEmpty(text))
			{
				text = text.Replace("\r\n", "\n").Replace('\r', '\n');
				return text.Split('\n');
			}
			return new string[0];
		}

		protected override void OnIsKeyboardFocusWithinChanged(DependencyPropertyChangedEventArgs e)
		{
			if (!base.IsKeyboardFocusWithin)
			{
				UpdateSource();
			}
			base.OnIsKeyboardFocusWithinChanged(e);
		}

		protected override void OnLostFocus(RoutedEventArgs e)
		{
			UpdateSource();
			base.OnLostFocus(e);
		}

		private void UpdateSource()
		{
			if (Editor != null)
			{
				Editor.GetBindingExpression(TextBox.TextProperty)?.UpdateSource();
			}
		}

		protected override void BuildDefaultContextMenu(ContextMenu menu)
		{
			base.BuildDefaultContextMenu(menu);
			CorrectCommandTarget(menu, Editor);
		}

		protected override void OnCanClear(CanExecuteRoutedEventArgs e)
		{
			if (!base.IsMMEnabled || base.IsReadOnly || base.Variable == null || string.IsNullOrEmpty(base.Text))
			{
				e.CanExecute = false;
			}
			else
			{
				e.CanExecute = true;
			}
		}

		protected override void OnClear(ExecutedRoutedEventArgs e)
		{
			base.Text = null;
			GetBindingExpression(AesTextEdit.TextProperty)?.UpdateSource();
		}
	}
