				}
			}
		}

		private void Editor_TextChanged(object sender, TextChangedEventArgs e)
		{
			if (!MaxLineLength.HasValue || MaxLineLength.Value <= 0 || _editor == null || _editor.Text == null)
			{
				return;
			}
			bool flag = false;
			string[] linesFromTextBox = MMDescription.GetLinesFromTextBox(_editor.Text);
			Collection<string> collection = new Collection<string>();
			for (int i = 0; i < linesFromTextBox.Length; i++)
			{
				bool flag2 = false;
				string text = linesFromTextBox[i];
				string text2 = null;
				int num = linesFromTextBox[i].Length;
				if (linesFromTextBox[i].Contains('\r'))
				{
					num--;
				}
				if (num > MaxLineLength && !text.Contains("<ErrorObjects"))
				{
					flag = true;
					text2 = text.Substring(MaxLineLength.Value, num - MaxLineLength.Value);
					text = text.Substring(0, MaxLineLength.Value);
					text += "\n";
					if (i + 1 != linesFromTextBox.Length)
					{
						linesFromTextBox[i + 1] = linesFromTextBox[i + 1].Insert(0, text2);
						flag2 = false;
					}
					else
					{
						flag2 = true;
					}
				}
				else if (linesFromTextBox[i] != linesFromTextBox.Last())
				{
					text += "\n";
				}
				collection.Add(text);
				if (flag2)
				{
					collection.Add(text2);
				}
			}
			if (!flag)
			{
				return;
			}
			string text3 = "";
			foreach (string item in collection)
			{
				text3 += item;
			}
			_editor.Text = text3;
		}

		protected override void BuildDefaultContextMenu(ContextMenu menu)
		{
			base.BuildDefaultContextMenu(menu);
			CorrectCommandTarget(menu, Editor);
			foreach (object item in (IEnumerable)menu.Items)
			{
				if (item is MenuItem)
				{
					MenuItem menuItem = item as MenuItem;
					if (menuItem.Command == ApplicationCommands.Undo)
					{
						menuItem.IsEnabled = false;
						break;
					}
				}
			}
		}

		protected override void OnCanClear(CanExecuteRoutedEventArgs e)
		{
			if (!base.IsMMEnabled || base.IsReadOnly || base.Variable == null || string.IsNullOrEmpty(base.Text))
			{
				e.CanExecute = false;
			}
			else
			{
				e.CanExecute = true;
			}
		}

		protected override void OnClear(ExecutedRoutedEventArgs e)
		{
			base.Text = null;
			GetBindingExpression(AesTextEdit.TextProperty)?.UpdateSource();
		}
	}
	public class NormalizeTextForLineCharsConverter : IValueConverter
	{
		private static string NormalizeTextForNewLineChars(string text)
		{
			if (!string.IsNullOrEmpty(text))
			{
				return text.Replace("\r\n", "\n").Replace('\r', '\n');
			}
			return text;
		}

		public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
		{
			if (value is string text)
			{
				return NormalizeTextForNewLineChars(text);
			}
			return value;
		}

		public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
		{
			if (value is string text)
			{
				return NormalizeTextForNewLineChars(text);
			}
			return value;
		}
	}
