			Container.Resolve<ILoggerFacade>(Array.Empty<ResolverOverride>()).Log(string.Format(CultureInfo.InvariantCulture, "Registering templates from assembly {0}", assembly.FullName), Category.Info, Priority.Low);
			Type[] types = assembly.GetTypes();
			foreach (Type type in types)
			{
				bool flag = false;
				if (type.IsSubclassOf(typeof(MMTabTemplate)))
				{
					flag = true;
				}
				else if (type.IsSubclassOf(typeof(MMViewModelContainer)))
				{
					object[] customAttributes = type.GetCustomAttributes(typeof(ProgIdAttribute), inherit: false);
					object[] customAttributes2 = type.GetCustomAttributes(typeof(MMBrowserInformationAttribute), inherit: false);
					if (customAttributes != null && customAttributes.Length != 0)
					{
						flag = true;
					}
					else if (customAttributes2 != null && customAttributes2.Length != 0)
					{
						flag = true;
					}
				}
				if (flag)
				{
					RegisterForm(type);
