		private void SetDataBinding()
		{
			if (base.DataGrid != null)
			{
				BindingOperations.ClearBinding(this, DataSourceProperty);
				if (!string.IsNullOrEmpty(DataProperty))
				{
					BindingOperations.SetBinding(this, DataSourceProperty, new Binding(DataProperty));
					BindingOperations.SetBinding(base.DataGrid, UIElement.IsEnabledProperty, new Binding(DataProperty + ".IsEnabled")
					{
						Converter = IsEnabledConverter.Converter
					});
					BindingOperations.SetBinding(base.DataGrid, UIElement.VisibilityProperty, new Binding(DataProperty + ".IsVisible")
					{
