			}
		}

		private static void DataSourceChanged(DependencyObject d, DependencyPropertyChangedEventArgs args)
		{
			MMScrollAreaHorizontal mMScrollAreaHorizontal = d as MMScrollAreaHorizontal;
			if (args.OldValue != null)
			{
				(args.OldValue as INotifyCollectionChanged).CollectionChanged -= mMScrollAreaHorizontal.DataSource_CollectionChanged;
			}
			if (args.NewValue != null)
			{
				(args.NewValue as INotifyCollectionChanged).CollectionChanged += mMScrollAreaHorizontal.DataSource_CollectionChanged;
			}
			mMScrollAreaHorizontal.ResetGridData();
		}

		private void DataSource_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			switch (e.Action)
			{
			case NotifyCollectionChangedAction.Add:
			{
				List<MMScrollAreaField> list = new List<MMScrollAreaField>();
				for (int num = 0; num < e.NewItems.Count; num++)
				{
					int num2 = e.NewStartingIndex + num + 1;
					if (IsUnitsVisible)
					{
						num2++;
					}
					list.Add(InsertShadowField(num2));
					foreach (MMScrollAreaRecord mMRecord in MMRecords)
					{
						foreach (MMScrollAreaField mMField in MMFields)
						{
							InsertFieldsInRow(mMField, mMRecord, e.NewItems, e.NewStartingIndex);
						}
					}
				}
				AddFields(list, e.NewStartingIndex);
				break;
			}
			case NotifyCollectionChangedAction.Remove:
			{
				foreach (object item in e.OldItems)
				{
					MMScrollAreaField mMScrollAreaField = _shadowFields.Where((MMScrollAreaField f) => f.Data == item).First();
					base.DataGrid.DefaultFieldLayout.Fields.Remove(mMScrollAreaField.Field);
					_shadowFields.Remove(mMScrollAreaField);
					RemoveFieldsInRow(e.OldItems);
				}
				break;
			}
			case NotifyCollectionChangedAction.Reset:
				ResetGridData();
				break;
			case NotifyCollectionChangedAction.Replace:
			case NotifyCollectionChangedAction.Move:
				break;
			}
		}

		private void ResetGridData()
		{
			if (base.DataContext == null)
			{
				return;
			}
			int num = 0;
			foreach (Field field in base.DataGrid.DefaultFieldLayout.Fields)
			{
				field.Visibility = Visibility.Collapsed;
				field.Tag = "ToBeDeleted";
				num++;
			}
			InitRecords();
			InitFieldsInDataGrid();
			int num2 = 0;
			while (num2 < base.DataGrid.DefaultFieldLayout.Fields.Count)
			{
				if (base.DataGrid.DefaultFieldLayout.Fields[num2].Tag != null && base.DataGrid.DefaultFieldLayout.Fields[num2].Tag.ToString() == "ToBeDeleted")
				{
					base.DataGrid.DefaultFieldLayout.Fields.RemoveAt(num2);
				}
				else
				{
					num2++;
				}
			}
			_isJustReset = true;
		}

		private void MMFields_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			if (e.Action != NotifyCollectionChangedAction.Add)
			{
				_ = 1;
			}
		}

		protected override void DoClearCell(Cell cell)
		{
			CellValuePresenter parent = CellValuePresenter.FromCell(cell);
			if (Infragistics.Windows.Utilities.GetDescendantFromType(parent, typeof(AesXamValueEdit), allowSubclassOfType: true) is AesXamValueEdit aesXamValueEdit)
			{
				bool isInEditMode = aesXamValueEdit.IsInEditMode;
				if (!isInEditMode)
				{
					aesXamValueEdit.StartEditMode();
				}
				else
				{
					aesXamValueEdit.Focus();
				}
				aesXamValueEdit.Value = null;
				if (!isInEditMode)
				{
					base.Dispatcher.Invoke(new Action<bool, bool>(aesXamValueEdit.EndEditMode), true, false);
				}
			}
			else if (Infragistics.Windows.Utilities.GetDescendantFromType(parent, typeof(AesXamComboEdit), allowSubclassOfType: true) is AesXamComboEdit aesXamComboEdit)
			{
				aesXamComboEdit.Value = null;
			}
			else if (Infragistics.Windows.Utilities.GetDescendantFromType(parent, typeof(AesXamCheckEdit), allowSubclassOfType: true) is AesXamCheckEdit aesXamCheckEdit)
			{
				aesXamCheckEdit.Value = null;
			}
		}

