			return CxsConverter.ValueToBoolean((base.DataContext as MMViewModel).ResolveViewPropertyPath(DataProperty + "[" + GetRowIdFromCell(cell).ToString(CultureInfo.InvariantCulture) + "]." + propertyPath + "." + status, null));
