		protected override void CVP_PreviewKeyDown(KeyEventArgs arg)
		{
			if (arg == null)
			{
				return;
			}
			base.LastKeyPressed = arg.Key;
			switch (arg.Key)
			{
			case Key.C:
				if ((Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control)
				{
					MMScrollAreaManualLayoutCommand.SetClipboardData(this, base.DataGrid.SelectedItems.Fields.Count > 0);
					arg.Handled = true;
				}
				break;
			case Key.V:
				if ((Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control)
				{
					MMScrollAreaManualLayoutCommand.DoPaste(this);
					arg.Handled = true;
				}
				break;
			case Key.Delete:
				if (base.DataGrid.SelectedItems.Fields.Count > 0 && CanDeleteSelectedField())
				{
					DeleteSelectedField();
					arg.Handled = true;
				}
				break;
			}
			bool flag = false;
			if (!arg.Handled)
			{
				flag = MMScrollAreaManualLayoutHelper.ManualLayoutKeyDown(arg, this);
			}
			if (!arg.Handled && flag)
			{
				base.CVP_PreviewKeyDown(arg);
			}
		}

		protected override void DataGrid_PreviewKeyDown(object sender, KeyEventArgs e)
		{
			if (ShouldDataGridRespondKeyDown(e) && e.Key == Key.Tab && base.DataGrid.SelectedItems.Cells.Count == 0 && base.DataGrid.SelectedItems.Records.Count > 0)
			{
				int index = base.DataGrid.SelectedItems.Records[0].Index;
				ClearSelection();
				Cell cell = (base.DataGrid.Records[index] as DataRecord).Cells[0];
				cell.IsSelected = true;
				base.DataGrid.ActiveCell = cell;
				CellValuePresenter.FromCell(cell)?.Focus();
				e.Handled = true;
			}
		}

		internal void DeleteSelectedField()
		{
			AesMessageBoxResult aesMessageBoxResult = AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strConfirmDeleteField, AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteColumn, AesMessageBoxButton.YesNo, AesMessageBoxImage.Question, showHelpButton: false, 2);
			if (aesMessageBoxResult == AesMessageBoxResult.No || aesMessageBoxResult == AesMessageBoxResult.Cancel || DataSource == null)
			{
				return;
			}
			IBindingList dataSource = DataSource;
			if (dataSource == null)
			{
				return;
			}
			List<int> list = new List<int>();
			if (base.DataGrid.SelectedItems.Fields.Count > 0)
			{
				foreach (Field field in base.DataGrid.SelectedItems.Fields)
				{
					list.Add(field.Index);
				}
			}
			else if (base.DataGrid.SelectedItems.Cells.Count > 0)
			{
				list.Add(base.DataGrid.SelectedItems.Cells[0].Field.Index);
			}
			if (list.Count == 0)
			{
				return;
			}
			int num = 0;
			list.Sort();
			foreach (int item in list)
			{
				int current2 = ((!IsUnitsVisible) ? (item - 1) : (item - 2));
				current2 -= num;
				try
				{
					dataSource.RemoveAt(current2);
					num++;
				}
				catch (InvalidOperationException)
				{
				}
				catch (CxsException)
				{
				}
			}
		}

		internal bool CanDeleteSelectedField()
		{
			bool flag = true;
			int num = ((!IsUnitsVisible) ? 1 : 2);
			if (base.DataContext == null || base.DataGrid.SelectedItems.Records.Count > 0)
			{
				flag = false;
			}
			else if ((base.DataContext as MMViewModel).ResolveViewPropertyPath(DataProperty, null) is CxvVectorPropertyData cxvVectorPropertyData)
			{
				if (base.DataGrid.SelectedItems.Fields.Count <= 0)
				{
					flag = base.DataGrid.SelectedItems.Cells.Count == 1 && cxvVectorPropertyData.IndexBasis != null && cxvVectorPropertyData.AllowRemoveAt(base.DataGrid.SelectedItems.Cells[0].Field.Index - num);
				}
				else
				{
					foreach (Field field in base.DataGrid.SelectedItems.Fields)
					{
						if (field.Index < num)
						{
							flag = false;
						}
						flag = cxvVectorPropertyData.IndexBasis != null && cxvVectorPropertyData.AllowRemoveAt(field.Index - num);
						if (!flag)
						{
							break;
						}
					}
				}
			}
			else
			{
				flag = false;
			}
			return flag;
		}

		private void InitRecords()
		{
			MMRecords.Clear();
			if (MMFields == null)
			{
				return;
			}
			foreach (MMScrollAreaField mMField in MMFields)
			{
				mMField.ParentScrollArea = this;
				mMField.ParentScrollAreaActions = this;
				if (!mMField.IsUsed)
				{
					continue;
				}
				MMScrollAreaRecord mMScrollAreaRecord = new MMScrollAreaRecord
				{
					ParentScrollArea = this
				};
				MMScrollAreaTextField mMScrollAreaTextField = new MMScrollAreaTextField
				{
					ParentScrollArea = mMScrollAreaRecord.ParentScrollArea,
					ColumnHeaderTemplate = mMField.ColumnHeaderTemplate
				};
				BindingOperations.SetBinding(mMScrollAreaTextField, MMScrollAreaTextField.TextProperty, new Binding("Label")
				{
					Source = mMField
				});
				mMScrollAreaRecord.Fields.Add(mMScrollAreaTextField);
				if (IsUnitsVisible)
				{
					MMScrollAreaField mMScrollAreaField = null;
					if (mMField is MMScrollAreaValueField mMScrollAreaValueField && !string.IsNullOrEmpty(mMScrollAreaValueField.HeaderUnitsProperty))
					{
						mMScrollAreaField = new MMScrollAreaUnitsField
						{
							ParentScrollArea = mMScrollAreaRecord.ParentScrollArea
						};
						BindingOperations.SetBinding(mMScrollAreaField, MMScrollAreaField.DataProperty, new Binding(mMScrollAreaValueField.HeaderUnitsProperty)
						{
							Source = mMScrollAreaRecord.ParentScrollArea.DataContext
						});
						BindingOperations.SetBinding(mMScrollAreaField, MMScrollAreaField.ResolvedCxsProviderProperty, new Binding("ResolvedCxsProvider")
						{
							Source = mMScrollAreaRecord.ParentScrollArea.DataContext,
							Mode = BindingMode.OneTime
						});
					}
					else
					{
						mMScrollAreaField = new MMScrollAreaTextField
						{
							Text = "",
							ParentScrollArea = mMScrollAreaRecord.ParentScrollArea
						};
					}
					mMScrollAreaField.Id = 1;
					mMScrollAreaRecord.Fields.Add(mMScrollAreaField);
				}
				if (DataSource != null)
				{
					InsertFieldsInRow(mMField, mMScrollAreaRecord, DataSource, (!IsUnitsVisible) ? 1 : 2);
				}
				MMRecords.Add(mMScrollAreaRecord);
			}
		}

		private void InsertFieldsInRow(MMScrollAreaField field, MMScrollAreaRecord record, IEnumerable dataItems, int startingId)
		{
			if (DesignerProperties.GetIsInDesignMode(this))
			{
				return;
			}
			int num = startingId;
			foreach (object dataItem in dataItems)
			{
				MMScrollAreaField mMScrollAreaField = field.Clone() as MMScrollAreaField;
				mMScrollAreaField.Id = num;
				mMScrollAreaField.ColumnHeaderTemplate = null;
				mMScrollAreaField.ParentScrollArea = record.ParentScrollArea;
				MMScrollAreaManualLayoutHelper.SetupDataInField(mMScrollAreaField, dataItem);
				record.Fields.Insert(num, mMScrollAreaField);
				num++;
			}
		}

		private void RemoveFieldsInRow(IEnumerable dataItems)
		{
			foreach (object item in dataItems)
			{
				foreach (MMScrollAreaRecord mMRecord in MMRecords)
				{
					IEnumerable<MMScrollAreaField> source = mMRecord.Fields.Where((MMScrollAreaField f) => f.Data == item);
					mMRecord.Fields.Remove(source.First());
				}
			}
		}

		private void InitFieldsInDataGrid()
		{
			if (DesignerProperties.GetIsInDesignMode(this))
			{
				InsertShadowField(0);
				if (IsUnitsVisible)
				{
					InsertShadowField(1);
				}
			}
			else
			{
				_shadowFields.Clear();
				if (DataSource != null)
				{
					int num = DataSource.Count + 1;
					if (IsUnitsVisible)
					{
						num++;
					}
					for (int i = 0; i < num; i++)
					{
						InsertShadowField(i);
					}
				}
			}
			AddFields(_shadowFields, 0);
			RestoreCustomization();
		}

		private MMScrollAreaField InsertShadowField(int fieldId)
		{
			MMScrollAreaField mMScrollAreaField = new MMScrollAreaField
			{
				IsManualRecordMode = true,
				Id = fieldId
			};
			if (fieldId == 0)
			{
				SetShadowFieldWidth(LabelWidth, mMScrollAreaField);
				mMScrollAreaField.IsFieldFixed = true;
			}
			else if (fieldId == 1 && IsUnitsVisible)
			{
				SetShadowFieldWidth(UnitsWidth, mMScrollAreaField);
				mMScrollAreaField.IsFieldFixed = true;
			}
			else
			{
				int num = fieldId - 1;
				if (IsUnitsVisible)
				{
					num--;
				}
				mMScrollAreaField.Data = DataSource[num];
				SetShadowFieldWidth(FieldWidth, mMScrollAreaField);
			}
			_shadowFields.Add(mMScrollAreaField);
			return mMScrollAreaField;
		}

		private static void SetShadowFieldWidth(double? specifiedWidth, MMScrollAreaField mmfield)
		{
			if (specifiedWidth.HasValue)
			{
				mmfield.Width = specifiedWidth.Value;
				mmfield.MinWidth = specifiedWidth.Value;
				mmfield.IsVisible = specifiedWidth.Value > 0.0;
			}
			else
			{
				mmfield.SetFieldWidth();
			}
		}

		public override string GetActiveScriptingPath()
		{
			return DataProperty;
		}
	}
	internal static class MMScrollAreaManualLayoutHelper
	{
		internal static void MergeManualLayoutStyle(MMScrollAreaBase sa)
		{
			ResourceDictionary resourceDictionary = new ResourceDictionary();
			resourceDictionary.Source = new Uri("pack://application:,,,/AspenTech.AspenPlus.MMControls;Component/Resources/MMScrollAreaManualLayoutStyle.xaml");
			sa.Resources.MergedDictionaries.Add(resourceDictionary);
		}

		internal static void SetupDataInField(MMScrollAreaField field, object source)
		{
			if (!string.IsNullOrEmpty(field.PropertyPath))
			{
				BindingOperations.SetBinding(field, MMScrollAreaField.DataProperty, new Binding(field.PropertyPath)
				{
					Source = source
				});
			}
			if (!string.IsNullOrEmpty(field.IsEnabledBindingPath))
			{
				BindingOperations.SetBinding(field, MMScrollAreaField.IsEnabledProperty, new Binding(field.IsEnabledBindingPath)
				{
					Source = source
				});
			}
			BindingOperations.SetBinding(field, MMScrollAreaField.ResolvedCxsProviderProperty, new Binding("ResolvedCxsProvider")
			{
				Source = source,
				Mode = BindingMode.OneTime
			});
		}

		internal static void SetupFieldLayoutSettingForManualLayout(FieldLayoutSettings setting, MMScrollAreaBase sa)
		{
			if (setting == null)
			{
				setting = new FieldLayoutSettings();
			}
			setting.AutoGenerateFields = false;
			setting.AutoArrangeCells = AutoArrangeCells.Never;
			setting.AllowFieldMoving = AllowFieldMoving.No;
			setting.FixedFieldUIType = FixedFieldUIType.None;
			sa.SetRecordSelectorVisible();
		}

		private static FrameworkElement GetEditingControl(FrameworkElement parent)
		{
			FrameworkElement frameworkElement = parent;
			while (frameworkElement != null && frameworkElement.Name != "PART_editControl" && VisualTreeHelper.GetChildrenCount(frameworkElement) != 0)
			{
				frameworkElement = VisualTreeHelper.GetChild(frameworkElement, 0) as FrameworkElement;
			}
			return frameworkElement;
		}

		internal static void ForceDisplayCellMessage(ValueEditor editor)
		{
			if (editor != null && !editor.IsInEditMode && !editor.IsReadOnly && editor.IsEnabled)
			{
				editor.StartEditMode();
				editor.EndEditMode(acceptChanges: false, force: false);
			}
		}

		internal static bool ManualLayoutKeyDown(KeyEventArgs e, IManualLayout ml)
		{
			ValueEditor activeEditor = (ml as MMScrollAreaBase).GetActiveEditor();
			bool result = true;
			if (activeEditor != null && activeEditor.IsInEditMode)
			{
				switch (e.Key)
				{
				case Key.Tab:
					if ((Keyboard.Modifiers & ModifierKeys.Shift) != ModifierKeys.Shift && activeEditor is AesXamValueEdit)
					{
						if (Infragistics.Windows.Utilities.GetAncestorFromType(activeEditor, typeof(MMVariableEdit), allowSubclassOfType: true) is MMVariableEdit parent && Infragistics.Windows.Utilities.GetDescendantFromType(parent, typeof(AesXamComboEdit), allowSubclassOfType: true) is AesXamComboEdit valueEdit)
						{
							StartEditModeInValueEditor(valueEdit, ml, e);
							result = false;
						}
					}
					else if ((Keyboard.Modifiers & ModifierKeys.Shift) == ModifierKeys.Shift && activeEditor is AesXamComboEdit)
					{
						if (Infragistics.Windows.Utilities.GetAncestorFromType(activeEditor, typeof(MMVariableEdit), allowSubclassOfType: true) is MMVariableEdit parent2)
						{
							StartEditModeInValueEditor(Infragistics.Windows.Utilities.GetDescendantFromType(parent2, typeof(AesXamValueEdit), allowSubclassOfType: true) as AesXamValueEdit, ml, e);
							result = false;
						}
					}
					else
					{
						EndEditMode(ml);
					}
					break;
				case Key.Down:
					if (e.OriginalSource is AesXamComboEdit aesXamComboEdit)
					{
						aesXamComboEdit.IsDropDownOpen = true;
						aesXamComboEdit.Focus();
						e.Handled = true;
						result = false;
					}
					break;
				default:
					result = false;
					break;
				}
			}
			else
			{
				switch (e.Key)
				{
				case Key.Escape:
				{
					CellValuePresenter cVPFromEventSource = GetCVPFromEventSource(e);
					if (cVPFromEventSource != null)
					{
						cVPFromEventSource.Focus();
						e.Handled = true;
					}
					break;
				}
				case Key.F2:
					if (e.OriginalSource.GetType() == typeof(CellValuePresenter))
					{
						StartEditModeInCVP(e.OriginalSource as CellValuePresenter, ml, e);
					}
					else if (e.OriginalSource.GetType() == typeof(ValueEditor))
					{
						StartEditModeInValueEditor(e.OriginalSource as ValueEditor, ml, e);
					}
					break;
				}
			}
			return result;
		}

		private static CellValuePresenter GetCVPFromEventSource(KeyEventArgs e)
		{
			CellValuePresenter cellValuePresenter = null;
			if (e.OriginalSource.GetType() == typeof(CellValuePresenter))
			{
				return e.OriginalSource as CellValuePresenter;
			}
			return Infragistics.Windows.Utilities.GetAncestorFromType(e.OriginalSource as DependencyObject, typeof(CellValuePresenter), allowSubclassOfType: false) as CellValuePresenter;
		}

		internal static bool StartEditModeInValueEditor(ValueEditor valueEdit, IManualLayout sa, KeyEventArgs e)
		{
			if (valueEdit == null || valueEdit.Visibility != Visibility.Visible || valueEdit.IsReadOnly || !valueEdit.IsEnabled)
			{
				return false;
			}
			if (valueEdit.IsInEditMode)
			{
				return false;
			}
			sa.ActiveEditor = valueEdit;
			valueEdit.Focus();
			valueEdit.StartEditMode();
			e.Handled = true;
			return true;
		}

		private static bool StartEditModeInCVP(CellValuePresenter cvp, IManualLayout sa, KeyEventArgs e)
		{
			if (Infragistics.Windows.Utilities.GetDescendantFromType(cvp, typeof(MMVariableEdit), allowSubclassOfType: true) is MMVariableEdit varEdit && StartEditModeInVariableEdit(varEdit, sa, e))
			{
				return true;
			}
			if (Infragistics.Windows.Utilities.GetDescendantFromType(cvp, typeof(ValueEditor), allowSubclassOfType: true) is ValueEditor valueEdit && StartEditModeInValueEditor(valueEdit, sa, e))
			{
				return true;
			}
			return false;
		}

		private static bool StartEditModeInVariableEdit(MMVariableEdit varEdit, IManualLayout sa, KeyEventArgs e)
		{
			if (Infragistics.Windows.Utilities.GetDescendantFromType(varEdit, typeof(AesBasisEdit), allowSubclassOfType: true) is AesBasisEdit { Visibility: Visibility.Visible, IsEnabled: not false, IsReadOnly: false } aesBasisEdit && StartEditModeInValueEditor(Infragistics.Windows.Utilities.GetDescendantFromType(aesBasisEdit, typeof(AesXamComboEdit), allowSubclassOfType: true) as AesXamComboEdit, sa, e))
			{
				return true;
			}
			if (Infragistics.Windows.Utilities.GetDescendantFromType(varEdit, typeof(AesValueEdit), allowSubclassOfType: true) is AesValueEdit { Visibility: Visibility.Visible, IsEnabled: not false, IsReadOnly: false } aesValueEdit && StartEditModeInValueEditor(Infragistics.Windows.Utilities.GetDescendantFromType(aesValueEdit, typeof(AesXamValueEdit), allowSubclassOfType: true) as AesXamValueEdit, sa, e))
			{
				return true;
			}
			if (Infragistics.Windows.Utilities.GetDescendantFromType(varEdit, typeof(AesUnitsEdit), allowSubclassOfType: true) is AesUnitsEdit { Visibility: Visibility.Visible, IsEnabled: not false, IsReadOnly: false } aesUnitsEdit && StartEditModeInValueEditor(Infragistics.Windows.Utilities.GetDescendantFromType(aesUnitsEdit, typeof(AesXamComboEdit), allowSubclassOfType: true) as AesXamComboEdit, sa, e))
			{
				return true;
			}
			return false;
		}

		internal static void CVPPreviewMouseDown(CellValuePresenter cvp, MMScrollAreaBase sab, MouseButtonEventArgs e)
		{
			if (sab == null)
			{
				return;
			}
			sab.LastKeyPressed = null;
			if (!(sab is IManualLayout manualLayout))
			{
				return;
			}
			if (e.ChangedButton == MouseButton.Left)
			{
				bool flag = (Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control;
				bool flag2 = (Keyboard.Modifiers & ModifierKeys.Shift) == ModifierKeys.Shift;
				if (e.ClickCount == 1 && Infragistics.Windows.Utilities.GetDescendantFromType(cvp, typeof(AesXamValueEdit), allowSubclassOfType: false) is AesXamValueEdit { IsInEditMode: false, IsInScrollArea: not false })
				{
					bool flag3 = true;
					if (e.OriginalSource is DependencyObject descendant && Infragistics.Windows.Utilities.GetAncestorFromType(descendant, typeof(AesXamComboEdit), allowSubclassOfType: false) is AesXamComboEdit)
					{
						flag3 = false;
					}
					if (flag3)
					{
						e.Handled = true;
					}
				}
				if (manualLayout.ActiveEditor != null)
				{
					CellValuePresenter cellValuePresenter = Infragistics.Windows.Utilities.GetAncestorFromType(manualLayout.ActiveEditor, typeof(CellValuePresenter), allowSubclassOfType: false) as CellValuePresenter;
					if (cvp == cellValuePresenter)
					{
						return;
					}
				}
				if (flag2)
				{
					if (sab is MMScrollAreaHorizontal saHorizontal)
					{
						AddCellsToSelectionForMMScrollAreaHorizontal(cvp, saHorizontal);
					}
					else
					{
						AddCellsToSelection(cvp, sab);
					}
				}
				else
				{
					SetSelectionToCurrentCVP(cvp, sab, !flag);
				}
				if (flag || flag2)
				{
					e.Handled = true;
				}
				else if (Infragistics.Windows.Utilities.GetDescendantFromType(cvp, typeof(AesXamComboEdit), allowSubclassOfType: false) is AesXamComboEdit { IsInScrollArea: not false } aesXamComboEdit)
				{
					manualLayout.ActiveEditor = aesXamComboEdit;
				}
				else if (Infragistics.Windows.Utilities.GetDescendantFromType(cvp, typeof(AesXamValueEdit), allowSubclassOfType: false) is AesXamValueEdit { IsInScrollArea: not false } aesXamValueEdit2)
				{
					manualLayout.ActiveEditor = aesXamValueEdit2;
				}
				else
				{
					manualLayout.ActiveEditor = null;
				}
			}
			else
			{
				if (e.ChangedButton != MouseButton.Right)
				{
					return;
				}
				if (manualLayout.ActiveEditor == null)
				{
					MMScrollAreaContextMenu.OnCellContextMenuOpening(cvp, null);
					e.Handled = true;
					return;
				}
				ValueEditor activeEditor = manualLayout.ActiveEditor;
				if (activeEditor != null)
				{
					if (!activeEditor.IsInEditMode)
					{
						MMScrollAreaContextMenu.OnCellContextMenuOpening(cvp, null);
						e.Handled = true;
					}
					else if (Infragistics.Windows.Utilities.GetDescendantFromType(cvp, typeof(AesXamValueEdit), allowSubclassOfType: false) is AesXamValueEdit aesXamValueEdit3 && aesXamValueEdit3 != activeEditor)
					{
						activeEditor.EndEditMode(acceptChanges: true, force: false);
						MMScrollAreaContextMenu.OnCellContextMenuOpening(cvp, null);
						e.Handled = true;
					}
				}
			}
		}

		private static void AddCellsToSelection(CellValuePresenter cvp, MMScrollAreaBase sab)
		{
			Cell activeCell = sab.DataGrid.ActiveCell;
			if (activeCell == null)
			{
				return;
			}
			sab.ClearSelection();
			System.Windows.Point point = new System.Windows.Point(Math.Min(activeCell.Field.ActualPosition.Column, cvp.Field.ActualPosition.Column), Math.Min(activeCell.Record.Index, cvp.Record.Index));
			System.Windows.Point point2 = new System.Windows.Point(Math.Max(activeCell.Field.ActualPosition.Column, cvp.Field.ActualPosition.Column), Math.Max(activeCell.Record.Index, cvp.Record.Index));
			for (int i = (int)point.Y; i <= (int)point2.Y; i++)
			{
				for (int j = (int)point.X; j <= (int)point2.X; j++)
				{
					(sab.DataGrid.Records[i] as DataRecord).Cells[j].IsSelected = true;
				}
			}
			activeCell.IsActive = true;
		}

		private static void AddCellsToSelectionForMMScrollAreaHorizontal(CellValuePresenter cvp, MMScrollAreaHorizontal saHorizontal)
		{
			Cell activeCell = saHorizontal.DataGrid.ActiveCell;
			if (activeCell == null)
			{
				return;
			}
			saHorizontal.ClearSelection();
			System.Windows.Point point = new System.Windows.Point(Math.Min(activeCell.Field.Column, cvp.Field.Column), Math.Min(activeCell.Record.Index, cvp.Record.Index));
			System.Windows.Point point2 = new System.Windows.Point(Math.Max(activeCell.Field.Column, cvp.Field.Column), Math.Max(activeCell.Record.Index, cvp.Record.Index));
			for (int i = (int)point.Y; i <= (int)point2.Y; i++)
			{
				for (int j = (int)point.X; j <= (int)point2.X; j++)
				{
					(saHorizontal.DataGrid.Records[i] as DataRecord).Cells[j].IsSelected = true;
				}
			}
			activeCell.IsActive = true;
		}

		private static void SetSelectionToCurrentCVP(CellValuePresenter cvp, MMScrollAreaBase sab, bool clearSelection)
		{
			if (clearSelection)
			{
				sab.ClearSelection();
			}
			try
			{
				cvp.Record.Cells[cvp.Field].IsSelected = true;
				cvp.Record.Cells[cvp.Field].IsActive = true;
			}
			catch (Exception)
			{
			}
		}

		internal static void EndEditMode(IManualLayout ml)
		{
			if (ml.ActiveEditor != null)
			{
				if (ml.ActiveEditor is AesXamComboEdit aesXamComboEdit)
				{
					aesXamComboEdit.EndEditMode(acceptChanges: true, force: true);
					ml.ActiveEditor = null;
				}
				else if (ml.ActiveEditor is AesXamValueEdit aesXamValueEdit)
				{
					aesXamValueEdit.EndEditMode(acceptChanges: true, force: true);
					ml.ActiveEditor = null;
				}
				else if (ml.ActiveEditor is AesXamCheckEdit aesXamCheckEdit)
				{
					aesXamCheckEdit.EndEditMode(acceptChanges: true, force: true);
					ml.ActiveEditor = null;
				}
			}
		}
	}
