		private string CustomizationKey
		{
			get
			{
				if (_CustomizationKey == null)
				{
					if (!(base.DataContext is MMViewModel mMViewModel))
					{
						return null;
					}
					CxvVectorPropertyData firstLevelVectorData = FirstLevelVectorData;
					if (firstLevelVectorData == null || firstLevelVectorData.IndexBasis == null)
					{
						return null;
					}
					CxvChildCountIndexBasisData cxvChildCountIndexBasisData = firstLevelVectorData.IndexBasis as CxvChildCountIndexBasisData;
					string text = "";
					if (cxvChildCountIndexBasisData != null)
					{
						text = mMViewModel.ExpandDataPath(cxvChildCountIndexBasisData.IndexBasis.DataPath, null);
					}
					string formProgId = GetFormProgId();
					if (formProgId == null)
					{
						return null;
					}
					if (base.Name == null)
					{
						return null;
					}
					_CustomizationKey = formProgId + "/" + base.Name + "/" + text;
				}
				return _CustomizationKey;
			}
		}

		private ScrollAreaCustomization MyCustomization
		{
			get
			{
				if (_MyCustomization == null)
				{
					if (CustomizationKey == null)
					{
						return null;
					}
					if (!SACustomizations.ContainsKey(CustomizationKey))
					{
						_MyCustomization = new ScrollAreaCustomization();
						SACustomizations.Add(CustomizationKey, _MyCustomization);
					}
					else
					{
						_MyCustomization = SACustomizations[CustomizationKey];
					}
				}
				return _MyCustomization;
			}
		}

		bool IMMScrollAreaPlot.HasVisibleFieldsToCreatePlot
		{
			get
			{
				int num = 0;
				if (DataTable != null && DataTable.Rows.Count > 1)
				{
					foreach (BindingDataColumn key in DataColumnMap.Keys)
					{
						if (key.Visibility != Visibility.Visible)
						{
							continue;
						}
						IDataCell dataCell = DataTable.Rows[0][key];
						bool flag = false;
						if (dataCell == null || dataCell.Value == null)
						{
							for (int i = 1; i < DataTable.Rows.Count; i++)
							{
								dataCell = DataTable.Rows[i][key];
								if (dataCell != null && dataCell.Value != null)
								{
									flag = true;
									break;
								}
							}
						}
						else
						{
							flag = true;
						}
						if (flag && double.TryParse(dataCell.Value.ToString(), out var _) && key.DisplayIndex >= 0)
						{
							num++;
							if (num > 1)
							{
								return true;
							}
						}
					}
				}
				return false;
			}
		}

