		private CxvVectorPropertyData SecondLevelVectorData
		{
			get
			{
				if (MMFields == null)
				{
					return null;
				}
				CxvPropertyWatch cxvPropertyWatch = new CxvPropertyWatch();
				foreach (MMScrollAreaField mMField in MMFields)
				{
					if (mMField is MMScrollAreaFieldRepeater mMScrollAreaFieldRepeater)
					{
						CxvVectorPropertyData cxvVectorPropertyData = null;
						if (!string.IsNullOrEmpty(mMScrollAreaFieldRepeater.SecondLevelVectorProperty))
						{
							cxvVectorPropertyData = cxvPropertyWatch.ResolvePropertyPath(this, string.Format(CultureInfo.InvariantCulture, "DataContext.{0}[0].{1}", DataProperty, mMScrollAreaFieldRepeater.SecondLevelVectorProperty)) as CxvVectorPropertyData;
						}
						else if (!string.IsNullOrEmpty(mMScrollAreaFieldRepeater.CountPath))
						{
							cxvVectorPropertyData = cxvPropertyWatch.ResolvePropertyPath(this, "DataContext." + mMScrollAreaFieldRepeater.CountPath.Replace(".Count", "")) as CxvVectorPropertyData;
						}
						if (cxvVectorPropertyData != null)
						{
							return cxvVectorPropertyData;
						}
					}
				}
				return null;
			}
		}

