		public bool AllowReorderResolved1st
		{
			get
			{
				if (!_AllowReorderResolved1st.HasValue)
				{
					if (AllowReorder.HasValue)
					{
						_AllowReorderResolved1st = AllowReorder.Value;
					}
					else if (base.DataContext is MMViewModel container && DataProperty != null)
					{
						bool? flag = CxsConverter.ValueToBoolean(container.ResolveViewPropertyPath(DataProperty + ".AllowReorder"));
						if (flag.HasValue)
						{
							_AllowReorderResolved1st = flag.Value;
						}
					}
					else
					{
						_AllowReorderResolved1st = false;
					}
				}
				return _AllowReorderResolved1st ?? false;
			}
		}

		public bool AllowReorderResolved2nd
		{
			get
			{
				bool result = false;
				if (AllowReorder.HasValue)
				{
					result = AllowReorder.Value;
				}
				else if (base.DataContext is MMViewModel container && DataProperty != null)
				{
					MMScrollAreaFieldRepeater firstRepeaterField = GetFirstRepeaterField();
					if (firstRepeaterField != null && firstRepeaterField.SecondLevelVectorProperty != null)
					{
						bool? flag = CxsConverter.ValueToBoolean(container.ResolveViewPropertyPath($"{DataProperty}[0].{firstRepeaterField.SecondLevelVectorProperty}.AllowReorder"));
						if (flag.HasValue)
						{
							result = flag.Value;
						}
					}
				}
				else
				{
					result = false;
				}
				return result;
			}
		}

