		public bool HasReadOnlyField
		{
			get
			{
				if (MMFields.FirstOrDefault((MMScrollAreaField x) => x is MMScrollAreaReadOnlyField) != null)
				{
					return true;
				}
				IEnumerable<MMScrollAreaField> enumerable = MMFields.Where((MMScrollAreaField vfield) => vfield is MMScrollAreaFieldRepeater);
				if (enumerable != null && enumerable.Count() > 0)
				{
					foreach (MMScrollAreaFieldRepeater item in enumerable)
					{
						if (item.Fields.FirstOrDefault((MMScrollAreaField x) => x is MMScrollAreaReadOnlyField) != null)
						{
							return true;
						}
					}
				}
				return false;
			}
		}

