		private void DoDefaultCopy(GridControlCopyEventArgs e)
		{
			int num = DataGrid.TotalOrderedSelectedCells.Count();
			if (MaxinumCopiedCellCount.HasValue && num > MaxinumCopiedCellCount)
			{
				MMViewModel obj = ViewModel as MMViewModel;
				ShowMMMessageBoxEventArgs args = new ShowMMMessageBoxEventArgs
				{
					Message = string.Format(AspenTech.AspenPlus.MMControls.Properties.Resources.ExceedMaxCopyCount, MaxinumCopiedCellCount) + Environment.NewLine + AspenTech.AspenPlus.MMControls.Properties.Resources.Too_Large_Copy_Msg_part3 + num,
					MsgBoxButton = 0,
					MsgBoxImage = 48,
					DialogResult = 1,
					Title = AspenTech.AspenPlus.MMControls.Properties.Resources.Unsupported_Copy_Operation
				};
				obj.ShowMMMessageBox(args);
				e.Handled = true;
				return;
			}
			MMScrollAreaDataCopyEventArgs e2 = new MMScrollAreaDataCopyEventArgs(this, e, DataCopyingEvent, this);
			OnDataCopying(e2);
			if (e2.Handled)
			{
				e.Handled = true;
			}
			if (e.Handled)
			{
				return;
			}
			e.Handled = true;
			if (ClipboardDataObject != null)
			{
				ClipboardDataObject.Dispose();
			}
			ClipboardDataObject = new MMScrollAreaMSClipboard();
			DataColumn dataColumn = DataGrid.SelectedColumns.FirstOrDefault();
			ClipboardDataObject.IncludeColumnHeader = dataColumn != null;
			List<IGridCellData> list = ClipboardDataObject.SetDataBatchGet(typeof(MMScrollAreaMS), this, e.IsAllSelected);
			if (list == null)
			{
				return;
			}
			bool removeProxyRow = false;
			if (e.IsAllSelected && DataOrientation == Orientation.Vertical)
			{
				CxvVectorPropertyData firstLevelVectorData = FirstLevelVectorData;
				if (firstLevelVectorData != null && firstLevelVectorData.IndexBasis is CxvChildCountIndexBasisData { HasProxyRow: not false })
				{
					int num2 = DataGrid.SelectedColumns.Count();
					int count = list.Count;
					list.RemoveRange(count - num2, num2);
					removeProxyRow = true;
				}
			}
			ClipboardDataObject.SetPlainTextAsCopyResult(e, list, removeProxyRow);
			ClipboardWrapper.SetDataObject(ClipboardDataObject, copy: false);
		}

		public Collection<string> GenerateSelectAllCXSPaths()
		{
			int count = DataTable.Rows.Count;
			MMViewModel mMViewModel = ((base.DataContext as MMViewModel).ResolveViewPropertyPath(DataProperty) as CxvVectorPropertyData)[0] as MMViewModel;
			List<string> list = new List<string>();
			List<MMScrollAreaField> list2 = new List<MMScrollAreaField>();
			if (DataOrientation == Orientation.Horizontal)
			{
				if (MMFields.Count != DataTable.Rows.Count)
				{
					return null;
				}
				list2 = MMFields.ToList();
			}
			else
			{
				foreach (DataColumn orderedSelectedColumn in DataGrid.OrderedSelectedColumns)
				{
					list2.Add(DataColumnMap[orderedSelectedColumn as BindingDataColumn]);
				}
			}
			foreach (MMScrollAreaField item in list2)
			{
				object obj = mMViewModel.ResolveViewPropertyPath(item.PropertyPath);
				if (obj == null)
				{
					continue;
				}
				if (obj is CxvVariableData cxvVariableData)
				{
					string[] array = (cxvVariableData.Property as CxvVariableProperty).DataPath.Split('.');
					int num = -1;
					foreach (CxvParameter parameter in mMViewModel.Parameters)
					{
						for (int i = 0; i < array.Length; i++)
						{
							if (array[i] == "@" + parameter.Name)
							{
								num = array.Length - 1 - i;
								break;
							}
						}
					}
					string dataPath = cxvVariableData.DataPath;
					string text = null;
					if (num <= 0)
					{
						text = ((cxvVariableData.DataPath[cxvVariableData.DataPath.LastIndexOf(".") + 1] != '#') ? ("cxs:" + cxvVariableData.DataPath.Substring(0, cxvVariableData.DataPath.LastIndexOf(".") + 1) + "REPLACE_ME") : ("cxs:" + cxvVariableData.DataPath.Substring(0, cxvVariableData.DataPath.LastIndexOf(".") + 1) + "#REPLACE_ME"));
					}
					else
					{
						text = "cxs:";
						array = dataPath.Split('.');
						for (int j = 0; j < array.Length; j++)
						{
							if (j + 1 + num == array.Length)
							{
								if (array[j].StartsWith("#"))
								{
									text += "#";
								}
								text += "REPLACE_ME";
							}
							else
							{
								text += array[j];
							}
							if (j != array.Length - 1)
							{
								text += ".";
							}
						}
					}
					if (cxvVariableData != null && (cxvVariableData.ResolvedExposeAs == CxvVariableTypeCode.IdWithOptions || cxvVariableData.ResolvedExposeAs == CxvVariableTypeCode.Id))
					{
						text = "ID:" + text;
					}
					list.Add(text);
				}
				else if (obj is CxvMultiMapPropertyData)
				{
					CxvMultiMapPropertyData cxvMultiMapPropertyData = obj as CxvMultiMapPropertyData;
					list.Add(cxvMultiMapPropertyData.CxsItemMoniker.Substring(0, cxvMultiMapPropertyData.CxsItemMoniker.LastIndexOf(".") + 1) + "REPLACE_ME");
				}
				else if (obj is CxvParameterPropertyData cxvParameterPropertyData && cxvParameterPropertyData.Value.ToString() == "1")
				{
					list.Add("N");
				}
				else
				{
					list.Add("U");
				}
			}
			List<string> list3 = null;
			if (DataOrientation == Orientation.Vertical)
			{
				list3 = new List<string>(list.Count * count);
				for (int k = 1; k <= count; k++)
				{
					for (int l = 0; l < list.Count; l++)
					{
						if (list[l].StartsWith("cxs:") || list[l].StartsWith("ID:"))
						{
							list3.Add(list[l].Replace("REPLACE_ME", k.ToString()));
						}
						else if (list[l].StartsWith("N"))
						{
							list3.Add(k.ToString());
						}
						else
						{
							list3.Add(string.Empty);
						}
					}
				}
			}
			else
			{
				list3 = new List<string>(list.Count * DataTable.Columns.Count + 1);
				for (int m = 0; m < list.Count; m++)
				{
					list3.Add(MMFields[m].Label);
					for (int n = 0; n < DataTable.Columns.Count - 2; n++)
					{
						if (list[m].StartsWith("cxs:") || list[m].StartsWith("ID:"))
						{
							list3.Add(list[m].Replace("REPLACE_ME", n.ToString()));
						}
						else if (list[m].StartsWith("N"))
						{
							list3.Add(n.ToString());
						}
						else
						{
							list3.Add(string.Empty);
						}
					}
					list3.Add(string.Empty);
				}
			}
			return new Collection<string>(list3);
		}

		public Collection<string> GetSelectedCellCopyValuesCXS(bool generateCXSPathsFromFields = false)
		{
			MMScrollAreaMSClipboard mMScrollAreaMSClipboard = new MMScrollAreaMSClipboard();
			Collection<string> collection = null;
			collection = ((!generateCXSPathsFromFields) ? mMScrollAreaMSClipboard.GetMonikersForSelectedCopyVariables(this) : GenerateSelectAllCXSPaths());
			if (collection == null || (collection != null && collection.Count < 1))
			{
				return null;
			}
			CxsBatchRequestData cxsBatchRequestData = new CxsBatchRequestData();
			foreach (string item in collection)
			{
				if (item.StartsWith("cxs:"))
				{
					cxsBatchRequestData.AddRequest(item.Substring(4), "value");
				}
				else if (item.StartsWith("ID:"))
				{
					cxsBatchRequestData.AddRequest(item.Substring(7), "id");
				}
			}
			object[] array = ViewModel.ResolvedCxsProvider.LargeBatchGet(cxsBatchRequestData, showProgressIndicator: true);
			Collection<string> collection2 = new Collection<string>();
			int num = 0;
			for (int i = 0; i < collection.Count; i++)
			{
				if (collection[i].StartsWith("cx") || collection[i].StartsWith("ID"))
				{
					if (array[num] != null)
					{
						if (array[num].GetType() == typeof(string))
						{
							if (((string)array[num])[0] != '#')
							{
								collection2.Add((string)array[num]);
							}
							else
							{
								collection2.Add(string.Empty);
							}
						}
						else
						{
							collection2.Add(array[num].ToString());
						}
					}
					else
					{
						collection2.Add(string.Empty);
					}
					num++;
				}
				else
				{
					collection2.Add(collection[i]);
				}
			}
			return collection2;
		}

		public static void CopyAllVariables(MMScrollAreaMS sa, ICollection<string> monikers)
		{
			if (sa == null || monikers == null)
			{
				return;
			}
			Collection<string> monikersForCopyVariables = new MMScrollAreaMSClipboard().GetMonikersForCopyVariables(sa);
			if (monikersForCopyVariables == null)
			{
				return;
			}
			for (int i = 0; i < monikersForCopyVariables.Count; i++)
			{
				if (string.IsNullOrEmpty(monikersForCopyVariables[i]) || monikers.Contains(monikersForCopyVariables[i]))
				{
					monikersForCopyVariables[i] = null;
				}
			}
			for (int j = 0; j < monikersForCopyVariables.Count; j++)
			{
				if (monikersForCopyVariables[j] != null)
				{
					monikers.Add(monikersForCopyVariables[j]);
				}
			}
		}

