		private void AddCustomContextMenu(DefaultContextMenuEventArgs e)
		{
			if (CustomContextMenu == null || !CustomContextMenu.HasItems)
			{
				return;
			}
			if (e.DefaultContextMenu.Items.Count > 0)
			{
				e.DefaultContextMenu.Items.Add(new Separator());
