						Command = menuItem.Command,
						CommandParameter = menuItem.CommandParameter,
						CommandTarget = menuItem.CommandTarget,
						DataContext = menuItem.DataContext
					};
					if (menuItem.CommandBindings != null && menuItem.CommandBindings.Count > 0)
					{
						menuItem2.CommandBindings.AddRange(menuItem.CommandBindings);
					}
					e.DefaultContextMenu.Items.Add(menuItem2);
