		private void _DataGrid_CanPasteChecking(object sender, GridControlCanPasteEventArgs arg)
		{
			if (PasteCommand != null)
			{
				arg.CanPaste = PasteCommand.CanExecute(null);
				arg.Handled = true;
				return;
			}
			MMScrollAreaCanPasteCheckingEventArgs e = new MMScrollAreaCanPasteCheckingEventArgs(this, arg, CanPasteCheckingEvent);
			OnCanPasteChecking(e);
			if (e.Handled)
			{
				arg.CanPaste = e.CanPaste;
				arg.Handled = true;
				return;
			}
			if (IsReadOnly)
			{
				arg.CanPaste = false;
				return;
			}
			if (DataRetriever is ReadOnlyViewModelDataRetriever)
			{
				arg.CanPaste = false;
				return;
			}
			DataTable dataTable = DataTable;
			if (dataTable != null && dataTable.Columns.All((DataColumn x) => x.IsReadOnly))
			{
				arg.CanPaste = false;
				return;
			}
			bool canPaste = false;
			if (ClipboardWrapper.GetData(DataFormats.Text) == null)
			{
				arg.CanPaste = false;
				return;
			}
			if (!(sender is GridControl gridControl))
			{
				canPaste = false;
			}
			else if (gridControl.TotalSelectedCells != null)
			{
				foreach (DataCellInfo totalSelectedCell in gridControl.TotalSelectedCells)
				{
					if (totalSelectedCell.Column.IsReadOnly)
					{
						continue;
					}
					if (totalSelectedCell.Data != null && !totalSelectedCell.Data.IsReadOnly)
					{
						canPaste = true;
						break;
					}
					if (totalSelectedCell.Data == null)
					{
						continue;
					}
					object cellBindingVariable = GetCellBindingVariable(totalSelectedCell);
					if (cellBindingVariable is CxvVariableData { IsEnabled: var isEnabled } cxvVariableData)
					{
						if ((isEnabled ?? true) && !cxvVariableData.IsReadOnly)
						{
							canPaste = true;
							break;
						}
					}
					else if (cellBindingVariable is CxvParameterPropertyData { IsReadOnly: false })
					{
						canPaste = true;
						break;
					}
				}
			}
			arg.CanPaste = canPaste;
		}

