		private bool CanPasteAtSelectedCells(GridControlPastingEventArgs args)
		{
			NumberSelectionInfo selectionInfo = args.SelectionInfo;
			string messageBoxText = string.Empty;
			IList<IList<string>> pastingData = args.PastingData;
			bool flag = true;
			int num = selectionInfo.SelectedColumnsCount * selectionInfo.SelectedRowsCount;
			int num2 = pastingData[0].Count * pastingData.Count;
			bool flag2 = selectionInfo.SelectedColumnsCount == DataGrid.DataSource.Columns.Count;
			bool flag3 = pastingData[0].Count + selectionInfo.StartColumnIndex <= DataGrid.DataSource.Columns.Count;
			bool flag4 = pastingData.Count + selectionInfo.StartRowIndex <= DataGrid.DataSource.Rows.Count;
			bool flag5 = pastingData.Count <= selectionInfo.SelectedRowsCount;
			bool flag6 = pastingData[0].Count <= selectionInfo.SelectedColumnsCount;
			if (num2 <= num)
			{
				selectionInfo.SelectedRowsCount = pastingData.Count;
				selectionInfo.SelectedColumnsCount = pastingData[0].Count;
				if (!flag6 || !flag5)
				{
					messageBoxText = AspenTech.AspenPlus.MMControls.Properties.Resources.GridControl_ClipBoardHelper_RangeMismatchCells;
					flag = false;
				}
				if (flag2)
				{
					selectionInfo.StartColumnIndex = DataGrid.CurrentCell.Column.Index;
					flag3 = pastingData[0].Count + selectionInfo.StartColumnIndex <= DataGrid.DataSource.Columns.Count;
					flag = flag3 || args.UserExtendTable;
				}
				if (!flag3 && !args.UserExtendTable && !flag)
				{
					messageBoxText = AspenTech.AspenPlus.MMControls.Properties.Resources.GridControl_ClipBoardHelper_CellsExcedRange;
					flag = false;
				}
			}
			else
			{
				if (args.UserExtendTable)
				{
					return true;
				}
				if (!flag3 || !flag4)
				{
					messageBoxText = AspenTech.AspenPlus.MMControls.Properties.Resources.GridControl_ClipBoardHelper_CellsExcedRange;
					flag = false;
				}
				else if (!flag5 || !flag6)
				{
					messageBoxText = AspenTech.AspenPlus.MMControls.Properties.Resources.GridControl_ClipBoardHelper_RangeMismatchCells;
					flag = num == 1;
				}
				else
				{
					messageBoxText = AspenTech.AspenPlus.MMControls.Properties.Resources.GridControl_ClipBoardHelper_RangeExcedCells;
					flag = false;
				}
			}
			if (!flag)
			{
				MessageBox.Show(messageBoxText, AspenTech.AspenPlus.MMControls.Properties.Resources.GridNameDialog_InvalidName_Title, MessageBoxButton.OK, MessageBoxImage.Exclamation);
			}
			return flag;
		}

		private void _DataGrid_DataPasting(object sender, GridControlPastingEventArgs e)
		{
			if (PasteCommand != null)
			{
				PasteCommand.Execute(null);
				e.Handled = true;
			}
			else
			{
				if (CxsProvider == null)
				{
					return;
				}
				MMScrollAreaDataPasteEventArgs e2 = new MMScrollAreaDataPasteEventArgs(this, e, DataPastingEvent, this);
				OnDataPasting(e2);
				if (e2.Handled)
				{
					e.Handled = true;
					return;
				}
				IList<IList<string>> pastingData = e.PastingData;
				int num = 0;
				int count = pastingData.Count;
				foreach (IList<string> item in pastingData)
				{
					if (item.Count > num)
					{
						num = item.Count;
					}
				}
				DataCellInfo dataCellInfo = DataGrid.TotalOrderedSelectedCells.FirstOrDefault();
				int num2 = DataTable.Rows.IndexOf(dataCellInfo.Row);
				int num3 = DataTable.Columns.IndexOf(dataCellInfo.Column);
				FixVariableDataToPaste(pastingData, count, num, num2, num3);
				bool flag = false;
				bool flag2 = false;
				bool flag3 = false;
				if (DataTable.Rows.Count - num2 < count)
				{
					if (DataOrientation == Orientation.Vertical)
					{
						e.Cancel = AddRecords(num2 + count + 1, DataTable.Rows.Count, FirstLevelVectorData);
						flag3 = true;
					}
					if (!e.Cancel)
					{
						flag = true;
						e.TryOnceMoreAfterRender = true;
						e.UserExtendTable = true;
					}
					flag2 = true;
				}
				if (DataTable.Columns.Count - num3 < num)
				{
					if (DataOrientation == Orientation.Vertical)
					{
						e.Cancel = AddRecords(num + num3 + 1, DataTable.Columns.Count, SecondLevelVectorData, !flag3);
					}
					else
					{
						e.Cancel = AddRecords(num + num3 + 1, DataTable.Columns.Count, FirstLevelVectorData);
					}
					if (!e.Cancel)
					{
						flag = true;
						e.TryOnceMoreAfterRender = true;
						e.UserExtendTable = true;
					}
					flag2 = true;
				}
				if (!e.Cancel)
				{
					if (flag)
					{
						CxsProvider.UpdateDataCache();
					}
					if (ViewModel.ToString() == "AspenTech.AspenPlus.MMForms.PhysicalProperties.Parameters.Pure_Components.T_Dependent.MMParam_PureCor_In_Para_ViewModel")
					{
						new MMScrollAreaMSClipboard().PasteVariableDataToSelection(this, pastingData, num2, num3, copyUnitless: true);
						e.Cancel = true;
					}
					if (DelayPasting)
					{
						e.ShouldDelayPasting = true;
					}
					else
					{
						e.ShouldDelayPasting = flag2 && DataRetriever == null;
					}
					if (!CanPasteAtSelectedCells(e))
					{
						e.Handled = true;
						e.Cancel = true;
					}
				}
			}
		}

		private void FixVariableDataToPaste(IList<IList<string>> data, int rowCount, int colCount, int topleftRowId, int topleftColId)
		{
			string asiFormatTextFromClipboard = ClipboardHelper.GetAsiFormatTextFromClipboard();
			if (string.IsNullOrEmpty(asiFormatTextFromClipboard))
			{
				return;
			}
			XElement xElement = null;
			try
			{
				xElement = XElement.Parse(asiFormatTextFromClipboard);
			}
			catch
			{
			}
			if (xElement == null)
			{
				return;
			}
			for (int i = 0; i < colCount; i++)
			{
				int displayIndex = topleftColId + i;
				if (!(DataGrid.ColumnFromDisplayIndex(displayIndex) is MMScrollAreaMSDataColumn mMScrollAreaMSDataColumn) || !(mMScrollAreaMSDataColumn.Field is MMScrollAreaBrowseField))
				{
					continue;
				}
				for (int j = 0; j < rowCount; j++)
				{
					IList<string> list = data[j];
					if (list.Count >= i)
					{
						string value = ExtractVariablePath(xElement, j, i, list[i]);
						if (!string.IsNullOrEmpty(value))
						{
							list[i] = value;
						}
					}
				}
			}
		}

		private void FixVariableDataToPaste(IList<IList<string>> data, int rowCount, int colCount, int topleftRowId, int topleftColId, IDataObject dObject)
		{
			if (dObject == null)
			{
				return;
			}
			string asiFormatTextFromDataObject = ClipboardHelper.GetAsiFormatTextFromDataObject(dObject);
			if (string.IsNullOrEmpty(asiFormatTextFromDataObject))
			{
				return;
			}
			XElement xElement = null;
			try
			{
				xElement = XElement.Parse(asiFormatTextFromDataObject);
			}
			catch
			{
			}
			if (xElement == null)
			{
				return;
			}
			for (int i = 0; i < colCount; i++)
			{
				int displayIndex = topleftColId + i;
				if (!(DataGrid.ColumnFromDisplayIndex(displayIndex) is MMScrollAreaMSDataColumn mMScrollAreaMSDataColumn) || !(mMScrollAreaMSDataColumn.Field is MMScrollAreaBrowseField))
				{
					continue;
				}
				for (int j = 0; j < rowCount; j++)
				{
					IList<string> list = data[j];
					if (list.Count >= i)
					{
						string value = ExtractVariablePath(xElement, j, i);
						if (!string.IsNullOrEmpty(value))
						{
							list[i] = value;
						}
					}
				}
			}
		}

		private string ExtractVariablePath(XElement asiNode, int row, int column, string cellValue = null)
		{
			XElement xElement = asiNode.XPathSelectElement($"//Items/Item[Row/text()={row} and Col/text()={column}] /Path");
			if (xElement != null)
			{
				string value = xElement.Value;
				if (!string.IsNullOrEmpty(value))
				{
					if (value.StartsWith("!EO Flowsheet!", StringComparison.CurrentCultureIgnoreCase))
					{
						string currentRecordPath = GetCurrentRecordPath(value.Substring(14));
						string trimmedRecordPath = GetTrimmedRecordPath();
						if (!string.IsNullOrEmpty(trimmedRecordPath))
						{
							string text = trimmedRecordPath + ".";
							if (currentRecordPath.StartsWith(text, StringComparison.CurrentCultureIgnoreCase))
							{
								return currentRecordPath.Substring(text.Length);
							}
						}
						return currentRecordPath;
					}
					if (value.Contains("SG_SPEC") && cellValue != null)
					{
						string trimmedRecordPath2 = GetTrimmedRecordPath();
						if (trimmedRecordPath2.Equals("Spec Groups", StringComparison.CurrentCultureIgnoreCase))
						{
							string blockStringBuild = string.Empty;
							GetBlockPath(value, ref blockStringBuild);
							return blockStringBuild + cellValue;
						}
						if (!string.IsNullOrEmpty(trimmedRecordPath2))
						{
							string text2 = trimmedRecordPath2 + ".";
							if (cellValue.StartsWith(text2, StringComparison.CurrentCultureIgnoreCase))
							{
								return cellValue.Substring(text2.Length);
							}
						}
						return cellValue;
					}
					return value;
				}
			}
			return null;
		}

		private void GetBlockPath(string dataPath, ref string blockStringBuild)
		{
			int num = dataPath.IndexOf("Blocks.");
			if (num > 0)
			{
				dataPath = dataPath.Substring(num + 7);
				int num2 = dataPath.IndexOf('.');
				if (num2 > 0)
				{
					blockStringBuild = blockStringBuild + dataPath.Substring(0, num2) + ".";
					GetBlockPath(dataPath, ref blockStringBuild);
				}
			}
		}

		private string GetTrimmedRecordPath()
		{
			CxvViewModel viewModel = ViewModel;
			if (viewModel == null)
			{
				return null;
			}
			string text = GetCurrentRecordPath(viewModel.ResolveParameter("main") as string);
			string[] array = new string[7] { "Data", "Blocks", "Streams", "Flowsheeting Options", "Design-Spec", "Measurement", "Calculator" };
			foreach (string text2 in array)
			{
				text = text.Replace("." + text2 + ".", ".");
			}
			int num = text.IndexOf(".EO Configuration.");
			if (num > 0)
			{
				text = text.Substring(0, num);
			}
			return text;
		}

		private static string GetCurrentRecordPath(string longPath)
		{
			if (longPath.StartsWith("Top.appModelV8.Blocks."))
			{
				return longPath.Substring("Top.appModelV8.Blocks.".Length);
			}
			if (longPath.StartsWith("Top.appModelV8.Streams."))
			{
				return longPath.Substring("Top.appModelV8.Streams.".Length);
			}
			if (longPath.StartsWith("Top.appModelV8.Flowsheeting Options.Design-Spec."))
			{
				return longPath.Substring("Top.appModelV8.Flowsheeting Options.Design-Spec.".Length);
			}
			if (longPath.StartsWith("Top.appModelV8.Flowsheeting Options.Measurement."))
			{
				return longPath.Substring("Top.appModelV8.Flowsheeting Options.Measurement.".Length);
			}
			if (longPath.StartsWith("Top.appModelV8.Flowsheeting Options.Calculator."))
			{
				return longPath.Substring("Top.appModelV8.Flowsheeting Options.Calculator.".Length);
			}
			if (longPath.StartsWith("Top.appModelV8.EO Configuration."))
			{
				return longPath.Substring("Top.appModelV8.EO Configuration.".Length);
			}
			if (string.Equals(longPath, "Top.appModelV8.EO Configuration.".Substring(0, "Top.appModelV8.EO Configuration.".Length - 1), StringComparison.InvariantCultureIgnoreCase))
			{
				return string.Empty;
			}
			return longPath;
		}

		private void _DataGrid_DataDropping(object sender, GridControlDataDroppingEventArgs e)
		{
			if (CxsProvider == null)
			{
				return;
			}
			if (SpecialProcessForFortranLine(e))
			{
				e.Handled = true;
				return;
			}
			IList<IList<string>> droppingData = e.DroppingData;
			int startRowIndex = e.TargetArea.StartRowIndex;
			int startColumnIndex = e.TargetArea.StartColumnIndex;
			int selectedColumnsCount = e.TargetArea.SelectedColumnsCount;
			int selectedRowsCount = e.TargetArea.SelectedRowsCount;
			FixVariableDataToPaste(droppingData, selectedRowsCount, selectedColumnsCount, startRowIndex, startColumnIndex, e.DataObject);
			if (DataTable.Rows.Count - startRowIndex < selectedRowsCount && DataOrientation == Orientation.Vertical)
			{
				e.Cancel = AddRecords(startRowIndex + selectedRowsCount + 1, DataTable.Rows.Count, FirstLevelVectorData);
			}
			if (DataTable.Columns.Count - startColumnIndex < selectedColumnsCount)
			{
				if (DataOrientation == Orientation.Vertical)
				{
					e.Cancel = AddRecords(selectedColumnsCount + startColumnIndex + 1, DataTable.Columns.Count, SecondLevelVectorData);
				}
				else
				{
					e.Cancel = AddRecords(selectedColumnsCount + startColumnIndex + 1, DataTable.Columns.Count, FirstLevelVectorData);
				}
			}
			e.ShouldDelayPasting = DataRetriever == null;
		}

		private bool SpecialProcessForFortranLine(GridControlDataDroppingEventArgs e)
		{
			if (e.TargetArea.SelectedColumnsCount == 1 && e.TargetArea.SelectedRowsCount == 1 && e.DroppingData.Count == 1 && e.DroppingData[0].Count == 1 && DataGrid?.DataSource is MMScrollAreaMSDataTable && DataGrid.ColumnFromDisplayIndex(e.TargetArea.StartColumnIndex) is MMScrollAreaMSDataColumn mMScrollAreaMSDataColumn && mMScrollAreaMSDataColumn.Field is MMScrollAreaFortranLineField)
			{
				string text = e.DroppingData[0][0];
				if (!string.IsNullOrWhiteSpace(text))
				{
					DataRow dataRow = DataGrid.BoundRows.ElementAtOrDefault(e.TargetArea.StartRowIndex);
					if (dataRow != null && dataRow[mMScrollAreaMSDataColumn] is DataCellText dataCellText)
					{
						if (string.IsNullOrEmpty(dataCellText.Value))
						{
							dataCellText.Value = text;
						}
						else
						{
							dataCellText.Value += text;
						}
						return true;
					}
				}
			}
			return false;
		}

		private void _DataGrid_CellValuePasting(object sender, CellValuePastingEventArgs e)
		{
			if (DataRetriever != null)
			{
				DataTable dataTable = DataTable;
				int rowIndex = dataTable.Rows.IndexOf(e.Cell.Row);
				int columnIndex = dataTable.Columns.IndexOf(e.Cell.Column);
				if (!DataRetriever.IgnoreCellOnDataPasting(rowIndex, columnIndex))
				{
					string errorMessage = null;
					if (!DataRetriever.UpdateCellValueOnDataPasting(rowIndex, columnIndex, e.PastingValue, e.IsLastRowInClipboard, out errorMessage) && !string.IsNullOrEmpty(errorMessage))
					{
						MessageBox.Show(Window.GetWindow(this), errorMessage, AspenTech.AspenPlus.MMControls.Properties.Resources.strPaste);
					}
					base.Dispatcher.BeginInvokeOnce(PublishUpdateDisplayEvent);
					e.Handled = true;
				}
			}
			else if (e.Cell != null && e.Cell.Column is MMScrollAreaMSDataColumn { Field: MMScrollAreaValueField { Mask: AesMaskOption.Id } } && !ValidName(e.PastingText))
			{
				e.Handled = true;
			}
		}

		public static bool ValidName(string newValue)
		{
			if (newValue != null && newValue.Length > 0)
			{
				if (!char.IsLetterOrDigit(newValue[0]))
				{
					return false;
				}
				char[] array = newValue.ToCharArray();
				for (int i = 1; i < array.Length; i++)
				{
					char c = array[i];
					if (!char.IsLetterOrDigit(c) && c != ',' && c != '$' && c != ':' && c != '+' && c != '-' && c != '\r' && c != '\b')
					{
						return false;
					}
				}
				if (Regex.IsMatch(newValue, "[^\\u0000-\\u007F]"))
				{
					return false;
				}
			}
			return true;
		}

