		private bool AddRecords(int desiredRecordCount, int currentCount, CxvVectorPropertyData vector, bool isMessageBoxDisplay = true)
		{
			if (vector == null)
			{
				return false;
			}
			if (isMessageBoxDisplay)
			{
				AesMessageBoxResult aesMessageBoxResult = AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strConfirmExtendGrid, AspenTech.AspenPlus.MMControls.Properties.Resources.Confirm, AesMessageBoxButton.YesNo, AesMessageBoxImage.Question, showHelpButton: false, 2);
				if (aesMessageBoxResult == AesMessageBoxResult.No || aesMessageBoxResult == AesMessageBoxResult.Cancel)
				{
					return true;
				}
			}
			if (!(vector.IndexBasis is CxvChildCountIndexBasisData cxvChildCountIndexBasisData) || !vector.AllowNew)
			{
				return true;
			}
			try
			{
				int num = vector.Count;
				if (cxvChildCountIndexBasisData.HasProxyRow)
				{
					num--;
				}
				Mouse.SetCursor(Cursors.Wait);
				CxsProvider.SuspendNotifications();
				for (int i = 0; i < desiredRecordCount - currentCount; i++)
				{
					vector.Insert(num, null);
				}
			}
			finally
			{
				Mouse.SetCursor(Cursors.Arrow);
				CxsProvider.ResumeNotifications();
			}
			return false;
		}

		private static bool ShouldSkipKey(Key key)
		{
			switch (key)
			{
			case Key.Pause:
			case Key.Capital:
			case Key.Space:
			case Key.Prior:
			case Key.Next:
			case Key.Left:
			case Key.Up:
			case Key.Right:
			case Key.Down:
			case Key.Snapshot:
			case Key.Insert:
			case Key.Delete:
			case Key.F1:
			case Key.F3:
			case Key.F4:
			case Key.F5:
			case Key.F6:
			case Key.F7:
			case Key.F8:
			case Key.F9:
			case Key.F10:
			case Key.F11:
			case Key.F12:
			case Key.NumLock:
			case Key.Scroll:
			case Key.LeftShift:
			case Key.RightShift:
			case Key.LeftCtrl:
			case Key.RightCtrl:
			case Key.LeftAlt:
			case Key.RightAlt:
			case Key.System:
				return true;
			default:
				if (Keyboard.Modifiers == ModifierKeys.Control)
				{
					return true;
				}
				return false;
			}
		}

		private void _DataGrid_PreviewKeyDown(object sender, KeyEventArgs e)
		{
			if (e.Key == Key.Delete && !(Infragistics.Windows.Utilities.GetAncestorFromType(e.OriginalSource as DependencyObject, typeof(AesXamValueEdit), allowSubclassOfType: false) is AesXamValueEdit { IsInEditMode: not false }))
			{
				if (DeleteRowCommand != null && DeleteRowCommand.CanExecute(null) && FirstLevelVectorData.AllowRemove)
				{
					DeleteRowCommand.Execute(null);
				}
				else
				{
					int num = DataGrid.SelectedRows.Count();
					int num2 = DataGrid.SelectedColumns.Count();
					if (num == 0 && num2 > 0 && FirstLevelVectorData.AllowRemove)
					{
						DeleteSelectedColumns();
					}
					else if (num > 0 && num2 == 0 && FirstLevelVectorData.AllowRemove)
					{
						DeleteSelectedRows();
					}
					else
					{
						ClearSelectedCells();
					}
				}
				e.Handled = true;
			}
			if (ShouldSkipKey(e.Key))
			{
				return;
			}
			base.Dispatcher.Invoke(delegate
			{
				IDataCell data = DataGrid.CurrentCell.Data;
				if (data != null)
				{
					GridControlCell hostControl = data.HostControl;
					if (hostControl != null && hostControl.Template != null)
					{
						UIElement uIElement = hostControl.Template.FindName("PART_FocusSite", hostControl) as UIElement;
						uIElement?.Focus();
						if (uIElement is TextBox textBox)
						{
							textBox.Focus();
						}
						else if (Infragistics.Windows.Utilities.GetDescendantFromType(hostControl, typeof(TextBox), allowSubclassOfType: true) is TextBox textBox2)
						{
							textBox2.Focus();
						}
					}
				}
			}, DispatcherPriority.Render);
		}

