		private void _DataGrid_ColumnViewGenerated(object sender, DataColumnEventArgs e)
		{
			if (DataOrientation == Orientation.Horizontal)
			{
				return;
			}
			MMScrollAreaMSDataColumn newColumn = e.Column as MMScrollAreaMSDataColumn;
			MMViewModel vm = base.DataContext as MMViewModel;
			MMScrollAreaField field = newColumn.Field;
			if (newColumn == null || vm == null)
			{
				return;
			}
			DataTemplate dataTemplate = null;
			string text = null;
			if (field.ColumnHeaderTemplate != null)
			{
				dataTemplate = field.ColumnHeaderTemplate;
			}
			else if (!string.IsNullOrEmpty(field.HeaderUnitsProperty))
			{
				dataTemplate = new DataTemplate();
				FrameworkElementFactory frameworkElementFactory = new FrameworkElementFactory(typeof(DockPanel));
				BuildColumnHeaderDockPanel(field, frameworkElementFactory, base.DataContext);
				text = AddUnitToLabel(this, field, frameworkElementFactory);
				dataTemplate.VisualTree = frameworkElementFactory;
			}
			if (dataTemplate == null && string.IsNullOrEmpty(newColumn.Header))
			{
				if (!string.IsNullOrEmpty(text))
				{
					newColumn.Header = text;
				}
				else
				{
					base.Dispatcher.BeginInvoke(DispatcherPriority.Input, (Action)delegate
					{
						StringBuilder stringBuilder = new StringBuilder();
						MMScrollAreaMSClipboard.GetLabelOfNonHeaderOnlyFields(stringBuilder, new MMScrollAreaField[1] { newColumn.Field }, this, vm, setHeaderLineCount: false);
						newColumn.Header = stringBuilder.Replace(Environment.NewLine, " ").ToString();
					});
				}
			}
			if (dataTemplate != null)
			{
				newColumn.HeaderContentTemplate = dataTemplate;
			}
		}

