		private void MMFields_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			switch (e.Action)
			{
			case NotifyCollectionChangedAction.Reset:
				InitFields();
				break;
			case NotifyCollectionChangedAction.Add:
			case NotifyCollectionChangedAction.Remove:
			case NotifyCollectionChangedAction.Replace:
			case NotifyCollectionChangedAction.Move:
				break;
			}
		}

		public void InitFields()
		{
			if (_isInitializing)
			{
				return;
			}
			_isInitializing = true;
			try
			{
				if (base.DataContext == null || base.Visibility != Visibility.Visible || !(base.DataContext is MMViewModel mMViewModel) || DataGrid == null)
				{
					return;
				}
				ClearDataPropertyDependencies();
				_dataPropertyDependencies = new CxvPropertyWatch();
				_dataPropertyDependencies.PropertyDependencyChanged += delegate
				{
					InvalidateFields();
				};
				if (!(mMViewModel.ResolveViewPropertyPath(DataProperty, _dataPropertyDependencies) is IEnumerable enumerable))
				{
					return;
				}
				bool showLastRowAsNewlyAdded = false;
				if (enumerable is CxvVectorPropertyData { Count: >0, IndexBasis: CxvChildCountIndexBasisData indexBasis })
				{
					showLastRowAsNewlyAdded = indexBasis.HasProxyRow;
				}
				int num = ((_expandedFields != null) ? _expandedFields.Count : 0);
				_dataColumnMap = new Dictionary<BindingDataColumn, MMScrollAreaField>();
				_expandedFields = ExpandField();
				CheckIfReadOnlyGrid();
				_hasInitialized = false;
				if (num >= _expandedFields.Count)
				{
					SaveCustomization();
				}
				if (DataOrientation == Orientation.Vertical)
				{
					List<BindingDataColumn> list = new List<BindingDataColumn>();
					double num2 = 0.0;
					foreach (MMScrollAreaField expandedField in _expandedFields)
					{
						Type type = expandedField.GetType();
						RefreshFieldBinding(expandedField);
						if (expandedField == null || !expandedField.IsUsed)
						{
							continue;
						}
						string text = expandedField.Label;
						if (expandedField.LabelTextConverter != null)
						{
							object obj = expandedField.LabelTextConverter.Convert(text, typeof(string), null, null);
							if (obj != null)
							{
								text = obj.ToString();
							}
						}
						MMScrollAreaMSDataColumn mMScrollAreaMSDataColumn = new MMScrollAreaMSDataColumn(expandedField)
						{
							Header = text,
							Width = expandedField.Width,
							IsFrozen = expandedField.IsFieldFixed,
							IsStarWidth = false,
							HeaderColumnSpan = expandedField.HeaderColumnSpanForScrollAreaMS,
							Tag = expandedField
						};
						if (!string.IsNullOrEmpty(expandedField.LabelBindingPath))
						{
							BindingOperations.SetBinding(mMScrollAreaMSDataColumn, DataColumn.HeaderProperty, new Binding(expandedField.LabelBindingPath)
							{
								Source = base.DataContext,
								Mode = BindingMode.OneWay
							});
						}
						if ((expandedField.BindLabelPromptToColumnHeaderTooltip ?? false) && !string.IsNullOrEmpty(expandedField.LabelBindingPath) && expandedField.LabelBindingPath.EndsWith(".Value", StringComparison.InvariantCulture) && expandedField.LabelBindingPath.Length > 6)
						{
							BindingOperations.SetBinding(mMScrollAreaMSDataColumn, DataColumn.TooltipProperty, new Binding(expandedField.LabelBindingPath.Substring(0, expandedField.LabelBindingPath.Length - 6) + ".VariablePrompt")
							{
								Source = base.DataContext,
								Mode = BindingMode.OneWay
							});
						}
						if (type == typeof(MMScrollAreaReadOnlyValueField))
						{
							mMScrollAreaMSDataColumn.IsReadOnly = true;
							MMScrollAreaReadOnlyValueField source = expandedField as MMScrollAreaReadOnlyValueField;
							BindingOperations.SetBinding(mMScrollAreaMSDataColumn, DataColumn.VisibilityProperty, new Binding("ReadOnlyMSFieldVisibility")
							{
								Source = source,
								Mode = BindingMode.TwoWay
							});
						}
