							frameworkElementFactory.SetBinding(ButtonBase.CommandProperty, new Binding(mMScrollAreaButtonField.CommandPath)
							{
								Source = base.DataContext
							});
							if (mMScrollAreaButtonField != null && !string.IsNullOrEmpty(mMScrollAreaButtonField.PropertyPath))
							{
								frameworkElementFactory.SetValue(AesVariableControlBase.VariablePathProperty, "Row.DataItem." + mMScrollAreaButtonField.PropertyPath);
								frameworkElementFactory.SetBinding(UIElement.VisibilityProperty, new Binding("Row.DataItem." + mMScrollAreaButtonField.PropertyPath + ".IsVisible")
								{
									Converter = IsVisibleConverter.Converter
