		private void SetAllowColumnChooser()
		{
			if (AllowColumnChooser.HasValue)
			{
				DataGrid.AllowColumnChooser = AllowColumnChooser.Value;
				return;
			}
			DataGrid.AllowColumnChooser = false;
			if (DataOrientation == Orientation.Horizontal || MMFields.Any((MMScrollAreaField x) => x is MMScrollAreaHeaderOnlyField))
			{
				return;
			}
			MMScrollAreaField mMScrollAreaField = MMFields.FirstOrDefault((MMScrollAreaField field) => field is MMScrollAreaFieldRepeater);
			if (mMScrollAreaField != null)
			{
				MMScrollAreaFieldRepeater mMScrollAreaFieldRepeater = mMScrollAreaField as MMScrollAreaFieldRepeater;
				if (mMScrollAreaFieldRepeater.Fields.Count > 0 && !string.IsNullOrEmpty(mMScrollAreaFieldRepeater.Fields[0].HeaderTypeProperty) && !mMScrollAreaFieldRepeater.Fields[0].IsHeaderReadOnly)
				{
					return;
				}
			}
			if (_expandedFields == null)
			{
				return;
			}
			foreach (MMScrollAreaField expandedField in _expandedFields)
			{
				if (expandedField != null && (!string.IsNullOrEmpty(expandedField.Label) || !string.IsNullOrEmpty(expandedField.HeaderTypeProperty)))
				{
					DataGrid.AllowColumnChooser = true;
					break;
				}
			}
		}

		private static string AddUnitToLabel(MMScrollAreaMS scrollAreaMS, MMScrollAreaField mmfield, FrameworkElementFactory root)
