					new StringBuilder();
					for (int i = 0; i < num; i++)
					{
						string text2 = ((array.Length <= i) ? array[array.Length - 1] : array[i]);
						text2 = text2.Trim();
						string text3 = ((array2 == null) ? "" : ((array2.Length >= i) ? array2[i] : ""));
						text3 = text3.Trim().ToLowerInvariant();
						if (string.IsNullOrEmpty(text3))
