							frameworkElementFactory2.SetValue(AesComboEdit.VariableDataMemberProperty, "Value");
							if (text == null)
							{
								text = text2 + ".Value";
							}
							frameworkElementFactory2.SetValue(AesComboEdit.IsInScrollAreaColumnHeaderProperty, true);
