							frameworkElementFactory2.SetValue(AesComboEdit.VariableDataMemberProperty, "SelectedItem");
							frameworkElementFactory2.SetValue(AesComboEdit.IsInScrollAreaColumnHeaderProperty, true);
							break;
						case "basis":
							frameworkElementFactory2 = new FrameworkElementFactory(typeof(MMBasisEdit));
							frameworkElementFactory2.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Stretch);
							frameworkElementFactory2.SetValue(AesComboEdit.IsInScrollAreaColumnHeaderProperty, true);
							break;
						case "value":
