							frameworkElementFactory2.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Stretch);
							frameworkElementFactory2.SetValue(AesVariableEdit.UnitsVisibilityProperty, Visibility.Collapsed);
							frameworkElementFactory2.SetValue(AesVariableEdit.BasisVisibilityProperty, Visibility.Collapsed);
							frameworkElementFactory2.SetValue(AesVariableEdit.IsInScrollAreaColumnHeaderProperty, true);
							break;
						case "textuppercase":
							frameworkElementFactory2 = new FrameworkElementFactory(typeof(MMVariableEdit));
							frameworkElementFactory2.SetValue(AesVariableEdit.ValueMaskProperty, AesMaskOption.None);
							frameworkElementFactory2.SetValue(AesVariableEdit.ValueCharacterCasingProperty, CharacterCasing.Upper);
							frameworkElementFactory2.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Stretch);
							frameworkElementFactory2.SetValue(AesVariableEdit.UnitsVisibilityProperty, Visibility.Collapsed);
							frameworkElementFactory2.SetValue(AesVariableEdit.BasisVisibilityProperty, Visibility.Collapsed);
							frameworkElementFactory2.SetValue(AesVariableEdit.IsInScrollAreaColumnHeaderProperty, true);
							break;
						case "textlowercase":
							frameworkElementFactory2 = new FrameworkElementFactory(typeof(MMVariableEdit));
							frameworkElementFactory2.SetValue(AesVariableEdit.ValueMaskProperty, AesMaskOption.None);
							frameworkElementFactory2.SetValue(AesVariableEdit.ValueCharacterCasingProperty, CharacterCasing.Lower);
							frameworkElementFactory2.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Stretch);
							frameworkElementFactory2.SetValue(AesVariableEdit.UnitsVisibilityProperty, Visibility.Collapsed);
							frameworkElementFactory2.SetValue(AesVariableEdit.BasisVisibilityProperty, Visibility.Collapsed);
							frameworkElementFactory2.SetValue(AesVariableEdit.IsInScrollAreaColumnHeaderProperty, true);
							break;
						}
						frameworkElementFactory2.SetBinding(FrameworkElement.DataContextProperty, new Binding("DataContext")
						{
							RelativeSource = new RelativeSource(RelativeSourceMode.FindAncestor, typeof(MMScrollAreaMS), 1)
