		private static void BuildColumnHeaderDockPanel(MMScrollAreaField mmfield, FrameworkElementFactory dockpanel, object dataContext)
		{
			if (mmfield.Label != null || mmfield.LabelBindingPath != null)
			{
				FrameworkElementFactory frameworkElementFactory = new FrameworkElementFactory(typeof(TextBlock));
				frameworkElementFactory.SetValue(UIElement.FocusableProperty, false);
				if (string.IsNullOrEmpty(mmfield.LabelBindingPath))
				{
					frameworkElementFactory.SetValue(TextBlock.TextProperty, mmfield.DataColumn.Header);
				}
				else
				{
					frameworkElementFactory.SetBinding(TextBlock.TextProperty, new Binding(mmfield.LabelBindingPath)
					{
						Source = dataContext,
						Converter = mmfield.LabelTextConverter
					});
				}
				frameworkElementFactory.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Center);
				frameworkElementFactory.SetValue(TextBlock.TextAlignmentProperty, TextAlignment.Center);
				if (mmfield.WidthFieldLengthResolved.Value.IsAbsolute || mmfield.WidthFieldLengthResolved.Value.IsStar || !mmfield.IncludeLabelWhenAutoWidth)
				{
					frameworkElementFactory.SetValue(TextBlock.TextWrappingProperty, TextWrapping.WrapWithOverflow);
				}
				frameworkElementFactory.SetValue(DockPanel.DockProperty, mmfield.LabelDockResolved);
				dockpanel.AppendChild(frameworkElementFactory);
			}
		}

		private MMScrollAreaFieldCollection ExpandField()
		{
			if (DesignerProperties.GetIsInDesignMode(this))
			{
				return MMFields;
			}
			ClearExpandedFieldDependencies();
			MMScrollAreaFieldCollection mMScrollAreaFieldCollection = new MMScrollAreaFieldCollection();
			ExpandField(MMFields, mMScrollAreaFieldCollection);
			if (_expandedFieldDependencies != null)
			{
				if (!_expandedFieldDependencies.IsEmpty)
				{
					_expandedFieldDependencies.PropertyDependencyChanged -= delegate
					{
						InvalidateFields();
					};
					_expandedFieldDependencies.PropertyDependencyChanged += delegate
					{
						InvalidateFields();
					};
				}
				else
				{
					_expandedFieldDependencies = null;
				}
			}
			return mMScrollAreaFieldCollection;
		}

		private void ClearExpandedFieldDependencies()
		{
			if (_expandedFieldDependencies != null)
			{
				_expandedFieldDependencies.PropertyDependencyChanged -= delegate
				{
					InvalidateFields();
				};
				_expandedFieldDependencies.Clear();
				_expandedFieldDependencies = null;
			}
		}

		private void InvalidateFields()
		{
			if (!_isFieldsInvalidated)
			{
				_isFieldsInvalidated = true;
				base.Dispatcher.BeginInvoke((Action)delegate
				{
					InitFields();
					_isFieldsInvalidated = false;
				});
			}
		}

		private void ExpandField(MMScrollAreaFieldCollection fields, MMScrollAreaFieldCollection expandedFields)
		{
			foreach (MMScrollAreaField field in fields)
			{
				if (!(field is MMScrollAreaFieldRepeater repeaterField))
				{
					if (field is MMScrollAreaHeaderOnlyField mMScrollAreaHeaderOnlyField)
					{
						MMScrollAreaHeaderOnlyField mMScrollAreaHeaderOnlyField2 = mMScrollAreaHeaderOnlyField.Clone() as MMScrollAreaHeaderOnlyField;
						mMScrollAreaHeaderOnlyField2.ResetMMFields();
						ExpandField(mMScrollAreaHeaderOnlyField.MMFields, mMScrollAreaHeaderOnlyField2.MMFields);
						expandedFields.Add(mMScrollAreaHeaderOnlyField2);
					}
					else
					{
						field.ParentScrollAreaActions = this;
						expandedFields.Add(field);
					}
				}
				else
				{
					DoExpandField(expandedFields, repeaterField);
				}
			}
		}

		private void DoExpandField(MMScrollAreaFieldCollection expandedFields, MMScrollAreaFieldRepeater repeaterField)
		{
			if (base.DataContext == null)
			{
				return;
			}
			int num = 0;
			if (_expandedFieldDependencies == null)
			{
				_expandedFieldDependencies = new CxvPropertyWatch();
			}
			if (!string.IsNullOrEmpty(repeaterField.SecondLevelVectorProperty))
			{
				num = GetMaxColumnCount(repeaterField);
				SetCanInsertDelete2ndLevelVector(repeaterField);
			}
			else
			{
				int? num2 = _expandedFieldDependencies.ResolveInt32(this, "DataContext." + repeaterField.CountPath);
				if (num2.HasValue)
				{
					num = num2.Value;
				}
			}
			if (repeaterField.Fields.Count == 1 && repeaterField.Fields[0].GetType() == typeof(MMScrollAreaReadOnlyValueField))
			{
				MMScrollAreaReadOnlyValueField mMScrollAreaReadOnlyValueField = repeaterField.Fields[0] as MMScrollAreaReadOnlyValueField;
				for (int i = 0; i < num; i++)
				{
					MMScrollAreaReadOnlyValueField mMScrollAreaReadOnlyValueField2 = new MMScrollAreaReadOnlyValueField();
					mMScrollAreaReadOnlyValueField2.ColumnHeaderTextAlignment = mMScrollAreaReadOnlyValueField.ColumnHeaderTextAlignment;
					mMScrollAreaReadOnlyValueField2.ExpandedFromRepeater = mMScrollAreaReadOnlyValueField.ExpandedFromRepeater;
					mMScrollAreaReadOnlyValueField2.HeaderTypeProperty = mMScrollAreaReadOnlyValueField.HeaderTypeProperty;
					mMScrollAreaReadOnlyValueField2.HeaderUnitsProperty = mMScrollAreaReadOnlyValueField.HeaderUnitsProperty;
					mMScrollAreaReadOnlyValueField2.HelpFile = mMScrollAreaReadOnlyValueField.HelpFile;
					mMScrollAreaReadOnlyValueField2.HelpId = mMScrollAreaReadOnlyValueField.HelpId;
					mMScrollAreaReadOnlyValueField2.IncludeLabelWhenAutoWidth = mMScrollAreaReadOnlyValueField.IncludeLabelWhenAutoWidth;
					mMScrollAreaReadOnlyValueField2.IsEnabled = mMScrollAreaReadOnlyValueField.IsEnabled;
					mMScrollAreaReadOnlyValueField2.IsEnabledBindingPath = mMScrollAreaReadOnlyValueField.IsEnabledBindingPath;
					mMScrollAreaReadOnlyValueField2.IsFieldFixed = mMScrollAreaReadOnlyValueField.IsFieldFixed;
					mMScrollAreaReadOnlyValueField2.IsHeaderUnitsEnabled = mMScrollAreaReadOnlyValueField.IsHeaderUnitsEnabled;
					mMScrollAreaReadOnlyValueField2.IsUsed = mMScrollAreaReadOnlyValueField.IsUsed;
					mMScrollAreaReadOnlyValueField2.IsUsedBindingPath = mMScrollAreaReadOnlyValueField.IsUsedBindingPath;
					mMScrollAreaReadOnlyValueField2.IsUsedBindingConverter = mMScrollAreaReadOnlyValueField.IsUsedBindingConverter;
					mMScrollAreaReadOnlyValueField2.IsUsedBindingConverterParameter = mMScrollAreaReadOnlyValueField.IsUsedBindingConverterParameter;
					mMScrollAreaReadOnlyValueField2.IsVisible = mMScrollAreaReadOnlyValueField.IsVisible;
					mMScrollAreaReadOnlyValueField2.Label = mMScrollAreaReadOnlyValueField.Label;
					mMScrollAreaReadOnlyValueField2.LabelBindingPath = mMScrollAreaReadOnlyValueField.LabelBindingPath;
					mMScrollAreaReadOnlyValueField2.LabelDock = mMScrollAreaReadOnlyValueField.LabelDock;
					mMScrollAreaReadOnlyValueField2.MinWidth = mMScrollAreaReadOnlyValueField.MinWidth;
					mMScrollAreaReadOnlyValueField2.PropertyPath = mMScrollAreaReadOnlyValueField.PropertyPath;
					mMScrollAreaReadOnlyValueField2.ResolvedCxsProvider = mMScrollAreaReadOnlyValueField.ResolvedCxsProvider;
					mMScrollAreaReadOnlyValueField2.UseFieldHelp = mMScrollAreaReadOnlyValueField.UseFieldHelp;
					mMScrollAreaReadOnlyValueField2.Width = mMScrollAreaReadOnlyValueField.Width;
					mMScrollAreaReadOnlyValueField2.WidthMode = mMScrollAreaReadOnlyValueField.WidthMode;
					mMScrollAreaReadOnlyValueField2.LabelTextConverterBindingPath = mMScrollAreaReadOnlyValueField.LabelTextConverterBindingPath;
					mMScrollAreaReadOnlyValueField2.LabelTextConverter = mMScrollAreaReadOnlyValueField.LabelTextConverter;
					mMScrollAreaReadOnlyValueField2.CharacterCasing = mMScrollAreaReadOnlyValueField.CharacterCasing;
					mMScrollAreaReadOnlyValueField2.ColumnHeaderCopyValue = mMScrollAreaReadOnlyValueField.ColumnHeaderCopyValue;
					mMScrollAreaReadOnlyValueField2.ColumnHeaderCopyValueBindingPath = mMScrollAreaReadOnlyValueField.ColumnHeaderCopyValueBindingPath;
					mMScrollAreaReadOnlyValueField2.HasColumnHeader = mMScrollAreaReadOnlyValueField.HasColumnHeader;
					mMScrollAreaReadOnlyValueField2.IsHeaderUnitsEnabled = mMScrollAreaReadOnlyValueField.IsHeaderUnitsEnabled;
					mMScrollAreaReadOnlyValueField2.Mask = mMScrollAreaReadOnlyValueField.Mask;
					mMScrollAreaReadOnlyValueField2.MaxLength = mMScrollAreaReadOnlyValueField.MaxLength;
					mMScrollAreaReadOnlyValueField2.VariableDataMember = mMScrollAreaReadOnlyValueField.VariableDataMember;
					mMScrollAreaReadOnlyValueField2.WidthFieldLength = mMScrollAreaReadOnlyValueField.WidthFieldLength;
					mMScrollAreaReadOnlyValueField2.IsHeaderReadOnly = mMScrollAreaReadOnlyValueField.IsHeaderReadOnly;
					mMScrollAreaReadOnlyValueField2.BindLabelPromptToColumnHeaderTooltip = mMScrollAreaReadOnlyValueField.BindLabelPromptToColumnHeaderTooltip;
					mMScrollAreaReadOnlyValueField2.ParentScrollAreaActions = this;
					AppendExpandedField(mMScrollAreaReadOnlyValueField2, expandedFields, repeaterField, i);
				}
				return;
			}
			for (int j = 0; j < num; j++)
			{
				foreach (MMScrollAreaField field in repeaterField.Fields)
				{
					MMScrollAreaField clone = field.Clone() as MMScrollAreaField;
					AppendExpandedField(clone, expandedFields, repeaterField, j);
				}
			}
		}

		private void AppendExpandedField(MMScrollAreaField clone, MMScrollAreaFieldCollection expandedFields, MMScrollAreaFieldRepeater repeaterField, int id)
		{
			clone.ExpandedId = id;
			clone.ExpandedFromRepeater = repeaterField;
			object obj = null;
			if (!string.IsNullOrEmpty(repeaterField.KeyPath))
			{
				string text = string.Format(CultureInfo.InvariantCulture, repeaterField.KeyPath, id);
				obj = _expandedFieldDependencies.ResolvePropertyPath(this, "DataContext." + text);
			}
			if (obj == null)
			{
				obj = string.Empty;
			}
			clone.SubstituteIndexAndKey(id, obj);
			if (!repeaterField.IgnoreIdenticalFields || string.IsNullOrEmpty(clone.Label) || expandedFields.FirstOrDefault((MMScrollAreaField f) => f.Label == clone.Label) == null)
			{
				expandedFields.Add(clone);
			}
		}

		private void RefreshFieldBinding(MMScrollAreaField field)
		{
			if (field == null)
			{
				return;
			}
			Type type = field.GetType();
			if (type == typeof(MMScrollAreaFieldRepeater))
			{
				return;
			}
			if (type == typeof(MMScrollAreaHeaderOnlyField))
			{
				foreach (MMScrollAreaField mMField in (field as MMScrollAreaHeaderOnlyField).MMFields)
				{
					RefreshFieldBinding(mMField);
				}
				return;
			}
			if (!string.IsNullOrEmpty(field.IsUsedBindingPath))
			{
				BindingOperations.SetBinding(field, MMScrollAreaField.IsUsedProperty, new Binding(field.IsUsedBindingPath)
				{
					Source = base.DataContext,
					Converter = field.IsUsedBindingConverter,
					ConverterParameter = field.IsUsedBindingConverterParameter,
					Mode = BindingMode.OneWay
				});
			}
			if (!string.IsNullOrEmpty(field.LabelBindingPath))
			{
				BindingOperations.SetBinding(field, MMScrollAreaField.LabelProperty, new Binding(field.LabelBindingPath)
				{
					Source = base.DataContext,
					Mode = BindingMode.OneWay
				});
			}
			if (!string.IsNullOrEmpty(field.ColumnHeaderCopyValueBindingPath))
			{
				BindingOperations.SetBinding(field, MMScrollAreaField.ColumnHeaderCopyValueProperty, new Binding(field.ColumnHeaderCopyValueBindingPath)
				{
					Source = base.DataContext,
					Mode = BindingMode.OneWay
				});
			}
			if (!string.IsNullOrEmpty(field.LabelTextConverterBindingPath))
			{
				BindingOperations.SetBinding(field, MMScrollAreaField.LabelTextConverterProperty, new Binding(field.LabelTextConverterBindingPath)
				{
					Source = base.DataContext,
					Mode = BindingMode.OneWay
				});
			}
			if (!string.IsNullOrEmpty(field.LabelForCopyPath))
			{
				BindingOperations.SetBinding(field, MMScrollAreaField.LabelForCopyProperty, new Binding(field.LabelForCopyPath)
				{
					Source = base.DataContext,
					Mode = BindingMode.OneWay
				});
			}
			if (field is MMScrollAreaBrowseField mMScrollAreaBrowseField)
			{
				if (!string.IsNullOrEmpty(mMScrollAreaBrowseField.BrowseCommandBindingPath))
				{
					BindingOperations.SetBinding(field, MMScrollAreaBrowseField.BrowseCommandProperty, new Binding(mMScrollAreaBrowseField.BrowseCommandBindingPath)
					{
						Source = base.DataContext
					});
				}
				if (!string.IsNullOrEmpty(mMScrollAreaBrowseField.BrowseVisibilityBindingPath))
				{
					BindingOperations.SetBinding(field, MMScrollAreaBrowseField.BrowseVisibilityProperty, new Binding(mMScrollAreaBrowseField.BrowseVisibilityBindingPath)
					{
						Source = base.DataContext,
						FallbackValue = Visibility.Collapsed
