		private int GetMaxColumnCount(MMScrollAreaFieldRepeater repeaterField)
		{
			if (base.DataContext == null)
			{
				return 0;
			}
			int? num = _expandedFieldDependencies.ResolveInt32(this, "DataContext." + DataProperty + ".Count");
			if (!num.HasValue)
			{
				return 0;
			}
			bool? flag = _expandedFieldDependencies.ResolveBoolean(this, "DataContext." + DataProperty + ".IsNotJagged");
			int num2 = 0;
			for (int i = 0; i < num.Value; i++)
			{
				int? num3 = _expandedFieldDependencies.ResolveInt32(this, string.Format(CultureInfo.InvariantCulture, "DataContext.{0}[{1}].{2}.Count", DataProperty, i, repeaterField.SecondLevelVectorProperty));
				if (num3.HasValue && num3.Value > num2)
				{
					num2 = num3.Value;
				}
				if (flag.HasValue && flag.Value)
				{
					break;
				}
			}
			return num2;
		}

