		private void SetDataBinding()
		{
			if (DataGrid == null)
			{
				return;
			}
			if (!string.IsNullOrEmpty(DataProperty))
			{
				if (BindingOperations.GetBindingExpression(this, IsMMEnabledProperty) == null)
				{
					MultiBinding multiBinding = new MultiBinding();
					multiBinding.Bindings.Add(new Binding(DataProperty + ".IsEnabled"));
					multiBinding.Bindings.Add(new Binding(DataProperty + ".Count"));
					multiBinding.Converter = ScrollareaIsEnabledConverter.Converter;
					BindingOperations.SetBinding(this, IsMMEnabledProperty, multiBinding);
				}
				BindingOperations.SetBinding(DataGrid, UIElement.VisibilityProperty, new Binding(DataProperty + ".IsVisible")
				{
					Converter = IsVisibleConverter.Converter
				});
				if (BindingOperations.GetMultiBinding(this, PromptProperty) == null)
				{
					BindingOperations.SetBinding(this, PromptProperty, new MultiBinding
					{
						Bindings = 
						{
							(BindingBase)new Binding(DataProperty + ".VariablePrompt"),
							(BindingBase)new Binding(DataProperty + ".DisabledPrompt"),
							(BindingBase)new Binding("IsEnabled")
							{
								Source = this
							},
							(BindingBase)new Binding("IsMMEnabled")
							{
								Source = this
							},
							(BindingBase)new Binding
							{
								Source = this
							}
						},
						Converter = new AesControlPromptConverter(),
						Mode = BindingMode.OneWay,
						FallbackValue = string.Empty
					});
				}
			}
			DataGrid.SetBinding(GridControl.IsMultilineAllowedInCellProperty, new Binding
			{
				Source = this,
				Path = new PropertyPath(IsMultilineAllowedInCellProperty),
				Mode = BindingMode.OneWay
			});
			DataGrid.SetBinding(GridControl.IsVerticalScrollDeferredProperty, new Binding
			{
				Source = this,
				Path = new PropertyPath(IsVerticalScrollDeferredProperty),
				Mode = BindingMode.OneWay
			});
			DataGrid.SetBinding(GridControl.IgnoreCellNativeClipboardActionsProperty, new Binding
			{
				Source = this,
				Path = new PropertyPath(IgnoreCellNativeClipboardActionsProperty),
				Mode = BindingMode.OneWay
			});
			DataGrid.SetBinding(GridControl.AlternatingRowBackgroundProperty, new Binding
			{
				Source = this,
				Path = new PropertyPath(AlternatingRowBackgroundProperty),
				Mode = BindingMode.OneWay
			});
		}

