		private void SetSelectedColumnSet()
		{
			if (DataColumnMap == null || SelectedColumnSet == null)
			{
				return;
			}
			if (!string.IsNullOrEmpty(MyCustomization.Customization) && _isFirstSetSelectedColumnSet)
			{
				_isFirstSetSelectedColumnSet = false;
				return;
			}
			bool flag = !_isLayoutSettingRestored;
			_isLayoutSettingRestored = false;
			List<DataColumn> list = new List<DataColumn>();
			string[] array = null;
			if (!string.IsNullOrEmpty(SelectedColumnSet.FieldNames))
			{
				array = SelectedColumnSet.FieldNames.Split(',');
				foreach (MMScrollAreaField mMField in MMFields)
				{
					if (mMField.DataColumn != null)
					{
						if (DataGrid.IsColumnFrozen(mMField.DataColumn))
						{
							list.Add(mMField.DataColumn);
						}
						DataGrid.UnfreezeColumn(mMField.DataColumn);
						mMField.DataColumn.Visibility = Visibility.Collapsed;
					}
				}
				int num = 0;
				string[] array2 = array;
				foreach (string colName in array2)
				{
					MMScrollAreaField mMScrollAreaField = MMFields.Where((MMScrollAreaField p) => p.FieldName == colName).FirstOrDefault();
					if (mMScrollAreaField != null && mMScrollAreaField.IsUsed && mMScrollAreaField.DataColumn != null)
					{
						mMScrollAreaField.DataColumn.Visibility = Visibility.Visible;
						if (flag)
						{
							mMScrollAreaField.DataColumn.DisplayIndex = num;
						}
						num++;
					}
				}
			}
			else
			{
				foreach (MMScrollAreaField mMField2 in MMFields)
				{
					if (mMField2.IsUsed && mMField2.DataColumn != null)
					{
						mMField2.DataColumn.Visibility = Visibility.Visible;
					}
				}
			}
			foreach (MMScrollAreaField mMField3 in MMFields)
			{
				if (mMField3.DataColumn != null)
				{
					if (mMField3.DataColumn.Visibility == Visibility.Visible && list.Contains(mMField3.DataColumn))
					{
						DataGrid.FreezeColumn(mMField3.DataColumn);
					}
					mMField3.DataColumn.ApplyVisibilityChange();
				}
			}
		}

