		public Dictionary<int, string> GetVisibleFields()
		{
			return DoGetVisibleFields(isListRequested: true);
		}

		public Dictionary<int, string> DoGetVisibleFields(bool isListRequested)
		{
			try
			{
				Dictionary<int, string> dictionary = new Dictionary<int, string>();
				if (DataTable == null || DataTable.Rows.Count <= 1)
				{
					return null;
				}
				int num = 9999999;
				foreach (BindingDataColumn key in DataColumnMap.Keys)
				{
					if (key.Visibility != Visibility.Visible)
					{
						continue;
					}
					IDataCell dataCell = DataTable.Rows[0][key];
					bool flag = false;
					if (dataCell == null || dataCell.Value == null)
					{
						for (int i = 1; i < DataTable.Rows.Count; i++)
						{
							dataCell = DataTable.Rows[i][key];
							if (dataCell != null && dataCell.Value != null)
							{
								flag = true;
								break;
							}
						}
					}
					else
					{
						flag = true;
					}
					if (!flag || !double.TryParse(dataCell.Value.ToString(), out var _))
					{
						continue;
					}
					if (!isListRequested)
					{
						return dictionary;
					}
					if (key.DisplayIndex >= 0)
					{
						StringBuilder stringBuilder = new StringBuilder();
						List<MMScrollAreaField> list = new List<MMScrollAreaField>();
						list.Add(DataColumnMap[key]);
						MMScrollAreaMSClipboard.GetLabelOfNonHeaderOnlyFields(stringBuilder, list, this, ViewModel, setHeaderLineCount: false);
						stringBuilder.Replace(Environment.NewLine, " ");
						if (key.DisplayIndex == 9999999)
						{
							dictionary.Add(num, stringBuilder.ToString());
							num++;
						}
						else
						{
							dictionary.Add(key.DisplayIndex, stringBuilder.ToString());
						}
					}
				}
				if (!isListRequested && dictionary.Count == 0)
				{
					return null;
				}
				return dictionary;
			}
			catch (Exception)
			{
			}
			return null;
		}

		public IEnumerable<Tuple<int, string>> EnumerateVisibleFields()
		{
			if (DataTable == null || DataTable.Rows.Count <= 1)
			{
				yield break;
			}
			int unallocatedDisplayIndex = 9999999;
			foreach (BindingDataColumn key in DataColumnMap.Keys)
			{
				if (key.Visibility != Visibility.Visible)
				{
					continue;
				}
				IDataCell dataCell = DataTable.Rows[0][key];
				bool flag = false;
				if (dataCell == null || dataCell.Value == null)
				{
					for (int i = 1; i < DataTable.Rows.Count; i++)
					{
						dataCell = DataTable.Rows[i][key];
						if (dataCell != null && dataCell.Value != null)
						{
							flag = true;
							break;
						}
					}
				}
				else
				{
					flag = true;
				}
				if (flag && double.TryParse(dataCell.Value.ToString(), out var _) && key.DisplayIndex >= 0)
				{
					StringBuilder stringBuilder = new StringBuilder();
					List<MMScrollAreaField> list = new List<MMScrollAreaField>();
					list.Add(DataColumnMap[key]);
					MMScrollAreaMSClipboard.GetLabelOfNonHeaderOnlyFields(stringBuilder, list, this, ViewModel, setHeaderLineCount: false);
					stringBuilder.Replace(Environment.NewLine, " ");
					if (key.DisplayIndex == 9999999)
					{
						yield return new Tuple<int, string>(unallocatedDisplayIndex, stringBuilder.ToString());
						unallocatedDisplayIndex++;
					}
					else
					{
						yield return new Tuple<int, string>(key.DisplayIndex, stringBuilder.ToString());
					}
				}
			}
		}

