		public List<string> GetSelectedFields()
		{
			List<string> list = new List<string>();
			foreach (DataCellInfo totalSelectedCell in DataGrid.TotalSelectedCells)
			{
				if (totalSelectedCell.Column != null && totalSelectedCell.Column.Visibility == Visibility.Visible)
				{
					StringBuilder stringBuilder = new StringBuilder();
					List<MMScrollAreaField> list2 = new List<MMScrollAreaField>();
					list2.Add(DataColumnMap[totalSelectedCell.Column as BindingDataColumn]);
					MMScrollAreaMSClipboard.GetLabelOfNonHeaderOnlyFields(stringBuilder, list2, this, ViewModel, setHeaderLineCount: false);
					stringBuilder.Replace(Environment.NewLine, " ");
					if (!list.Contains(stringBuilder.ToString()))
					{
						list.Add(stringBuilder.ToString());
					}
				}
			}
			return list;
		}

		private string GetPropPath(MMScrollAreaField field, int rowId)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(DataProperty).Append("[").Append(rowId.ToString(CultureInfo.InvariantCulture))
				.Append("]");
			if (!string.IsNullOrEmpty(field.PropertyPath))
			{
				stringBuilder.Append(".").Append(field.PropertyPath);
			}
			return stringBuilder.ToString();
		}

		private void PlotVariablesFromSelection(List<object> selection)
		{
			selection.Clear();
			List<DataCellInfo> list = DataGrid.TotalSelectedCells.ToList();
			if (list.Count < 2 || ViewModel == null)
			{
				return;
			}
			int num = -1;
			foreach (DataCellInfo item2 in list)
			{
				BindingDataColumn key = item2.Column as BindingDataColumn;
				if (!DataColumnMap.ContainsKey(key))
				{
					continue;
				}
				BindingDataRow item = item2.Row as BindingDataRow;
				int num2 = (item2.Row.DataTable as BindingDataTable).Rows.IndexOf(item);
				MMScrollAreaField mMScrollAreaField = DataColumnMap[key];
				Type type = mMScrollAreaField.GetType();
				if (type == typeof(MMScrollAreaTextField))
				{
					continue;
				}
				if (type == typeof(MMScrollAreaComboValueField))
				{
					if (!(ViewModel.ResolveViewPropertyPath(GetPropPath(mMScrollAreaField, num2)) is CxvVariableData))
					{
					}
				}
				else if (!(type == typeof(MMScrollAreaBasisField)) && !(type == typeof(MMScrollAreaUnitsField)) && mMScrollAreaField is MMScrollAreaValueField mMScrollAreaValueField && (string.IsNullOrEmpty(mMScrollAreaValueField.VariableDataMember) || mMScrollAreaValueField.VariableDataMember == "Value"))
				{
					object obj = ViewModel.ResolveViewPropertyPath(GetPropPath(mMScrollAreaField, num2));
					if (obj is CxvVariableData cxvVariableData)
					{
						num++;
						selection.Add(new PlotVariableDescriptor
						{
							Path = cxvVariableData.DataPath,
							CurrentValue = cxvVariableData.Value,
							ExposeAs = cxvVariableData.ResolvedExposeAs,
							Column = ((mMScrollAreaValueField.DataColumn == null) ? (-1) : mMScrollAreaValueField.DataColumn.DisplayIndex),
							Location = num2,
							Dimension = cxvVariableData.Dimension,
							Units = cxvVariableData.Units,
							Decorated_name = item2.Column.Header
						});
					}
					else if (obj is AdsVariableData adsVariableData)
					{
						num++;
						selection.Add(new PlotVariableDescriptor
						{
							Path = adsVariableData.DataPath,
							CurrentValue = adsVariableData.Value,
							ExposeAs = CxvVariableTypeCode.Real,
							Column = ((mMScrollAreaValueField.DataColumn == null) ? (-1) : mMScrollAreaValueField.DataColumn.DisplayIndex),
							Location = num2,
							Units = adsVariableData.Units
						});
					}
					else if (obj is CxvParameterPropertyData cxvParameterPropertyData)
					{
						num++;
						selection.Add(new PlotVariableDescriptor
						{
							CurrentValue = cxvParameterPropertyData.Value,
							ExposeAs = CxvVariableTypeCode.String,
							Column = ((mMScrollAreaValueField.DataColumn == null) ? (-1) : mMScrollAreaValueField.DataColumn.DisplayIndex),
							Location = num2,
							Units = null
						});
					}
					else if (obj is CxvManualVariableData { Path: not null } cxvManualVariableData)
					{
						num++;
						selection.Add(new PlotVariableDescriptor
						{
							Path = cxvManualVariableData.Path,
							CurrentValue = cxvManualVariableData.Value,
							ExposeAs = CxvVariableTypeCode.Real,
							Column = ((mMScrollAreaValueField.Field == null) ? (-1) : mMScrollAreaValueField.Field.Column),
							Location = num,
							Decorated_name = item2.Column.Header
						});
					}
				}
			}
		}

