		public void SelectField(int displayId, bool clearCurrentSelection)
		{
			if (clearCurrentSelection)
			{
				ClearSelection();
			}
			if (displayId < DataTable.Columns.Count)
			{
				DataColumn columnByDisplayId = GetColumnByDisplayId(displayId);
				if (columnByDisplayId != null)
				{
					DataGrid.SelectColumn(columnByDisplayId);
				}
			}
		}

		private DataColumn GetColumnByDisplayId(int displayId)
		{
			return DataTable.Columns.Where((DataColumn c) => c.DisplayIndex == displayId).FirstOrDefault();
		}

		public void UnSelectField(int displayId)
		{
			if (displayId < DataTable.Columns.Count)
			{
				DataColumn columnByDisplayId = GetColumnByDisplayId(displayId);
				if (columnByDisplayId != null)
				{
					DataGrid.DeselectColumn(columnByDisplayId);
				}
			}
		}

		string IScrollAreaSettings.SaveGridSettings()
		{
			if (DataGrid == null)
			{
				return null;
			}
			return DataGrid.SaveLayoutSettings();
		}

		void IScrollAreaSettings.RestoreGridSettings(string settings)
		{
			if (DataGrid != null)
			{
				DataGrid.LoadLayoutSettings(settings);
				_isLayoutSettingRestored = true;
			}
		}

		private void TrySubscribeEvents()
		{
			if (!_hasSubscribedEvents)
			{
				if (base.DataContext is CxvViewModel { UnityContainer: not null } cxvViewModel)
				{
					CxvUnityContainerExtensions.TryResolve<IEventAggregator>(cxvViewModel.UnityContainer)?.GetEvent<UpdateDisplayEvent>().Subscribe(OnUpdateDisplayEvent);
				}
				_hasSubscribedEvents = true;
			}
		}

		private void UnsubscribeEvents()
		{
			if (base.DataContext is CxvViewModel { UnityContainer: not null } cxvViewModel)
			{
				CxvUnityContainerExtensions.TryResolve<IEventAggregator>(cxvViewModel.UnityContainer)?.GetEvent<UpdateDisplayEvent>().Unsubscribe(OnUpdateDisplayEvent);
			}
		}

		private void OnUpdateDisplayEvent(UpdateDisplayEventArgs args)
		{
			if (DataGrid != null && DataRetriever != null)
			{
				DataGrid.InvalidateData();
			}
		}

		public void InvalidateGridData()
		{
			DataGrid.InvalidateData();
		}

		public void PublishUpdateDisplayEvent()
		{
			if (base.DataContext is MMViewModel mMViewModel)
			{
				mMViewModel.UpdateDisplay();
				mMViewModel.UpdateAll();
			}
		}

		public void Dispose()
		{
			Dispose(disposing: true);
			GC.SuppressFinalize(this);
		}

		~MMScrollAreaMS()
		{
			Dispose(disposing: false);
		}

		protected virtual void Dispose(bool disposing)
		{
			if (!disposing)
			{
				return;
			}
			if (MMFields != null)
			{
				foreach (MMScrollAreaField mMField in MMFields)
				{
					if (mMField is IDisposable disposable)
					{
						disposable.Dispose();
					}
				}
				_MMFields = null;
			}
			if (_MMColumnSets != null)
			{
				foreach (MMScrollAreaColumnSet mMColumnSet in MMColumnSets)
				{
					mMColumnSet.Dispose();
				}
				_MMColumnSets = null;
			}
			ClearExpandedFieldDependencies();
			ClearDataPropertyDependencies();
			if (ClipboardDataObject != null)
			{
				ClipboardDataObject.Dispose();
			}
		}

		protected override AutomationPeer OnCreateAutomationPeer()
		{
			return new UIACustomControlAutomationPeer(this)
			{
				ClassName = GetType().Name,
				GetNameFunction = (FrameworkElement control) => (control as MMScrollAreaMS).Name
			};
		}

		private static System.Windows.Controls.Image GetContextItemIcon(string strImage)
		{
			System.Windows.Controls.Image image = new System.Windows.Controls.Image();
			string text = "pack://application:,,,/" + typeof(MMScrollAreaContextMenu).Assembly.FullName + ";component/Images/";
			image.Source = new BitmapImage(new Uri(text + strImage));
			return image;
		}

		private void SetCanInsertDelete2ndLevelVector(MMScrollAreaFieldRepeater repeaterField)
		{
			CanDelete2ndLevelVector = false;
			CanInsert2ndLevelVector = false;
			if (base.DataContext != null && new CxvPropertyWatch().ResolvePropertyPath(this, string.Format(CultureInfo.InvariantCulture, "DataContext.{0}[0].{1}", DataProperty, repeaterField.SecondLevelVectorProperty)) is IBindingList bindingList)
			{
				CanDelete2ndLevelVector = bindingList.AllowRemove;
				CanInsert2ndLevelVector = bindingList.AllowNew;
			}
		}

		private void SetCanInsertDelete1stLevelVector(bool attachCountChange)
		{
			CxvVectorPropertyData firstLevelVectorData = FirstLevelVectorData;
			if (firstLevelVectorData != null)
			{
				CanInsert1stLevelVector = firstLevelVectorData.AllowNew;
				CanDelete1stLevelVector = firstLevelVectorData.AllowRemove;
				if (attachCountChange && firstLevelVectorData.IndexBasis != null)
				{
					firstLevelVectorData.IndexBasis.CountChanged += IndexBasis_CountChanged;
				}
			}
		}

		private void IndexBasis_CountChanged(object sender, EventArgs e)
		{
			SetCanInsertDelete1stLevelVector(attachCountChange: false);
		}

		private static bool CanDeleteSelectedColumnVertical(MMScrollAreaMS sa)
		{
			bool flag = true;
			foreach (DataColumn selectedColumn in sa.DataGrid.SelectedColumns)
			{
				if (!(selectedColumn.Tag is MMScrollAreaField { ExpandedId: not null }))
				{
					flag = false;
					break;
				}
			}
			if (flag)
			{
				new CxvPropertyWatch();
				List<MMScrollAreaField> list = new List<MMScrollAreaField>();
				if (sa.DataGrid.SelectedColumns.Count() > 0)
				{
					foreach (DataColumn selectedColumn2 in sa.DataGrid.SelectedColumns)
					{
						list.Add(selectedColumn2.Tag as MMScrollAreaField);
					}
				}
				else
				{
					if (sa.DataGrid.SelectedCells.Count() != 1)
					{
						return false;
					}
					list.Add(sa.DataGrid.SelectedCells.First().Column.Tag as MMScrollAreaField);
				}
				CxvVectorPropertyData secondLevelVectorData = sa.SecondLevelVectorData;
				if (secondLevelVectorData != null)
				{
					foreach (MMScrollAreaField item in list)
					{
						if (item == null || !item.ExpandedId.HasValue || !secondLevelVectorData.AllowRemoveAt(item.ExpandedId.Value))
						{
							flag = false;
							break;
						}
					}
				}
			}
			return flag;
		}

		private static bool CanDeleteSelectedRowVertical(MMScrollAreaMS sa)
		{
			new CxvPropertyWatch();
			CxvVectorPropertyData firstLevelVectorData = sa.FirstLevelVectorData;
			if (firstLevelVectorData == null)
			{
				return false;
			}
			if (sa.DataGrid.SelectedRows.Count() == 0 && sa.DataGrid.SelectedCells.Count() == 1)
			{
				int num = sa.DataGrid.DataSource.Rows.IndexOf(sa.DataGrid.SelectedCells.First().Row);
				if (num < 0)
				{
					return false;
				}
				if (firstLevelVectorData.IndexBasis != null)
				{
					return firstLevelVectorData.IndexBasis.AllowRemoveAt(num);
				}
			}
			else if (sa.DataGrid.SelectedRows.Count() > 0 && firstLevelVectorData.IndexBasis != null)
			{
				foreach (DataRow selectedRow in sa.DataGrid.SelectedRows)
				{
					if (firstLevelVectorData.IndexBasis.AllowRemoveAt(sa.DataGrid.DataSource.Rows.IndexOf(selectedRow)))
					{
						return true;
					}
				}
			}
			return false;
		}

		private static void InsertFieldVertical(MMScrollAreaMS sa)
		{
			MMScrollAreaField mMScrollAreaField = null;
			if (sa.DataGrid.SelectedColumns.Count() > 0)
			{
				mMScrollAreaField = sa.DataGrid.SelectedColumns.First().Tag as MMScrollAreaField;
			}
			else if (sa.DataGrid.SelectedCells.Count() > 0)
			{
				mMScrollAreaField = sa.DataGrid.SelectedCells.First().Column.Tag as MMScrollAreaField;
			}
			if (mMScrollAreaField == null)
			{
				return;
			}
			MMScrollAreaFieldRepeater expandedFromRepeater = mMScrollAreaField.ExpandedFromRepeater;
			if (expandedFromRepeater == null || sa.CxsProvider == null)
			{
				return;
			}
			CxvVectorPropertyData firstLevelVectorData = sa.FirstLevelVectorData;
			if (firstLevelVectorData == null)
			{
				return;
			}
			CxvPropertyWatch cxvPropertyWatch = new CxvPropertyWatch();
			if (firstLevelVectorData.IndexBasis.IsNotJagged.HasValue && !firstLevelVectorData.IndexBasis.IsNotJagged.Value)
			{
				int num = firstLevelVectorData.Count;
				if (!(firstLevelVectorData.IndexBasis is CxvChildCountIndexBasisData cxvChildCountIndexBasisData))
				{
					return;
				}
				if (cxvChildCountIndexBasisData.HasProxyRow)
				{
					num--;
				}
				sa.CxsProvider.SuspendNotifications();
				try
				{
					Mouse.SetCursor(Cursors.Wait);
					for (int i = 0; i < num; i++)
					{
						(cxvPropertyWatch.ResolvePropertyPath(sa, string.Format(CultureInfo.InvariantCulture, "DataContext.{0}[{1}].{2}", sa.DataProperty, i.ToString(), expandedFromRepeater.SecondLevelVectorProperty)) as IBindingList).Insert(mMScrollAreaField.ExpandedId.Value, null);
					}
					return;
				}
				catch (Exception)
				{
					return;
				}
				finally
				{
					sa.CxsProvider.ResumeNotifications();
					Mouse.SetCursor(Cursors.Arrow);
				}
			}
			try
			{
				Mouse.SetCursor(Cursors.Wait);
				(cxvPropertyWatch.ResolvePropertyPath(sa, string.Format(CultureInfo.InvariantCulture, "DataContext.{0}[0].{1}", sa.DataProperty, expandedFromRepeater.SecondLevelVectorProperty)) as IBindingList).Insert(mMScrollAreaField.ExpandedId.Value, null);
			}
			finally
			{
				Mouse.SetCursor(Cursors.Arrow);
			}
		}

		private void DeleteFieldVertical()
		{
			if (!CanDeleteSelectedColumnVertical(this))
			{
				return;
			}
			AesMessageBoxResult aesMessageBoxResult = AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strConfirmDeleteField, AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteColumn, AesMessageBoxButton.YesNo, AesMessageBoxImage.Question, showHelpButton: false, 2);
			if (aesMessageBoxResult == AesMessageBoxResult.No || aesMessageBoxResult == AesMessageBoxResult.Cancel)
			{
				return;
			}
			try
			{
				Mouse.SetCursor(Cursors.Wait);
				CxsProvider.SuspendNotifications();
				List<int> list = new List<int>();
				MMScrollAreaFieldRepeater mMScrollAreaFieldRepeater = null;
				if (DataGrid.SelectedColumns.Count() > 0)
				{
					foreach (DataColumn selectedColumn in DataGrid.SelectedColumns)
					{
						MMScrollAreaField mMScrollAreaField = selectedColumn.Tag as MMScrollAreaField;
						if (mMScrollAreaFieldRepeater == null)
						{
							mMScrollAreaFieldRepeater = mMScrollAreaField.ExpandedFromRepeater;
						}
						else if (mMScrollAreaFieldRepeater != mMScrollAreaField.ExpandedFromRepeater)
						{
							throw new NotSupportedException();
						}
						list.Add(mMScrollAreaField.ExpandedId.Value);
					}
				}
				else if (DataGrid.SelectedCells.Count() == 1)
				{
					MMScrollAreaField mMScrollAreaField2 = DataGrid.SelectedCells.First().Column.Tag as MMScrollAreaField;
					if (mMScrollAreaFieldRepeater == null)
					{
						mMScrollAreaFieldRepeater = mMScrollAreaField2.ExpandedFromRepeater;
					}
					else if (mMScrollAreaFieldRepeater != mMScrollAreaField2.ExpandedFromRepeater)
					{
						throw new NotSupportedException();
					}
					list.Add(mMScrollAreaField2.ExpandedId.Value);
				}
				list.Sort();
				IBindingList bindingList = new CxvPropertyWatch().ResolvePropertyPath(this, string.Format(CultureInfo.InvariantCulture, "DataContext.{0}[0].{1}", DataProperty, mMScrollAreaFieldRepeater.SecondLevelVectorProperty)) as IBindingList;
				for (int num = list.Count - 1; num >= 0; num--)
				{
					try
					{
						bindingList.RemoveAt(list[num]);
					}
					catch (InvalidOperationException)
					{
					}
					catch (CxsException)
					{
					}
				}
			}
			finally
			{
				CxsProvider.ResumeNotifications();
				Mouse.SetCursor(Cursors.Arrow);
			}
		}

		private static void InsertRecordVertical(MMScrollAreaMS sa, int rowId)
		{
			if (rowId < 0)
			{
				return;
			}
			bool flag = true;
			CxvVectorPropertyData firstLevelVectorData = sa.FirstLevelVectorData;
			if (firstLevelVectorData == null)
			{
				return;
			}
			try
			{
				Mouse.SetCursor(Cursors.Wait);
				firstLevelVectorData.Insert(rowId, null);
			}
			catch (InvalidOperationException)
			{
				flag = false;
			}
			catch (CxsException)
			{
				flag = false;
			}
			finally
			{
				Mouse.SetCursor(Cursors.Arrow);
			}
			if (!flag)
			{
				AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strInsertRowFailed, AspenTech.AspenPlus.MMControls.Properties.Resources.DialogTitle_InsertRecord, AesMessageBoxButton.OK, AesMessageBoxImage.Error);
			}
		}

		private void DeleteRecordVertical(IEnumerable<int> selectedIds)
		{
			if (CxsProvider == null)
			{
				return;
			}
			CxvVectorPropertyData firstLevelVectorData = FirstLevelVectorData;
			if (firstLevelVectorData == null)
			{
				return;
			}
			ClearSelection();
			CxsProvider.SuspendNotifications();
			bool flag = true;
			try
			{
				Mouse.SetCursor(Cursors.Wait);
				firstLevelVectorData.RemoveAt(selectedIds.OrderByDescending((int x) => x).ToList());
			}
			catch (InvalidOperationException)
			{
			}
			catch (CxsException)
			{
				flag = false;
			}
			catch (Exception)
			{
			}
			finally
			{
				CxsProvider.ResumeNotifications();
				Mouse.SetCursor(Cursors.Wait);
			}
			if (!flag)
			{
				AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRowFailed, AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRow, AesMessageBoxButton.OK, AesMessageBoxImage.Error);
			}
		}

		private void DeleteSelectedColumns()
		{
			if (base.DataContext == null)
			{
				return;
			}
			if (DataOrientation == Orientation.Vertical)
			{
				DeleteFieldVertical();
				return;
			}
			AesMessageBoxResult aesMessageBoxResult = AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strConfirmDeleteField, AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteColumn, AesMessageBoxButton.YesNo, AesMessageBoxImage.Question, showHelpButton: false, 2);
			if (aesMessageBoxResult == AesMessageBoxResult.No || aesMessageBoxResult == AesMessageBoxResult.Cancel)
			{
				return;
			}
			SortedSet<int> sortedSet = new SortedSet<int>();
			if (DataGrid.SelectedColumns.Count() > 0)
			{
				foreach (DataColumn selectedColumn in DataGrid.SelectedColumns)
				{
					int num = DataGrid.DataSource.Columns.IndexOf(selectedColumn) - 1;
					if (num >= 0)
					{
						sortedSet.Add(num);
					}
				}
			}
			else
			{
				if (DataGrid.SelectedCells.Count() != 1)
				{
					return;
				}
				int num2 = DataGrid.DataSource.Columns.IndexOf(DataGrid.SelectedCells.First().Column) - 1;
				if (num2 >= 0)
				{
					sortedSet.Add(num2);
				}
			}
			DeleteRecordVertical(sortedSet);
		}

		private void DeleteSelectedRows()
		{
			if (DataOrientation != Orientation.Vertical)
			{
				return;
			}
			AesMessageBoxResult aesMessageBoxResult = AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strConfirmDeleteRecord, AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRow, AesMessageBoxButton.YesNo, AesMessageBoxImage.Question, showHelpButton: false, 2);
			if (aesMessageBoxResult == AesMessageBoxResult.No || aesMessageBoxResult == AesMessageBoxResult.Cancel)
			{
				return;
			}
			List<int> list = DataGrid.SelectedRows.Select((DataRow x) => DataGrid.DataSource.Rows.IndexOf(x)).ToList();
			if (list.Count == 0 && DataGrid.SelectedCells.Count() == 1)
			{
				list.Add(DataGrid.DataSource.Rows.IndexOf(DataGrid.SelectedCells.First().Row));
			}
			if (DataGrid?.DataSource is BindingDataTable { ItemsSource: CxvVectorPropertyData { IndexBasis: CxvChildCountIndexBasisData { HasProxyRow: not false } } })
			{
				int item = DataGrid.DataSource.Rows.Count - 1;
				if (list.Contains(item))
				{
					list.Remove(item);
				}
			}
			if (DataRetriever != null && DataRetriever.GetService(typeof(IDataRetrieverServiceRowsRemover)) is IDataRetrieverServiceRowsRemover dataRetrieverServiceRowsRemover)
			{
				dataRetrieverServiceRowsRemover.RemoveRows(list, out var handled);
				if (handled)
				{
					UpdateDataCache();
					PublishUpdateDisplayEvent();
					return;
				}
			}
			if (list.Count > 0)
			{
				DeleteRecordVertical(list);
			}
		}

		private void AddContextMenu(DefaultContextMenuEventArgs e)
		{
			if (e.DefaultContextMenu.Items.Count > 0)
			{
				e.DefaultContextMenu.Items.Insert(0, new Separator());
			}
			e.DefaultContextMenu.Items.Add(new MenuItem
			{
				Icon = new System.Windows.Controls.Image
				{
					Source = ImageSourceHelper.Copy16
				},
				Command = ApplicationCommands.Copy,
				CommandTarget = e.GridControl
			});
			bool flag = true;
			bool flag2 = true;
			if (e.IsOpenFromGridCell)
			{
				DataCellInfo currentCell = e.GridControl.CurrentCell;
				if (currentCell.Column != null)
				{
					MMScrollAreaField mMScrollAreaField = ((DataOrientation != Orientation.Vertical) ? (currentCell.Row as MMScrollAreaMSInversionDataTable.MSInversionDataRow)?.Field : (currentCell.Column.Tag as MMScrollAreaField));
					if (mMScrollAreaField != null && mMScrollAreaField.AllowPaste.HasValue)
					{
						flag = mMScrollAreaField.AllowPaste.Value;
					}
					if (mMScrollAreaField != null && mMScrollAreaField.AllowClear.HasValue)
					{
						flag2 = mMScrollAreaField.AllowClear.Value;
					}
				}
			}
			else if (e.IsOpenFromColumnHeader)
			{
				IEnumerable<DataColumn> selectedColumns = e.GridControl.SelectedColumns;
				if (selectedColumns != null && selectedColumns.Count() > 0 && selectedColumns.ElementAt(0).Tag is MMScrollAreaField { AllowPaste: not null, AllowPaste: var allowPaste })
				{
					flag = allowPaste.Value;
				}
			}
			if (!e.IsOpenFromHeaderPrefixArea && flag)
			{
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = new System.Windows.Controls.Image
					{
						Source = ImageSourceHelper.Paste16
					},
					Command = ApplicationCommands.Paste,
					CommandTarget = e.GridControl
				});
			}
			if (e.IsOpenFromGridCell && flag2)
			{
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = GetContextItemIcon("Clear16.ico"),
					Command = ClearCommand,
					CommandParameter = e.SourceCell,
					CommandBindings = 
					{
						new CommandBinding(ClearCommand, OnClearCommand, CanClearCommand)
					}
				});
			}
			if (e.IsOpenFromColumnHeader || (e.IsOpenFromGridCell && DataGrid.SelectedRows.Count() == 0))
			{
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = GetContextItemIcon("DeleteColumn.ico"),
					Command = DeleteFieldCommand,
					CommandParameter = this,
					CommandBindings = 
					{
						new CommandBinding(DeleteFieldCommand, OnDeleteFieldCommand, CanDeleteFieldCommand)
					}
				});
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = GetContextItemIcon("InsertColumn.ico"),
					Command = InsertFieldCommand,
					CommandParameter = this,
					CommandBindings = 
					{
						new CommandBinding(InsertFieldCommand, OnInsertFieldCommand, CanInsertFieldCommand)
					}
				});
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Command = ReorderFieldCommand,
					CommandParameter = this,
					CommandBindings = 
					{
						new CommandBinding(ReorderFieldCommand, OnReorderFieldCommand, CanReorderFieldCommand)
					}
				});
			}
			if (e.IsOpenFromRowHeader || (e.IsOpenFromGridCell && DataGrid.SelectedColumns.Count() == 0))
			{
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = GetContextItemIcon("DeleteRow16.ico"),
					Command = DeleteRecordCommand,
					CommandParameter = this,
					CommandBindings = 
					{
						new CommandBinding(DeleteRecordCommand, OnDeleteRecordCommand, CanDeleteRecordCommand)
					}
				});
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = GetContextItemIcon("InsertRow16.ico"),
					Command = InsertRecordCommand,
					CommandParameter = this,
					CommandBindings = 
					{
						new CommandBinding(InsertRecordCommand, OnInsertRecordCommand, CanInsertRecordCommand)
					}
				});
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Command = RoutedReorderRecordCommand,
					CommandParameter = this,
					CommandBindings = 
					{
						new CommandBinding(RoutedReorderRecordCommand, OnRoutedReorderRecordCommand, CanRoutedReorderRecordCommand)
					}
				});
			}
		}

		internal static void OnInsertFieldCommand(object sender, ExecutedRoutedEventArgs arg)
		{
			if (!(arg.Parameter is MMScrollAreaMS { DataContext: not null } mMScrollAreaMS))
			{
				return;
			}
			if (mMScrollAreaMS.DataOrientation == Orientation.Vertical)
			{
				InsertFieldVertical(mMScrollAreaMS);
				return;
			}
			int num = -1;
			if (mMScrollAreaMS.DataGrid.SelectedColumns.Count() == 1)
			{
				num = mMScrollAreaMS.DataGrid.DataSource.Columns.IndexOf(mMScrollAreaMS.DataGrid.SelectedColumns.First()) - 1;
			}
			else
			{
				if (mMScrollAreaMS.DataGrid.SelectedCells.Count() != 1)
				{
					return;
				}
				num = mMScrollAreaMS.DataGrid.DataSource.Columns.IndexOf(mMScrollAreaMS.DataGrid.SelectedCells.First().Column) - 1;
			}
			InsertRecordVertical(mMScrollAreaMS, num);
		}

		internal static void CanInsertFieldCommand(object sender, CanExecuteRoutedEventArgs arg)
		{
			arg.CanExecute = false;
			if (!(arg.Parameter is MMScrollAreaMS mMScrollAreaMS) || mMScrollAreaMS.DataGrid.SelectedColumns.Count() > 1)
			{
				return;
			}
			if (mMScrollAreaMS.DataOrientation == Orientation.Vertical)
			{
				if (mMScrollAreaMS.CanInsert2ndLevelVector)
				{
					arg.CanExecute = CanDeleteSelectedColumnVertical(mMScrollAreaMS);
				}
			}
			else if (mMScrollAreaMS.DataGrid.SelectedColumns.Count() == 0)
			{
				if (mMScrollAreaMS.DataGrid.SelectedCells.Count() > 1)
				{
					arg.CanExecute = false;
					return;
				}
				DataCellInfo dataCellInfo = mMScrollAreaMS.DataGrid.SelectedCells.FirstOrDefault();
				if (dataCellInfo.Column != null && dataCellInfo.Column.DisplayIndex >= 1 && mMScrollAreaMS.FirstLevelVectorData != null && mMScrollAreaMS.FirstLevelVectorData.AllowRemoveAt(dataCellInfo.Column.DisplayIndex - 1))
				{
					arg.CanExecute = true;
				}
			}
			else
			{
				arg.CanExecute = mMScrollAreaMS.CanInsert1stLevelVector;
			}
		}

