		internal static void CanDeleteFieldCommand(object sender, CanExecuteRoutedEventArgs arg)
		{
			if (!(arg.Parameter is MMScrollAreaMS mMScrollAreaMS))
			{
				return;
			}
			if (mMScrollAreaMS.DataOrientation == Orientation.Vertical)
			{
				if (mMScrollAreaMS.CanDelete2ndLevelVector)
				{
					arg.CanExecute = CanDeleteSelectedColumnVertical(mMScrollAreaMS);
				}
			}
			else if (mMScrollAreaMS.DataGrid.SelectedColumns.Count() == 0)
			{
				if (mMScrollAreaMS.DataGrid.SelectedCells.Count() > 1)
				{
					arg.CanExecute = false;
					return;
				}
				DataCellInfo dataCellInfo = mMScrollAreaMS.DataGrid.SelectedCells.FirstOrDefault();
				if (dataCellInfo.Column != null && dataCellInfo.Column.DisplayIndex >= 1 && mMScrollAreaMS.FirstLevelVectorData != null && mMScrollAreaMS.FirstLevelVectorData.AllowRemoveAt(dataCellInfo.Column.DisplayIndex - 1))
				{
					arg.CanExecute = true;
				}
			}
			else if (mMScrollAreaMS.DataGrid.SelectedColumns.Count() == 1)
			{
				DataColumn dataColumn = mMScrollAreaMS.DataGrid.SelectedColumns.FirstOrDefault();
				if (dataColumn != null && dataColumn.DisplayIndex <= 0)
				{
					arg.CanExecute = false;
				}
				else if (dataColumn != null && dataColumn.DisplayIndex >= 1 && mMScrollAreaMS.FirstLevelVectorData != null && mMScrollAreaMS.FirstLevelVectorData.AllowRemoveAt(dataColumn.DisplayIndex - 1))
				{
					arg.CanExecute = true;
				}
			}
			else
			{
				arg.CanExecute = mMScrollAreaMS.CanDelete1stLevelVector;
			}
		}

