		private static void ReorderFirstLevel(MMScrollAreaMS sa)
		{
			if (!(sa.DataContext is MMViewModel viewModel))
			{
				return;
			}
			sa.DataGrid.SortingInfo.ClearSorts();
			MMScrollAreaReorder mMScrollAreaReorder = new MMScrollAreaReorder
			{
				AllowUseValueInReorder = sa.AllowUseValueInReorder
			};
			mMScrollAreaReorder.ViewModel = viewModel;
			mMScrollAreaReorder.DataProperty = sa.DataProperty;
			if (sa.DisplayEntireRowWhenReorder)
			{
				List<string> list = new List<string>();
				int count = sa.DataGrid.DataSource.Columns.Count;
				foreach (DataRow row in sa.DataGrid.DataSource.Rows)
				{
					StringBuilder stringBuilder = new StringBuilder();
					for (int i = 0; i < count; i++)
					{
						if (!string.IsNullOrEmpty(row[i].ValueAsString))
						{
							stringBuilder.Append(row[i].ValueAsString + " ");
						}
					}
					list.Add(stringBuilder.ToString());
				}
				mMScrollAreaReorder.DisplayItems = list;
			}
			mMScrollAreaReorder.ShowDialog();
			sa.ClearSelection();
		}

		private static void ReorderSecondLevel(MMScrollAreaMS sa)
		{
			if (sa.DataContext is MMViewModel viewModel)
			{
				MMScrollAreaFieldRepeater firstRepeaterField = sa.GetFirstRepeaterField();
				if (firstRepeaterField != null)
				{
					sa.DataGrid.SortingInfo.ClearSorts();
					MMScrollAreaReorder mMScrollAreaReorder = new MMScrollAreaReorder();
					mMScrollAreaReorder.AllowUseValueInReorder = sa.AllowUseValueInReorder;
					mMScrollAreaReorder.ViewModel = viewModel;
					mMScrollAreaReorder.DataProperty = $"{sa.DataProperty}[0].{firstRepeaterField.SecondLevelVectorProperty}";
					mMScrollAreaReorder.ShowDialog();
					sa.ClearSelection();
				}
			}
		}

		private void ClearSelectedCells()
		{
			if (base.DataContext == null || DataGrid.TotalSelectedCells.Count() == 0 || CxsProvider == null)
			{
				return;
			}
			try
			{
				foreach (DataCellInfo item in DataGrid.SelectedCells.OrderByDescending((DataCellInfo p) => DataGrid.DataSource.Rows.IndexOf(p.Row)))
				{
					bool flag = true;
					if (item.Column != null)
					{
						MMScrollAreaField mMScrollAreaField = ((DataOrientation != Orientation.Vertical) ? (item.Row as MMScrollAreaMSInversionDataTable.MSInversionDataRow)?.Field : (item.Column.Tag as MMScrollAreaField));
						if (mMScrollAreaField != null && mMScrollAreaField.AllowClear.HasValue)
						{
							flag = mMScrollAreaField.AllowClear.Value;
						}
					}
					if (!item.Data.IsReadOnly && flag)
					{
						item.Data.ClearValue();
					}
				}
			}
			catch (Exception)
			{
			}
		}

		internal static void OnClearCommand(object sender, ExecutedRoutedEventArgs arg)
		{
			if (!(arg.Parameter is GridControlCell gridControlCell))
			{
				return;
			}
			GridControl grid = gridControlCell.GridColumn.GridControlOwner;
			if (grid == null)
			{
				return;
			}
			foreach (DataCellInfo item in grid.TotalSelectedCells.OrderByDescending((DataCellInfo p) => grid.DataSource.Rows.IndexOf(p.Row)))
			{
				try
				{
					if (CanDataCellClear(item))
					{
						item.Data.ClearValue();
					}
				}
				catch (Exception)
				{
				}
			}
		}

		internal static void CanClearCommand(object sender, CanExecuteRoutedEventArgs arg)
		{
			bool canExecute = false;
			if (arg.Parameter is GridControlCell gridControlCell)
			{
				foreach (DataCellInfo totalSelectedCell in gridControlCell.GridColumn.GridControlOwner.TotalSelectedCells)
				{
					if (CanDataCellClear(totalSelectedCell))
					{
						canExecute = true;
						break;
					}
				}
			}
			arg.CanExecute = canExecute;
		}

		internal static object GetCellBindingVariable(DataCellInfo c)
		{
			object result = null;
			if (c.Row.DataTable is MMScrollAreaMSDataTable mMScrollAreaMSDataTable)
			{
				result = mMScrollAreaMSDataTable.GetBindingVariable(c.Data);
			}
			else if (c.Row.DataTable is MMScrollAreaMSInversionDataTable mMScrollAreaMSInversionDataTable)
			{
				result = mMScrollAreaMSInversionDataTable.GetBindingVariable(c.Data);
			}
			return result;
		}

		public static bool CanDataCellClear(DataCellInfo c)
		{
			if (c.Data != null && !c.Data.IsReadOnly)
			{
				object cellBindingVariable = GetCellBindingVariable(c);
				if (cellBindingVariable is CxvVariableData { IsEntered: var isEntered } cxvVariableData)
				{
					if ((isEntered ?? false) && (cxvVariableData.IsEnabled ?? true) && !cxvVariableData.IsReadOnly)
					{
						return true;
					}
				}
				else if (cellBindingVariable is CxvParameterPropertyData { IsEntered: var isEntered2 } cxvParameterPropertyData)
				{
					if ((isEntered2 ?? false) && !cxvParameterPropertyData.IsReadOnly)
					{
						return true;
					}
				}
				else if (cellBindingVariable is CxvMultiMapPropertyData { IsEntered: var isEntered3 } cxvMultiMapPropertyData)
				{
					if ((isEntered3 ?? false) && (cxvMultiMapPropertyData.IsEnabled ?? true) && !cxvMultiMapPropertyData.IsReadOnly)
					{
						return true;
					}
				}
				else if (cellBindingVariable is CxvBooleanPropertyData { IsEntered: var isEntered4 } cxvBooleanPropertyData && (isEntered4 ?? false) && (cxvBooleanPropertyData.IsEnabled ?? true) && cxvBooleanPropertyData.IsReadOnly != true)
				{
					return true;
				}
			}
			return false;
		}

		private MMScrollAreaFieldRepeater GetFirstRepeaterField()
		{
			if (MMFields == null)
			{
				return null;
			}
			MMScrollAreaFieldRepeater mMScrollAreaFieldRepeater = null;
			foreach (MMScrollAreaField mMField in MMFields)
			{
				mMScrollAreaFieldRepeater = mMField as MMScrollAreaFieldRepeater;
				if (mMScrollAreaFieldRepeater != null)
				{
					break;
				}
			}
			return mMScrollAreaFieldRepeater;
		}

