		protected void SetSelectedRow()
		{
			if (_suppressSetSelectedRow || SelectedRowIds == null || SelectedRowIds.Count == 0 || DataGrid.DataSource == null)
			{
				return;
			}
			_suppressSetSelectedRow = true;
			DataGrid.SupressSelectionChangedEvent = true;
			ClearSelection();
			List<int> list = SelectedRowIds.ToList();
			foreach (int item in list)
			{
				if (item < DataGrid.DataSource.Rows.Count)
				{
					DataGrid.SelectRow(DataGrid.DataSource.Rows[item]);
				}
			}
			if (list.Count > 0 && list[0] < DataGrid.DataSource.Rows.Count)
			{
				DataGrid.ScrollIntoView(DataGrid.DataSource.Rows[list[0]]);
			}
			DataGrid.SupressSelectionChangedEvent = false;
			_suppressSetSelectedRow = false;
		}

		private void SetSelectedField()
		{
			if (_suppressSetSelectedField || SelectedFieldIds == null || SelectedFieldIds.Count == 0 || DataGrid.DataSource == null)
			{
				return;
			}
			_suppressSetSelectedField = true;
			ClearSelection();
			List<int> list = SelectedFieldIds.ToList();
			foreach (int item in list)
			{
				int num = item;
				if (DataOrientation == Orientation.Horizontal)
				{
					num++;
				}
				if (num < DataGrid.DataSource.Columns.Count)
				{
					DataGrid.SelectColumn(DataGrid.DataSource.Columns[num]);
				}
			}
			if (list.Count > 0)
			{
				int num2 = list[0];
				if (DataOrientation == Orientation.Horizontal)
				{
					num2++;
				}
				DataGrid.ScrollIntoView(DataGrid.DataSource.Columns[num2]);
			}
			_suppressSetSelectedField = false;
		}

		public void SetSelection()
		{
			if (_suppressSetSelectedField || _suppressSetSelectedRow)
			{
				return;
			}
			_suppressSetSelectedRow = true;
			_suppressSetSelectedField = true;
			List<int> list = new List<int>();
			if (SelectedFieldIds == null)
			{
				SelectedFieldIds = new ObservableCollection<int>();
			}
			else
			{
				SelectedFieldIds.Clear();
			}
			foreach (DataCellInfo totalOrderedSelectedCell in DataGrid.TotalOrderedSelectedCells)
			{
				int num = DataGrid.DataSource.Rows.IndexOf(totalOrderedSelectedCell.Row);
				if (num >= 0 && !list.Contains(num))
				{
					list.Add(num);
				}
				int num2 = DataGrid.DataSource.Columns.IndexOf(totalOrderedSelectedCell.Column);
				if (DataOrientation == Orientation.Horizontal)
				{
					num2--;
				}
				if (num2 >= 0 && !SelectedFieldIds.Contains(num2))
				{
					SelectedFieldIds.Add(num2);
				}
			}
			SelectedRowIds = new ObservableCollection<int>(list);
			SelectedRowsCount = SelectedRowIds.Count;
			_suppressSetSelectedRow = false;
			_suppressSetSelectedField = false;
		}

		public void SelectCell(int rowId, int colId)
		{
			ClearSelection();
			if (DataOrientation == Orientation.Horizontal)
			{
				colId++;
			}
			DataCellInfo cell = new DataCellInfo(DataGrid.DataSource.Rows[rowId], DataGrid.DataSource.Columns[colId]);
			DataGrid.SelectCell(cell);
			DataGrid.ScrollIntoView(cell);
		}

		public void ClearSelection()
		{
			DataGrid?.DeselectAll();
		}

