		private void OnDataDragging(GridControlDataDraggingEventArgs e)
		{
			using MMScrollAreaMSClipboard mMScrollAreaMSClipboard = new MMScrollAreaMSClipboard();
			DataColumn dataColumn = DataGrid.SelectedColumns.FirstOrDefault();
			mMScrollAreaMSClipboard.IncludeColumnHeader = dataColumn != null;
