			string asiSelectionXml = ClipboardHelper.GetAsiSelectionXml(mMScrollAreaMSClipboard.Monikers, mMScrollAreaMSClipboard.CaseFullFileName, mMScrollAreaMSClipboard.ApplicationName);
			e.DataObject.SetData(DataFormats.GetDataFormat("ASI Format").Name, asiSelectionXml);
		}

