		private static void UpdateEnterableCellFonts(IDataCell cd, bool isValueDefaulted)
		{
			cd.Foreground = System.Windows.Media.Brushes.Blue;
			if (isValueDefaulted)
			{
				cd.FontStyle = FontStyles.Italic;
				cd.FontWeight = FontWeights.Normal;
			}
			else
			{
				cd.FontStyle = FontStyles.Normal;
				cd.FontWeight = FontWeights.Bold;
			}
