		{
			Field = field;
			base.Template = MMScrollAreaMSTemplateHelper.GetTemplateForField(field);
			base.EditTemplate = MMScrollAreaMSTemplateHelper.GetEditTemplateForField(field);
			base.Binding.Converter = CreateConverter();
			if (field is MMScrollAreaComboValueField { IsEditable: not false })
			{
				base.BindingMode = BindingMode.TwoWay;
			}
			if (!double.IsNaN(field.MinWidth) && field.MinWidth > 0.0 && field.MinWidth != double.PositiveInfinity)
			{
				base.MinWidth = field.MinWidth;
			}
			if (field.IsReadonlyField)
			{
				base.IsReadOnly = true;
			}
			base.Visibility = ((!field.IsVisible) ? Visibility.Collapsed : Visibility.Visible);
		}

		private IValueConverter CreateConverter()
		{
			if (Field is MMScrollAreaComboValueField { IsEditable: not false, Mask: AesMaskOption.Double })
