		protected override void OnItemsSourceChanged(IEnumerable oldValue, IEnumerable newValue)
		{
			if (oldValue is CxvVectorPropertyData cxvVectorPropertyData)
			{
				cxvVectorPropertyData.ItemPropertyChanging -= Vector_ItemPropertyChanging;
			}
			if (newValue is CxvVectorPropertyData cxvVectorPropertyData2)
			{
				cxvVectorPropertyData2.ItemPropertyChanging += Vector_ItemPropertyChanging;
			}
			base.OnItemsSourceChanged(oldValue, newValue);
