		private void Vector_ItemPropertyChanging(object sender, CxvVectorItemPropertyChangingEventArgs e)
		{
			IMMScrollAreaMSDataRetriever dataRetriever = _scrollArea.DataRetriever;
			if (dataRetriever != null && dataRetriever.TryUpdateCellData(_scrollArea, e))
			{
				e.Cancel = true;
				_scrollArea.PublishUpdateDisplayEvent();
			}
		}

		protected override void OnPreparingCellValues(PreparingCellValuesEventArgs e)
		{
			base.OnPreparingCellValues(e);
