		protected override IDataCell OnCellValueQueried(DataRow row, DataColumn column)
		{
			IDataCell dataCell = null;
			bool flag = false;
			_scrollArea.IsQueringCellValue = true;
			try
			{
				if (_scrollArea.DataRetriever != null)
				{
					dataCell = _scrollArea.DataRetriever.GetCellData(row, column);
				}
				flag = dataCell != null;
				if (!flag)
				{
					dataCell = base.OnCellValueQueried(row, column);
				}
			}
			finally
			{
				_scrollArea.IsQueringCellValue = false;
			}
			if (dataCell != null)
			{
				InitializeCellProperties(dataCell, row as BindingDataRow, column as MMScrollAreaMSDataColumn, flag);
			}
			return dataCell;
		}

		protected override void OnCellValueCleared(IDataCell cell)
		{
			object bindingVariable = GetBindingVariable(cell);
			if (bindingVariable is CxvVariableData cxvVariableData)
			{
				cxvVariableData.Value = null;
			}
			else if (bindingVariable is CxvParameterPropertyData cxvParameterPropertyData)
			{
				cxvParameterPropertyData.Value = null;
			}
		}

		protected override string FixCellDisplayText(IDataCell cell, string text)
		{
			if (_scrollArea.DisplayTextConverter != null)
			{
				(bool, string) tuple = _scrollArea.DisplayTextConverter(cell, text);
				if (tuple.Item1)
				{
					return tuple.Item2;
				}
			}
			if (cell.Column is MMScrollAreaMSDataColumn mMScrollAreaMSDataColumn && mMScrollAreaMSDataColumn.Field is MMScrollAreaMessageIconField)
			{
				return null;
			}
			if (_scrollArea.ShowValuesForGlobalUnitSet && GetBindingVariable(cell) is CxvVariableData { UnitRow: not 0 } cxvVariableData)
			{
				string text2 = CreateTextAtDisplayUnit(cell, cxvVariableData);
				if (text2 != null)
				{
					return text2;
				}
			}
			return base.FixCellDisplayText(cell, text);
		}

		internal static string CreateTextAtDisplayUnit(IDataCell cell, CxvVariableData variable)
		{
			object obj;
			if (variable == null)
			{
				obj = null;
			}
			else
			{
				ICxvViewDataContainer dataContainer = variable.DataContainer;
				if (dataContainer == null)
				{
					obj = null;
				}
				else
				{
					IUnityContainer unityContainer = dataContainer.UnityContainer;
					obj = ((unityContainer != null) ? CxvUnityContainerExtensions.TryResolve<IAdbUnitsProvider>(unityContainer) : null);
				}
			}
			IAdbUnitsProvider adbUnitsProvider = (IAdbUnitsProvider)obj;
			if (adbUnitsProvider != null && variable.Value is double valueFrom)
			{
				string units = variable.Units;
				string defaultDisplayUnits = adbUnitsProvider.GetDefaultDisplayUnits(variable.UnitRow);
				double? num = adbUnitsProvider.Convert(variable.UnitRow, valueFrom, units, defaultDisplayUnits);
				if (num.HasValue)
				{
					string text = (string.IsNullOrEmpty(cell.Mask) ? "g6" : cell.Mask);
					return string.Format("{0:" + text + "}", num);
				}
			}
			return null;
		}

		internal static System.Windows.Controls.Image GetIcon(string strImage)
		{
			System.Windows.Controls.Image image = new System.Windows.Controls.Image();
			string text = "pack://application:,,,/" + typeof(MMScrollAreaMSDataTable).Assembly.FullName + ";component/Images/";
			image.Source = new BitmapImage(new Uri(text + strImage));
			return image;
		}

