		private void InitializeCellProperties(IDataCell dc, BindingDataRow row, MMScrollAreaMSDataColumn column, bool useDataRetriever)
		{
			bool flag = true;
			if (column.Field is MMScrollAreaReadOnlyValueField)
			{
				return;
			}
			if (column.Field is MMScrollAreaReadOnlyColorValueField mMScrollAreaReadOnlyColorValueField)
			{
				if (mMScrollAreaReadOnlyColorValueField.ValueToColorConverter != null)
				{
					dc.SetBinding("Background", new Binding("Value")
					{
						RelativeSource = new RelativeSource(RelativeSourceMode.Self),
						Mode = BindingMode.OneWay,
						Converter = mMScrollAreaReadOnlyColorValueField.ValueToColorConverter
					});
				}
				return;
			}
			if (column.Field is MMScrollAreaMessageIconField)
			{
				dc.SetBinding("PrefixImage", new Binding(column.Field.PropertyPath + ".Value")
				{
					Source = row.DataItem,
					Mode = BindingMode.OneWay,
					Converter = MMScrollAreaMSMessageIconConverter.Default
				});
				dc.IsReadOnly = (column.Field as MMScrollAreaMessageIconField).IsReadOnly;
				return;
			}
			if (column.Field is MMScrollAreaImageField)
			{
				dc.IsReadOnly = true;
				dc.Value = null;
				return;
			}
			DataTemplate dataTemplate = dc.EditTemplate ?? column.EditTemplate;
			if (dataTemplate != null && dataTemplate.VisualTree != null && dataTemplate.VisualTree.Type == typeof(AesXamComboEdit))
			{
				dc.ShouldEnterEditModeWhenFocused = true;
			}
			else if (column.Field is MMScrollAreaSpinField)
			{
				dc.ShouldEnterEditModeWhenFocused = true;
			}
			else if (column.Field is MMScrollAreaEOBrowseField)
			{
				dc.ShouldEnterEditModeWhenFocused = true;
			}
			else if (column.Field is MMScrollAreaCustomTemplateField)
			{
				dc.ShouldEnterEditModeWhenFocused = true;
			}
			else if (column.Field is MMScrollAreaFortranLineField mMScrollAreaFortranLineField)
			{
				flag = mMScrollAreaFortranLineField.NeedItemsSource;
				dc.ShouldEnterEditModeWhenFocused = true;
			}
			if (useDataRetriever)
			{
				return;
			}
			dc.SetBinding("FontStyle", CreateStatusBinding(row.DataItem, column.Field, MMScrollAreaMSFontStyleConverter.Default));
			dc.SetBinding("FontWeight", CreateStatusBinding(row.DataItem, column.Field, MMScrollAreaMSFontWeightConverter.Default));
			dc.SetBinding("Foreground", CreateForegroundStatusBinding(row.DataItem, column.Field, MMScrollAreaMSForegroundConverter.Default));
			dc.SetBinding("Background", new Binding(column.Field.PropertyPath + ".IsEnabled")
			{
				Source = row.DataItem,
				Mode = BindingMode.OneWay,
				Converter = MMScrollAreaMSDisabledBackgroundConverter.Default,
				ConverterParameter = column.Field.DisabledBackground
			});
			if (column.Field is MMScrollAreaComboValueField mMScrollAreaComboValueField)
			{
				if (!string.IsNullOrEmpty(mMScrollAreaComboValueField.ValueOptionsPath))
				{
					dc.SetBinding("ItemsSource", new Binding(mMScrollAreaComboValueField.ValueOptionsPath)
					{
						Source = row.DataItem,
						Mode = BindingMode.OneWay
					});
					flag = false;
				}
				if (!string.IsNullOrWhiteSpace(mMScrollAreaComboValueField.ValuePath))
				{
					dc.SetBinding("Value", new Binding(mMScrollAreaComboValueField.ValuePath)
					{
						Source = row.DataItem,
						Mode = BindingMode.TwoWay
					});
				}
			}
			if (flag)
			{
				dc.SetBinding("ItemsSource", new Binding(column.Field.PropertyPath + ".ValueOptions")
				{
					Source = row.DataItem,
					Mode = BindingMode.OneWay
				});
			}
			if (dataTemplate != null && dataTemplate.VisualTree != null)
			{
				dc.SetBinding("IsReadOnly", new MultiBinding
				{
					Bindings = 
					{
						(BindingBase)new Binding("IsRunning")
						{
							Source = _scrollArea.SimulatorStatus
						},
						(BindingBase)new Binding(column.Field.PropertyPath + ".IsEnabled")
						{
							Source = row.DataItem
						},
						(BindingBase)new Binding(column.Field.PropertyPath + ".IsReadOnly")
						{
							Source = row.DataItem
						}
					},
					Converter = new MMScrollAreaMSIsReadOnlyConverter(),
					Mode = BindingMode.OneWay
				});
			}
			else if (column.Field is MMScrollAreaCheckBoxField)
			{
				dc.SetBinding("IsReadOnly", new MultiBinding
				{
					Bindings = 
					{
						(BindingBase)new Binding("IsRunning")
						{
							Source = _scrollArea.SimulatorStatus
						},
						(BindingBase)new Binding(column.Field.PropertyPath + ".IsEnabled")
						{
							Source = row.DataItem
						},
						(BindingBase)new Binding(column.Field.PropertyPath + ".IsReadOnly")
						{
							Source = row.DataItem
						}
					},
					Converter = new MMScrollAreaMSIsReadOnlyConverter(),
					Mode = BindingMode.OneWay
				});
			}
		}

