			frameworkElementFactory.SetBinding(System.Windows.Controls.Image.SourceProperty, new Binding("Row.DataItem." + imageField.ImageSourcePath)
			{
				Mode = BindingMode.OneWay
			});
			FrameworkElementFactory frameworkElementFactory2 = new FrameworkElementFactory(typeof(Border));
			frameworkElementFactory2.SetValue(FrameworkElement.MarginProperty, new Thickness(4.0, 2.0, 4.0, 2.0));
			frameworkElementFactory2.SetValue(FrameworkElement.WidthProperty, imageField.ImageWidth);
			frameworkElementFactory2.SetValue(FrameworkElement.HeightProperty, imageField.ImageHeight);
			frameworkElementFactory2.AppendChild(frameworkElementFactory);
			return new DataTemplate
			{
				VisualTree = frameworkElementFactory2
			};
		}

