				frameworkElementFactory.SetValue(AesXamValueEdit.ValueUpdateTriggerProperty, UpdateSourceTrigger.LostFocus);
				frameworkElementFactory.SetValue(AesXamValueEdit.VariableDataMemberProperty, field.VariableDataMemberResolved);
				frameworkElementFactory.SetValue(AesXamValueEdit.MaxLengthProperty, field.MaxLength);
				frameworkElementFactory.SetValue(AesXamValueEdit.DisplayedCaseProperty, field.DisplayedCase);
				frameworkElementFactory.SetValue(AesXamValueEdit.CharacterCasingProperty, field.CharacterCasing);
				frameworkElementFactory.SetValue(AesXamValueEdit.MaskProperty, field.Mask);
				frameworkElementFactory.SetValue(AesXamValueEdit.IsInScrollAreaProperty, true);
