				frameworkElementFactory2.SetValue(ValueEditor.IsInEditModeProperty, true);
				frameworkElementFactory2.SetValue(ValueEditor.IsAlwaysInEditModeProperty, true);
				if (inversion)
				{
					frameworkElementFactory2.SetValue(AesXamComboEdit.VariablePathProperty, "Column.DataItem." + field.PropertyPath);
