				}
				frameworkElementFactory2.SetValue(AesXamComboEdit.ValueUpdateTriggerProperty, UpdateSourceTrigger.LostFocus);
				frameworkElementFactory2.SetValue(AesXamComboEdit.VariableDataMemberProperty, field.VariableDataMemberResolved);
				frameworkElementFactory2.SetValue(AesXamComboEdit.IsInScrollAreaProperty, true);
				return new DataTemplate
				{
					VisualTree = frameworkElementFactory2
				};
			}
			return null;
		}

