		private void InitializeCellProperties(IDataCell dc, MSInversionDataRow row, TransposedDataColumn column, bool useDataRetriever)
		{
			MMScrollAreaField field = row.Field;
			object dataItem = column.DataItem;
			dc.SetBinding("Value", new Binding(field.PropertyPath + "." + field.VariableDataMemberResolved)
			{
				Source = dataItem,
				Mode = BindingMode.TwoWay
			});
			if (row.Field is MMScrollAreaReadOnlyValueField)
			{
				return;
			}
			if (row.Template != null)
			{
				dc.Template = row.Template;
			}
			DataTemplate dataTemplate = (dc.EditTemplate = row.EditTemplate);
			DataTemplate dataTemplate2 = dataTemplate;
			if (dataTemplate2 != null && dataTemplate2.VisualTree != null && dataTemplate2.VisualTree.Type == typeof(AesXamComboEdit))
			{
				dc.ShouldEnterEditModeWhenFocused = true;
			}
			else if (row.Field is MMScrollAreaSpinField || row.Field is MMScrollAreaCustomTemplateField)
			{
				dc.ShouldEnterEditModeWhenFocused = true;
			}
			if (!useDataRetriever)
			{
				dc.SetBinding("FontStyle", MMScrollAreaMSDataTable.CreateStatusBinding(dataItem, field, MMScrollAreaMSFontStyleConverter.Default));
				dc.SetBinding("FontWeight", MMScrollAreaMSDataTable.CreateStatusBinding(dataItem, field, MMScrollAreaMSFontWeightConverter.Default));
				dc.SetBinding("Foreground", MMScrollAreaMSDataTable.CreateForegroundStatusBinding(dataItem, field, MMScrollAreaMSForegroundConverter.Default));
