				{
					dc.SetBinding("IsReadOnly", new MultiBinding
					{
						Bindings = 
						{
							(BindingBase)new Binding("IsRunning")
							{
								Source = ScrollArea.SimulatorStatus
							},
							(BindingBase)new Binding(field.PropertyPath + ".IsEnabled")
							{
								Source = dataItem
							},
							(BindingBase)new Binding(field.PropertyPath + ".IsReadOnly")
							{
								Source = dataItem
							}
						},
						Converter = new MMScrollAreaMSIsReadOnlyConverter(),
						Mode = BindingMode.OneWay
					});
				}
				else if (field is MMScrollAreaCheckBoxField)
				{
					dc.SetBinding("IsReadOnly", new MultiBinding
					{
						Bindings = 
						{
							(BindingBase)new Binding("IsRunning")
							{
								Source = ScrollArea.SimulatorStatus
							},
							(BindingBase)new Binding(field.PropertyPath + ".IsEnabled")
							{
								Source = dataItem
							},
							(BindingBase)new Binding(field.PropertyPath + ".IsReadOnly")
							{
								Source = dataItem
							}
						},
						Converter = new MMScrollAreaMSIsReadOnlyConverter(),
						Mode = BindingMode.OneWay
					});
				}
			}
		}

