						{
							Source = dataItem
						},
						(BindingBase)new Binding(mSInversionDataRow.Field.PropertyPath + ".UpperLimit")
						{
							Source = dataItem
						},
						(BindingBase)new Binding(mSInversionDataRow.Field.PropertyPath + ".IsReadOnly")
						{
