		private static Type GetFieldValueType(MMScrollAreaField field)
		{
			if (field is MMScrollAreaValueField { Mask: var mask })
			{
				switch (mask)
				{
				case AesMaskOption.Integer:
					return DataRow.Int32Type;
				case AesMaskOption.Double:
					return DataRow.DoubleType;
				}
			}
			if (field is MMScrollAreaComboValueField { IsEditable: not false, Mask: var mask2 })
			{
				switch (mask2)
				{
				case AesMaskOption.Integer:
					return DataRow.Int32Type;
				case AesMaskOption.Double:
					return DataRow.DoubleType;
				}
			}
			if (field is MMScrollAreaCheckBoxField)
			{
				return DataRow.BooleanType;
			}
			return DataRow.StringType;
		}
	}
