				double num = Math.Max(0.0, availableSize.Height - SystemParameters.HorizontalScrollBarHeight);
				System.Windows.Size size2 = TryGetRequiredSize(pageContent, new System.Windows.Size(size.Width, num), border);
				if (RoughlyLess(size2.Height, num))
				{
					border.Height = num;
					sv.VerticalScrollBarVisibility = ScrollBarVisibility.Hidden;
				}
				else
				{
					border.Height = size2.Height;
					sv.VerticalScrollBarVisibility = ScrollBarVisibility.Visible;
				}
			}
			else if (RoughlyLess(size.Width, availableSize.Width) && ClearlyGreater(size.Height, availableSize.Height))
			{
				border.Height = size.Height;
				sv.VerticalScrollBarVisibility = ScrollBarVisibility.Visible;
				double num2 = Math.Max(0.0, availableSize.Width - SystemParameters.HorizontalScrollBarHeight);
				System.Windows.Size size3 = TryGetRequiredSize(pageContent, new System.Windows.Size(num2, size.Height), border);
				if (RoughlyLess(size3.Width, num2))
				{
					border.Width = num2;
					sv.HorizontalScrollBarVisibility = ScrollBarVisibility.Hidden;
				}
				else
				{
					border.Width = size3.Width;
					sv.HorizontalScrollBarVisibility = ScrollBarVisibility.Visible;
				}
			}
		}

		private static double GetZoomFactor(FrameworkElement element)
		{
			if (element.LayoutTransform is ScaleTransform scaleTransform)
			{
				return scaleTransform.ScaleX;
			}
			if (element.RenderTransform is ScaleTransform scaleTransform2)
			{
				return scaleTransform2.ScaleX;
			}
			return 1.0;
		}

		private static System.Windows.Size TryGetRequiredSize(FrameworkElement element, System.Windows.Size availableSize, FrameworkElement relativeTo)
		{
			element.Measure(availableSize);
			double width = Math.Max(availableSize.Width, element.DesiredSize.Width);
			double height = Math.Max(availableSize.Height, element.DesiredSize.Height);
			element.Arrange(new Rect(new System.Windows.Size(width, height)));
			System.Windows.Size requiredSize = element.RenderSize;
			GetActualRequiredSize(element, relativeTo, default(Thickness), ref requiredSize);
			return requiredSize;
		}

		private static void GetActualRequiredSize(FrameworkElement element, FrameworkElement relativeTo, Thickness accumulatedMargin, ref System.Windows.Size requiredSize)
		{
			if (element == null || element.Visibility != Visibility.Visible)
			{
				return;
			}
			Thickness thickness = ExtendRightBottom(accumulatedMargin, element.Margin);
			requiredSize = Union(requiredSize, Inflate(GetRightBottom(element, relativeTo), thickness));
			if (element is GroupBox groupBox)
			{
				GetActualRequiredSize(groupBox.Content as FrameworkElement, relativeTo, ExtendRightBottom(thickness, groupBox.Padding), ref requiredSize);
			}
			else if (element is MMGroupBox mMGroupBox)
			{
				GetActualRequiredSize(mMGroupBox.Content as FrameworkElement, relativeTo, ExtendRightBottom(thickness, mMGroupBox.Padding), ref requiredSize);
			}
			else if (element is Expander { IsExpanded: not false } expander)
			{
				GetActualRequiredSize(expander.Content as FrameworkElement, relativeTo, ExtendRightBottom(thickness, expander.Padding), ref requiredSize);
			}
			else if (element is ContentControl contentControl)
			{
				GetActualRequiredSize(contentControl.Content as FrameworkElement, relativeTo, ExtendRightBottom(thickness, contentControl.Padding), ref requiredSize);
			}
			else
			{
				if (!(element is Panel panel))
				{
					return;
				}
				foreach (FrameworkElement child in panel.Children)
				{
					GetActualRequiredSize(child, relativeTo, thickness, ref requiredSize);
				}
			}
		}

		private static System.Windows.Size Inflate(System.Windows.Size size, params Thickness[] thicknesses)
		{
			double num = size.Width;
			double num2 = size.Height;
			for (int i = 0; i < thicknesses.Length; i++)
			{
				Thickness thickness = thicknesses[i];
				num += thickness.Left + thickness.Right;
				num2 += thickness.Top + thickness.Bottom;
			}
			return new System.Windows.Size(num, num2);
		}

		private static Thickness ExtendRightBottom(Thickness input, Thickness addition)
		{
			return new Thickness(input.Left, input.Top, input.Right + addition.Right, input.Bottom + addition.Bottom);
		}

		private static System.Windows.Size GetRightBottom(FrameworkElement element, FrameworkElement relativeTo)
		{
			System.Windows.Point point = element.TranslatePoint(new System.Windows.Point(0.0, 0.0), relativeTo);
			return new System.Windows.Size(Math.Max(0.0, point.X + element.ActualWidth), Math.Max(0.0, point.Y + element.ActualHeight));
		}

		private static System.Windows.Size Union(System.Windows.Size x, System.Windows.Size y)
		{
			return new System.Windows.Size(Math.Max(x.Width, y.Width), Math.Max(x.Height, y.Height));
		}

		private static bool RoughlyLess(double x, double y)
		{
			return x - y <= 0.01;
		}

		private static bool ClearlyGreater(double x, double y)
		{
			return x - y > 0.01;
		}

		private static bool RoughlyEqual(double x, double y)
		{
			return Math.Abs(x - y) <= 0.01;
		}
	}
