	public static class SizingHelper
	{
		public static string createEDRFile(CxsCase _cxsCase, string basePath, ref string tName)
		{
			string result = "";
			if (string.IsNullOrEmpty(basePath) || _cxsCase == null)
			{
				return result;
			}
			int num = 0;
			string text = string.Empty;
			string text2 = basePath;
			text2 = text2.Substring(text2.IndexOf("Blocks.") + 7);
			while (true)
			{
				num = text2.IndexOf(".Data.Blocks");
				if (num == -1)
				{
					break;
				}
				text += text2.Substring(0, num);
				text2 = text2.Substring(num + 12);
			}
			text += text2.Trim();
			tName = _cxsCase.CaseWorkingDirectory;
			result = tName + "\\" + text + ".edr";
			int num2 = 0;
			while (File.Exists(result))
			{
				string[] obj = new string[6] { tName, "\\", text, "_", null, null };
				int num3 = ++num2;
				obj[4] = num3.ToString();
				obj[5] = ".edr";
				result = string.Concat(obj);
			}
			tName = tName + "\\" + _cxsCase.CaseFileName + "!" + text;
			return result;
		}

		public static void passSpecToEDR(object ATVobj, CxvViewModel viewModel, string modelTypeinAP)
		{
			if (ATVobj == null || viewModel == null)
			{
				return;
			}
			object pScalars = null;
			try
			{
				if (modelTypeinAP == "KETTLE" || modelTypeinAP == "THERMOSIPHON")
				{
					setATVar(ATVobj, ref pScalars, "ApplTypeCS", "3");
					setATVar(ATVobj, ref pScalars, "VaporizerType", (modelTypeinAP == "KETTLE") ? "1" : "2");
					if (modelTypeinAP == "KETTLE")
					{
						setATVar(ATVobj, ref pScalars, "ShlType", "6");
						setATVar(ATVobj, ref pScalars, "LocFluidHS", "2");
					}
					if (modelTypeinAP == "THERMOSIPHON")
					{
						setATVar(ATVobj, ref pScalars, "ShlType", "1");
						double? num = CxsConverter.ValueToDouble(viewModel.ExpandDataPathAndGet("@main.Output.COLDINP", "value", "N/sqm"));
						if (num.HasValue)
						{
							setATVar(ATVobj, ref pScalars, "PresOperAtLiqSurfCS", num.ToString());
						}
					}
				}
				if (modelTypeinAP == "TASCPLUS-RIG" || modelTypeinAP == "THERMOSIPHON")
				{
					string text = CxsConverter.ValueToString(viewModel.ExpandDataPathAndGet("@main.Input.HSHELL_TUBE", "value"));
					if (!string.IsNullOrEmpty(text))
					{
						setATVar(ATVobj, ref pScalars, "LocFluidHS", (text == "SHELL") ? "1" : "2");
					}
				}
			}
			catch (Exception ex)
			{
				if (pScalars != null)
				{
					pScalars = null;
				}
				throw ex;
			}
			if (pScalars != null)
			{
				pScalars = null;
			}
		}

		public static void setATVar(object objATV, ref object pScalars, string variable, string val)
		{
			if ((pScalars == null && objATV == null) || string.IsNullOrEmpty(variable))
			{
				return;
			}
			dynamic val2 = null;
			object obj = null;
			try
			{
				if (pScalars == null)
				{
					pScalars = objATV.GetType().InvokeMember("get_Scalars", BindingFlags.InvokeMethod, null, objATV, new object[0]);
				}
				if (pScalars == null)
				{
					return;
				}
				val2 = pScalars.GetType().InvokeMember("get_Item", BindingFlags.InvokeMethod, null, pScalars, new object[1] { variable });
				if ((object)val2 == null)
				{
					return;
				}
				Type type = val2.Source.GetType();
				object obj2 = null;
				obj = ((object)val2).GetType().InvokeMember("szValuePureSI", BindingFlags.GetProperty, null, (object)val2, new object[0]);
				if (val == null)
				{
					obj2 = Enum.Parse(type, "adsDefault");
					val = obj2.ToString();
					if (obj == null || obj.ToString() != val)
					{
						type.InvokeMember("set_Source", BindingFlags.InvokeMethod, null, (object)val2, new object[1] { obj2 });
					}
				}
				else
				{
					obj2 = Enum.Parse(type, "adsUser");
					if (obj == null || obj.ToString() != val)
					{
						((object)val2).GetType().InvokeMember("szValuePureSI", BindingFlags.SetProperty, null, (object)val2, new object[1] { val });
						((object)val2).GetType().InvokeMember("set_Source", BindingFlags.InvokeMethod, null, (object)val2, new object[1] { obj2 });
					}
				}
			}
			catch (Exception ex)
			{
				if ((object)val2 != null)
				{
					val2 = null;
				}
				if (obj != null)
				{
					obj = null;
				}
				throw ex;
			}
			if ((object)val2 != null)
			{
				val2 = null;
			}
			if (obj != null)
			{
				obj = null;
			}
		}

		public static string getATVar(object objATV, ref object pScalars, string variable)
		{
			string text = null;
			if (pScalars == null && objATV == null)
			{
				return text;
			}
			if (string.IsNullOrEmpty(variable))
			{
				return text;
			}
			object obj = null;
			try
			{
				if (pScalars == null)
				{
					pScalars = objATV.GetType().InvokeMember("get_Scalars", BindingFlags.InvokeMethod, null, objATV, new object[0]);
				}
				if (pScalars == null)
				{
					return text;
				}
				obj = pScalars.GetType().InvokeMember("get_Item", BindingFlags.InvokeMethod, null, pScalars, new object[1] { variable });
				if (obj != null)
				{
					text = obj.GetType().InvokeMember("szValuePureSI", BindingFlags.GetProperty, null, obj, new object[0]).ToString();
				}
				obj = null;
			}
			catch (Exception ex)
			{
				if (obj != null)
				{
					obj = null;
				}
				throw ex;
			}
			return text?.Trim();
		}
	}
