					(BindingBase)new Binding("OptionGroup.PromptsDictionary")
					{
						Source = this
					},
					(BindingBase)new Binding("CheckedValue.DisplayLocalized")
					{
						Source = this
					},
					(BindingBase)new Binding("CheckedValue")
					{
						Source = this
					}
				},
				Converter = new MMOptionButtonPromptConvter(),
				Mode = BindingMode.OneWay,
				FallbackValue = null
			};
			SetBinding(PromptProperty, _promptBinding);
			_tabNavigationBinding = new Binding
			{
				Path = new PropertyPath("IsChecked"),
				Converter = new IsCheckedToKeyboardNavigationModeConverter(),
				Mode = BindingMode.OneWay,
				Source = this
			};
			SetBinding(KeyboardNavigation.TabNavigationProperty, _tabNavigationBinding);
			base.Loaded += MMOptionButton_Loaded;
		}

		private void MMOptionButton_Loaded(object sender, RoutedEventArgs e)
		{
			if (OptionGroup == null)
			{
				SetBinding(OptionGroupProperty, _parentGroupBinding);
			}
		}

		protected override void OnPreviewMouseLeftButtonUp(MouseButtonEventArgs e)
		{
			RaisePromptDisplayed();
			base.OnPreviewMouseLeftButtonUp(e);
		}

		protected override void OnPreviewGotKeyboardFocus(KeyboardFocusChangedEventArgs e)
		{
			RaisePromptDisplayed();
			base.OnPreviewGotKeyboardFocus(e);
		}

		protected override void OnPreviewKeyDown(KeyEventArgs e)
		{
			if (OptionGroup != null)
			{
				bool flag = e.Key == Key.Up || e.Key == Key.Left;
				bool flag2 = e.Key == Key.Down || e.Key == Key.Right;
				if (flag || flag2)
				{
					int count = OptionGroup.OptionButtons.Count;
					int num = OptionGroup.OptionButtons.IndexOf(this);
					if (num >= 0)
					{
						if (flag)
						{
							num--;
							if (num < 0)
							{
								num = count - 1;
							}
						}
						else if (flag2)
						{
							num++;
							if (num == count)
							{
								num = 0;
							}
						}
						if (num < count)
						{
							MMOptionButton mMOptionButton = OptionGroup.OptionButtons[num];
							mMOptionButton.IsChecked = true;
							if (mMOptionButton.Template.FindName("PART_RadioButton", mMOptionButton) is RadioButton element)
							{
								Keyboard.Focus(element);
							}
							e.Handled = true;
						}
					}
				}
			}
			base.OnPreviewKeyDown(e);
		}

		protected override void OnChecked(RoutedEventArgs e)
		{
			base.OnChecked(e);
			RefreshOptionValue();
		}

		private static void OnOptionGroupPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs args)
		{
			if (d is MMOptionButton mMOptionButton)
			{
				mMOptionButton.OnOptionGroupChanged(args.OldValue as MMOptionGroup, args.NewValue as MMOptionGroup);
			}
		}

		private void OnOptionGroupChanged(MMOptionGroup oldGroup, MMOptionGroup newGroup)
		{
			if (oldGroup != null)
			{
				oldGroup.OptionValueChanged -= Group_OptionValueChanged;
			}
			if (newGroup != null)
			{
				newGroup.OptionValueChanged += Group_OptionValueChanged;
			}
			RefreshCheckedState();
		}

		private void Group_OptionValueChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
		{
			RefreshCheckedState();
		}

		private static void CheckedValuePropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs args)
		{
			(d as MMOptionButton).RefreshOptionValue();
		}

		protected override bool ShouldSerializeProperty(DependencyProperty dp)
		{
			if (dp == OptionGroupProperty && BindingOperations.GetBinding(this, dp) == _parentGroupBinding)
			{
				return false;
			}
			if (dp == PromptProperty && BindingOperations.GetMultiBinding(this, dp) == _promptBinding)
			{
				return false;
			}
			if (dp == KeyboardNavigation.TabNavigationProperty && BindingOperations.GetBinding(this, dp) == _tabNavigationBinding)
			{
				return false;
			}
			return base.ShouldSerializeProperty(dp);
		}

		private void RaisePromptDisplayed()
		{
			if (!string.IsNullOrEmpty(Prompt))
			{
				OnPromptDisplayed(Prompt);
			}
			else
			{
				if (OptionGroup == null || base.Content == null)
				{
					return;
				}
				string text = null;
				if (base.Content != null)
				{
					text = ((base.Content.GetType() == typeof(string)) ? base.Content.ToString() : ((!(base.Content.GetType() == typeof(TextBlock))) ? base.Content.ToString() : (base.Content as TextBlock).Text));
				}
				if (!string.IsNullOrEmpty(text))
				{
					if (OptionGroup.PromptsDictionary != null && OptionGroup.PromptsDictionary.ContainsKey(text) && !string.IsNullOrEmpty(OptionGroup.PromptsDictionary[text]))
					{
						OnPromptDisplayed(OptionGroup.PromptsDictionary[text]);
					}
					else
					{
						OnPromptDisplayed(OptionGroup.Prompt);
					}
				}
			}
		}

		private void RefreshOptionValue()
		{
			if (base.IsChecked.HasValue && base.IsChecked.Value && OptionGroup != null)
			{
				OptionGroup.UpdateOptionValue(CheckedValue);
			}
		}

		private void RefreshCheckedState()
		{
			if (OptionGroup.OptionValue is CxvMultiMapPropertyData cxvMultiMapPropertyData)
			{
				base.IsChecked = OptionGroup != null && CxvHelpers.ValuesEquivalent(CheckedValue, cxvMultiMapPropertyData.Value);
			}
			else
			{
				base.IsChecked = OptionGroup != null && CxvHelpers.ValuesEquivalent(CheckedValue, OptionGroup.OptionValue);
			}
		}

		protected virtual void OnPromptDisplayed(string prompt)
		{
			RoutedEventArgs<string> e = new RoutedEventArgs<string>(prompt, AesControlBase.PromptDisplayedEvent, this);
			RaiseEvent(e);
		}
	}
	internal class MMOptionButtonPromptConvter : IMultiValueConverter
	{
		public object Convert(object[] values, Type targetType, object parameter, CultureInfo culture)
		{
			if (values == null || values.Length < 5)
			{
				return null;
			}
			if (values[0] == null || values[0] == DependencyProperty.UnsetValue)
			{
				return null;
			}
			if (values[2] != null && values[2] != DependencyProperty.UnsetValue)
			{
				string text = null;
				string text2 = null;
				text = ((values[0].GetType() == typeof(string)) ? values[0].ToString() : ((!(values[0].GetType() == typeof(TextBlock))) ? values[0].ToString() : (values[0] as TextBlock).Text));
				text2 = ((values[4] != null) ? values[4].ToString() : null);
				if (values[2] is Dictionary<string, string> dictionary)
				{
					string value = null;
					bool flag = !string.IsNullOrEmpty(text) && dictionary.TryGetValue(text, out value) && !string.IsNullOrEmpty(value);
					if (!flag)
					{
						flag = !string.IsNullOrEmpty(text2) && dictionary.TryGetValue(text2, out value) && !string.IsNullOrEmpty(value);
					}
					if (flag)
					{
						return value;
					}
				}
			}
			if (values[1] != null && values[1] != DependencyProperty.UnsetValue)
			{
				return values[1].ToString();
			}
			return null;
		}

		public object[] ConvertBack(object value, Type[] targetTypes, object parameter, CultureInfo culture)
		{
			throw new NotImplementedException();
		}
	}
	internal class IsCheckedToKeyboardNavigationModeConverter : IValueConverter
	{
		public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
		{
			if ((bool)value)
			{
				return KeyboardNavigationMode.Continue;
			}
			return KeyboardNavigationMode.None;
		}

		public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
		{
			throw new NotImplementedException();
		}
	}
	public class MMOptionGroup : AesOptionGroup
	{
		private List<MMOptionButton> _optionButtons;

		[DesignerSerializationVisibility(DesignerSerializationVisibility.Hidden)]
		public List<MMOptionButton> OptionButtons
		{
			get
			{
				if (_optionButtons == null)
				{
					IEnumerable<MMOptionButton> visualChildren = GetVisualChildren(this);
					if (visualChildren != null)
					{
						_optionButtons = visualChildren.ToList();
					}
				}
				return _optionButtons;
			}
		}

		static MMOptionGroup()
		{
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(MMOptionGroup), new FrameworkPropertyMetadata(typeof(MMOptionGroup)));
		}

		private static IEnumerable<MMOptionButton> GetVisualChildren(DependencyObject parent)
		{
			if (parent == null)
			{
				return null;
			}
			List<MMOptionButton> list = new List<MMOptionButton>();
			int childrenCount = VisualTreeHelper.GetChildrenCount(parent);
			for (int i = 0; i < childrenCount; i++)
			{
				DependencyObject child = VisualTreeHelper.GetChild(parent, i);
				if (child is MMOptionButton item)
				{
					list.Add(item);
					continue;
				}
				DependencyObject dependencyObject = child;
				if (dependencyObject != null && child.GetType() != typeof(MMOptionGroup))
				{
					list.AddRange(GetVisualChildren(dependencyObject));
				}
			}
			return list.OrderBy((MMOptionButton p) => p.Name);
		}
	}
