		public override bool OnClosing()
		{
			IEnumerable<MMTabPage> desendantTabPages = GetDesendantTabPages();
			if (desendantTabPages != null)
			{
				for (int i = 0; i < desendantTabPages.Count(); i++)
				{
					MMTabPage mMTabPage = desendantTabPages.ElementAtOrDefault(i);
					if (mMTabPage != null && !mMTabPage.OnClosing())
					{
						return false;
					}
				}
			}
			return base.OnClosing();
		}

