		public bool ActivatePage(MMTabPage page)
		{
			if (page == null)
			{
				throw new ArgumentNullException("page");
			}
			if (base.Content != null)
			{
				if (base.Content is MMTabStrip)
				{
					foreach (MMTabItem item in (base.Content as MMTabStrip).Items)
					{
						if (item.Content as MMTabPage == page)
						{
							item.IsSelected = true;
							return true;
						}
					}
				}
				else if (base.Content is MMTabPage)
				{
					return base.Content as MMTabPage == page;
				}
			}
			return false;
		}

