		public bool SetSelectedTab(string tabName)
		{
			if (base.Content is MMTabStrip mMTabStrip)
			{
				foreach (MMTabItem item in mMTabStrip.Items)
				{
					if (item.Header != null && item.Header.ToString() == tabName)
					{
						mMTabStrip.ActiveTab = item;
						return true;
					}
				}
			}
			else if (base.Content is Grid grid)
			{
				foreach (UIElement child in grid.Children)
				{
					if (!(child is MMTabStrip mMTabStrip2))
					{
						continue;
					}
					foreach (MMTabItem item2 in mMTabStrip2.Items)
					{
						if (item2.Header != null && item2.Header.ToString() == tabName)
						{
							mMTabStrip2.ActiveTab = item2;
							return true;
						}
					}
				}
			}
			return false;
		}

		public override void OnRequestingClosingEvent(RequestingClosingEventArgs args)
		{
			foreach (MMTabPage desendantTabPage in GetDesendantTabPages())
			{
				desendantTabPage.OnRequestingClosingEvent(args);
				if (args.StopClosing)
				{
					break;
				}
			}
			base.OnRequestingClosingEvent(args);
		}
	}
