		private void OnContentProgIdChanged(string oldType, string newType)
		{
			if (!string.IsNullOrEmpty(ContentProgId))
			{
				FrameworkElementFactory frameworkElementFactory = new FrameworkElementFactory(typeof(Border), "PART_OutBorder");
				frameworkElementFactory.SetValue(Border.BorderBrushProperty, new TemplateBindingExtension(Control.BorderBrushProperty));
				frameworkElementFactory.SetValue(Border.BorderThicknessProperty, new TemplateBindingExtension(Control.BorderThicknessProperty));
				frameworkElementFactory.SetValue(Border.BackgroundProperty, new TemplateBindingExtension(Control.BackgroundProperty));
				frameworkElementFactory.AppendChild(new FrameworkElementFactory(typeof(ContentPresenter)));
				base.Template = new ControlTemplate(typeof(MMTabPage))
				{
					VisualTree = frameworkElementFactory
				};
			}
			if (oldType != newType)
			{
				UpdateContent();
			}
		}

