			SetBinding(DataForClipboard.CaseFullFilePathProperty, _clipboardCaseFullFilePathBinding);
			SetBinding(DataForClipboard.ApplicationNameProperty, _clipboardApplicationNameBinding);
			AddHandler(MMNextButton.NextEvent, new RoutedEventHandler(MMNextButton_Next));
			AddHandler(AesControlBase.PromptDisplayedEvent, new EventHandler<RoutedEventArgs<string>>(InnerControl_PromptDisplayedEvent));
			AddHandler(AesXamComboEdit.F4KeyDownEvent, new EventHandler(Combo_F4KeyDownEvent));
			base.Loaded += MMTabPage_Loaded;
			base.Unloaded += MMTabPage_Unloaded;
			AddHandler(AesVariableControlBase.ScriptingDisplayVariablePathEvent, new EventHandler<RoutedEventArgs<string>>(InnerControl_ScriptingDisplayVariablePathEvent));
			LayoutSettingControls = new ObservableCollection<IScrollAreaSettings>();
			LayoutSettingControls.CollectionChanged += ChildScrollAreas_CollectionChanged;
			CommandManager.AddPreviewExecutedHandler(this, PreviewExecute);
		}

		private void PreviewExecute(object sender, ExecutedRoutedEventArgs e)
		{
			if ((e.Command == MMScrollAreaCommand.PasteCommand || e.Command == ApplicationCommands.Paste) && !ScrollAreaDropHelper.IsDropping)
			{
				string asiFormatTextFromClipboard = ClipboardHelper.GetAsiFormatTextFromClipboard();
				if (!string.IsNullOrEmpty(asiFormatTextFromClipboard) && base.ViewModel != null && base.ViewModel.ResolvedCxsProvider != null && base.ViewModel.ResolvedCxsProvider.Case != null)
				{
					IList<string> paths = ClipboardHelper.ParseCxsPathFromAsiFormat(asiFormatTextFromClipboard, base.ViewModel.ResolvedCxsProvider.Case.CaseFullFilePath);
					OnPreviewVariableDataPaste(paths, e);
				}
			}
		}

		protected override void OnDragEnter(DragEventArgs e)
		{
			Window.GetWindow(this)?.Activate();
			base.OnDragEnter(e);
		}

		protected override void OnPreviewDrop(DragEventArgs e)
		{
			if (Infragistics.Windows.Utilities.GetAncestorFromType(e.OriginalSource as DependencyObject, typeof(MMScrollAreaBase), allowSubclassOfType: true) is MMScrollAreaBase mMScrollAreaBase && !mMScrollAreaBase.CanDrop(e.OriginalSource as DependencyObject))
			{
				base.OnPreviewDrop(e);
				return;
			}
			if (e.Data != null)
			{
				string text = string.Empty;
				object data = e.Data.GetData("ASI Format");
				if (data is string)
				{
					text = (string)data;
				}
				else if (data is MemoryStream)
				{
					text = Encoding.UTF8.GetString(((MemoryStream)data).ToArray());
				}
				if (!string.IsNullOrEmpty(text) && base.ViewModel != null && base.ViewModel.ResolvedCxsProvider != null && base.ViewModel.ResolvedCxsProvider.Case != null)
				{
					IList<string> paths = ClipboardHelper.ParseCxsPathFromAsiFormat(text, base.ViewModel.ResolvedCxsProvider.Case.CaseFilePath);
					OnPreviewVariableDataDrop(paths, e);
				}
			}
			base.OnPreviewDrop(e);
		}

