		private void MMTabPage_Loaded(object sender, RoutedEventArgs e)
		{
			if (!DesignerProperties.GetIsInDesignMode(this) && (base.MinWidth > 0.0 || base.MinHeight > 0.0))
			{
				ClearValue(FrameworkElement.MinWidthProperty);
				ClearValue(FrameworkElement.MinHeightProperty);
			}
			if (base.IsEnabled && ((base.Tag as bool?) ?? true))
			{
				base.Dispatcher.BeginInvoke(new Action(InternalDoFocusFirstControl), DispatcherPriority.Loaded);
			}
			if (base.UnityContainer != null)
			{
				base.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<RefreshPlotWizardRibbonEvent>().Publish(new RefreshPlotWizardRibbonEventArgs());
				GetDocumentActiveModeEventArgs e2 = new GetDocumentActiveModeEventArgs();
				base.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<GetDocumentActiveModeEvent>().Publish(e2);
				if (e2.ActiveMode as string == "PSVPlus" && e2.NavigationGroupToSelect == "PSVPlus")
				{
					DisableControls(this);
				}
			}
			InvalidateInContextGuidanceButtonLayout();
		}

		public void InvalidateInContextGuidanceButtonLayout()
		{
			MMInContextGuidanceButton.InvalidateInjectionPosition(this);
		}

		private void DisableControls(DependencyObject parent)
		{
			if (parent == null)
			{
				return;
			}
			for (int i = 0; i < VisualTreeHelper.GetChildrenCount(parent); i++)
			{
				DependencyObject child = VisualTreeHelper.GetChild(parent, i);
				bool flag = true;
				if (child is TextBox textBox)
				{
					textBox.IsEnabled = false;
					textBox.Foreground = System.Windows.Media.Brushes.DarkGray;
				}
				if (child is ComboBox comboBox)
				{
					comboBox.IsEnabled = false;
				}
				if (child is ListBox listBox)
				{
					listBox.IsEnabled = false;
				}
				if (child is Button button)
				{
					button.IsEnabled = false;
				}
				if (child is RadioButton radioButton)
				{
					radioButton.IsEnabled = false;
				}
				if (child is XamDataGrid xamDataGrid)
				{
					xamDataGrid.IsEnabled = false;
				}
				GridControlDataGrid gcdg = child as GridControlDataGrid;
				MMTabItem mMTabItem = ((base.Parent == null) ? null : (base.Parent as MMTabItem));
				bool flag2 = mMTabItem != null && mMTabItem.Header != null && mMTabItem.Header.ToString().Equals(AspenTech.AspenPlus.MMControls.Properties.Resources.MMTabPage_Header_Material, StringComparison.OrdinalIgnoreCase);
				if (gcdg != null && flag2)
				{
					flag = false;
				}
				if (gcdg != null && !flag2)
				{
					gcdg.IsEnabled = false;
					base.Dispatcher.BeginInvoke((Action)delegate
					{
						if (gcdg.Items != null)
						{
							foreach (DataRow item in (IEnumerable)gcdg.Items)
							{
								for (int j = 0; j < item.AvailableColumnsCount; j++)
								{
									if (item[j] != null)
									{
										item[j].Foreground = System.Windows.Media.Brushes.DarkGray;
										item[j].FontWeight = FontWeights.Normal;
									}
								}
							}
						}
					}, DispatcherPriority.Loaded);
				}
				if (child is MMAdvancedComboEdit mMAdvancedComboEdit)
				{
					mMAdvancedComboEdit.IsEnabled = false;
					mMAdvancedComboEdit.IsReadOnly = true;
				}
				if (child is AesXamComboEdit aesXamComboEdit)
				{
					aesXamComboEdit.IsEnabled = false;
					aesXamComboEdit.IsReadOnly = true;
				}
				if (child is AesXamCheckEdit aesXamCheckEdit)
				{
					aesXamCheckEdit.IsEnabled = false;
				}
				if (child is AesXamValueEdit aesXamValueEdit)
				{
					aesXamValueEdit.IsEnabled = false;
					aesXamValueEdit.IsReadOnly = true;
				}
				if (child is AesXamMaskedEdit aesXamMaskedEdit)
				{
					aesXamMaskedEdit.IsEnabled = false;
					aesXamMaskedEdit.IsReadOnly = true;
				}
				if (child is MMBasisEdit mMBasisEdit)
				{
					mMBasisEdit.IsEnabled = false;
					mMBasisEdit.IsReadOnly = true;
				}
				if (child is MMListPicker mMListPicker)
				{
					mMListPicker.IsEnabled = false;
				}
				if (child is MMTextEdit mMTextEdit)
				{
					mMTextEdit.IsEnabled = false;
					mMTextEdit.IsReadOnly = true;
				}
				if (child is MMRichTextBox mMRichTextBox)
				{
					mMRichTextBox.IsEnabled = false;
					mMRichTextBox.IsReadOnly = true;
				}
				if (child is MMCheckBox mMCheckBox)
				{
					mMCheckBox.IsEnabled = false;
				}
				if (child is MMValueEdit mMValueEdit)
				{
					mMValueEdit.IsEnabled = false;
					mMValueEdit.IsReadOnly = true;
				}
				if (child is MMVariableEdit mMVariableEdit)
				{
					mMVariableEdit.IsEnabled = false;
					mMVariableEdit.IsReadOnly = true;
				}
				if (child is MMSpinBox mMSpinBox)
				{
					mMSpinBox.IsEnabled = false;
				}
				if (child is MMComboBox mMComboBox)
				{
					mMComboBox.IsEnabled = false;
					mMComboBox.IsReadOnly = true;
				}
				if (child is MMComboEdit mMComboEdit)
				{
					mMComboEdit.IsEnabled = false;
					mMComboEdit.IsReadOnly = true;
				}
				if (child is MMComboButton mMComboButton)
				{
					mMComboButton.IsEnabled = false;
					mMComboButton.IsReadOnly = true;
				}
				if (child is MMGroupBox mMGroupBox)
				{
					mMGroupBox.IsEnabled = false;
					mMGroupBox.Foreground = System.Windows.Media.Brushes.DarkGray;
				}
				if (child is MMFortran mMFortran)
				{
					mMFortran.IsEnabled = false;
					mMFortran.IsReadOnly = true;
				}
				if (child is MMExpander mMExpander)
				{
					mMExpander.IsEnabled = false;
				}
				if (flag)
				{
					DisableControls(child);
				}
			}
		}

		private void InternalDoFocusFirstControl()
		{
			if (IsParentScreenActiveResolved)
			{
				DoFocusFirstControl();
			}
		}

		protected virtual void DoFocusFirstControl()
		{
			if (!IsParentScreenActiveResolved)
			{
				return;
			}
			if (base.IsKeyboardFocusWithin)
			{
				IInputElement focusedElement = Keyboard.FocusedElement;
				if (focusedElement != null && focusedElement.IsEnabled)
				{
					return;
				}
			}
			MMNavigationHelper.SetIsTabbing(this, 3);
			TraversalRequest request = new TraversalRequest(FocusNavigationDirection.Next);
			MoveFocus(request);
			MMNavigationHelper.SetIsTabbing(this, 0);
		}

		protected override void OnUnityContainerChanged(IUnityContainer oldContainer, IUnityContainer newContainer)
		{
			UpdateContent();
			base.OnUnityContainerChanged(oldContainer, newContainer);
		}

		private void UpdateContent()
		{
			if (base.UnityContainer == null || string.IsNullOrEmpty(ContentProgId))
			{
				return;
			}
			Type type = base.UnityContainer.Resolve<MMFormsCatalog>(Array.Empty<ResolverOverride>()).LookupControlType(ContentProgId);
			if (type != null)
			{
				base.Content = base.UnityContainer.Resolve(type);
				if (base.Content is MMTabPage target && BindingOperations.GetBinding(target, MMTabItem.IsOuterTabItemAccessibleProperty) == null)
				{
					BindingOperations.SetBinding(target, MMTabItem.IsOuterTabItemAccessibleProperty, new Binding
					{
						Source = this,
						Path = new PropertyPath(MMTabItem.IsOuterTabItemAccessibleProperty),
						Mode = BindingMode.OneWay
					});
				}
			}
		}

		protected void ShowSubPage(MMTabPage subPage, string title, bool showAsDialog)
		{
			if (subPage == null)
			{
				throw new ArgumentNullException("subPage");
			}
			Window window = new Window
			{
				Content = new Border
				{
					Margin = new Thickness(5.0),
					Child = subPage
				},
				Title = title,
				SizeToContent = SizeToContent.WidthAndHeight,
				ShowInTaskbar = false,
				ResizeMode = ResizeMode.NoResize,
				WindowStartupLocation = WindowStartupLocation.CenterOwner
			};
			ShowWindow(window, showAsDialog);
		}

		protected void ShowWindow(Window window, bool showAsDialog)
		{
			if (window == null)
			{
				throw new ArgumentNullException("window");
			}
			Window window2 = Window.GetWindow(this);
			if (window2 != null)
			{
				window.Owner = window2;
				if (showAsDialog)
				{
					window.ShowDialog();
				}
				else
				{
					window.Show();
				}
			}
			else
			{
				NativeMethods.ShowWindow(window, showAsDialog);
			}
		}

