		protected override void OnPreviewKeyDown(KeyEventArgs e)
		{
			if (e.Key == Key.Tab)
			{
				if ((Keyboard.Modifiers & ModifierKeys.Shift) == ModifierKeys.Shift)
				{
					MMNavigationHelper.SetIsTabbing(this, 2);
				}
				else
				{
					MMNavigationHelper.SetIsTabbing(this, 1);
				}
			}
			else if (e.Key == Key.V && Keyboard.Modifiers == ModifierKeys.Control)
			{
				if (ScrollAreaDropHelper.IsDropping)
				{
					return;
				}
				string asiFormatTextFromClipboard = ClipboardHelper.GetAsiFormatTextFromClipboard();
				if (!string.IsNullOrEmpty(asiFormatTextFromClipboard) && base.ViewModel != null && base.ViewModel.ResolvedCxsProvider != null && base.ViewModel.ResolvedCxsProvider.Case != null)
				{
					IList<string> paths = ClipboardHelper.ParseCxsPathFromAsiFormat(asiFormatTextFromClipboard, base.ViewModel.ResolvedCxsProvider.Case.CaseFullFilePath);
					OnPreviewVariableDataPaste(paths, e);
				}
			}
			base.OnPreviewKeyDown(e);
		}

		protected override void OnPreviewKeyUp(KeyEventArgs e)
		{
			MMNavigationHelper.SetIsTabbing(this, 0);
			base.OnKeyUp(e);
		}

		void IShellZoomable.Zoom(double factor)
		{
			if (!((IShellZoomable)this).SupportsZoom)
			{
				return;
			}
			FrameworkElement frameworkElement = FindZoomTarget();
			if (frameworkElement != null)
			{
				if (frameworkElement is IShellZoomable)
				{
					((IShellZoomable)frameworkElement).Zoom(factor);
				}
				else
				{
					ApplyZoomFactorToElement(frameworkElement, factor);
				}
			}
			else if (base.Content is IShellZoomable shellZoomable)
			{
				shellZoomable.Zoom(factor);
			}
			else
			{
				ApplyZoomFactor(factor);
			}
		}

		private FrameworkElement FindZoomTarget()
		{
			if (!string.IsNullOrEmpty(ZoomElementName))
			{
				if (!ZoomElementName.Contains(','))
				{
					return FindName(ZoomElementName) as FrameworkElement;
				}
				string[] array = ZoomElementName.Split(',');
				foreach (string text in array)
				{
					if (!string.IsNullOrEmpty(text) && FindName(text.Trim()) is FrameworkElement { Visibility: Visibility.Visible } frameworkElement)
					{
						return frameworkElement;
					}
				}
			}
			return null;
		}

		protected virtual void ApplyZoomFactor(double zoomFactor)
		{
			if (_templatedBorder != null)
			{
				ApplyZoomFactorToElement(_templatedBorder, zoomFactor);
				if (_templatedScrollViewer != null)
				{
					UpdateChildInnerBorder();
				}
			}
			else if (base.Content is FrameworkElement element)
			{
				ApplyZoomFactorToElement(element, zoomFactor);
			}
		}

		private static void ApplyZoomFactorToElement(FrameworkElement element, double factor)
		{
			if (factor <= 0.0 || factor == 1.0)
			{
				element.LayoutTransform = Transform.Identity;
				element.RenderTransform = Transform.Identity;
			}
			else
			{
				element.LayoutTransform = new ScaleTransform(factor, factor);
				element.RenderTransform = Transform.Identity;
			}
		}

		public override void OnApplyTemplate()
		{
			_templatedScrollViewer = GetTemplateChild("PART_ScrollViewer") as ScrollViewer;
			if (_templatedScrollViewer != null)
			{
				_templatedScrollViewer.SizeChanged += scrollViewer_SizeChanged;
			}
			_templatedBorder = GetTemplateChild("PART_ContentBorder") as ScrollViewerInnerBorder;
			base.OnApplyTemplate();
