		private void scrollViewer_SizeChanged(object sender, SizeChangedEventArgs e)
		{
			if (e.PreviousSize != e.NewSize)
			{
				UpdateChildInnerBorder();
			}
		}

		protected void UpdateChildInnerBorder()
		{
			if (_templatedBorder != null && ShouldRemeasureChild())
			{
				_templatedBorder.ShouldRemeasureDescendants = true;
				_templatedBorder.UpdateScollBars();
			}
		}

		private bool ShouldRemeasureChild()
		{
			if (RecalculateContentSizeAlways)
			{
				return true;
			}
			if (RecalculateContentSizeNever)
			{
				return false;
			}
			return IsChildStrechable(base.Content as FrameworkElement);
		}

		private bool IsChildStrechable(FrameworkElement element)
		{
			if (element == null)
			{
				return false;
			}
			if (element is AutoFitPanel)
			{
				return true;
			}
			if (element.HorizontalAlignment != HorizontalAlignment.Stretch && element.VerticalAlignment != VerticalAlignment.Stretch)
			{
				return false;
			}
			if (element is Grid grid)
			{
				if (grid.VerticalAlignment == VerticalAlignment.Stretch && grid.RowDefinitions.FirstOrDefault((RowDefinition rd) => rd.Height.IsStar) != null)
				{
					return true;
				}
				if (grid.HorizontalAlignment == HorizontalAlignment.Stretch && grid.ColumnDefinitions.FirstOrDefault((ColumnDefinition cd) => cd.Width.IsStar) != null)
				{
					return true;
				}
				return false;
			}
			return true;
		}

