		internal void InitContextMenu(ContextMenuEventArgs e)
		{
			if (ReadLocalValue(FrameworkElement.ContextMenuProperty) != DependencyProperty.UnsetValue || ShouldSkipToCreateContextMenu(e.OriginalSource))
			{
				return;
			}
			if (_defaultContextMenu == null)
			{
				_defaultContextMenu = new ContextMenu();
				BuildDefaultContextMenu(_defaultContextMenu);
			}
			if (_defaultContextMenu.Items.Count <= 0)
			{
				return;
			}
			OnDefaultContextMenuInvoking(new RoutedEventArgs<ContextMenu>(_defaultContextMenu, DefaultContextMenuInvokingEvent, this));
			if (_defaultContextMenu.Items.Count > 0)
			{
				_defaultContextMenu.IsOpen = true;
				if (e != null)
				{
					e.Handled = true;
				}
			}
		}

		private bool ShouldSkipToCreateContextMenu(object originalSource)
		{
			DependencyObject dependencyObject = originalSource as DependencyObject;
			while (dependencyObject != null && dependencyObject != this)
			{
				if (_ControlTypesToSkip.Contains(dependencyObject.GetType()))
				{
					return true;
				}
				try
				{
					dependencyObject = VisualTreeHelper.GetParent(dependencyObject);
				}
				catch
				{
					return true;
				}
			}
			return false;
		}

		protected virtual void BuildDefaultContextMenu(ContextMenu menu)
		{
			string text = "pack://application:,,,/" + typeof(AesControlBase).Assembly.FullName + ";component/Images/";
			if (menu != null)
			{
				System.Windows.Controls.Image image = new System.Windows.Controls.Image();
				image.Source = new BitmapImage(new Uri(text + "Copy16.ico"));
				menu.Items.Add(new MenuItem
				{
					Header = AspenTech.AspenPlus.MMControls.Properties.Resources.ContextMenuHeaderCopyVars,
					InputGestureText = "",
					Command = ApplicationCommands.Copy,
					CommandTarget = this,
					Icon = image
				});
			}
		}

		protected virtual void OnDefaultContextMenuInvoking(RoutedEventArgs<ContextMenu> e)
		{
			RaiseEvent(e);
		}

