		private static bool HasVariableChild(DependencyObject parent)
		{
			if (!(parent is UIElement uIElement))
			{
				return false;
			}
			if (uIElement.Visibility != Visibility.Visible)
			{
				return false;
			}
			if (parent is AesVariableControlBase)
			{
				if (!(parent is AesGroupBox) && !(parent is AesCmdButton) && !(parent is AesExpander) && !(parent is AesOptionGroup))
				{
					return true;
				}
			}
			else
			{
				if (parent is MMScrollArea)
				{
					return true;
				}
				if (parent is MMScrollAreaBase)
				{
					return true;
				}
				if (parent is MMScrollAreaMS)
				{
					return true;
				}
			}
			if (parent is IVariableControl)
			{
				return (parent as IVariableControl).HasVariables;
			}
			int childrenCount = VisualTreeHelper.GetChildrenCount(parent);
			for (int i = 0; i < childrenCount; i++)
			{
				if (HasVariableChild(VisualTreeHelper.GetChild(parent, i)))
				{
					return true;
				}
			}
			return false;
		}

		public static void AddVariableChild(DependencyObject parent, ICollection<string> monikers)
		{
			if (!(parent is UIElement { Visibility: Visibility.Visible }))
			{
				return;
			}
			if (parent is AesVariableControlBase)
			{
				if (!(parent is AesGroupBox) && !(parent is AesCmdButton) && !(parent is AesExpander) && !(parent is AesOptionGroup))
				{
					if (!((parent as AesVariableControlBase).Variable is CxvVariableData { ResolvedExposeAs: CxvVariableTypeCode.Id }))
					{
						string cxsItemMoniker = DataForClipboard.GetCxsItemMoniker(parent);
						if (!string.IsNullOrEmpty(cxsItemMoniker) && !monikers.Contains(cxsItemMoniker))
						{
							monikers.Add(cxsItemMoniker);
						}
					}
					return;
				}
			}
			else
			{
				if (parent is MMScrollArea)
				{
					MMScrollAreaCommand.CopyAllVariables(parent as MMScrollArea, monikers);
					return;
				}
				if (parent is MMScrollAreaBase)
				{
					MMScrollAreaManualLayoutCommand.CopyAllVariables(parent as MMScrollAreaBase, monikers);
					return;
				}
				if (parent is MMScrollAreaMS)
				{
					MMScrollAreaMS.CopyAllVariables(parent as MMScrollAreaMS, monikers);
					return;
				}
			}
			if (parent is IVariableControl)
			{
				IEnumerable<string> variableMonikers = (parent as IVariableControl).GetVariableMonikers();
				if (variableMonikers == null)
				{
					return;
				}
				{
					foreach (string item in variableMonikers)
					{
						monikers.Add(item);
					}
					return;
				}
			}
			int childrenCount = VisualTreeHelper.GetChildrenCount(parent);
			for (int i = 0; i < childrenCount; i++)
			{
				AddVariableChild(VisualTreeHelper.GetChild(parent, i), monikers);
			}
		}

		private void ChildScrollAreas_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			if (e.Action != NotifyCollectionChangedAction.Add || e.NewItems == null || _scrollAreaSettings == null || _scrollAreaSettings.Count <= 0)
			{
				return;
			}
			foreach (IScrollAreaSettings sa in e.NewItems)
			{
				KeyValuePair<string, string> keyValuePair = _scrollAreaSettings.FirstOrDefault((KeyValuePair<string, string> x) => string.Equals(x.Key, sa.Name, StringComparison.InvariantCulture));
				if (!string.IsNullOrEmpty(keyValuePair.Value))
				{
					sa.RestoreGridSettings(keyValuePair.Value);
				}
			}
		}

		public virtual string SaveFormSettings()
		{
			if (base.Content is IFormSettings formSettings)
			{
				return formSettings.SaveFormSettings();
			}
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			foreach (IScrollAreaSettings layoutSettingControl in LayoutSettingControls)
			{
				string name = layoutSettingControl.Name;
				if (!string.IsNullOrEmpty(name))
				{
					string value = layoutSettingControl.SaveGridSettings();
					if (!string.IsNullOrEmpty(value))
					{
						dictionary[name] = value;
					}
				}
			}
			if (dictionary.Count > 0)
			{
				XDocument xDocument = new XDocument(new XElement("pageRoot"));
				XElement xElement = new XElement("scrollAreas");
				xDocument.Root.Add(xElement);
				foreach (KeyValuePair<string, string> item in dictionary)
				{
					XElement xElement2 = new XElement("scrollArea");
					xElement2.SetAttributeValue("id", item.Key);
					xElement2.SetValue(item.Value);
					xElement.Add(xElement2);
				}
				return xDocument.ToString();
			}
			return null;
		}

		public virtual void RestoreFormSettings(string settings)
		{
			if (base.Content is IFormSettings formSettings)
			{
				formSettings.RestoreFormSettings(settings);
			}
			else
			{
				if (string.IsNullOrEmpty(settings))
				{
					return;
				}
				XDocument xDocument = XDocument.Parse(settings);
				if (xDocument == null)
				{
					return;
				}
				XElement xElement = xDocument.Root.Elements("scrollAreas").FirstOrDefault();
				if (xElement == null)
				{
					return;
				}
				if (_scrollAreaSettings == null)
				{
					_scrollAreaSettings = new Dictionary<string, string>();
				}
				foreach (XElement item in xElement.Elements())
				{
					_scrollAreaSettings.Add((string)item.Attribute("id"), item.Value);
				}
				RestoreScrollAreaSettings();
			}
		}

		public void RestoreScrollAreaSettings()
		{
			if (LayoutSettingControls.Count == 0 || _scrollAreaSettings == null)
			{
				return;
			}
			foreach (string id in _scrollAreaSettings.Keys)
			{
				LayoutSettingControls.FirstOrDefault((IScrollAreaSettings x) => string.Equals(x.Name, id, StringComparison.InvariantCulture))?.RestoreGridSettings(_scrollAreaSettings[id]);
			}
		}

