		protected MMTabPage ResolveNeighborTabPage(int tabIndex)
		{
			MMTabStrip mMTabStrip = FindParentTabStrip();
			if (mMTabStrip != null && mMTabStrip.Items.Count > tabIndex && tabIndex >= 0)
			{
				return mMTabStrip.Items[tabIndex].ForceGetContent() as MMTabPage;
			}
			return null;
		}

		protected MMTabPage ResolveNeighborTabPage(string tabProgId)
		{
			MMTabStrip mMTabStrip = FindParentTabStrip();
			if (mMTabStrip != null)
			{
				MMTabItem mMTabItem = mMTabStrip.Items.FirstOrDefault((MMTabItem x) => string.Equals(x.ContentProgId, tabProgId, StringComparison.InvariantCultureIgnoreCase));
				if (mMTabItem != null)
				{
					return mMTabItem.ForceGetContent() as MMTabPage;
				}
			}
			return null;
		}

		protected T ResolveNeighborTabPage<T>() where T : MMTabPage
		{
			MMTabStrip mMTabStrip = FindParentTabStrip();
			if (mMTabStrip != null)
			{
				MMTabItem mMTabItem = mMTabStrip.Items.FirstOrDefault((MMTabItem x) => x.ContentType == typeof(T));
				if (mMTabItem != null)
				{
					return mMTabItem.ForceGetContent() as T;
				}
			}
			return null;
		}

		private MMTabStrip FindParentTabStrip()
		{
