	public class RibbonGalleryPlotBehavior : DependencyObject
	{
		private const string CustomPlotKey = "Custom";

		private const string ParametricPlotKey = "Parametric";

		public static readonly DependencyProperty SuppressCustomProperty = DependencyProperty.Register("SuppressCustom", typeof(bool), typeof(RibbonGalleryPlotBehavior));

		public static readonly DependencyProperty SuppressParametricProperty = DependencyProperty.Register("SuppressParametric", typeof(bool), typeof(RibbonGalleryPlotBehavior));

		[DefaultValue(false)]
		public bool SuppressCustom
		{
			get
			{
				return (bool)GetValue(SuppressCustomProperty);
			}
			set
			{
				SetValue(SuppressCustomProperty, value);
			}
		}

		[DefaultValue(false)]
		public bool SuppressParametric
		{
			get
			{
				return (bool)GetValue(SuppressParametricProperty);
			}
			set
			{
				SetValue(SuppressParametricProperty, value);
			}
		}

		[DesignerSerializationVisibility(DesignerSerializationVisibility.Content)]
		public IList<string> ExclusivePlotTypes { get; private set; }

		[DesignerSerializationVisibility(DesignerSerializationVisibility.Content)]
		public IList<string> MustHavePlotTypes { get; private set; }

		public RibbonGalleryPlotBehavior()
		{
			ExclusivePlotTypes = new List<string>();
			MustHavePlotTypes = new List<string>();
		}

		public IEnumerable<string> FilterBuiltInPlotTypes(IEnumerable<string> builtInPlotTypes)
		{
			List<string> list = new List<string>();
			if (builtInPlotTypes != null)
			{
				list.AddRange(builtInPlotTypes);
				if (MustHavePlotTypes.Count > 0)
				{
					foreach (string mustHavePlotType in MustHavePlotTypes)
					{
						if (!list.Contains(mustHavePlotType, StringComparer.InvariantCultureIgnoreCase))
						{
							list.Add(mustHavePlotType);
						}
					}
				}
				if (ExclusivePlotTypes.Count > 0)
				{
					list.RemoveAll((string x) => ExclusivePlotTypes.Contains(x, StringComparer.InvariantCultureIgnoreCase));
				}
				if (SuppressCustom)
				{
					list.RemoveAll((string x) => string.Equals(x, "Custom", StringComparison.InvariantCultureIgnoreCase));
				}
				if (SuppressParametric)
				{
					list.RemoveAll((string x) => string.Equals(x, "Parametric", StringComparison.InvariantCultureIgnoreCase));
				}
			}
			return list;
		}
	}
