		public static readonly DependencyProperty UpperLimitProperty;

		public static readonly DependencyProperty SpinStepSizeProperty;

		public static readonly DependencyProperty ValueProperty;

		private static RoutedCommand _spinUpCommand;

		private static RoutedCommand _spinDownCommand;

		public int? LowerLimit
		{
			get
			{
				return (int?)GetValue(LowerLimitProperty);
			}
			set
			{
				SetValue(LowerLimitProperty, value);
			}
		}

		public int? UpperLimit
		{
			get
			{
				return (int?)GetValue(UpperLimitProperty);
			}
			set
			{
				SetValue(UpperLimitProperty, value);
			}
		}

		public int SpinStepSize
		{
			get
			{
				return (int)GetValue(SpinStepSizeProperty);
			}
			set
			{
				SetValue(SpinStepSizeProperty, value);
			}
		}

		public int? Value
		{
			get
			{
				return (int?)GetValue(ValueProperty);
			}
			set
			{
				SetValue(ValueProperty, value);
			}
		}

		public static RoutedCommand SpinUpCommand => _spinUpCommand;

		public static RoutedCommand SpinDownCommand => _spinDownCommand;

		public override void OnApplyTemplate()
		{
			base.OnApplyTemplate();
			if (base.Template.FindName("PART_TextBox", this) is TextBox textBox)
			{
				textBox.PreviewTextInput += textBox_PreviewTextInput;
			}
		}

		private void textBox_PreviewTextInput(object sender, TextCompositionEventArgs e)
		{
			if (!string.IsNullOrEmpty(e.Text) && Regex.IsMatch(e.Text, "\\D"))
			{
				e.Handled = true;
			}
		}

		static NumericSpinBox()
		{
			LowerLimitProperty = DependencyProperty.Register("LowerLimit", typeof(int?), typeof(NumericSpinBox), new FrameworkPropertyMetadata(null));
			UpperLimitProperty = DependencyProperty.Register("UpperLimit", typeof(int?), typeof(NumericSpinBox), new FrameworkPropertyMetadata(null));
			SpinStepSizeProperty = DependencyProperty.Register("SpinStepSize", typeof(int), typeof(NumericSpinBox), new FrameworkPropertyMetadata(1));
			ValueProperty = DependencyProperty.Register("Value", typeof(int?), typeof(NumericSpinBox), new FrameworkPropertyMetadata(0));
			_spinUpCommand = new RoutedCommand("SpinUpCommand", typeof(NumericSpinBox));
			_spinDownCommand = new RoutedCommand("SpinDownCommand", typeof(NumericSpinBox));
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(NumericSpinBox), new FrameworkPropertyMetadata(typeof(NumericSpinBox)));
			CommandManager.RegisterClassCommandBinding(typeof(NumericSpinBox), new CommandBinding(SpinUpCommand, OnSpinUp));
			CommandManager.RegisterClassCommandBinding(typeof(NumericSpinBox), new CommandBinding(SpinDownCommand, OnSpinDown));
		}

		private static void OnSpinUp(object sender, ExecutedRoutedEventArgs e)
		{
			NumericSpinBox numericSpinBox = sender as NumericSpinBox;
			if (!numericSpinBox.Value.HasValue)
			{
				return;
			}
			if (numericSpinBox.UpperLimit.HasValue)
			{
				if (numericSpinBox.Value + numericSpinBox.SpinStepSize <= numericSpinBox.UpperLimit.Value)
				{
					numericSpinBox.Value += numericSpinBox.SpinStepSize;
				}
			}
			else
			{
				numericSpinBox.Value += numericSpinBox.SpinStepSize;
			}
		}

		private static void OnSpinDown(object sender, ExecutedRoutedEventArgs e)
		{
			NumericSpinBox numericSpinBox = sender as NumericSpinBox;
			if (!numericSpinBox.Value.HasValue)
			{
				return;
			}
			if (numericSpinBox.LowerLimit.HasValue)
			{
				if (numericSpinBox.Value - numericSpinBox.SpinStepSize >= numericSpinBox.LowerLimit.Value)
				{
					numericSpinBox.Value -= numericSpinBox.SpinStepSize;
				}
			}
			else
			{
				numericSpinBox.Value -= numericSpinBox.SpinStepSize;
			}
		}
	}
