		private void UpdateNewActiveTab()
		{
			if (ActiveTab.Visibility == Visibility.Visible)
			{
				return;
			}
			using IEnumerator<MMTabItem> enumerator = Items.GetEnumerator();
			if (enumerator.MoveNext())
			{
				MMTabItem current = enumerator.Current;
				if (current.Visibility == Visibility.Visible)
				{
					current.IsSelected = true;
				}
			}
		}

		private static void OnUnityContainerPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs args)
		{
			if (d is MMTabStrip mMTabStrip && args.NewValue != args.OldValue)
			{
				mMTabStrip.OnUnityContainerChanged(args.OldValue as IUnityContainer, args.NewValue as IUnityContainer);
			}
		}

		protected virtual void OnUnityContainerChanged(IUnityContainer oldContainer, IUnityContainer newContainer)
		{
			if (newContainer == null)
			{
				return;
			}
			CxvSharedParameters cxvSharedParameters = newContainer.Resolve<CxvSharedParameters>(Array.Empty<ResolverOverride>());
			if (cxvSharedParameters != null && cxvSharedParameters.Parameters.Find("selected_tab") != null)
			{
				CxvParameter cxvParameter = cxvSharedParameters.Parameters.Find("selected_tab");
				if (cxvParameter != null && cxvParameter.Value != null && GetActiveTabId() != cxvParameter.Value.ToString())
				{
					SetTabById(cxvParameter.Value.ToString());
				}
			}
			foreach (MMTabItem item in Items)
			{
				newContainer.BuildUp(item.GetType(), item);
			}
		}

