		public int NextHit(out string messages)
		{
			MMTabItem mMTabItem = null;
			foreach (MMTabItem item in Items)
			{
				if (item.IsSelected)
				{
					mMTabItem = item;
					if ((!item.Accessible.HasValue || item.Accessible.Value) && item.Complete.HasValue && !item.Complete.Value)
					{
						messages = item.CompletionMessages;
						return 0;
					}
				}
				else if (mMTabItem != null && (!item.Accessible.HasValue || item.Accessible.Value) && item.Complete.HasValue && !item.Complete.Value)
				{
					item.IsSelected = true;
					messages = null;
					return 1;
				}
			}
			foreach (MMTabItem item2 in Items)
			{
				if (item2 == mMTabItem)
				{
					break;
				}
				if ((!item2.Accessible.HasValue || item2.Accessible.Value) && item2.Complete.HasValue && !item2.Complete.Value)
				{
					item2.IsSelected = true;
					messages = null;
					return 1;
				}
			}
			messages = null;
			return -1;
		}

		public bool IsIncomplete()
		{
			foreach (MMTabItem item in Items)
			{
				if ((!item.Accessible.HasValue || item.Accessible.Value) && item.Complete.HasValue && !item.Complete.Value)
				{
					return true;
				}
			}
			return false;
		}

