		public string GetActiveTabName()
		{
			string result = string.Empty;
			MMTabItem activeTab = ActiveTab;
			if (activeTab != null && activeTab.Header != null)
			{
				result = activeTab.Header.ToString();
			}
			return result;
		}

		public string GetActiveTabId()
		{
			string result = string.Empty;
			MMTabItem activeTab = ActiveTab;
			if (activeTab != null && activeTab.Name != null)
			{
				result = activeTab.Name;
			}
			return result;
		}

		public bool SetTab(string sTabName)
		{
			bool result = false;
			foreach (MMTabItem item in Items)
			{
				if (item.Header != null && sTabName.CompareTo(item.Header.ToString()) == 0)
				{
					item.IsSelected = true;
					result = true;
					break;
				}
			}
			return result;
		}

		public bool SetTabById(string sTabName)
		{
			bool result = false;
			foreach (MMTabItem item in Items)
			{
				if (item == null || !(sTabName == item.Name))
				{
					continue;
				}
				if (DelayOpenTab)
				{
					base.Dispatcher.BeginInvoke(DispatcherPriority.Loaded, (Action)delegate
					{
						item.IsSelected = true;
					});
				}
				else
				{
					base.Dispatcher.BeginInvoke((Action)delegate
					{
						item.IsSelected = true;
					});
				}
				result = true;
				break;
			}
			return result;
		}

		void IViewModelDisposable.DisposeViewModel()
		{
			foreach (MMTabItem item in Items)
			{
				if (item.Content is IViewModelDisposable viewModelDisposable)
				{
					viewModelDisposable.DisposeViewModel();
				}
			}
		}

		public string SaveFormSettings()
		{
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			foreach (MMTabItem item in Items)
			{
				string text = item.Header as string;
				if (!string.IsNullOrEmpty(text))
				{
					string value = item.SaveFormSettings();
					if (!string.IsNullOrEmpty(value))
					{
						dictionary.Add(text, value);
					}
				}
			}
			if (dictionary.Count > 0)
			{
				XDocument xDocument = new XDocument(new XElement("root"));
				XElement xElement = new XElement("tabs");
				xDocument.Root.Add(xElement);
				foreach (KeyValuePair<string, string> item2 in dictionary)
				{
					XElement xElement2 = new XElement("tab");
					xElement2.SetAttributeValue("id", item2.Key);
					xElement2.SetValue(item2.Value);
					xElement.Add(xElement2);
				}
				return xDocument.ToString();
			}
			return null;
		}

		public void RestoreFormSettings(string settings)
		{
			if (string.IsNullOrEmpty(settings))
			{
				return;
			}
			XDocument xDocument = XDocument.Parse(settings);
			if (xDocument == null)
			{
				return;
			}
			XElement xElement = xDocument.Root.Elements("tabs").FirstOrDefault();
			if (xElement == null)
			{
				return;
			}
			foreach (XElement item in xElement.Elements())
			{
				string id = (string)item.Attribute("id");
				Items.FirstOrDefault((MMTabItem x) => string.Equals(x.Header as string, id, StringComparison.CurrentCultureIgnoreCase))?.RestoreFormSettings(item.Value);
			}
		}

		protected virtual void OnContextualRibbonTabsChanged()
		{
			if (this.ContextualRibbonTabsChanged != null)
			{
				this.ContextualRibbonTabsChanged(this, EventArgs.Empty);
			}
		}

		public void RaiseContextualRibbonTabsChanged()
		{
			OnContextualRibbonTabsChanged();
		}

		public void DetachContextualRibbonTabsChanged()
		{
			if (_contextualRibbonHelper == null)
			{
				return;
			}
			foreach (MMTabItem item in Items)
			{
				_contextualRibbonHelper.DetachContextualRibbonTabsChanged(item);
			}
		}

		public void OnClosed()
		{
			foreach (MMTabItem item in Items)
			{
				item.OnClosed();
			}
			Items.Clear();
		}
	}
