				UpdateResultStatusImage();
			}
		}

		private void _watch_PropertyDependencyChanged(object sender, EventArgs e)
		{
			UpdateResultStatusImage();
		}

		private void UpdateResultStatusImage()
		{
			if (_watch == null)
			{
				_watch = new CxvPropertyWatch();
				_watch.PropertyDependencyChanged += _watch_PropertyDependencyChanged;
			}
			else
			{
				_watch.Clear();
			}
			ImageSource tabStatusImage = null;
			if (_viewModel == null)
			{
				_viewModel = UnityContainer.Resolve<MMViewModel>(Array.Empty<ResolverOverride>());
			}
			int? num = CxsConverter.ValueToInt32(_viewModel.ExpandDataPathAndGet("@main", "status_code", null, _watch));
			string strObjectPath = _viewModel.ExpandDataPath("@main");
			if (UnityContainer != null)
			{
				PSVGetObjectStatusCodeEventArgs e = new PSVGetObjectStatusCodeEventArgs(strObjectPath);
				UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<PSVGetObjectStatusCodeEvent>().Publish(e);
				if (e.PSVMode && e.StatusCode != -1)
				{
					num = e.StatusCode;
				}
			}
			if (num.HasValue)
			{
				if ((num & 0x10000) != 0)
				{
					tabStatusImage = AspenTech.AspenPlus.MMControls.Internal.ImageResources.StatusError_16;
				}
				else if ((num & 0x8000) != 0)
				{
					tabStatusImage = AspenTech.AspenPlus.MMControls.Internal.ImageResources.Caution_16;
				}
				else if ((num & 1) != 0)
				{
					tabStatusImage = AspenTech.AspenPlus.MMControls.Internal.ImageResources.StatusComplete_16;
				}
				else if ((num & 0x20) != 0)
				{
					tabStatusImage = AspenTech.AspenPlus.MMControls.Internal.ImageResources.StatusError_16;
				}
				else if ((num & 4) != 0)
				{
					tabStatusImage = AspenTech.AspenPlus.MMControls.Internal.ImageResources.Caution_16;
				}
				else if ((num & 0x10) != 0)
				{
					tabStatusImage = AspenTech.AspenPlus.MMControls.Internal.ImageResources.StatusInputChanged_16;
				}
				else if ((num & 0x40) != 0)
				{
					tabStatusImage = AspenTech.AspenPlus.MMControls.Internal.ImageResources.StatusIncomplete_16;
				}
			}
			TabStatusImage = tabStatusImage;
		}

