		private void UpdateTabStatusImage()
		{
			if (ContentProgId == "MMGeneric.MMGeneric_Results_Status")
			{
				return;
			}
			ImageSource tabStatusImage = null;
			if (AccessibleResolved)
			{
				bool? complete = Complete;
				if (complete.HasValue)
				{
					if (complete.Value)
					{
						bool? entered = Entered;
						if (!entered.HasValue || entered.Value)
						{
							tabStatusImage = AspenTech.AspenPlus.MMControls.Internal.ImageResources.InputComplete_16x16;
						}
					}
					else
					{
						tabStatusImage = AspenTech.AspenPlus.MMControls.Internal.ImageResources.InputRequired_16x16;
					}
				}
				else
				{
					bool? entered2 = Entered;
					if (entered2.HasValue && entered2.Value)
					{
						tabStatusImage = AspenTech.AspenPlus.MMControls.Internal.ImageResources.InputComplete_16x16;
					}
				}
			}
			TabStatusImage = tabStatusImage;
		}

