		public object ForceGetContent()
		{
			if (base.Content == null)
			{
				UpdateContent(ignoreSelectedOrNot: true);
			}
			return base.Content;
		}

		private void UpdateContent(bool ignoreSelectedOrNot = false)
		{
			Type type = ContentType;
			if (type == null)
			{
				string contentProgId = ContentProgId;
				if (!string.IsNullOrEmpty(contentProgId))
				{
					IUnityContainer unityContainer = UnityContainer;
					if (unityContainer != null)
					{
						type = unityContainer.Resolve<MMFormsCatalog>(Array.Empty<ResolverOverride>()).LookupControlType(contentProgId);
					}
				}
			}
			if (type == null || (base.Content != null && !_contentCreatedFromType) || (!ignoreSelectedOrNot && !base.IsSelected) || (base.Content != null && base.Content.GetType() == type))
			{
				return;
			}
			try
			{
				IUnityContainer unityContainer2 = UnityContainer;
				if (unityContainer2 != null)
				{
					base.Content = unityContainer2.Resolve(type);
				}
				else
				{
					base.Content = Activator.CreateInstance(type);
				}
				_contentCreatedFromType = true;
			}
			catch (Exception)
			{
			}
		}

		public override bool ShouldSerializeContent()
		{
			if (_contentCreatedFromType)
			{
				return false;
			}
			return base.ShouldSerializeContent();
		}

