		void IAutoBindControl.GenerateVariableToValueBindingItems(IList<VariableToValueBindingItem> items)
		{
			items.Add(new VariableToValueBindingItem(VariableProperty, EnteredProperty, EnteredProperty.Name)
			{
				Mode = BindingMode.OneWay
			});
			items.Add(new VariableToValueBindingItem(VariableProperty, CompleteProperty, CompleteProperty.Name)
			{
				Mode = BindingMode.OneWay
			});
			items.Add(new VariableToValueBindingItem(VariableProperty, AccessibleProperty, AccessibleProperty.Name)
			{
				Mode = BindingMode.OneWay
			});
			items.Add(new VariableToValueBindingItem(VariableProperty, PromptProperty, "VariablePrompt")
			{
				Mode = BindingMode.OneWay
			});
			items.Add(new VariableToValueBindingItem(VariableProperty, UIElement.VisibilityProperty, "IsVisible")
			{
				Mode = BindingMode.OneWay,
				Converter = new MMTabItemlVisibilityConverter()
			});
		}

