	[AttributeUsage(AttributeTargets.Class)]
	public sealed class MMBrowserInformationAttribute : Attribute
	{
		public string BrowserNodeId { get; set; }

		public string BrowserDisplayName { get; set; }

		public string BrowserDisplayResourceKey { get; set; }

		public MMFormBrowserInfo ConvertToFormInfo(Type owner)
		{
			return new MMFormBrowserInfo
			{
				FormType = owner,
				BrowserNodeId = BrowserNodeId,
				BrowserDisplayName = BrowserDisplayName,
				BrowserDisplayResourceKey = BrowserDisplayResourceKey
			};
		}
	}
	public class MMFormsCatalog
	{
		private ILoggerFacade _logger;

		private IUnityContainer _container;

		private Dictionary<string, Type> _catalog = new Dictionary<string, Type>();

		private Dictionary<string, List<MMFormBrowserInfo>> _navigatorFormDictionary = new Dictionary<string, List<MMFormBrowserInfo>>();

		public MMFormsCatalog(ILoggerFacade logger, IUnityContainer container)
		{
			_logger = logger;
			_container = container;
		}

		public void RegisterForm(Type form)
		{
			ProgIdAttribute progIdAttribute = form.GetCustomAttributes(typeof(ProgIdAttribute), inherit: false).FirstOrDefault() as ProgIdAttribute;
			string text = string.Empty;
			if (progIdAttribute != null)
			{
				text = progIdAttribute.Value;
			}
			if (!string.IsNullOrEmpty(text))
			{
				text = text.ToUpperInvariant();
				_logger.Log(string.Format(CultureInfo.InvariantCulture, "  Registering form {0} as {1}", form.FullName, text), Category.Info, Priority.Low);
				_catalog[text] = form;
			}
			object[] customAttributes = form.GetCustomAttributes(typeof(MMBrowserInformationAttribute), inherit: false);
			if (customAttributes != null && customAttributes.Length != 0)
			{
				object[] array = customAttributes;
				for (int i = 0; i < array.Length; i++)
				{
					MMFormBrowserInfo formInfo = (array[i] as MMBrowserInformationAttribute).ConvertToFormInfo(form);
					RegisterFormInfo(formInfo);
				}
			}
			else
			{
				if (!typeof(MMTabTemplate).IsAssignableFrom(form) || string.IsNullOrEmpty(text))
				{
					return;
				}
				int num = text.IndexOf('.');
				if (num > 0)
				{
					string text2 = text.Substring(0, num).ToUpperInvariant();
					if (text2.StartsWith("MM", StringComparison.Ordinal))
					{
						text2 = text2.Substring(2);
					}
					string text3 = text.Substring(num + 1);
					int num2 = text3.IndexOf('_');
					if (num2 > 0)
					{
						text3 = text3.Substring(num2 + 1);
					}
					RegisterFormInfo(new MMFormBrowserInfo
					{
						BrowserNodeId = text2,
						FormType = form,
						BrowserDisplayName = text3
					});
				}
			}
		}

		public void RegisterFormInfo(MMFormBrowserInfo formInfo)
		{
			if (!string.IsNullOrEmpty(formInfo.BrowserNodeId) && !string.IsNullOrEmpty(formInfo.BrowserNodeId))
			{
				List<MMFormBrowserInfo> value = null;
				if (!_navigatorFormDictionary.TryGetValue(formInfo.BrowserNodeId, out value))
				{
					value = new List<MMFormBrowserInfo>();
					_navigatorFormDictionary[formInfo.BrowserNodeId] = value;
				}
				value.Add(formInfo);
			}
		}

		public string[] GetRegisteredForms()
		{
			return _catalog.Keys.ToArray();
		}

		public Type LookupControlType(string name)
		{
			if (FormsManager.IsInitialized)
			{
				Type type = FormsManager.LookupTypeByProgId(name);
				if (type != null)
				{
					return type;
				}
			}
			Type value = null;
			_catalog.TryGetValue(name.ToUpperInvariant(), out value);
			return value;
		}

		public IEnumerable<string> EnumerateForms()
		{
			foreach (string key in _catalog.Keys)
			{
				yield return key;
			}
		}

		public IEnumerable<MMFormBrowserInfo> EnumerateFormForBrowserKey(string key)
		{
			List<MMFormBrowserInfo> value = null;
			if (!_navigatorFormDictionary.TryGetValue(key, out value))
			{
				yield break;
			}
			foreach (MMFormBrowserInfo item in value)
			{
				yield return item;
			}
		}
	}
