		private bool _inEditMode;

		private bool _changed;

		public bool? UseFieldHelp
		{
			get
			{
				return (bool?)GetValue(UseFieldHelpProperty);
			}
			set
			{
				SetValue(UseFieldHelpProperty, value);
			}
		}

		private static void OnUseFieldHelpChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			if ((e.NewValue as bool?) ?? false)
			{
				(d as FrameworkElement).SetBinding(MMHelp.HelpFileProperty, new MultiBinding
				{
					Bindings = 
					{
						(BindingBase)new Binding("Variable.HelpFile")
						{
							Source = d
						},
						(BindingBase)new Binding
						{
							Source = d
						}
					},
					Converter = new HelpFileConverter(),
					Mode = BindingMode.OneWay
				});
				(d as FrameworkElement).SetBinding(MMHelp.HelpIdProperty, new MultiBinding
				{
					Bindings = 
					{
						(BindingBase)new Binding("Variable.HelpId")
						{
							Source = d
						},
						(BindingBase)new Binding
						{
							Source = d
						}
					},
					Converter = new HelpIdConverter(),
					Mode = BindingMode.OneWay
				});
			}
		}

		static MMVariableEdit()
		{
			UseFieldHelpProperty = DependencyProperty.Register("UseFieldHelp", typeof(bool?), typeof(MMVariableEdit), new FrameworkPropertyMetadata(null, OnUseFieldHelpChanged));
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(MMVariableEdit), new FrameworkPropertyMetadata(typeof(MMVariableEdit)));
			AesVariableEdit.MaxLengthProperty.OverrideMetadata(typeof(MMVariableEdit), new FrameworkPropertyMetadata(11));
			AesVariableEdit.ValueMaskProperty.OverrideMetadata(typeof(MMVariableEdit), new FrameworkPropertyMetadata(AesMaskOption.Double));
		}

		public override void OnApplyTemplate()
		{
			base.OnApplyTemplate();
			if (base.Template.FindName("textBox", this) is AesValueEdit aesValueEdit)
			{
				aesValueEdit.Loaded += varEditor_Loaded;
			}
		}

		private void varEditor_Loaded(object sender, RoutedEventArgs e)
		{
			if (sender is AesValueEdit aesValueEdit)
			{
				aesValueEdit.Loaded -= varEditor_Loaded;
				if (aesValueEdit.Template.FindName("PART_editControl", aesValueEdit) is AesXamValueEdit aesXamValueEdit)
				{
					aesXamValueEdit.EditModeStarting += valEdit_EditModeStarting;
				}
			}
		}

		private void valEdit_EditModeStarting(object sender, Infragistics.Windows.Editors.Events.EditModeStartingEventArgs e)
		{
			if (base.Variable != null && base.UnitsVisibility == Visibility.Visible)
			{
				if (!(base.Variable is ICxvEditableObject cxvEditableObject))
				{
					return;
				}
				if (!_managingVariableEdits)
				{
					_managingVariableEdits = true;
					if (sender is AesXamValueEdit aesXamValueEdit)
					{
						aesXamValueEdit.EditModeEnded += valEdit_EditModeEnded;
						aesXamValueEdit.ValueChanged += valEdit_ValueChanged;
					}
				}
				_inEditMode = true;
				_changed = false;
				cxvEditableObject.BeginEdit();
			}
			else if (sender is AesXamValueEdit aesXamValueEdit2)
			{
				aesXamValueEdit2.EditModeStarting -= valEdit_EditModeStarting;
			}
		}

		private void valEdit_ValueChanged(object sender, RoutedPropertyChangedEventArgs<object> e)
		{
			if (_inEditMode)
			{
				_changed = true;
			}
		}

		private void valEdit_EditModeEnded(object sender, Infragistics.Windows.Editors.Events.EditModeEndedEventArgs e)
		{
			if (!_inEditMode)
			{
				return;
			}
			if (base.Variable is ICxvEditableObject cxvEditableObject)
			{
				if (_changed && e.ChangesAccepted)
				{
					if (base.IsKeyboardFocusWithin && base.Template.FindName("PART_UnitEdit", this) is AesUnitsEdit { IsKeyboardFocusWithin: not false } aesUnitsEdit && aesUnitsEdit.Template.FindName("PART_editControl", aesUnitsEdit) is AesXamComboEdit { IsInEditMode: not false } aesXamComboEdit)
					{
						aesXamComboEdit.EditModeEnded += comboEdit_EditModeEnded;
						aesXamComboEdit.DropDownClosed += comboEdit_DropDownClosed;
						return;
					}
					try
					{
						cxvEditableObject.EndEdit();
					}
					catch (CxsException)
					{
					}
				}
				else
				{
					cxvEditableObject.CancelEdit();
				}
			}
			_inEditMode = false;
		}

		private void comboEdit_DropDownClosed(object sender, RoutedEventArgs e)
		{
			base.Dispatcher.BeginInvoke((Action)delegate
			{
				EndUnitsEdit(sender, acceptChanges: true);
			});
		}

		private void comboEdit_EditModeEnded(object sender, Infragistics.Windows.Editors.Events.EditModeEndedEventArgs e)
		{
			EndUnitsEdit(sender, e.ChangesAccepted);
		}

		private void EndUnitsEdit(object sender, bool acceptChanges)
		{
			if (sender is AesXamComboEdit aesXamComboEdit)
			{
				aesXamComboEdit.EditModeEnded -= comboEdit_EditModeEnded;
				aesXamComboEdit.DropDownClosed -= comboEdit_DropDownClosed;
			}
			if (!_inEditMode)
			{
				return;
			}
			if (base.Variable is ICxvEditableObject cxvEditableObject)
			{
				if (acceptChanges)
				{
					try
					{
						cxvEditableObject.EndEdit();
					}
					catch (CxsException)
					{
					}
				}
				else
				{
					cxvEditableObject.CancelEdit();
				}
			}
			_inEditMode = false;
		}
	}
	internal class HelpFileConverter : IMultiValueConverter
	{
		public object Convert(object[] values, Type targetType, object parameter, CultureInfo culture)
		{
			if (values == null)
			{
				return null;
			}
			if (values[0] != null)
			{
				return values[0];
			}
			return (values[1] as FrameworkElement).Parent?.GetValue(MMHelp.HelpFileProperty);
		}

		public object[] ConvertBack(object value, Type[] targetTypes, object parameter, CultureInfo culture)
		{
			throw new NotImplementedException();
		}
	}
	internal class HelpIdConverter : IMultiValueConverter
	{
		public object Convert(object[] values, Type targetType, object parameter, CultureInfo culture)
		{
			if (values == null)
			{
				return null;
			}
			if (values[0] != null && ((values[0] as int?) ?? 0) != 0)
			{
				return values[0];
			}
			return (values[1] as FrameworkElement).Parent?.GetValue(MMHelp.HelpIdProperty);
		}

		public object[] ConvertBack(object value, Type[] targetTypes, object parameter, CultureInfo culture)
		{
			throw new NotImplementedException();
		}
	}
