		public bool? ShowAddChildDialog(string parentPath, out string newChildId, bool silently = false)
		{
			newChildId = null;
			string text = ExpandDataPath(parentPath);
			if (text.EndsWith("Pure Components"))
			{
				CxvActionResult cxvActionResult = InvokeAction("Top.appModelV8.Custom Actions", "gxPure_component_param", false);
				if (cxvActionResult.Succeeded && cxvActionResult.Result is string && !string.IsNullOrEmpty(cxvActionResult.Result.ToString()))
				{
					newChildId = cxvActionResult.Result.ToString();
					UpdateDisplay();
					UpdateAll();
					return true;
				}
				return false;
			}
			object[] array = CreateAddChildDilogData(text);
			if (array == null || array.Length < 4)
			{
				return false;
			}
			string recordType;
			return DisplayAddChildDialog(text, array, out newChildId, out recordType, silently);
		}

		public bool? ShowAddChildDialog(string parentPath, out string newChildId, out string recordType, bool silently = false, bool allowEmptyID = true)
		{
			newChildId = null;
			recordType = null;
			bool? result = false;
			string text = ExpandDataPath(parentPath);
			if (text.EndsWith("Pure Components"))
			{
				CxvActionResult cxvActionResult = InvokeAction("Top.appModelV8.Custom Actions", "gxPure_component_param", false);
				if (cxvActionResult.Succeeded && cxvActionResult.Result is string && !string.IsNullOrEmpty(cxvActionResult.Result.ToString()))
				{
					newChildId = cxvActionResult.Result.ToString();
					UpdateDisplay();
					UpdateAll();
					result = true;
				}
				return result;
			}
			object[] array = CreateAddChildDilogData(text);
			if (array == null || array.Length < 3)
			{
				return false;
			}
			return DisplayAddChildDialog(text, array, out newChildId, out recordType, silently, allowEmptyID);
		}

		private bool? DisplayAddChildDialog(string expandedParentPath, object[] dialogData, out string newChildId, out string recordType, bool silently = false, bool allowEmptyID = true)
		{
			recordType = null;
			newChildId = null;
			OneIdDialog.maskType mask = OneIdDialog.maskType.IS_ID;
			int value = 8;
			string[] optionList = null;
			if (dialogData[0] != null && dialogData[0] != DBNull.Value)
			{
				optionList = CxsConverter.ValueToOptionArray(dialogData[0]);
				if (optionList != null)
				{
					if (optionList.Length == 1)
					{
						recordType = optionList[0];
						optionList = null;
						dialogData[0] = null;
					}
					else if (expandedParentPath.EndsWith("Reactions"))
					{
						int index = -1;
						string[] array = optionList;
						foreach (string obj in array)
						{
							index++;
							if (obj.Equals("USERACM", StringComparison.OrdinalIgnoreCase))
							{
								optionList = optionList.Where((string w) => w != optionList[index]).ToArray();
							}
						}
					}
				}
			}
			bool flag;
			while (true)
			{
				string default_text = CxsConverter.ValueToString(dialogData[2]);
				string text = CxsConverter.ValueToString(dialogData[3]);
				if (text.Equals("NQ Curves", StringComparison.OrdinalIgnoreCase))
				{
					mask = OneIdDialog.maskType.IS_INTEGER;
					value = 3;
				}
				else
				{
					foreach (string item in _HcurvesNode)
					{
						if (item.Equals(text, StringComparison.OrdinalIgnoreCase))
						{
							mask = OneIdDialog.maskType.IS_INTEGER;
							value = 4;
							break;
						}
					}
				}
				OneIdDialog oneIdDialog = new OneIdDialog(base.UnityContainer, CxsConverter.ValueToString(dialogData[1]), default_text, optionList, text, mask, AspenTech.AspenPlus.MMControls.Properties.Resources.strNewChild, value);
				string prompt = string.Empty;
				if (dialogData.Length > 2)
				{
					prompt = CxsConverter.ValueToString(dialogData[1]);
				}
				oneIdDialog.Prompt = prompt;
				if (IsPFSBlkObject(expandedParentPath))
				{
					oneIdDialog.ExistingIds = ExistingIds(expandedParentPath);
					oneIdDialog.PathCheck = expandedParentPath;
					oneIdDialog.Provider = base.ResolvedCxsProvider;
				}
				if (IsSectionObject(expandedParentPath))
				{
					oneIdDialog.ExistingIds = ExistingIds2(expandedParentPath, oneIdDialog.ExistingIds);
					oneIdDialog.PathCheck = expandedParentPath;
					oneIdDialog.Provider = base.ResolvedCxsProvider;
				}
				if (IsRegressionOrReactionsObject(expandedParentPath))
				{
					oneIdDialog.ExistingIds = ExistingIdsRegressionsAndReactions(expandedParentPath, oneIdDialog.ExistingIds);
					oneIdDialog.PathCheck = expandedParentPath;
					oneIdDialog.Provider = base.ResolvedCxsProvider;
				}
				MMHelp.SetHelpFile(oneIdDialog, "plotwiz.chm");
				MMHelp.SetHelpId(oneIdDialog, 113);
				flag = false;
				if (!silently)
				{
					NativeMethods.ShowWindow(oneIdDialog, showAsDialog: true);
					if (oneIdDialog.DialogResult.HasValue && oneIdDialog.DialogResult.Value)
					{
						flag = allowEmptyID || !string.IsNullOrEmpty(oneIdDialog.NewID);
					}
				}
				else
				{
					flag = true;
				}
				if (!flag)
				{
					break;
				}
				string text2 = (newChildId = oneIdDialog.NewID);
				if (dialogData[0] != null && dialogData[0] != DBNull.Value)
				{
					if (oneIdDialog.RecordType == "TERNARY")
					{
						recordType = "TERDIAGRAM";
					}
					else
					{
						recordType = oneIdDialog.RecordType;
					}
				}
				if (recordType != null)
				{
					text2 = text2 + "!" + recordType;
				}
				CxvActionResult cxvActionResult = InvokeAction(expandedParentPath, "InsertChild", base.NotifyUpdates, text2);
				if (cxvActionResult.Succeeded)
				{
					break;
				}
				newChildId = null;
				if (string.IsNullOrEmpty(cxvActionResult.Error))
				{
					break;
				}
