			string text = ExpandDataPath(parentPath);
			object[] array = CreateRenameChildDialogData(text);
			if (array == null || array.Length < 1)
			{
				return false;
			}
			string text2 = CxsConverter.ValueToString(array[0]);
			if (text2.Equals("HCurves", StringComparison.OrdinalIgnoreCase))
			{
				mask = OneIdDialog.maskType.IS_INTEGER;
				value2 = 4;
				prompt = string.Format(AspenTech.AspenPlus.MMControls.Properties.Resources.RenameConfirmPrompt_Number, childId);
			}
			else if (text2.Equals("NQ Curves", StringComparison.OrdinalIgnoreCase))
			{
				mask = OneIdDialog.maskType.IS_INTEGER;
				value2 = 3;
				prompt = string.Format(AspenTech.AspenPlus.MMControls.Properties.Resources.RenameConfirmPrompt_Number, childId);
			}
			OneIdDialog oneIdDialog = new OneIdDialog(base.UnityContainer, prompt, childId, null, mask, AspenTech.AspenPlus.MMControls.Properties.Resources.strRenameChild, value2);
			MMHelp.SetHelpFile(oneIdDialog, "userguide1.chm");
			MMHelp.SetHelpId(oneIdDialog, 446);
