			{
				oneIdDialog.ExistingIds = ExistingIds(text);
				oneIdDialog.PathCheck = text;
				oneIdDialog.Provider = base.ResolvedCxsProvider;
				if (oneIdDialog.ExistingIds != null && childId != null && oneIdDialog.ExistingIds.Contains(childId) && !silently)
				{
					oneIdDialog.ExistingIds.Remove(childId);
				}
			}
			if (IsSectionObject(text))
			{
				oneIdDialog.ExistingIds = ExistingIds2(text, oneIdDialog.ExistingIds);
				oneIdDialog.PathCheck = text;
				oneIdDialog.Provider = base.ResolvedCxsProvider;
				if (oneIdDialog.ExistingIds != null && childId != null && oneIdDialog.ExistingIds.Contains(childId) && !silently)
				{
					oneIdDialog.ExistingIds.Remove(childId);
				}
			}
			if (IsRegressionOrReactionsObject(text))
			{
				oneIdDialog.ExistingIds = ExistingIdsRegressionsAndReactions(text, oneIdDialog.ExistingIds);
				oneIdDialog.PathCheck = text;
				oneIdDialog.Provider = base.ResolvedCxsProvider;
				if (oneIdDialog.ExistingIds != null && childId != null && oneIdDialog.ExistingIds.Contains(childId) && !silently)
				{
					oneIdDialog.ExistingIds.Remove(childId);
				}
			}
			bool flag = false;
			if (!silently)
			{
				NativeMethods.ShowWindow(oneIdDialog, showAsDialog: true);
				flag = oneIdDialog.DialogResult == true;
			}
			else
			{
				flag = oneIdDialog.CheckIfValidId(childId, showErrorAsync: true);
			}
			if (flag)
			{
				base.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<BeforeObjectRenamedEvent>().Publish(new BeforeObjectRenamedEventArgs(childId, oneIdDialog.NewID, text + "." + childId, text + "." + oneIdDialog.NewID));
				CxvActionResult cxvActionResult = InvokeAction(parentPath, "RenameChild", true, childId, oneIdDialog.NewID);
				if (!cxvActionResult.Succeeded && !string.IsNullOrEmpty(cxvActionResult.Error))
				{
					ShowMessageBox(new ShowMessageBoxEventArgs
					{
						Message = cxvActionResult.Error,
						Title = AspenTech.AspenPlus.MMControls.Properties.Resources.strRenameChildFailureTitle,
						MsgBoxButton = MessageBoxButton.OK,
						MsgBoxImage = MessageBoxImage.Asterisk
					});
					value = false;
				}
				else
				{
					childId = oneIdDialog.NewID;
					value = true;
				}
			}
			UpdateDisplay("MMViewModel.ShowRenameChildDialog");
			UpdateAll();
			return value;
		}

