		private CxvActionResult InternalDeleteChild(string parentPath, string childId)
		{
			CxvActionResult cxvActionResult = InvokeAction(parentPath, "DeleteChild", true, childId);
			if (cxvActionResult.Succeeded && !string.IsNullOrEmpty(childId))
			{
				IUnityContainer unityContainer = base.UnityContainer;
				if (unityContainer == null)
				{
					return cxvActionResult;
				}
