		public void ClearChildren(string parentPath, IEnumerable<string> children)
		{
			bool flag = false;
			List<string> list = new List<string>();
			string strConfirmClearChildren = AspenTech.AspenPlus.MMControls.Properties.Resources.strConfirmClearChildren;
			for (int i = 0; i < children.Count(); i++)
			{
				if (flag)
				{
					list.Add(children.ElementAt(i));
					continue;
				}
				strConfirmClearChildren = AspenTech.AspenPlus.MMControls.Properties.Resources.Clear + " " + children.ElementAt(i) + "?";
				ShowMMMessageBoxEventArgs e = new ShowMMMessageBoxEventArgs
				{
					Title = AspenTech.AspenPlus.MMControls.Properties.Resources.Confirm,
					Message = strConfirmClearChildren,
					MsgBoxButton = ((children.Count() == 1) ? 1 : 13),
					MsgBoxImage = 32,
					DialogResult = 5
				};
				ShowMMMessageBox(e);
				if (children.Count() == 1)
				{
					if (e.DialogResult == 1)
					{
						list.Add(children.ElementAt(i));
					}
					continue;
				}
				flag = e.DialogResult == 14;
				bool num = e.DialogResult == 15;
				if (e.DialogResult == 6 || flag)
				{
					list.Add(children.ElementAt(i));
				}
				if (num)
				{
					break;
				}
				if (e.DialogResult == 2)
				{
					list.Clear();
					break;
				}
			}
			if (list.Count <= 0)
			{
				return;
			}
			foreach (string item in list)
			{
				InvokeAction(parentPath, "ClearChild", false, item);
			}
			UpdateDisplay();
			UpdateAll();
		}

