		public virtual int NextHit(out string messages, string[] completionPaths)
		{
			int num = -1;
			messages = null;
			PropertyDescriptorCollection properties = TypeDescriptor.GetProperties(this);
			if (properties != null && properties.Count > 0)
			{
				foreach (PropertyDescriptor item in properties)
				{
					CxvPropertyDeclaration cxvPropertyDeclaration = CxvViewModel.DeclarationFromProperty(item);
					if (cxvPropertyDeclaration != null && GetValue(cxvPropertyDeclaration) is ICxvCompletableObject { IsComplete: false } cxvCompletableObject && cxvCompletableObject.ShowNextIncomplete() == 0)
					{
						return 0;
					}
				}
			}
			if (completionPaths == null)
			{
				num = -1;
			}
			else if (num == -1 && completionPaths != null)
			{
				ICxsDataWatch cxsDataWatch = CreateCxsWatch();
				foreach (string text in completionPaths)
				{
					string dataPath = text;
					if (text[0] != '@')
					{
						dataPath = "@main.CC Nodes." + text;
					}
					string path = ExpandDataPath(dataPath);
					cxsDataWatch.AddWatch(path, "tabstate", "complete");
				}
				object[] values = cxsDataWatch.Values;
				cxsDataWatch = CreateCxsWatch();
				if (values != null)
				{
					int num2 = 0;
					object[] array = values;
					for (int i = 0; i < array.Length; i++)
					{
						bool? flag = CxsConverter.ValueToBoolean(array[i]);
						if (flag.HasValue && !flag.Value)
						{
							string dataPath2 = completionPaths[num2];
							if (completionPaths[num2][0] != '@')
							{
								dataPath2 = "@main.CC Nodes." + completionPaths[num2];
							}
							string path2 = ExpandDataPath(dataPath2);
							cxsDataWatch.AddWatch(path2, "completion_message");
						}
						num2++;
					}
					array = cxsDataWatch.Values;
					for (int i = 0; i < array.Length; i++)
					{
						string text2 = CxsConverter.ValueToString(array[i]);
						if (!string.IsNullOrEmpty(text2))
						{
							num = 0;
							if (messages == null)
							{
								messages = text2;
							}
							else
							{
								messages += text2;
							}
						}
					}
				}
				if (messages == null)
				{
					num = -1;
				}
			}
			return num;
		}

		public virtual bool? CheckComplete(string[] completionPaths)
		{
			if (completionPaths == null)
			{
				return null;
			}
			ICxsDataWatch cxsDataWatch = CreateCxsWatch();
			foreach (string text in completionPaths)
			{
				string dataPath = text;
				if (text[0] != '@')
				{
					dataPath = "@main.CC Nodes." + text;
				}
				string text2 = ExpandDataPath(dataPath);
				if (string.IsNullOrEmpty(text2))
				{
					return false;
				}
				cxsDataWatch.AddWatch(text2, "tabstate", "complete");
			}
			object[] values = cxsDataWatch.Values;
			if (values != null)
			{
				object[] array = values;
				for (int i = 0; i < array.Length; i++)
				{
					bool? flag = CxsConverter.ValueToBoolean(array[i]);
					if (flag.HasValue && !flag.Value)
					{
						return false;
					}
				}
			}
			return true;
		}

		protected string EOVariableNameToCxsPath(string varname)
		{
			if (string.IsNullOrEmpty(varname))
			{
				return null;
