			string text = ExpandDataPath(varname);
			string[] itemMonikers = new string[1] { "!EO Flowsheet!" + text };
			string[] array = base.ResolvedCxsProvider.Case.ConvertMonikersToPaths(itemMonikers);
			if (array == null || array.Count() < 1)
			{
				return null;
			}
			array[0] = array[0].Replace("Top.appModel", "Top.appModelV8");
			return array[0];
		}

