			if (!string.Equals(asiFormatTextFromClipboard, _oldAsiFormatText))
			{
				_oldAsiFormatText = asiFormatTextFromClipboard;
				try
				{
					IList<string> list = ClipboardHelper.ParseCxsPathFromAsiFormat(asiFormatTextFromClipboard, base.ResolvedCxsProvider.Case.CaseFullFilePath, 1);
					_newCanPaste = list != null && list.Count > 0;
				}
				catch (Exception)
				{
