		private void GoToNodeEx(string path, string group)
		{
			string text = ExpandDataPath("@main");
			text = ((!text.Contains("Blocks")) ? text.Replace("Top.appModelV8.", "") : text.Replace("Data.", "").Substring(text.IndexOf("Blocks")));
			text = text.Replace("Subobjects.", "");
			GoToNode($"{group}!{text}.{path.Substring(2)}");
		}

