		public string GetAdsFlowsheetPathForStreamSummaryForms()
		{
			string text = ExpandDataPath("@main");
			if (!text.Contains(".Blocks."))
			{
				return "Flowsheet";
			}
			string text2 = text.Replace(".Data.", ".").Replace("Top.appModelV8.", "").Replace("Top.appModel.", "");
			if (text2.StartsWith("Blocks."))
			{
				text2 = text2.Substring("Blocks.".Length);
			}
			if (text2.Contains(".Streams."))
			{
				int length = text2.IndexOf(".Streams.");
				text2 = text2.Substring(0, length).Replace(".Blocks.", ".");
				return GetAdsFlowsheetPathFromSegments(text2);
			}
			if (text2.Contains(".Results Summary.") || text2.EndsWith(".Results Summary"))
			{
				int length2 = (text2.Contains(".Results Summary.") ? text2.IndexOf(".Results Summary.") : text2.IndexOf(".Results Summary"));
				text2 = text2.Substring(0, length2).Replace(".Blocks.", ".");
				return GetAdsFlowsheetPathFromSegments(text2);
			}
			int num = text2.LastIndexOf(".Blocks.");
			if (num <= 0)
			{
				return "Flowsheet";
			}
			text2 = text2.Substring(0, num).Replace(".Blocks.", ".");
			return GetAdsFlowsheetPathFromSegments(text2);
		}

		private string GetAdsFlowsheetPathFromSegments(string blockSegments)
		{
			if (string.IsNullOrWhiteSpace(blockSegments))
			{
				return "Flowsheet";
			}
			string[] array = blockSegments.Split('.');
			StringBuilder stringBuilder = new StringBuilder("Flowsheet");
			for (int i = 0; i < array.Length; i++)
			{
				stringBuilder.Append(".Blocks.").Append(array[i]).Append(".SubFlowsheets.Simulation");
			}
			return stringBuilder.ToString();
		}

