		public string GetFullBlockName(string mainPath, string blkName)
		{
			string text = CxsConverter.ValueToString(ExpandDataPathAndGet(mainPath, "container"));
			if (string.IsNullOrEmpty(text))
			{
				return blkName;
			}
			string text2 = ExpandDataPath(mainPath).Replace("Top.appModelV8.Blocks.", string.Empty).Replace("Data.Blocks.", string.Empty);
			int length = text2.LastIndexOf(text) + text.Length;
			return text2.Substring(0, length) + "." + blkName;
		}

