				arg.Handled = true;
			}
			base.CVP_PreviewKeyDown(arg);
		}

		private static void DoSetClipboardData(MMScrollArea sa)
		{
			if (sa.ClipboardDataObject != null)
			{
				sa.ClipboardDataObject.Dispose();
			}
			sa.ClipboardDataObject = new DataObjectLateGen();
			sa.ClipboardDataObject.IncludeColumnHeader = sa.DataGrid.SelectedItems.Fields.Count > 0;
			sa.ClipboardDataObject.SetData(typeof(MMScrollArea), sa);
			List<IGridCellData> list = new List<IGridCellData>();
			int num = 0;
			int num2 = -1;
			int num3 = -1;
			if (sa.ClipboardDataObject.IncludeColumnHeader)
			{
				foreach (Field field in sa.DataGrid.SelectedItems.Fields)
				{
					if (field != null)
					{
						string textValue = ((field.Label is LabelHeader labelHeader) ? labelHeader.LabelText : ((field.Label != null) ? field.Label.ToString() : string.Empty));
						CxsGridCellData item = new CxsGridCellData
						{
							TextValue = textValue,
							ColumnIndex = field.Index,
							RowIndex = 0
						};
						list.Add(item);
						num2 = 0;
					}
				}
			}
			foreach (MMScrollAreaSelectedCell item3 in sa.ClipboardDataObject.SelectedCellsSorted)
			{
				int num4 = item3.Record.DisplayIndex;
				if (sa.ClipboardDataObject.IncludeColumnHeader)
				{
					num4++;
				}
				int index = item3.Field.Field.Index;
				if (num2 == -1 || num4 < num2)
				{
					num2 = num4;
				}
				if (num3 == -1 || index < num3)
				{
					num3 = index;
				}
				bool flag = false;
				if (item3.Field != null)
				{
					flag = item3.Field.GetType() == typeof(MMScrollAreaTextField);
				}
				CxsGridCellData item2 = new CxsGridCellData
				{
					Moniker = (flag ? string.Empty : sa.ClipboardDataObject.GetCellMoniker(item3)),
					RowIndex = num4,
					ColumnIndex = index,
					TextValue = sa.ClipboardDataObject.GetCellValue(item3)
				};
				list.Add(item2);
				num++;
			}
			foreach (IGridCellData item4 in list)
			{
				item4.RowIndex -= num2;
				item4.ColumnIndex -= num3;
			}
			if (num > 1)
			{
				foreach (IGridCellData item5 in list)
				{
					int rowIndex = item5.RowIndex;
					int columnIndex = item5.ColumnIndex;
					item5.RowIndex = columnIndex;
					item5.ColumnIndex = rowIndex;
				}
			}
			ClipboardHelper.CreateClipboard(list, sa.ClipboardDataObject.Value, sa.ClipboardDataObject.CaseFullFileName, sa.ClipboardDataObject.ApplicationName);
		}

		protected override void DataGrid_Loaded(object sender, RoutedEventArgs e)
		{
			base.DataGrid_Loaded(sender, e);
			base.DataGrid.BindToSampleData = false;
			_isDataGridLoaded = true;
			base.IsKeyboardFocusWithinChanged += MMHorizontalListEdit_IsKeyboardFocusWithinChanged;
			base.PreviewLostKeyboardFocus += MMHorizontalListEdit_PreviewLostKeyboardFocus;
			if (base.CopyCommand == null)
			{
				base.CopyCommand = HorizontalListEditCopyCommnad;
			}
		}

		private void MMHorizontalListEdit_PreviewLostKeyboardFocus(object sender, KeyboardFocusChangedEventArgs e)
		{
			if (e.NewFocus is ContextMenu)
			{
				foreach (Cell cell in base.DataGrid.SelectedItems.Cells)
				{
					CellValuePresenter cellValuePresenter = CellValuePresenter.FromCell(cell);
					if (cellValuePresenter != null)
					{
						System.Windows.Point position = Mouse.GetPosition(cellValuePresenter);
						if (position.X <= cellValuePresenter.ActualWidth && position.Y <= cellValuePresenter.ActualHeight && position.X >= 0.0 && position.Y >= 0.0)
						{
							shouldClearSelection = false;
						}
					}
				}
			}
			else if (e.NewFocus is MenuItem)
			{
				shouldClearSelection = false;
			}
			if (shouldClearSelection)
			{
				_lastSelectedCell = base.DataGrid.SelectedItems.Cells.Cast<Cell>().FirstOrDefault();
			}
			else
			{
				_lastSelectedCell = null;
			}
			base.OnPreviewLostKeyboardFocus(e);
		}

		private void MMHorizontalListEdit_IsKeyboardFocusWithinChanged(object sender, DependencyPropertyChangedEventArgs e)
		{
			if (!(bool)e.NewValue && shouldClearSelection && IsEqualCells(base.DataGrid.SelectedItems.Cells.Cast<Cell>().FirstOrDefault(), _lastSelectedCell))
			{
				ClearSelection();
				_lastSelectedCell = null;
			}
			shouldClearSelection = true;
		}

		private static bool IsEqualCells(Cell first, Cell second)
		{
			if (first == null && second == null)
			{
				return true;
			}
			if (first == null || second == null)
			{
				return false;
			}
			if (first == second)
			{
				return true;
			}
			if (first.Field == second.Field)
			{
				return first.Record == second.Record;
			}
			return false;
		}

		public override void OnApplyTemplate()
		{
			base.OnApplyTemplate();
			_btnScrollLeft = GetTemplateChild("PART_ScrollLeft") as RepeatButton;
			_btnScrollRight = GetTemplateChild("PART_ScrollRight") as RepeatButton;
			_btnSelectAll = GetTemplateChild("PART_SelectAll") as Button;
			_btnSelectAll.Click += _btnSelectAll_Click;
			SetDataBinding();
		}

		protected override void OnDataPropertyChanged(object newValue)
		{
			base.OnDataPropertyChanged(newValue);
			SetDataBinding();
		}

		protected override void Records_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			if (e.Action == NotifyCollectionChangedAction.Reset)
			{
				if (_currentEditor != null && _currentEditor.IsInEditMode)
				{
					_currentEditor.EndEditMode(acceptChanges: true, force: true);
				}
				_isJustReset = true;
			}
		}

		protected override void DataGrid_RecordsInViewChanged(object sender, RecordsInViewChangedEventArgs e)
		{
			if (!base.IsMMEnabled)
			{
				return;
			}
			IsScrollLeftRightButtonVisible = base.DataGrid.ScrollInfo.ScrollOwner.ExtentWidth > base.DataGrid.ScrollInfo.ScrollOwner.ViewportWidth;
			if (!_isJustReset || (base.LastKeyPressed != Key.Return && base.LastKeyPressed != Key.Tab))
			{
				return;
			}
			if (recordsCount >= base.DataGrid.Records.Count)
			{
				int num = Math.Min(base.DataGrid.Records.Count - 1, base.CurrentActivePosition.RecordId);
				int num2 = Math.Min(base.DataGrid.DefaultFieldLayout.Fields.Count - 1, base.CurrentActivePosition.FieldId);
				if (num >= 0 && num2 >= 0)
				{
					base.DataGrid.ActiveCell = (base.DataGrid.Records[num] as DataRecord).Cells[num2];
				}
			}
			else if (_isDataGridLoaded && base.CurrentActivePosition.RecordId >= 0 && base.DataGrid.Records != null && base.DataGrid.Records.Count > 0 && (base.CurrentActivePosition.RecordId == base.DataGrid.Records.Count - 2 || base.CurrentActivePosition.RecordId == 0))
			{
				base.SuppressPreviewGotKeyboardFocus = true;
				base.DataGrid.ActiveCell = (base.DataGrid.Records[base.DataGrid.Records.Count - 1] as DataRecord).Cells[0];
				if (base.DataGrid.ActiveCell != null)
				{
					try
					{
						base.DataGrid.ActiveCell.IsSelected = true;
						base.DataGrid.BringCellIntoView(base.DataGrid.ActiveCell);
					}
					catch (Exception)
					{
					}
				}
				base.SuppressPreviewGotKeyboardFocus = false;
			}
			recordsCount = base.DataGrid.Records.Count;
			base.DataGrid.SelectedItems.Cells.Clear();
			_isJustReset = false;
		}

		internal override void ClearSelectedCells(bool cellOnly)
		{
			ValueEditor activeEditor = GetActiveEditor();
			if (activeEditor != null && activeEditor.IsInEditMode)
			{
				return;
			}
			CxsDataProvider resolvedCxsProvider = (base.DataContext as CxvViewModel).ResolvedCxsProvider;
			resolvedCxsProvider?.SuspendNotifications();
			try
			{
				if (base.DataGrid.ActiveCell != null)
				{
					base.DataGrid.ActiveCell.IsSelected = true;
				}
				foreach (int item in (from Cell c in base.DataGrid.SelectedItems.Cells.Cast<Cell>()
					orderby c.Record.Index descending
					select c.Record.Index).ToList())
				{
					DoClearCell((base.DataGrid.Records[item] as DataRecord).Cells[0]);
				}
			}
			catch (Exception)
			{
			}
			finally
			{
				resolvedCxsProvider?.ResumeNotifications();
			}
		}

		private void _btnSelectAll_Click(object sender, RoutedEventArgs e)
		{
			DoSelectAll();
		}

		private void SetDataBinding()
		{
			if (base.DataGrid != null && !string.IsNullOrEmpty(base.DataProperty))
			{
				base.CommandBindings.Add(new CommandBinding(MMScrollAreaCommand.ScrollLeftCommand, MMScrollAreaCommand.OnScrollLeftCommand));
				base.CommandBindings.Add(new CommandBinding(MMScrollAreaCommand.ScrollRightCommand, MMScrollAreaCommand.OnScrollRightCommand));
			}
		}
	}
