					{
						return null;
					}
					CxvChildCountIndexBasisData cxvChildCountIndexBasisData = cxvVectorPropertyData.IndexBasis as CxvChildCountIndexBasisData;
					string text = "";
					if (cxvChildCountIndexBasisData != null && base.DataContext is MMViewModel mMViewModel)
					{
						text = mMViewModel.ExpandDataPath(cxvChildCountIndexBasisData.IndexBasis.DataPath, null);
					}
					string formProgId = GetFormProgId();
					if (formProgId == null)
					{
						return null;
					}
					if (base.Name == null)
					{
						return null;
					}
					_CustomizationKey = formProgId + "/" + base.Name + "/" + text;
				}
				return _CustomizationKey;
			}
		}

		bool IMMScrollAreaPlot.HasVisibleFieldsToCreatePlot
		{
			get
			{
				int num = 0;
				if (base.DataGrid.Records.Count > 1)
				{
					foreach (Field @field in base.DataGrid.DefaultFieldLayout.Fields)
					{
						if (@field.VisibilityResolved != Visibility.Visible)
						{
							continue;
						}
						object value = (base.DataGrid.Records[0] as DataRecord).Cells[@field].Value;
						bool flag = false;
						if (value == null)
						{
							for (int i = 1; i < base.DataGrid.Records.Count; i++)
							{
								value = (base.DataGrid.Records[i] as DataRecord).Cells[@field].Value;
								if (value != null)
								{
									flag = true;
									break;
								}
							}
						}
						else
						{
							flag = true;
						}
						if (flag && double.TryParse(value.ToString(), out var _))
						{
							num++;
							if (num > 1)
							{
								return true;
							}
						}
					}
				}
				return false;
			}
		}

		bool IMMScrollAreaPlot.HasSelectedFields
		{
			get
			{
				if (base.DataGrid != null && base.DataGrid.Visibility == Visibility.Visible)
				{
					if (base.DataGrid.SelectedItems.Cells.Count > 0)
					{
						foreach (Cell cell in base.DataGrid.SelectedItems.Cells)
						{
							if (cell.Field.VisibilityResolved == Visibility.Visible && cell.Record.VisibilityResolved == Visibility.Visible && cell.Field.CellContentAlignmentResolved != CellContentAlignment.LabelOnly)
							{
								return true;
							}
						}
					}
					else if (base.DataGrid.SelectedItems.Fields.Count > 0)
					{
						foreach (Field @field in base.DataGrid.SelectedItems.Fields)
						{
							if (@field.VisibilityResolved == Visibility.Visible && @field.CellContentAlignmentResolved != CellContentAlignment.LabelOnly)
							{
								return true;
							}
						}
					}
				}
				return false;
			}
		}

