		internal static void OnControlInHeaderLoaded(object sender, RoutedEventArgs arg)
		{
			if (sender != null && sender is FrameworkElement frameworkElement && Infragistics.Windows.Utilities.GetAncestorFromType(frameworkElement, typeof(LabelPresenter), allowSubclassOfType: false) is LabelPresenter labelPresenter && Infragistics.Windows.Utilities.GetAncestorFromType(labelPresenter.DataPresenter, typeof(MMScrollArea), allowSubclassOfType: false) is MMScrollArea mMScrollArea)
			{
				if (!mMScrollArea.ControlInColumnHeader.ContainsKey(labelPresenter))
				{
					mMScrollArea.ControlInColumnHeader.Add(labelPresenter, new List<FrameworkElement>());
				}
				if (!mMScrollArea.ControlInColumnHeader[labelPresenter].Contains(frameworkElement))
				{
					mMScrollArea.ControlInColumnHeader[labelPresenter].Add(frameworkElement);
				}
			}
		}

		private static int GetTagId(object tag)
		{
			if (tag == null)
			{
				return int.MaxValue;
			}
			if (int.TryParse(tag.ToString(), out var result))
			{
				return result;
			}
			return int.MaxValue;
		}

		internal static void OnControlInHeaderPreviewKeyDown(object sender, KeyEventArgs arg)
		{
			if (arg.Key != Key.Tab || sender == null || !(sender is FrameworkElement frameworkElement) || !(Infragistics.Windows.Utilities.GetAncestorFromType(frameworkElement, typeof(LabelPresenter), allowSubclassOfType: false) is LabelPresenter labelPresenter) || !(Infragistics.Windows.Utilities.GetAncestorFromType(labelPresenter.DataPresenter, typeof(MMScrollArea), allowSubclassOfType: false) is MMScrollArea mMScrollArea))
			{
				return;
			}
			mMScrollArea.ClearSelection();
			mMScrollArea.DataGrid.ActiveCell = null;
			mMScrollArea.RefreshContrlInHeader();
			bool flag = (Keyboard.Modifiers & ModifierKeys.Shift) != ModifierKeys.Shift;
			FrameworkElement frameworkElement2 = null;
			if (mMScrollArea.ControlInColumnHeader.ContainsKey(labelPresenter))
			{
				frameworkElement2 = GetNextControlToFocus(frameworkElement, mMScrollArea.ControlInColumnHeader[labelPresenter], flag);
			}
			if (frameworkElement2 != null || flag)
			{
				mMScrollArea._isFocusingToColumnHeader = true;
				mMScrollArea.LastKeyPressed = arg.Key;
				mMScrollArea.CurrentActivePosition = new CellLocation((frameworkElement2 != null) ? GetTagId(frameworkElement2.Tag) : 0, labelPresenter.Field.ActualPosition.Column);
				if (frameworkElement2 == null)
				{
					FocusToNextColumn(arg, labelPresenter, mMScrollArea, flag);
				}
				else
				{
					FocusControlInHeaderAndStartEdit(frameworkElement2, arg);
				}
			}
		}

		internal static void OnControlInHeaderPreviewMouseDown(object sender, MouseButtonEventArgs arg)
		{
			if (sender is MMComboEdit mMComboEdit && Infragistics.Windows.Utilities.GetAncestorFromType(mMComboEdit, typeof(LabelPresenter), allowSubclassOfType: false) is LabelPresenter labelPresenter && Infragistics.Windows.Utilities.GetAncestorFromType(labelPresenter.DataPresenter, typeof(MMScrollArea), allowSubclassOfType: false) is MMScrollArea mMScrollArea)
			{
				mMScrollArea.ClearSelection();
				mMScrollArea.DataGrid.ActiveCell = null;
				mMScrollArea.RefreshContrlInHeader();
				mMScrollArea._isFocusingToColumnHeader = true;
				mMScrollArea.CurrentActivePosition = new CellLocation(GetTagId(mMComboEdit.Tag), labelPresenter.Field.ActualPosition.Column);
			}
		}

		private static FrameworkElement GetNextControlToFocus(FrameworkElement currentControl, List<FrameworkElement> controlsInHeader, bool tabForward)
		{
			FrameworkElement result = null;
			int currentControlId = -1;
			if (currentControl != null)
			{
				currentControlId = GetTagId(currentControl.Tag);
			}
			else if (!tabForward)
			{
				currentControlId = int.MaxValue;
			}
			IOrderedEnumerable<FrameworkElement> orderedEnumerable = null;
			orderedEnumerable = ((!tabForward) ? (from ctl in controlsInHeader
				where GetTagId(ctl.Tag) < currentControlId
				orderby GetTagId(ctl.Tag) descending
				select ctl) : (from ctl in controlsInHeader
				where GetTagId(ctl.Tag) > currentControlId
				orderby GetTagId(ctl.Tag)
				select ctl));
			List<FrameworkElement> list = orderedEnumerable.ToList();
			if (list != null && list.Count > 0)
			{
				result = list[0];
			}
			return result;
		}

		private void RefreshContrlInHeader()
		{
			List<LabelPresenter> list = ControlInColumnHeader.Keys.ToList();
			int num = 0;
			while (num < list.Count)
			{
				if (Infragistics.Windows.Utilities.GetAncestorFromType(list[num], typeof(MMScrollArea), allowSubclassOfType: false) == null)
				{
					ControlInColumnHeader.Remove(list[num]);
					list.RemoveAt(num);
				}
				else
				{
					num++;
				}
			}
		}

		private static void FocusToNextColumn(KeyEventArgs arg, LabelPresenter lp, MMScrollArea sa, bool tabForward)
		{
			IOrderedEnumerable<LabelPresenter> orderedEnumerable = null;
			orderedEnumerable = ((!tabForward) ? (from labelPresenter in sa.ControlInColumnHeader.Keys
				where labelPresenter.Field.ActualPosition.Column < lp.Field.ActualPosition.Column
				orderby labelPresenter.Field.ActualPosition.Column descending
				select labelPresenter) : (from labelPresenter in sa.ControlInColumnHeader.Keys
				where labelPresenter.Field.ActualPosition.Column > lp.Field.ActualPosition.Column
				orderby labelPresenter.Field.ActualPosition.Column
				select labelPresenter));
			List<LabelPresenter> list = orderedEnumerable.ToList();
			if (list != null && list.Count > 0)
			{
				LabelPresenter key = list[0];
				if (sa.ControlInColumnHeader[key].Count > 0)
				{
					FocusControlInHeaderAndStartEdit(GetNextControlToFocus(null, sa.ControlInColumnHeader[key], tabForward), arg);
				}
			}
			else if (sa.DataGrid.Records.Count > 0)
			{
				DataRecord dataRecord = sa.DataGrid.Records[0] as DataRecord;
				if (dataRecord.Cells.Count > 0)
				{
					dataRecord.Cells[0].IsActive = true;
					sa.MoveToNextCell(2, startWithCurrentActiveCell: true);
					arg.Handled = true;
				}
			}
		}

		private static void FocusControlInHeaderAndStartEdit(FrameworkElement controlToFocus, KeyEventArgs arg)
		{
			if (!controlToFocus.IsKeyboardFocusWithin)
			{
				controlToFocus.Focus();
			}
			if (Infragistics.Windows.Utilities.GetDescendantFromType(controlToFocus, typeof(ValueEditor), allowSubclassOfType: true) is ValueEditor valueEditor)
			{
				valueEditor.StartEditMode();
			}
			if (arg != null)
			{
				arg.Handled = true;
			}
		}

		protected override void RestoreActivePositionAfterReset(bool shouldStartEditMode)
		{
			if (base.DataOrientation == Orientation.Horizontal)
			{
				return;
			}
			if (_isFocusingToColumnHeader)
			{
				_isFocusingToColumnHeader = false;
				RefreshContrlInHeader();
				int targetFieldId = base.CurrentActivePosition.FieldId;
				if (base.LastKeyPressed == Key.Tab && base.CurrentActivePosition.RecordId == 0)
				{
					targetFieldId++;
				}
				LabelPresenter labelPresenter = ControlInColumnHeader.Keys.Where((LabelPresenter lp) => lp.Field.ActualPosition.Column == targetFieldId).FirstOrDefault();
				if (labelPresenter != null)
				{
					FrameworkElement frameworkElement = ControlInColumnHeader[labelPresenter].Where((FrameworkElement ctl) => GetTagId(ctl.Tag) == base.CurrentActivePosition.RecordId).FirstOrDefault();
					if (frameworkElement != null)
					{
						FocusControlInHeaderAndStartEdit(frameworkElement, null);
					}
				}
			}
			else if (base.ContainsHierachy && base.CurrentActivePosition.ParentRecord != null)
			{
				if (base.LastKeyPressed == Key.Tab)
				{
					base.CurrentActivePosition.FieldId++;
				}
				else
				{
					if (base.LastKeyPressed != Key.Return)
					{
						return;
					}
					base.CurrentActivePosition.RecordId++;
				}
				if (base.DataGrid.Records.Contains(base.CurrentActivePosition.ParentRecord.ParentRecord) && base.CurrentActivePosition.ParentRecord.ChildRecords.Count > base.CurrentActivePosition.RecordId)
				{
					DataRecord dataRecord = base.CurrentActivePosition.ParentRecord.ChildRecords[base.CurrentActivePosition.RecordId] as DataRecord;
					if (dataRecord.Cells.Count > base.CurrentActivePosition.FieldId)
					{
						dataRecord.Cells[base.CurrentActivePosition.FieldId].IsActive = true;
					}
				}
			}
			else
			{
				base.RestoreActivePositionAfterReset(shouldStartEditMode);
			}
		}

		protected override bool TabToColumnHeader()
		{
			LabelPresenter labelPresenter = null;
			foreach (KeyValuePair<LabelPresenter, List<FrameworkElement>> item in ControlInColumnHeader)
			{
				if (labelPresenter == null)
				{
					labelPresenter = item.Key;
				}
				else if (item.Key.Field.ActualPosition.Column > labelPresenter.Field.ActualPosition.Column)
				{
					labelPresenter = item.Key;
				}
			}
			if (labelPresenter == null)
			{
				return false;
			}
			FrameworkElement frameworkElement = ControlInColumnHeader[labelPresenter].OrderByDescending((FrameworkElement ctl) => GetTagId(ctl.Tag)).FirstOrDefault();
			if (frameworkElement == null)
			{
				return false;
			}
			FocusControlInHeaderAndStartEdit(frameworkElement, null);
			return true;
		}

		private static void SelectedColumnSetChanged(DependencyObject d, DependencyPropertyChangedEventArgs args)
		{
			(d as MMScrollArea).SetSelectedColumnSet();
		}

		private void SetSelectedColumnSet()
		{
			if (base.DataGrid.DefaultFieldLayout.Fields.Count <= 0 || SelectedColumnSet == null)
			{
				return;
			}
			string[] array = null;
			if (!string.IsNullOrEmpty(SelectedColumnSet.FieldNames))
			{
				array = SelectedColumnSet.FieldNames.Split(',');
				foreach (MMScrollAreaField mMField in MMFields)
				{
					mMField.IsVisible = false;
				}
				int num = 0;
				string[] array2 = array;
				foreach (string colName in array2)
				{
					MMScrollAreaField mMScrollAreaField = MMFields.Where((MMScrollAreaField p) => p.FieldName == colName).FirstOrDefault();
					if (mMScrollAreaField != null && mMScrollAreaField.IsUsed)
					{
						mMScrollAreaField.IsVisible = true;
						mMScrollAreaField.Field.Column = num;
						num++;
					}
					else if (mMScrollAreaField != null && !mMScrollAreaField.IsUsed)
					{
						mMScrollAreaField.IsVisible = false;
						if (mMScrollAreaField.Field != null)
						{
							mMScrollAreaField.Field.Column = num;
							num++;
						}
					}
				}
				return;
			}
			int num2 = 0;
			foreach (MMScrollAreaField mMField2 in MMFields)
			{
				if (mMField2.IsUsed)
				{
					mMField2.IsVisible = true;
					if (mMField2.Field != null)
					{
						mMField2.Field.Column = num2;
						num2++;
					}
				}
			}
		}

		public void SaveLayout()
		{
			using FileStream stream = new FileStream(GetLayoutFilePath(), FileMode.Create, FileAccess.Write);
			base.DataGrid.SaveCustomizations(stream);
		}

		public bool LoadLayout()
		{
			string layoutFilePath = GetLayoutFilePath();
			if (File.Exists(layoutFilePath))
			{
				using (FileStream stream = new FileStream(layoutFilePath, FileMode.Open, FileAccess.Read))
				{
					base.DataGrid.LoadCustomizations(stream);
				}
				return true;
			}
			return false;
		}

