		private void Fields_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			foreach (Field field in base.DataGrid.SelectedItems.Fields)
			{
				if (!(GetLinkedMMField(field) is MMScrollAreaHeaderOnlyField mMScrollAreaHeaderOnlyField))
				{
					continue;
				}
				foreach (MMScrollAreaField mMField in mMScrollAreaHeaderOnlyField.MMFields)
				{
					if (!mMField.Field.IsSelected)
					{
						mMField.Field.IsSelected = true;
					}
				}
			}
		}

		private void DataGrid_FieldChooserOpening(object sender, FieldChooserOpeningEventArgs e)
		{
			e.FieldChooser.FieldFilters.Clear();
			Predicate<FieldItem> filter = delegate(FieldItem field)
			{
				if (field.IsFixed)
				{
					return false;
				}
				MMScrollAreaField linkedMMField = GetLinkedMMField(field as Field);
				return linkedMMField == null || !string.IsNullOrEmpty(linkedMMField.Label) || !string.IsNullOrEmpty(linkedMMField.HeaderTypeProperty);
			};
			FieldChooserFilter item = new FieldChooserFilter("emptyLabel", filter, "Fields with label");
			e.FieldChooser.FieldFilters.Add(item);
			e.FieldChooser.CurrentFieldGroup = e.FieldChooser.FieldGroups[e.FieldChooser.FieldGroups.Count - 1];
			e.FieldChooser.FieldGroupSelectorVisibility = Visibility.Collapsed;
		}

		private void DataGrid_AssigningFieldLayoutToItem(object sender, AssigningFieldLayoutToItemEventArgs e)
		{
			if (!base.ContainsHierachy)
			{
				return;
			}
			string name = e.Item.GetType().Name;
			foreach (FieldLayout fieldLayout in base.DataGrid.FieldLayouts)
			{
				if (fieldLayout.Key.ToString() == name)
				{
					e.FieldLayout = fieldLayout;
					break;
				}
			}
		}

		protected override void CVP_PreviewKeyDown(KeyEventArgs arg)
		{
			_isFocusingToColumnHeader = false;
			base.LastKeyPressed = arg.Key;
			if (!ShouldCVPRespondKeyDown(arg))
			{
				return;
			}
			if (arg.Key == Key.Delete)
			{
				if (base.DataGrid.SelectedItems.Records.Count > 0 && base.DataGrid.RecordManager.DataSourceAllowsDelete)
				{
					MMScrollAreaCommand.DoDeleteRecord(this, deleteAsColumn: false);
					arg.Handled = true;
					return;
				}
				if (base.DataGrid.SelectedItems.Fields.Count > 0 && CanDeleteSelectedField())
				{
					DeleteSelectedField();
					arg.Handled = true;
					return;
				}
			}
			base.CVP_PreviewKeyDown(arg);
			if (arg.Handled)
			{
				return;
			}
			switch (arg.Key)
			{
			case Key.C:
				if ((Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control)
				{
					MMScrollAreaCommand.SetClipboardData(this);
					arg.Handled = true;
				}
				break;
			case Key.V:
				if ((Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control)
				{
					MMScrollAreaCommand.PasteCommand.Execute(this, this);
					arg.Handled = true;
				}
				break;
			}
		}

		protected override void DataGrid_PreviewKeyDown(object sender, KeyEventArgs e)
		{
			if (!ShouldDataGridRespondKeyDown(e))
			{
				return;
			}
			switch (e.Key)
			{
			case Key.C:
				if ((Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control)
				{
					MMScrollAreaCommand.SetClipboardData(this);
					e.Handled = true;
				}
				break;
			case Key.V:
				if ((Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control)
				{
					MMScrollAreaCommand.DoPaste(this);
					e.Handled = true;
				}
				break;
			case Key.Delete:
				if (base.DataGrid.SelectedItems.Records.Count > 0 && base.DataGrid.RecordManager.DataSourceAllowsDelete)
				{
					MMScrollAreaCommand.DoDeleteRecord(this, deleteAsColumn: false);
					e.Handled = true;
				}
				else if (base.DataGrid.SelectedItems.Fields.Count > 0 && CanDeleteSelectedField())
				{
					DeleteSelectedField();
				}
				else
				{
					ClearSelectedCells(cellOnly: false);
				}
				break;
			}
			if (!e.Handled)
			{
				base.DataGrid_PreviewKeyDown(sender, e);
			}
		}

