		private void SetFieldLayoutSetting(FieldLayout fl)
		{
			if (fl.Settings == null)
			{
				fl.Settings = new FieldLayoutSettings();
			}
			fl.Settings.AutoGenerateFields = false;
			fl.Settings.AutoArrangeCells = AutoArrangeCells.Never;
			fl.Settings.FixedFieldUIType = FixedFieldUIType.None;
			fl.Settings.FixedRecordUIType = FixedRecordUIType.Button;
			fl.Settings.FixedRecordSortOrder = FixedRecordSortOrder.FixOrder;
			fl.Settings.AllowFieldMoving = (AllowUserMovingField ? AllowFieldMoving.WithinLogicalRow : AllowFieldMoving.No);
			fl.Settings.SelectionTypeField = SelectionType.ExtendedAutoDrag;
			if (base.IsBoundToPlainDataSource)
			{
				fl.Settings.AllowClipboardOperations = AllowClipboardOperations.Copy;
				fl.Settings.CopyFieldLabelsToClipboard = true;
			}
			fl.Settings.FilterUIType = FilterUIType.LabelIcons;
			fl.Settings.DataRecordSizingMode = DataRecordSizingMode.Fixed;
			if (base.DataOrientation == Orientation.Horizontal)
			{
				fl.Settings.HighlightAlternateRecords = false;
				fl.Settings.DataRecordSizingMode = DataRecordSizingMode.IndividuallySizable;
			}
		}

