		private void DataGrid_CellChanged(object sender, CellChangedEventArgs e)
		{
			if (_resettingValue)
			{
				return;
			}
			bool flag = false;
			if (e.Cell.Field.EditorTypeResolved == typeof(AesXamComboEdit))
			{
				CellValuePresenter cellValuePresenter = CellValuePresenter.FromCell(e.Cell);
				if (cellValuePresenter != null && cellValuePresenter.Editor is AesXamComboEdit aesXamComboEdit)
				{
					flag = aesXamComboEdit.IsDropDownOpen;
				}
			}
			else if (e.Cell.Field.EditorTypeResolved == typeof(AesXamCheckEdit))
			{
				flag = true;
			}
			if (!flag)
			{
				return;
			}
			object value = e.Cell.Value;
			int index = e.Cell.Record.Index;
			if (index < 0)
			{
				return;
			}
			int column = ((base.DataOrientation == Orientation.Vertical) ? e.Cell.Field.ActualPosition.Column : e.Cell.Field.ActualPosition.Row);
			e.Cell.Value = e.Editor.Value;
			bool flag2 = e.Editor.IsInEditMode;
			Cell cell = null;
			if (base.ContainsHierachy)
			{
				cell = e.Cell;
			}
			else
			{
				cell = (base.DataGrid.Records[index] as DataRecord).Cells.Where((Cell cell2) => column == ((base.DataOrientation == Orientation.Vertical) ? cell2.Field.ActualPosition.Column : cell2.Field.ActualPosition.Row)).FirstOrDefault();
				if (cell == null)
				{
					cell = e.Cell;
				}
			}
			if (CxvHelpers.ValuesEquivalent(cell.Value, value))
			{
				_resettingValue = true;
				e.Editor.Value = cell.Value;
				_resettingValue = false;
				if (e.Cell.Field.EditorTypeResolved == typeof(AesXamComboEdit))
				{
					flag2 = false;
					try
					{
						AesXamComboEdit cEdit = e.Editor as AesXamComboEdit;
						if (cEdit != null && cEdit.Value != null && cEdit.Value.GetType() == typeof(string) && cEdit.ItemsSource != null)
						{
							int num = 0;
							foreach (object item in cEdit.ItemsSource)
							{
								if (item == null || !(item.GetType() == typeof(string)) || !(cEdit.Value.ToString() == item.ToString()))
								{
									num++;
									continue;
								}
								break;
							}
							if (cEdit.SelectedIndex != num)
							{
								cEdit.SelectedIndex = num;
							}
							if (cEdit.SelectedItem != null && cEdit.SelectedItem.GetType() == typeof(string) && cEdit.SelectedItem.ToString() != cEdit.Value.ToString())
							{
								base.Dispatcher.BeginInvoke(DispatcherPriority.Loaded, (Action)delegate
								{
									if (!CxvHelpers.ValuesEquivalent(cEdit.SelectedItem, cEdit.Value))
									{
										cEdit.SelectedItem = cEdit.Value;
									}
								});
							}
						}
					}
					catch (Exception)
					{
					}
				}
			}
			if (e.Cell.Field.EditorTypeResolved == typeof(AesXamComboEdit))
			{
				AesXamComboEdit aesXamComboEdit2 = e.Editor as AesXamComboEdit;
				if (!aesXamComboEdit2.IsDropDownOpen || aesXamComboEdit2.IsEditable)
				{
					flag2 = false;
				}
				if (e.Cell != cell)
				{
					flag2 = false;
				}
			}
			if (flag2)
			{
				e.Editor.EndEditMode(acceptChanges: true, force: false);
			}
		}

		private string GetPropPath(MMScrollAreaSelectedCell cell)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(DataProperty).Append("[").Append(cell.Record.Index.ToString(CultureInfo.InvariantCulture))
				.Append("]");
			if (!string.IsNullOrEmpty(cell.Field.PropertyPath))
			{
				stringBuilder.Append(".").Append(cell.Field.PropertyPath);
			}
			return stringBuilder.ToString();
		}

		private void PlotVariablesFromSelection(List<object> selection)
		{
			List<MMScrollAreaSelectedCell> list = new List<MMScrollAreaSelectedCell>();
			CollectSelectedCellFromRecords(list);
			CollectSelectedCellFromCells(list);
			CollectSelectedCellFromFields(list);
			selection.Clear();
			if (list.Count < 2 || !(base.DataContext is CxvViewModel container))
			{
				return;
			}
			int num = -1;
			foreach (MMScrollAreaSelectedCell item in list)
			{
				Type type = item.Field.GetType();
				if (type == typeof(MMScrollAreaTextField))
				{
					continue;
				}
				if (type == typeof(MMScrollAreaComboValueField))
				{
					if (container.ResolveViewPropertyPath(GetPropPath(item)) is CxvVariableData cxvVariableData && item.Field is MMScrollAreaComboValueField mMScrollAreaComboValueField)
					{
						num++;
						selection.Add(new PlotVariableDescriptor
						{
							Path = cxvVariableData.DataPath,
							CurrentValue = cxvVariableData.Value,
							ExposeAs = CxvVariableTypeCode.Real,
							Column = ((mMScrollAreaComboValueField.Field == null) ? (-1) : mMScrollAreaComboValueField.Field.Column),
							Location = num,
							Dimension = cxvVariableData.Dimension,
							Units = cxvVariableData.Units
						});
					}
				}
				else if (!(type == typeof(MMScrollAreaBasisField)) && !(type == typeof(MMScrollAreaUnitsField)) && item.Field is MMScrollAreaValueField mMScrollAreaValueField && (string.IsNullOrEmpty(mMScrollAreaValueField.VariableDataMember) || mMScrollAreaValueField.VariableDataMember == "Value"))
				{
					object obj = container.ResolveViewPropertyPath(GetPropPath(item));
					if (obj is CxvVariableData cxvVariableData2)
					{
						num++;
						selection.Add(new PlotVariableDescriptor
						{
							Path = cxvVariableData2.DataPath,
							CurrentValue = cxvVariableData2.Value,
							ExposeAs = cxvVariableData2.ResolvedExposeAs,
							Column = ((mMScrollAreaValueField.Field == null) ? (-1) : mMScrollAreaValueField.Field.Column),
							Location = num,
							Dimension = cxvVariableData2.Dimension,
							Units = cxvVariableData2.Units
						});
					}
					else if (obj is CxvManualVariableData { Path: not null } cxvManualVariableData)
					{
						num++;
						selection.Add(new PlotVariableDescriptor
						{
							Path = cxvManualVariableData.Path,
							CurrentValue = cxvManualVariableData.Value,
							ExposeAs = CxvVariableTypeCode.Real,
							Column = ((mMScrollAreaValueField.Field == null) ? (-1) : mMScrollAreaValueField.Field.Column),
							Location = num
						});
					}
				}
			}
		}

		private void EnsurePlotValue()
		{
			if (_plotValues == null && base.DataContext is CxvViewModel cxvViewModel)
