		private void SetupSortedFields()
		{
			if (base.DataGrid.DefaultFieldLayout.SortedFields.Count != 0 || string.IsNullOrEmpty(SortedFields))
			{
				return;
			}
			string[] array = SortedFields.Split(',');
			if (array == null)
			{
				return;
			}
			string[] array2 = array;
			foreach (string text in array2)
			{
				if (string.IsNullOrEmpty(text))
				{
					continue;
				}
				string[] array3 = text.Split('/');
				string text2 = array3[0];
				string text3 = null;
				if (array3.Length == 2)
				{
					text3 = array3[1];
				}
				Field field = null;
				foreach (MMScrollAreaField mMField in MMFields)
				{
					if (mMField.FieldName == text2)
					{
						field = mMField.Field;
						break;
					}
				}
				if (field != null)
				{
					ListSortDirection direction = ListSortDirection.Ascending;
					if (!string.IsNullOrEmpty(text3) && string.Compare(text3, "D", StringComparison.OrdinalIgnoreCase) == 0)
					{
						direction = ListSortDirection.Descending;
					}
					FieldSortDescription item = new FieldSortDescription
					{
						Direction = direction,
						Field = field
					};
					field.Owner.SortedFields.Add(item);
				}
			}
		}

		private void SetupFixedFields()
		{
			if (string.IsNullOrEmpty(FixedFields))
			{
				return;
			}
			string[] array = FixedFields.Split(',');
			if (array == null)
			{
				return;
			}
			string[] array2 = array;
			foreach (string text in array2)
			{
				string fieldName = text.Trim();
				if (!string.IsNullOrEmpty(fieldName))
				{
					MMScrollAreaField mMScrollAreaField = MMFields.Where((MMScrollAreaField p) => string.Compare(p.FieldName, fieldName, StringComparison.OrdinalIgnoreCase) == 0).FirstOrDefault();
					if (mMScrollAreaField != null)
					{
						mMScrollAreaField.Field.FixedLocation = FixedFieldLocation.FixedToNearEdge;
					}
				}
			}
		}

		internal void DeleteSelectedField()
