				{
					throw new NotSupportedException();
				}
				list.Add(mMScrollAreaField2.ExpandedId.Value);
			}
			list.Sort();
			CxvPropertyWatch cxvPropertyWatch = new CxvPropertyWatch();
			_ = (cxvPropertyWatch.ResolvePropertyPath(this, string.Format(CultureInfo.InvariantCulture, "DataContext.{0}[0].{1}", DataProperty, mMScrollAreaFieldRepeater.SecondLevelVectorProperty)) as IBindingList).Count;
			_ = base.DataGrid.SelectedItems.Fields.Count;
			for (int num = list.Count - 1; num >= 0; num--)
			{
				IBindingList bindingList = cxvPropertyWatch.ResolvePropertyPath(this, string.Format(CultureInfo.InvariantCulture, "DataContext.{0}[0].{1}", DataProperty, mMScrollAreaFieldRepeater.SecondLevelVectorProperty)) as IBindingList;
				try
				{
					bindingList.RemoveAt(list[num]);
				}
				catch (InvalidOperationException)
				{
				}
				catch (CxsException)
				{
				}
			}
		}

		internal bool CanDeleteSelectedField()
		{
			bool flag = CanDeleteField;
			if (flag)
			{
				foreach (Field field in base.DataGrid.SelectedItems.Fields)
				{
					MMScrollAreaField linkedMMField = GetLinkedMMField(field);
					if (linkedMMField != null && !linkedMMField.ExpandedId.HasValue)
					{
						flag = false;
						break;
					}
				}
				if (flag)
				{
					CxvPropertyWatch cxvPropertyWatch = new CxvPropertyWatch();
					List<MMScrollAreaField> list = new List<MMScrollAreaField>();
					if (base.DataGrid.SelectedItems.Fields.Count > 0)
					{
						foreach (Field field2 in base.DataGrid.SelectedItems.Fields)
						{
							list.Add(field2.Tag as MMScrollAreaField);
						}
					}
					else if (base.DataGrid.SelectedItems.Cells.Count == 1)
					{
						list.Add(base.DataGrid.SelectedItems.Cells[0].Field.Tag as MMScrollAreaField);
					}
					foreach (MMScrollAreaField item in list)
					{
						if (item != null && item.ExpandedId.HasValue)
						{
							MMScrollAreaFieldRepeater expandedFromRepeater = item.ExpandedFromRepeater;
							if (expandedFromRepeater != null)
							{
								CxvVectorPropertyData cxvVectorPropertyData = null;
								if (!string.IsNullOrEmpty(expandedFromRepeater.SecondLevelVectorProperty))
								{
									cxvVectorPropertyData = cxvPropertyWatch.ResolvePropertyPath(this, string.Format(CultureInfo.InvariantCulture, "DataContext.{0}[0].{1}", DataProperty, expandedFromRepeater.SecondLevelVectorProperty)) as CxvVectorPropertyData;
								}
								else if (!string.IsNullOrEmpty(expandedFromRepeater.CountPath))
								{
									cxvVectorPropertyData = cxvPropertyWatch.ResolvePropertyPath(this, "DataContext." + expandedFromRepeater.CountPath.Replace(".Count", "")) as CxvVectorPropertyData;
								}
								if (cxvVectorPropertyData != null && !cxvVectorPropertyData.AllowRemoveAt(item.ExpandedId.Value))
								{
									flag = false;
									break;
								}
							}
							continue;
						}
						flag = false;
						break;
					}
					if (list.Count == 0)
					{
						flag = false;
					}
				}
			}
			return flag;
		}

