		internal void InsertField()
		{
			if (base.DataContext == null)
			{
				return;
			}
			int num = -1;
			if (base.DataGrid.SelectedItems.Fields.Count > 0)
			{
				num = base.DataGrid.SelectedItems.Fields[0].Index;
			}
			else if (base.DataGrid.SelectedItems.Cells.Count > 0)
			{
				num = base.DataGrid.SelectedItems.Cells[0].Field.Index;
			}
			if (num < 0 || !(base.DataGrid.DefaultFieldLayout.Fields[num].Tag is MMScrollAreaField { ExpandedFromRepeater: { } expandedFromRepeater } mMScrollAreaField))
			{
				return;
			}
			CxvPropertyWatch cxvPropertyWatch = new CxvPropertyWatch();
			if (!(base.DataContext is CxvViewModel cxvViewModel) || !(cxvPropertyWatch.ResolvePropertyPath(this, "DataContext." + DataProperty) is CxvVectorPropertyData cxvVectorPropertyData))
			{
				return;
			}
			if (cxvVectorPropertyData.IndexBasis.IsNotJagged.HasValue && !cxvVectorPropertyData.IndexBasis.IsNotJagged.Value)
			{
				int num2 = cxvVectorPropertyData.Count;
				if (!(cxvVectorPropertyData.IndexBasis is CxvChildCountIndexBasisData cxvChildCountIndexBasisData))
				{
					return;
				}
				if (cxvChildCountIndexBasisData.HasProxyRow)
				{
					num2--;
				}
				CxsDataProvider resolvedCxsProvider = cxvViewModel.ResolvedCxsProvider;
				resolvedCxsProvider?.SuspendNotifications();
				try
				{
					for (int i = 0; i < num2; i++)
					{
						(cxvPropertyWatch.ResolvePropertyPath(this, string.Format(CultureInfo.InvariantCulture, "DataContext.{0}[{1}].{2}", DataProperty, i.ToString(), expandedFromRepeater.SecondLevelVectorProperty)) as IBindingList).Insert(mMScrollAreaField.ExpandedId.Value, null);
					}
					return;
				}
				catch (Exception)
				{
					return;
				}
				finally
				{
					resolvedCxsProvider?.ResumeNotifications();
				}
			}
			(cxvPropertyWatch.ResolvePropertyPath(this, string.Format(CultureInfo.InvariantCulture, "DataContext.{0}[0].{1}", DataProperty, expandedFromRepeater.SecondLevelVectorProperty)) as IBindingList).Insert(mMScrollAreaField.ExpandedId.Value, null);
		}

		internal string GetLayoutFilePath()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData)).Append("\\AspenTech\\AspenPlus\\SavedScrollAreaLayout");
			if (!Directory.Exists(stringBuilder.ToString()))
			{
				Directory.CreateDirectory(stringBuilder.ToString());
			}
			stringBuilder.Append("\\");
			if (Infragistics.Windows.Utilities.GetAncestorFromType(this, typeof(MMTabPage), allowSubclassOfType: true) is MMTabPage mMTabPage)
			{
				stringBuilder.Append(mMTabPage.GetType().Name).Append("_");
			}
			if (base.Name != null)
			{
				stringBuilder.Append(base.Name);
			}
			stringBuilder.Append(".xml");
			return stringBuilder.ToString();
		}

		internal override MMScrollAreaField GetLinkedMMField(Field field)
		{
			MMScrollAreaFieldCollection mmfields = ((_expandedFields == null) ? MMFields : _expandedFields);
			return DoGetLinkedMMField(mmfields, field);
		}

		private MMScrollAreaField DoGetLinkedMMField(MMScrollAreaFieldCollection mmfields, Field field)
		{
			foreach (MMScrollAreaField mmfield in mmfields)
			{
				if (mmfield.Field == field)
				{
					return mmfield;
				}
				if (mmfield is MMScrollAreaHeaderOnlyField mMScrollAreaHeaderOnlyField)
				{
					MMScrollAreaField mMScrollAreaField = DoGetLinkedMMField(mMScrollAreaHeaderOnlyField.MMFields, field);
					if (mMScrollAreaField != null)
					{
						return mMScrollAreaField;
					}
				}
			}
			return null;
		}

		protected override void RefreshAllFieldsBinding()
		{
			if (MMFields != null)
			{
				foreach (MMScrollAreaField mMField in MMFields)
				{
					RefreshFieldBinding(mMField);
				}
			}
			if (_MMColumnSets != null)
			{
				MMColumnSets.RefreshAllColumnSetBinding();
			}
		}

		private static object GetPromptControl(FrameworkElement parent)
		{
			FrameworkElement frameworkElement = parent;
			while (frameworkElement != null && !(frameworkElement is IPromptControl) && VisualTreeHelper.GetChildrenCount(frameworkElement) != 0)
			{
				frameworkElement = VisualTreeHelper.GetChild(frameworkElement, 0) as FrameworkElement;
			}
			return frameworkElement;
		}

		protected override void InitFields()
		{
			if (base.DataContext == null || MMFields == null)
			{
				return;
			}
			IEnumerable<MMScrollAreaField> source = MMFields.Where((MMScrollAreaField f) => f.GetType() == typeof(MMScrollAreaReadOnlyValueField));
			if (base.Visibility != Visibility.Visible && source.FirstOrDefault() != null)
			{
				return;
			}
			Mouse.OverrideCursor = Cursors.Wait;
			try
			{
				DoInitFields();
			}
			catch (Exception)
			{
			}
			finally
			{
				Mouse.OverrideCursor = null;
			}
		}

		private void DoInitFields()
		{
			bool flag = false;
			_expandedFields = ExpandField();
			_hasInitialized = false;
			EnsureFieldLayoutAndSettings();
			if (DesignerProperties.GetIsInDesignMode(this) || !_isDataGridLoaded)
			{
				base.DataGrid.DefaultFieldLayout.Fields.Clear();
			}
			else
			{
				if (base.DataGrid.DefaultFieldLayout.Fields.Count > 0)
				{
					flag = true;
					SaveCustomization(isUnloading: false);
				}
				LoadInitialLayout();
				if (base.DataGrid.DefaultFieldLayout.Fields.Count > 0)
				{
					foreach (UnboundField field in base.DataGrid.DefaultFieldLayout.Fields)
					{
						field.Visibility = Visibility.Collapsed;
					}
				}
				base.NonHeaderOnlyFields.Clear();
				if (MMFields.Count == 0 && MMFieldsDP != null && MMFieldsDP.Count > 0)
				{
					SetMMFields(MMFieldsDP.Clone());
					if (MMFields == null || MMFields.Count == 0)
					{
						return;
					}
				}
			}
			int maxRows = AddFields(_expandedFields, 0, 0, base.DataGrid.DefaultFieldLayout);
			AfterAddingFields(maxRows);
			if (!string.IsNullOrEmpty(DefaultColumnSet))
			{
				SelectedColumnSet = MMColumnSets[DefaultColumnSet];
			}
			SetupSortedFields();
			SetupFixedFields();
			if (flag)
			{
				int num = 0;
				while (num < base.DataGrid.DefaultFieldLayout.Fields.Count)
				{
					if (base.DataGrid.DefaultFieldLayout.Fields[num].VisibilityResolved == Visibility.Collapsed)
					{
						base.DataGrid.DefaultFieldLayout.Fields.RemoveAt(num);
					}
					else
					{
						num++;
					}
				}
			}
			SetSelectedColumnSet();
			RestoreCustomization();
			if (_initialLayout == null && !DesignerProperties.GetIsInDesignMode(this) && _isDataGridLoaded)
			{
				_initialLayout = base.DataGrid.SaveCustomizations();
			}
			_hasInitialized = true;
		}

		public void LoadInitialLayout()
		{
			if (_initialLayout != null)
			{
				base.DataGrid.LoadCustomizations(_initialLayout);
			}
		}

		private int AddFields(IEnumerable<MMScrollAreaField> fields, int currentRow, int startingColumnId, FieldLayout fieldLayout)
		{
			EnsureFieldLayoutAndSettings();
			int num = 1;
			int num2 = startingColumnId;
			bool flag = startingColumnId >= VisibleFieldCount;
			fieldLayout.Fields.BeginUpdate();
			foreach (MMScrollAreaField field in fields)
			{
				field.ParentScrollArea = this;
				field.ParentScrollAreaActions = this;
				if (!field.IsUsed)
				{
					continue;
				}
				UnboundField unboundField = new UnboundField();
				if (base.IsBoundToPlainDataSource)
				{
					unboundField.Label = field.Label;
				}
				else
				{
					LabelHeader label = (field.Header = new LabelHeader());
					unboundField.Label = label;
				}
				field.Field = unboundField;
				field.InitField();
				unboundField.Tag = field;
				if (string.IsNullOrEmpty(field.FieldName))
				{
					unboundField.Name = "R" + currentRow.ToString(CultureInfo.InvariantCulture) + "C" + num2.ToString(CultureInfo.InvariantCulture);
				}
				else
				{
					unboundField.Name = field.FieldName;
				}
				unboundField.Settings.LabelClickAction = LabelClickAction.SelectField;
				unboundField.Settings.AllowCellVirtualization = true;
				unboundField.Settings.AllowLabelVirtualization = string.IsNullOrEmpty(field.HeaderUnitsProperty);
				unboundField.Settings.AllowFixing = AllowFieldFixing.NearOrFar;
				unboundField.Settings.SortComparer = new FieldSortComparer
				{
					MMField = field
				};
				if (base.DataOrientation == Orientation.Vertical)
				{
					unboundField.Column = num2;
					unboundField.Row = currentRow;
				}
				else
				{
					unboundField.Row = num2;
					unboundField.Column = currentRow;
					if (FieldWidth.HasValue)
					{
						unboundField.Settings.CellMinWidth = FieldWidth.Value;
					}
					if (LabelWidth.HasValue)
					{
						unboundField.Settings.LabelWidth = LabelWidth.Value;
					}
				}
				int num3 = 1;
				Type type = field.GetType();
				if (type == typeof(MMScrollAreaHeaderOnlyField))
				{
					MMScrollAreaHeaderOnlyField mMScrollAreaHeaderOnlyField = field as MMScrollAreaHeaderOnlyField;
					unboundField.Settings.CellContentAlignment = CellContentAlignment.LabelOnly;
					int visibleFieldCount = VisibleFieldCount;
					int num4 = currentRow;
					num4 = checked(num4 + 1);
					int num5 = AddFields(mMScrollAreaHeaderOnlyField.MMFields, num4, num2, fieldLayout);
					if (VisibleFieldCount == visibleFieldCount)
					{
						num2++;
					}
					else
					{
						num = Math.Max(num, ++num5);
						num3 = VisibleFieldCount - visibleFieldCount;
						num2 += num3;
						if (base.DataOrientation == Orientation.Vertical)
						{
							unboundField.ColumnSpan = num3;
						}
						else
						{
							unboundField.RowSpan = num3;
						}
					}
				}
				else if (type == typeof(MMScrollAreaHierarchicalField) && !DesignerProperties.GetIsInDesignMode(this))
				{
					unboundField.DataType = typeof(IEnumerable);
					MMScrollAreaHierarchicalField mMScrollAreaHierarchicalField = field as MMScrollAreaHierarchicalField;
					if (string.IsNullOrEmpty(mMScrollAreaHierarchicalField.InnerDataItemType))
					{
						throw new ArgumentNullException("InnerDataItemType");
					}
					FieldLayout fieldLayout2 = new FieldLayout
					{
						Key = mMScrollAreaHierarchicalField.InnerDataItemType
					};
					DoFieldLayoutInitializing(fieldLayout2);
					SetFieldLayoutSetting(fieldLayout2);
					AddFields(mMScrollAreaHierarchicalField.MMFields, 0, 0, fieldLayout2);
					base.DataGrid.FieldLayouts.Add(fieldLayout2);
					base.ContainsHierachy = true;
				}
				else
				{
					if (!field.HasColumnHeader)
					{
						unboundField.Settings.CellContentAlignment = CellContentAlignment.ValueOnly;
					}
					if (base.NonHeaderOnlyFields != null)
					{
						base.NonHeaderOnlyFields.Add(unboundField);
					}
					num2++;
				}
				MMScrollAreaTemplateHelper.SetCellStyleAndFieldBinding(field);
				if (type != typeof(MMScrollAreaHierarchicalField))
				{
					MMScrollAreaTemplateHelper.SetLabelPresenterStyle(field);
				}
				if (!flag)
				{
					foreach (Field field2 in fieldLayout.Fields)
					{
						if (base.DataOrientation == Orientation.Horizontal && field2.Row >= unboundField.Row)
						{
							field2.Row += num3;
						}
						if (base.DataOrientation == Orientation.Vertical && field2.Column >= unboundField.Column)
						{
							field2.Column += num3;
						}
					}
				}
				fieldLayout.Fields.Add(unboundField);
			}
			fieldLayout.Fields.EndUpdate();
			return num;
		}

		private void AfterAddingFields(int maxRows)
		{
			_maxNumOfHeaderRows = Math.Max(maxRows, _maxNumOfHeaderRows);
			if (_maxNumOfHeaderRows <= 1)
			{
				return;
			}
			foreach (UnboundField nonHeaderOnlyField in base.NonHeaderOnlyFields)
			{
				if (base.DataOrientation == Orientation.Vertical)
				{
					nonHeaderOnlyField.RowSpan = _maxNumOfHeaderRows - nonHeaderOnlyField.Row;
				}
				else
				{
					nonHeaderOnlyField.ColumnSpan = _maxNumOfHeaderRows - nonHeaderOnlyField.Column;
				}
			}
		}

