					mMScrollAreaReadOnlyValueField2.HasColumnHeader = mMScrollAreaReadOnlyValueField.HasColumnHeader;
					mMScrollAreaReadOnlyValueField2.IsHeaderUnitsEnabled = mMScrollAreaReadOnlyValueField.IsHeaderUnitsEnabled;
					mMScrollAreaReadOnlyValueField2.Mask = mMScrollAreaReadOnlyValueField.Mask;
					mMScrollAreaReadOnlyValueField2.MaxLength = mMScrollAreaReadOnlyValueField.MaxLength;
					mMScrollAreaReadOnlyValueField2.VariableDataMember = mMScrollAreaReadOnlyValueField.VariableDataMember;
					mMScrollAreaReadOnlyValueField2.WidthFieldLength = mMScrollAreaReadOnlyValueField.WidthFieldLength;
					AppendExpandedField(mMScrollAreaReadOnlyValueField2, expandedFields, repeaterField, i);
				}
				return;
			}
			for (int j = 0; j < num; j++)
			{
				foreach (MMScrollAreaField field in repeaterField.Fields)
				{
					MMScrollAreaField clone = field.Clone() as MMScrollAreaField;
					AppendExpandedField(clone, expandedFields, repeaterField, j);
				}
			}
		}

		private void AppendExpandedField(MMScrollAreaField clone, MMScrollAreaFieldCollection expandedFields, MMScrollAreaFieldRepeater repeaterField, int id)
		{
			clone.ExpandedId = id;
			clone.ExpandedFromRepeater = repeaterField;
			object obj = null;
			if (!string.IsNullOrEmpty(repeaterField.KeyPath))
			{
				string text = string.Format(CultureInfo.InvariantCulture, repeaterField.KeyPath, id);
				obj = _expandedFieldDependencies.ResolvePropertyPath(this, "DataContext." + text);
			}
			if (obj == null)
			{
				obj = string.Empty;
			}
			clone.SubstituteIndexAndKey(id, obj);
			RefreshFieldBinding(clone);
			expandedFields.Add(clone);
		}

		private void ExpandField(MMScrollAreaFieldCollection fields, MMScrollAreaFieldCollection expandedFields)
		{
			foreach (MMScrollAreaField field in fields)
			{
				if (!(field is MMScrollAreaFieldRepeater repeaterField))
				{
					if (field is MMScrollAreaHeaderOnlyField mMScrollAreaHeaderOnlyField)
					{
						MMScrollAreaHeaderOnlyField mMScrollAreaHeaderOnlyField2 = mMScrollAreaHeaderOnlyField.Clone() as MMScrollAreaHeaderOnlyField;
						mMScrollAreaHeaderOnlyField2.ResetMMFields();
						ExpandField(mMScrollAreaHeaderOnlyField.MMFields, mMScrollAreaHeaderOnlyField2.MMFields);
						expandedFields.Add(mMScrollAreaHeaderOnlyField2);
					}
					else
					{
						expandedFields.Add(field);
					}
				}
				else
				{
					DoExpandField(expandedFields, repeaterField);
				}
			}
		}

		private MMScrollAreaFieldCollection ExpandField()
		{
			if (DesignerProperties.GetIsInDesignMode(this))
			{
				return MMFields;
			}
			if (_expandedFieldDependencies != null)
			{
				_expandedFieldDependencies.PropertyDependencyChanged -= delegate
				{
					ReInitFields();
				};
				_expandedFieldDependencies.Clear();
				_expandedFieldDependencies = null;
			}
			MMScrollAreaFieldCollection mMScrollAreaFieldCollection = new MMScrollAreaFieldCollection();
			ExpandField(MMFields, mMScrollAreaFieldCollection);
			if (_expandedFieldDependencies != null)
			{
				if (!_expandedFieldDependencies.IsEmpty)
				{
					_expandedFieldDependencies.PropertyDependencyChanged -= delegate
					{
						ReInitFields();
					};
					_expandedFieldDependencies.PropertyDependencyChanged += delegate
					{
						ReInitFields();
					};
				}
				else
				{
					_expandedFieldDependencies = null;
				}
			}
			return mMScrollAreaFieldCollection;
		}

		public void ReInitFields()
		{
			if (!SuspendInitFields)
			{
				if (_ReInitFieldsTimer == null)
				{
					_ReInitFieldsTimer = new DispatcherTimer();
					_ReInitFieldsTimer.Tick += _ReInitFieldsTimer_Tick;
					_ReInitFieldsTimer.Interval = new TimeSpan(0, 0, 0, 0, 500);
				}
				if (_ReInitFieldsTimer.IsEnabled)
				{
					_ReInitFieldsRequestCount++;
					return;
				}
				_ReInitFieldsRequestCountOld = 1;
				_ReInitFieldsRequestCount = 1;
				_ReInitFieldsTimer.Start();
			}
		}

		private void _ReInitFieldsTimer_Tick(object sender, EventArgs e)
		{
			if (_ReInitFieldsRequestCount == _ReInitFieldsRequestCountOld)
			{
				_ReInitFieldsTimer.Stop();
				InitFields();
				_isJustReset = true;
			}
			else
			{
				_ReInitFieldsRequestCountOld = _ReInitFieldsRequestCount;
			}
		}

		private int GetMaxColumnOfFields()
		{
			int num = 0;
			foreach (Field field in base.DataGrid.DefaultFieldLayout.Fields)
			{
				if (field.ActualPosition.Column > num)
				{
					num = field.ActualPosition.Column;
				}
			}
			return num;
		}

		private int GetMaxColumnCount(MMScrollAreaFieldRepeater repeaterField)
		{
			if (base.DataContext == null)
			{
				return 0;
			}
			int? num = _expandedFieldDependencies.ResolveInt32(this, "DataContext." + DataProperty + ".Count");
			if (!num.HasValue)
			{
				return 0;
			}
			bool? flag = _expandedFieldDependencies.ResolveBoolean(this, "DataContext." + DataProperty + ".IsNotJagged");
			int num2 = 0;
			for (int i = 0; i < num.Value; i++)
			{
				int? num3 = _expandedFieldDependencies.ResolveInt32(this, string.Format(CultureInfo.InvariantCulture, "DataContext.{0}[{1}].{2}.Count", DataProperty, i, repeaterField.SecondLevelVectorProperty));
				if (num3.HasValue && num3.Value > num2)
				{
					num2 = num3.Value;
				}
				if (flag.HasValue && flag.Value)
				{
					break;
				}
			}
			return num2;
		}

		private void SetCanDeleteField(MMScrollAreaFieldRepeater repeaterField)
		{
			CanDeleteField = false;
			if (base.DataContext != null && new CxvPropertyWatch().ResolvePropertyPath(this, string.Format(CultureInfo.InvariantCulture, "DataContext.{0}[0].{1}", DataProperty, repeaterField.SecondLevelVectorProperty)) is IBindingList bindingList)
			{
				CanDeleteField = bindingList.AllowRemove;
				CanInsertField = bindingList.AllowNew;
			}
		}

		private void SetCanDeleteField(string countPath)
		{
			CanDeleteField = false;
			if (base.DataContext != null && !string.IsNullOrEmpty(countPath) && new CxvPropertyWatch().ResolvePropertyPath(this, "DataContext." + countPath.Replace(".Count", "")) is IBindingList bindingList)
			{
				CanDeleteField = bindingList.AllowRemove;
				CanInsertField = bindingList.AllowNew;
			}
		}

		private string GetFieldPropertyPath(Cell cell)
		{
			MMScrollAreaField linkedMMField = GetLinkedMMField(cell.Field);
			if (linkedMMField == null)
			{
				UnboundField unboundField = cell.Field as UnboundField;
				if (unboundField.BindingPath == null)
				{
					return null;
				}
				return unboundField.BindingPath.Path.Split('.')[0];
			}
			return linkedMMField.PropertyPath;
		}

