		private void MMFields_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			switch (e.Action)
			{
			case NotifyCollectionChangedAction.Add:
				if (_hasInitialized)
				{
					List<MMScrollAreaField> list = new List<MMScrollAreaField>();
					foreach (object newItem in e.NewItems)
					{
						list.Add(newItem as MMScrollAreaField);
					}
					int maxRows = AddFields(list, 0, e.NewStartingIndex, base.DataGrid.DefaultFieldLayout);
					AfterAddingFields(maxRows);
				}
				else if (DesignerProperties.GetIsInDesignMode(this) && MMFields.Count > 1)
				{
					InitFields();
				}
				break;
			case NotifyCollectionChangedAction.Remove:
			{
				foreach (object oldItem in e.OldItems)
				{
					MMScrollAreaField mMScrollAreaField = oldItem as MMScrollAreaField;
					foreach (Field field in base.DataGrid.DefaultFieldLayout.Fields)
					{
						if (base.DataOrientation == Orientation.Horizontal && field.Row > mMScrollAreaField.Field.Row)
						{
							field.Row--;
						}
						else if (base.DataOrientation == Orientation.Vertical && field.Column > mMScrollAreaField.Field.Column)
						{
							field.Column--;
						}
					}
					base.DataGrid.DefaultFieldLayout.Fields.Remove(mMScrollAreaField.Field);
					if (base.NonHeaderOnlyFields.Contains(mMScrollAreaField.Field))
					{
						base.NonHeaderOnlyFields.Remove(mMScrollAreaField.Field);
					}
				}
				break;
			}
			case NotifyCollectionChangedAction.Reset:
				InitFields();
				break;
			case NotifyCollectionChangedAction.Replace:
			case NotifyCollectionChangedAction.Move:
				break;
			}
		}

		private static void GrayedOutRowIdsPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs args)
		{
			MMScrollArea mMScrollArea = d as MMScrollArea;
			if (args.NewValue != null)
			{
				ObservableCollection<int> obj = args.NewValue as ObservableCollection<int>;
				mMScrollArea.RefreshRowBackground();
				obj.CollectionChanged += mMScrollArea.GrayedOutRowIds_CollectionChanged;
			}
			if (args.OldValue != null)
			{
				(args.OldValue as ObservableCollection<int>).CollectionChanged += mMScrollArea.GrayedOutRowIds_CollectionChanged;
			}
		}

		private void GrayedOutRowIds_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			RefreshRowBackground();
		}

		private void RefreshRowBackground()
		{
			if (GrayedOutRowIds != null && base.DataGrid.Records != null)
			{
				if (!_originalHighlightAlternateRecords.HasValue)
				{
					_originalHighlightAlternateRecords = base.DataGrid.DefaultFieldLayout.HighlightAlternateRecordsResolved;
				}
				base.DataGrid.DefaultFieldLayout.Settings.HighlightAlternateRecords = false;
				for (int i = 0; i < base.DataGrid.Records.Count; i++)
				{
					RecordPresenter recordPresenter = RecordPresenter.FromRecord(base.DataGrid.Records[i]);
					if (recordPresenter != null)
					{
						if (GrayedOutRowIds.Contains(i))
						{
							recordPresenter.Background = GrayedOutRowBackgroundResolved;
						}
						else
						{
							recordPresenter.ClearValue(Control.BackgroundProperty);
						}
					}
				}
			}
			else if (_originalHighlightAlternateRecords.HasValue)
			{
				base.DataGrid.DefaultFieldLayout.Settings.HighlightAlternateRecords = _originalHighlightAlternateRecords;
			}
		}

