		private void SetDataBinding()
		{
			if (base.DataGrid == null)
			{
				return;
			}
			if (base.DataGrid.Records != null)
			{
				base.DataGrid.Records.CollectionChanged -= Records_CollectionChanged;
			}
			BindingOperations.ClearBinding(base.DataGrid, DataPresenterBase.DataSourceProperty);
			if (!string.IsNullOrEmpty(DataProperty))
			{
				BindingOperations.SetBinding(base.DataGrid, DataPresenterBase.DataSourceProperty, new Binding(DataProperty));
				if (BindingOperations.GetBindingExpression(this, MMScrollAreaBase.IsMMEnabledProperty) == null)
				{
					MultiBinding multiBinding = new MultiBinding();
					multiBinding.Bindings.Add(new Binding(DataProperty + ".IsEnabled"));
					multiBinding.Bindings.Add(new Binding(DataProperty + ".Count"));
					multiBinding.Converter = ScrollareaIsEnabledConverter.Converter;
					BindingOperations.SetBinding(this, MMScrollAreaBase.IsMMEnabledProperty, multiBinding);
				}
				BindingOperations.SetBinding(base.DataGrid, UIElement.VisibilityProperty, new Binding(DataProperty + ".IsVisible")
				{
					Converter = IsVisibleConverter.Converter
				});
				base.DataGrid.Records.CollectionChanged += Records_CollectionChanged;
				if (BindingOperations.GetMultiBinding(this, MMScrollAreaBase.PromptProperty) == null)
				{
					BindingOperations.SetBinding(this, MMScrollAreaBase.PromptProperty, new MultiBinding
					{
						Bindings = 
						{
							(BindingBase)new Binding(DataProperty + ".VariablePrompt"),
							(BindingBase)new Binding(DataProperty + ".DisabledPrompt"),
							(BindingBase)new Binding("IsEnabled")
							{
								Source = this
							},
							(BindingBase)new Binding("IsMMEnabled")
							{
								Source = this
							},
							(BindingBase)new Binding
							{
								Source = this
							}
						},
						Converter = new AesControlPromptConverter(),
						Mode = BindingMode.OneWay,
						FallbackValue = string.Empty
					});
				}
			}
		}

		protected virtual void Records_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			if (e == null)
			{
				return;
			}
			switch (e.Action)
			{
			case NotifyCollectionChangedAction.Remove:
				SetSelection(null);
				break;
			case NotifyCollectionChangedAction.Reset:
				if (_isDataGridLoaded)
				{
					_isJustReset = true;
					if (base.DataOrientation == Orientation.Horizontal)
					{
						RefreshRecordSelectors(isClearingAllHighlight: true);
					}
					base.DataGrid.SelectedItems.Records.Clear();
					base.DataGrid.SelectedItems.Fields.Clear();
					base.DataGrid.SelectedItems.Cells.Clear();
					BindingExpression bindingExpression = BindingOperations.GetBindingExpression(this, MMScrollAreaBase.SelectedRowIndexesProperty);
					if (bindingExpression != null && bindingExpression.ParentBinding.Mode == BindingMode.TwoWay)
					{
						SetSelectedRow();
						_shouldRestoreActiveCellOnReset = false;
					}
					else
					{
						SetSelection(null);
					}
					if (base.ContainsHierachy)
					{
						base.DataGrid.Records.CollapseAll(recursive: false);
					}
					_recordCountBeforeReset = base.DataGrid.Records.Count;
				}
				break;
			}
		}

