		protected override void Dispose(bool disposing)
		{
			base.Dispose(disposing);
			if (!disposing)
			{
				return;
			}
			if (MMFields != null)
			{
				foreach (MMScrollAreaField mMField in MMFields)
				{
					if (mMField is IDisposable disposable)
					{
						disposable.Dispose();
					}
				}
				_MMFields = null;
			}
			if (_MMColumnSets != null)
			{
				foreach (MMScrollAreaColumnSet mMColumnSet in MMColumnSets)
				{
					mMColumnSet.Dispose();
				}
				_MMColumnSets = null;
			}
			if (_expandedFieldDependencies != null)
			{
				_expandedFieldDependencies.PropertyDependencyChanged -= delegate
				{
					ReInitFields();
				};
				_expandedFieldDependencies.Clear();
				_expandedFieldDependencies = null;
			}
		}

