		{
			if (base.DataGrid.Records.Count <= 1)
			{
				yield break;
			}
			foreach (Field field in base.DataGrid.DefaultFieldLayout.Fields)
			{
				if (field.VisibilityResolved != Visibility.Visible)
				{
					continue;
				}
				object value = (base.DataGrid.Records[0] as DataRecord).Cells[field].Value;
				bool flag = false;
				if (value == null)
				{
					for (int i = 1; i < base.DataGrid.Records.Count; i++)
					{
						value = (base.DataGrid.Records[i] as DataRecord).Cells[field].Value;
						if (value != null)
						{
							flag = true;
							break;
						}
					}
				}
				else
				{
					flag = true;
				}
				if (flag && double.TryParse(value.ToString(), out var _))
				{
					StringBuilder stringBuilder = new StringBuilder();
					List<MMScrollAreaField> list = new List<MMScrollAreaField>();
					list.Add(GetLinkedMMField(field));
					DataObjectLateGen.GetLabelOfNonHeaderOnlyFields(stringBuilder, list, this, base.DataContext as CxvViewModel, setHeaderLineCount: false);
					stringBuilder.Replace(Environment.NewLine, " ");
					yield return new Tuple<int, string>(field.ActualPosition.Column, stringBuilder.ToString());
				}
			}
		}

