						stringBuilder.Replace(Environment.NewLine, " ");
						list.Add(stringBuilder.ToString());
					}
				}
			}
			else if (base.DataGrid.SelectedItems.Fields.Count > 0)
			{
				foreach (Field field in base.DataGrid.SelectedItems.Fields)
				{
					if (field.VisibilityResolved == Visibility.Visible && field.CellContentAlignmentResolved != CellContentAlignment.LabelOnly)
					{
						StringBuilder stringBuilder2 = new StringBuilder();
