						list.Add(stringBuilder2.ToString());
					}
				}
			}
			return list;
		}

		public void SelectField(int displayId, bool clearCurrentSelection)
		{
			if (clearCurrentSelection)
			{
				ClearSelection();
			}
			if (displayId < base.DataGrid.DefaultFieldLayout.Fields.Count)
			{
				Field fieldByDisplayId = GetFieldByDisplayId(displayId);
				if (fieldByDisplayId != null)
				{
					fieldByDisplayId.IsSelected = true;
				}
			}
		}

		public void UnSelectField(int displayId)
		{
			if (displayId < base.DataGrid.DefaultFieldLayout.Fields.Count)
			{
				Field fieldByDisplayId = GetFieldByDisplayId(displayId);
				if (fieldByDisplayId != null)
				{
					fieldByDisplayId.IsSelected = false;
				}
			}
		}

		private Field GetFieldByDisplayId(int displayId)
		{
			return base.DataGrid.DefaultFieldLayout.Fields.Where((Field f) => f.ActualPosition.Column == displayId).FirstOrDefault();
		}

