		private bool IsVisualChild(DependencyObject child)
		{
			while (child != null)
			{
				if (child == this)
				{
					return true;
				}
				child = ((!(child is Visual)) ? LogicalTreeHelper.GetParent(child) : VisualTreeHelper.GetParent(child));
			}
			return false;
