		public override string GetActiveScriptingPath()
		{
			if (base.DataGrid == null || base.DataGrid.ActiveCell == null)
			{
				return DataProperty;
			}
			string pathIfInHierarchicalField = GetPathIfInHierarchicalField();
			if (!string.IsNullOrEmpty(pathIfInHierarchicalField))
			{
				return pathIfInHierarchicalField;
			}
			MMScrollAreaSelectedCell mMScrollAreaSelectedCell = new MMScrollAreaSelectedCell
			{
				Field = GetLinkedMMField(base.DataGrid.ActiveCell.Field),
				Record = new MMScrollAreaSelectedRecord
				{
					Index = base.DataGrid.ActiveCell.Record.DataItemIndex,
					DisplayIndex = base.DataGrid.ActiveCell.Record.VisibleIndex
				}
			};
			if (mMScrollAreaSelectedCell.Field == null)
			{
				return DataProperty;
			}
			return GetPropPath(mMScrollAreaSelectedCell);
		}

		private string GetPathIfInHierarchicalField()
		{
			if (base.DataGrid == null || base.DataGrid.ActiveCell == null || base.DataGrid.ActiveCell.Field == null || base.DataGrid.ActiveCell.Record == null || MMFields == null)
			{
				return null;
			}
			MMScrollAreaField linkedMMfield = GetLinkedMMField(base.DataGrid.ActiveCell.Field);
			MMScrollAreaHierarchicalField mMScrollAreaHierarchicalField = null;
			foreach (MMScrollAreaField mMField in MMFields)
			{
				if (mMField is MMScrollAreaHierarchicalField mMScrollAreaHierarchicalField2 && mMScrollAreaHierarchicalField2.MMFields.Count((MMScrollAreaField p) => p == linkedMMfield) > 0)
				{
					mMScrollAreaHierarchicalField = mMScrollAreaHierarchicalField2;
					break;
				}
			}
			if (mMScrollAreaHierarchicalField != null && base.DataContext is MMViewModel container && container.ResolveViewPropertyPath(DataProperty) is CxvVectorPropertyData cxvVectorPropertyData && base.DataGrid.ActiveCell.Record.DataItem is MMViewModel { Parent: { } parent })
			{
				int num = cxvVectorPropertyData.IndexOf(parent);
				if (num > -1)
				{
					StringBuilder stringBuilder = new StringBuilder();
					stringBuilder.Append(DataProperty).Append("[").Append(num)
						.Append("].")
						.Append(mMScrollAreaHierarchicalField.PropertyPath)
						.Append("[")
						.Append(base.DataGrid.ActiveCell.Record.Index)
						.Append("].")
						.Append(linkedMMfield.PropertyPath);
					return stringBuilder.ToString();
				}
			}
			return null;
		}
	}
