	public class MMScrollAreaSelectedCell
	{
		public MMScrollAreaField Field { get; set; }

		public MMScrollAreaSelectedRecord Record { get; set; }

		public override bool Equals(object obj)
		{
			if (obj == null || obj.GetType() != typeof(MMScrollAreaSelectedCell))
			{
				return false;
			}
			MMScrollAreaSelectedCell mMScrollAreaSelectedCell = obj as MMScrollAreaSelectedCell;
			if (mMScrollAreaSelectedCell.Field == Field)
			{
				return mMScrollAreaSelectedCell.Record.Index == Record.Index;
			}
			return false;
		}

		public override int GetHashCode()
		{
			return base.GetHashCode();
		}

		internal static int CompareSelectedCell(MMScrollAreaSelectedCell a, MMScrollAreaSelectedCell b)
		{
			bool flag = false;
			if (a.Field.ParentScrollArea is MMScrollArea mMScrollArea)
			{
				flag = mMScrollArea.DataOrientation == Orientation.Horizontal;
			}
			if (flag)
			{
				if (a.Field.Field == null || b.Field.Field == null)
				{
					return a.Field.Id - b.Field.Id;
				}
				if (a.Field.Field.ActualPosition.Row == b.Field.Field.ActualPosition.Row)
				{
					return a.Record.DisplayIndex - b.Record.DisplayIndex;
				}
				return a.Field.Field.ActualPosition.Row - b.Field.Field.ActualPosition.Row;
			}
			if (a.Record.DisplayIndex == b.Record.DisplayIndex)
			{
				if (a.Field.Field != null && b.Field.Field != null)
				{
					return a.Field.Field.ActualPosition.Column - b.Field.Field.ActualPosition.Column;
				}
				return a.Field.Id - b.Field.Id;
			}
			return a.Record.DisplayIndex - b.Record.DisplayIndex;
		}
	}
	public class MMScrollAreaSelection
	{
		public MMScrollAreaBase ScrollArea { get; private set; }

		public int SelectedRecordsCount => ScrollArea.DataGrid.SelectedItems.Records.Count;

		public IEnumerable<MMScrollAreaSelectedRecord> SelectedRecords
		{
			get
			{
				foreach (Record record in ScrollArea.DataGrid.SelectedItems.Records)
				{
					if (record.NestingDepth <= 0)
					{
						yield return new MMScrollAreaSelectedRecord
						{
							Index = (record as DataRecord).DataItemIndex,
							DisplayIndex = (record as DataRecord).VisibleIndex
						};
					}
				}
			}
		}

		public int SelectedFieldsCount
		{
			get
			{
				int num = 0;
				foreach (Field @field in ScrollArea.DataGrid.SelectedItems.Fields)
				{
					if (@field.CellContentAlignmentResolved != CellContentAlignment.LabelOnly)
					{
						num++;
					}
				}
				return num;
			}
		}

		public IEnumerable<MMScrollAreaField> SelectedFields
		{
			get
			{
				foreach (Field @field in ScrollArea.DataGrid.SelectedItems.Fields)
				{
					if (@field.CellContentAlignmentResolved != CellContentAlignment.LabelOnly)
					{
						MMScrollAreaField linkedMMField = ScrollArea.GetLinkedMMField(@field);
						if (linkedMMField != null)
						{
							yield return linkedMMField;
						}
					}
				}
			}
		}

		public int SelectedCellsCount
		{
			get
			{
				int num = 0;
				foreach (Cell cell in ScrollArea.DataGrid.SelectedItems.Cells)
				{
					if (cell.Field.CellContentAlignmentResolved != CellContentAlignment.LabelOnly)
					{
						num++;
					}
				}
				return num;
			}
		}

		public IEnumerable<MMScrollAreaSelectedCell> SelectedCells
		{
			get
			{
				foreach (Cell cell in ScrollArea.DataGrid.SelectedItems.Cells)
				{
					if (cell.Field.CellContentAlignmentResolved != CellContentAlignment.LabelOnly && cell.Field.Owner == ScrollArea.DataGrid.DefaultFieldLayout)
					{
						MMScrollAreaField linkedMMField = ScrollArea.GetLinkedMMField(cell.Field);
						yield return new MMScrollAreaSelectedCell
						{
							Field = linkedMMField,
							Record = new MMScrollAreaSelectedRecord
							{
								Index = cell.Record.DataItemIndex,
								DisplayIndex = cell.Record.VisibleIndex
							}
						};
					}
				}
			}
		}

		public int AllSelectedRecordsCount
		{
			get
			{
				if (SelectedFieldsCount > 0)
				{
					return ScrollArea.DataGrid.Records.Count;
				}
				if (SelectedCellsCount > 0)
				{
					List<int> list = new List<int>();
					foreach (MMScrollAreaSelectedCell selectedCell in ScrollArea.Selection.SelectedCells)
					{
						int num = list.BinarySearch(selectedCell.Record.Index);
						if (num < 0)
						{
							list.Insert(~num, selectedCell.Record.Index);
						}
					}
					return list.Count;
				}
				return SelectedRecordsCount;
			}
		}

		public IEnumerable<MMScrollAreaSelectedRecord> AllSelectedRecords
		{
			get
			{
				if (SelectedFieldsCount > 0)
				{
					foreach (Record item in (IEnumerable<Record>)ScrollArea.DataGrid.Records)
					{
						yield return new MMScrollAreaSelectedRecord
						{
							Index = (item as DataRecord).DataItemIndex
						};
					}
					yield break;
				}
				if (SelectedCellsCount > 0)
				{
					List<int> selectedRecords = new List<int>();
					foreach (MMScrollAreaSelectedCell selectedCell in ScrollArea.Selection.SelectedCells)
					{
						int num = selectedRecords.BinarySearch(selectedCell.Record.Index);
						if (num < 0)
						{
							selectedRecords.Insert(~num, selectedCell.Record.Index);
							yield return new MMScrollAreaSelectedRecord
							{
								Index = selectedCell.Record.Index
							};
						}
					}
					yield break;
				}
				foreach (MMScrollAreaSelectedRecord selectedRecord in ScrollArea.Selection.SelectedRecords)
				{
					yield return new MMScrollAreaSelectedRecord
					{
						Index = selectedRecord.Index
					};
				}
			}
		}

		public IEnumerable<Field> AllSelectedFields
		{
			get
			{
				if (SelectedFieldsCount > 0)
				{
					foreach (Field @field in ScrollArea.DataGrid.SelectedItems.Fields)
					{
						if (@field.CellContentAlignmentResolved != CellContentAlignment.LabelOnly)
						{
							yield return @field;
						}
					}
				}
				else
				{
					if (SelectedCellsCount <= 0)
					{
						yield break;
					}
					foreach (Cell cell in ScrollArea.DataGrid.SelectedItems.Cells)
					{
						if (cell.Field.CellContentAlignmentResolved != CellContentAlignment.LabelOnly)
						{
							yield return cell.Field;
						}
					}
				}
			}
		}

		public IEnumerable<Cell> AllSelectedCells
		{
			get
			{
				IList<Cell> list = new List<Cell>();
				foreach (Cell cell in ScrollArea.DataGrid.SelectedItems.Cells)
				{
					if (cell.Field.VisibilityResolved == Visibility.Visible && cell.Record.VisibilityResolved == Visibility.Visible)
					{
						list.Add(cell);
					}
				}
				foreach (Field @field in ScrollArea.DataGrid.SelectedItems.Fields)
				{
					if (@field.VisibilityResolved != Visibility.Visible)
					{
						continue;
					}
					foreach (Record record in (IEnumerable<Record>)ScrollArea.DataGrid.Records)
					{
						if (record is DataRecord && @field.VisibilityResolved == Visibility.Visible && !list.Any((Cell x) => x.Record == record && x.Field == @field))
						{
							list.Add(((DataRecord)record).Cells[@field]);
						}
					}
				}
				foreach (Record record2 in ScrollArea.DataGrid.SelectedItems.Records)
				{
					if (!(record2 is DataRecord) || record2.VisibilityResolved != Visibility.Visible)
					{
						continue;
					}
					foreach (Field field2 in ScrollArea.DataGrid.DefaultFieldLayout.Fields)
					{
						if (field2.VisibilityResolved != Visibility.Visible && !list.Any((Cell x) => x.Record == record2 && x.Field == field2))
						{
							list.Add(((DataRecord)record2).Cells[field2]);
						}
					}
				}
				return list;
			}
		}

		internal MMScrollAreaSelection(MMScrollAreaBase scrollArea)
		{
			ScrollArea = scrollArea;
		}
	}
