		public bool IsUsed
		{
			get
			{
				return (bool)GetValue(IsUsedProperty);
			}
			set
			{
				SetValue(IsUsedProperty, value);
			}
		}

		[DefaultValue(null)]
		public string IsUsedBindingPath { get; set; }

		internal event EventHandler IsUsedChanged;

		protected override void OnPropertyChanged(DependencyPropertyChangedEventArgs e)
		{
			base.OnPropertyChanged(e);
			if (e.Property == IsUsedProperty && this.IsUsedChanged != null)
			{
				this.IsUsedChanged(this, new EventArgs());
			}
		}

		public void Dispose()
		{
			Dispose(disposing: true);
			GC.SuppressFinalize(this);
		}

		~MMScrollAreaColumnSet()
		{
			Dispose(disposing: false);
