	public class MMScrollAreaColumnSetCollection : ObservableCollection<MMScrollAreaColumnSet>
	{
		private ObservableCollection<MMScrollAreaColumnSet> _UsedColumnSets = new ObservableCollection<MMScrollAreaColumnSet>();

		internal MMScrollArea ParentScrollArea { get; set; }

		public MMScrollAreaColumnSet this[string name] => base.Items.Where((MMScrollAreaColumnSet cs) => cs.Name == name).ElementAtOrDefault(0);

		public ObservableCollection<MMScrollAreaColumnSet> UsedColumnSets => _UsedColumnSets;

		public MMScrollAreaColumnSetCollection()
		{
			CollectionChanged += MMScrollAreaColumnSets_CollectionChanged;
		}

		private void MMScrollAreaColumnSets_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			if (e.Action == NotifyCollectionChangedAction.Add)
			{
				foreach (object newItem in e.NewItems)
				{
					MMScrollAreaColumnSet mMScrollAreaColumnSet = newItem as MMScrollAreaColumnSet;
					mMScrollAreaColumnSet.IsUsedChanged += cs_IsUsedChanged;
					RefreshColumnSetBinding(mMScrollAreaColumnSet);
					if (mMScrollAreaColumnSet.IsUsed)
					{
						UsedColumnSets.Add(mMScrollAreaColumnSet);
					}
				}
				return;
			}
			if (e.Action != NotifyCollectionChangedAction.Remove)
			{
				return;
			}
			foreach (object oldItem in e.OldItems)
			{
				MMScrollAreaColumnSet mMScrollAreaColumnSet2 = oldItem as MMScrollAreaColumnSet;
				mMScrollAreaColumnSet2.IsUsedChanged -= cs_IsUsedChanged;
				if (UsedColumnSets.Contains(mMScrollAreaColumnSet2))
				{
					UsedColumnSets.Remove(mMScrollAreaColumnSet2);
				}
			}
		}

		private void cs_IsUsedChanged(object sender, EventArgs e)
		{
			MMScrollAreaColumnSet mMScrollAreaColumnSet = sender as MMScrollAreaColumnSet;
			if (mMScrollAreaColumnSet.IsUsed && !UsedColumnSets.Contains(mMScrollAreaColumnSet))
			{
				UsedColumnSets.Add(mMScrollAreaColumnSet);
			}
			else if (!mMScrollAreaColumnSet.IsUsed && UsedColumnSets.Contains(mMScrollAreaColumnSet))
			{
				UsedColumnSets.Remove(mMScrollAreaColumnSet);
			}
		}

		private void RefreshColumnSetBinding(MMScrollAreaColumnSet cs)
		{
			if (!string.IsNullOrEmpty(cs.IsUsedBindingPath) && ParentScrollArea != null)
			{
				BindingOperations.SetBinding(cs, MMScrollAreaColumnSet.IsUsedProperty, new Binding(cs.IsUsedBindingPath)
				{
					Source = ParentScrollArea.DataContext
				});
			}
		}

		internal void RefreshAllColumnSetBinding()
		{
			foreach (MMScrollAreaColumnSet item in base.Items)
			{
				RefreshColumnSetBinding(item);
			}
		}
	}
