		internal static void OnSortDescendingCommand(object sender, ExecutedRoutedEventArgs arg)
		{
			if (arg.Parameter is UnboundField unboundField)
			{
				unboundField.Owner.SortedFields.Clear();
				FieldSortDescription item = new FieldSortDescription
				{
					Direction = ListSortDirection.Descending,
					Field = unboundField
				};
				unboundField.Owner.SortedFields.Add(item);
			}
		}

		internal static void OnSortAscendingCommand(object sender, ExecutedRoutedEventArgs arg)
		{
			if (arg.Parameter is UnboundField unboundField)
			{
				unboundField.Owner.SortedFields.Clear();
				FieldSortDescription item = new FieldSortDescription
				{
					Direction = ListSortDirection.Ascending,
					Field = unboundField
				};
				unboundField.Owner.SortedFields.Add(item);
			}
		}

		internal static void OnRemoveSortingCommand(object sender, ExecutedRoutedEventArgs arg)
		{
			UnboundField field = arg.Parameter as UnboundField;
			if (field != null)
			{
				FieldSortDescription[] array = field.Owner.SortedFields.Where((FieldSortDescription fieldSortDescription) => fieldSortDescription.Field == field).ToArray();
				foreach (FieldSortDescription item in array)
				{
					field.Owner.SortedFields.Remove(item);
				}
			}
		}

		internal static void CanRemoveSortingCommand(object sender, CanExecuteRoutedEventArgs arg)
		{
