		internal static void CanChooseFieldsCommand(object sender, CanExecuteRoutedEventArgs arg)
		{
			MMScrollArea mMScrollArea = arg.Parameter as MMScrollArea;
			arg.CanExecute = false;
			if (mMScrollArea == null || mMScrollArea.MMFields == null || mMScrollArea.MMFields.Where((MMScrollAreaField field) => field is MMScrollAreaHeaderOnlyField).FirstOrDefault() != null)
			{
				return;
			}
			MMScrollAreaField mMScrollAreaField = mMScrollArea.MMFields.Where((MMScrollAreaField field) => field is MMScrollAreaFieldRepeater).FirstOrDefault();
			if (mMScrollAreaField != null)
			{
				MMScrollAreaFieldRepeater mMScrollAreaFieldRepeater = mMScrollAreaField as MMScrollAreaFieldRepeater;
				if (mMScrollAreaFieldRepeater.Fields.Count > 0 && !string.IsNullOrEmpty(mMScrollAreaFieldRepeater.Fields[0].HeaderTypeProperty))
				{
					return;
				}
			}
			if (mMScrollArea.MMFields.Count <= 0 || !mMScrollArea.AllowChooseFields)
			{
				return;
			}
			foreach (Field field in mMScrollArea.DataGrid.DefaultFieldLayout.Fields)
			{
				if (!field.IsFixed)
				{
					MMScrollAreaField linkedMMField = mMScrollArea.GetLinkedMMField(field);
					if (linkedMMField != null && (!string.IsNullOrEmpty(linkedMMField.Label) || !string.IsNullOrEmpty(linkedMMField.HeaderTypeProperty)))
					{
						arg.CanExecute = true;
						break;
					}
				}
			}
		}

		internal static void OnMoveFieldToCommand(object sender, ExecutedRoutedEventArgs arg)
		{
			Field field = arg.Parameter as Field;
			Field field2 = (sender as MenuItem).CommandParameter as Field;
			int column = field2.Column;
			int column2 = field.Column;
			if (column == column2)
			{
				return;
			}
			foreach (Field field3 in field.Owner.Fields)
			{
				if (column > column2)
				{
					if (field3 == field2)
					{
						field3.Column = column2 + 1;
					}
					else if (field3.Column > column2 && field3.Column < column)
					{
						field3.Column++;
					}
				}
				else if (column < column2)
				{
					if (field3 == field2)
					{
						field3.Column = column2;
					}
					else if (field3.Column <= column2 && field3.Column > column)
					{
						field3.Column--;
					}
				}
			}
		}

