			if (flag && mMScrollArea.DataGrid != null)
			{
				int num = -1;
				if (mMScrollArea.DataGrid.SelectedItems.Fields.Count > 0)
				{
					num = mMScrollArea.DataGrid.SelectedItems.Fields[0].Index;
				}
				else if (mMScrollArea.DataGrid.SelectedItems.Cells.Count > 0)
				{
					num = mMScrollArea.DataGrid.SelectedItems.Cells[0].Field.Index;
				}
				if (num < 0)
				{
					flag = false;
				}
				if (flag && mMScrollArea.DataGrid.DefaultFieldLayout != null && mMScrollArea.DataGrid.DefaultFieldLayout.Fields != null && mMScrollArea.DataGrid.DefaultFieldLayout.Fields.Count > num)
				{
					if (!(mMScrollArea.DataGrid.DefaultFieldLayout.Fields[num].Tag is MMScrollAreaField mMScrollAreaField))
					{
						flag = false;
					}
					else if (mMScrollAreaField.ExpandedFromRepeater == null)
					{
						flag = false;
					}
				}
			}
			arg.CanExecute = flag;
		}

