		internal static void OnDeleteRecordCommand(object sender, ExecutedRoutedEventArgs arg)
		{
			if (arg.Parameter is MMScrollArea mMScrollArea)
			{
				bool deleteAsColumn = false;
				if (mMScrollArea is MMHorizontalListEdit && mMScrollArea.DataGrid.SelectedItems.Cells.Count > 0)
				{
					deleteAsColumn = true;
				}
				else if (mMScrollArea.DataGrid.SelectedItems.Records.Count == 0 && mMScrollArea.DataGrid.SelectedItems.Cells.Count == 1 && mMScrollArea.DataGrid.SelectedItems.Fields.Count == 0)
				{
					mMScrollArea.DataGrid.SelectedItems.Cells[0].Record.IsSelected = true;
