		internal static void DoDeleteRecord(MMScrollArea sa, bool deleteAsColumn)
		{
			if (sa.DeleteRowCommand != null)
			{
				if (sa.DeleteRowCommand.CanExecute(null))
				{
					sa.DeleteRowCommand.Execute(null);
				}
			}
			else
			{
				if (!IsDeleteRecordCommandEnabled(sa) || !(sa.DataGrid.DataSource is CxvVectorPropertyData cxvVectorPropertyData))
				{
					return;
				}
				if (!deleteAsColumn)
				{
					AesMessageBoxResult aesMessageBoxResult = AesMessageBoxResult.None;
					aesMessageBoxResult = ((sa.DataOrientation != Orientation.Horizontal) ? AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strConfirmDeleteRecord, AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRow, AesMessageBoxButton.YesNo, AesMessageBoxImage.Question, showHelpButton: false, 2) : AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strConfirmDeleteField, AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteColumn, AesMessageBoxButton.YesNo, AesMessageBoxImage.Question, showHelpButton: false, 2));
					if (aesMessageBoxResult == AesMessageBoxResult.No || aesMessageBoxResult == AesMessageBoxResult.Cancel)
					{
						return;
					}
				}
				SortedSet<int> sortedSet = new SortedSet<int>();
				if (deleteAsColumn)
				{
					foreach (Cell cell in sa.DataGrid.SelectedItems.Cells)
					{
						if (!sortedSet.Contains(cell.Record.Index))
						{
							sortedSet.Add(cell.Record.Index);
						}
					}
				}
				else if (sa.DataGrid.DefaultFieldLayout.Fields.Where((Field f) => !f.IsExpandableResolved).Count() == sa.DataGrid.SelectedItems.Fields.Count)
				{
					foreach (Record item in (IEnumerable<Record>)sa.DataGrid.Records)
					{
						sortedSet.Add(item.Index);
					}
				}
				else
				{
					foreach (Record record in sa.DataGrid.SelectedItems.Records)
					{
						sortedSet.Add(sa.DataGrid.RecordManager.Unsorted.IndexOf(record as DataRecord));
					}
				}
				sa.ClearSelection();
				_ = sa.DataContext;
				bool flag = true;
				int count = cxvVectorPropertyData.Count;
				for (int num = sortedSet.Count - 1; num >= 0; num--)
				{
					try
					{
						cxvVectorPropertyData.RemoveAt(sortedSet.ToList()[num]);
					}
					catch (InvalidOperationException)
					{
					}
					catch (CxsException)
					{
						flag = false;
					}
					catch (Exception)
					{
					}
					if (count - cxvVectorPropertyData.Count >= sortedSet.Count)
					{
						break;
					}
				}
				if (!flag)
				{
					AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRowFailed, AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRow, AesMessageBoxButton.OK, AesMessageBoxImage.Error);
				}
			}
		}

		internal static bool IsDeleteRecordCommandEnabled(MMScrollArea sa)
		{
			bool result = false;
			if (!(sa.DataGrid.DataSource is CxvVectorPropertyData cxvVectorPropertyData))
			{
				return false;
			}
			if (sa is MMHorizontalListEdit)
			{
				if (sa.DataGrid.SelectedItems.Records.Count == 0 && sa.DataGrid.SelectedItems.Cells.Count >= 1)
				{
					foreach (Cell cell in sa.DataGrid.SelectedItems.Cells)
					{
						int num = sa.DataGrid.RecordManager.Unsorted.IndexOf(cell.Record);
						if (num < 0)
						{
							break;
						}
						if (cxvVectorPropertyData.IndexBasis.AllowRemoveAt(num))
						{
							result = true;
							break;
						}
					}
				}
			}
			else if (sa.DataGrid.SelectedItems.Records.Count == 0 && sa.DataGrid.SelectedItems.Cells.Count == 1)
			{
				int num2 = sa.DataGrid.RecordManager.Unsorted.IndexOf(sa.DataGrid.SelectedItems.Cells[0].Record);
				result = num2 >= 0 && cxvVectorPropertyData.IndexBasis.AllowRemoveAt(num2);
			}
			else if (sa.DataGrid.SelectedItems.Records.Count > 0)
			{
				bool flag = false;
				foreach (DataRecord record in sa.DataGrid.SelectedItems.Records)
				{
					if (record.NestingDepth > 0)
					{
						flag = false;
						break;
					}
					if (cxvVectorPropertyData.IndexBasis.AllowRemoveAt(sa.DataGrid.RecordManager.Unsorted.IndexOf(record)))
					{
						flag = true;
						break;
					}
				}
				result = flag;
			}
			else if (sa.DataGrid.DefaultFieldLayout.Fields.Where((Field f) => !f.IsExpandableResolved).Count() == sa.DataGrid.SelectedItems.Fields.Count)
			{
				result = true;
			}
			return result;
		}

		internal static void CanDeleteRecordCommand(object sender, CanExecuteRoutedEventArgs arg)
		{
			if (arg.Parameter is MMScrollArea mMScrollArea)
			{
				if (mMScrollArea.DeleteRowCommand != null)
				{
					arg.CanExecute = mMScrollArea.DeleteRowCommand.CanExecute(null);
				}
				else if (mMScrollArea.DataGrid.RecordManager.DataSourceAllowsDelete)
				{
					arg.CanExecute = IsDeleteRecordCommandEnabled(mMScrollArea);
				}
			}
		}

		internal static void OnInsertRecordCommand(object sender, ExecutedRoutedEventArgs arg)
		{
			if (!(arg.Parameter is MMScrollArea mMScrollArea) || mMScrollArea.DataGrid.SelectedItems == null || mMScrollArea.DataGrid.SelectedItems.Records == null || mMScrollArea.DataGrid.SelectedItems.Records.Count <= 0)
			{
				return;
			}
			Record record = mMScrollArea.DataGrid.SelectedItems.Records[0];
			if (record.DataPresenter.DataSource is IBindingList bindingList && record.Index >= 0)
			{
				bool flag = true;
				try
				{
					bindingList.Insert(record.Index, null);
				}
				catch (InvalidOperationException)
				{
					flag = false;
				}
				catch (CxsException)
				{
					flag = false;
				}
				if (!flag)
				{
					AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strInsertRowFailed, AspenTech.AspenPlus.MMControls.Properties.Resources.DialogTitle_InsertRecord, AesMessageBoxButton.OK, AesMessageBoxImage.Error);
				}
			}
		}

