				if (mMScrollArea.DataGrid.SelectedItems != null && mMScrollArea.DataGrid.SelectedItems.Records != null && mMScrollArea.DataGrid.SelectedItems.Records.Count > 0)
				{
					Record record = mMScrollArea.DataGrid.SelectedItems.Records[0];
					arg.CanExecute = record != null && record.NestingDepth == 0 && record.DataPresenter.RecordManager.DataSourceAllowsAddNew && (record.DataPresenter.SelectedItems.Records.Count == 1 || (record.DataPresenter.SelectedItems.Records.Count == 0 && record.DataPresenter.SelectedItems.Cells.Count == 1));
				}
				else
				{
					arg.CanExecute = false;
				}
			}
			else
			{
				arg.CanExecute = false;
			}
		}

		internal static void OnReorderCommand(object sender, ExecutedRoutedEventArgs arg)
		{
			if (!(arg.Parameter is MMScrollArea mMScrollArea))
			{
				return;
			}
			mMScrollArea.DataGrid.DefaultFieldLayout.SortedFields.Clear();
			MMScrollAreaReorderParameter mMScrollAreaReorderParameter = null;
			if (mMScrollArea.ReorderRowCommand != null && mMScrollArea.ReorderRowCommand.CanExecute(null))
			{
				mMScrollAreaReorderParameter = new MMScrollAreaReorderParameter
				{
					ScrollArea = mMScrollArea
				};
				mMScrollArea.ReorderRowCommand.Execute(mMScrollAreaReorderParameter);
			}
			if (mMScrollAreaReorderParameter != null && mMScrollAreaReorderParameter.Handled)
			{
				return;
			}
			MMScrollAreaReorder mMScrollAreaReorder = new MMScrollAreaReorder
			{
				AllowUseValueInReorder = mMScrollArea.AllowUseValueInReorder
			};
			if (mMScrollArea.DataContext is MMViewModel viewModel)
			{
				mMScrollAreaReorder.ViewModel = viewModel;
				mMScrollAreaReorder.DataProperty = mMScrollArea.DataProperty;
				mMScrollAreaReorder.ShowDialog();
				mMScrollArea.ClearSelection();
				if (mMScrollArea.DataGrid.Records.Count > 0 && mMScrollArea.DataGrid.DefaultFieldLayout.Fields.Count > 0)
				{
					mMScrollArea.DataGrid.ActiveCell = (mMScrollArea.DataGrid.Records[0] as DataRecord).Cells[0];
					mMScrollArea.SetSelection((mMScrollArea.DataGrid.Records[0] as DataRecord).Cells[0]);
				}
			}
		}

