				arg.CanExecute = mMScrollArea.AllowReorderResolved && HaveValidRecords(mMScrollArea);
			}
		}

		private static bool HaveValidRecords(MMScrollArea sa)
		{
			if (sa.DataGrid.Records == null)
			{
				return false;
			}
			if (sa.DataGrid.RecordManager.DataSourceAllowsAddNew)
			{
				return sa.DataGrid.Records.Count > 2;
			}
			return sa.DataGrid.Records.Count >= 2;
		}

