			{
				mMScrollArea.DoSelectAll();
				if (mMScrollArea.IsBoundToPlainDataSource)
				{
					Thread.Sleep(10);
					mMScrollArea.DataGrid.ExecuteCommand(DataPresenterCommands.Copy);
				}
				else
				{
					SetClipboardData(mMScrollArea);
				}
			}
		}

		internal static void SetClipboardData(MMScrollArea sa)
		{
			if (sa.ContainsHierachy)
			{
				Thread.Sleep(10);
				sa.DataGrid.ExecuteCommand(DataPresenterCommands.Copy);
				return;
			}
			try
			{
				DoSetClipboardData(sa);
			}
			catch (Exception)
			{
				try
				{
					DoSetClipboardData(sa);
				}
				catch (Exception)
				{
					AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strCanOpenClipboard);
				}
			}
		}

		private static void DoSetClipboardData(MMScrollArea sa)
		{
			if (sa.ClipboardDataObject != null)
			{
				sa.ClipboardDataObject.Dispose();
			}
			sa.ClipboardDataObject = new DataObjectLateGen();
			sa.ClipboardDataObject.IncludeColumnHeader = sa.DataGrid.SelectedItems.Fields.Count > 0;
			sa.ClipboardDataObject.SetData(typeof(MMScrollArea), sa);
			List<IGridCellData> list = new List<IGridCellData>();
			int num = 0;
			int num2 = -1;
			int num3 = -1;
			if (sa.ClipboardDataObject.IncludeColumnHeader)
			{
				foreach (Field field in sa.DataGrid.SelectedItems.Fields)
				{
					if (field != null)
					{
						string textValue = ((field.Label is LabelHeader labelHeader) ? labelHeader.LabelText : ((field.Label != null) ? field.Label.ToString() : string.Empty));
						CxsGridCellData item = new CxsGridCellData
						{
							TextValue = textValue,
							ColumnIndex = field.Index,
							RowIndex = 0
						};
						list.Add(item);
						num2 = 0;
					}
				}
			}
			foreach (MMScrollAreaSelectedCell item3 in sa.ClipboardDataObject.SelectedCellsSorted)
			{
				int num4 = item3.Record.DisplayIndex;
				if (sa.ClipboardDataObject.IncludeColumnHeader)
				{
					num4++;
				}
				int index = item3.Field.Field.Index;
				if (num2 == -1 || num4 < num2)
				{
					num2 = num4;
				}
				if (num3 == -1 || index < num3)
				{
					num3 = index;
				}
				bool flag = false;
				if (item3.Field != null)
				{
					flag = item3.Field.GetType() == typeof(MMScrollAreaTextField);
				}
				CxsGridCellData item2 = new CxsGridCellData
				{
					Moniker = (flag ? string.Empty : sa.ClipboardDataObject.GetCellMoniker(item3)),
					RowIndex = num4,
					ColumnIndex = index,
					TextValue = sa.ClipboardDataObject.GetCellValue(item3)
				};
				list.Add(item2);
				num++;
			}
			foreach (IGridCellData item4 in list)
			{
				item4.RowIndex -= num2;
				item4.ColumnIndex -= num3;
			}
			ClipboardHelper.CreateClipboard(list, sa.ClipboardDataObject.Value, sa.ClipboardDataObject.CaseFullFileName, sa.ClipboardDataObject.ApplicationName);
		}

		internal static void OnSelectAllCommand(object sender, ExecutedRoutedEventArgs arg)
		{
			MMScrollAreaBase mMScrollAreaBase = arg.Parameter as MMScrollAreaBase;
			if (mMScrollAreaBase.IsAllSelected)
			{
				mMScrollAreaBase.ClearSelection();
			}
			else
			{
				mMScrollAreaBase.DoSelectAll();
			}
		}

		internal static void OnPasteCommand(object sender, ExecutedRoutedEventArgs arg)
		{
			MMScrollAreaBase mMScrollAreaBase = arg.Parameter as MMScrollAreaBase;
			if (mMScrollAreaBase.PasteCommand == null)
			{
				if (mMScrollAreaBase is MMHorizontalListEdit hle)
				{
					DoPaste(hle);
				}
				else
				{
					DoPaste(mMScrollAreaBase);
				}
			}
			else
			{
				mMScrollAreaBase.PasteCommand.Execute(null);
			}
		}

		internal static void DoPaste(MMHorizontalListEdit hle)
		{
			Cell topLeftCellFromSelection = GetTopLeftCellFromSelection(hle);
			if (topLeftCellFromSelection == null)
			{
				return;
			}
			int num = topLeftCellFromSelection.Record.Index;
			try
			{
				string[] array = ClipboardWrapper.GetText().Split('\t');
				for (int i = 0; i < array.Length; i++)
				{
					(hle.DataGrid.Records[num] as DataRecord).Cells[0].Value = array[i];
					num++;
				}
			}
			catch (Exception)
			{
			}
		}

		private static void DoPasteForHorizontal(MMScrollArea sa)
		{
			Mouse.OverrideCursor = Cursors.Wait;
			CxsDataProvider cxsDataProvider = null;
			try
			{
				Cell topLeftCellFromSelectionHorizontal = GetTopLeftCellFromSelectionHorizontal(sa);
				if (topLeftCellFromSelectionHorizontal == null)
				{
					return;
				}
				CellValuePresenter cellValuePresenter = CellValuePresenter.FromCell(topLeftCellFromSelectionHorizontal);
				if (cellValuePresenter == null || !MMScrollAreaBase.IsCellEditable(cellValuePresenter))
				{
					return;
				}
				int num = topLeftCellFromSelectionHorizontal.Field.ActualPosition.Row;
				int visibleIndex = topLeftCellFromSelectionHorizontal.Record.VisibleIndex;
				List<string> list = ClipboardWrapper.GetText().Split('\n').ToList();
				int startRowIndexForPaste = GetStartRowIndexForPaste();
				if (list.Count > 0 && string.IsNullOrEmpty(list[list.Count - 1]))
				{
					list.RemoveAt(list.Count - 1);
				}
				if (sa.DataContext is CxvViewModel cxvViewModel)
				{
					cxsDataProvider = cxvViewModel.ResolvedCxsProvider;
					if (cxsDataProvider != null)
					{
						cxsDataProvider.Force = true;
						cxsDataProvider.StartBatchPaste();
					}
				}
				for (int i = 0; i < list.Count; i++)
				{
					string[] array = list[i].Replace("\r", "").Split('\t');
					int num2 = visibleIndex;
					int count = sa.DataGrid.Records.Count;
					int num3 = startRowIndexForPaste;
					while (num3 < array.Length)
					{
						string text = array[num3];
						if (num2 == count)
						{
							count = sa.DataGrid.Records.Count;
							if (num2 == count)
							{
								break;
							}
						}
						try
						{
							Cell cell = (sa.DataGrid.Records[num2] as DataRecord).Cells[num];
							CellValuePresenter cellValuePresenter2 = CellValuePresenter.FromCell(cell);
							if (cellValuePresenter2 != null)
							{
								if (cellValuePresenter2.Editor is AesXamValueEdit || cellValuePresenter2.Editor is AesXamComboEdit)
								{
									ApplicationCommands.Paste.Execute((text == null) ? string.Empty : text, cellValuePresenter2.Editor);
								}
							}
							else
							{
								cell.Value = ((text == string.Empty) ? null : text);
							}
						}
						catch (Exception)
						{
						}
						num3++;
						num2++;
					}
					num++;
				}
			}
			catch (Exception)
			{
				AesMessageBox.Show(Window.GetWindow(sa), AspenTech.AspenPlus.MMControls.Properties.Resources.strFailedToPaste);
			}
			finally
			{
				if (cxsDataProvider != null)
				{
					cxsDataProvider.Force = false;
					cxsDataProvider.EndBatchPaste();
				}
				Mouse.OverrideCursor = null;
			}
		}

		internal static void DoPaste(MMScrollAreaBase sab)
		{
			MMScrollArea mMScrollArea = sab as MMScrollArea;
			if (mMScrollArea != null && mMScrollArea.ContainsHierachy)
			{
				sab.DataGrid.ExecuteCommand(DataPresenterCommands.Paste);
				return;
			}
			if (mMScrollArea.DataOrientation == Orientation.Horizontal)
			{
				DoPasteForHorizontal(mMScrollArea);
				return;
			}
			bool flag = mMScrollArea.DataGrid.SelectedItems.Cells.Count <= 0;
			Cell topLeftCellFromSelection = GetTopLeftCellFromSelection(sab);
			CxvViewModel cxvViewModel = null;
			CxsDataProvider cxsDataProvider = null;
			if (topLeftCellFromSelection == null)
			{
				return;
			}
			CellValuePresenter cellValuePresenter = CellValuePresenter.FromCell(topLeftCellFromSelection);
			if (cellValuePresenter == null || !MMScrollAreaBase.IsCellEditable(cellValuePresenter))
			{
				return;
			}
			int num = topLeftCellFromSelection.Record.Index;
			int num2 = num;
			int column = topLeftCellFromSelection.Field.ActualPosition.Column;
			int startRowIndexForPaste = GetStartRowIndexForPaste();
			try
			{
				string text = string.Empty;
				if (flag && ClipboardWrapper.ContainsData("Grid Text") && ClipboardWrapper.GetData("Grid Text") is MemoryStream stream)
				{
					text = new StreamReader(stream).ReadToEnd();
				}
				if (string.IsNullOrEmpty(text) && ClipboardWrapper.ContainsData("AP_Text") && ClipboardWrapper.GetData("AP_Text") is MemoryStream stream2)
				{
					text = new StreamReader(stream2).ReadToEnd();
				}
				if (string.IsNullOrEmpty(text))
				{
					text = ClipboardWrapper.GetText();
				}
				List<string> list = text.Split('\n').ToList();
				RemoveEmptyRows(list);
				if ((mMScrollArea.TransposeHorizontalListToVerticalForPaste ?? false) && list != null && list.Count == 1 && list[0].Contains("\t"))
				{
					string text2 = list[0].Replace("\t", "\r");
					if (!string.IsNullOrEmpty(text2))
					{
						string[] array = text2.Split('\r');
						if (array != null && array.Length != 0)
						{
							list.Clear();
							string[] array2 = array;
							foreach (string text3 in array2)
							{
								if (!string.IsNullOrEmpty(text3))
								{
									list.Add(text3 + "\r");
								}
							}
						}
					}
				}
				if (sab.DataContext is CxvViewModel cxvViewModel2)
				{
					cxsDataProvider = cxvViewModel2.ResolvedCxsProvider;
					if (cxsDataProvider != null)
					{
						cxsDataProvider.SuspendNotifications();
						cxsDataProvider.Force = true;
						if (list.Count > 1 || (list.Count == 1 && list[0].Contains('\t')))
						{
							cxsDataProvider.StartBatchPaste();
						}
					}
				}
				CxvVectorPropertyData cxvVectorPropertyData = sab.DataGrid.DataSource as CxvVectorPropertyData;
				int count = sab.DataGrid.DefaultFieldLayout.Fields.Count;
				for (int j = startRowIndexForPaste; j < list.Count; j++)
				{
					if (num >= sab.DataGrid.Records.Count)
					{
						int num3 = num;
						if (!(cxvVectorPropertyData.IndexBasis is CxvChildCountIndexBasisData cxvChildCountIndexBasisData) || !cxvVectorPropertyData.AllowNew || (cxvChildCountIndexBasisData.IndexBasis != null && cxvChildCountIndexBasisData.IndexBasis.MaximumRows.HasValue && sab.DataGrid.Records.Count >= cxvChildCountIndexBasisData.IndexBasis.MaximumRows.Value))
						{
							break;
						}
						if (cxvChildCountIndexBasisData.HasProxyRow)
						{
							num3--;
						}
						cxvVectorPropertyData.Insert(num3, null);
					}
					num++;
				}
				if (cxsDataProvider != null)
				{
					cxsDataProvider.ResumeNotifications();
					cxsDataProvider.UpdateDataCache();
					cxsDataProvider.SuspendNotifications();
				}
				num = num2;
				for (int k = startRowIndexForPaste; k < list.Count; k++)
				{
					string text4 = list[k].Replace("\r", "");
					if (num == mMScrollArea.DataGrid.Records.Count)
					{
						break;
					}
					string[] array3 = text4.Split('\t');
					int num4 = column;
					int num5 = 0;
					while (num5 < array3.Length)
					{
						string text5 = array3[num5];
						if (num4 == count)
						{
							cxsDataProvider.ResumeNotifications();
							count = sab.DataGrid.DefaultFieldLayout.Fields.Count;
							cxsDataProvider.SuspendNotifications();
							if (num4 == count)
							{
								break;
							}
						}
						Cell cell = (mMScrollArea.DataGrid.Records[num] as DataRecord).Cells[GetFieldIndexByActualPosition(mMScrollArea, num4)];
						CellValuePresenter cellValuePresenter2 = CellValuePresenter.FromCell(cell);
						if (cellValuePresenter2 == null)
						{
							sab.Dispatcher.Invoke(delegate
							{
							}, DispatcherPriority.Loaded);
							cellValuePresenter2 = CellValuePresenter.FromCell(cell);
						}
						if (cellValuePresenter2 != null)
						{
							if (cellValuePresenter2.Editor is AesXamValueEdit || cellValuePresenter2.Editor is AesXamComboEdit)
							{
								bool flag2 = ApplicationCommands.Paste.CanExecute((text5 == null) ? string.Empty : text5, cellValuePresenter2.Editor);
								if (mMScrollArea.MMFields.Count > num5 && mMScrollArea.MMFields[num5].AllowPaste.HasValue && !mMScrollArea.MMFields[num5].AllowPaste.Value)
								{
									cxsDataProvider.ShowMessageBox(new ShowMessageBoxEventArgs
									{
										Title = "Paste Error",
										Message = "This field (" + mMScrollArea.MMFields[num5].Label + ") does not allow paste."
									});
								}
								else if (flag2)
								{
									ApplicationCommands.Paste.Execute((text5 == null) ? string.Empty : text5, cellValuePresenter2.Editor);
								}
								else if (!string.IsNullOrEmpty(text5) && !cellValuePresenter2.Editor.IsReadOnly)
								{
									cxsDataProvider.BatchPasteError();
								}
							}
						}
						else
						{
							cell.Value = ((text5 == string.Empty) ? null : text5);
						}
						num5++;
						num4++;
					}
					num++;
				}
			}
			catch (Exception)
			{
				AesMessageBox.Show(Window.GetWindow(sab), AspenTech.AspenPlus.MMControls.Properties.Resources.strFailedToPaste + " " + AspenTech.AspenPlus.MMControls.Properties.Resources.strCheckClipboard, AspenTech.AspenPlus.MMControls.Properties.Resources.strPaste, AesMessageBoxButton.OK, AesMessageBoxImage.Error);
			}
			finally
			{
				if (cxsDataProvider != null)
				{
					cxsDataProvider.ResumeNotifications();
					cxsDataProvider.Force = false;
					cxsDataProvider.EndBatchPaste();
				}
			}
		}

		internal static int GetFieldIndexByActualPosition(MMScrollArea sa, int index)
		{
			try
			{
				foreach (Field field in sa.DataGrid.DefaultFieldLayout.Fields)
				{
					if (field.ActualPosition.Column == index)
					{
						return field.Index;
					}
				}
			}
			catch
			{
			}
			return index;
		}

		internal static int GetStartRowIndexForPaste()
		{
			int result = 0;
			if (ClipboardWrapper.GetData("DatagridMetadata") is MemoryStream stream)
			{
				string text = new StreamReader(stream).ReadToEnd();
				if (text != null && !string.IsNullOrEmpty(text.Trim()))
				{
					result = int.Parse(text.Split('=')[1]);
				}
			}
			return result;
		}

		internal static Cell GetTopLeftCellFromSelection(MMScrollAreaBase sa)
		{
			Cell cell = null;
			try
			{
				if (sa.DataGrid.SelectedItems.Cells.Count > 0)
				{
					foreach (Cell cell2 in sa.DataGrid.SelectedItems.Cells)
					{
						if (cell == null || cell2.Record.Index < cell.Record.Index || (cell2.Record.Index < cell.Record.Index && cell2.Field.Index < cell.Field.Index))
						{
							cell = cell2;
						}
					}
				}
				else if (sa.DataGrid.SelectedItems.Fields.Count > 0 && sa.DataGrid.Records.Count > 0)
				{
					foreach (Field field2 in sa.DataGrid.SelectedItems.Fields)
					{
						if (cell == null || field2.ActualPosition.Column < cell.Field.ActualPosition.Column)
						{
							cell = (sa.DataGrid.Records[0] as DataRecord).Cells[field2];
						}
					}
				}
				else if (sa.DataGrid.SelectedItems.Records.Count > 0)
				{
					DataRecord dataRecord = sa.DataGrid.SelectedItems.Records.OfType<DataRecord>().FirstOrDefault();
					Field field = sa.DataGrid.FieldLayouts[0].Fields.FirstOrDefault();
					if (dataRecord != null && field != null)
					{
						cell = dataRecord.Cells[field];
					}
				}
			}
			catch (Exception)
			{
			}
			return cell;
		}

		internal static Cell GetTopLeftCellFromSelectionHorizontal(MMScrollArea sa)
		{
			Cell cell = null;
			try
			{
				if (sa.DataGrid.SelectedItems.Cells.Count > 0)
				{
					foreach (Cell cell2 in sa.DataGrid.SelectedItems.Cells)
					{
						if (cell == null || cell2.Field.ActualPosition.Column < cell.Field.ActualPosition.Column || (cell2.Field.ActualPosition.Column < cell.Field.ActualPosition.Column && cell2.Record.VisibleIndex < cell.Record.VisibleIndex))
						{
							cell = cell2;
						}
					}
				}
			}
			catch (Exception)
			{
			}
			return cell;
		}

		internal static void CanPasteCommand(object sender, CanExecuteRoutedEventArgs arg)
		{
			if (!(arg.Parameter is MMScrollAreaBase mMScrollAreaBase))
			{
				return;
			}
			if (mMScrollAreaBase.DataOrientation == Orientation.Horizontal)
			{
				arg.CanExecute = true;
			}
			else if (mMScrollAreaBase.PasteCommand == null)
			{
				if (ClipboardWrapper.GetData(DataFormats.Text) == null)
				{
					arg.CanExecute = false;
				}
				else
				{
					arg.CanExecute = IsAllSelectedCellsPastable(mMScrollAreaBase);
				}
			}
			else
			{
				arg.CanExecute = mMScrollAreaBase.PasteCommand.CanExecute(null);
			}
		}

		internal static void OnPasteField(object sender, ExecutedRoutedEventArgs arg)
		{
			if (arg.Parameter is MMScrollArea sab)
			{
				DoPaste(sab);
			}
		}

		internal static void CanPasteField(object sender, CanExecuteRoutedEventArgs arg)
		{
			arg.CanExecute = false;
			if (!(arg.Parameter is MMScrollArea sa))
			{
				return;
			}
			Cell topLeftCellFromSelection = GetTopLeftCellFromSelection(sa);
			if (topLeftCellFromSelection != null)
			{
				CellValuePresenter cellValuePresenter = CellValuePresenter.FromCell(topLeftCellFromSelection);
				if (cellValuePresenter != null && MMScrollAreaBase.IsCellEditable(cellValuePresenter))
				{
					arg.CanExecute = true;
				}
			}
		}

		internal static void OnClearCell(object sender, ExecutedRoutedEventArgs arg)
		{
			(arg.Parameter as MMScrollAreaBase).ClearSelectedCells(cellOnly: false);
		}

		internal static void CanClearCell(object sender, CanExecuteRoutedEventArgs arg)
		{
			MMScrollAreaBase mMScrollAreaBase = arg.Parameter as MMScrollAreaBase;
			arg.CanExecute = false;
			if (mMScrollAreaBase.DataGrid.SelectedItems.Cells.Count > 0)
			{
				foreach (Cell cell in mMScrollAreaBase.DataGrid.SelectedItems.Cells)
				{
					CellValuePresenter cellValuePresenter = CellValuePresenter.FromCell(cell);
					if (cellValuePresenter != null && IsCellClearable(cellValuePresenter))
					{
						arg.CanExecute = true;
						break;
					}
				}
				return;
			}
			if (mMScrollAreaBase.DataGrid.SelectedItems.Fields.Count > 0)
			{
				foreach (Field field in mMScrollAreaBase.DataGrid.SelectedItems.Fields)
				{
					foreach (DataRecord item in mMScrollAreaBase.DataGrid.Records.OfType<DataRecord>())
					{
						CellValuePresenter cellValuePresenter2 = CellValuePresenter.FromRecordAndField(item, field);
						if (cellValuePresenter2 != null && IsCellClearable(cellValuePresenter2))
						{
							arg.CanExecute = true;
							break;
						}
					}
				}
				return;
			}
			if (mMScrollAreaBase.DataGrid.SelectedItems.Records.Count <= 0)
			{
				return;
			}
			foreach (DataRecord record in mMScrollAreaBase.DataGrid.SelectedItems.Records)
			{
				foreach (Field field2 in mMScrollAreaBase.DataGrid.DefaultFieldLayout.Fields)
				{
					try
					{
						CellValuePresenter cellValuePresenter3 = CellValuePresenter.FromCell(record.Cells[field2]);
						if (cellValuePresenter3 != null && IsCellClearable(cellValuePresenter3))
						{
							arg.CanExecute = true;
							break;
						}
					}
					catch (IndexOutOfRangeException)
					{
					}
				}
			}
		}

		internal static bool IsCellClearable(CellValuePresenter cvp)
		{
			bool result = false;
			if (MMScrollAreaBase.IsCellEditable(cvp))
			{
				if (cvp.Editor != null && (cvp.Editor is AesXamValueEdit || cvp.Editor is AesXamComboEdit || cvp.Editor is AesXamCheckEdit))
				{
					if (cvp.Editor is AesXamValueEdit)
					{
						AesXamValueEdit aesXamValueEdit = cvp.Editor as AesXamValueEdit;
						if (aesXamValueEdit.Variable != null && aesXamValueEdit.Variable is CxvVariableData)
						{
							CxvVariableData cxvVariableData = aesXamValueEdit.Variable as CxvVariableData;
							if ((cxvVariableData.IsCalculated.HasValue && cxvVariableData.IsCalculated.Value) || (cxvVariableData.IsEntered.HasValue && cxvVariableData.IsEntered.Value))
							{
								result = true;
							}
						}
					}
					else if (cvp.Editor is AesXamCheckEdit)
					{
						AesXamCheckEdit aesXamCheckEdit = cvp.Editor as AesXamCheckEdit;
						if (aesXamCheckEdit.Variable is CxvBooleanPropertyData)
						{
							result = (aesXamCheckEdit.Variable as CxvBooleanPropertyData).CanClear != false;
						}
					}
					else
					{
						AesXamComboEdit aesXamComboEdit = cvp.Editor as AesXamComboEdit;
						if (aesXamComboEdit.DisallowClear.HasValue && aesXamComboEdit.DisallowClear.Value)
						{
							result = false;
						}
						else if (aesXamComboEdit.Variable != null)
						{
							if (aesXamComboEdit.Variable is CxvVariableData)
							{
								CxvVariableData cxvVariableData2 = aesXamComboEdit.Variable as CxvVariableData;
								if ((cxvVariableData2.IsCalculated.HasValue && cxvVariableData2.IsCalculated.Value) || (cxvVariableData2.IsEntered.HasValue && cxvVariableData2.IsEntered.Value))
								{
									result = true;
								}
							}
							else if (aesXamComboEdit.Variable is CxvMultiMapPropertyData)
							{
								CxvMultiMapPropertyData cxvMultiMapPropertyData = aesXamComboEdit.Variable as CxvMultiMapPropertyData;
								if ((cxvMultiMapPropertyData.IsCalculated.HasValue && cxvMultiMapPropertyData.IsCalculated.Value) || (cxvMultiMapPropertyData.IsEntered.HasValue && cxvMultiMapPropertyData.IsEntered.Value))
								{
									result = true;
								}
							}
						}
					}
				}
				else
				{
					result = true;
				}
			}
			return result;
		}

		private static bool IsAllSelectedCellsPastable(MMScrollAreaBase sa)
		{
			bool flag = true;
			if (sa.DataGrid.SelectedItems.Cells.Count > 0)
			{
				foreach (Cell cell in sa.DataGrid.SelectedItems.Cells)
				{
					CellValuePresenter cellValuePresenter = CellValuePresenter.FromCell(cell);
					if (cellValuePresenter != null && !MMScrollAreaBase.IsCellEditable(cellValuePresenter))
					{
						flag = false;
						break;
					}
				}
			}
			else if (sa.DataGrid.SelectedItems.Fields.Count > 0)
			{
				foreach (Field field in sa.DataGrid.SelectedItems.Fields)
				{
					if (field.Owner != sa.DataGrid.DefaultFieldLayout)
					{
						flag = false;
						break;
					}
					foreach (DataRecord item in (IEnumerable<Record>)sa.DataGrid.Records)
					{
						CellValuePresenter cellValuePresenter2 = CellValuePresenter.FromRecordAndField(item, field);
						if (cellValuePresenter2 != null && !MMScrollAreaBase.IsCellEditable(cellValuePresenter2))
						{
							flag = false;
							break;
						}
					}
					if (!flag)
					{
						break;
					}
				}
			}
			else if (sa.DataGrid.SelectedItems.Records.Count > 0)
			{
				foreach (DataRecord record in sa.DataGrid.SelectedItems.Records)
				{
					foreach (Field field2 in sa.DataGrid.DefaultFieldLayout.Fields)
					{
						CellValuePresenter cellValuePresenter3 = CellValuePresenter.FromRecordAndField(record, field2);
						if (cellValuePresenter3 != null && !MMScrollAreaBase.IsCellEditable(cellValuePresenter3))
						{
							flag = false;
							break;
						}
					}
				}
			}
			return flag;
		}

