		internal static void SetClipboardData(MMScrollArea sa, ICollection<string> monikers)
		{
			if (sa.ContainsHierachy)
			{
				return;
			}
			try
			{
				DoSetClipboardData(sa, monikers);
			}
			catch (Exception)
