		private static void DoSetClipboardData(MMScrollArea sa, ICollection<string> monikers)
		{
			DataObjectLateGen dataObjectLateGen = new DataObjectLateGen();
			dataObjectLateGen.IncludeColumnHeader = sa.DataGrid.SelectedItems.Fields.Count > 0;
			dataObjectLateGen.SetData(typeof(MMScrollArea), sa);
			foreach (string item in dataObjectLateGen.MonikersWithValue)
			{
				if (!string.IsNullOrEmpty(item) && !monikers.Contains(item))
				{
					monikers.Add(item);
				}
			}
		}

		private static void RemoveEmptyRows(List<string> rows)
		{
			int num = 0;
			while (num < rows.Count)
			{
				if (string.IsNullOrEmpty(rows[num].Replace("\t", "").Replace("\r", "").Trim()))
				{
					rows.RemoveAt(num);
				}
				else
				{
					num++;
				}
			}
		}
	}
