		private static string GetPropPath(MMScrollAreaSelectedCell cell)
		{
			return cell.Field.PropertyPath;
		}

		private static string GetPropPathHorizontal(MMScrollAreaSelectedCell cell)
		{
			MMScrollAreaHorizontal mMScrollAreaHorizontal = cell.Field.ParentScrollArea as MMScrollAreaHorizontal;
			int num = cell.Field.Id - 1;
			if (mMScrollAreaHorizontal.IsUnitsVisible)
			{
				num--;
			}
			if (num >= 0)
			{
				return mMScrollAreaHorizontal.DataProperty + "[" + num.ToString(CultureInfo.InvariantCulture) + "]." + cell.Field.PropertyPath;
			}
			return null;
		}

		private static void AddCellToSelection(IManualLayout sa, List<MMScrollAreaSelectedCell> selectedCells, Record record, Field field)
		{
			if (field.VisibilityResolved == Visibility.Visible && sa.MMRecords[record.Index].IsVisible && field.Index < sa.MMRecords[record.Index].Fields.Count)
			{
				MMScrollAreaSelectedCell mMScrollAreaSelectedCell = new MMScrollAreaSelectedCell
				{
					Field = sa.MMRecords[record.Index].Fields[field.Index],
					Record = new MMScrollAreaSelectedRecord
					{
						Index = (record as DataRecord).DataItemIndex,
						DisplayIndex = (record as DataRecord).VisibleIndex
					}
				};
				mMScrollAreaSelectedCell.Field.Id = field.Index;
				if (!selectedCells.Contains(mMScrollAreaSelectedCell))
				{
					selectedCells.Add(mMScrollAreaSelectedCell);
				}
			}
		}

		internal static void DoPaste(MMScrollAreaBase sab)
		{
			MMScrollAreaHorizontal mMScrollAreaHorizontal = sab as MMScrollAreaHorizontal;
			IManualLayout manualLayout = sab as IManualLayout;
			IEnumerable<Cell> pastingTargetCells = GetPastingTargetCells(sab);
			if (pastingTargetCells.Any())
			{
				string[] array = new string[0];
				try
				{
					array = ClipboardWrapper.GetText().Split('\n');
				}
				catch
				{
				}
				if (array.Length != 0)
				{
					string[] array2 = array[0].Replace("\r", "").Split('\t');
					if (array2.Length != 0)
					{
						Cell cell = pastingTargetCells.FirstOrDefault();
						if (cell != null)
						{
							CellValuePresenter cellValuePresenter = CellValuePresenter.FromCell(cell);
							if (cellValuePresenter != null && Infragistics.Windows.Utilities.GetDescendantFromType(cellValuePresenter, typeof(MMLabel), allowSubclassOfType: false) is MMLabel { IsVisible: not false, Content: not null } mMLabel && mMLabel.Content.ToString() != array2[0])
							{
								return;
							}
						}
					}
				}
				Cell cell2 = null;
				foreach (Cell item in pastingTargetCells)
				{
					if (cell2 == null)
					{
						cell2 = item;
					}
					else if (item.Record.Index < cell2.Record.Index || (item.Record.Index < cell2.Record.Index && item.Field.Index < cell2.Field.Index))
					{
						cell2 = item;
					}
				}
				CxvViewModel cxvViewModel = sab.DataContext as CxvViewModel;
				CxsDataProvider cxsDataProvider = null;
				cxsDataProvider = cxvViewModel.ResolvedCxsProvider;
				int num = cell2.Record.Index;
				int index = cell2.Field.Index;
				for (int i = MMScrollAreaCommand.GetStartRowIndexForPaste(); i < array.Length && !string.IsNullOrEmpty(array[i]); i++)
				{
					string[] array3 = array[i].Replace("\r", "").Split('\t');
					int num2 = index;
					string[] array4 = array3;
					foreach (string value in array4)
					{
						if (num2 >= sab.DataGrid.DefaultFieldLayout.Fields.Count)
						{
							break;
						}
						try
						{
							MMScrollAreaSelectedCell cell3 = new MMScrollAreaSelectedCell
							{
								Field = manualLayout.MMRecords[num].Fields[num2],
								Record = new MMScrollAreaSelectedRecord
								{
									Index = num
								}
							};
							if (mMScrollAreaHorizontal != null)
							{
								DataObjectLateGen.SetValueForSelection(cell3, cxvViewModel, GetPropPathHorizontal, value);
							}
							else
							{
								DataObjectLateGen.SetValueForSelection(cell3, cxvViewModel, GetPropPath, value);
							}
							cxsDataProvider?.UpdateDataCache();
						}
						catch (Exception)
						{
						}
						num2++;
					}
					num++;
				}
			}
			Mouse.SetCursor(Cursors.Arrow);
		}

		private static IEnumerable<Cell> GetPastingTargetCells(MMScrollAreaBase sab)
		{
			DataPresenterBase.SelectedItemHolder selectedItems = sab.DataGrid.SelectedItems;
			foreach (Cell cell in selectedItems.Cells)
			{
				yield return cell;
			}
			foreach (Field f in selectedItems.Fields)
			{
				foreach (Record item in (IEnumerable<Record>)sab.DataGrid.Records)
				{
					if (item is DataRecord)
					{
						yield return ((DataRecord)item).Cells[f];
					}
				}
			}
			foreach (Record record in selectedItems.Records)
			{
				if (!(record is DataRecord))
				{
					continue;
				}
				foreach (Cell item2 in (IEnumerable<Cell>)((DataRecord)record).Cells)
				{
					yield return item2;
				}
			}
		}

		internal static void OnPasteCommand(object sender, ExecutedRoutedEventArgs arg)
		{
			if (arg.Parameter is MMScrollAreaBase mMScrollAreaBase)
			{
				Mouse.SetCursor(Cursors.Wait);
				mMScrollAreaBase.Dispatcher.BeginInvoke(new DoPasteDelegate(DoPaste), mMScrollAreaBase);
			}
		}

		internal static void CanPasteCommand(object sender, CanExecuteRoutedEventArgs arg)
		{
			MMScrollAreaBase mMScrollAreaBase = arg.Parameter as MMScrollAreaBase;
			bool canExecute = false;
			if (ClipboardWrapper.GetData(DataFormats.Text) == null)
			{
				return;
			}
			bool? isCalculated;
			if (mMScrollAreaBase.AllowEdit.HasValue && !mMScrollAreaBase.AllowEdit.Value)
			{
				canExecute = false;
			}
			else if (IsSelectedCellsEditable(mMScrollAreaBase, out isCalculated))
			{
				canExecute = true;
			}
			else if (isCalculated.HasValue && isCalculated.Value)
			{
				canExecute = false;
			}
			else
			{
				object text = ClipboardWrapper.GetText();
				if (text != null)
				{
					string text2 = text.ToString();
					if (text2.Contains("\t") || text2.Contains(Environment.NewLine))
					{
						canExecute = true;
					}
				}
			}
			arg.CanExecute = canExecute;
		}

		private static bool IsSelectedCellsEditable(MMScrollAreaBase sab, out bool? isCalculated)
		{
			bool result = true;
			isCalculated = null;
			if (sab != null)
			{
				if (sab.AllowEdit.HasValue && !sab.AllowEdit.Value)
				{
					result = false;
				}
				else
				{
					Cell cell = null;
					if (sab.DataGrid.SelectedItems.Fields.Count > 0 && sab.DataGrid.Records.Count > 0)
					{
						result = false;
					}
					else if (sab.DataGrid.SelectedItems.Records.Count > 0)
					{
						result = false;
					}
					else if (sab.DataGrid.SelectedItems.Cells.Count > 1)
					{
						result = false;
					}
					else if (sab.DataGrid.SelectedItems.Cells.Count == 1)
					{
						cell = sab.DataGrid.SelectedItems.Cells[0];
					}
					if (cell != null)
					{
						CellValuePresenter cellValuePresenter = CellValuePresenter.FromCell(cell);
						if (cellValuePresenter != null)
						{
							ValueEditor valueEditor = null;
							CxvVariableData cxvVariableData = null;
							if (Infragistics.Windows.Utilities.GetDescendantFromType(cellValuePresenter, typeof(MMComboEdit), allowSubclassOfType: false) is MMComboEdit mMComboEdit)
							{
								cxvVariableData = mMComboEdit.Variable as CxvVariableData;
								if (mMComboEdit.Variable is ICxvObjectVerbs cxvObjectVerbs)
								{
									CxvVerbDescriptor cxvVerbDescriptor = cxvObjectVerbs.FindVerb("Delete");
									if (cxvVerbDescriptor != null)
									{
										result = cxvVerbDescriptor.Enabled;
										if (cxvVariableData != null)
										{
											isCalculated = cxvVariableData.IsCalculated;
										}
										return result;
									}
								}
								valueEditor = Infragistics.Windows.Utilities.GetDescendantFromType(mMComboEdit, typeof(AesXamComboEdit), allowSubclassOfType: false) as AesXamComboEdit;
							}
							if (valueEditor == null)
							{
								valueEditor = Infragistics.Windows.Utilities.GetDescendantFromType(cellValuePresenter, typeof(AesXamValueEdit), allowSubclassOfType: true) as AesXamValueEdit;
								if (valueEditor != null)
								{
									cxvVariableData = (valueEditor as AesXamValueEdit).Variable as CxvVariableData;
									if (cxvVariableData != null)
									{
										isCalculated = cxvVariableData.IsCalculated;
									}
									if (valueEditor != null && !valueEditor.IsReadOnly && valueEditor.IsEnabled)
									{
										if (cxvVariableData != null)
										{
											return cxvVariableData.ResolvedExposeAs != CxvVariableTypeCode.Id;
										}
										return true;
									}
									return false;
								}
							}
							result = valueEditor != null && !valueEditor.IsReadOnly && valueEditor.IsEnabled;
						}
					}
				}
			}
			return result;
		}

		internal static void OnClearCell(object sender, ExecutedRoutedEventArgs arg)
		{
			if (!(arg.Parameter is MMScrollAreaBase mMScrollAreaBase))
			{
				return;
			}
			CxsDataProvider cxsDataProvider = null;
			if (mMScrollAreaBase.DataContext is CxvViewModel cxvViewModel)
			{
				cxsDataProvider = cxvViewModel.ResolvedCxsProvider;
				cxsDataProvider?.SuspendNotifications();
			}
			try
			{
				if (mMScrollAreaBase.DataGrid.SelectedItems.Cells.Count > 0)
				{
					foreach (Cell cell in mMScrollAreaBase.DataGrid.SelectedItems.Cells)
					{
						DoClearCellValue(cell);
					}
				}
				if (mMScrollAreaBase.DataGrid.SelectedItems.Records.Count > 0)
				{
					foreach (Record record in mMScrollAreaBase.DataGrid.SelectedItems.Records)
					{
						foreach (Cell item in (IEnumerable<Cell>)(record as DataRecord).Cells)
						{
							DoClearCellValue(item);
						}
					}
				}
				if (mMScrollAreaBase.DataGrid.SelectedItems.Fields.Count <= 0)
				{
					return;
				}
				List<int> list = new List<int>();
				foreach (Field field in mMScrollAreaBase.DataGrid.SelectedItems.Fields)
				{
					list.Add(field.Index);
				}
				list.Sort();
				for (int num = list.Count - 1; num >= 0; num--)
				{
					foreach (DataRecord item2 in (IEnumerable<Record>)mMScrollAreaBase.DataGrid.Records)
					{
						DoClearCellValue(item2.Cells[list[num]]);
					}
				}
			}
			catch (Exception)
			{
			}
			finally
			{
				cxsDataProvider?.ResumeNotifications();
			}
		}

		private static void DoClearCellValue(Cell cell)
		{
			if (cell == null)
			{
				return;
			}
			CellValuePresenter cellValuePresenter = CellValuePresenter.FromCell(cell);
			if (cellValuePresenter != null)
			{
				AesVariableControlBase aesVariableControlBase = null;
				aesVariableControlBase = Infragistics.Windows.Utilities.GetDescendantFromType(cellValuePresenter, typeof(MMComboEdit), allowSubclassOfType: true) as MMComboEdit;
				if (aesVariableControlBase == null)
				{
					aesVariableControlBase = Infragistics.Windows.Utilities.GetDescendantFromType(cellValuePresenter, typeof(MMVariableEdit), allowSubclassOfType: true) as MMVariableEdit;
				}
				if (aesVariableControlBase == null)
				{
					aesVariableControlBase = Infragistics.Windows.Utilities.GetDescendantFromType(cellValuePresenter, typeof(MMSpinBox), allowSubclassOfType: true) as MMSpinBox;
				}
				if (aesVariableControlBase == null)
				{
					aesVariableControlBase = Infragistics.Windows.Utilities.GetDescendantFromType(cellValuePresenter, typeof(MMCheckBox), allowSubclassOfType: true) as MMCheckBox;
				}
				aesVariableControlBase?.ClearValue();
			}
		}

