		internal static void OnInsertFieldCommand(object sender, ExecutedRoutedEventArgs arg)
		{
			DoInsertField(arg.Parameter as MMScrollAreaHorizontal);
		}

		internal static void DoInsertField(MMScrollAreaHorizontal sah)
		{
			if (sah == null)
			{
				return;
			}
			int num = GetInsertTargetFieldId(sah);
			if (num >= 0)
			{
				if (sah.LabelWidth > 0.0)
				{
					num--;
				}
				if (sah.IsUnitsVisible)
				{
					num--;
				}
				IBindingList dataSource = sah.DataSource;
				if (dataSource != null && num >= 0)
				{
					dataSource.Insert(num, null);
				}
			}
		}

		private static int GetInsertTargetFieldId(MMScrollAreaHorizontal sah)
		{
			int result = -1;
			if (sah.DataGrid.SelectedItems.Fields.Count > 0)
			{
				result = sah.DataGrid.SelectedItems.Fields[0].ActualPosition.Column;
			}
			else if (sah.DataGrid.SelectedItems.Cells.Count == 1)
			{
				result = sah.DataGrid.SelectedItems.Cells[0].Field.ActualPosition.Column;
			}
			return result;
		}

		internal static void CanInsertFieldCommand(object sender, CanExecuteRoutedEventArgs arg)
		{
			if (!(arg.Parameter is MMScrollAreaHorizontal mMScrollAreaHorizontal))
			{
				return;
			}
			IBindingList dataSource = mMScrollAreaHorizontal.DataSource;
			if (dataSource != null)
			{
				int num = ((!mMScrollAreaHorizontal.IsUnitsVisible) ? 1 : 2);
				int insertTargetFieldId = GetInsertTargetFieldId(mMScrollAreaHorizontal);
				if (insertTargetFieldId >= 0 && insertTargetFieldId >= num)
				{
					arg.CanExecute = mMScrollAreaHorizontal.AllowUserInsertField && dataSource.AllowNew && mMScrollAreaHorizontal.DataGrid.SelectedItems.Records.Count == 0;
				}
			}
		}

		internal static void OnReorderFieldCommand(object sender, ExecutedRoutedEventArgs arg)
		{
			if (arg.Parameter is MMScrollAreaHorizontal mMScrollAreaHorizontal)
			{
				MMScrollAreaReorder mMScrollAreaReorder = new MMScrollAreaReorder
				{
					AllowUseValueInReorder = mMScrollAreaHorizontal.AllowUseValueInReorder
				};
				if (mMScrollAreaHorizontal.DataContext is MMViewModel viewModel)
				{
					mMScrollAreaReorder.ViewModel = viewModel;
					mMScrollAreaReorder.DataProperty = mMScrollAreaHorizontal.DataProperty;
					mMScrollAreaReorder.ShowDialog();
				}
			}
		}

		internal static void CanReorderFieldCommand(object sender, CanExecuteRoutedEventArgs arg)
		{
			if (arg.Parameter is MMScrollAreaHorizontal { AllowReorder: var allowReorder } mMScrollAreaHorizontal && (!allowReorder.HasValue || mMScrollAreaHorizontal.AllowReorder.Value) && mMScrollAreaHorizontal.DataSource != null)
			{
				arg.CanExecute = mMScrollAreaHorizontal.DataSource.AllowReorder && mMScrollAreaHorizontal.DataGrid.SelectedItems.Records.Count == 0;
			}
		}
	}
