		internal static void OnLabelPresenterContextMenuOpening(object sender, ContextMenuEventArgs e)
		{
			if (!(sender is LabelPresenter { IsInFieldChooser: false } labelPresenter) || labelPresenter.Field.Owner != labelPresenter.DataPresenter.DefaultFieldLayout || !(Infragistics.Windows.Utilities.GetAncestorFromType(labelPresenter.DataPresenter, typeof(MMScrollAreaBase), allowSubclassOfType: true) is MMScrollAreaBase { IsEnabled: not false } mMScrollAreaBase))
			{
				return;
			}
			mMScrollAreaBase.LastKeyPressed = null;
			if (!labelPresenter.Field.IsSelected)
			{
				if (labelPresenter.Field.Owner.DataPresenter.ActiveCell != null)
				{
					labelPresenter.Field.Owner.DataPresenter.ActiveCell.EndEditMode();
				}
				labelPresenter.Field.Owner.DataPresenter.SelectedItems.Fields.Clear();
				labelPresenter.Field.Owner.DataPresenter.SelectedItems.Records.Clear();
				labelPresenter.Field.Owner.DataPresenter.SelectedItems.Cells.Clear();
				if (labelPresenter.Field.Owner.DataPresenter.Records.Count > 0)
				{
					Cell cell = (labelPresenter.Field.Owner.DataPresenter.Records[0] as DataRecord).Cells[labelPresenter.Field];
					if (cell != null)
					{
						cell.IsActive = true;
						labelPresenter.Field.Owner.DataPresenter.BringCellIntoView(cell);
					}
				}
				labelPresenter.Field.IsSelected = true;
			}
			if (labelPresenter.ContextMenu == null && mMScrollAreaBase != null)
			{
				labelPresenter.ContextMenu = new ContextMenu();
				MMScrollArea mMScrollArea = mMScrollAreaBase as MMScrollArea;
				MMScrollAreaManualLayout mMScrollAreaManualLayout = mMScrollAreaBase as MMScrollAreaManualLayout;
				MMScrollAreaHorizontal mMScrollAreaHorizontal = mMScrollAreaBase as MMScrollAreaHorizontal;
				if (mMScrollArea != null)
				{
					AddLabelPresenterMenuItems(labelPresenter, mMScrollArea);
				}
				else if (mMScrollAreaManualLayout != null)
				{
					AddManualLayoutLabelPresenterMenuItems(labelPresenter);
				}
				else if (mMScrollAreaHorizontal != null)
				{
					AddHorizontalLabelPresenterMenuItems(labelPresenter, mMScrollAreaHorizontal);
				}
			}
			e.Handled = true;
			if (labelPresenter.ContextMenu != null && labelPresenter.ContextMenu.Items.Count > 0)
			{
				labelPresenter.ContextMenu.IsOpen = true;
			}
		}

