						{
							new CommandBinding(MMScrollAreaCommand.CopyCommand, MMScrollAreaCommand.OnCopyAll)
						}
					});
				}
				else
				{
					Type type = mMScrollAreaBase.GetType();
					if (type == typeof(MMScrollArea))
					{
						AddHeaderPrefixAreaContextMenu(headerPrefixArea, mMScrollAreaBase as MMScrollArea);
					}
					else if (type == typeof(MMScrollAreaManualLayout) || type == typeof(MMScrollAreaHorizontal) || type.IsSubclassOf(typeof(MMScrollAreaManualLayout)) || type.IsSubclassOf(typeof(MMScrollAreaHorizontal)))
					{
						AddManualLayoutHeaderPrefixAreaContextMenu(headerPrefixArea, mMScrollAreaBase);
					}
				}
			}
			MenuItem menuItem = null;
			foreach (object item in (IEnumerable)headerPrefixArea.ContextMenu.Items)
			{
				if (item is MenuItem menuItem2 && menuItem2.Command == MMScrollAreaCommand.SelectAllCommand)
				{
					menuItem = menuItem2;
					break;
				}
			}
			if (menuItem != null)
			{
				menuItem.IsChecked = mMScrollAreaBase.IsAllSelected;
			}
			e.Handled = true;
			headerPrefixArea.ContextMenu.IsOpen = true;
