		internal static void OnCellContextMenuOpening(object sender, ContextMenuEventArgs e)
		{
			if (!(sender is CellValuePresenter cellValuePresenter))
			{
				return;
			}
			XamDataGrid xamDataGrid = cellValuePresenter.DataPresenter as XamDataGrid;
			if (!(Infragistics.Windows.Utilities.GetAncestorFromType(xamDataGrid, typeof(MMScrollAreaBase), allowSubclassOfType: true) is MMScrollAreaBase { IsEnabled: not false } mMScrollAreaBase))
			{
				return;
			}
			if (!xamDataGrid.IsKeyboardFocusWithin)
			{
				xamDataGrid.Focus();
			}
			cellValuePresenter.ContextMenu = new ContextMenu();
			if (mMScrollAreaBase.IsBoundToPlainDataSource)
			{
				cellValuePresenter.ContextMenu.Items.Add(new MenuItem
				{
					Icon = GetContextItemIcon("Copy16.ico"),
					Command = MMScrollAreaCommand.CopyCommand,
					CommandParameter = mMScrollAreaBase,
					CommandBindings = 
					{
						new CommandBinding(MMScrollAreaCommand.CopyCommand, MMScrollAreaCommand.OnCopyCell, MMScrollAreaCommand.CanCopyCell)
					}
				});
			}
			else
			{
				Type type = mMScrollAreaBase.GetType();
				if (type == typeof(MMScrollArea))
				{
					AddNormalCellContextMenu(cellValuePresenter, mMScrollAreaBase);
					AddInsertDeleteReorderRow(cellValuePresenter.ContextMenu, mMScrollAreaBase, cellValuePresenter.Record);
					AddInsertDeleteColumn(cellValuePresenter.ContextMenu, mMScrollAreaBase);
					AddExpandCollapse(cellValuePresenter.ContextMenu, mMScrollAreaBase as MMScrollArea);
				}
				else if (type == typeof(MMHorizontalListEdit))
				{
					AddNormalCellContextMenu(cellValuePresenter, mMScrollAreaBase);
					AddHorizontalListEditCellContextMenu(cellValuePresenter, mMScrollAreaBase as MMHorizontalListEdit);
				}
				else if (type == typeof(MMScrollAreaHorizontal))
				{
					AddManualLayoutCellContextMenu(cellValuePresenter, mMScrollAreaBase);
					AddDeleteInsertReorderForHorizontal(mMScrollAreaBase as MMScrollAreaHorizontal, cellValuePresenter.ContextMenu);
				}
				else if (type == typeof(MMScrollAreaManualLayout))
				{
					AddManualLayoutCellContextMenu(cellValuePresenter, mMScrollAreaBase);
				}
			}
			AddCustomMenuItem(cellValuePresenter.ContextMenu, mMScrollAreaBase);
			if (cellValuePresenter.ContextMenu != null && cellValuePresenter.ContextMenu.PlacementTarget == null)
			{
				cellValuePresenter.ContextMenu.PlacementTarget = mMScrollAreaBase;
			}
			if (e != null)
			{
				e.Handled = true;
			}
			if (cellValuePresenter.ContextMenu != null && cellValuePresenter.ContextMenu.Items.Count > 0)
			{
				cellValuePresenter.ContextMenu.IsOpen = true;
			}
			if (!cellValuePresenter.IsSelected && !cellValuePresenter.IsRecordSelected && !cellValuePresenter.IsFieldSelected)
			{
				xamDataGrid.SelectedItems.Cells.Clear();
				cellValuePresenter.IsSelected = true;
			}
		}

		private static void AddNormalCellContextMenu(CellValuePresenter cvp, MMScrollAreaBase sa)
		{
			if (cvp.Editor != null && cvp.Editor is AesXamComboEdit { ItemsSource: ObservableCollection<string> itemsSource } && itemsSource.Contains(CxvVariableData.NewItem))
			{
				cvp.ContextMenu.Items.Add(new MenuItem
				{
					Header = AspenTech.AspenPlus.MMControls.Properties.Resources.ContextMenuHeaderNew,
					Icon = GetContextItemIcon("New16.ico"),
					Command = ApplicationCommands.New,
					CommandParameter = cvp,
					CommandBindings = 
					{
						new CommandBinding(ApplicationCommands.New, MMScrollAreaCommand.OnNewInCombo, MMScrollAreaCommand.CanNewInCombo)
					}
				});
				cvp.ContextMenu.Items.Add(new Separator());
			}
			cvp.ContextMenu.Items.Add(new MenuItem
			{
				Icon = GetContextItemIcon("Copy16.ico"),
				Command = MMScrollAreaCommand.CopyCommand,
				CommandParameter = sa,
				CommandBindings = 
				{
					new CommandBinding(MMScrollAreaCommand.CopyCommand, MMScrollAreaCommand.OnCopyCell, MMScrollAreaCommand.CanCopyCell)
				}
			});
			MMScrollAreaField linkedMMField = sa.GetLinkedMMField(cvp.Field);
			if (linkedMMField == null || linkedMMField.AllowPaste != false)
			{
				cvp.ContextMenu.Items.Add(CreatePasteMenuItem(MMScrollAreaCommand.PasteCommand, sa));
			}
			cvp.ContextMenu.Items.Add(new MenuItem
			{
				Icon = GetContextItemIcon("Clear16.ico"),
				Command = MMScrollAreaCommand.ClearCommand,
				CommandParameter = sa,
				CommandBindings = 
				{
					new CommandBinding(MMScrollAreaCommand.ClearCommand, MMScrollAreaCommand.OnClearCell, MMScrollAreaCommand.CanClearCell)
				}
			});
		}

