		private static MenuItem CreatePasteMenuItem(ICommand command, object commandParameter)
		{
			MenuItem menuItem = new MenuItem
			{
				Icon = GetContextItemIcon("Paste16.ico"),
				Command = command
			};
			if (commandParameter != null)
			{
				menuItem.CommandParameter = commandParameter;
			}
			menuItem.SetBinding(MenuItem.CommandTargetProperty, new Binding
			{
				Path = new PropertyPath("PlacementTarget"),
				RelativeSource = new RelativeSource
				{
					Mode = RelativeSourceMode.FindAncestor,
					AncestorType = typeof(ContextMenu)
				}
			});
			return menuItem;
		}

