		private static void AddInsertDeleteReorderRow(ContextMenu cm, MMScrollAreaBase sab, Record record)
		{
			if (cm != null)
			{
				if (cm.Items.Count > 0)
				{
					cm.Items.Add(new Separator());
				}
				MenuItem menuItem = new MenuItem
				{
					Icon = GetContextItemIcon("DeleteRow16.ico"),
					Command = MMScrollAreaCommand.DeleteRecordCommand,
					CommandParameter = sab,
					CommandBindings = 
					{
						new CommandBinding(MMScrollAreaCommand.DeleteRecordCommand, MMScrollAreaCommand.OnDeleteRecordCommand, MMScrollAreaCommand.CanDeleteRecordCommand)
					}
				};
				cm.Items.Add(menuItem);
				MenuItem menuItem2 = new MenuItem
				{
					Icon = GetContextItemIcon("InsertRow16.ico"),
					Command = MMScrollAreaCommand.InsertRecordCommand,
					CommandParameter = sab,
					CommandBindings = 
					{
						new CommandBinding(MMScrollAreaCommand.InsertRecordCommand, MMScrollAreaCommand.OnInsertRecordCommand, MMScrollAreaCommand.CanInsertRecordCommand)
					}
				};
				cm.Items.Add(menuItem2);
				if (sab is MMScrollArea { DataOrientation: Orientation.Horizontal })
				{
					menuItem2.Header = AspenTech.AspenPlus.MMControls.Properties.Resources.strInsertField;
					menuItem2.Icon = GetContextItemIcon("InsertColumn.ico");
					menuItem.Header = AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteField;
					menuItem.Icon = GetContextItemIcon("DeleteColumn.ico");
				}
				cm.Items.Add(new MenuItem
				{
					Command = MMScrollAreaCommand.ReorderCommand,
					CommandParameter = sab,
					CommandBindings = 
					{
						new CommandBinding(MMScrollAreaCommand.ReorderCommand, MMScrollAreaCommand.OnReorderCommand, MMScrollAreaCommand.CanReorderCommand)
					}
				});
			}
		}

		private static void AddCustomMenuItem(ContextMenu cm, MMScrollAreaBase sa)
		{
			if (sa.ContextMenuItems == null)
			{
				return;
			}
			if (sa.ContextMenuItems.Count > 0)
			{
				cm.Items.Add(new Separator());
			}
			foreach (MMScrollAreaContextMenuItem contextMenuItem in sa.ContextMenuItems)
			{
				if (contextMenuItem.Visibility == Visibility.Visible)
				{
					cm.Items.Add(new MenuItem
					{
						Command = contextMenuItem.Command,
						Header = contextMenuItem.Display
					});
				}
			}
		}

