	[TemplatePart(Name = "PART_DataGrid", Type = typeof(XamDataGrid))]
	public class MMScrollAreaManualLayout : MMScrollAreaBase, IManualLayout
	{
		private MMScrollAreaColumnCollection _MMColumns = new MMScrollAreaColumnCollection();

		private MMScrollAreaRecordCollection _MMRecords = new MMScrollAreaRecordCollection();

		[DesignerSerializationVisibility(DesignerSerializationVisibility.Content)]
		public MMScrollAreaColumnCollection MMColumns => _MMColumns;

		[DesignerSerializationVisibility(DesignerSerializationVisibility.Content)]
		public MMScrollAreaRecordCollection MMRecords => _MMRecords;

		protected override string CustomizationKey
		{
			get
			{
				if (_CustomizationKey == null)
				{
					string formProgId = GetFormProgId();
					if (formProgId == null)
					{
						return null;
					}
					if (base.Name == null)
					{
						return null;
					}
					_CustomizationKey = formProgId + "/" + base.Name;
				}
				return _CustomizationKey;
			}
		}

		[DesignerSerializationVisibility(DesignerSerializationVisibility.Hidden)]
		public ValueEditor ActiveEditor { get; set; }

		static MMScrollAreaManualLayout()
		{
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(MMScrollAreaManualLayout), new FrameworkPropertyMetadata(typeof(MMScrollAreaManualLayout)));
			CommandManager.RegisterClassCommandBinding(typeof(MMScrollAreaManualLayout), new CommandBinding(MMScrollAreaCommand.PasteCommand, MMScrollAreaManualLayoutCommand.OnPasteCommand, MMScrollAreaManualLayoutCommand.CanPasteCommand));
		}

		protected override void RegisterEvents()
		{
			base.RegisterEvents();
			MMColumns.CollectionChanged += MMColumns_CollectionChanged;
			MMRecords.CollectionChanged += MMRecords_CollectionChanged;
		}

		public override void OnApplyTemplate()
		{
			base.OnApplyTemplate();
			MMScrollAreaManualLayoutHelper.MergeManualLayoutStyle(this);
			AddColumns(MMColumns, 0);
			SetupRecords(MMRecords);
			BindingOperations.SetBinding(base.DataGrid, DataPresenterBase.DataSourceProperty, new Binding("MMRecords")
			{
				Source = this
			});
		}

		protected override void SetFieldWidthMode(FieldSizeMode mode)
		{
			base.SetFieldWidthMode(mode);
			foreach (MMScrollAreaColumn mMColumn in MMColumns)
			{
				if (mMColumn.LinkedMMField != null)
				{
					mMColumn.LinkedMMField.SetFieldWidth();
				}
			}
		}

		protected override void FieldLayoutInitializing(FieldLayoutInitializingEventArgs e)
		{
			base.FieldLayoutInitializing(e);
			MMScrollAreaManualLayoutHelper.SetupFieldLayoutSettingForManualLayout(e.FieldLayout.Settings, this);
		}

		protected override void DataGrid_Loaded(object sender, RoutedEventArgs e)
		{
			base.DataGrid_Loaded(sender, e);
			RefreshAllRecordBinding();
			RefreshAllColumnBinding();
			MMColumns.SetColumnsVisibility();
			RestoreCustomization();
		}

		protected override void CVP_PreviewKeyDown(KeyEventArgs arg)
		{
			if (arg.Key == Key.C && Keyboard.Modifiers.HasFlag(ModifierKeys.Control))
			{
				MMScrollAreaManualLayoutCommand.SetClipboardData(this, base.DataGrid.SelectedItems.Fields.Count > 0);
				arg.Handled = true;
			}
			else if (ShouldCVPRespondKeyDown(arg))
			{
				base.CVP_PreviewKeyDown(arg);
			}
		}

		protected override void DataGrid_PreviewKeyDown(object sender, KeyEventArgs e)
		{
			if (e.Key == Key.C && Keyboard.Modifiers.HasFlag(ModifierKeys.Control))
			{
				MMScrollAreaManualLayoutCommand.SetClipboardData(this, base.DataGrid.SelectedItems.Fields.Count > 0);
				e.Handled = true;
			}
			else if (e.Key == Key.V && Keyboard.Modifiers.HasFlag(ModifierKeys.Control))
			{
				MMScrollAreaCommand.PasteCommand.Execute(this, this);
				e.Handled = true;
			}
			else if (ShouldDataGridRespondKeyDown(e) && !e.Handled)
			{
				base.DataGrid_PreviewKeyDown(sender, e);
			}
		}

		protected override void DataGrid_SelectedItemsChanged(object sender, SelectedItemsChangedEventArgs e)
		{
			base.DataGrid_SelectedItemsChanged(sender, e);
			MMScrollAreaManualLayoutHelper.ForceDisplayCellMessage(GetActiveEditor());
		}

		internal override MMScrollAreaField GetLinkedMMField(Field field)
		{
			foreach (MMScrollAreaRecord mMRecord in MMRecords)
			{
				foreach (MMScrollAreaField field2 in mMRecord.Fields)
				{
					if (field2.Field == field)
					{
						return field2;
					}
				}
			}
			return null;
		}

		private void RefreshAllColumnBinding()
		{
			foreach (MMScrollAreaColumn mMColumn in MMColumns)
			{
				if (!string.IsNullOrEmpty(mMColumn.IsVisibleBindingPath))
				{
					BindingOperations.SetBinding(mMColumn, MMScrollAreaColumn.IsVisibleProperty, new Binding(mMColumn.IsVisibleBindingPath)
					{
						Source = base.DataContext
					});
				}
			}
		}

		private void RefreshAllRecordBinding()
		{
			foreach (MMScrollAreaRecord mMRecord in MMRecords)
			{
				if (!string.IsNullOrEmpty(mMRecord.IsVisibleBindingPath))
				{
