		private void MMColumns_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			if (e.Action == NotifyCollectionChangedAction.Add)
			{
				AddColumns(e.NewItems, e.NewStartingIndex);
			}
			else if (e.Action == NotifyCollectionChangedAction.Remove)
			{
				for (int i = e.OldStartingIndex; i < e.OldItems.Count + e.OldStartingIndex; i++)
				{
					base.DataGrid.DefaultFieldLayout.Fields.RemoveAt(i);
				}
			}
		}

		private void AddColumns(IList items, int startingIndex)
		{
			List<MMScrollAreaField> list = new List<MMScrollAreaField>();
			int num = startingIndex;
			foreach (MMScrollAreaColumn item2 in items)
			{
				MMScrollAreaValueField item = (MMScrollAreaValueField)(item2.LinkedMMField = new MMScrollAreaValueField
				{
					Label = item2.Label,
					FieldName = item2.Name,
					IsManualRecordMode = true,
					Id = num,
					WidthFieldLength = item2.WidthFieldLength,
					HeaderUnitsProperty = item2.HeaderUnitsProperty
				});
				list.Add(item);
				num++;
			}
			AddFields(list, startingIndex);
		}

