		protected override void DoClearCell(Cell cell)
		{
			CellValuePresenter cellValuePresenter = CellValuePresenter.FromCell(cell);
			if (!MMScrollAreaBase.IsCellEditable(cellValuePresenter) || !(Infragistics.Windows.Utilities.GetDescendantFromType(cellValuePresenter, typeof(AesVariableControlBase), allowSubclassOfType: true) is AesVariableControlBase { VariablePath: var text } aesVariableControlBase))
			{
				return;
			}
			if (aesVariableControlBase.VariablePath == null && aesVariableControlBase.Variable != null && aesVariableControlBase.Variable is CxvPropertyData { Property: not null } cxvPropertyData)
			{
				text = cxvPropertyData.Property.Name;
			}
			if (base.DataContext is MMViewModel mMViewModel)
			{
				string text2 = "Value";
				if (aesVariableControlBase is AesComboEdit aesComboEdit)
				{
					text2 = aesComboEdit.VariableDataMember;
				}
				string path = text + "." + text2;
				object obj = mMViewModel.ResolveViewPropertyPath(path);
				mMViewModel.ResolveUpdateViewPropertyPath(path, null);
				if (obj == mMViewModel.ResolveViewPropertyPath(path))
				{
					mMViewModel.ResolveUpdateViewPropertyPath(path, "");
