		protected override bool? GetCellStatus(Cell cell, string status)
		{
			if (cell == null)
			{
				return null;
			}
			if (!(cell.Record.DataItem is MMScrollAreaRecord mMScrollAreaRecord))
			{
				return null;
			}
			string propertyPath = mMScrollAreaRecord.Fields[cell.Field.Index].PropertyPath;
			bool? flag = mMScrollAreaRecord.Fields[cell.Field.Index].IsEnabled;
			bool? flag2 = CxsConverter.ValueToBoolean((base.DataContext as MMViewModel).ResolveViewPropertyPath(propertyPath + "." + status, null));
			bool? result = flag;
			bool? result2 = flag2;
			if (result != true && (result2 == true || result.HasValue))
			{
				return result;
			}
			return result2;
		}

		protected override bool NotComboOrHasOptions(Cell cell)
		{
			if (cell == null || !(base.DataContext is MMViewModel))
			{
				return false;
			}
			if (!(cell.Record.DataItem is MMScrollAreaRecord mMScrollAreaRecord))
			{
				return true;
			}
			if (!(mMScrollAreaRecord.Fields[cell.Field.Index] is MMScrollAreaComboValueField mMScrollAreaComboValueField))
			{
				return true;
			}
			object obj = (base.DataContext as MMViewModel).ResolveViewPropertyPath(mMScrollAreaComboValueField.PropertyPath + "." + MMScrollAreaBase.GetComboItemsPath(mMScrollAreaComboValueField) + ".Count", null);
			if ((base.DataContext as MMViewModel).ResolveViewPropertyPath(mMScrollAreaComboValueField.PropertyPath + "." + MMScrollAreaBase.GetComboItemsPath(mMScrollAreaComboValueField), null) != null && int.Parse(obj.ToString()) > 0)
			{
				return true;
			}
			return false;
		}

		protected override void RefreshAllFieldsBinding()
		{
			foreach (MMScrollAreaRecord mMRecord in MMRecords)
