		protected virtual void DisposeViewModel()
		{
			if (ViewModel == null)
			{
				return;
			}
			string text = ViewModel.ToString();
			if (text.IndexOf("MMHeatx_Hetranui") != -1 || text.IndexOf("MMHeatx_Aerotranresult_ProfPlots") != -1 || text.IndexOf("MMHeatx_Aerotranresult_SettingPlan") != -1 || text.IndexOf("MMHeatx_Aerotranresult_TubeLayout") != -1 || text.IndexOf("MMHeatx_Hetranresult_ProfPlots") != -1 || text.IndexOf("MMHeatx_Hetranresult_SettingPlan") != -1 || text.IndexOf("MMHeatx_Hetranresult_TubeLayout") != -1 || text.IndexOf("MMHeatx_Plateresult_ProfPlots") != -1 || text.IndexOf("MMHeatx_Plateresult_SettingPlan") != -1)
			{
				try
				{
					ViewModel.Unload();
					if ((ViewModel as MMViewModel).View is MMTabPage mMTabPage && !string.IsNullOrEmpty(mMTabPage.ContentProgId) && mMTabPage.Content is MMTabPage { ViewModel: not null } mMTabPage2)
					{
						mMTabPage2.ViewModel.Unload();
					}
					return;
				}
				catch (Exception)
				{
					return;
				}
			}
			base.Dispatcher.BeginInvoke(DispatcherPriority.Background, (Action)delegate
			{
				try
