	public class FieldSortComparer : IComparer
	{
		public MMScrollAreaField MMField { get; set; }

		public int Compare(object x, object y)
		{
			MMScrollAreaValueField mMScrollAreaValueField = MMField as MMScrollAreaValueField;
			if (x == null && y == null)
			{
				return 0;
			}
			if (x == null)
			{
				if (MMField.Field.SortStatus == SortStatus.Descending)
				{
					return -1;
				}
				return 1;
			}
			if (y == null)
			{
				if (MMField.Field.SortStatus == SortStatus.Descending)
				{
					return 1;
				}
				return -1;
			}
			if (mMScrollAreaValueField != null && mMScrollAreaValueField.Mask == AesMaskOption.Integer)
			{
				return CompareInt(x, y);
			}
			if (mMScrollAreaValueField != null && mMScrollAreaValueField.Mask == AesMaskOption.Double)
			{
				return CompareDouble(x, y);
			}
			if (x.GetType() == typeof(string))
			{
				return CompareString(x, y);
			}
			if (x.GetType() == typeof(int))
			{
				return CompareInt(x, y);
			}
			if (x.GetType() == typeof(double))
			{
				return CompareDouble(x, y);
			}
			return 0;
		}

		private int CompareString(object x, object y)
		{
			string text = x.ToString();
			string text2 = y.ToString();
			if (string.IsNullOrEmpty(text))
			{
				if (MMField.Field.SortStatus == SortStatus.Descending)
				{
					return -1;
				}
				return 1;
			}
			if (string.IsNullOrEmpty(text2))
			{
				if (MMField.Field.SortStatus == SortStatus.Descending)
				{
					return 1;
				}
				return -1;
			}
			return string.Compare(text, text2);
		}

		private int CompareDouble(object x, object y)
		{
			if (string.IsNullOrEmpty(x.ToString()) || string.IsNullOrEmpty(y.ToString()))
			{
				return CompareString(x, y);
			}
			if (!double.TryParse(x.ToString(), out var _) || !double.TryParse(y.ToString(), out var _))
			{
				return CompareString(x, y);
			}
			double num = Convert.ToDouble(x) - Convert.ToDouble(y);
			if (num > 0.0)
			{
				return 1;
			}
			if (num < 0.0)
			{
				return -1;
			}
			return 0;
		}

		private int CompareInt(object x, object y)
		{
			if (string.IsNullOrEmpty(x.ToString()) || string.IsNullOrEmpty(y.ToString()))
			{
				return CompareString(x, y);
			}
			if (!int.TryParse(x.ToString(), out var _) || !int.TryParse(y.ToString(), out var _))
			{
				return CompareString(x, y);
			}
			return Convert.ToInt32(x) - Convert.ToInt32(y);
		}
	}
