	{
		public static readonly ColumnHeaderHorizontalAlignmentConverter Converter = new ColumnHeaderHorizontalAlignmentConverter();

		public override object Convert(object value, Type targetType, object parameter, CultureInfo culture)
		{
			if (value == null)
			{
				return null;
			}
			if (value.GetType() != typeof(TextAlignment))
			{
				return null;
			}
			return (TextAlignment)value switch
			{
				TextAlignment.Center => HorizontalAlignment.Center, 
				TextAlignment.Left => HorizontalAlignment.Left, 
				TextAlignment.Right => HorizontalAlignment.Right, 
				TextAlignment.Justify => HorizontalAlignment.Stretch, 
				_ => null, 
			};
		}
