		private void SetAutoWidthOption()
		{
			if (Field != null)
			{
				Field.Settings.AutoSizeOptions = FieldAutoSizeOptions.DataCells;
				if (IncludeLabelWhenAutoWidth)
				{
					Field.Settings.AutoSizeOptions = (FieldAutoSizeOptions?)((uint?)Field.Settings.AutoSizeOptions | 1u);
				}
			}
		}

		private FieldLength? ResolveWidthFieldLength(FieldSizeMode value)
		{
			FieldLength? result = null;
			if (ParentScrollArea != null && DesignerProperties.GetIsInDesignMode(ParentScrollArea) && value == FieldSizeMode.InitialAuto)
			{
				value = FieldSizeMode.Auto;
			}
			switch (value)
			{
			case FieldSizeMode.Auto:
				result = FieldLength.Auto;
				break;
			case FieldSizeMode.InitialAuto:
				result = FieldLength.InitialAuto;
				break;
			case FieldSizeMode.Pixel:
				result = new FieldLength(Width, FieldLengthUnitType.Pixel);
				break;
			case FieldSizeMode.Star:
				result = new FieldLength(Width, FieldLengthUnitType.Star);
				break;
			}
			return result;
		}

		internal void SetFieldWidth()
		{
			if (Field != null && IsUsed)
			{
				Field.Settings.Width = WidthFieldLengthResolved;
				Field.Settings.CellMinWidth = MinWidth;
			}
		}

