			if (Field != null && !IsManualRecordMode)
			{
				if (AllowEdit.HasValue)
				{
					Field.Settings.AllowEdit = AllowEdit;
				}
				else if (ParentScrollArea is MMScrollArea { AllowEdit: not null } mMScrollArea)
				{
					Field.Settings.AllowEdit = mMScrollArea.AllowEdit;
