		internal virtual void SubstituteIndexAndKey(int index, object key)
		{
			Label = SubstituteIndexAndKey(Label, index, key);
			LabelBindingPath = SubstituteIndexAndKey(LabelBindingPath, index, key);
			PropertyPath = SubstituteIndexAndKey(PropertyPath, index, key);
			IsEnabledBindingPath = SubstituteIndexAndKey(IsEnabledBindingPath, index, key);
			HeaderUnitsProperty = SubstituteIndexAndKey(HeaderUnitsProperty, index, key);
		}

		internal static string SubstituteIndexAndKey(string template, int index, object key)
		{
			if (string.IsNullOrEmpty(template))
			{
				return template;
			}
			return template.Replace("{index}", index.ToString(CultureInfo.InvariantCulture)).Replace("{key}", key.ToString());
		}

