	public class MMScrollAreaEOBrowseField : MMScrollAreaBrowseField
	{
		private IUnityContainer _unityContainer;

		private IUnityContainer UnityContainer
		{
			get
			{
				if (_unityContainer == null)
				{
					if (base.ResolvedCxsProvider != null)
					{
						_unityContainer = base.ResolvedCxsProvider.UnityContainer;
					}
					if (_unityContainer == null && base.ParentScrollArea != null && Infragistics.Windows.Utilities.GetAncestorFromType(base.ParentScrollArea, typeof(MMTabPage), allowSubclassOfType: true) is MMTabPage mMTabPage)
					{
						_unityContainer = mMTabPage.UnityContainer;
					}
				}
				return _unityContainer;
			}
			set
			{
				_unityContainer = value;
			}
		}

		public MMScrollAreaEOBrowseField()
		{
			base.BrowseVisibility = Visibility.Visible;
			base.BrowseCommand = new DelegateCommand<object>(BrowseCommand_Execute, BrowseCommand_CanExecute);
		}

		private void BrowseCommand_Execute(object parameter)
		{
			if (UnityContainer != null)
			{
				MMControlHelper.ListToSelectEOVariables(UnityContainer, parameter);
			}
		}

		private bool BrowseCommand_CanExecute(object parameter)
		{
			if (UnityContainer != null)
			{
				return MMControlHelper.CanListEOVariables(UnityContainer, parameter);
			}
			if (parameter is AesXamValueEditBrowse { Editor: { } editor } && Infragistics.Windows.Utilities.GetAncestorFromType(editor, typeof(MMTabPage), allowSubclassOfType: true) is MMTabPage { UnityContainer: not null } mMTabPage)
			{
				_unityContainer = mMTabPage.UnityContainer;
			}
			return false;
		}
	}
