	internal static class MMScrollAreaTemplateHelper
	{
		private static Style _ReadOnlyFieldEditorStyle;

		private static Style _CellValuePresenterStyle;

		private static Style _LabelPresenterStyle;

		private static Style ReadOnlyFieldEditorStyle
		{
			get
			{
				if (_ReadOnlyFieldEditorStyle == null)
				{
					_ReadOnlyFieldEditorStyle = new Style(typeof(XamNumericEditor));
					_ReadOnlyFieldEditorStyle.Setters.Add(new Setter(ValueEditor.FormatProperty, "G6"));
					_ReadOnlyFieldEditorStyle.Setters.Add(new Setter(Control.HorizontalContentAlignmentProperty, HorizontalAlignment.Left));
				}
