		internal static void SetCellStyleAndFieldBinding(MMScrollAreaField mmfield)
		{
			if (_CellValuePresenterStyle == null)
			{
				_CellValuePresenterStyle = (Style)mmfield.ParentScrollArea.FindResource("CellValuePresenterStyle");
			}
			Style style = new Style(typeof(CellValuePresenter), _CellValuePresenterStyle);
			string text = null;
			ControlTemplate controlTemplate = null;
			Type type = mmfield.GetType();
			AddHelpProperty(mmfield, style);
			AddFieldHelpBinding(mmfield, style);
			if (type == typeof(MMScrollAreaDeleteButtonField))
			{
				controlTemplate = GetButtonFieldTemplate(mmfield as MMScrollAreaDeleteButtonField);
			}
			else if (type == typeof(MMScrollAreaButtonField))
			{
				controlTemplate = GetButtonFieldTemplate(mmfield as MMScrollAreaButtonField);
			}
			else if (type == typeof(MMScrollAreaLineFormatField))
			{
				controlTemplate = GetLineFormatField(mmfield as MMScrollAreaLineFormatField);
			}
			else if (type == typeof(MMScrollAreaFortranLineField))
			{
				controlTemplate = GetFortranLineFieldTemplate(mmfield as MMScrollAreaFortranLineField);
			}
			else if (type == typeof(MMScrollAreaGridField))
			{
				controlTemplate = GetGridFieldTemplate(mmfield as MMScrollAreaGridField);
			}
			else if (type == typeof(MMScrollAreaCheckBoxField))
			{
				SetupCheckField(mmfield as MMScrollAreaCheckBoxField);
			}
			else if (type == typeof(MMScrollAreaHierarchicalField) || type == typeof(MMScrollAreaReadOnlyField))
			{
				text = mmfield.PropertyPath;
			}
			else if (type == typeof(MMScrollAreaReadOnlyValueField))
			{
				string variableDataMemberResolved = ((MMScrollAreaValueField)mmfield).VariableDataMemberResolved;
				text = mmfield.PropertyPath + "." + (string.IsNullOrEmpty(variableDataMemberResolved) ? "Value" : variableDataMemberResolved);
				mmfield.Field.Settings.EditorStyle = ReadOnlyFieldEditorStyle;
			}
			else if (mmfield is MMScrollAreaValueField)
			{
				text = SetupValueField(mmfield);
			}
			else if (mmfield is MMScrollAreaComboValueField)
			{
				text = SetupComboField(mmfield);
			}
			if (mmfield.IsManualRecordMode)
			{
				controlTemplate = GetManualRecordModeTemplate(mmfield);
			}
			if (controlTemplate != null)
			{
				style.Setters.Add(new Setter(Control.TemplateProperty, controlTemplate));
			}
			if (mmfield.Field.Settings.CellValuePresenterStyle == null && type != typeof(MMScrollAreaHierarchicalField))
			{
				mmfield.Field.Settings.CellValuePresenterStyle = style;
			}
			if (!(type == typeof(MMScrollAreaGridField)) && !(type == typeof(MMScrollAreaButtonField)) && !(type == typeof(MMScrollAreaDeleteButtonField)) && !mmfield.IsManualRecordMode)
			{
				if (text == null)
				{
					text = ((!string.IsNullOrEmpty(mmfield.PropertyPath)) ? (mmfield.PropertyPath + ".Value") : "Value");
				}
				mmfield.Field.BindingPath = new PropertyPath(text);
				if (type == typeof(MMScrollAreaHierarchicalField) || mmfield is MMScrollAreaReadOnlyField)
				{
					mmfield.Field.Settings.AllowEdit = false;
				}
				if (mmfield.Field.AllowEditResolved)
				{
					mmfield.Field.BindingMode = BindingMode.TwoWay;
				}
				if ((mmfield.ParentScrollArea as MMScrollArea).RecordFilteringMode == RecordFilteringMode.Auto)
				{
					mmfield.Field.Settings.AllowRecordFiltering = true;
				}
				if (mmfield.HorizontalContentAlignment.HasValue)
				{
					mmfield.Field.HorizontalContentAlignment = mmfield.HorizontalContentAlignment.Value;
				}
			}
		}

		internal static void SetLabelPresenterStyle(MMScrollAreaField mmfield)
		{
			if (_LabelPresenterStyle == null)
			{
				_LabelPresenterStyle = (Style)mmfield.ParentScrollArea.FindResource("LabelPresenterStyle");
			}
			Style style = new Style(typeof(LabelPresenter), _LabelPresenterStyle);
			DataTemplate dataTemplate;
			if (mmfield.ColumnHeaderTemplate != null)
			{
				dataTemplate = mmfield.ColumnHeaderTemplate;
			}
			else
			{
				dataTemplate = new DataTemplate(typeof(LabelHeader));
				FrameworkElementFactory frameworkElementFactory = new FrameworkElementFactory(typeof(DockPanel));
				Binding binding = new Binding("LabelText");
				if (mmfield.LabelTextConverter != null)
				{
					binding.Converter = mmfield.LabelTextConverter;
				}
				BuildColumnHeaderDockPanel(mmfield, frameworkElementFactory, binding);
				string text = AddUnitToLabel(mmfield, frameworkElementFactory);
				FrameworkElementFactory frameworkElementFactory2 = new FrameworkElementFactory(typeof(TextBlock));
				if (text == null)
				{
					frameworkElementFactory2.SetBinding(TextBlock.TextProperty, binding);
				}
				else
				{
					frameworkElementFactory2.SetBinding(FrameworkElement.DataContextProperty, new Binding("DataContext")
					{
						Source = mmfield.ParentScrollArea
					});
					frameworkElementFactory2.SetBinding(TextBlock.TextProperty, new Binding(text));
				}
				frameworkElementFactory2.SetBinding(UIElement.VisibilityProperty, new Binding
				{
					RelativeSource = new RelativeSource(RelativeSourceMode.Self),
					Converter = ColumnHeaderCaptionFCVisibilityConverter.Converter
				});
				FrameworkElementFactory frameworkElementFactory3 = new FrameworkElementFactory(typeof(Grid));
				frameworkElementFactory3.SetValue(FrameworkElement.MarginProperty, new Thickness(2.0));
				frameworkElementFactory3.AppendChild(frameworkElementFactory);
				frameworkElementFactory3.AppendChild(frameworkElementFactory2);
				dataTemplate.VisualTree = frameworkElementFactory3;
			}
			if (dataTemplate != null)
			{
				style.Setters.Add(new Setter(ContentControl.ContentTemplateProperty, dataTemplate));
			}
			if (mmfield.ParentScrollArea.ColumnHeaderHeight.HasValue)
			{
				style.Setters.Add(new Setter(FrameworkElement.HeightProperty, mmfield.ParentScrollArea.ColumnHeaderHeight.Value));
			}
			mmfield.Field.Settings.LabelPresenterStyle = style;
		}

		private static ControlTemplate GetManualRecordModeTemplate(MMScrollAreaField mmfield)
		{
			FrameworkElementFactory root = null;
			ControlTemplate rootTemplate = GetRootTemplate(mmfield, out root);
			FrameworkElementFactory frameworkElementFactory = new FrameworkElementFactory(typeof(ContentControl));
			string text = "DataItem.Fields[" + mmfield.Id + "]";
			frameworkElementFactory.SetBinding(ContentControl.ContentProperty, new Binding(text)
			{
				FallbackValue = null,
				Mode = BindingMode.OneTime
			});
			frameworkElementFactory.SetBinding(UIElement.IsEnabledProperty, new Binding(text + ".IsEnabled")
			{
				FallbackValue = true,
				Mode = BindingMode.OneWay
			});
			frameworkElementFactory.SetValue(ContentControl.ContentTemplateSelectorProperty, new ManualLayoutCellTemplateSelector());
			frameworkElementFactory.SetValue(FrameworkElement.VerticalAlignmentProperty, VerticalAlignment.Center);
			frameworkElementFactory.SetValue(Control.VerticalContentAlignmentProperty, VerticalAlignment.Center);
			root.AppendChild(frameworkElementFactory);
			foreach (TriggerBase trigger in (mmfield.ParentScrollArea.FindResource("CellValuePresenterTemplate") as ControlTemplate).Triggers)
			{
				rootTemplate.Triggers.Add(trigger);
			}
			return rootTemplate;
		}

		private static ControlTemplate GetGridFieldTemplate(MMScrollAreaGridField mmfield)
		{
			FrameworkElementFactory root = null;
			ControlTemplate rootTemplate = GetRootTemplate(mmfield, out root);
			FrameworkElementFactory elementFactoryForCell = GetElementFactoryForCell(typeof(MMScrollArea));
			elementFactoryForCell.SetValue(FrameworkElement.MarginProperty, new Thickness(0.0, 0.0, 1.0, 1.0));
			elementFactoryForCell.SetValue(MMScrollAreaBase.IsColumnHeaderVisibleProperty, false);
			elementFactoryForCell.SetValue(MMScrollAreaBase.IsRecordSelectorVisibleProperty, false);
			elementFactoryForCell.SetValue(MMScrollArea.DataPropertyProperty, (!string.IsNullOrEmpty(mmfield.PropertyPath)) ? ("DataItem." + mmfield.PropertyPath) : "DataItem");
			elementFactoryForCell.SetValue(MMScrollArea.MMFieldsDPProperty, mmfield.MMFields);
			root.AppendChild(elementFactoryForCell);
			return rootTemplate;
		}

		private static ControlTemplate GetLineFormatField(MMScrollAreaLineFormatField mmfield)
		{
			FrameworkElementFactory root = null;
			ControlTemplate rootTemplate = GetRootTemplate(mmfield, out root);
			FrameworkElementFactory elementFactoryForCell = GetElementFactoryForCell(typeof(MMLineFormatBox));
			if (mmfield != null && !string.IsNullOrEmpty(mmfield.PropertyPath))
			{
				elementFactoryForCell.SetValue(AesVariableControlBase.VariablePathProperty, "DataItem." + mmfield.PropertyPath);
			}
			root.AppendChild(elementFactoryForCell);
			return rootTemplate;
		}

		private static ControlTemplate GetButtonFieldTemplate(MMScrollAreaButtonField mmfield)
		{
			FrameworkElementFactory root = null;
			ControlTemplate rootTemplate = GetRootTemplate(mmfield, out root);
			FrameworkElementFactory frameworkElementFactory = null;
			if (mmfield is MMScrollAreaDeleteButtonField)
			{
				frameworkElementFactory = GetElementFactoryForCell(typeof(MMDeleteButton));
				frameworkElementFactory.SetValue(Control.BackgroundProperty, System.Windows.Media.Brushes.Transparent);
				frameworkElementFactory.SetValue(Control.BorderBrushProperty, System.Windows.Media.Brushes.Transparent);
			}
			else
			{
				frameworkElementFactory = GetElementFactoryForCell(typeof(MMCmdButton));
			}
			frameworkElementFactory.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Stretch);
			frameworkElementFactory.SetValue(ContentControl.ContentProperty, mmfield.Caption);
			Binding binding = null;
			frameworkElementFactory.SetBinding(binding: (!string.IsNullOrEmpty(mmfield.CommandParameterPath)) ? new Binding("DataItem." + mmfield.CommandParameterPath) : new Binding("Index"), dp: ButtonBase.CommandParameterProperty);
			frameworkElementFactory.SetBinding(ButtonBase.CommandProperty, new Binding(mmfield.CommandPath)
			{
				Source = mmfield.ParentScrollArea.DataContext
			});
			if (mmfield != null && !string.IsNullOrEmpty(mmfield.PropertyPath))
			{
				frameworkElementFactory.SetValue(AesVariableControlBase.VariablePathProperty, "DataItem." + mmfield.PropertyPath);
				frameworkElementFactory.SetBinding(UIElement.VisibilityProperty, new Binding("DataItem." + mmfield.PropertyPath + ".IsVisible")
				{
					Converter = IsVisibleConverter.Converter
				});
			}
			root.AppendChild(frameworkElementFactory);
			return rootTemplate;
		}

		private static ControlTemplate GetFortranLineFieldTemplate(MMScrollAreaFortranLineField mmfield)
		{
			FrameworkElementFactory root = null;
			ControlTemplate rootTemplate = GetRootTemplate(mmfield, out root);
			FrameworkElementFactory elementFactoryForCell = GetElementFactoryForCell(typeof(MMFortranLine));
			elementFactoryForCell.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Stretch);
			elementFactoryForCell.SetValue(AesTextEdit.IsInScrollAreaProperty, true);
			elementFactoryForCell.SetBinding(AesVariableControlBase.VariableProperty, new Binding("DataItem." + mmfield.PropertyPath));
			root.AppendChild(elementFactoryForCell);
			return rootTemplate;
		}

		private static ControlTemplate GetRootTemplate(MMScrollAreaField mmfield, out FrameworkElementFactory root)
		{
			ControlTemplate controlTemplate = new ControlTemplate();
			root = new FrameworkElementFactory(typeof(Grid));
			root.SetValue(Panel.BackgroundProperty, new TemplateBindingExtension(Control.BackgroundProperty));
			FrameworkElementFactory frameworkElementFactory = new FrameworkElementFactory(typeof(Border));
			frameworkElementFactory.SetValue(Border.BorderThicknessProperty, new Thickness(0.0, 0.0, 1.0, 1.0));
			frameworkElementFactory.SetValue(Border.BorderBrushProperty, mmfield.ParentScrollArea.FindResource("GridLineBrush"));
			root.AppendChild(frameworkElementFactory);
			controlTemplate.VisualTree = root;
			return controlTemplate;
		}

		private static FrameworkElementFactory GetElementFactoryForCell(Type type)
		{
			FrameworkElementFactory frameworkElementFactory = new FrameworkElementFactory(type);
			frameworkElementFactory.SetValue(Control.VerticalContentAlignmentProperty, VerticalAlignment.Center);
			return frameworkElementFactory;
		}

		private static string SetupComboField(MMScrollAreaField mmfield)
		{
			if (!(mmfield is MMScrollAreaComboValueField mMScrollAreaComboValueField))
			{
				return null;
			}
			mmfield.Field.Settings.EditorType = typeof(AesXamComboEdit);
			string result = ((!string.IsNullOrEmpty(mmfield.PropertyPath)) ? (mmfield.PropertyPath + "." + mMScrollAreaComboValueField.VariableDataMemberResolved) : mMScrollAreaComboValueField.VariableDataMemberResolved);
			Style style = new Style(basedOn: mmfield.ParentScrollArea.FindResource("AesXamComboEditStyle") as Style, targetType: typeof(AesXamComboEdit));
			if (mmfield.IsManualRecordMode)
			{
				style.Setters.Add(new Setter(AesXamComboEdit.VariablePathProperty, mmfield.PropertyPath));
				style.Setters.Add(new Setter(FrameworkElement.DataContextProperty, new Binding("DataContext")
				{
					RelativeSource = new RelativeSource(RelativeSourceMode.FindAncestor, typeof(MMScrollArea), 1)
				}));
			}
			else
			{
				style.Setters.Add(new Setter(AesXamComboEdit.VariablePathProperty, (!string.IsNullOrEmpty(mmfield.PropertyPath)) ? ("DataItem." + mmfield.PropertyPath) : "DataItem"));
			}
			if (mmfield is MMScrollAreaUnitsField mMScrollAreaUnitsField)
			{
				style.Setters.Add(new Setter(AesXamComboEdit.ShouldBindIsEnabledToIsReadOnlyProperty, mMScrollAreaUnitsField.ShouldBindIsEnabledToIsReadOnly));
			}
			style.Setters.Add(new Setter(AesXamComboEdit.DisplayedCaseProperty, mMScrollAreaComboValueField.DisplayedCase));
			style.Setters.Add(new Setter(AesXamComboEdit.VariableDataMemberProperty, mMScrollAreaComboValueField.VariableDataMemberResolved));
			style.Setters.Add(new Setter(AesXamComboEdit.MaskProperty, mMScrollAreaComboValueField.Mask));
			style.Setters.Add(new Setter(XamComboEditor.IsEditableProperty, mMScrollAreaComboValueField.IsEditable));
			style.Setters.Add(new Setter(AesXamComboEdit.DisplayValueToRenderTextConverterProperty, mMScrollAreaComboValueField.DisplayValueToRenderTextConverter));
			style.Setters.Add(new Setter(AesXamComboEdit.MaskProperty, mMScrollAreaComboValueField.Mask));
			style.Setters.Add(new Setter(AesXamComboEdit.DisplayAsTextBoxProperty, mMScrollAreaComboValueField.DisplayAsTextBox));
			style.Setters.Add(new Setter(AesXamComboEdit.DisallowClearProperty, mMScrollAreaComboValueField.DisallowClear));
			style.Setters.Add(new Setter(AesXamComboEdit.TooltipTemplateProperty, mMScrollAreaComboValueField.TooltipTemplate));
			style.Setters.Add(new Setter(AesXamComboEdit.ItemTooltipTemplateProperty, mMScrollAreaComboValueField.ItemTooltipTemplate));
			if (!string.IsNullOrEmpty(mMScrollAreaComboValueField.ValueOptionsPath))
			{
				style.Setters.Add(new Setter(XamComboEditor.ItemsSourceProperty, new Binding
				{
					RelativeSource = new RelativeSource(RelativeSourceMode.Self),
					Path = new PropertyPath("DataContext.DataItem." + mMScrollAreaComboValueField.ValueOptionsPath)
				}));
			}
			if (!string.IsNullOrEmpty(mMScrollAreaComboValueField.ValuePath))
			{
				style.Setters.Add(new Setter(ValueEditor.ValueProperty, new Binding
				{
					RelativeSource = new RelativeSource(RelativeSourceMode.Self),
					Path = new PropertyPath("DataContext.DataItem." + mMScrollAreaComboValueField.ValuePath)
				}));
			}
			if (!string.IsNullOrEmpty(mMScrollAreaComboValueField.PromptsDictionaryPath))
			{
				style.Setters.Add(new Setter(AesXamComboEdit.PromptsDictionaryProperty, new Binding
				{
					RelativeSource = new RelativeSource(RelativeSourceMode.Self),
					Path = new PropertyPath("DataContext.DataItem." + mMScrollAreaComboValueField.PromptsDictionaryPath)
				}));
			}
			AddHelpProperty(mmfield, style);
			mmfield.Field.Settings.EditorStyle = style;
			SetCellIsEnabled(mmfield);
			return result;
		}

		private static string SetupValueField(MMScrollAreaField mmfield)
		{
			if (!(mmfield is MMScrollAreaValueField mMScrollAreaValueField))
			{
				return null;
			}
			mmfield.Field.Settings.EditorType = typeof(AesXamValueEdit);
			string result = ((!string.IsNullOrEmpty(mmfield.PropertyPath)) ? (mmfield.PropertyPath + "." + mMScrollAreaValueField.VariableDataMemberResolved) : mMScrollAreaValueField.VariableDataMemberResolved);
			if (mMScrollAreaValueField.IsGrayOut)
			{
				Style style = new Style(basedOn: mmfield.ParentScrollArea.FindResource("CellValuePresenterStyle") as Style, targetType: typeof(CellValuePresenter));
				System.Windows.Media.Brush value = mmfield.ParentScrollArea.FindResource("DisabledCellBrush") as System.Windows.Media.Brush;
				style.Setters.Add(new Setter(UIElement.IsEnabledProperty, false));
				style.Setters.Add(new Setter(Control.BackgroundProperty, value));
				mmfield.Field.Settings.CellValuePresenterStyle = style;
			}
			if (mmfield.ParentScrollArea.Name != "grdSubstrAttr" || mmfield.Header.LabelText == "Weight fraction")
			{
				Style style2 = new Style(basedOn: mmfield.ParentScrollArea.FindResource("AesXamValueEditStyle") as Style, targetType: typeof(AesXamValueEdit))
				{
					Setters = 
					{
						(SetterBase)new Setter(AesXamValueEdit.VariablePathProperty, (!string.IsNullOrEmpty(mmfield.PropertyPath)) ? ("DataItem." + mmfield.PropertyPath) : "DataItem"),
						(SetterBase)new Setter(AesXamValueEdit.VariableDataMemberProperty, mMScrollAreaValueField.VariableDataMemberResolved),
						(SetterBase)new Setter(AesXamValueEdit.MaxLengthProperty, mMScrollAreaValueField.MaxLength),
						(SetterBase)new Setter(AesXamValueEdit.DisplayedCaseProperty, mMScrollAreaValueField.DisplayedCase),
						(SetterBase)new Setter(AesXamValueEdit.CharacterCasingProperty, mMScrollAreaValueField.CharacterCasing),
						(SetterBase)new Setter(AesXamValueEdit.MaskProperty, mMScrollAreaValueField.Mask),
						(SetterBase)new Setter(AesXamValueEdit.IsInScrollAreaProperty, true)
					}
				};
				Type type = mMScrollAreaValueField.GetType();
				if (type == typeof(MMScrollAreaSpinField))
				{
					style2.Setters.Add(new Setter(AesXamValueEdit.SpinVisibilityProperty, Visibility.Visible));
					style2.Setters.Add(new Setter(XamTextEditor.TextAlignmentProperty, TextAlignment.Right));
					style2.Setters.Add(new Setter(Control.HorizontalContentAlignmentProperty, HorizontalAlignment.Right));
				}
				else if (typeof(MMScrollAreaBrowseField).IsAssignableFrom(type))
				{
					MMScrollAreaBrowseField mMScrollAreaBrowseField = mMScrollAreaValueField as MMScrollAreaBrowseField;
					style2.Setters.Add(new Setter(AesXamValueEdit.BrowseVisibilityProperty, new Binding("BrowseVisibility")
					{
						Source = mMScrollAreaBrowseField
					}));
					if (mMScrollAreaBrowseField.BrowseCommand != null)
					{
						style2.Setters.Add(new Setter(AesXamValueEdit.BrowseCommandProperty, mMScrollAreaBrowseField.BrowseCommand));
					}
				}
				else if (type == typeof(MMScrollAreaTextField))
				{
					MMScrollAreaTextField mMScrollAreaTextField = mMScrollAreaValueField as MMScrollAreaTextField;
					if (!string.IsNullOrEmpty(mMScrollAreaTextField.Text))
					{
						style2.Setters.Add(new Setter(ValueEditor.TextProperty, mMScrollAreaTextField.Text));
					}
				}
				AddHelpProperty(mmfield, style2);
				mmfield.Field.Settings.EditorStyle = style2;
			}
			SetCellIsEnabled(mmfield);
			return result;
		}

		private static void SetupCheckField(MMScrollAreaField mmfield)
		{
			if (mmfield is MMScrollAreaCheckBoxField mMScrollAreaCheckBoxField)
			{
				mmfield.Field.Settings.EditorType = typeof(AesXamCheckEdit);
				Style basedOn = mmfield.ParentScrollArea.FindResource("AesXamCheckEditStyle") as Style;
				if (mMScrollAreaCheckBoxField.DisplayAsRadioButton)
				{
					basedOn = mmfield.ParentScrollArea.FindResource("AesXamCheckEditAsRadioButtonStyle") as Style;
				}
				Style style = new Style(typeof(AesXamCheckEdit), basedOn);
				style.Setters.Add(new Setter(AesXamCheckEdit.VariablePathProperty, (!string.IsNullOrEmpty(mmfield.PropertyPath)) ? ("DataItem." + mmfield.PropertyPath) : "DataItem"));
				AddHelpProperty(mmfield, style);
				mmfield.Field.Settings.EditorStyle = style;
				SetCellIsEnabled(mmfield);
			}
		}

		private static void AddHelpProperty(MMScrollAreaField mmfield, Style editorStyle)
		{
			if (mmfield.HelpFile != null)
			{
				editorStyle.Setters.Add(new Setter(MMHelp.HelpFileProperty, mmfield.HelpFile));
			}
			else if (MMHelp.GetHelpFile(mmfield) != null)
			{
				editorStyle.Setters.Add(new Setter(MMHelp.HelpFileProperty, mmfield.GetValue(MMHelp.HelpFileProperty)));
			}
			if (mmfield.HelpId.HasValue)
			{
				editorStyle.Setters.Add(new Setter(MMHelp.HelpIdProperty, mmfield.HelpId.Value));
			}
			else if (MMHelp.GetHelpId(mmfield).HasValue && MMHelp.GetHelpId(mmfield) != 0)
			{
				editorStyle.Setters.Add(new Setter(MMHelp.HelpIdProperty, mmfield.GetValue(MMHelp.HelpIdProperty)));
			}
		}

		private static void AddFieldHelpBinding(MMScrollAreaField mmfield, Style editorStyle)
		{
			if ((mmfield.UseFieldHelp ?? false) && !string.IsNullOrEmpty(mmfield.PropertyPath))
			{
				editorStyle.Setters.Add(new Setter(MMHelp.HelpFileProperty, new Binding("DataItem." + mmfield.PropertyPath + ".HelpFile")));
				editorStyle.Setters.Add(new Setter(MMHelp.HelpIdProperty, new Binding("DataItem." + mmfield.PropertyPath + ".HelpId")));
			}
		}

		private static void SetCellIsEnabled(MMScrollAreaField mmfield)
		{
			if (!string.IsNullOrEmpty(mmfield.IsEnabledBindingPath))
			{
				Style basedOn = mmfield.ParentScrollArea.FindResource("CellValuePresenterStyle") as Style;
				Style style = new Style(typeof(CellValuePresenter), basedOn);
				System.Windows.Media.Brush value = mmfield.ParentScrollArea.FindResource("DisabledCellBrush") as System.Windows.Media.Brush;
				style.Triggers.Add(new DataTrigger
				{
					Binding = new Binding("DataItem." + mmfield.IsEnabledBindingPath + ".Value"),
					Value = false,
					Setters = 
					{
						(SetterBase)new Setter(UIElement.IsEnabledProperty, false),
						(SetterBase)new Setter(Control.BackgroundProperty, value)
					}
				});
				mmfield.Field.Settings.CellValuePresenterStyle = style;
			}
			else if (!mmfield.IsEnabled)
			{
				Style basedOn2 = mmfield.ParentScrollArea.FindResource("CellValuePresenterStyle") as Style;
				Style style2 = new Style(typeof(CellValuePresenter), basedOn2);
				mmfield.ParentScrollArea.FindResource("DisabledCellBrush");
				style2.Setters.Add(new Setter(UIElement.IsEnabledProperty, false));
				mmfield.Field.Settings.CellValuePresenterStyle = style2;
			}
		}

		private static string AddUnitToLabel(MMScrollAreaField mmfield, FrameworkElementFactory root)
		{
			string text = null;
			if (mmfield != null)
			{
				if (!string.IsNullOrEmpty(mmfield.HeaderUnitsProperty))
				{
					string[] array = mmfield.HeaderUnitsProperty.Split(',');
					string[] array2 = null;
					if (!string.IsNullOrEmpty(mmfield.HeaderTypeProperty))
					{
						array2 = mmfield.HeaderTypeProperty.Split(',');
					}
					int num = 1;
					num = ((array2 != null) ? array2.Length : array.Length);
					for (int num2 = num; num2 > 0; num2--)
					{
						string text2 = ((array.Length < num2) ? array[array.Length - 1] : array[num2 - 1]);
						text2 = text2.Trim();
						string text3 = ((array2 == null) ? "" : ((array2.Length >= num2) ? array2[num2 - 1] : ""));
						text3 = text3.Trim().ToLowerInvariant();
						if (string.IsNullOrEmpty(text3))
						{
							text3 = "units";
						}
						FrameworkElementFactory frameworkElementFactory = null;
						switch (text3)
						{
						case "units":
							frameworkElementFactory = new FrameworkElementFactory(typeof(MMUnitsEdit));
							if (!mmfield.IsHeaderUnitsEnabled)
							{
								frameworkElementFactory.SetValue(UIElement.IsEnabledProperty, false);
							}
							frameworkElementFactory.SetValue(AesComboEdit.IsInScrollAreaColumnHeaderProperty, true);
							break;
						case "id":
							frameworkElementFactory = new FrameworkElementFactory(typeof(MMComboEdit));
							frameworkElementFactory.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Stretch);
							frameworkElementFactory.SetValue(AesComboEdit.VariableDataMemberProperty, "Value");
							if (text == null)
							{
								text = text2 + ".Value";
							}
							frameworkElementFactory.SetValue(AesComboEdit.IsInScrollAreaColumnHeaderProperty, true);
							break;
						case "selecteditem":
							frameworkElementFactory = new FrameworkElementFactory(typeof(MMComboEdit));
							frameworkElementFactory.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Stretch);
							frameworkElementFactory.SetValue(AesComboEdit.VariableDataMemberProperty, "SelectedItem");
							frameworkElementFactory.SetValue(AesComboEdit.IsInScrollAreaColumnHeaderProperty, true);
							break;
						case "basis":
							frameworkElementFactory = new FrameworkElementFactory(typeof(MMBasisEdit));
							frameworkElementFactory.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Stretch);
							frameworkElementFactory.SetValue(AesComboEdit.IsInScrollAreaColumnHeaderProperty, true);
