		private static bool InteractiveLoadResultsOff(this MMViewModel viewModel)
		{
			CxsDataProvider cxsDataProvider = viewModel.UnityContainer.Resolve<CxsDataProvider>(Array.Empty<ResolverOverride>());
			int? num = CxsConverter.ValueToInt32(cxsDataProvider.BatchGet("Top.appmodelV8.Settings.partial", "value", null));
			if (num == 1)
			{
				CxsBatchRequestData cxsBatchRequestData = new CxsBatchRequestData();
				cxsBatchRequestData.AddRequest("Top.Solver.InteractivelyLoad", "value", null, 0);
				cxsDataProvider.BatchSetNoRefresh(cxsBatchRequestData);
			}
			return Convert.ToBoolean(num);
		}

		private static void InteractiveLoadResultsOn(this MMViewModel viewModel)
		{
			CxsDataProvider cxsDataProvider = viewModel.UnityContainer.Resolve<CxsDataProvider>(Array.Empty<ResolverOverride>());
			CxsBatchRequestData cxsBatchRequestData = new CxsBatchRequestData();
			cxsBatchRequestData.AddRequest("Top.Solver.InteractivelyLoad", "value", null, 1);
			cxsDataProvider.BatchSetNoRefresh(cxsBatchRequestData);
		}

