		public static int GxAddStream(this MMViewModel viewModel, string streamType, int addFlag)
		{
			CxvActionResult cxvActionResult = viewModel.InvokeAction("Top.appModelV8.Custom Actions", "gxAddStream", true, streamType, addFlag);
			int? num = (cxvActionResult.Succeeded ? CxsConverter.ValueToInt32(cxvActionResult.Result) : new int?(0));
			if (!num.HasValue)
			{
				return 0;
			}
			return num.Value;
		}

