		private static string GetObjectIdSegment(string path, int offset)
		{
			if (string.IsNullOrEmpty(path))
			{
				return null;
			}
			if (offset < 0)
			{
				return null;
			}
			int num = path.IndexOf(".Input.");
			int length = ".Input.".Length;
			if (num < 0)
			{
				if (path.Contains(".Output.STR_MAIN."))
				{
					num = path.IndexOf(".Output.STR_MAIN.");
					length = ".Output.STR_MAIN.".Length;
				}
				else if (path.Contains(".Output.STR_CATT."))
				{
					num = path.IndexOf(".Output.STR_CATT.");
					length = ".Output.STR_CATT.".Length;
				}
				else if (path.Contains(".Output.SUBSATTR."))
				{
					num = path.IndexOf(".Output.SUBSATTR.");
					length = ".Output.SUBSATTR.".Length;
				}
				else
				{
					num = path.IndexOf(".Output.");
					length = ".Output.".Length;
				}
			}
			if (num > 0)
			{
				string text = path.Substring(num + length);
				if (!string.IsNullOrEmpty(text))
				{
					string[] array = text.Split('.');
					if (array.Length > offset)
					{
						return array[offset];
					}
				}
			}
			else if (offset == 0 && path.IndexOf(".EO Flowsheet.") > 0)
			{
				int num2 = path.LastIndexOf(".\"");
				if (num2 > 0 && path.Length > num2 + 2)
				{
					string text2 = path.Substring(num2 + 2);
					if (text2.LastOrDefault() == '"')
					{
						return text2.Substring(0, text2.Length - 1);
					}
				}
			}
			return null;
		}

