		public static bool IsOneOfStreamSpecial(string csPath, ref int nLength, ref int nPos, ref int itype)
		{
			nPos = -1;
			itype = -1;
			if (IsOutputStreamMain(csPath))
			{
				nPos = csPath.IndexOf(".Output.STR_MAIN.");
				nLength = ".Output.STR_MAIN.".Length;
				itype = 1;
			}
			else if (IsOutputStreamCattr(csPath))
			{
				nPos = csPath.IndexOf(".Output.STR_CATT.");
				nLength = ".Output.STR_CATT.".Length;
				itype = 2;
			}
			else
			{
				if (!IsOutputStreamSubsattr(csPath))
				{
					return false;
				}
				nPos = csPath.IndexOf(".Output.SUBSATTR.");
				nLength = ".Output.SUBSATTR.".Length;
				itype = 3;
			}
			return true;
		}

