				{
					"ZVN", "F", "FV", "D", "DE", "DEF", "A", "B", "C", "D",
					"E", "F"
				};
				string[] array4 = new string[12]
				{
					"V", "VA", "VAR", "D", "DE", "DEF", "A", "B", "C", "D",
					"E", "F"
				};
				while (flag3 || sUniqueId.Length > 8)
				{
					if (sUniqueId.Length > 8)
					{
						if (flag2)
						{
							sUniqueId = array4[num2];
						}
						else
						{
							sUniqueId = array3[num2];
						}
						num2++;
					}
					string text3 = sUniqueId;
					for (int i = 1; i < 1000; i++)
					{
						if (eAccessType == VarAcessType.Define || flag2)
						{
							if (i == 1)
							{
								sUniqueId = text3;
							}
							else
							{
								sUniqueId = text3 + i;
							}
						}
						else
						{
							sUniqueId = i.ToString();
						}
						flag3 = false;
						string[] array5 = array2;
						for (int j = 0; j < array5.Length; j++)
						{
							if (string.Compare(array5[j].ToString(), sUniqueId, StringComparison.OrdinalIgnoreCase) == 0)
							{
								flag3 = true;
