		public static void ProcessVarAccessIdSegment(MMViewModel viewModel, string sSourcePath, string sidSegment, ref Dictionary<string, string> dictIdToValue)
		{
			string[] array = sidSegment.Split('=');
			if (array.Length <= 1)
			{
				return;
			}
			string text = array[0].ToUpper().Trim();
			string text2 = array[1].ToUpper().Trim().Replace("-", "_");
			if (int.TryParse(text2, out var _))
			{
				if (text == "ELEM")
				{
					text2 = ((!int.TryParse(text2, out var result2)) ? ("#" + text2) : ("#" + (result2 - 1)));
				}
				if (dictIdToValue.ContainsKey(text))
				{
					dictIdToValue[text] = text2;
				}
				else
				{
					dictIdToValue.Add(text, text2);
				}
				return;
			}
			Dictionary<string, string> dictIdVarToValue = new Dictionary<string, string>();
			string objectIdSegment = GetObjectIdSegment(sSourcePath, 0);
			string value = null;
			if (!string.IsNullOrEmpty(text2) && text2.IndexOf('#') != -1)
			{
				string newValue = text2.Substring(1, text2.Length - 1);
				string dataPath = sSourcePath.Replace(objectIdSegment, newValue);
				string strB = CxsConverter.ValueToString(viewModel.ExpandDataPathAndGet(dataPath, "value"));
				string[] array2 = CxsConverter.ValueToStringArray(viewModel.ExpandDataPathAndGet(dataPath, "option_list"));
				int num = 0;
				string[] array3 = array2;
				foreach (string strA in array3)
				{
					num++;
					if (string.Compare(strA, strB, ignoreCase: true) == 0)
					{
						value = num.ToString();
						break;
					}
				}
			}
			else
			{
				string text3 = sSourcePath.Replace(objectIdSegment, text2);
				bool? flag = CxsConverter.ValueToBoolean(viewModel.ExpandDataPathAndGet(CxsPath.ParentPath(text3), "is_array"));
				if (flag.HasValue && flag.Value)
				{
					value = CxsConverter.ValueToString(viewModel.ExpandDataPathAndGet(text3, "value"));
				}
				else
				{
					MapIdVariable2Value(viewModel, sSourcePath, ref dictIdVarToValue);
					string key = text2.Replace("_", "-");
					value = ((!dictIdVarToValue.ContainsKey(key)) ? CxsConverter.ValueToString(viewModel.ExpandDataPathAndGet(text3, "value")) : dictIdVarToValue[key]);
				}
				if (string.IsNullOrEmpty(value))
				{
					if (dictIdVarToValue == null)
					{
						MapIdVariable2Value(viewModel, sSourcePath, ref dictIdVarToValue);
					}
					string key2 = text2.Replace("_", "-");
					if (dictIdVarToValue.ContainsKey(key2))
					{
						value = dictIdVarToValue[key2];
					}
				}
			}
			if (dictIdToValue.ContainsKey(text))
			{
				dictIdToValue[text] = value;
			}
			else
			{
				dictIdToValue.Add(text, value);
			}
		}

