		public static void RemoveBasisBracket(ref string sAccesVarNameSegment)
		{
			string text = sAccesVarNameSegment;
			string value = "$BASIS";
			string value2 = "$BASIS[";
			int num = text.IndexOf(value2);
			text.IndexOf(value);
			if (num != -1)
			{
				int num2 = text.Substring(num).IndexOf('[') + num;
				int num3 = text.Substring(num2).IndexOf(']') + num2;
				string oldValue = text.Substring(num2, num3 - num2);
				sAccesVarNameSegment.Replace(oldValue, "");
			}
		}

		public static string ParseAccessVarforIdKeyword(MMViewModel viewModel, string sSourcePath, string sAccesVarNameSegment)
		{
			if (string.IsNullOrEmpty(sSourcePath))
			{
				return null;
			}
			string sAccesVarNameSegment2 = sAccesVarNameSegment;
			RemoveBasisBracket(ref sAccesVarNameSegment2);
			if (sAccesVarNameSegment2.IndexOf('[') == -1)
			{
				return null;
			}
			int num = sAccesVarNameSegment2.IndexOf('[');
			int num2 = sAccesVarNameSegment2.IndexOf(']');
			string[] array = sAccesVarNameSegment2.Substring(num + 1, num2 - num - 1).Split(',');
			Dictionary<string, string> dictIdToValue = new Dictionary<string, string>();
			string objectIdSegment = GetObjectIdSegment(sSourcePath, 0);
			string text = sSourcePath.Substring(0, sSourcePath.IndexOf(objectIdSegment)) + objectIdSegment;
			string[] array2 = sSourcePath.Substring(sSourcePath.IndexOf(objectIdSegment)).Split('.');
			int num3 = 0;
			for (int i = 1; i < array2.Length; i++)
			{
				string value = array2[i];
				num3++;
				dictIdToValue.Add("ID" + num3, value);
			}
			string text2 = text;
			for (int j = 0; j < array.Length; j++)
			{
				ProcessVarAccessIdSegment(viewModel, sSourcePath, array[j], ref dictIdToValue);
			}
			string[] array3 = new string[4] { "ID1", "ID2", "ID3", "ELEM" };
			foreach (string key in array3)
			{
				if (dictIdToValue.ContainsKey(key))
				{
					string text3 = dictIdToValue[key];
					if (!string.IsNullOrEmpty(text3))
					{
						text2 = text2 + "." + text3.Trim();
					}
				}
			}
			return text2;
		}

		public static void ParseAccessVarforSystemKeyWords(MMViewModel viewModel, string sSourcePath, string sBasisValue, ref string sAccesVarNameSegment)
		{
			if (string.IsNullOrEmpty(sBasisValue))
			{
				return;
			}
			string text = sAccesVarNameSegment;
			string text2 = "$BASIS";
			string value = "$BASIS[";
			int num = text.IndexOf(value);
			int num2 = text.IndexOf(text2);
			if (num != -1)
			{
				int num3 = text.Substring(num).IndexOf('[') + num;
				int num4 = text.Substring(num3).IndexOf(']') + num3;
				string text3 = text.Substring(0, num);
				string sTrimmedVar = text.Substring(num4 + 1);
				TrimRecMappedAccessVariable(sTrimmedVar, ref sTrimmedVar);
				string[] array = text.Substring(num3 + 1, num4 - num3 - 1).Split(';');
				string text4 = sBasisValue;
				bool flag = false;
				string[] array2 = array;
				for (int i = 0; i < array2.Length; i++)
				{
					string[] array3 = array2[i].Split('=');
					if (array3.Count() > 1 && string.Compare(array3[0], sBasisValue, ignoreCase: true) == 0)
					{
						text4 = ((!string.IsNullOrEmpty(array3[1]) && !(array3[1] == " ")) ? array3[1].Trim().ToUpper() : "*");
						flag = true;
					}
				}
				if (flag)
				{
					if (text4.CompareTo("*") == 0)
					{
						if (sTrimmedVar[0] == '-')
						{
							sTrimmedVar = sTrimmedVar.Substring(1);
						}
						sAccesVarNameSegment = text3 + sTrimmedVar;
					}
					else
					{
						sAccesVarNameSegment = text3 + text4 + sTrimmedVar;
					}
					sAccesVarNameSegment = sAccesVarNameSegment.Trim();
					if (sAccesVarNameSegment.Length > 12)
					{
						sAccesVarNameSegment.Substring(12);
					}
				}
				else
				{
					sAccesVarNameSegment = text3 + sBasisValue + sTrimmedVar;
					if (sAccesVarNameSegment.Length > 12)
					{
						sAccesVarNameSegment.Substring(12);
					}
				}
			}
			else if (num2 != -1)
			{
				TrimRecMappedAccessVariable(sAccesVarNameSegment, ref sAccesVarNameSegment);
				sAccesVarNameSegment = sAccesVarNameSegment.Replace(text2, sBasisValue);
				if (sAccesVarNameSegment.Length > 12)
				{
					sAccesVarNameSegment = sAccesVarNameSegment.Substring(0, 12);
				}
			}
		}

		public static bool EvaluateExpression(MMViewModel viewModel, string sSourcePath, string sToEvaluate, ref string sAccessVarName)
		{
			if (string.IsNullOrEmpty(sToEvaluate))
			{
				return false;
			}
			sToEvaluate = sToEvaluate.Trim();
			string[] array = sToEvaluate.Split(' ');
			int num = sToEvaluate.Split('@').Length - 1;
			int num2 = 0;
			for (int i = 0; i < num; i++)
			{
				if (string.Compare(array[i].Substring(0, 1), "@") == 0 && CompareValues(viewModel, sSourcePath, array[i]))
				{
					num2++;
				}
			}
			if (num2 > 0 && num2 == num)
			{
				sAccessVarName = array[num];
				return true;
			}
			return false;
		}

		public static bool CompareValues(MMViewModel viewModel, string sSourcePath, string sExpressionItem)
		{
			if (string.Compare(sExpressionItem.Substring(0, 1), "@") != 0)
			{
				return false;
			}
			string[] array = sExpressionItem.Split('=');
			if (array.Count() > 2)
			{
				return false;
			}
			string objectIdSegment = GetObjectIdSegment(sSourcePath, 0);
			if (string.IsNullOrEmpty(objectIdSegment))
			{
				return false;
			}
			string newValue = "Input." + array[0].Replace("@", "").Trim().ToUpper();
			string text = sSourcePath.Replace("Input." + objectIdSegment, newValue);
			string text2 = CxsConverter.ValueToString(viewModel.ExpandDataPathAndGet(text, "value"));
			if (string.IsNullOrEmpty(text2))
			{
				string sReconstructedPath = string.Empty;
				GetParameterPath(viewModel, text, ref sReconstructedPath);
				text2 = CxsConverter.ValueToString(viewModel.ExpandDataPathAndGet(sReconstructedPath, "value"));
			}
			if (!string.IsNullOrEmpty(text2) && string.Compare(text2.ToUpper(), array[1].Trim().ToUpper(), ignoreCase: true) == 0)
			{
				return true;
			}
			return false;
		}

		public static string ParseVariablePath(MMViewModel viewModel, string cxsDroppedPastedPath)
