namespace AspenTech.AspenPlus.MMControls.Utils
{
	public static class VisualControlsSearch
	{
		public static T GetParentObject<T>(DependencyObject obj, string name) where T : FrameworkElement
		{
			for (DependencyObject parent = VisualTreeHelper.GetParent(obj); parent != null; parent = VisualTreeHelper.GetParent(parent))
			{
				if (parent is T val && (val.Name == name || string.IsNullOrEmpty(name)))
				{
					return val;
				}
			}
			return null;
		}

		public static T GetChildObject<T>(DependencyObject obj, string name) where T : FrameworkElement
		{
			DependencyObject dependencyObject = null;
			T val = null;
			for (int i = 0; i <= VisualTreeHelper.GetChildrenCount(obj) - 1; i++)
			{
				dependencyObject = VisualTreeHelper.GetChild(obj, i);
				if (dependencyObject is T val2 && (val2.Name == name || string.IsNullOrEmpty(name)))
				{
					return val2;
				}
				val = GetChildObject<T>(dependencyObject, name);
				if (val != null)
				{
					return val;
				}
			}
			return null;
		}

		public static T GetFirstChildObject<T>(DependencyObject obj) where T : FrameworkElement
		{
			DependencyObject dependencyObject = null;
			T val = null;
			for (int i = 0; i <= VisualTreeHelper.GetChildrenCount(obj) - 1; i++)
			{
				dependencyObject = VisualTreeHelper.GetChild(obj, i);
				if (dependencyObject is T result)
				{
					return result;
				}
				val = GetFirstChildObject<T>(dependencyObject);
				if (val != null)
				{
					return val;
				}
			}
			return null;
		}

		public static IEnumerable<T> FindVisualChildren<T>(DependencyObject obj) where T : FrameworkElement
		{
			if (obj == null)
			{
				yield break;
			}
			for (int i = 0; i < VisualTreeHelper.GetChildrenCount(obj); i++)
			{
				DependencyObject childObject = VisualTreeHelper.GetChild(obj, i);
				if (childObject != null && childObject is T)
				{
					yield return (T)childObject;
				}
				foreach (T item in FindVisualChildren<T>(childObject))
				{
					yield return item;
				}
			}
		}
	}
}
namespace AspenTech.AspenPlus.MMControls.ScrollArea
