	internal static class ScrollAreaDropHelper
	{
		public static bool IsDropping { get; set; }

		public static bool DoDrop(MMScrollAreaBase sab, DragEventArgs dea)
		{
			if (sab == null)
			{
				throw new ArgumentNullException("sab");
			}
			if (dea == null)
			{
				throw new ArgumentNullException("dea");
			}
			IDataObject data = dea.Data;
			MMHorizontalListEdit mMHorizontalListEdit = sab as MMHorizontalListEdit;
			CellValuePresenter cellValuePresenter = GetCellValuePresenter(dea.OriginalSource);
			if (cellValuePresenter == null)
			{
				return false;
			}
			if (mMHorizontalListEdit != null)
			{
				return DoDropInternal(mMHorizontalListEdit, data, cellValuePresenter);
			}
			return DoDropInternal(sab, data, cellValuePresenter);
		}

		private static bool DoDropInternal(MMHorizontalListEdit hle, IDataObject data, CellValuePresenter cvp)
		{
			int num = cvp.Record.Index;
			try
			{
				IList<IList<string>> plainTexts = data.GetPlainTexts();
				if (plainTexts.Count > 0)
				{
					for (int i = 0; i < plainTexts.Count; i++)
					{
						for (int j = 0; j < plainTexts[i].Count; j++)
						{
							(hle.DataGrid.Records[num] as DataRecord).Cells[0].Value = plainTexts[i][j];
							num++;
						}
					}
				}
			}
			catch (Exception)
			{
			}
			return true;
		}

		private static bool DoDropInternalForHorizontal(MMScrollArea sa, IDataObject data, CellValuePresenter cvp)
		{
			Mouse.OverrideCursor = Cursors.Wait;
			CxsDataProvider cxsDataProvider = null;
			try
			{
				if (!MMScrollAreaBase.IsCellEditable(cvp))
				{
					return false;
				}
				int num = cvp.Field.ActualPosition.Row;
				int visibleIndex = cvp.Record.VisibleIndex;
				IList<IList<string>> plainTexts = data.GetPlainTexts();
				if (sa.DataContext is CxvViewModel cxvViewModel)
				{
					cxsDataProvider = cxvViewModel.ResolvedCxsProvider;
					if (cxsDataProvider != null)
					{
						cxsDataProvider.Force = true;
						cxsDataProvider.StartBatchPaste();
					}
				}
				for (int i = 0; i < plainTexts.Count; i++)
				{
					IList<string> list = plainTexts[i];
					int num2 = visibleIndex;
					int count = sa.DataGrid.Records.Count;
					int num3 = 0;
					while (num3 < list.Count)
					{
						string text = list[num3];
						if (num2 == count)
						{
							count = sa.DataGrid.Records.Count;
							if (num2 == count)
							{
								break;
							}
						}
						try
						{
							Cell cell = (sa.DataGrid.Records[num2] as DataRecord).Cells[num];
							CellValuePresenter cellValuePresenter = CellValuePresenter.FromCell(cell);
							if (cellValuePresenter != null)
							{
								if (cellValuePresenter.Editor is AesXamValueEdit || cellValuePresenter.Editor is AesXamComboEdit)
								{
									IsDropping = true;
									ApplicationCommands.Paste.Execute((text == null) ? string.Empty : text, cellValuePresenter.Editor);
									IsDropping = false;
								}
							}
							else
							{
								cell.Value = ((text == string.Empty) ? null : text);
							}
						}
						catch (Exception)
						{
						}
						num3++;
						num2++;
					}
					num++;
				}
			}
			catch (Exception)
			{
				AesMessageBox.Show(Window.GetWindow(sa), AspenTech.AspenPlus.MMControls.Properties.Resources.strFailedToPaste);
			}
			finally
			{
				if (cxsDataProvider != null)
				{
					cxsDataProvider.Force = false;
					cxsDataProvider.EndBatchPaste();
				}
				Mouse.OverrideCursor = null;
			}
			return true;
		}

