					{
						int num4 = num;
						if (!(cxvVectorPropertyData.IndexBasis is CxvChildCountIndexBasisData cxvChildCountIndexBasisData) || !cxvVectorPropertyData.AllowNew)
						{
							break;
						}
						if (cxvChildCountIndexBasisData.HasProxyRow)
						{
							num4--;
						}
						cxvVectorPropertyData.Insert(num4, null);
					}
					num++;
				}
				if (cxsDataProvider != null)
				{
					cxsDataProvider.ResumeNotifications();
					cxsDataProvider.SuspendNotifications();
				}
				num = num2;
				for (int j = num3; j < list.Count; j++)
				{
					string text = list[j].Replace("\r", "");
					if (num == mMScrollArea.DataGrid.Records.Count)
					{
						break;
					}
					string[] array = text.Split('\t');
					int num5 = index;
					int num6 = 0;
					while (num6 < array.Length)
					{
						string text2 = array[num6];
						if (num5 == count)
						{
							cxsDataProvider.ResumeNotifications();
							count = sab.DataGrid.DefaultFieldLayout.Fields.Count;
							cxsDataProvider.SuspendNotifications();
							if (num5 == count)
							{
								break;
							}
						}
						if ((sab.DataGrid.Records[num] as DataRecord).Cells[num5].Field.ColumnSpan == 1)
						{
							Cell cell = (mMScrollArea.DataGrid.Records[num] as DataRecord).Cells[num5];
							CellValuePresenter cellValuePresenter = CellValuePresenter.FromCell(cell);
							if (cellValuePresenter != null && (cellValuePresenter.Editor is AesXamValueEdit || cellValuePresenter.Editor is AesXamComboEdit))
							{
								if (ApplicationCommands.Paste.CanExecute((text2 == null) ? string.Empty : text2, cellValuePresenter.Editor))
								{
									IsDropping = true;
									ApplicationCommands.Paste.Execute((text2 == null) ? string.Empty : text2, cellValuePresenter.Editor);
									IsDropping = false;
								}
								else
								{
									cxsDataProvider.BatchPasteError();
								}
							}
							else
							{
								cell.Value = ((text2 == string.Empty) ? null : text2);
							}
							num6++;
						}
						num5++;
					}
					num++;
				}
			}
			catch (Exception)
			{
				AesMessageBox.Show(Window.GetWindow(sab), AspenTech.AspenPlus.MMControls.Properties.Resources.strFailedToPaste);
			}
			finally
			{
				if (cxsDataProvider != null)
				{
					cxsDataProvider.ResumeNotifications();
					cxsDataProvider.Force = false;
					cxsDataProvider.EndBatchPaste();
				}
			}
			return true;
		}

		private static CellValuePresenter GetCellValuePresenter(object originalSource)
		{
			for (DependencyObject dependencyObject = originalSource as DependencyObject; dependencyObject != null; dependencyObject = VisualTreeHelper.GetParent(dependencyObject))
			{
				if (dependencyObject is CellValuePresenter)
				{
					return dependencyObject as CellValuePresenter;
				}
			}
			return null;
		}
	}
	internal static class DataObjectExtension
	{
		public static string GetPlainText(this IDataObject data)
		{
			if (data == null)
			{
				throw new ArgumentNullException("data");
			}
			if (data.GetDataPresent(DataFormats.UnicodeText))
			{
				return data.GetData(DataFormats.UnicodeText) as string;
			}
			if (data.GetDataPresent(DataFormats.Text))
			{
				return data.GetData(DataFormats.Text) as string;
			}
			return null;
		}

		public static IList<IList<string>> GetPlainTexts(this IDataObject data)
		{
			if (data == null)
			{
				throw new ArgumentNullException("data");
			}
			IList<IList<string>> list = new List<IList<string>>();
			string plainText = data.GetPlainText();
			if (!string.IsNullOrWhiteSpace(plainText))
			{
				string[] array = plainText.Split('\n');
				foreach (string text in array)
				{
					if (text == null)
					{
						continue;
					}
					IList<string> list2 = new List<string>();
					string[] array2 = text.Split('\t');
					foreach (string text2 in array2)
					{
						if (text2 == null)
						{
							list2.Add(text2);
						}
						else
						{
							list2.Add(text2.Trim());
						}
					}
					list.Add(list2);
				}
			}
			return list;
		}
	}
}
namespace AspenTech.AspenPlus.MMControls.Plotting
{
	[TemplatePart(Name = "PART_OverlapGrid", Type = typeof(Grid))]
	[TemplatePart(Name = "PART_ContainerBorder", Type = typeof(Border))]
	public class SpecPlotControl : Control
	{
		private class SpecPlotZoomer : ISpecPlotZoomable
		{
			private const double DefaultMinimumZoomFactor = 0.01;

			private const double ZoomInFactor = 0.5;

			private const double ZoomOutFactor = 2.0;

			private readonly SpecPlotControl _parentControl;

			private double _minimumZoomFactor = 0.01;

			private double _xAxisZoomFactor;

			private double _yAxisZoomFactor;

			public double MinimumZoomFactor
			{
				get
				{
					return _minimumZoomFactor;
				}
				set
				{
					if (value > 1.0)
					{
						_minimumZoomFactor = 1.0;
					}
					else if (value < 0.0)
					{
						_minimumZoomFactor = 0.01;
					}
					else
					{
						_minimumZoomFactor = value;
					}
				}
			}

			public double XAxisZoomFactor
			{
				get
				{
					return _xAxisZoomFactor;
				}
				set
				{
					double num = FixZoomFactor(value);
					if (_xAxisZoomFactor != num)
					{
						double xAxisZoomFactor = _xAxisZoomFactor;
						_xAxisZoomFactor = num;
						OnXAxisZoomFactorChanged(xAxisZoomFactor, num);
					}
				}
			}

			public double YAxisZoomFactor
			{
				get
				{
					return _yAxisZoomFactor;
				}
				set
				{
					double num = FixZoomFactor(value);
					if (_yAxisZoomFactor != num)
					{
						double yAxisZoomFactor = _yAxisZoomFactor;
						_yAxisZoomFactor = num;
						OnYAxisZoomFactorChanged(yAxisZoomFactor, num);
					}
				}
			}

			public SpecPlotZoomer(SpecPlotControl parentControl)
			{
				_parentControl = parentControl;
			}

			public void ZoomIn()
			{
				ZoomInXAxis();
				ZoomInYAxis();
			}

			public void ZoomOut()
			{
				ZoomOutXAxis();
				ZoomOutYAxis();
			}

			public void ZoomToFull()
			{
				ZoomToFullXAxis();
				ZoomToFullYAxis();
				_parentControl.ForceUpdateBySizeChange();
			}

			public void ZoomInXAxis()
			{
				SpecPlotValueRange zoomRange = _parentControl.PlotData.ZoomRange;
				if (zoomRange == null || !zoomRange.IsValid)
				{
					_parentControl.PlotData.ZoomRange = _parentControl.PlotData.ExtentRange.ExtendsFromCenter(0.5);
				}
				else
				{
					_parentControl.PlotData.ZoomRange = zoomRange.ExtendsFromCenter(0.5);
				}
			}

			public void ZoomOutXAxis()
			{
				SpecPlotValueRange zoomRange = _parentControl.PlotData.ZoomRange;
				if (zoomRange == null || !zoomRange.IsValid)
				{
					_parentControl.PlotData.ZoomRange = _parentControl.PlotData.ExtentRange;
				}
				else
				{
					_parentControl.PlotData.ZoomRange = _parentControl.PlotData.ZoomRange.ExtendsFromCenter(2.0);
				}
			}

			public void ZoomToFullXAxis()
			{
				_parentControl.PlotData.ZoomRange = _parentControl.PlotData.ExtentRange;
			}

			public void ZoomXAxisTo(double min, double max)
			{
				SpecPlotValueRange specPlotValueRange = new SpecPlotValueRange(min, max);
				if (specPlotValueRange.IsValid)
				{
					_parentControl.PlotData.ZoomRange = specPlotValueRange;
				}
			}

			public void ZoomInYAxis()
			{
				SpecPlotValueRange relativeZoomRangeOnYAxis = _parentControl._uiHelper.GetRelativeZoomRangeOnYAxis();
				if (relativeZoomRangeOnYAxis != null && relativeZoomRangeOnYAxis.IsValid)
				{
					SpecPlotValueRange relativeRange = SpecPlotValueRange.FixRange(new SpecPlotValueRange(0.0, 1.0), relativeZoomRangeOnYAxis.ExtendsFromCenter(0.5));
					_parentControl._uiHelper.UpdateRelativeZoomRangeOnYAxis(relativeRange);
				}
			}

			public void ZoomOutYAxis()
			{
				SpecPlotValueRange relativeZoomRangeOnYAxis = _parentControl._uiHelper.GetRelativeZoomRangeOnYAxis();
				if (relativeZoomRangeOnYAxis != null && relativeZoomRangeOnYAxis.IsValid)
				{
					SpecPlotValueRange relativeRange = SpecPlotValueRange.FixRange(new SpecPlotValueRange(0.0, 1.0), relativeZoomRangeOnYAxis.ExtendsFromCenter(2.0));
					_parentControl._uiHelper.UpdateRelativeZoomRangeOnYAxis(relativeRange);
				}
			}

			public void ZoomToFullYAxis()
			{
				_parentControl._uiHelper.UpdateRelativeZoomRangeOnYAxis(new SpecPlotValueRange(0.0, 1.0));
			}

			public void ZoomYAxisTo(double min, double max)
			{
				if (!(min >= max) && !_parentControl.PlotAttributes.ShowMultipleYAxes)
				{
					_parentControl._uiHelper.UpdateAbsoluteZoomRangeOnYAxis(min, max);
				}
			}

			private void OnXAxisZoomFactorChanged(double oldFactor, double newFactor)
			{
				SpecPlotValueRange extentRange = _parentControl.PlotData.ExtentRange;
				if (!extentRange.IsValid)
				{
					return;
				}
				SpecPlotValueRange zoomRange = _parentControl.PlotData.ZoomRange;
				if (zoomRange == null || !zoomRange.IsValid)
				{
					_parentControl.PlotData.ZoomRange = extentRange.ExtendsFromCenter(newFactor);
					return;
				}
				double num = extentRange.Length * newFactor;
				if (zoomRange.Length != num)
				{
					_parentControl.PlotData.ZoomRange = zoomRange.ExtendsFromCenter(num / zoomRange.Length);
				}
			}

			private void OnYAxisZoomFactorChanged(double oldFactor, double newFactor)
			{
				SpecPlotValueRange relativeZoomRangeOnYAxis = _parentControl._uiHelper.GetRelativeZoomRangeOnYAxis();
				if (relativeZoomRangeOnYAxis != null && relativeZoomRangeOnYAxis.IsValid)
				{
					if (relativeZoomRangeOnYAxis.Length != newFactor)
					{
						SpecPlotValueRange relativeRange = SpecPlotValueRange.FixRange(new SpecPlotValueRange(0.0, 1.0), relativeZoomRangeOnYAxis.ExtendsFromCenter(newFactor / relativeZoomRangeOnYAxis.Length));
						_parentControl._uiHelper.UpdateRelativeZoomRangeOnYAxis(relativeRange);
					}
				}
				else
				{
					_parentControl._uiHelper.UpdateRelativeZoomRangeOnYAxis(new SpecPlotValueRange(0.0, 1.0).ExtendsFromCenter(newFactor));
				}
			}

			private double FixZoomFactor(double factor)
			{
				if (factor > 1.0)
				{
					return 1.0;
				}
				if (factor < MinimumZoomFactor)
				{
					return MinimumZoomFactor;
				}
				return factor;
			}
		}

		private class SpecPlotPrinter : IShellPrintSupport
		{
			private readonly SpecPlotControl _parentControl;

			private bool IsInPlotMode => _parentControl.DisplayMode == SpecPlotDisplayMode.Plot;

			private GridControl VisibleGridControl
			{
				get
				{
					if (_parentControl.DisplayMode == SpecPlotDisplayMode.Table)
					{
						return _parentControl.InternalGridControl;
					}
					if (_parentControl.DisplayMode == SpecPlotDisplayMode.FacePlate)
					{
						return _parentControl.InternalFacePlateControl;
					}
					return null;
				}
			}

			public bool CanPrintPreview => true;

			public bool CanPrint => true;

			public SpecPlotPrinter(SpecPlotControl parentControl)
			{
				_parentControl = parentControl;
			}

			public IEnumerable<FrameworkElement> GeneratePrintPages(System.Windows.Size availablePrintSize)
			{
				if (IsInPlotMode)
				{
					if (!(Infragistics.Windows.Utilities.GetDescendantFromType(_parentControl, typeof(GraphLayoutVisual), allowSubclassOfType: false) is GraphLayoutVisual graphLayoutVisual))
					{
						_parentControl.InternalPlotCtrl.CopyPlot();
						BitmapSource image = Clipboard.GetImage();
						return new List<FrameworkElement>
						{
							new Border
							{
								Child = new System.Windows.Controls.Image
								{
									Source = image,
									Width = availablePrintSize.Width - 80.0,
									Height = availablePrintSize.Height,
									VerticalAlignment = VerticalAlignment.Top
								}
							}
						};
					}
					RenderTargetBitmap renderTargetBitmap = new RenderTargetBitmap((int)graphLayoutVisual.Width, (int)graphLayoutVisual.Height, 96.0, 96.0, PixelFormats.Pbgra32);
					renderTargetBitmap.Render(graphLayoutVisual);
					return new List<FrameworkElement>
					{
						new Border
						{
							Child = new System.Windows.Controls.Image
							{
								Source = renderTargetBitmap,
								Width = availablePrintSize.Width,
								Height = availablePrintSize.Height,
								VerticalAlignment = VerticalAlignment.Top
							}
						}
					};
				}
				return VisibleGridControl?.GenerateGenericPrintPages(availablePrintSize, 0, 0, _parentControl.PlotData.PlotTitle);
			}

			public bool DoCustomPrintPreview()
			{
				return false;
			}

			public bool DoCustomPrint()
			{
				if (IsInPlotMode)
				{
					if (!(Infragistics.Windows.Utilities.GetDescendantFromType(_parentControl, typeof(GraphLayoutVisual), allowSubclassOfType: false) is Visual visual))
					{
						return false;
					}
					PrintDialog printDialog = new PrintDialog();
					if (printDialog.ShowDialog() == true)
					{
						printDialog.PrintVisual(visual, string.Empty);
					}
					return true;
				}
				return false;
			}

			public bool DoCustomPrintSetup()
			{
				return false;
			}
		}

		private class SpecPlotControlUIHelper
		{
			private readonly SpecPlotColorGenerator _colorGenerator = new SpecPlotColorGenerator();

			private readonly Dictionary<SpecPlotDataSeries, List<int>> _loadedPointsInRegularPlot = new Dictionary<SpecPlotDataSeries, List<int>>();

			private readonly SpecPlotControl _parentCtrl;

			private readonly PlotCtrl _plotCtrl;

			private readonly GridControl _gridCtrl;

			private readonly GridControl _facePlateCtrl;

			private readonly StackPanel _buttonsPanel;

			private Border _containerBorder;

			private Grid _overlapGrid;

			private bool _invalidatePlotFlag;

			private PlotTitleEditHelper _titleEditHelper;

			private TextBlock _emptyTextBlock;

			private bool _invalidateGraphZoomedFlag;

			private readonly List<Action> ActionsOnPlotRefreshed = new List<Action>();

			public bool IsValid
			{
				get
				{
					if (_parentCtrl != null)
					{
						return _containerBorder != null;
					}
					return false;
				}
			}

			public PlotCtrl InternalPlotCtrl => _plotCtrl;

			public GridControl InternalGridControl => _gridCtrl;

			public GridControl InternalFacePlateCtrl => _facePlateCtrl;

			public StackPanel ButtonsPanel => _buttonsPanel;

			private PlotTitleEditHelper TitleEditHelper => _titleEditHelper ?? (_titleEditHelper = new PlotTitleEditHelper(_parentCtrl, _plotCtrl, _overlapGrid));

			public SpecPlotControlUIHelper(SpecPlotControl parentCtrl)
			{
				_parentCtrl = parentCtrl;
				_plotCtrl = new PlotCtrl();
				_gridCtrl = new GridControl();
				_facePlateCtrl = new GridControl();
				_buttonsPanel = new StackPanel
				{
					Orientation = Orientation.Horizontal,
					VerticalAlignment = VerticalAlignment.Top,
					HorizontalAlignment = HorizontalAlignment.Right,
					Background = System.Windows.Media.Brushes.White,
					Margin = new Thickness(0.0, 3.0, 26.0, 0.0)
				};
			}

			public void Initialize(Grid overlapGrid, Border containerBorder)
			{
				_overlapGrid = overlapGrid;
				_containerBorder = containerBorder;
				UpdateBorderContent();
				UpdateOverlapGridContent();
				if (IsValid)
				{
					InitializePlotControl(_plotCtrl);
					RefreshPlotUI();
					RefreshPlotData();
					_parentCtrl.PlotAttributes.ApplyAttributes();
					InitializeGridControl(_gridCtrl);
					RefreshGridUI();
					RefreshGridData();
					InitializeFacePlateControl(_facePlateCtrl);
					RefreshFacePlateUI();
					RefreshFacePlateData();
				}
				if (containerBorder != null)
				{
					containerBorder.SizeChanged += containerBorder_SizeChanged;
				}
				_plotCtrl.SizeChanged += _plotCtrl_SizeChanged;
				_gridCtrl.SizeChanged += _gridCtrl_SizeChanged;
				_facePlateCtrl.SizeChanged += _facePlateCtrl_SizeChanged;
				_buttonsPanel.SizeChanged += _buttonsPanel_SizeChanged;
				_gridCtrl.ColumnActualWidthChanged += _gridCtrl_ColumnActualWidthChanged;
				_facePlateCtrl.ColumnActualWidthChanged += _facePlateCtrl_ColumnActualWidthChanged;
			}

			private void containerBorder_SizeChanged(object sender, SizeChangedEventArgs e)
			{
				PositionElements();
				RepositionLegend(e.PreviousSize, e.NewSize);
			}

			private void _plotCtrl_SizeChanged(object sender, SizeChangedEventArgs e)
			{
				if (_parentCtrl.DisplayMode == SpecPlotDisplayMode.Plot)
				{
					PositionElements();
				}
			}

			private void _gridCtrl_SizeChanged(object sender, SizeChangedEventArgs e)
			{
				if (_parentCtrl.DisplayMode == SpecPlotDisplayMode.Table)
				{
					PositionElements();
				}
			}

			private void _facePlateCtrl_SizeChanged(object sender, SizeChangedEventArgs e)
			{
				if (_parentCtrl.DisplayMode == SpecPlotDisplayMode.FacePlate)
				{
					PositionElements();
				}
			}

			private void _buttonsPanel_SizeChanged(object sender, SizeChangedEventArgs e)
			{
				PositionElements();
			}

			private void _gridCtrl_ColumnActualWidthChanged(object sender, DataColumnEventArgs e)
			{
				PositionElements();
			}

			private void _facePlateCtrl_ColumnActualWidthChanged(object sender, DataColumnEventArgs e)
			{
				PositionElements();
			}

			public void PositionElements()
			{
				if (_parentCtrl.DisplayMode == SpecPlotDisplayMode.Plot)
				{
					return;
				}
				if (_parentCtrl.DisplayMode == SpecPlotDisplayMode.Table)
				{
					if (_buttonsPanel.Visibility == Visibility.Visible && GetNeededWidth(_gridCtrl) + _buttonsPanel.ActualWidth > _containerBorder.ActualWidth)
					{
						_gridCtrl.Margin = new Thickness(0.0, _buttonsPanel.ActualHeight + 3.0, 0.0, 0.0);
					}
					else
					{
						_gridCtrl.Margin = default(Thickness);
					}
				}
				else if (_parentCtrl.DisplayMode == SpecPlotDisplayMode.FacePlate)
				{
					if (_buttonsPanel.Visibility == Visibility.Visible && GetNeededWidth(_facePlateCtrl) + _buttonsPanel.ActualWidth > _containerBorder.ActualWidth)
					{
						_facePlateCtrl.Margin = new Thickness(0.0, _buttonsPanel.ActualHeight + 3.0, 0.0, 0.0);
					}
					else
					{
						_facePlateCtrl.Margin = default(Thickness);
					}
				}
			}

			private static double GetNeededWidth(GridControl gc)
			{
				double num = 50.0;
				if (gc == null || gc.DataSource == null || gc.DataSource.Columns == null)
				{
					return num;
				}
				foreach (DataColumn column in gc.DataSource.Columns)
				{
					num += column.RenderedWidth;
				}
				return num;
			}

			public void UpdateLegendPosition()
			{
				if (!IsValid)
				{
					return;
				}
				IGraphLayout graphLayout = _plotCtrl.Plot.Frames[0].GraphLayout;
				SpecPlotLegendPosition legendPosition = _parentCtrl.PlotAttributes.LegendPosition;
				if (legendPosition == SpecPlotLegendPosition.Floating)
				{
					graphLayout.LegendPosition = GraphElementPosition.Right | GraphElementPosition.Top;
					_parentCtrl.InvalidatePlotProperties();
					_parentCtrl.Dispatcher.BeginInvoke((Action)delegate
					{
						graphLayout.LegendPosition = GraphElementPosition.Floating;
						if (_parentCtrl.PlotAttributes.ShowButtonsPanel && graphLayout.FloatingLegendPosition.Y < _buttonsPanel.ActualHeight)
						{
							graphLayout.FloatingLegendPosition = new System.Windows.Point(graphLayout.FloatingLegendPosition.X, _buttonsPanel.ActualHeight);
						}
						_parentCtrl.InvalidatePlotProperties();
					}, DispatcherPriority.DataBind);
				}
				else
				{
					graphLayout.LegendPosition = (GraphElementPosition)Enum.Parse(typeof(GraphElementPosition), legendPosition.ToString());
					_parentCtrl.InvalidatePlotProperties();
				}
			}

			private void RepositionLegend(System.Windows.Size previousPlotSize, System.Windows.Size newPlotSize)
			{
				if (IsValid && !previousPlotSize.IsEmpty && !newPlotSize.IsEmpty && _parentCtrl.PlotAttributes.LegendPosition == SpecPlotLegendPosition.Floating)
				{
					_plotCtrl.Plot.Frames[0].GraphLayout.FloatingLegendPosition += new Vector(newPlotSize.Width - previousPlotSize.Width, 0.0);
					_parentCtrl.InvalidatePlotProperties();
				}
			}

			public void InvalidateLegend()
			{
				if (IsValid)
				{
					IGraphLayout graphLayout = _plotCtrl.Plot.Frames[0].GraphLayout;
					SpecPlotLegendPosition legendPosition = _parentCtrl.PlotAttributes.LegendPosition;
					GraphElementPosition gllp = (GraphElementPosition)Enum.Parse(typeof(GraphElementPosition), legendPosition.ToString());
					System.Windows.Point position = graphLayout.FloatingLegendPosition;
					graphLayout.LegendPosition = GraphElementPosition.None;
					_parentCtrl.Dispatcher.BeginInvoke((Action)delegate
					{
						graphLayout.LegendPosition = gllp;
						graphLayout.FloatingLegendPosition = position;
						_parentCtrl.InvalidatePlotProperties();
					}, DispatcherPriority.DataBind);
					_parentCtrl.InvalidatePlotProperties();
				}
			}

			public void UpdateBorderContent()
			{
				if (_containerBorder != null)
				{
					if (_parentCtrl.DisplayMode == SpecPlotDisplayMode.Table)
					{
						_containerBorder.Child = _gridCtrl;
					}
					else if (_parentCtrl.DisplayMode == SpecPlotDisplayMode.FacePlate)
					{
						_containerBorder.Child = _facePlateCtrl;
					}
					else
					{
						_containerBorder.Child = _plotCtrl;
					}
					PositionElements();
				}
			}

			private void UpdateOverlapGridContent()
			{
				if (_overlapGrid != null)
				{
					RadioButtonTool radioButtonTool = new RadioButtonTool
					{
						Content = AspenTech.AspenPlus.MMControls.Properties.Resources.SpecPlotControl_ToggleButton_Plot,
						MinWidth = 40.0,
						HorizontalContentAlignment = HorizontalAlignment.Center
					};
					radioButtonTool.SetBinding(ToggleButton.IsCheckedProperty, new Binding
					{
						Source = _parentCtrl,
						Path = new PropertyPath(DisplayModeProperty),
						Converter = new DisplayModeToCheckStatusConverter
						{
							CheckedMode = SpecPlotDisplayMode.Plot
						}
					});
					RadioButtonTool radioButtonTool2 = new RadioButtonTool
					{
						Content = AspenTech.AspenPlus.MMControls.Properties.Resources.SpecPlotControl_ToggleButton_Table,
						MinWidth = 40.0,
						HorizontalContentAlignment = HorizontalAlignment.Center
					};
					radioButtonTool2.SetBinding(ToggleButton.IsCheckedProperty, new Binding
					{
						Source = _parentCtrl,
						Path = new PropertyPath(DisplayModeProperty),
						Converter = new DisplayModeToCheckStatusConverter
						{
							CheckedMode = SpecPlotDisplayMode.Table
						}
					});
					RadioButtonTool radioButtonTool3 = new RadioButtonTool
					{
						Content = AspenTech.AspenPlus.MMControls.Properties.Resources.SpecPlotControl_ToggleButton_FacePlate,
						MinWidth = 40.0,
						HorizontalContentAlignment = HorizontalAlignment.Center
					};
					radioButtonTool3.SetBinding(ToggleButton.IsCheckedProperty, new Binding
					{
						Source = _parentCtrl,
						Path = new PropertyPath(DisplayModeProperty),
						Converter = new DisplayModeToCheckStatusConverter
						{
							CheckedMode = SpecPlotDisplayMode.FacePlate
						}
					});
					radioButtonTool3.SetBinding(UIElement.VisibilityProperty, new Binding
					{
						Source = _parentCtrl.PlotAttributes,
						Path = new PropertyPath(SpecPlotAttributes.ShowFacePlateButtonProperty),
						Converter = new BooleanToVisibilityConverter(),
						Mode = BindingMode.OneWay
					});
					_buttonsPanel.Children.Add(radioButtonTool);
					_buttonsPanel.Children.Add(radioButtonTool2);
					_buttonsPanel.Children.Add(radioButtonTool3);
					_buttonsPanel.SetBinding(UIElement.VisibilityProperty, new Binding
					{
