						Path = new PropertyPath(SpecPlotAttributes.ShowButtonsPanelProperty),
						Converter = new BooleanToVisibilityConverter(),
						Mode = BindingMode.OneWay
					});
					_overlapGrid.Children.Add(_buttonsPanel);
					_emptyTextBlock = new TextBlock
					{
