			public System.Windows.Point MapGraphPositionToDataPoint(System.Windows.Point position, SpecPlotDataSeries dataSeries)
			{
				if (dataSeries == null)
				{
					throw new ArgumentNullException("dataSeries");
				}
				if (!IsValid)
				{
					throw new InvalidOperationException("The plot hasn't been initialized ready.");
				}
				IGraph graph = _plotCtrl.Plot.Frames[0].GraphLayout.Graph;
				IDataSeries dataSeries2 = graph.DataSeriesCollection.FirstOrDefault((IDataSeries dataSeries3) => dataSeries3.Tag == dataSeries);
				if (dataSeries2 == null)
				{
					throw new ArgumentException("The given dataSeries hasn't been added into the plot.");
				}
				AxesVisual axesVisual = graph.Axes.Renderer.Visual as AxesVisual;
				System.Windows.Point point = axesVisual.PlotAreaToHost(position);
				double val = point.X / axesVisual.PlotArea.Width;
				val = Math.Max(0.0, Math.Min(1.0, val));
				IGraphAxis axis = graph.Axes.GetAxis(PlotAxisID.X);
				bool valid = false;
				object obj = axis.AxisAnnotator.AxisFractionUnmapValue(axis, val, out valid);
				double x = (valid ? ((double)obj) : double.NaN);
				double val2 = point.Y / axesVisual.PlotArea.Height;
				val2 = 1.0 - Math.Max(0.0, Math.Min(1.0, val2));
				IGraphAxis axis2 = graph.Axes.GetAxis(PlotAxisID.Y);
				if (axis2 is IMultiGraphAxis)
				{
					axis2 = ((IMultiGraphAxis)axis2).GetAxis(dataSeries2);
				}
				bool valid2 = false;
				object obj2 = axis2.AxisAnnotator.AxisFractionUnmapValue(axis2, val2, out valid2);
				double y = (valid2 ? ((double)obj2) : double.NaN);
				return new System.Windows.Point(x, y);
			}

