			private void graph_ChildYAxisGenerated(object sender, ChildYAxisEventArgs e)
			{
				if (!IsValid)
				{
					return;
				}
				IGraph graph = _plotCtrl.Plot.Frames[0].GraphLayout.Graph;
				if (graph.Axes.GetAxis(PlotAxisID.Y) is IMultiGraphAxis multiGraphAxis)
				{
					SpecPlotAttributes plotAttributes = _parentCtrl.PlotAttributes;
					IGraphAxis axis = multiGraphAxis.GetAxis(graph.DataSeriesCollection.First((IDataSeries x) => x.Tag == _parentCtrl.PlotData.DataSeriesCollection.Last()));
					UpdateAxisElementVisibilities(e.ChildYAxis, plotAttributes.ShowYAxisGridLines && e.ChildYAxis == axis, plotAttributes.ShowYAxisTicks, plotAttributes.ShowYAxisLabels);
					ApplyChildAxisFormat(graph, multiGraphAxis, e.ChildYAxis);
				}
			}

			private void ApplyChildAxisFormat(IGraph graph, IMultiGraphAxis yAxis, IGraphAxis childAxis)
			{
				IDataSeries dataSeries = graph.DataSeriesCollection.FirstOrDefault((IDataSeries x) => yAxis.GetAxis(x) == childAxis);
				if (dataSeries != null && dataSeries.Tag is SpecPlotDataSeries specPlotDataSeries)
				{
					childAxis.AxisAnnotator = SpecPlotAttributes.CreateNewAxisAnnotator(specPlotDataSeries.AxisType);
					childAxis.DataLabelFormatString = null;
					if (!specPlotDataSeries.AutoAdjustRange && specPlotDataSeries.YAxisRange != null && specPlotDataSeries.YAxisRange.IsValid)
					{
						SetYAxisDataRange(childAxis, specPlotDataSeries.YAxisRange.Left, specPlotDataSeries.YAxisRange.Right);
					}
					else
					{
						childAxis.Scaling = PlotAxisScaling.AutoMargin;
					}
				}
			}

			private void ApplyGeneralAxisFormat(IGraph graph, IGraphAxis yAxis)
			{
				if (graph.AxesStyle != PlotAxesStyle.RectXY || _parentCtrl.PlotData.DataSeriesCollection.Count <= 0)
				{
					return;
				}
				IList<SpecPlotDataSeries> list = null;
				list = (_parentCtrl.PlotAttributes.ShowMultipleYAxes ? ((IList<SpecPlotDataSeries>)graph.DataSeriesCollection.Select((IDataSeries x) => x.Tag as SpecPlotDataSeries).ToList()) : ((IList<SpecPlotDataSeries>)_parentCtrl.PlotData.DataSeriesCollection));
				int num = list.Count((SpecPlotDataSeries x) => x.AutoAdjustRange);
				int num2 = list.Count((SpecPlotDataSeries x) => x.YAxisRange != null);
				IEnumerable<IGrouping<SpecPlotAxisType, SpecPlotDataSeries>> source = from x in list
					group x by x.AxisType;
				if (source.Count() == 1)
				{
					yAxis.AxisAnnotator = SpecPlotAttributes.CreateNewAxisAnnotator(source.First().Key);
				}
				else
				{
					yAxis.AxisAnnotator = SpecPlotAttributes.CreateNewAxisAnnotator(SpecPlotAxisType.Linear);
				}
				if (num == 0 && num2 == list.Count)
				{
					double min = list.Min((SpecPlotDataSeries x) => x.YAxisRange.Left);
					double max = list.Max((SpecPlotDataSeries x) => x.YAxisRange.Right);
					SetYAxisDataRange(yAxis, min, max);
				}
				else
				{
					yAxis.Scaling = PlotAxisScaling.AutoMargin;
				}
			}

			private void SetYAxisDataRange(IGraphAxis yAxis, double min, double max)
			{
				if (yAxis.AxisAnnotator != null && string.Equals(yAxis.AxisAnnotator.AnnotatorType, "Probability", StringComparison.InvariantCultureIgnoreCase))
				{
					if (min < 0.0 || min >= 1.0)
					{
						min = 0.0;
					}
					if (max < 0.0 || max >= 1.0)
					{
						max = 0.9999999;
					}
				}
				else
				{
					max += (max - min) * 0.02;
				}
				yAxis.Scaling = PlotAxisScaling.None;
				yAxis.DataRange.SetAbsolute(min, max, validate: true);
			}

