			public void UpdateYAxis()
			{
				if (!IsValid)
				{
					return;
				}
				SpecPlotAttributes attr = _parentCtrl.PlotAttributes;
				IGraph graph = _plotCtrl.Plot.Frames[0].GraphLayout.Graph;
				graph.GraphLayout.AutoElementVisibility = false;
				if (_parentCtrl.PlotAttributes.ShowMultipleYAxes)
				{
					graph.AxesStyle = PlotAxesStyle.RectXMultiY;
					IMultiGraphAxis multiYAxis = graph.Axes.GetAxis(PlotAxisID.Y) as IMultiGraphAxis;
					multiYAxis.ChildAxisLayout = ChildAxisLayout.TitledSideBySide;
					ActionsOnPlotRefreshed.Add(delegate
					{
						IDataSeries dataSeries = graph.DataSeriesCollection.FirstOrDefault((IDataSeries x) => x.Tag == _parentCtrl.PlotData.DataSeriesCollection.LastOrDefault());
						foreach (IDataSeries item in graph.DataSeriesCollection)
						{
							IGraphAxis axis3 = multiYAxis.GetAxis(item);
							if (axis3 == null)
							{
								multiYAxis.Stretch(double.NaN, item);
								axis3 = multiYAxis.GetAxis(item);
							}
							if (axis3 != null)
							{
								UpdateAxisElementVisibilities(axis3, attr.ShowYAxisGridLines && dataSeries == item, attr.ShowYAxisTicks, attr.ShowYAxisLabels);
							}
						}
						_plotCtrl.Refresh();
					});
				}
				else
				{
					graph.AxesStyle = PlotAxesStyle.RectXY;
				}
				IGraphAxis axis = graph.Axes.GetAxis(PlotAxisID.X);
				UpdateAxisElementVisibilities(axis, attr.ShowXAxisGridLines, attr.ShowXAxisTicks, attr.ShowXAxisLabels);
				UpdateXAxis();
				IGraphAxis axis2 = graph.Axes.GetAxis(PlotAxisID.Y);
				axis2.Scaling = PlotAxisScaling.AutoMargin;
				axis2.DataType = PlotAxisDataType.Number;
				ApplyGeneralAxisFormat(graph, axis2);
				bool flag = !_parentCtrl.PlotAttributes.ShowMultipleYAxes;
				UpdateAxisElementVisibilities(axis2, attr.ShowYAxisGridLines && flag, attr.ShowYAxisTicks && flag, attr.ShowYAxisLabels && flag);
				UpdateTitles();
				UpdateDataRangeX();
				UpdateDataRangeY();
				UpdateZoomRange();
				InvalidateInternalPlotControl();
			}

			private void UpdateAxisElementVisibilities(IGraphAxis axis, bool showGridLines, bool showTicks, bool showLabels)
			{
				axis.SetVisualElementVisibility(PlotAxisVisualElements.MajorGridLines, showGridLines);
				axis.SetVisualElementVisibility(PlotAxisVisualElements.MinorGridLines, showGridLines);
				axis.SetVisualElementVisibility(PlotAxisVisualElements.MajorTicks, showTicks);
				axis.SetVisualElementVisibility(PlotAxisVisualElements.MinorTicks, showTicks);
				axis.SetVisualElementVisibility(PlotAxisVisualElements.Labels, showLabels);
			}

