			public void UpdateZoomRange()
			{
				if (!IsValid || _plotCtrl.Plot.Frames.Count <= 0)
				{
					return;
				}
				SpecPlotValueRange zoomRange = _parentCtrl.PlotData.ZoomRange;
				if (zoomRange == null || !zoomRange.IsValid)
				{
					return;
				}
				SpecPlotValueRange extentRange = _parentCtrl.PlotData.ExtentRange;
				if (extentRange != null && extentRange.IsValid)
				{
					SpecPlotValueRange specPlotValueRange = SpecPlotValueRange.FixRange(extentRange, zoomRange);
					double value = extentRange.PointToFraction(specPlotValueRange.Left);
					double value2 = extentRange.PointToFraction(specPlotValueRange.Right);
					IGraphAxis axis = _plotCtrl.Plot.Frames[0].GraphLayout.Graph.Axes.GetAxis(PlotAxisID.X);
					axis.ZoomReset();
					axis.ZoomRange = new ValueRange
					{
						Minimum = new RRangeValue
						{
							Value = value
						},
						Maximum = new RRangeValue
						{
							Value = value2
						}
					};
					if (!_parentCtrl.SuppressDataVirtualization)
					{
						EnsurePointsLoadedInRegularMode(specPlotValueRange);
					}
					_parentCtrl.OnZoomRangeChanged();
					InvalidateInternalPlotControl();
				}
			}

