			public void UpdateAbsoluteZoomRangeOnYAxis(double min, double max)
			{
				if (!(min >= max) && IsValid)
				{
					IGraphAxis axis = _plotCtrl.Plot.Frames[0].GraphLayout.Graph.Axes.GetAxis(PlotAxisID.Y);
					if (!(axis is IMultiGraphAxis))
					{
						double value = axis.DataRange.Maximum.Value;
						SpecPlotValueRange specPlotValueRange = SpecPlotValueRange.FixRange(new SpecPlotValueRange(axis.DataRange.Minimum.Value, value), new SpecPlotValueRange(min, max));
						double left = axis.DataRange.ValueToFraction(specPlotValueRange.Left);
						double right = axis.DataRange.ValueToFraction(specPlotValueRange.Right);
						UpdateRelativeZoomRangeOnYAxis(new SpecPlotValueRange(left, right));
					}
				}
			}

			public void UpdateRelativeZoomRangeOnYAxis(SpecPlotValueRange relativeRange)
			{
				if (relativeRange != null && relativeRange.IsValid && IsValid)
				{
					IGraphAxis axis = _plotCtrl.Plot.Frames[0].GraphLayout.Graph.Axes.GetAxis(PlotAxisID.Y);
					SpecPlotValueRange specPlotValueRange = SpecPlotValueRange.FixRange(new SpecPlotValueRange(0.0, 1.0), relativeRange);
					IValueRange zoomRange = axis.ZoomRange;
					if (!IsRoughlyEqual(specPlotValueRange.Left, zoomRange.Minimum.Value) || !IsRoughlyEqual(specPlotValueRange.Right, zoomRange.Maximum.Value))
					{
						axis.ZoomRange.SetAbsolute(specPlotValueRange.Left, specPlotValueRange.Right, validate: true);
						InvalidateInternalPlotControl();
					}
				}
			}

			private void PlotCtrl_GraphZoom(object sender, PlotZoomEventArgs e)
			{
				if (!_invalidateGraphZoomedFlag)
				{
					_invalidateGraphZoomedFlag = true;
					_parentCtrl.Dispatcher.BeginInvoke((Action)delegate
					{
						OnPlotCtrlGraphZoomed();
						_invalidateGraphZoomedFlag = false;
					});
				}
			}

			private void OnPlotCtrlGraphZoomed()
			{
				SpecPlotData plotData = _parentCtrl.PlotData;
				SpecPlotValueRange extentRange = plotData.ExtentRange;
				if (extentRange != null && extentRange.IsValid)
				{
					IGraph graph = _plotCtrl.Plot.Frames[0].GraphLayout.Graph;
					IGraphAxis axis = graph.Axes.GetAxis(PlotAxisID.X);
					graph.Axes.GetAxis(PlotAxisID.Y);
					double left = extentRange.FractionToPoint(axis.ZoomRange.Minimum.Value);
					double right = extentRange.FractionToPoint(axis.ZoomRange.Maximum.Value);
					SpecPlotValueRange specPlotValueRange = new SpecPlotValueRange(left, right);
					if (!specPlotValueRange.Equals(plotData.ZoomRange))
					{
						plotData.ZoomRange = specPlotValueRange;
					}
					if (!_parentCtrl.SuppressDataVirtualization)
					{
						EnsurePointsLoadedInRegularMode(specPlotValueRange);
					}
					_parentCtrl.OnZoomRangeChanged();
				}
			}

			private static bool IsRoughlyEqual(double x, double y)
			{
				if (double.IsNaN(x))
				{
					return double.IsNaN(y);
				}
				if (double.IsNaN(y))
				{
					return false;
				}
				return Math.Abs(x - y) < 1E-06;
			}

