			private void RefreshPlotUIInRegularMode()
			{
				SpecPlotData plotData = _parentCtrl.PlotData;
				IGraph graph = _plotCtrl.Plot.Frames[0].GraphLayout.Graph;
				List<IDataSeries> list = new List<IDataSeries>();
				List<IDataSeries> list2 = new List<IDataSeries>();
				foreach (IDataSeries item2 in graph.DataSeriesCollection)
				{
					if (item2.Tag is SpecPlotDataSeries item && plotData.DataSeriesCollection.Contains(item))
					{
						list.Add(item2);
					}
					else
					{
						list2.Add(item2);
					}
				}
				foreach (IDataSeries item3 in list2)
				{
					graph.DeleteDataSeries(item3);
				}
				foreach (SpecPlotDataSeries spto in plotData.DataSeriesCollection)
				{
					IDataSeries dataSeries = list.FirstOrDefault((IDataSeries x) => x.Tag == spto);
					if (dataSeries == null)
					{
						dataSeries = graph.NewDataSeries();
						dataSeries.Label = GetDataSeriesDisplayName(spto);
						dataSeries.ScooterValueFormat = spto.ScooterValueFormat;
						dataSeries.DataSource = new OrderedDataStore();
						dataSeries.Tag = spto;
						UpdateCurveFormat(dataSeries, spto.CurveFormat);
					}
					dataSeries.AxisGroup = spto.AxisGroup;
				}
			}

			private void UpdateCurveFormat(IDataSeries ds, SpecPlotCurveFormat format)
			{
				SpecPlotCurveFormat specPlotCurveFormat = format ?? new SpecPlotCurveFormat();
				ds.LineStyle = EnsureLineStyle(specPlotCurveFormat.LineStyle);
				ds.LineWidth = EnsureLineWidth(specPlotCurveFormat.LineWidth);
				ds.LineColour = EnsureLineColor(ds, specPlotCurveFormat.LineColor);
				ds.SymbolStyle = ConvertSymbolStyle(specPlotCurveFormat.SymbolStyle);
				ds.SymbolColour = specPlotCurveFormat.SymbolColor.GetValueOrDefault(ds.LineColour);
				ds.SymbolScale = specPlotCurveFormat.SymbolScale;
			}

