					if (dataSeries != null)
					{
						dataSeries.Label = GetDataSeriesDisplayName(spds);
						_plotCtrl.Refresh();
						InvalidateInternalPlotControl();
						Plot_PerformPropertiesChanged();
					}
				}
			}

