			private void RefreshPlotDataInRegularMode()
			{
				SpecPlotData plotData = _parentCtrl.PlotData;
				IGraph graph = _plotCtrl.Plot.Frames[0].GraphLayout.Graph;
				graph.Axes.GetAxis(PlotAxisID.X);
				foreach (IDataSeries item in graph.DataSeriesCollection)
				{
					if (item.DataSource is IPlotDataStore plotDataStore)
					{
						plotDataStore.Clear();
					}
				}
				EnsurePointsLoadedInRegularMode(plotData.ZoomRange);
				UpdateDataRangeX();
			}

			private void EnsurePointsLoadedInRegularMode(SpecPlotValueRange range)
			{
				if (!IsValid)
				{
					return;
				}
				SpecPlotData plotData = _parentCtrl.PlotData;
				IGraph graph = _plotCtrl.Plot.Frames[0].GraphLayout.Graph;
				if (range == null || !range.IsValid)
				{
					range = plotData.ExtentRange;
				}
				bool flag = false;
				SpecPlotLocationRange specPlotLocationRange = null;
				specPlotLocationRange = (_parentCtrl.SuppressDataVirtualization ? new SpecPlotLocationRange(0, plotData.RecordsCount) : GetLocationRange(plotData, range));
				for (int i = specPlotLocationRange.Start; i <= specPlotLocationRange.End; i++)
				{
					double xAxisValue = plotData.GetXAxisValue(i);
					foreach (IDataSeries item in graph.DataSeriesCollection)
					{
						SpecPlotDataSeries series = item.Tag as SpecPlotDataSeries;
						if (!HasPointLoaded(series, i))
						{
							MarkPointLoaded(series, i);
							double? pointValue = plotData.GetPointValue(series, i);
							if (pointValue.HasValue)
							{
								(item.DataSource as IPlotDataStore).AddPoint(xAxisValue, pointValue.Value);
								flag = true;
							}
						}
					}
				}
				if (flag)
				{
					UpdateDataRangeY();
					InvalidateInternalPlotControl();
				}
			}

			private bool HasPointLoaded(SpecPlotDataSeries series, int location)
			{
				if (!_loadedPointsInRegularPlot.ContainsKey(series))
				{
					return false;
				}
				return _loadedPointsInRegularPlot[series].Contains(location);
			}

			private void MarkPointLoaded(SpecPlotDataSeries series, int location)
			{
				List<int> value = null;
				if (!_loadedPointsInRegularPlot.TryGetValue(series, out value))
				{
					value = new List<int>();
					_loadedPointsInRegularPlot[series] = value;
				}
				value.Add(location);
			}

			public void ClearLoadedPoints(SpecPlotDataSeries series = null, SpecPlotLocationRange range = null)
			{
				if (range == null)
				{
					if (series == null)
					{
						_loadedPointsInRegularPlot.Clear();
					}
					else if (_loadedPointsInRegularPlot.ContainsKey(series))
					{
						_loadedPointsInRegularPlot.Remove(series);
					}
					return;
				}
				if (series == null)
				{
					foreach (List<int> value in _loadedPointsInRegularPlot.Values)
					{
						for (int i = range.Start; i <= range.End; i++)
						{
							if (value.Contains(i))
							{
								value.Remove(i);
							}
						}
					}
					return;
				}
				if (!_loadedPointsInRegularPlot.ContainsKey(series))
				{
					return;
				}
				List<int> list = _loadedPointsInRegularPlot[series];
				for (int j = range.Start; j <= range.End; j++)
				{
					if (list.Contains(j))
					{
						list.Remove(j);
					}
				}
			}

			private SpecPlotLocationRange GetLocationRange(SpecPlotData pd, SpecPlotValueRange range)
			{
				if (pd.RecordsCount <= 2)
				{
					return new SpecPlotLocationRange(0, pd.RecordsCount);
				}
				int num = 0;
				int num2 = pd.RecordsCount - 1;
				int? num3 = null;
				int? num4 = null;
				double num5 = range.Left;
				double num6 = range.Right;
				while (num <= num2)
				{
					int num7 = (num + num2) / 2;
					double xAxisValue = pd.GetXAxisValue(num7);
					if (xAxisValue <= num6)
					{
						num4 = ((!num4.HasValue) ? new int?(num7) : new int?(Math.Max(num4.Value, num7)));
					}
					if (num5 == xAxisValue)
					{
						num3 = num7;
						break;
					}
					if (num5 < xAxisValue)
					{
						num2 = num7 - 1;
					}
					else
					{
						num = num7 + 1;
					}
				}
				if (!num3.HasValue)
				{
					num3 = Math.Max(0, num - 1);
				}
				if (!num4.HasValue)
				{
					num4 = num3;
				}
				int i;
				for (i = num4.Value; i < pd.RecordsCount && !(pd.GetXAxisValue(i) >= num6); i++)
				{
				}
				return new SpecPlotLocationRange(num3.Value, Math.Min(pd.RecordsCount, i - num3.Value + 1));
			}

			public void InvalidateInternalPlotControl()
			{
				if (_invalidatePlotFlag)
				{
					return;
				}
				_invalidatePlotFlag = true;
				_parentCtrl.Dispatcher.BeginInvoke((Action)delegate
				{
					try
					{
						_plotCtrl.Refresh();
						OnPlotCtrlRefreshed();
					}
					catch (Exception ex)
					{
						Trace.WriteLine(ex.Message);
						Trace.WriteLine(ex.StackTrace);
					}
					finally
					{
						_invalidatePlotFlag = false;
					}
				});
			}

			private void OnPlotCtrlRefreshed()
			{
				if (ActionsOnPlotRefreshed.Count > 0)
				{
					foreach (Action item in ActionsOnPlotRefreshed)
					{
						item?.Invoke();
					}
					ActionsOnPlotRefreshed.Clear();
				}
				_parentCtrl.OnPlotGraphRefreshed();
			}

			private AspenTech.Visualisation.Controls.Plot.LineStyle EnsureLineStyle(SpecPlotLineStyle style)
			{
				return style switch
				{
					SpecPlotLineStyle.Dash => AspenTech.Visualisation.Controls.Plot.LineStyle.Dash, 
					SpecPlotLineStyle.DashDot => AspenTech.Visualisation.Controls.Plot.LineStyle.DashDot, 
					SpecPlotLineStyle.DashDotDot => AspenTech.Visualisation.Controls.Plot.LineStyle.DashDotDot, 
					SpecPlotLineStyle.Dot => AspenTech.Visualisation.Controls.Plot.LineStyle.Dot, 
					SpecPlotLineStyle.Solid => AspenTech.Visualisation.Controls.Plot.LineStyle.Solid, 
					_ => AspenTech.Visualisation.Controls.Plot.LineStyle.Solid, 
				};
			}

			private System.Windows.Media.Color EnsureLineColor(IDataSeries ds, System.Windows.Media.Color? color)
			{
				if (color.HasValue)
				{
					return color.Value;
				}
				return FindNextColor(ds);
			}

			private double EnsureLineWidth(double? width)
			{
				if (width.HasValue)
				{
					return Math.Max(0.0, width.Value);
				}
				return 2.0;
			}

			private System.Windows.Media.Color FindNextColor(IDataSeries ds)
			{
				List<System.Windows.Media.Color> exclusion = (from x in _plotCtrl.Plot.Frames[0].GraphLayout.Graph.DataSeriesCollection.Except(new IDataSeries[1] { ds })
					select x.LineColour).ToList();
				return _colorGenerator.Next(exclusion);
			}

			private static SymbolStyle ConvertSymbolStyle(SpecPlotSymbolStyle spss)
			{
				return spss switch
				{
					SpecPlotSymbolStyle.Circle => SymbolStyle.Circle, 
					SpecPlotSymbolStyle.Cross => SymbolStyle.Cross, 
					SpecPlotSymbolStyle.Diamond => SymbolStyle.Diamond, 
					SpecPlotSymbolStyle.Dot => SymbolStyle.Dot, 
					SpecPlotSymbolStyle.Plus => SymbolStyle.Plus, 
					SpecPlotSymbolStyle.Square => SymbolStyle.Square, 
					SpecPlotSymbolStyle.TriangleUp => SymbolStyle.TriangleUp, 
					SpecPlotSymbolStyle.TriangleDown => SymbolStyle.TriangleDown, 
					SpecPlotSymbolStyle.FilledDiamond => SymbolStyle.Diamond | SymbolStyle.Filled, 
					SpecPlotSymbolStyle.FilledSquare => SymbolStyle.Square | SymbolStyle.Filled, 
					SpecPlotSymbolStyle.FilledTriangleUp => SymbolStyle.TriangleUp | SymbolStyle.Filled, 
					SpecPlotSymbolStyle.FilledTriangleDown => SymbolStyle.TriangleDown | SymbolStyle.Filled, 
					_ => SymbolStyle.None, 
				};
			}

			private void InitializeGridControl(GridControl gc)
			{
				gc.AllowRowReorder = false;
				gc.AllowRecordFiltering = false;
				gc.AllowColumnFreeze = false;
				gc.SortingMode = SortingMode.NotAllowed;
				gc.CellValueQueried += GridCtrl_CellValueQueried;
				gc.DefaultContextMenuOpening += GridCtrl_DefaultContextMenuOpening;
			}

			public void RefreshGridUI()
			{
				if (!IsValid)
				{
					return;
				}
				SpecPlotData plotData = _parentCtrl.PlotData;
				List<DataColumn> list = new List<DataColumn>();
				DataColumn dataColumn = new DataColumn
				{
					IsReadOnly = true,
					Width = 110.0
				};
				BindingOperations.SetBinding(dataColumn, DataColumn.HeaderProperty, new Binding
				{
					Source = plotData,
					Path = new PropertyPath(SpecPlotData.RecordIndexerColumnHeaderProperty),
					Mode = BindingMode.OneWay
				});
				list.Add(dataColumn);
				foreach (SpecPlotDataSeries item in _parentCtrl.PlotData.DataSeriesCollection)
				{
					DataColumn dataColumn2 = new DataColumn
					{
						IsReadOnly = true,
						Tag = item,
						Width = 120.0
					};
					BindingOperations.SetBinding(dataColumn2, DataColumn.HeaderProperty, new Binding
					{
						Source = item,
						Path = new PropertyPath(SpecPlotDataSeries.NameProperty),
						Mode = BindingMode.OneWay
					});
					list.Add(dataColumn2);
				}
				_gridCtrl.DataSource = new DataTable(list);
			}

			public void RefreshGridData()
			{
				if (IsValid)
				{
					_gridCtrl.DataSource?.UpdateRows(_parentCtrl.PlotData.RecordsCount, CreateDataRow);
				}
			}

			private DataRow CreateDataRow(int rowIndex)
			{
				return new DataRow(_gridCtrl.DataSource, _gridCtrl.DataSource.Columns)
				{
					Tag = rowIndex
				};
			}

			private void GridCtrl_CellValueQueried(object sender, CellValueQueriedEventArgs e)
			{
				int num = (int)e.Row.Tag;
				SpecPlotData plotData = _parentCtrl.PlotData;
				if (num >= plotData.RecordsCount)
				{
					return;
				}
				if (e.Column.Tag is SpecPlotDataSeries)
				{
					double? pointValue = plotData.GetPointValue(e.Column.Tag as SpecPlotDataSeries, num);
					e.Data = new DataCellDouble(pointValue);
					return;
				}
				bool flag = false;
				if (plotData.XAxisLables != null)
				{
					string text = plotData.XAxisLables.Skip(num).FirstOrDefault();
					if (text != null)
					{
						e.Data = CreateXAxisLabelCell(text);
						flag = true;
					}
				}
				if (!flag)
				{
					double xAxisValue = plotData.GetXAxisValue(num);
					e.Data = new DataCellDouble(xAxisValue);
				}
			}

			private void GridCtrl_DefaultContextMenuOpening(object sender, DefaultContextMenuEventArgs e)
			{
				InitializeDefaultContextMenu(e.DefaultContextMenu);
			}

			private static IDataCell CreateXAxisLabelCell(string label)
			{
				double result = 0.0;
				if (double.TryParse(label, out result))
				{
					return new DataCellDouble(result);
				}
				return new DataCellText(label);
			}

