			private DataRow CreateFacePlateRow(int index)
			{
				DataRow dataRow = new DataRow(_facePlateCtrl.DataSource, _facePlateCtrl.DataSource.Columns);
				if (index > 0)
				{
					dataRow.Tag = _parentCtrl.PlotData.DataSeriesCollection[index - 1];
				}
				return dataRow;
			}

			private void FacePlateCtrl_CellValueQueried(object sender, CellValueQueriedEventArgs e)
			{
				int num = (int)e.Column.Tag;
				SpecPlotDataSeries specPlotDataSeries = e.Row.Tag as SpecPlotDataSeries;
				switch (num)
				{
				case 0:
				{
					string value = ((specPlotDataSeries == null) ? _parentCtrl.PlotData.RecordIndexerColumnHeader : specPlotDataSeries.Name);
					e.Data = new DataCellText(value);
					break;
				}
				case 1:
				{
					SpecPlotData plotData = _parentCtrl.PlotData;
					if (plotData.RecordsCount <= 0)
					{
						break;
					}
					if (specPlotDataSeries == null)
					{
						if (plotData.XAxisLables != null)
						{
							string label = plotData.XAxisLables.LastOrDefault();
							e.Data = CreateXAxisLabelCell(label);
						}
						else
						{
							double xAxisValue = plotData.GetXAxisValue(plotData.RecordsCount - 1);
							e.Data = new DataCellDouble(xAxisValue);
						}
					}
					else
					{
						double? pointValue = plotData.GetPointValue(specPlotDataSeries, plotData.RecordsCount - 1);
						e.Data = new DataCellDouble(pointValue);
					}
					break;
				}
				}
			}

			private void FacePlateCtrl_DefaultContextMenuOpening(object sender, DefaultContextMenuEventArgs e)
			{
				InitializeDefaultContextMenu(e.DefaultContextMenu);
			}

			private void InitializeDefaultContextMenu(ContextMenu contextMenu)
			{
				string header = ((_parentCtrl.DisplayMode == SpecPlotDisplayMode.Plot) ? AspenTech.AspenPlus.MMControls.Properties.Resources.SpecPlotControl_ContextMenu_ShowPlotAsTable : AspenTech.AspenPlus.MMControls.Properties.Resources.SpecPlotControl_ContextMenu_ShowTableAsPlot);
				MenuItem menuItem = new MenuItem
				{
					Header = header
				};
				menuItem.Click += SwitichDisplayMode_MenuItem_Click;
				contextMenu.Items.Clear();
				contextMenu.Items.Add(menuItem);
				SpecPlotContextMenuEventArgs e = new SpecPlotContextMenuEventArgs(contextMenu);
				_parentCtrl.OnDefaultContextMenuOpening(e);
			}

			private void SwitichDisplayMode_MenuItem_Click(object sender, RoutedEventArgs e)
			{
				SpecPlotDisplayMode specPlotDisplayMode = ((_parentCtrl.DisplayMode == SpecPlotDisplayMode.Plot) ? SpecPlotDisplayMode.Table : SpecPlotDisplayMode.Plot);
				if (!_parentCtrl.TriggerDisplayModeChangingEvent(_parentCtrl.DisplayMode, specPlotDisplayMode))
				{
					_parentCtrl.DisplayMode = specPlotDisplayMode;
				}
			}
		}

		private class PlotTitleEditHelper
		{
			private readonly SpecPlotControl _parentControl;

			private readonly PlotCtrl _plotCtrl;

			private readonly Grid _overlapGrid;

			private TextBox _editTextBox;

			private TextBox EditTextBox
			{
				get
				{
					if (_editTextBox == null)
					{
						_editTextBox = new TextBox
						{
							Tag = "PlotTitleEditHelper",
							HorizontalAlignment = HorizontalAlignment.Left,
							VerticalAlignment = VerticalAlignment.Top
						};
						_editTextBox.LostKeyboardFocus += EditTextBox_LostKeyboardFocus;
						_overlapGrid.Children.Add(_editTextBox);
					}
					return _editTextBox;
				}
			}

			public PlotTitleEditHelper(SpecPlotControl parentControl, PlotCtrl plotCtrl, Grid overlapGrid)
			{
				_parentControl = parentControl;
				_plotCtrl = plotCtrl;
				_overlapGrid = overlapGrid;
				_parentControl.MouseDown += _parentControl_MouseDown;
			}

			private void _parentControl_MouseDown(object sender, MouseButtonEventArgs e)
			{
				if (_parentControl.PlotAttributes.AllowDoubleClickToEditPlotTitle && _editTextBox != null && EditTextBox.Visibility == Visibility.Visible && !EditTextBox.IsMouseOver)
				{
					HideEditTextBox();
				}
			}

			private void EditTextBox_LostKeyboardFocus(object sender, KeyboardFocusChangedEventArgs e)
			{
				HideEditTextBox();
			}

			public void OnMouseDoubleClick(MouseButtonEventArgs args)
			{
				if (_parentControl.PlotAttributes.AllowDoubleClickToEditPlotTitle)
				{
					PlotElementInfo plotElementInfo = PlotElementInfo.CreateFrom(args, _plotCtrl);
					if (plotElementInfo.TargetElementType == PlotSelectedElementType.Title)
					{
						FrameworkElement targetElement = plotElementInfo.TargetElement;
						DisplayEditTextBox(targetElement);
					}
				}
			}

			public void HideEditTextBox()
			{
				if (!string.IsNullOrWhiteSpace(EditTextBox.Text))
				{
					_parentControl.PlotData.PlotTitle = EditTextBox.Text;
				}
				EditTextBox.Visibility = Visibility.Collapsed;
				_overlapGrid.Background = null;
			}

			private void DisplayEditTextBox(FrameworkElement titleElement)
			{
				_overlapGrid.Background = System.Windows.Media.Brushes.Transparent;
				EditTextBox.Text = _parentControl.PlotData.PlotTitle;
				EditTextBox.MinWidth = titleElement.ActualWidth;
				EditTextBox.MinHeight = titleElement.ActualHeight;
				SpecPlotFontAttributes titleFontAttributes = _parentControl.PlotAttributes.TitleFontAttributes;
				EditTextBox.FontFamily = titleFontAttributes.FontFamily;
				EditTextBox.FontSize = titleFontAttributes.FontSize;
				EditTextBox.FontStyle = titleFontAttributes.FontStyle;
				EditTextBox.FontWeight = titleFontAttributes.FontWeight;
				EditTextBox.Foreground = new SolidColorBrush(titleFontAttributes.FontColor);
				System.Windows.Point point = titleElement.TranslatePoint(new System.Windows.Point(0.0, 0.0), _plotCtrl);
				EditTextBox.Margin = new Thickness(point.X, point.Y, 0.0, 0.0);
				EditTextBox.Visibility = Visibility.Visible;
				EditTextBox.SelectAll();
				EditTextBox.Focus();
			}
		}

		private class OrderedDataStore : List<IDataPoint>, IPlotDataStore, IPlotDataSource, IEnumerable<IDataPoint>, IEnumerable, IList<IDataPoint>, ICollection<IDataPoint>
		{
			private string _xUom = string.Empty;

			private string _yUom = string.Empty;

			private string _zUom = string.Empty;

			private PlotDataSourceType _dataSourceType;

			public new IDataPoint this[int index]
			{
				get
				{
					return base[index];
				}
				set
				{
					if (base[index] != value)
					{
						base[index] = value;
						Updated = true;
					}
				}
			}

			public PlotDataSourceType DataSourceType
			{
				get
				{
					return _dataSourceType;
				}
				set
				{
					if (_dataSourceType != value)
					{
						_dataSourceType = value;
						Updated = true;
					}
				}
			}

			public int DataSize
			{
				get
				{
					switch (_dataSourceType)
					{
					case PlotDataSourceType.Surface:
					case PlotDataSourceType.HiLoAvg:
						return 3;
					case PlotDataSourceType.Bar:
					case PlotDataSourceType.Histogram:
					case PlotDataSourceType.Bubble:
					case PlotDataSourceType.HiLo:
						return 2;
					default:
						return 1;
					}
				}
			}

			public bool LiveDataSource => false;

			public bool Updated { get; set; }

			public new void Add(IDataPoint item)
			{
				AddPoint(item);
			}

			public new void Insert(int index, IDataPoint item)
			{
				TryRemoveFakePoint();
				base.Insert(index, item);
				Updated = true;
			}

			public new void RemoveAt(int index)
			{
				base.RemoveAt(index);
				Updated = true;
				TryAddFakePoint();
			}

			public new void Clear()
			{
				base.Clear();
				Updated = true;
				TryAddFakePoint();
			}

			private int AddPoint(IDataPoint item)
			{
				TryRemoveFakePoint();
				if (base.Count == 0)
				{
					base.Add(item);
					Updated = true;
					return 0;
				}
				int num = 0;
				int num2 = base.Count - 1;
				int? num3 = null;
				double num4 = (double)item.X;
				while (num <= num2)
				{
					int num5 = (num + num2) / 2;
					double doubleValueAt = GetDoubleValueAt(num5);
					if (num4 == doubleValueAt)
					{
						num3 = num5 + 1;
						break;
					}
					if (num4 < doubleValueAt)
					{
						num2 = num5 - 1;
					}
					else
					{
						num = num5 + 1;
					}
				}
				if (!num3.HasValue)
				{
					num3 = num;
				}
				if (num3 < 0)
				{
					num3 = 0;
				}
				if (num3 > base.Count)
				{
					num3 = base.Count;
				}
				base.Insert(num3.Value, item);
				Updated = true;
				return num3.Value;
			}

			private void TryRemoveFakePoint()
			{
				if (base.Count == 1)
				{
					IDataPoint dataPoint = this[0];
					if (dataPoint.X is double && dataPoint.Y is double && double.IsNaN((double)dataPoint.X) && double.IsNaN((double)dataPoint.Y))
					{
						Remove(dataPoint);
						Updated = true;
					}
				}
			}

			private void TryAddFakePoint()
			{
				if (base.Count == 0)
				{
					base.Add((IDataPoint)new RDataPoint
					{
						X = double.NaN,
						Y = double.NaN
					});
					Updated = true;
				}
			}

			private double GetDoubleValueAt(int index)
			{
				return (double)this[index].X;
			}

			public int AddPoint(object x, object y, object z, string label, bool newSegment, object styleKey, bool hideSymbol)
			{
				RDataPoint rDataPoint = new RDataPoint();
				rDataPoint.X = x;
				rDataPoint.Y = y;
				rDataPoint.Z = z;
				rDataPoint.Label = label;
				rDataPoint.NewSegment = newSegment;
				rDataPoint.StyleKey = styleKey;
				rDataPoint.HideSymbol = hideSymbol;
				return AddPoint(rDataPoint);
			}

			public int AddPoint(object x, object y, object z, string label, bool newSegment)
			{
				return AddPoint(x, y, z, label, newSegment, null, hideSymbol: false);
			}

			public int AddPoint(object x, object y, string label, bool newSegment, object styleKey, bool hideSymbol)
			{
				return AddPoint(x, y, 0, label, newSegment, styleKey, hideSymbol);
			}

			public int AddPoint(object x, object y, string label, bool newSegment)
			{
				return AddPoint(x, y, 0, label, newSegment);
			}

			public int AddPoint(object x, object y, object z)
			{
				return AddPoint(x, y, z, string.Empty, newSegment: false);
			}

			public int AddPoint(object x, object y)
			{
				return AddPoint(x, y, 0, string.Empty, newSegment: false);
			}

			public void SetDataUom(string xUom, string yUom, string zUom)
			{
				if (xUom != _xUom || yUom != _yUom || zUom != _zUom)
				{
					_xUom = xUom;
					_yUom = yUom;
					_zUom = zUom;
					Updated = true;
				}
			}

			public void GetDataUom(out string xUom, out string yUom, out string zUom)
			{
				xUom = _xUom;
				yUom = _yUom;
				zUom = _zUom;
			}
		}

		private class DisplayModeToCheckStatusConverter : IValueConverter
		{
			public SpecPlotDisplayMode CheckedMode { get; set; }

			public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
			{
				if (value is SpecPlotDisplayMode)
				{
					return (SpecPlotDisplayMode)value == CheckedMode;
				}
				return false;
			}

			public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
			{
				if (value is bool && (bool)value)
				{
					return CheckedMode;
				}
				return SpecPlotDisplayMode.Plot;
			}
		}

		public static readonly DependencyProperty DisplayModeProperty;

		public static readonly DependencyProperty SuppressDataVirtualizationProperty;

		private static readonly DependencyPropertyKey IsPrintingPropertyKey;

		public static readonly DependencyProperty IsPrintingProperty;

		private const string PART_OverlapGrid = "PART_OverlapGrid";

