		public void Print()
		{
			IsPrinting = true;
			try
			{
				if (DisplayMode == SpecPlotDisplayMode.Plot)
				{
					InternalPlotCtrl.PrintPlot();
				}
				else if (DisplayMode == SpecPlotDisplayMode.FacePlate)
				{
					InternalFacePlateControl.Print(PlotData.PlotTitle, null);
				}
				else if (DisplayMode == SpecPlotDisplayMode.Table)
				{
					InternalGridControl.Print(PlotData.PlotTitle, null);
				}
			}
			finally
			{
				IsPrinting = false;
			}
		}

