		private void UpdateZoomer()
		{
			SpecPlotValueRange extentRange = PlotData.ExtentRange;
			if (extentRange.IsValid)
			{
				SpecPlotValueRange zoomRange = PlotData.ZoomRange;
				if (zoomRange != null && zoomRange.IsValid)
				{
					PlotZoomer.XAxisZoomFactor = zoomRange.Length / extentRange.Length;
				}
				SpecPlotValueRange relativeZoomRangeOnYAxis = _uiHelper.GetRelativeZoomRangeOnYAxis();
				if (relativeZoomRangeOnYAxis != null && relativeZoomRangeOnYAxis.IsValid)
				{
					PlotZoomer.YAxisZoomFactor = relativeZoomRangeOnYAxis.Length;
				}
			}
		}

