		private static object CoerceDisplayMode(DependencyObject d, object baseValue)
		{
			SpecPlotControl specPlotControl = d as SpecPlotControl;
			if (baseValue is SpecPlotDisplayMode newMode && specPlotControl.DisplayModeChanging != null && specPlotControl.TriggerDisplayModeChangingEvent(specPlotControl.DisplayMode, newMode))
			{
				return specPlotControl.DisplayMode;
			}
			return baseValue;
		}

