		public SpecPlotValueRange ExtentRange
		{
			get
			{
				if (RecordsCount <= 0)
				{
					return new SpecPlotValueRange(0.0, MinWindowSize);
				}
				double xAxisValue = GetXAxisValue(0);
				double right = Math.Max(xAxisValue + MinWindowSize, GetXAxisValue(RecordsCount - 1));
				return new SpecPlotValueRange(xAxisValue, right);
			}
		}

