		internal SpecPlotData(SpecPlotControl parentPlotControl)
		{
			if (parentPlotControl == null)
			{
				throw new ArgumentNullException("parentPlotControl");
			}
			_parentPlotControl = parentPlotControl;
			DataSeriesCollection = new ObservableCollection<SpecPlotDataSeries>();
			DataSeriesCollection.CollectionChanged += DataSeries_CollectionChanged;
		}

		private void DataSeries_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			if (e.OldItems != null)
			{
				foreach (SpecPlotDataSeries oldItem in e.OldItems)
				{
					oldItem.ParentPlotControl = null;
				}
			}
			if (e.NewItems != null)
			{
				foreach (SpecPlotDataSeries newItem in e.NewItems)
				{
					newItem.ParentPlotControl = _parentPlotControl;
				}
			}
			if (!_parentPlotControl._supressNotifyDataSeriesCollectionChanged)
			{
				_parentPlotControl.OnDataSeriesCollectionChanged();
			}
		}

		public double GetXAxisValue(int recordIndex)
		{
			if (recordIndex < 0 || recordIndex >= RecordsCount)
			{
				return 0.0;
			}
			if (_xAxisValuesCache.ContainsKey(recordIndex))
			{
				return _xAxisValuesCache[recordIndex];
			}
			SpecPlotXAxisDataQueryEventArgs e = new SpecPlotXAxisDataQueryEventArgs(recordIndex);
			_parentPlotControl.OnXAxisDataQueried(e);
			_xAxisValuesCache[recordIndex] = e.Value;
			return e.Value;
		}

		public double? GetPointValue(SpecPlotDataSeries series, int recordIndex)
		{
			if (series == null)
			{
				throw new ArgumentNullException("series");
			}
			if (recordIndex < 0 || recordIndex >= RecordsCount)
			{
				return null;
			}
			Dictionary<int, double?> value = null;
			if (!_pointValuesCache.TryGetValue(series, out value))
			{
				value = (_pointValuesCache[series] = new Dictionary<int, double?>());
			}
			if (value.ContainsKey(recordIndex))
			{
				return value[recordIndex];
			}
			double xAxisValue = GetXAxisValue(recordIndex);
			SpecPlotPointDataQueryEventArgs e = new SpecPlotPointDataQueryEventArgs(recordIndex, xAxisValue, series);
			_parentPlotControl.OnPointDataQueried(e);
			value[recordIndex] = e.Value;
			return e.Value;
		}

		public void InvalidateData(SpecPlotDataSeries series = null, SpecPlotLocationRange range = null, bool invalidateEmptyValuesOnly = false)
		{
			ClearCachedPoints(series, range, invalidateEmptyValuesOnly);
			_parentPlotControl.ClearPlotCachedPoints(series, range);
			_parentPlotControl.InvalidateData();
		}

		public void ClearValuesInCache()
		{
			_xAxisValuesCache.Clear();
			_pointValuesCache.Clear();
		}

		private void ClearCachedPoints(SpecPlotDataSeries series = null, SpecPlotLocationRange range = null, bool onlyEmptyValues = false)
		{
			if (series != null && !_pointValuesCache.ContainsKey(series))
			{
				return;
			}
			if (range == null)
			{
				if (series == null)
				{
					if (!onlyEmptyValues)
					{
						_pointValuesCache.Clear();
						return;
					}
					{
						foreach (Dictionary<int, double?> points in _pointValuesCache.Values)
						{
							foreach (int item in points.Keys.Where((int x) => !points[x].HasValue).ToList())
							{
								points.Remove(item);
							}
						}
						return;
					}
				}
				if (!onlyEmptyValues)
				{
					_pointValuesCache.Remove(series);
					return;
				}
				Dictionary<int, double?> points2 = _pointValuesCache[series];
				{
					foreach (int item2 in points2.Keys.Where((int x) => !points2[x].HasValue).ToList())
					{
						points2.Remove(item2);
					}
					return;
				}
			}
			if (series == null)
			{
				if (!onlyEmptyValues)
				{
					foreach (Dictionary<int, double?> value in _pointValuesCache.Values)
					{
						for (int num = range.Start; num <= range.End; num++)
						{
							if (value.ContainsKey(num))
							{
								value.Remove(num);
							}
						}
					}
					return;
				}
				{
					foreach (Dictionary<int, double?> value2 in _pointValuesCache.Values)
					{
						for (int num2 = range.Start; num2 <= range.End; num2++)
						{
							if (value2.ContainsKey(num2) && !value2[num2].HasValue)
							{
								value2.Remove(num2);
							}
						}
					}
					return;
				}
			}
			if (!onlyEmptyValues)
			{
				Dictionary<int, double?> dictionary = _pointValuesCache[series];
				for (int num3 = range.Start; num3 <= range.End; num3++)
				{
					if (dictionary.ContainsKey(num3))
					{
						dictionary.Remove(num3);
					}
				}
				return;
			}
			Dictionary<int, double?> dictionary2 = _pointValuesCache[series];
			for (int num4 = range.Start; num4 <= range.End; num4++)
			{
				if (dictionary2.ContainsKey(num4) && !dictionary2[num4].HasValue)
				{
					dictionary2.Remove(num4);
				}
			}
		}

