		private static void OnZoomRangePropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			SpecPlotData specPlotData = d as SpecPlotData;
			SpecPlotValueRange specPlotValueRange = e.OldValue as SpecPlotValueRange;
			SpecPlotValueRange specPlotValueRange2 = e.NewValue as SpecPlotValueRange;
			if (specPlotValueRange == null || specPlotValueRange2 == null || !specPlotValueRange.Equals(specPlotValueRange2))
			{
				specPlotData._parentPlotControl.OnXAxisZoomRangeChanged();
			}
		}

		private static object OnZoomRangePropertyCoerced(DependencyObject d, object value)
