		private SpecPlotControl PlotOwner { get; set; }

		private PlotCtrl OriginalPlotCtrl => PlotOwner.InternalPlotCtrl;

		private bool IsPlotInitialized => OriginalPlotCtrl.Plot.Frames.Count > 0;

		private IGraphLayout GraphLayout => OriginalPlotCtrl.Plot.Frames[0].GraphLayout;

		private IGraphAxis XAxis => GraphLayout.Graph.Axes.GetAxis(PlotAxisID.X);

		private IGraphAxis YAxis => GraphLayout.Graph.Axes.GetAxis(PlotAxisID.Y);

		internal SpecPlotAttributes(SpecPlotControl plotOwner)
		{
			if (plotOwner == null)
			{
				throw new ArgumentNullException("plotOwner");
			}
			PlotOwner = plotOwner;
			PlotOwner.MouseMove += PlotOwner_MouseMove;
		}

		private void TextAnnotations_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			if (e.OldItems != null)
			{
				foreach (SpecPlotTextAnnotation oldItem in e.OldItems)
				{
					oldItem.ParentAttributes = null;
				}
			}
			if (e.NewItems != null)
			{
				foreach (SpecPlotTextAnnotation newItem in e.NewItems)
				{
					newItem.ParentAttributes = this;
				}
			}
			if (IsPlotInitialized)
			{
				UpdateTextAnnotations();
				PlotOwner.InvalidateInternalPlotControl();
			}
		}

		private void PlotOwner_MouseMove(object sender, MouseEventArgs e)
		{
			if (IsPlotInitialized && PlotOwner.DisplayMode == SpecPlotDisplayMode.Plot && _trackerScooter != null && !TrackerLineXPosition.HasValue)
			{
				if (PlotOwner.PlotData.RecordsCount > 0)
				{
					_trackerScooter.Visible = true;
					System.Windows.Point position = e.GetPosition(OriginalPlotCtrl);
					AxesVisual axesVisual = GraphLayout.Graph.Axes.Renderer.Visual as AxesVisual;
					double val = axesVisual.PlotAreaToHost(position).X / axesVisual.PlotArea.Width;
					val = Math.Max(0.0, Math.Min(1.0, val));
					double snappedFractionX = GetSnappedFractionX(val);
					_trackerScooter.SetFractionalPosition(snappedFractionX);
				}
				else
				{
					_trackerScooter.Visible = false;
				}
				PlotOwner.InvalidateInternalPlotControl();
			}
		}

		private double GetSnappedFractionX(double fraction)
		{
			bool valid = false;
			IGraphAxis xAxis = XAxis;
			double? num = xAxis.AxisAnnotator.AxisFractionUnmapValue(xAxis, fraction, out valid) as double?;
			if (!valid || !num.HasValue)
			{
				return 0.0;
			}
			double value = num.Value;
			int num2 = 0;
			SpecPlotData plotData = PlotOwner.PlotData;
			int num3 = plotData.RecordsCount - 1;
			while (num2 <= num3)
			{
				int num4 = (num2 + num3) / 2;
				double xAxisValue = plotData.GetXAxisValue(num4);
				if (xAxisValue == value)
				{
					return fraction;
				}
				if (value < xAxisValue)
				{
					num3 = num4 - 1;
				}
				else
				{
					num2 = num4 + 1;
				}
			}
			if (num2 == 0)
			{
				return 0.0;
			}
			double xAxisValue2 = plotData.GetXAxisValue(num2 - 1);
			double xAxisValue3 = plotData.GetXAxisValue(num2);
			if (value <= xAxisValue2 || value >= xAxisValue3)
			{
				return fraction;
			}
			double num5 = (xAxisValue3 - xAxisValue2) * 0.1;
			if (value - xAxisValue2 <= num5)
			{
				return Math.Max(0.0, xAxis.AxisAnnotator.AxisFractionMapValue(xAxis, xAxisValue2, out valid));
			}
			if (xAxisValue3 - value <= num5)
			{
				return Math.Min(1.0, xAxis.AxisAnnotator.AxisFractionMapValue(xAxis, xAxisValue3, out valid));
			}
			return fraction;
		}

		public void ApplyAttributes()
		{
			if (!IsPlotInitialized)
			{
				return;
			}
			UpdateMultipleYAxes();
			base.Dispatcher.BeginInvoke((Action)delegate
			{
				IGraphAxis xAxis = XAxis;
				IGraphAxis yAxis = YAxis;
				if (XAxisType != SpecPlotAxisType.Linear)
				{
					xAxis.AxisAnnotator = CreateNewAxisAnnotator(XAxisType);
				}
				if (YAxisType != SpecPlotAxisType.Linear)
				{
					yAxis.AxisAnnotator = CreateNewAxisAnnotator(YAxisType);
				}
				xAxis.SetVisualElementColour(PlotAxisVisualElements.Edge, XAxisEdgeColor);
				yAxis.SetVisualElementColour(PlotAxisVisualElements.Edge, YAxisEdgeColor);
				GraphLayout.TitlePosition = (ShowPlotTitle ? GraphTitlePosition.TopMiddle : GraphTitlePosition.None);
				xAxis.SetVisualElementVisibility(PlotAxisVisualElements.Title, ShowXAxisTitle);
				UpdateLegendPosition();
				UpdateYAxisVisibility();
				UpdateTextAnnotations();
				UpdateTitleFontAttributes();
				UpdateSubtitleFontAttributes();
				UpdateLegendFontAttributes();
				UpdateXAxisTitleFontAttributes();
				UpdateYAxisTitleFontAttributes();
				UpdateXAxisScalesFontAttributes();
				UpdateYAxisScalesFontAttributes();
				OriginalPlotCtrl.SetBinding(PlotCtrl.AllowElementSelectionProperty, new Binding
				{
					Source = this,
					Path = new PropertyPath(AllowElementSelectionProperty),
					Mode = BindingMode.OneWay
				});
				GraphLayout.ScrollBarVisibility = ScrollBarVisibility;
				GraphLayout.HorizontalScrollBarVisibility = HorizontalScrollBarVisibility;
				GraphLayout.VerticalScrollBarVisibility = VerticalScrollBarVisibility;
				PlotOwner.InvalidatePlotProperties();
			});
		}

		private void UpdateTextAnnotations()
		{
			IGraphAnnotationCollection annotationCollection = GraphLayout.Graph.AnnotationCollection;
			int count = TextAnnotations.Count;
			int num = annotationCollection.Count((IGraphAnnotation x) => x is IGraphTextAnnotation);
			for (int num2 = 0; num2 < num - count; num2++)
			{
				annotationCollection.Remove(annotationCollection.Last((IGraphAnnotation x) => x is IGraphTextAnnotation));
			}
			for (int num3 = 0; num3 < count - num; num3++)
			{
				annotationCollection.Add(new GraphTextAnnotation(GraphLayout.Graph));
			}
			int num4 = 0;
			foreach (IGraphAnnotation item in annotationCollection)
			{
				if (item is IGraphTextAnnotation gta)
				{
					SpecPlotTextAnnotation sta = TextAnnotations[num4++];
					AssignAnnotationProperties(gta, sta);
				}
			}
		}

		internal void OnTextAnnotationPropertyChanged(SpecPlotTextAnnotation sta)
		{
			if (!IsPlotInitialized)
			{
				return;
			}
			int num = TextAnnotations.IndexOf(sta);
			if (num < 0)
			{
				return;
			}
			int num2 = 0;
			foreach (IGraphAnnotation item in GraphLayout.Graph.AnnotationCollection)
			{
				if (item is IGraphTextAnnotation gta)
				{
					if (num2 == num)
					{
						AssignAnnotationProperties(gta, sta);
						PlotOwner.InvalidateInternalPlotControl();
						break;
					}
					num2++;
				}
			}
		}

		private void AssignAnnotationProperties(IGraphTextAnnotation gta, SpecPlotTextAnnotation sta)
		{
			IDataSeries dataSeries = GraphLayout.Graph.DataSeriesCollection.FirstOrDefault((IDataSeries x) => x.Tag == sta.OwnerDataSeries);
			if (dataSeries != null)
			{
				gta.Text = sta.Text;
				gta.FontFamily = sta.FontAttributes.FontFamily;
				gta.Colour = sta.FontAttributes.FontColor;
				gta.PointSize = sta.FontAttributes.FontSize;
				if (sta.BackgroundColor != null)
				{
					gta.BackgroundColour = sta.BackgroundColor;
				}
				if (sta.HorizontalAlignment == HorizontalAlignment.Left || sta.HorizontalAlignment == HorizontalAlignment.Stretch)
				{
					gta.ContentAnchor = GraphElementPosition.Left;
				}
				else if (sta.HorizontalAlignment == HorizontalAlignment.Center)
				{
					gta.ContentAnchor = GraphElementPosition.Centre;
				}
				else
				{
					gta.ContentAnchor = GraphElementPosition.Right;
				}
				if (sta.VerticalAlignment == VerticalAlignment.Top || sta.VerticalAlignment == VerticalAlignment.Stretch)
				{
					gta.ContentAnchor |= GraphElementPosition.Top;
				}
				else if (sta.VerticalAlignment == VerticalAlignment.Bottom)
				{
					gta.ContentAnchor |= GraphElementPosition.Bottom;
				}
				else
				{
					gta.ContentAnchor |= GraphElementPosition.Middle;
				}
				gta.SetPosition(sta.Position.X, sta.Position.Y, dataSeries);
			}
		}

		private void UpdateMultipleYAxes()
		{
			PlotOwner.InvalidateYAxis();
			UpdateZeroLine();
			UpdateTracker();
		}

		private void UpdateZeroLine()
		{
			if (!IsPlotInitialized)
			{
				return;
			}
			if (ShowZeroLine && (!ShowMultipleYAxes || PlotOwner.PlotData.DataSeriesCollection.Count <= 1))
			{
				if (_zeroLineScooter == null)
				{
					IGraphScooter graphScooter = GraphLayout.Graph.NewScooter();
					graphScooter.LinkedAxisId = PlotAxisID.Y;
					graphScooter.LineStyle = AspenTech.Visualisation.Controls.Plot.LineStyle.Solid;
					graphScooter.LineWidth = ZeroLineWidth;
					graphScooter.LineColour = ZeroLineColor;
					graphScooter.ScooterType = ScooterType.Data;
					graphScooter.ScooterPosition = 0.0;
					graphScooter.ShowIntersectTicks = false;
					graphScooter.ShowIntersectValues = false;
					_zeroLineScooter = graphScooter;
				}
			}
			else if (_zeroLineScooter != null && GraphLayout.Graph.ScooterCollection.Contains(_zeroLineScooter))
			{
				GraphLayout.Graph.DeleteScooter(_zeroLineScooter);
				_zeroLineScooter = null;
			}
		}

		internal void UpdateTracker()
		{
			if (!IsPlotInitialized)
			{
				return;
			}
			if (ShowTrackerLine)
			{
				if (_trackerScooter == null)
				{
					IGraphScooter graphScooter = GraphLayout.Graph.NewScooter();
					graphScooter.LinkedAxisId = PlotAxisID.X;
					graphScooter.LineStyle = AspenTech.Visualisation.Controls.Plot.LineStyle.Solid;
					graphScooter.LineWidth = TrackerLineWidth;
					graphScooter.LineColour = TrackerLineColor;
					graphScooter.ScooterType = ScooterType.Axis;
					graphScooter.ShowIntersectTicks = false;
					graphScooter.ShowIntersectValues = true;
					graphScooter.Renderer.Visual.IsHitTestVisible = false;
					_trackerScooter = graphScooter;
				}
				bool flag = !PlotOwner.IsPrinting && PlotOwner.PlotData.RecordsCount > 0;
				if (flag)
				{
					flag = SetTrackerPosition(TrackerLineXPosition);
				}
				_trackerScooter.Visible = flag;
			}
			else if (_trackerScooter != null)
			{
				if (GraphLayout.Graph.ScooterCollection.Contains(_trackerScooter))
				{
					GraphLayout.Graph.DeleteScooter(_trackerScooter);
				}
				_trackerScooter = null;
			}
		}

		private bool SetTrackerPosition(double? position)
		{
			if (_trackerScooter != null && position.HasValue)
			{
				SpecPlotValueRange zoomRange = PlotOwner.PlotData.ZoomRange;
				if (zoomRange != null && zoomRange.IsValid)
				{
					double num = zoomRange.PointToFraction(position.Value);
					if (num >= 0.0 && num <= 1.0)
					{
						_trackerScooter.SetFractionalPosition(num);
						return true;
					}
				}
			}
			return false;
		}

		private void UpdateYAxisVisibility()
		{
			IGraphAxis yAxis = YAxis;
			if (yAxis is IMultiGraphAxis)
			{
				IMultiGraphAxis multiGraphAxis = yAxis as IMultiGraphAxis;
				{
					foreach (IDataSeries item in GraphLayout.Graph.DataSeriesCollection)
					{
						multiGraphAxis.GetAxis(item)?.SetVisualElementVisibility(PlotAxisVisualElements.Title, ShowYAxisTitle);
					}
					return;
				}
			}
			yAxis.SetVisualElementVisibility(PlotAxisVisualElements.Title, ShowYAxisTitle);
		}

		private SpecPlotFontAttributes ResolveFontAttributes(string key, Action propertyChangedAction)
		{
			if (_fontAttributes == null)
			{
				_fontAttributes = new Dictionary<string, SpecPlotFontAttributes>();
			}
			if (_fontAttributes.ContainsKey(key))
			{
				return _fontAttributes[key];
			}
			SpecPlotFontAttributes specPlotFontAttributes = new SpecPlotFontAttributes();
			specPlotFontAttributes.PropertyChanged += delegate
			{
				if (propertyChangedAction != null)
				{
					propertyChangedAction();
				}
			};
			_fontAttributes[key] = specPlotFontAttributes;
			return specPlotFontAttributes;
		}

