	public class SpecPlotFontAttributes : DependencyObject, INotifyPropertyChanged
	{
		public static readonly DependencyProperty FontFamilyProperty = DependencyProperty.Register("FontFamily", typeof(System.Windows.Media.FontFamily), typeof(SpecPlotFontAttributes), new PropertyMetadata(PlotSupport.SystemCaptionTypeface, OnDependencyPropertyChanged));

		public static readonly DependencyProperty FontSizeProperty = DependencyProperty.Register("FontSize", typeof(double), typeof(SpecPlotFontAttributes), new PropertyMetadata(16.0, OnDependencyPropertyChanged));

		public static readonly DependencyProperty FontColorProperty = DependencyProperty.Register("FontColor", typeof(System.Windows.Media.Color), typeof(SpecPlotFontAttributes), new PropertyMetadata(Colors.Black, OnDependencyPropertyChanged));

		public static readonly DependencyProperty FontStyleProperty = DependencyProperty.Register("FontStyle", typeof(System.Windows.FontStyle), typeof(SpecPlotFontAttributes), new PropertyMetadata(FontStyles.Normal, OnDependencyPropertyChanged));

		public static readonly DependencyProperty FontWeightProperty = DependencyProperty.Register("FontWeight", typeof(FontWeight), typeof(SpecPlotFontAttributes), new PropertyMetadata(FontWeights.Normal, OnDependencyPropertyChanged));

		public static readonly DependencyProperty TextDecorationsProperty = DependencyProperty.Register("TextDecorations", typeof(TextDecorationCollection), typeof(SpecPlotFontAttributes), new PropertyMetadata(OnDependencyPropertyChanged));

		public System.Windows.Media.FontFamily FontFamily
		{
			get
			{
				return (System.Windows.Media.FontFamily)GetValue(FontFamilyProperty);
			}
			set
			{
				SetValue(FontFamilyProperty, value);
			}
		}

		public double FontSize
		{
			get
			{
				return (double)GetValue(FontSizeProperty);
			}
			set
			{
				SetValue(FontSizeProperty, value);
			}
		}

		public System.Windows.Media.Color FontColor
		{
			get
			{
				return (System.Windows.Media.Color)GetValue(FontColorProperty);
			}
			set
