				SetValue(TextDecorationsProperty, value);
			}
		}

		public event PropertyChangedEventHandler PropertyChanged;

		protected virtual void OnPropertyChanged(string propertyName)
		{
			if (this.PropertyChanged != null)
			{
				this.PropertyChanged(this, new PropertyChangedEventArgs(propertyName));
			}
		}

		public string Save()
		{
			XElement xElement = new XElement("SpecPlotFontAttributes");
			xElement.SetAttributeValue("FontFamily", (FontFamily == null) ? null : FontFamily.Source);
			xElement.SetAttributeValue("FontSize", FontSize.ToString(CultureInfo.InvariantCulture));
			xElement.SetAttributeValue("FontColor", FontColor);
			xElement.SetAttributeValue("FontStyle", FontStyle);
			xElement.SetAttributeValue("FontWeight", FontWeight);
			xElement.SetAttributeValue("TextDecorations", ConvertToString(TextDecorations));
			return xElement.ToString(SaveOptions.DisableFormatting);
		}

		public void TryParse(string text)
		{
			XElement xElement = SpecPlotCurveFormat.TryParseXElement(text);
			if (xElement != null)
			{
				System.Windows.Media.FontFamily fontFamily = CreateFontFamily((string)xElement.Attribute("FontFamily"));
				if (fontFamily != null)
				{
					FontFamily = fontFamily;
				}
				double? doubleValue = xElement.Attribute("FontSize").GetDoubleValue(CultureInfo.InvariantCulture);
				if (doubleValue.HasValue)
				{
					FontSize = doubleValue.Value;
				}
				string value = (string)xElement.Attribute("FontColor");
				if (!string.IsNullOrWhiteSpace(value))
				{
					System.Windows.Media.Color fontColor = (System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(value);
					FontColor = fontColor;
				}
				System.Windows.FontStyle? fontStyle = CreateFontStyle((string)xElement.Attribute("FontStyle"));
				if (fontStyle.HasValue)
				{
					FontStyle = fontStyle.Value;
				}
				FontWeight? fontWeight = CreateFontWeight((string)xElement.Attribute("FontWeight"));
				if (fontWeight.HasValue)
				{
					FontWeight = fontWeight.Value;
				}
				TextDecorationCollection textDecorationCollection = CreateTextDecorations((string)xElement.Attribute("TextDecorations"));
				if (textDecorationCollection != null)
				{
					TextDecorations = textDecorationCollection;
				}
			}
		}

		public bool EqualsToSettings(string settings)
		{
			XElement xElement = SpecPlotCurveFormat.TryParseXElement(settings);
			if (xElement == null)
			{
				return false;
			}
			XAttribute xAttribute = xElement.Attribute("FontFamily");
			bool flag = xAttribute == null || string.IsNullOrWhiteSpace((string)xAttribute);
			if (FontFamily == null)
			{
				if (!flag)
				{
					return false;
				}
			}
			else
			{
				if (flag)
				{
					return false;
				}
				if (!SpecPlotEqualMethods.EqualsEx(FontFamily.Source, xAttribute))
				{
					return false;
				}
			}
			if (!SpecPlotEqualMethods.EqualsEx(FontSize, xElement.Attribute("FontSize"), CultureInfo.InvariantCulture))
			{
				return false;
			}
			if (!SpecPlotEqualMethods.EqualsEx(FontColor, (string)xElement.Attribute("FontColor")))
			{
				return false;
			}
			if (!SpecPlotEqualMethods.GenericEquals(FontStyle, (string)xElement.Attribute("FontStyle")))
			{
				return false;
			}
			if (!SpecPlotEqualMethods.GenericEquals(FontWeight, (string)xElement.Attribute("FontWeight")))
			{
				return false;
			}
			if (!SpecPlotEqualMethods.GenericEquals(ConvertToString(TextDecorations), (string)xElement.Attribute("TextDecorations")))
			{
				return false;
			}
			return true;
		}

		private static void OnDependencyPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			(d as SpecPlotFontAttributes).OnPropertyChanged(e.Property.Name);
		}

		private static System.Windows.Media.FontFamily CreateFontFamily(string fontFamily)
		{
			try
			{
				if (!string.IsNullOrEmpty(fontFamily))
				{
					return new System.Windows.Media.FontFamily(fontFamily);
				}
			}
			catch
			{
			}
			return null;
		}

		private static System.Windows.FontStyle? CreateFontStyle(string fontStyle)
		{
			if (string.Equals(fontStyle, "Italic", StringComparison.CurrentCultureIgnoreCase))
			{
				return FontStyles.Italic;
			}
			if (string.Equals(fontStyle, "Oblique", StringComparison.CurrentCultureIgnoreCase))
			{
				return FontStyles.Oblique;
			}
			if (string.Equals(fontStyle, "Normal", StringComparison.CurrentCultureIgnoreCase))
			{
				return FontStyles.Normal;
			}
			try
			{
				return (System.Windows.FontStyle)new FontStyleConverter().ConvertFromString(fontStyle);
			}
			catch
			{
				return null;
			}
		}

		private static FontWeight? CreateFontWeight(string fontWeight)
		{
			if (string.Equals(fontWeight, "Bold", StringComparison.CurrentCultureIgnoreCase))
			{
				return FontWeights.Bold;
			}
			if (string.Equals(fontWeight, "Normal", StringComparison.CurrentCultureIgnoreCase))
			{
				return FontWeights.Normal;
			}
			try
			{
				return (FontWeight)new FontWeightConverter().ConvertFromString(fontWeight);
			}
			catch
			{
				return null;
			}
		}

		private static TextDecorationCollection CreateTextDecorations(string textDecorations)
		{
			if (string.Equals(textDecorations, "Underline", StringComparison.CurrentCultureIgnoreCase))
			{
				return System.Windows.TextDecorations.Underline;
			}
			if (string.Equals(textDecorations, "Baseline", StringComparison.CurrentCultureIgnoreCase))
			{
				return System.Windows.TextDecorations.Baseline;
			}
			if (string.Equals(textDecorations, "OverLine", StringComparison.CurrentCultureIgnoreCase))
			{
				return System.Windows.TextDecorations.OverLine;
			}
			try
			{
				return TextDecorationCollectionConverter.ConvertFromString(textDecorations);
			}
			catch
			{
				return null;
			}
		}

		private static string ConvertToString(TextDecorationCollection textDecorations)
		{
			if (textDecorations != null)
			{
				StringBuilder stringBuilder = new StringBuilder();
				foreach (TextDecoration textDecoration in textDecorations)
				{
					if (stringBuilder.Length > 0)
					{
						stringBuilder.Append(',');
					}
					stringBuilder.Append(textDecoration.Location.ToString());
				}
				return stringBuilder.ToString();
			}
			return null;
		}
	}
	public class SpecPlotDataSeries : DependencyObject
	{
