	public class SpecPlotValueRange : ICloneable
	{
		public double Left { get; private set; }

		public double Right { get; private set; }

		public bool IsValid
		{
			get
			{
				if (!double.IsNaN(Left) && !double.IsNaN(Right))
				{
					return Left < Right;
				}
				return false;
			}
		}

		public double Length => Right - Left;

		public SpecPlotValueRange(double left, double right)
		{
			Left = left;
			Right = right;
		}

		public SpecPlotValueRange Shift(double offset)
		{
			return new SpecPlotValueRange(Left + offset, Right + offset);
		}

		public SpecPlotValueRange ExtendsFromCenter(double ratio)
		{
			double num = (Left + Right) / 2.0;
			double num2 = ratio * (Right - Left) / 2.0;
			return new SpecPlotValueRange(num - num2, num + num2);
		}

		public bool Contains(double point)
		{
			if (IsRoughlyEqual(point, Left) || IsRoughlyEqual(point, Right))
			{
				return true;
			}
			if (point > Left)
			{
				return point < Right;
			}
			return false;
		}

		public double PointToFraction(double point)
		{
			if (IsValid)
			{
				return (point - Left) / Length;
			}
			return double.NaN;
		}

		public double FractionToPoint(double fraction)
		{
			if (IsValid)
			{
				return Left + Length * fraction;
			}
			return double.NaN;
		}

		public override string ToString()
		{
			return $"({Left.ToString(CultureInfo.InvariantCulture)}, {Right.ToString(CultureInfo.InvariantCulture)})";
		}

		public override bool Equals(object obj)
		{
			if (obj is SpecPlotValueRange specPlotValueRange)
			{
				if (SpecPlotEqualMethods.EqualsEx(Left, specPlotValueRange.Left))
				{
					return SpecPlotEqualMethods.EqualsEx(Right, specPlotValueRange.Right);
				}
				return false;
			}
			return false;
		}

		public bool EqualsTo(string serialized)
		{
			SpecPlotValueRange obj = TryParse(serialized);
			return Equals(obj);
		}

		public override int GetHashCode()
		{
			return base.GetHashCode();
		}

		public static SpecPlotValueRange TryParse(string text)
		{
			if (!string.IsNullOrWhiteSpace(text))
			{
				string text2 = text.Trim();
				if (text2.FirstOrDefault() == '(' && text2.LastOrDefault() == ')')
				{
					text2 = text2.Substring(1, text2.Length - 2);
				}
				string[] array = text2.Split(',');
				if (array.Length == 2)
				{
					double result = 0.0;
					double result2 = 0.0;
					if (double.TryParse(array[0], NumberStyles.Any, CultureInfo.InvariantCulture, out result) && double.TryParse(array[1], NumberStyles.Any, CultureInfo.InvariantCulture, out result2))
					{
						return new SpecPlotValueRange(result, result2);
					}
				}
			}
			return null;
		}

		public static SpecPlotValueRange FixRange(SpecPlotValueRange extent, SpecPlotValueRange range)
		{
			if (range == null || !range.IsValid)
			{
				return null;
			}
			if (extent == null || !extent.IsValid)
			{
				return range;
			}
			if (range.Length >= extent.Length)
			{
				return new SpecPlotValueRange(extent.Left, extent.Right);
			}
			if (range.Left < extent.Left)
			{
				return new SpecPlotValueRange(extent.Left, extent.Left + range.Length);
			}
			if (range.Right > extent.Right)
			{
				return new SpecPlotValueRange(extent.Right - range.Length, extent.Right);
			}
			return new SpecPlotValueRange(range.Left, range.Right);
		}

		public object Clone()
		{
			return new SpecPlotValueRange(Left, Right);
		}

		private static bool IsRoughlyEqual(double x, double y)
		{
			return Math.Abs(x - y) <= 1E-06;
		}
	}
