	public static class SpecPlotEqualMethods
	{
		public static bool EqualsEx(string first, string second, StringComparison comparison = StringComparison.CurrentCulture)
		{
			if (string.IsNullOrWhiteSpace(first) && string.IsNullOrWhiteSpace(second))
			{
				return true;
			}
			return string.Equals(first, second, comparison);
		}

		public static bool EqualsEx(string first, XElement second, StringComparison comparison = StringComparison.CurrentCulture)
		{
			return EqualsEx(first, (string)second);
		}

		public static bool EqualsEx(string first, XAttribute second, StringComparison comparison = StringComparison.CurrentCulture)
		{
			return EqualsEx(first, (string)second);
		}

		public static bool EqualsEx(int? first, int? second)
		{
			if (first == second)
			{
				return true;
			}
			if (first.HasValue && second.HasValue)
			{
				return first.Value == second.Value;
			}
			return false;
		}

		public static bool EqualsEx(int? first, XElement second, IFormatProvider formatProvider = null)
		{
			return EqualsEx(first, second.GetIntegerValue(formatProvider));
		}

		public static bool EqualsEx(int? first, XAttribute second, IFormatProvider formatProvider = null)
		{
			return EqualsEx(first, second.GetIntegerValue(formatProvider));
		}

		public static bool EqualsEx(double? first, double? second)
		{
			if (first == second)
			{
				return true;
			}
			if (first.HasValue && second.HasValue)
			{
				return Math.Abs(first.Value - second.Value) < 1E-06;
			}
			return false;
		}

		public static bool EqualsEx(double? first, XElement second, IFormatProvider formatProvider = null)
		{
			return EqualsEx(first, second.GetDoubleValue(formatProvider));
		}

		public static bool EqualsEx(double? first, XAttribute second, IFormatProvider formatProvider = null)
		{
			return EqualsEx(first, second.GetDoubleValue(formatProvider));
		}

		public static bool EqualsEx(bool? first, bool? second)
		{
			return first == true == (second == true);
		}

		public static bool EqualsEx(bool? first, XElement second)
		{
			return EqualsEx(first, (bool?)second);
		}

		public static bool EqualsEx(bool? first, XAttribute second)
		{
			return EqualsEx(first, (bool?)second);
		}

		public static bool EqualsEx(SpecPlotValueRange first, string second)
		{
			return first?.EqualsTo(second) ?? string.IsNullOrWhiteSpace(second);
		}

		public static bool EqualsEx(System.Windows.Media.Color? first, string second)
		{
			if (!first.HasValue)
			{
				return string.IsNullOrWhiteSpace(second);
			}
			return string.Equals(first.Value.ToString(), second);
		}

		public static bool EnumEquals<T>(T first, string second)
		{
			if (string.IsNullOrWhiteSpace(second))
			{
				return object.Equals(first, default(T));
			}
			return EqualsEx(first.ToString(), second);
		}

		public static bool GenericEquals(object first, string second)
		{
			if (first == null)
			{
				return string.IsNullOrWhiteSpace(second);
			}
			return string.Equals(first.ToString(), second);
		}

		public static int? GetIntegerValue(this XElement element, IFormatProvider formatProvider = null)
		{
			if (element != null)
			{
				return TryGetIntegerValue(element.Value, formatProvider);
			}
			return null;
		}

		public static int? GetIntegerValue(this XAttribute attribute, IFormatProvider formatProvider = null)
		{
			if (attribute != null)
			{
				return TryGetIntegerValue(attribute.Value, formatProvider);
			}
			return null;
		}

		public static double? GetDoubleValue(this XElement element, IFormatProvider formatProvider = null)
		{
			if (element != null)
			{
				return TryGetDoubleValue(element.Value, formatProvider);
			}
			return null;
		}

		public static double? GetDoubleValue(this XAttribute attribute, IFormatProvider formatProvider = null)
		{
			if (attribute != null)
			{
				return TryGetDoubleValue(attribute.Value, formatProvider);
			}
			return null;
		}

		private static int? TryGetIntegerValue(string text, IFormatProvider formatProvider)
		{
			if (!string.IsNullOrWhiteSpace(text))
			{
				int result = 0;
				if (int.TryParse(text, NumberStyles.Any, formatProvider, out result))
				{
					return result;
				}
			}
			return null;
		}

		private static double? TryGetDoubleValue(string text, IFormatProvider formatProvider)
		{
			if (!string.IsNullOrWhiteSpace(text))
			{
				double result = 0.0;
				if (double.TryParse(text, NumberStyles.Any, formatProvider, out result))
				{
					return result;
				}
			}
			return null;
		}
