		static SpecPlotLineStyleComboBox()
		{
			StrokeDashArray_None = new DoubleCollection { 0.0, 2.0 };
			StrokeDashArray_Solid = new DoubleCollection { 2.0, 0.0 };
			StrokeDashArray_Dot = new DoubleCollection { 2.0, 2.0 };
			StrokeDashArray_Dash = new DoubleCollection { 4.0, 1.0 };
			StrokeDashArray_DashDot = new DoubleCollection { 4.0, 1.0, 2.0, 1.0 };
			StrokeDashArray_DashDotDot = new DoubleCollection { 4.0, 1.0, 2.0, 1.0, 2.0, 1.0 };
			SelectedStrokeDashArrayProperty = DependencyProperty.Register("SelectedStrokeDashArray", typeof(DoubleCollection), typeof(SpecPlotLineStyleComboBox), new FrameworkPropertyMetadata(OnSelectedStrokeDashArrayPropertyChanged));
			SelectedLineStyleProperty = DependencyProperty.Register("SelectedLineStyle", typeof(SpecPlotLineStyle), typeof(SpecPlotLineStyleComboBox), new FrameworkPropertyMetadata(OnSelectedLineStylePropertyChanged));
			StrokeDashArraysPropertyKey = DependencyProperty.RegisterReadOnly("StrokeDashArrays", typeof(IEnumerable<DoubleCollection>), typeof(SpecPlotLineStyleComboBox), null);
			StrokeDashArraysProperty = StrokeDashArraysPropertyKey.DependencyProperty;
			AvoidNoneItemProperty = DependencyProperty.Register("AvoidNoneItem", typeof(bool), typeof(SpecPlotLineStyleComboBox), new FrameworkPropertyMetadata(OnAvoidNoneItemPropertyChanged));
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(SpecPlotLineStyleComboBox), new FrameworkPropertyMetadata(typeof(SpecPlotLineStyleComboBox)));
		}

		public SpecPlotLineStyleComboBox()
		{
			InitializeStrokeDashArrays();
		}

		protected virtual void OnAvoidNoneItemChanged(bool oldValue, bool newValue)
		{
			InitializeStrokeDashArrays();
		}

		private void InitializeStrokeDashArrays()
		{
			List<DoubleCollection> list = new List<DoubleCollection> { StrokeDashArray_Solid, StrokeDashArray_Dot, StrokeDashArray_Dash, StrokeDashArray_DashDot, StrokeDashArray_DashDotDot };
			if (!AvoidNoneItem)
			{
				list.Insert(0, StrokeDashArray_None);
			}
			StrokeDashArrays = list;
		}

		private static SpecPlotLineStyle ConvertToLineStyle(DoubleCollection dc)
		{
			if (dc == StrokeDashArray_Solid)
			{
				return SpecPlotLineStyle.Solid;
			}
			if (dc == StrokeDashArray_Dot)
			{
				return SpecPlotLineStyle.Dot;
			}
			if (dc == StrokeDashArray_Dash)
			{
				return SpecPlotLineStyle.Dash;
			}
			if (dc == StrokeDashArray_DashDot)
			{
				return SpecPlotLineStyle.DashDot;
			}
			if (dc == StrokeDashArray_DashDotDot)
			{
				return SpecPlotLineStyle.DashDotDot;
			}
			return SpecPlotLineStyle.None;
		}

		private static DoubleCollection GetDashArray(SpecPlotLineStyle lineStyle)
		{
			return lineStyle switch
			{
				SpecPlotLineStyle.Solid => StrokeDashArray_Solid, 
				SpecPlotLineStyle.Dot => StrokeDashArray_Dot, 
				SpecPlotLineStyle.Dash => StrokeDashArray_Dash, 
				SpecPlotLineStyle.DashDot => StrokeDashArray_DashDot, 
				SpecPlotLineStyle.DashDotDot => StrokeDashArray_DashDotDot, 
				_ => StrokeDashArray_None, 
			};
		}

		private static void OnSelectedStrokeDashArrayPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			SpecPlotLineStyleComboBox obj = d as SpecPlotLineStyleComboBox;
			DoubleCollection dc = e.NewValue as DoubleCollection;
			obj.SelectedLineStyle = ConvertToLineStyle(dc);
		}

		private static void OnSelectedLineStylePropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			SpecPlotLineStyleComboBox obj = d as SpecPlotLineStyleComboBox;
			SpecPlotLineStyle lineStyle = (SpecPlotLineStyle)e.NewValue;
			obj.SelectedStrokeDashArray = GetDashArray(lineStyle);
		}

		private static void OnAvoidNoneItemPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			(d as SpecPlotLineStyleComboBox).OnAvoidNoneItemChanged((bool)e.OldValue, (bool)e.NewValue);
		}
	}
