	public class AdhocPlot : IAdhocPlot
	{
		private IUnityContainer _unityContainer;

		private CxsCase _cxsCase;

		private CxsDataProvider _provider;

		private PlotValue _plotValue;

		private bool _plotUptoDate;

		public bool isAdsPlot;

		private bool? _isRealLabel;

		private bool? _isIntegerLabel;

		private List<double> _realLabels;

		private string _parentPathIndexForLabel;

		private Dictionary<string, object[]> _pathProperties = new Dictionary<string, object[]>();

		private List<PlotVariableDescriptor> _independentVariableList = new List<PlotVariableDescriptor>();

		private string _independentVariableParent;

		private List<PlotVariableDescriptor> _parametricVariableList = new List<PlotVariableDescriptor>();

		private string _parametericVariableParent;

		private List<List<PlotVariableDescriptor>> _dependentVariableLists = new List<List<PlotVariableDescriptor>>();

		private List<string> _dependentVariableParent = new List<string>();

		public List<int> _dependentVariableDepth = new List<int>();

		private List<string> _curveNameLst = new List<string>();

		private string _xAxisTitle = string.Empty;

		[Microsoft.Practices.Unity.Dependency]
		public IUnityContainer UnityContainer
		{
			get
			{
				return _unityContainer;
			}
			set
			{
				if (value != _unityContainer)
				{
					_unityContainer = value;
					_cxsCase = _unityContainer.Resolve<CxsCase>(Array.Empty<ResolverOverride>());
					_provider = _unityContainer.Resolve<CxsDataProvider>(Array.Empty<ResolverOverride>());
					OnUnityContainerChanged();
				}
			}
		}

		public IPlotValue PlotValue
		{
			get
			{
				LoadPlotValue();
				return _plotValue;
			}
		}

		public bool ReadyToPlot
		{
			get
			{
				if (_independentVariableList != null)
				{
					if (_dependentVariableLists != null && _dependentVariableLists.Count > 0)
					{
						return true;
					}
				}
				else if (_dependentVariableLists != null && _dependentVariableLists.Count > 0)
				{
					return IsIntegerRealLabel;
				}
				return false;
			}
		}

		private bool IsIntegerRealLabel
		{
			get
			{
				if (_dependentVariableLists == null || _dependentVariableLists.Count == 0)
				{
					_isRealLabel = false;
					return _isRealLabel.Value;
				}
				foreach (string item in _dependentVariableParent)
				{
					if (!_pathProperties.ContainsKey(item))
					{
						continue;
					}
					object[] array = _pathProperties[item];
					if (array == null || array.Count() <= 1)
					{
						continue;
					}
					string[] array2 = CxsConverter.ValueToOptionArray(array[1]);
					if (array2 == null || array2.Count() == 0)
					{
						continue;
					}
					_isRealLabel = true;
					_isIntegerLabel = true;
					_realLabels = new List<double>();
					string[] array3 = array2;
					foreach (string s in array3)
					{
						if (!double.TryParse(s, NumberStyles.Any, CultureInfo.InvariantCulture, out var result))
						{
							_isRealLabel = false;
							_isIntegerLabel = false;
							break;
						}
						_realLabels.Add(result);
						if (_isIntegerLabel.Value && !int.TryParse(s, NumberStyles.Any, CultureInfo.InvariantCulture, out var _))
						{
							_isIntegerLabel = false;
						}
					}
					if (_isRealLabel.Value)
					{
						_parentPathIndexForLabel = item;
						return true;
					}
				}
				return false;
			}
		}

		public bool PlotUptoDate
		{
			get
			{
				return _plotUptoDate;
			}
			set
			{
				_plotUptoDate = value;
			}
		}

