		protected virtual void OnUnityContainerChanged()
		{
		}

		private PlotValue EnsurePlotVal(ICxvViewDataContainer container)
		{
			if (_plotValue == null)
			{
				_plotValue = _unityContainer.Resolve<PlotValue>(Array.Empty<ResolverOverride>());
				if (container != null)
				{
					ICxsDataWatch cxsDataWatch = container.CreateCxsWatch();
					cxsDataWatch.AddWatch("Top.appModelV8.Settings.gridstyle", "value");
					cxsDataWatch.AddWatch("Top.appModelV8.Settings.linestyle", "value");
					cxsDataWatch.AddWatch("Top.appModelV8.Settings.plotmarkersize", "value");
					cxsDataWatch.AddWatch("Top.appModelV8.Settings.showlegend", "value");
					cxsDataWatch.AddWatch("Top.appModelV8.Settings.plottimestamp", "value");
					object[] values = cxsDataWatch.Values;
					cxsDataWatch.Unload();
					if (values != null)
					{
						if (values[0] != null && values[0].GetType() != typeof(DBNull))
						{
							_plotValue.GridType = (GridType)CxsConverter.ValueToInt32(values[0]).Value;
						}
						if (values[1] != null && values[1].GetType() != typeof(DBNull))
						{
							_plotValue.LineStyle = (LineStyle)CxsConverter.ValueToInt32(values[1]).Value;
						}
						if (values[2] != null && values[2].GetType() != typeof(DBNull))
						{
							_plotValue.MarkerSize = CxsConverter.ValueToInt32(values[2]).Value;
						}
						if (values[3] != null && values[3].GetType() != typeof(DBNull))
						{
							_plotValue.ShowLegend = CxsConverter.ValueToBoolean(values[3]) ?? true;
						}
						if (values[4] != null && values[4].GetType() != typeof(DBNull))
						{
							_plotValue.AddTimeStamp = CxsConverter.ValueToBoolean(values[4]) ?? false;
						}
					}
				}
			}
			return _plotValue;
		}

		private void LoadPlotValue()
		{
			if (!_plotUptoDate)
			{
				PlotValue plotValue = EnsurePlotVal(null);
				plotValue.Clear();
				bool flag = false;
				if (_parametricVariableList != null && _parametricVariableList.Count() > 0)
				{
					flag = true;
				}
				List<int> list = new List<int>();
				foreach (List<PlotVariableDescriptor> dependentVariableList in _dependentVariableLists)
				{
					for (int i = 0; i < dependentVariableList.Count(); i++)
					{
						if (!list.Contains(dependentVariableList[i].Location))
						{
							list.Add(dependentVariableList[i].Location);
						}
					}
				}
				bool flag2 = false;
				if (_independentVariableList == null || (_independentVariableList.Count() == 0 && IsIntegerRealLabel))
				{
					_ = IsIntegerRealLabel;
					if (_realLabels == null || _realLabels.Count() == 0)
					{
						return;
					}
					flag2 = true;
					_plotValue.Points = _realLabels.Count();
					string text = plotValue.Context;
					while (!_parentPathIndexForLabel.Contains(text) && text != "Top")
					{
						text = CxsPath.ParentPath(text);
					}
					string value = _parentPathIndexForLabel.Substring(text.Length);
					for (int j = 0; j < _realLabels.Count(); j++)
					{
						_plotValue.SetXData(0, j, 0, _realLabels[j]);
						_plotValue.SetXData(0, j, 1, value);
						_plotValue.SetXData(0, j, 3, "child_ids");
					}
					object[] array = _pathProperties[_parentPathIndexForLabel];
					if (array[3] != null && array[3].GetType() != typeof(DBNull))
					{
						_plotValue.SetXUOM(0, CxsConverter.ValueToString(array[3]));
					}
					if (_isIntegerLabel.HasValue)
					{
						_plotValue.SetXDataIsInteger(0, _isIntegerLabel.Value);
					}
				}
				else
				{
					bool flag3 = false;
					if (_independentVariableList.Count() > 0)
					{
						_plotValue.Points = _independentVariableList.Count();
						for (int k = 0; k < _independentVariableList.Count(); k++)
						{
							if (_plotValue.Points <= list.Count)
							{
								_plotValue.SetXData(0, k, 0, _independentVariableList[k].CurrentValue);
								_plotValue.SetXData(0, k, 1, _independentVariableList[k].Path);
								_plotValue.SetXData(0, k, 2, _independentVariableList[k].ExposeAs);
							}
							else
							{
								for (int l = 0; l < list.Count; l++)
								{
									if (k == list[l])
									{
										_plotValue.SetXData(0, l, 0, _independentVariableList[k].CurrentValue);
										_plotValue.SetXData(0, l, 1, _independentVariableList[k].Path);
										_plotValue.SetXData(0, l, 2, _independentVariableList[k].ExposeAs);
									}
								}
							}
							int result = 0;
							if (!int.TryParse((_independentVariableList[k].CurrentValue != null) ? _independentVariableList[k].CurrentValue.ToString() : string.Empty, out result))
							{
								flag3 = true;
							}
						}
						if (!string.IsNullOrEmpty(_independentVariableParent))
						{
							object[] array2 = _pathProperties[_independentVariableParent];
							if (array2[5] != null && array2[5].GetType() != typeof(DBNull))
							{
