		private void RemoveUnmatchedNodes()
		{
			if (_independentVariableList == null || _independentVariableList.Count() == 0)
			{
				return;
			}
			bool flag = false;
			for (int i = 0; i < _independentVariableList.Count(); i++)
			{
				int location = _independentVariableList[i].Location;
				if (_parametricVariableList != null && _parametricVariableList.Count() > 0)
				{
					int num = _parametricVariableList.Count();
					if (num > 0)
					{
						if (i < num && _parametricVariableList[i].Location < location)
						{
							_parametricVariableList.Remove(_parametricVariableList[i]);
							flag = true;
						}
						if (i >= num)
						{
							_parametricVariableList.Add(_parametricVariableList[i]);
						}
						else if (_parametricVariableList[i].Location > location)
						{
							_parametricVariableList.Insert(i, _parametricVariableList[i]);
						}
					}
				}
				for (int j = 0; j < _dependentVariableLists.Count(); j++)
				{
					List<PlotVariableDescriptor> list = new List<PlotVariableDescriptor>();
					list = _dependentVariableLists[j];
					int num2 = list.Count();
					if (i < num2 && list[i].Location < location)
					{
						list.Remove(list[i]);
						flag = true;
					}
					if (i >= num2)
					{
						list.Add(list[i]);
					}
					else if (list[i].Location > location)
					{
						list.Insert(i, list[i]);
					}
				}
			}
			for (int k = 0; k < _dependentVariableLists.Count(); k++)
			{
				new List<PlotVariableDescriptor>();
				if (_dependentVariableLists[k] == null)
				{
					_dependentVariableLists.RemoveAt(k);
					k--;
				}
			}
			if (flag)
			{
				ShowMessageBoxEventArgs payload = new ShowMessageBoxEventArgs
				{
					Title = AspenTech.AspenPlus.MMControls.Properties.Resources.strPlot,
					Message = AspenTech.AspenPlus.MMControls.Properties.Resources.strDataNotMatchVariable,
					MsgBoxButton = MessageBoxButton.OK,
					MsgBoxImage = MessageBoxImage.Asterisk
				};
				UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ShowMessageBoxEvent>().Publish(payload);
			}
		}

