		private void CachePathProperties(ICxvViewDataContainer container, string path, int depth, string decoratedName, string decoratedUnit)
		{
			ICxsDataWatch cxsDataWatch = null;
			if (container.ResolvedCxsProvider != null)
			{
				container.ResolvedCxsProvider.UpdateDataCache(path);
				cxsDataWatch = container.CreateCxsWatch();
			}
			else
			{
				_provider.Case = _cxsCase;
				_provider.UpdateDataCache(path);
				cxsDataWatch = _provider.CreateWatch();
			}
			cxsDataWatch.AddWatch(path, "type");
			cxsDataWatch.AddWatch(path, "child_ids");
			cxsDataWatch.AddWatch(path, "decorated_name");
			cxsDataWatch.AddWatch(path, "decorated_unit");
			cxsDataWatch.AddWatch(path, "dimension_name");
			cxsDataWatch.AddWatch(path, "dimension");
			cxsDataWatch.AddWatch(path, "uom");
			cxsDataWatch.AddWatch(path, "dummy1");
			cxsDataWatch.AddWatch(path, "dummy2");
			object[] values = cxsDataWatch.Values;
			if (values != null)
			{
				if (!string.IsNullOrEmpty(decoratedName) && values[2] as string != decoratedName)
				{
					values[7] = true;
				}
				else
				{
					values[7] = false;
				}
				if (!string.IsNullOrEmpty(decoratedUnit) && values[3] as string != decoratedUnit)
				{
					values[8] = true;
				}
				else
				{
					values[8] = false;
				}
			}
			_pathProperties.Remove(path);
			_pathProperties.Add(path, values);
			cxsDataWatch.Unload();
		}

		private void LoadFromSelection(ICxvViewDataContainer container, IEnumerable<object> selection, Dictionary<string, List<PlotVariableDescriptor>> lists, List<string> parents, List<int> depths, string context)
		{
