						list2.Last().Add(item);
					}
					else
					{
						int index = list.IndexOf(item.Column);
						list2[index].Add(item);
					}
				}
			}
			int num = 0;
			foreach (List<PlotVariableDescriptor> item2 in list2)
			{
				int num2 = 1;
				string text = null;
				string text2 = null;
				string text3 = null;
				PlotVariableDescriptor plotVariableDescriptor2 = item2.FirstOrDefault((PlotVariableDescriptor s) => s.Path != null);
				if (plotVariableDescriptor2 != null)
				{
					CxsBatchRequestData cxsBatchRequestData = new CxsBatchRequestData();
					CxsBatchRequestData cxsBatchRequestData2 = new CxsBatchRequestData();
					foreach (PlotVariableDescriptor item3 in item2)
					{
						cxsBatchRequestData.AddRequest(new CxsBatchRequest(item3.Path, "decorated_name"));
						cxsBatchRequestData2.AddRequest(new CxsBatchRequest(item3.Path, "decorated_unit"));
					}
					text = cxsBatchRequestData.CommonBasePath;
					if (text != null)
					{
						if (plotVariableDescriptor2.Path.Length > text.Length)
						{
							num2 = CxsPath.Split(plotVariableDescriptor2.Path.Substring(text.Length + 1)).Count();
						}
						string text4 = text;
						while (text4 != "Top")
						{
							object[] array = _cxsCase.BatchGet(cxsBatchRequestData);
							if (array != null)
							{
								object[] array2 = array;
								foreach (object obj in array2)
								{
									if (!string.IsNullOrEmpty(obj as string))
									{
										text2 = obj as string;
										break;
									}
								}
							}
							if (text2 != null)
							{
								break;
							}
							text4 = CxsPath.ParentPath(text4);
							cxsBatchRequestData.AddRequest(new CxsBatchRequest(text4, "decorated_name"));
						}
						object[] array3 = _cxsCase.BatchGet(cxsBatchRequestData2);
						if (array3 != null)
						{
							object[] array2 = array3;
							foreach (object obj2 in array2)
							{
								if (!string.IsNullOrEmpty(obj2 as string))
								{
									text3 = obj2 as string;
									break;
								}
							}
						}
						if (text3 == null)
						{
							text3 = plotVariableDescriptor2.Units;
						}
					}
				}
				foreach (PlotVariableDescriptor item4 in item2)
				{
					string parentPath = ((text == null) ? container.ExpandDataPath(item4.Path + ".@parent", null) : text);
					CachePathProperties(container, parentPath, num2, text2, text3);
					string key = num.ToString(CultureInfo.InvariantCulture) + parentPath;
					List<PlotVariableDescriptor> list3;
					if (lists.ContainsKey(key))
					{
						list3 = lists[key];
					}
					else
					{
						list3 = new List<PlotVariableDescriptor>();
						lists.Add(key, list3);
						parents.Find((string item) => item == parentPath);
						parents.Add(parentPath);
						if (depths.Count > parents.Count)
						{
							depths[parents.Count - 1] = num2;
						}
						else
						{
							depths.Add(num2);
						}
					}
					string text5 = context;
					if (item4.Path != null)
					{
						while (!item4.Path.Contains(text5) && text5 != "Top")
						{
							text5 = CxsPath.ParentPath(text5);
						}
					}
					list3.Add(new PlotVariableDescriptor
					{
						Path = ((item4.Path == null) ? null : item4.Path.Substring(text5.Length)),
						ExposeAs = item4.ExposeAs,
						CurrentValue = item4.CurrentValue,
						Column = item4.Column,
						Location = item4.Location,
						Dimension = item4.Dimension,
						Units = item4.Units,
						Decorated_name = (string.IsNullOrEmpty(item4.Decorated_name) ? text2 : item4.Decorated_name),
						Decorated_unit = text3,
						DataContainer = container
					});
				}
				num++;
			}
		}

		public void SetIndependentVariable(IEnumerable<object> selection, string xAxisTitle)
