	public class AdhocI18nHelper
	{
		public static string GetI18nString(string prompt)
		{
			if (string.IsNullOrEmpty(prompt))
			{
				return prompt;
			}
			string text = prompt;
			try
			{
				Assembly assembly = null;
				Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
				foreach (Assembly assembly2 in assemblies)
				{
					if (assembly2.GetName().Name == "AspenTech.AspenPlus.Localization")
					{
						assembly = assembly2;
						break;
					}
				}
				if (assembly == null)
				{
					return prompt;
				}
				Type type = assembly.GetType("AspenTech.AspenPlus.Localization.WpfPlotWizards.AdhocVaPromptResource");
				text = (type.GetProperty("ResourceManager", BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public).GetValue(type, null) as ResourceManager).GetString(CreateKey(prompt));
				if (string.IsNullOrEmpty(text))
				{
					text = prompt;
				}
			}
			catch (Exception)
			{
				return prompt;
			}
			return text;
		}

		private static string CreateKey(string prompt)
		{
			StringBuilder stringBuilder = new StringBuilder(prompt.Length * 2 + 1);
			stringBuilder.Append(Regex.Replace(prompt, "[^a-zA-Z0-9]", "_"));
			stringBuilder.Append(GetOwnHashCode(prompt));
			if (char.IsDigit(stringBuilder[0]))
			{
				stringBuilder.Insert(0, '_');
			}
			return stringBuilder.ToString();
		}

		private static string GetOwnHashCode(string prompt)
		{
			StringBuilder stringBuilder = new StringBuilder(prompt.Length + 1);
			stringBuilder.Append('_');
			for (int i = 0; i < prompt.Length; i++)
			{
				if (char.IsLetter(prompt[i]))
				{
					if (char.IsLower(prompt[i]))
					{
						stringBuilder.Append('0');
					}
					else
					{
						stringBuilder.Append('1');
					}
				}
			}
			return stringBuilder.ToString();
		}
	}
