		private static string SaveList<T>(IEnumerable<T> list)
		{
			if (list != null && list.Any())
			{
				XElement xElement = new XElement("List");
				foreach (T item in list)
				{
					XElement content = new XElement("Item", item);
					xElement.Add(content);
				}
				return xElement.ToString(SaveOptions.DisableFormatting);
			}
			return null;
		}

		private static IEnumerable<XElement> ExtractListItems(XElement xml, string propertyName)
		{
			XElement xElement = ((string)xml.Element(propertyName)).TryParseXElement();
			if (xElement == null)
			{
				yield break;
			}
			foreach (XElement item in xElement.Elements("Item"))
			{
				yield return item;
			}
		}

		private static string SaveDictionary(IDictionary<int, int> dict)
		{
			if (dict != null && dict.Count > 0)
			{
				XElement xElement = new XElement("Dict");
				foreach (int key in dict.Keys)
				{
					XElement xElement2 = new XElement("Item");
					xElement2.SetAttributeValue("Key", key);
					xElement2.SetAttributeValue("Value", dict[key]);
					xElement.Add(xElement2);
				}
				return xElement.ToString(SaveOptions.DisableFormatting);
			}
			return null;
		}

		private static Dictionary<int, int> ExtractDictionary(XElement xml, string propertyName)
		{
			Dictionary<int, int> dictionary = new Dictionary<int, int>();
			XElement xElement = ((string)xml.Element(propertyName)).TryParseXElement();
			if (xElement != null)
			{
				foreach (XElement item in xElement.Elements("Item"))
				{
					int? num = (int?)item.Attribute("Key");
					int? num2 = (int?)item.Attribute("Value");
					dictionary[num.GetValueOrDefault()] = num2.GetValueOrDefault();
				}
			}
			return dictionary;
		}

		private static string SavePointsVector(IEnumerable<List<PlotDataPoint>> vector)
		{
			if (vector != null && vector.Any())
			{
				XElement xElement = new XElement("Vector");
				foreach (List<PlotDataPoint> item in vector)
				{
					XElement xElement2 = new XElement("Line");
					if (item != null && item.Any())
					{
						foreach (PlotDataPoint item2 in item)
						{
							XElement content = new XElement("Point", item2.Save());
							xElement2.Add(content);
						}
					}
					xElement.Add(xElement2);
				}
				return xElement.ToString(SaveOptions.DisableFormatting);
			}
			return null;
		}

		private static IEnumerable<List<PlotDataPoint>> ExtractPointsVector(XElement xml, string propertyName)
		{
			XElement xElement = ((string)xml.Element(propertyName)).TryParseXElement();
			if (xElement == null)
			{
				yield break;
			}
			foreach (XElement item in xElement.Elements("Line"))
			{
				List<PlotDataPoint> list = new List<PlotDataPoint>();
				foreach (XElement item2 in item.Elements("Point"))
				{
					list.Add(PlotDataPoint.TryParse((string)item2));
				}
				yield return list;
			}
		}

