		public void SetXData(int index, int datano, int attribute, object value)
		{
			if (_xVariables == null)
			{
				_xVariables = new List<List<PlotDataPoint>>(XVariables);
				for (int i = 0; i < XVariables; i++)
				{
					_xVariables.Add(new List<PlotDataPoint>(Points));
					for (int j = 0; j < Points; j++)
					{
						_xVariables[i].Add(new PlotDataPoint());
					}
				}
			}
			if (index >= XVariables || datano >= Points)
			{
				return;
			}
			switch (attribute)
			{
			case 0:
				if (value == null)
				{
					_xVariables[index][datano].CurrentValue = 1E+28;
				}
				else if (value.GetType() == typeof(double))
				{
					_xVariables[index][datano].CurrentValue = (double)value;
				}
				else if (value.GetType() == typeof(int))
				{
					_xVariables[index][datano].CurrentValue = (int)value;
				}
				else if (value.GetType() == typeof(string))
				{
					if (double.TryParse((string)value, NumberStyles.Any, CultureInfo.InvariantCulture, out var result))
					{
						_xVariables[index][datano].CurrentValue = result;
					}
					else
					{
						_xVariables[index][datano].CurrentValue = 1E+28;
					}
				}
				break;
			case 1:
				if (value != null)
				{
					_xVariables[index][datano].Path = value.ToString();
				}
				break;
			case 2:
				if (value != null && value.GetType() == typeof(CxvVariableTypeCode))
				{
					_xVariables[index][datano].ExposeAs = (CxvVariableTypeCode)value;
				}
				break;
			case 3:
				if (value != null)
				{
					_xVariables[index][datano].CxsAttribute = value.ToString();
				}
				break;
			}
		}

