	public static class XmlPersisterExtensions
	{
		public static void TryAppendProperty<T>(this XElement target, string propertyName, T value)
		{
			if (target != null && !string.IsNullOrEmpty(propertyName) && !object.Equals(value, default(T)))
			{
				target.SetElementValue(propertyName, value);
			}
		}

		public static XElement TryParseXElement(this string text)
		{
			if (!string.IsNullOrWhiteSpace(text))
			{
				try
				{
					return XElement.Parse(text);
				}
				catch
				{
					return null;
				}
			}
			return null;
		}
	}
