	public class SpecPlotSymbolStyleComboBox : Control
	{
		public static readonly DependencyProperty SelectedIndexProperty;

		public static readonly DependencyProperty SelectedSymbolStyleProperty;

		public int SelectedIndex
		{
			get
			{
				return (int)GetValue(SelectedIndexProperty);
			}
			set
			{
				SetValue(SelectedIndexProperty, value);
			}
		}

		public SpecPlotSymbolStyle SelectedSymbolStyle
		{
			get
			{
				return (SpecPlotSymbolStyle)GetValue(SelectedSymbolStyleProperty);
			}
			set
			{
				SetValue(SelectedSymbolStyleProperty, value);
			}
		}

		static SpecPlotSymbolStyleComboBox()
		{
			SelectedIndexProperty = DependencyProperty.Register("SelectedIndex", typeof(int), typeof(SpecPlotSymbolStyleComboBox), new FrameworkPropertyMetadata(OnSelectedIndexPropertyChanged));
			SelectedSymbolStyleProperty = DependencyProperty.Register("SelectedSymbolStyle", typeof(SpecPlotSymbolStyle), typeof(SpecPlotSymbolStyleComboBox), new FrameworkPropertyMetadata(OnSelectedSymbolStylePropertyChanged));
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(SpecPlotSymbolStyleComboBox), new FrameworkPropertyMetadata(typeof(SpecPlotSymbolStyleComboBox)));
		}

		private static SpecPlotSymbolStyle GetSymboStyleFromIndex(int index)
		{
			return index switch
			{
				0 => SpecPlotSymbolStyle.None, 
				1 => SpecPlotSymbolStyle.Circle, 
				2 => SpecPlotSymbolStyle.Cross, 
				3 => SpecPlotSymbolStyle.Diamond, 
				4 => SpecPlotSymbolStyle.Dot, 
				5 => SpecPlotSymbolStyle.Plus, 
				6 => SpecPlotSymbolStyle.Square, 
				7 => SpecPlotSymbolStyle.TriangleUp, 
				8 => SpecPlotSymbolStyle.TriangleDown, 
				9 => SpecPlotSymbolStyle.FilledDiamond, 
				10 => SpecPlotSymbolStyle.FilledSquare, 
				11 => SpecPlotSymbolStyle.FilledTriangleUp, 
				12 => SpecPlotSymbolStyle.FilledTriangleDown, 
				_ => SpecPlotSymbolStyle.None, 
			};
		}

		private static int GetIndexFromSymbolStyle(SpecPlotSymbolStyle symbolStyle)
		{
			return symbolStyle switch
			{
				SpecPlotSymbolStyle.None => 0, 
				SpecPlotSymbolStyle.Circle => 1, 
				SpecPlotSymbolStyle.Cross => 2, 
				SpecPlotSymbolStyle.Diamond => 3, 
				SpecPlotSymbolStyle.Dot => 4, 
				SpecPlotSymbolStyle.Plus => 5, 
				SpecPlotSymbolStyle.Square => 6, 
				SpecPlotSymbolStyle.TriangleUp => 7, 
				SpecPlotSymbolStyle.TriangleDown => 8, 
				SpecPlotSymbolStyle.FilledDiamond => 9, 
				SpecPlotSymbolStyle.FilledSquare => 10, 
				SpecPlotSymbolStyle.FilledTriangleUp => 11, 
				SpecPlotSymbolStyle.FilledTriangleDown => 12, 
				_ => 0, 
			};
		}

		private static void OnSelectedIndexPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			(d as SpecPlotSymbolStyleComboBox).SelectedSymbolStyle = GetSymboStyleFromIndex((int)e.NewValue);
		}

		private static void OnSelectedSymbolStylePropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			(d as SpecPlotSymbolStyleComboBox).SelectedIndex = GetIndexFromSymbolStyle((SpecPlotSymbolStyle)e.NewValue);
		}
	}
