namespace AspenTech.AspenPlus.MMControls.Internal
{
	public static class MultipleMovingHelper
	{
		public static bool CanMove(int totalCount, IEnumerable<int> selectedIndexes, bool up, bool isLastIndexValid)
		{
			IList<int> orderedSelection = GetOrderedSelection(totalCount, selectedIndexes, isLastIndexValid);
			if (orderedSelection.Count > 0)
			{
				if (up)
				{
					return orderedSelection[orderedSelection.Count - 1] > orderedSelection.Count - 1;
				}
				if (isLastIndexValid)
				{
					return orderedSelection[0] + orderedSelection.Count < totalCount;
				}
				return orderedSelection[0] + orderedSelection.Count < totalCount - 1;
			}
			return false;
		}

		public static IDictionary<int, int> GetMovingTargets(int totalCount, IEnumerable<int> selectedIndexes, bool up, bool isLastIndexValid)
		{
			Dictionary<int, int> dictionary = new Dictionary<int, int>();
			if (CanMove(totalCount, selectedIndexes, up, isLastIndexValid))
			{
				IList<int> orderedSelection = GetOrderedSelection(totalCount, selectedIndexes, isLastIndexValid);
				if (up)
				{
					for (int i = 0; i < orderedSelection.Count; i++)
					{
						int num = orderedSelection[i];
						int value = ((num > i) ? (num - 1) : num);
						dictionary[num] = value;
					}
				}
				else
				{
					for (int j = 0; j < orderedSelection.Count; j++)
					{
						int num2 = orderedSelection[j];
						if (isLastIndexValid)
						{
							int num3 = num2 + 1;
							int value2 = ((num3 + orderedSelection.Count - 1 - j < totalCount) ? num3 : num2);
							dictionary[num2] = value2;
						}
						else
						{
							int num4 = num2 + 1;
							int value3 = ((num4 + orderedSelection.Count - j < totalCount) ? num4 : num2);
							dictionary[num2] = value3;
						}
					}
				}
			}
			return dictionary;
		}

		public static IList<int> GetNewIndexesAfterMoved(int totalCount, IDictionary<int, int> movingTargets, bool isLastIndexValid)
		{
			List<int> list = new List<int>();
			if (movingTargets != null && totalCount > 0)
			{
				int num = (isLastIndexValid ? totalCount : (totalCount - 1));
				List<int> list2 = new List<int>();
				for (int i = 0; i < num; i++)
				{
					list2.Add(i);
				}
				Dictionary<int, int> dictionary = new Dictionary<int, int>();
				foreach (int key in movingTargets.Keys)
				{
					dictionary[movingTargets[key]] = key;
				}
				Queue<int> queue = new Queue<int>(list2.Except(movingTargets.Keys));
				for (int j = 0; j < num; j++)
				{
					if (dictionary.ContainsKey(j))
					{
						list.Add(dictionary[j]);
					}
					else
					{
						list.Add(queue.Dequeue());
					}
				}
			}
			return list;
		}

		private static IList<int> GetOrderedSelection(int totalCount, IEnumerable<int> selectedIndexes, bool isLastIndexValid)
		{
			if (totalCount > 0 && selectedIndexes != null)
			{
				if (isLastIndexValid)
				{
					return selectedIndexes.OrderBy((int x) => x).ToList();
				}
				return (from x in selectedIndexes
					where x != totalCount - 1
					orderby x
					select x).ToList();
			}
			return new int[0];
		}
	}
	internal static class BindingHelpers
	{
		public static Binding UpdateVariablePropertyBinding(FrameworkElement element, DependencyProperty variableProperty, string oldPath, string newPath, Binding currentBinding)
		{
			if (oldPath == newPath)
			{
				return currentBinding;
			}
			if (BindingOperations.GetBinding(element, variableProperty) != currentBinding)
			{
				return null;
			}
			BindingOperations.ClearBinding(element, variableProperty);
			if (string.IsNullOrEmpty(newPath))
			{
				return null;
			}
			Binding binding = new Binding(newPath);
			BindingOperations.SetBinding(element, variableProperty, binding);
			return binding;
		}

		public static Binding UpdateVariableRelativeBinding(PropertyDescriptorCollection sourceProperties, DependencyObject element, DependencyProperty targetProperty, Binding existingBinding)
		{
			return UpdateVariableRelativeBinding(sourceProperties, element, targetProperty, targetProperty.Name, BindingMode.TwoWay, existingBinding);
		}

		public static Binding UpdateVariableRelativeBinding(PropertyDescriptorCollection sourceProperties, DependencyObject element, DependencyProperty targetProperty, BindingMode bindingMode, Binding existingBinding)
		{
			return UpdateVariableRelativeBinding(sourceProperties, element, targetProperty, targetProperty.Name, bindingMode, existingBinding);
		}

		public static Binding UpdateVariableRelativeBinding(PropertyDescriptorCollection sourceProperties, DependencyObject element, DependencyProperty targetProperty, string sourceSubProperty, BindingMode bindingMode, Binding existingBinding)
		{
			PropertyDescriptor propertyDescriptor = sourceProperties?.Find(sourceSubProperty, ignoreCase: false);
			if (propertyDescriptor != null)
			{
				if (bindingMode != BindingMode.OneWay && propertyDescriptor.IsReadOnly)
				{
					bindingMode = BindingMode.OneWay;
				}
				StringBuilder stringBuilder = new StringBuilder("Variable.");
				stringBuilder.Append(sourceSubProperty);
				string text = stringBuilder.ToString();
				if (existingBinding != null && (existingBinding.Mode != bindingMode || existingBinding.Path.Path != text))
				{
					BindingOperations.ClearBinding(element, targetProperty);
					existingBinding = null;
				}
				if (existingBinding == null)
				{
					existingBinding = new Binding
					{
						RelativeSource = RelativeSource.Self,
						Path = new PropertyPath(text),
						Mode = bindingMode
					};
					BindingOperations.SetBinding(element, targetProperty, existingBinding);
				}
			}
			else if (existingBinding != null)
			{
				BindingOperations.ClearBinding(element, targetProperty);
				existingBinding = null;
			}
			return existingBinding;
		}

		public static Binding UpdateRelativeBinding(PropertyDescriptorCollection sourceProperties, DependencyObject element, DependencyProperty targetProperty, DependencyProperty sourceProperty, Binding existingBinding)
		{
			return UpdateRelativeBinding(sourceProperties, element, targetProperty, sourceProperty, targetProperty.Name, BindingMode.TwoWay, existingBinding);
		}

		public static Binding UpdateRelativeBinding(PropertyDescriptorCollection sourceProperties, DependencyObject element, DependencyProperty targetProperty, DependencyProperty sourceProperty, string sourceSubProperty, BindingMode bindingMode, Binding existingBinding)
		{
			PropertyDescriptor propertyDescriptor = sourceProperties?.Find(sourceSubProperty, ignoreCase: false);
			if (propertyDescriptor != null)
			{
				if (bindingMode != BindingMode.OneWay && propertyDescriptor.IsReadOnly)
				{
					bindingMode = BindingMode.OneWay;
				}
				string text = sourceProperty.Name + "." + sourceSubProperty;
				if (existingBinding != null && (existingBinding.Mode != bindingMode || existingBinding.Path.Path != text))
				{
					BindingOperations.ClearBinding(element, targetProperty);
					existingBinding = null;
				}
				if (existingBinding == null)
				{
					existingBinding = new Binding
					{
						RelativeSource = RelativeSource.Self,
						Path = new PropertyPath(text),
						Mode = bindingMode
					};
					BindingOperations.SetBinding(element, targetProperty, existingBinding);
				}
			}
			else if (existingBinding != null)
			{
				BindingOperations.ClearBinding(element, targetProperty);
				existingBinding = null;
			}
			return existingBinding;
		}

		internal static bool PropertyAndBindingMatch(DependencyObject element, DependencyProperty property, DependencyProperty testProperty, Binding testBinding)
		{
			if (element == null || property != testProperty || testBinding == null)
			{
				return false;
			}
			return BindingOperations.GetBinding(element, property) == testBinding;
		}
	}
