	public class MMVerticalGridPanel : Grid
	{
		public static readonly DependencyProperty ChildrenCountProperty = DependencyProperty.Register("ChildrenCount", typeof(int), typeof(MMVerticalGridPanel), new PropertyMetadata(0, OnChildrenCountPropertyChanged));

		public int ChildrenCount
		{
			get
			{
				return (int)GetValue(ChildrenCountProperty);
			}
			set
			{
				SetValue(ChildrenCountProperty, value);
			}
		}

		public MMVerticalGridPanel()
		{
			base.RowDefinitions.Add(new RowDefinition
			{
				Height = new GridLength(0.0, GridUnitType.Auto)
			});
		}

		protected override System.Windows.Size ArrangeOverride(System.Windows.Size arrangeSize)
		{
			ChildrenCount = VisualChildrenCount;
			return base.ArrangeOverride(arrangeSize);
		}

		private static void OnChildrenCountPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			(d as MMVerticalGridPanel).ReSetElementLocation();
		}

		private void ReSetElementLocation()
		{
			base.RowDefinitions.Clear();
			base.RowDefinitions.Add(new RowDefinition
			{
				Height = new GridLength(0.0, GridUnitType.Auto)
			});
			foreach (UIElement child in base.Children)
			{
				if (MMVerticalGridPanelAttachProperty.GetPanelVerticalAlignment(child) == MMVerticalGridRowAlignment.Bottom)
				{
					base.RowDefinitions.Add(new RowDefinition
					{
						Height = new GridLength(1.0, GridUnitType.Star)
					});
					base.RowDefinitions.Add(new RowDefinition
					{
						Height = new GridLength(0.0, GridUnitType.Auto)
					});
					Grid.SetRow(child, base.RowDefinitions.Count - 1);
				}
				else
				{
					base.RowDefinitions.Add(new RowDefinition
					{
						Height = new GridLength(0.0, GridUnitType.Auto)
					});
					Grid.SetRow(child, base.RowDefinitions.Count - 1);
				}
			}
		}
	}
