		public ListChooserDialog(MMViewModel viewModel, string prompt, string path, string[] choices)
		{
			InitializeComponent();
			this.viewModel = viewModel;
			this.path = path;
			startingChoices = choices;
			if (choices != null)
			{
				foreach (string newItem in choices)
				{
					lbItems.Items.Add(newItem);
				}
			}
			HeaderLabel = prompt;
			base.Loaded += ListChooserDialog_Loaded;
		}

		private void Button_Click(object sender, RoutedEventArgs e)
		{
			base.DialogResult = true;
			Close();
		}

		private void lbItems_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			foreach (string removedItem in e.RemovedItems)
			{
				if (selection.Contains(removedItem))
				{
					selection.Remove(removedItem);
				}
			}
			foreach (string addedItem in e.AddedItems)
			{
				if (!selection.Contains(addedItem))
				{
					selection.Add(addedItem);
				}
			}
			if (selection.Count > 0)
			{
				bool isEnabled = true;
				btnRemove.IsEnabled = true;
				foreach (string item in selection)
				{
					if (item.Contains("Blocks"))
					{
						isEnabled = false;
					}
				}
				btnExport.IsEnabled = isEnabled;
			}
			else
			{
				btnRemove.IsEnabled = false;
				btnExport.IsEnabled = false;
			}
			GetOkButtonEnableFlag();
		}

		private void btnRemove_Click(object sender, RoutedEventArgs e)
		{
			string[] choice = Choice;
			lbItems.UnselectAll();
			string[] array = choice;
			foreach (string text in array)
			{
				remove.Add(text);
				lbItems.Items.Remove(text);
			}
			if (remove.Count > 0)
			{
				btnUndo.IsEnabled = true;
			}
			else
			{
				btnUndo.IsEnabled = false;
			}
			GetOkButtonEnableFlag();
		}

		private void btnExport_Click(object sender, RoutedEventArgs e)
		{
			if (selection == null && selection.Count == 0)
			{
				return;
			}
			List<int> list = new List<int>();
			foreach (string item in selection)
			{
				if (!startingChoices.Contains(item))
				{
					continue;
				}
				for (int i = 0; i < startingChoices.Count(); i++)
				{
					if (startingChoices[i] == item)
					{
						list.Add(i);
						break;
					}
				}
			}
			if (list.Count != 0)
			{
				viewModel.GxExportSelectedFile(path, list);
			}
		}

		private void btnUndo_Click(object sender, RoutedEventArgs e)
		{
			selection.Clear();
			lbItems.Items.Clear();
			string[] array = startingChoices;
			foreach (string newItem in array)
			{
				lbItems.Items.Add(newItem);
			}
			remove.Clear();
			btnUndo.IsEnabled = false;
			GetOkButtonEnableFlag();
		}

		private void GetOkButtonEnableFlag()
		{
			if (selection.Count > 0 || remove.Count > 0)
			{
				ButtonOkEnable = true;
			}
			else
			{
				ButtonOkEnable = false;
			}
		}

