				break;
			case 4:
				btnExport = (Button)target;
				btnExport.Click += btnExport_Click;
				break;
			case 5:
				btnUndo = (Button)target;
				btnUndo.Click += btnUndo_Click;
				break;
			default:
				_contentLoaded = true;
				break;
			}
		}
	}
