		private string GetPrompt(string key)
		{
			string text = key;
			int num = key.LastIndexOf(":");
			if (num > 0 && num < key.Length)
			{
				key = key.Substring(0, key.LastIndexOf(":"));
			}
			string name = "CreateId_" + key.Replace(' ', '_');
			name = AspenTech.AspenPlus.MMControls.Properties.Resources.ResourceManager.GetString(name, AspenTech.AspenPlus.MMControls.Properties.Resources.Culture);
			if (string.IsNullOrEmpty(name))
			{
				name = text;
			}
			return name;
		}

		private string GetLocalizedOption(string key, string defaultOptionValue)
		{
			string text = string.Empty;
			if (!string.IsNullOrEmpty(key))
			{
				string name = Regex.Replace(key, "[^a-zA-Z0-9]", "_").ToLower();
				text = AspenTech.AspenPlus.MMControls.Properties.Resources.ResourceManager.GetString(name, AspenTech.AspenPlus.MMControls.Properties.Resources.Culture);
			}
			if (!string.IsNullOrEmpty(text))
			{
				return text;
			}
			return defaultOptionValue;
		}

		public OneIdDialog(IUnityContainer container, string prompt, string default_text, string[] options, maskType mask, string title = null, int? maxTextLength = null)
		{
			UnityContainer = container;
			if (!string.IsNullOrEmpty(prompt))
			{
				this.prompt = GetPrompt(prompt);
			}
			if (!string.IsNullOrEmpty(title))
			{
				base.Title = title;
			}
			if (maxTextLength.HasValue)
			{
				TbTextLength = maxTextLength.Value;
			}
			this.default_text = default_text;
			if (default_text != null)
			{
				NewID = default_text;
			}
			this.mask = mask;
			option_list = options;
			InitializeComponent();
			LocalizePrompt();
			if (option_list != null)
			{
				for (int i = 0; i < options.Length; i++)
				{
					cbRecord.Items.Add(options[i]);
				}
				cbRecord.Items.SortDescriptions.Add(new SortDescription("", ListSortDirection.Ascending));
				btnOK.IsEnabled = false;
				base.Height += 40.0;
			}
			else
			{
				panelRecord.Visibility = Visibility.Collapsed;
				if (text == "")
				{
					btnOK.IsEnabled = false;
				}
			}
			switch (mask)
			{
			case maskType.IS_FORTRAN_VARIABLE:
				tbText.MaxLength = 8;
				tbText.CharacterCasing = CharacterCasing.Upper;
				break;
			case maskType.IS_TEXT:
				tbText.MaxLength = 100;
				tbText.CharacterCasing = CharacterCasing.Normal;
				break;
			case maskType.IS_MODEL:
				tbText.MaxLength = 27;
				tbText.CharacterCasing = CharacterCasing.Normal;
				break;
			}
			if (UnityContainer != null)
			{
				IShellApplication shellApplication = UnityContainer.Resolve<IShellApplication>(Array.Empty<ResolverOverride>());
				if (shellApplication != null)
				{
					base.Owner = Window.GetWindow(shellApplication.ActiveWindow as DependencyObject);
				}
			}
		}

		public OneIdDialog(IUnityContainer container, string prompt, string default_text, string[] options, string optionType, maskType mask, string title = null, int? maxTextLength = null)
		{
			UnityContainer = container;
			if (!string.IsNullOrEmpty(prompt))
			{
				this.prompt = GetPrompt(prompt);
			}
			if (!string.IsNullOrEmpty(title))
			{
				base.Title = title;
			}
			if (maxTextLength.HasValue)
			{
				TbTextLength = maxTextLength.Value;
			}
			this.default_text = default_text;
			if (default_text != null)
			{
				NewID = default_text;
			}
			this.mask = mask;
			List<string> list = new List<string>();
			if (options != null)
			{
				foreach (string text in options)
				{
					if (string.Compare(text, "PSValve") != 0)
					{
						list.Add(text);
					}
				}
			}
			if (list.Count > 0)
			{
				option_list = list.ToArray();
			}
			InitializeComponent();
			LocalizePrompt();
			if (option_list != null && option_list.Length != 0)
			{
				for (int j = 0; j < option_list.Length; j++)
				{
					string text2 = option_list[j];
					if (optionType != "Blocks")
					{
						text2 = GetLocalizedOption("rectype_" + optionType + "_" + options[j], options[j]);
					}
					if (localizedOptionlist == null)
					{
						localizedOptionlist = new List<string>();
					}
					localizedOptionlist.Add(text2);
					cbRecord.Items.Add(text2);
				}
				cbRecord.Items.SortDescriptions.Add(new SortDescription("", ListSortDirection.Ascending));
				btnOK.IsEnabled = false;
				base.Height += 40.0;
			}
			else
			{
				panelRecord.Visibility = Visibility.Collapsed;
				if (this.text == "")
				{
					btnOK.IsEnabled = false;
				}
			}
			if (mask == maskType.IS_FORTRAN_VARIABLE)
			{
				tbText.MaxLength = 8;
				tbText.CharacterCasing = CharacterCasing.Upper;
			}
			if (mask == maskType.IS_TEXT)
			{
				tbText.MaxLength = 100;
				tbText.CharacterCasing = CharacterCasing.Normal;
			}
			if (UnityContainer != null)
			{
				IShellApplication shellApplication = UnityContainer.Resolve<IShellApplication>(Array.Empty<ResolverOverride>());
				if (shellApplication != null)
				{
					base.Owner = Window.GetWindow(shellApplication.ActiveWindow as DependencyObject);
				}
			}
		}

		private void LocalizePrompt()
		{
			if (prompt == "Packing rating section number: ")
			{
				textBlkPrompt.Text = AspenTech.AspenPlus.MMControls.Properties.Resources.EnterPackingRatingId;
			}
			else if (prompt == "Packing sizing section number: ")
			{
				textBlkPrompt.Text = AspenTech.AspenPlus.MMControls.Properties.Resources.EnterPackingSizingId;
			}
			else
			{
				textBlkPrompt.Text = prompt;
			}
		}

		private void OneIDDialog_Loaded(object sender, RoutedEventArgs e)
		{
			if (ScriptingSupport.Enabled && ScriptingSupport.ScriptRunning)
			{
				int num = ScriptingSupport.DialogArgs.Find("Id");
				if (num >= 0)
				{
					NewID = ScriptingSupport.DialogArgs[num].Value.ToString();
				}
				num = ScriptingSupport.DialogArgs.Find("Type");
				if (num >= 0)
				{
					RecordType = ScriptingSupport.DialogArgs[num].Value.ToString();
				}
				tbText.Text = NewID;
				Ok_Click(null, null);
				if (base.DialogResult == true)
				{
					return;
				}
			}
			tbText.Focus();
			tbText.Text = text;
			tbText.SelectAll();
		}

		public string GetI18nApplicationName(string appName)
		{
			string text = "";
			try
			{
				string[] array = appName.Split(' ');
				foreach (string text2 in array)
				{
					text += text2;
				}
			}
			catch (Exception)
			{
			}
			text = AspenTech.AspenPlus.MMControls.Properties.Resources.ResourceManager.GetString(text);
			if (string.IsNullOrEmpty(text))
			{
				return appName;
			}
			return text;
		}

		public bool CheckIfValidId(string name, bool showErrorAsync = false)
		{
			if (string.IsNullOrEmpty(name))
			{
				return false;
			}
			if (Regex.IsMatch(name, "[^\\u0000-\\u007F]"))
			{
				string title = null;
				if (Provider != null && Provider.Case != null)
				{
					title = Provider.GetI18nApplicationName();
				}
				else if (UnityContainer != null)
				{
					CxsCase cxsCase = UnityContainer.Resolve<CxsCase>(Array.Empty<ResolverOverride>());
					if (cxsCase != null)
					{
						title = GetI18nApplicationName(cxsCase.ApplicationName);
					}
				}
				ShowMMMessageBoxEventArgs msg = new ShowMMMessageBoxEventArgs
				{
					Message = AspenTech.AspenPlus.MMControls.Properties.Resources.CannotInputNonASCIICharAsID,
					MsgBoxButton = 0,
					MsgBoxImage = 48,
					DialogResult = 1,
					Title = title
				};
				if (showErrorAsync)
				{
					base.Dispatcher.BeginInvoke((Action)delegate
					{
						UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ShowMMMessageBoxEvent>().Publish(msg);
					}, DispatcherPriority.Input);
				}
				else
				{
					UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ShowMMMessageBoxEvent>().Publish(msg);
				}
				return false;
			}
			if (ExistingIds != null)
			{
				string[] array = ExistingIds.Where((string id) => string.Compare(id, name, ignoreCase: true) == 0).ToArray();
				if (array != null && array.Length != 0)
				{
					string text = MMViewModel.ConflictingType(PathCheck, name, Provider);
					if (text == null)
					{
						text = "Object";
					}
					string title2 = null;
					if (Provider != null && Provider.Case != null)
					{
						title2 = Provider.GetI18nApplicationName();
					}
					else if (UnityContainer != null)
					{
						CxsCase cxsCase2 = UnityContainer.Resolve<CxsCase>(Array.Empty<ResolverOverride>());
						if (cxsCase2 != null)
						{
							title2 = GetI18nApplicationName(cxsCase2.ApplicationName);
						}
					}
					ShowMMMessageBoxEventArgs mbExists = new ShowMMMessageBoxEventArgs
					{
						Message = string.Format(AspenTech.AspenPlus.MMControls.Properties.Resources.strIdExists, name, text),
						MsgBoxButton = 0,
						MsgBoxImage = 48,
						DialogResult = 1,
						Title = title2
					};
					if (showErrorAsync)
					{
						base.Dispatcher.BeginInvoke((Action)delegate
						{
							UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ShowMMMessageBoxEvent>().Publish(mbExists);
						}, DispatcherPriority.Input);
					}
					else
					{
						UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ShowMMMessageBoxEvent>().Publish(mbExists);
					}
					return false;
				}
			}
			return true;
		}

		private void Ok_Click(object sender, RoutedEventArgs e)
		{
			if (CheckIfValidId(tbText.Text))
			{
				base.DialogResult = true;
				Close();
			}
		}

		private void On_tbTextChanged(object sender, RoutedEventArgs e)
		{
			BindingOperations.GetMultiBindingExpression(tbText, TextBox.TextProperty)?.UpdateSource();
			bool flag = (bool)tbText.GetValue(Validation.HasErrorProperty);
			tbText.ToolTip = null;
			if (flag || string.IsNullOrEmpty(text.Trim()) || !ValidName(tbText.Text) || tbText.Text.Length > tbTextLength)
			{
				btnOK.IsEnabled = false;
				if (flag)
				{
					tbText.ToolTip = "Invalid Id";
				}
			}
			else if (tbText.Text == "Application.Tree")
			{
				MessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.InvalidPath_Message, AspenTech.AspenPlus.MMControls.Properties.Resources.InvalidPath_Title, MessageBoxButton.OK, MessageBoxImage.Hand);
				btnOK.IsEnabled = false;
			}
			else if (option_list != null && recordType == null)
			{
				btnOK.IsEnabled = false;
			}
			else
			{
				btnOK.IsEnabled = true;
			}
		}

		private bool ValidName(string newValue)
		{
			switch (mask)
			{
			case maskType.IS_INTEGER:
			{
				if (newValue == null || newValue.Length <= 0)
				{
					break;
				}
				char[] array4 = newValue.ToCharArray();
				for (int num4 = 0; num4 < array4.Length; num4++)
				{
					if (!char.IsDigit(array4[num4]))
					{
						return false;
					}
				}
				break;
			}
			case maskType.IS_REAL:
			{
				if (newValue == null || newValue.Length <= 0)
				{
					break;
				}
				char[] array2 = newValue.ToCharArray();
				foreach (char c2 in array2)
				{
					if (!char.IsDigit(c2) && c2 != '.' && c2 != MaskingAndValidatingHelper.GetSystemDecimalSymbol()[0] && c2 != '+' && c2 != '-' && c2 != 'e' && c2 != 'E')
					{
						return false;
					}
				}
				break;
			}
			case maskType.IS_ID:
			{
				if (newValue == null || newValue.Length <= 0)
				{
					break;
				}
				if (!char.IsLetterOrDigit(newValue[0]))
				{
					return false;
				}
				char[] array = newValue.ToCharArray();
				for (int num = 1; num < array.Length; num++)
				{
					char c = array[num];
					if (!char.IsLetterOrDigit(c) && c != ',' && c != '$' && c != ':' && c != '+' && c != '-' && c != '\r' && c != '\b')
					{
						return false;
					}
				}
				break;
			}
			case maskType.IS_COMPID:
			{
				if (newValue == null || newValue.Length <= 0)
				{
					break;
				}
				if (!char.IsLetterOrDigit(newValue[0]))
				{
					throw new Exception("Invalid ID");
				}
				char[] array5 = newValue.ToCharArray();
				for (int num5 = 1; num5 < array5.Length; num5++)
				{
					char c4 = array5[num5];
					if (!char.IsLetterOrDigit(c4) && c4 != '$' && c4 != ',' && c4 != ':' && c4 != '+' && c4 != '-' && c4 != '/' && c4 != '=' && c4 != '*' && c4 != '.' && c4 != '&' && c4 != '(' && c4 != ')' && c4 != '[' && c4 != ']' && c4 != '{' && c4 != '}' && c4 != '<' && c4 != '>' && c4 != '\r' && c4 != '\b')
					{
						return false;
					}
				}
				break;
			}
			case maskType.IS_FORTRAN_VARIABLE:
			{
				if (newValue == null || newValue.Length <= 0)
				{
					break;
				}
				if (!char.IsLetter(newValue[0]))
				{
					return false;
				}
				char[] array3 = newValue.ToCharArray();
				for (int num3 = 1; num3 < array3.Length; num3++)
				{
					char c3 = array3[num3];
					if (!char.IsLetterOrDigit(c3) && c3 != '\b')
					{
						return false;
					}
				}
				if (array3.Length > 1 && ((array3[0] == 'I' && array3[1] == 'Z') || (array3[0] == 'Z' && array3[1] == 'Z')))
				{
					return false;
				}
				break;
			}
			case maskType.IS_MODEL:
				if (newValue != null && newValue.Length > 0)
				{
					if (!char.IsLetter(newValue[0]))
					{
						return false;
					}
					if (newValue.Any((char c5) => !char.IsLetterOrDigit(c5) && c5 != '_'))
					{
						return false;
					}
				}
				break;
			}
			return true;
		}

		private void cbRecord_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			if (text == "")
			{
				btnOK.IsEnabled = false;
			}
			else
			{
				btnOK.IsEnabled = true;
			}
			if (e.AddedItems.Count > 0)
			{
				string item = e.AddedItems[0] as string;
				int num = localizedOptionlist.IndexOf(item);
				if (num != -1)
				{
					recordType = option_list[num];
				}
				else
				{
					recordType = item;
				}
			}
		}

		private void tbText_PreviewTextInput(object sender, TextCompositionEventArgs e)
		{
			int caretIndex = tbText.CaretIndex;
			StringBuilder stringBuilder = new StringBuilder(tbText.Text);
			if (tbText.SelectedText.Trim().Length > 0)
			{
				stringBuilder.Replace(tbText.SelectedText, e.Text);
			}
			else
			{
				stringBuilder.Insert(caretIndex, e.Text);
			}
			if (stringBuilder.Length > tbTextLength || !ValidName(stringBuilder.ToString()))
			{
				e.Handled = true;
			}
		}

		private void tbText_PreviewKeyDown(object sender, KeyEventArgs e)
		{
			if (e.Key == Key.Space)
			{
				e.Handled = true;
			}
			else if (e.Key == Key.OemPeriod)
			{
				if (mask == maskType.IS_REAL && MaskingAndValidatingHelper.GetSystemDecimalSymbol() != ".")
				{
					e.Handled = true;
				}
			}
			else if (e.Key == Key.OemComma && mask == maskType.IS_REAL && MaskingAndValidatingHelper.GetSystemDecimalSymbol() != ",")
			{
				e.Handled = true;
			}
			if (e.Handled)
			{
				SystemSounds.Asterisk.Play();
			}
		}

		private void Paste_CanExecute(object sender, CanExecuteRoutedEventArgs e)
		{
			string text = ClipboardWrapper.GetText();
			e.CanExecute = text != null && ValidName(text);
			e.Handled = true;
		}

		private void Paste_Executed(object sender, ExecutedRoutedEventArgs e)
		{
			string text = ClipboardWrapper.GetText();
			if (text != null)
			{
				try
				{
					tbText.Text = ((text.Length > TbTextLength) ? text.Substring(0, TbTextLength) : text);
				}
				catch
				{
				}
			}
		}

