	public class MultiVisibilityAndConverter : IMultiValueConverter
	{
		public object Convert(object[] values, Type targetType, object parameter, CultureInfo culture)
		{
			if (values.Length != 0)
			{
				Visibility? visibility = null;
				for (int i = 0; i < values.Length; i++)
				{
					visibility = values[i] as Visibility?;
					if (!visibility.HasValue || visibility.Value != Visibility.Visible)
					{
						return Visibility.Collapsed;
					}
				}
			}
			return Visibility.Visible;
		}

		public object[] ConvertBack(object value, Type[] targetTypes, object parameter, CultureInfo culture)
		{
			throw new NotImplementedException();
		}
	}
	public class OneDialogInputDisplayCvt : IMultiValueConverter
	{
		private OneIdDialog dialog;

		public object Convert(object[] values, Type targetType, object parameter, CultureInfo culture)
		{
			if (values.Length != 2 || !(values[0] is string) || !(values[1] is OneIdDialog) || values[0] == null)
			{
				return values[0];
			}
			dialog = values[1] as OneIdDialog;
			if (dialog.mask == OneIdDialog.maskType.IS_REAL)
			{
				return values[0].ToString().Replace(".", MaskingAndValidatingHelper.GetSystemDecimalSymbol());
			}
			return values[0];
		}

		public object[] ConvertBack(object value, Type[] targetTypes, object parameter, CultureInfo culture)
		{
			object[] array = new object[2] { null, null };
			if (dialog != null && dialog.mask == OneIdDialog.maskType.IS_REAL && value != null)
			{
				array[0] = value.ToString().Replace(MaskingAndValidatingHelper.GetSystemDecimalSymbol(), ".");
			}
			else
			{
				array[0] = value;
			}
			return array;
		}
	}
