	public class OppositeVisibilityConverter : IValueConverter
	{
		public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
		{
			if (value != null)
			{
				if ((Visibility)value == Visibility.Visible)
				{
					return Visibility.Collapsed;
				}
				return Visibility.Visible;
			}
			return Visibility.Collapsed;
		}

		public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
		{
			throw new NotImplementedException();
		}
	}
	public class EngineValueToDisplayValueConverter : IValueConverter
	{
		public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
		{
			if (value != null)
			{
				double? num = CxsConverter.ValueToDouble(value);
				if (num.HasValue && Math.Abs(num.Value) < 1E-12)
				{
					return 0.0;
				}
				if (num == 1E+35)
				{
					return null;
				}
			}
			return value;
		}

		public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
		{
			throw new NotImplementedException();
		}
	}
