	public class ObjectDeletedAnywhereEventArgs : EventArgs
	{
		public string DeletedObjectPath { get; }

		public ObjectDeletedAnywhereEventArgs(string objectPath)
		{
			if (string.IsNullOrWhiteSpace(objectPath))
			{
				throw new ArgumentNullException("objectPath");
			}
			DeletedObjectPath = ObjectRenamedAnywhereEventArgs.UnifyCxsPath(objectPath);
		}

		public ObjectDeletedAnywhereEventArgs(string parentPath, string objectId)
		{
			if (string.IsNullOrWhiteSpace(parentPath))
			{
				throw new ArgumentNullException("parentPath");
			}
			if (string.IsNullOrWhiteSpace(objectId))
			{
				throw new ArgumentNullException("objectId");
			}
			DeletedObjectPath = ObjectRenamedAnywhereEventArgs.UnifyCxsPath(parentPath) + "." + objectId;
		}

		public ObjectDeletedAnywhereEventArgs(string parentPath, int objectLocation)
		{
			if (string.IsNullOrWhiteSpace(parentPath))
			{
				throw new ArgumentNullException("parentPath");
			}
			DeletedObjectPath = $"{ObjectRenamedAnywhereEventArgs.UnifyCxsPath(parentPath)}.#{objectLocation}";
		}

		public override bool Equals(object obj)
		{
			if (obj is ObjectDeletedAnywhereEventArgs e)
			{
				if (this == e)
				{
					return true;
				}
				return string.Equals(DeletedObjectPath, e.DeletedObjectPath, StringComparison.InvariantCultureIgnoreCase);
			}
			return base.Equals(obj);
		}

		public override int GetHashCode()
		{
			if (DeletedObjectPath != null)
			{
				return DeletedObjectPath.GetHashCode();
			}
			return base.GetHashCode();
		}

		public static string GetRealRemovedObjectPath(string testPath)
		{
			string text = ObjectRenamedAnywhereEventArgs.UnifyCxsPath(testPath);
			int num = text.LastIndexOf(".Data.", StringComparison.CurrentCultureIgnoreCase);
			if (num < 0)
			{
				return text;
			}
			int num2 = text.IndexOf('.', num + 6);
			if (num2 < 0)
			{
				return text;
			}
			int num3 = text.IndexOf('.', num2 + 1);
			if (num3 < 0)
			{
				return text;
			}
			return text.Substring(0, num3);
		}

		public string GetFullCxsPath()
		{
			return "Top.appModelV8." + DeletedObjectPath;
		}

		public bool IsCxsPathImpacted(string testPath)
		{
			if (!string.IsNullOrEmpty(testPath))
			{
				string text = ObjectRenamedAnywhereEventArgs.UnifyCxsPath(testPath);
				if (!string.IsNullOrEmpty(text))
				{
					if (string.Equals(text, DeletedObjectPath, StringComparison.CurrentCultureIgnoreCase))
					{
						return true;
					}
					if (text.StartsWith(DeletedObjectPath + ".", StringComparison.CurrentCultureIgnoreCase))
					{
						return true;
					}
				}
			}
			return false;
		}
	}
	public class ObjectDeletedAnywhereEvent : DispathcerPublishedRoutedCompositePresentationEvent<ObjectDeletedAnywhereEventArgs>
	{
		protected override bool ShouldCancelEvent(ObjectDeletedAnywhereEventArgs args)
		{
			if (base.EventAggregator is RoutingEventAggregator routingEventAggregator)
			{
				CxsCase cxsCase = UnityContainerHelper.TryResolve<CxsCase>(routingEventAggregator.Container);
				if (cxsCase != null)
				{
					try
					{
						string text = args.GetFullCxsPath();
						object obj = cxsCase.InvokeAction("Top.appModelV8.Custom Actions", "HappNode", text);
						if (obj != null && obj != DBNull.Value)
						{
							return true;
						}
						do
						{
							text = CxsPath.ParentPath(text);
							obj = cxsCase.InvokeAction("Top.appModelV8.Custom Actions", "HappNode", text);
							if (obj == null || obj == DBNull.Value)
							{
								return true;
							}
						}
						while (!string.IsNullOrEmpty(text));
					}
					catch (Exception)
					{
						return false;
					}
				}
			}
			return base.ShouldCancelEvent(args);
		}
	}
