	public enum DisplayFormMode
	{
		FormModal = 0,
		AppModal = 1,
		NonModal = 2,
		TabSheet = 3,
		FormModalTabbed = 4,
		AppModalTabbed = 5,
		NonModalTabbed = 6,
		AnalysisResult = 33
	}
	public class DisplayFormEventArgs : EventArgs
	{
		private bool _IsRunInModalMode = true;

		public short LegacyFlags
		{
			get
			{
				short num = 0;
				switch (DisplayMode)
				{
				case DisplayFormMode.FormModal:
					num = 0;
					break;
				case DisplayFormMode.AppModal:
					num = 1;
					break;
				case DisplayFormMode.NonModal:
					num = 2;
					break;
				case DisplayFormMode.TabSheet:
					num = 3;
					break;
				case DisplayFormMode.FormModalTabbed:
					num = 4;
					break;
				case DisplayFormMode.AppModalTabbed:
					num = 5;
					break;
				case DisplayFormMode.AnalysisResult:
					num = 21;
					break;
				}
				if (DisplayMode != DisplayFormMode.AnalysisResult && IsSingleton)
				{
					num |= 0x10;
				}
				if (ShowPrompts)
				{
					num |= 8;
				}
				if (IsIndirectModal)
				{
					num |= 0x20;
				}
				return num;
			}
			set
			{
				if ((value & 0x10) != 0 && value != 21)
				{
					IsSingleton = true;
					value &= -17;
				}
				if ((value & 8) != 0)
				{
					ShowPrompts = true;
					value &= -9;
				}
				if ((value & 0x20) != 0)
				{
					IsIndirectModal = true;
					value &= -33;
				}
				switch (value)
				{
				case 0:
					DisplayMode = DisplayFormMode.FormModal;
					break;
				case 1:
					DisplayMode = DisplayFormMode.AppModal;
					break;
				case 2:
					DisplayMode = DisplayFormMode.NonModal;
					break;
				case 3:
					DisplayMode = DisplayFormMode.TabSheet;
					break;
				case 4:
					DisplayMode = DisplayFormMode.FormModalTabbed;
					break;
				case 6:
					DisplayMode = DisplayFormMode.AppModalTabbed;
					break;
				case 21:
					DisplayMode = DisplayFormMode.AnalysisResult;
					break;
				}
			}
		}

		public DisplayFormMode DisplayMode { get; set; }

		public bool IsSingleton { get; set; }

		public bool ShowPrompts { get; set; }

		public bool IsIndirectModal { get; set; }

		public Type FormType { get; set; }

		public string FormProgId { get; set; }

		public string ShortName { get; set; }

		public int? PreferredWidth { get; set; }

		public int? PreferredHeight { get; set; }

		public Dictionary<string, object> Parameters { get; private set; }

		public string[] CompleteDataPaths { get; set; }

		public string HelpFile { get; set; }

		public int? HelpId { get; set; }

		public bool? IsNested { get; set; }

		public bool IsRunInModalMode
		{
			get
			{
				return _IsRunInModalMode;
			}
			set
			{
				if (value != _IsRunInModalMode)
				{
					_IsRunInModalMode = value;
				}
			}
		}

		public ResizeMode ResizeMode { get; set; }

		public bool HideCloseButton { get; set; }

		public DisplayFormEventArgs()
		{
			DisplayMode = DisplayFormMode.FormModal;
			Parameters = new Dictionary<string, object>();
		}
	}
