	public class ObjectRenamedAnywhereEventArgs : EventArgs
	{
		public string OldPath { get; }

		public string NewPath { get; }

		public string OldName { get; }

		public string NewName { get; }

		private ObjectRenamedAnywhereEventArgs(string oldPath, string newPath, string oldName, string newName)
		{
			OldPath = oldPath ?? throw new ArgumentNullException("oldPath");
			NewPath = newPath ?? throw new ArgumentNullException("newPath");
			OldName = oldName ?? throw new ArgumentNullException("oldName");
			NewName = newName ?? throw new ArgumentNullException("newName");
		}

		public override bool Equals(object obj)
		{
			if (obj is ObjectRenamedAnywhereEventArgs e)
			{
				if (this == e)
				{
					return true;
				}
				if (OldPath == e.OldPath && NewPath == e.NewPath && OldName == e.OldName)
				{
					return NewName == e.NewName;
				}
				return false;
			}
			return base.Equals(obj);
		}

		public override int GetHashCode()
		{
			if (OldPath != null && NewPath != null && OldName != null && NewName != null)
			{
				return OldPath.GetHashCode() ^ NewPath.GetHashCode() ^ OldName.GetHashCode() ^ NewName.GetHashCode();
			}
			return base.GetHashCode();
		}

		public bool IsCxsPathImpacted(string testPath)
		{
			if (!string.IsNullOrEmpty(testPath))
			{
				string text = UnifyCxsPath(testPath);
				if (!string.IsNullOrEmpty(text))
				{
					if (string.Equals(text, OldPath, StringComparison.CurrentCultureIgnoreCase))
					{
						return true;
					}
					if (text.StartsWith(OldPath + ".", StringComparison.CurrentCultureIgnoreCase))
					{
						return true;
					}
				}
			}
			return false;
		}

		public string GetNewPathAfterRenamed(string testPath)
		{
			if (!string.IsNullOrEmpty(testPath))
			{
				string text = UnifyCxsPath(testPath);
				if (!string.IsNullOrEmpty(text))
				{
					if (string.Equals(text, OldPath, StringComparison.CurrentCultureIgnoreCase))
					{
						return MakeNewPath(testPath, NewPath);
					}
					if (text.StartsWith(OldPath + ".", StringComparison.CurrentCultureIgnoreCase))
					{
						string newSegment = NewPath + text.Substring(OldPath.Length);
						return MakeNewPath(testPath, newSegment);
					}
				}
			}
			return testPath;
			static string MakeNewPath(string originalPath, string text2)
			{
				if (originalPath.StartsWith("Top.appModelV8.", StringComparison.CurrentCultureIgnoreCase))
				{
					return "Top.appModelV8." + text2;
				}
				if (originalPath.StartsWith("Top.appModel.", StringComparison.CurrentCultureIgnoreCase))
				{
					return "Top.appModel." + text2;
				}
				return text2;
			}
		}

		public static ObjectRenamedAnywhereEventArgs Create(string oldPath, string oldName, string newName)
		{
			if (oldPath == null)
			{
				throw new ArgumentNullException("oldPath");
			}
			if (oldName == null)
			{
				throw new ArgumentNullException("oldName");
			}
			if (newName == null)
			{
				throw new ArgumentNullException("newName");
			}
			if (oldPath.EndsWith("." + oldName))
			{
				string text = UnifyCxsPath(oldPath);
				string newPath = text.Substring(0, text.Length - oldName.Length) + newName;
				return new ObjectRenamedAnywhereEventArgs(text, newPath, oldName, newName);
			}
			return null;
		}

		public static ObjectRenamedAnywhereEventArgs Create(string oldPath, string newPath)
		{
			if (oldPath == null)
			{
				throw new ArgumentNullException("oldPath");
			}
			if (newPath == null)
			{
				throw new ArgumentNullException("newPath");
			}
			string[] array = UnifyCxsPath(oldPath).Split('.');
			string[] array2 = UnifyCxsPath(newPath).Split('.');
			if (array.Length == array2.Length)
			{
				string text = null;
				string text2 = null;
				StringBuilder stringBuilder = new StringBuilder();
				StringBuilder stringBuilder2 = new StringBuilder();
				for (int i = 0; i < array.Length; i++)
				{
					string text3 = array[i];
					string text4 = array2[i];
					stringBuilder.Append(text3).Append('.');
					stringBuilder2.Append(text4).Append('.');
					if (!string.Equals(text3, text4))
					{
						stringBuilder.Remove(stringBuilder.Length - 1, 1);
						stringBuilder2.Remove(stringBuilder2.Length - 1, 1);
						text = text3;
						text2 = text4;
						break;
					}
				}
				if (!string.IsNullOrWhiteSpace(text) && !string.IsNullOrWhiteSpace(text2))
				{
					return new ObjectRenamedAnywhereEventArgs(stringBuilder.ToString(), stringBuilder2.ToString(), text, text2);
				}
			}
			return null;
		}

		internal static string UnifyCxsPath(string path)
		{
			string text = path;
			if (path.StartsWith("Top.appModel.", StringComparison.CurrentCultureIgnoreCase))
			{
				text = text.Substring("Top.appModel.".Length);
			}
			if (path.StartsWith("Top.appModelV8.", StringComparison.CurrentCultureIgnoreCase))
			{
				text = text.Substring("Top.appModelV8.".Length);
			}
			if (text.Contains(".Data."))
			{
				return text;
			}
			if (text.Contains(".Blocks."))
			{
				return text.Replace(".Blocks.", ".Data.Blocks.");
			}
			if (!text.StartsWith("Blocks."))
			{
				text.StartsWith("Streams.");
			}
			return text;
		}
	}
	public class ObjectRenamedAnywhereEvent : DispathcerPublishedRoutedCompositePresentationEvent<ObjectRenamedAnywhereEventArgs>
	{
	}
	public abstract class DispathcerPublishedRoutedCompositePresentationEvent<TPayload> : RoutedCompositePresentationEvent<TPayload>
	{
		private readonly List<TPayload> _eventArgsList = new List<TPayload>();

		protected DispathcerPublishedRoutedCompositePresentationEvent()
		{
			base.RoutingStrategy = CompositeEventRoutingStrategy.AllTopDown;
		}

		public void DispatcherPublish(TPayload args)
		{
			lock (_eventArgsList)
			{
				if (!_eventArgsList.Contains(args))
				{
					_eventArgsList.Add(args);
				}
			}
			Dispatcher.CurrentDispatcher.BeginInvokeOnce(FlushEvents, DispatcherPriority.Loaded);
		}

		protected virtual bool ShouldCancelEvent(TPayload args)
		{
			if (args == null)
			{
				return true;
			}
			return false;
		}

		private void FlushEvents()
		{
			List<TPayload> list = new List<TPayload>();
			lock (_eventArgsList)
			{
				foreach (TPayload eventArgs in _eventArgsList)
				{
					if (!ShouldCancelEvent(eventArgs))
					{
						list.Add(eventArgs);
					}
				}
				_eventArgsList.Clear();
			}
			foreach (TPayload item in list)
			{
				Publish(item);
			}
		}
	}
}
namespace AspenTech.AspenPlus.MMControls.Ads
{
	internal static class AdsDataGridClipboardHelper
	{
		private static void GetLabelOfNonHeaderOnlyFields(StringBuilder sb, IEnumerable<DataColumn> selectedFields, AdsDataGrid sa, GridControl gridControl)
		{
			if (sb == null || selectedFields == null || sa == null || gridControl.DataSource == null)
			{
				return;
			}
			List<DataColumn> list = selectedFields.ToList();
			ReadOnlyCollection<DataColumn> columns = gridControl.DataSource.Columns;
			for (int i = 0; i < list.Count; i++)
			{
				DataColumn dataColumn = list[i];
				if (i > 0)
				{
					int num = dataColumn.DisplayIndex - list[i - 1].DisplayIndex;
					for (int j = 0; j < num; j++)
					{
						if (j != 0)
						{
							int offsetColumnIndex = list[i - 1].DisplayIndex + j;
							DataColumn dataColumn2 = columns.FirstOrDefault((DataColumn p) => p.DisplayIndex == offsetColumnIndex);
							if (dataColumn2 != null && dataColumn2.Visibility != Visibility.Visible)
							{
								continue;
							}
						}
						sb.Append("\t");
					}
				}
				string value = "\"" + dataColumn.Header + "\"";
				sb.Append(value);
			}
			List<string> list2 = new List<string>();
			bool flag = false;
			for (int num2 = 0; num2 < list.Count; num2++)
			{
				DataColumn dataColumn3 = list[num2];
				AdsField adsField = dataColumn3.Tag as AdsField;
				if (num2 > 0)
				{
					int num3 = dataColumn3.DisplayIndex - list[num2 - 1].DisplayIndex;
					for (int num4 = 0; num4 < num3; num4++)
					{
						if (num4 != 0)
						{
							int offsetColumnIndex2 = list[num2 - 1].DisplayIndex + num4;
							DataColumn dataColumn4 = columns.FirstOrDefault((DataColumn p) => p.DisplayIndex == offsetColumnIndex2);
							if (dataColumn4 != null && dataColumn4.Visibility != Visibility.Visible)
							{
								continue;
							}
						}
						list2.Add("\t");
					}
				}
				if (adsField.CurrentHeaderUnits != null && (!sa.AutoFillUnitsInColumnHeader || !string.IsNullOrEmpty(adsField.Label)))
				{
					list2.Add(adsField.CurrentHeaderUnits);
					flag = true;
				}
				else
				{
					list2.Add("");
				}
			}
			if (flag && list2.Count > 0)
			{
				string value2 = string.Join("", list2.ToArray());
				sb.AppendLine();
				sb.Append(value2);
			}
			sb.AppendLine();
		}

		internal static void DoDataCopy(AdsDataGrid adg, GridControlCopyEventArgs e)
		{
			if (adg.AdbTopProvider != null && adg.ContainerViewModel != null && adg.InternalGridControl != null && adg.IsLoaded)
			{
				StringBuilder stringBuilder = new StringBuilder();
				string text = null;
				if (e.GridControl.SelectedColumns.FirstOrDefault() != null)
				{
					e.GridControl.ClipboardCopyMode = GridControlClipboardCopyMode.ExcludeHeader;
					text = e.GenerateTextToCopy();
					GetLabelOfNonHeaderOnlyFields(stringBuilder, e.GridControl.SelectedColumns, adg, e.GridControl);
				}
				if (text != null)
				{
					stringBuilder.Append(text);
				}
				else
				{
					stringBuilder.Append(e.GenerateTextToCopy());
				}
				string text2 = stringBuilder.ToString();
				string caseFullFileName = adg.ContainerViewModel.ResolveViewPropertyPath("ResolvedCxsProvider.Case.CaseFullFilePath") as string;
				string applicationName = adg.ContainerViewModel.ResolveViewPropertyPath("ResolvedCxsProvider.Case.ApplicationName") as string;
				e.ClipboardContents.Add(DataFormats.Text, text2);
				e.ClipboardContents.Add("CSV", ConvertToStream(GenerateCsvFormatContent(text2)));
				e.ClipboardContents.Add("DatagridMetadata", ConvertToStream(GenerateDatagridMetadataFormatContent(adg, e)));
				e.ClipboardContents.Add("ASI Format", ConvertToStream(GenerateAsiFormatContent(adg, e.ResolvedIncludeHeader, caseFullFileName, applicationName)));
				e.ClipboardContents.Add("ASI File Format", ConvertToStream(GenerateAsiFileFormatContent(caseFullFileName, applicationName)));
				e.Handled = true;
			}
		}

		internal static void DoDataDrag(AdsDataGrid adg, GridControlDataDraggingEventArgs e)
		{
			if (adg.AdbTopProvider != null && adg.ContainerViewModel != null && adg.InternalGridControl != null && adg.IsLoaded && adg.InternalGridControl.DataSource != null && adg.InternalGridControl.HasSelection && adg.ContainerViewModel.UnityContainer != null)
			{
				string data = e.GenerateTextToCopy();
				e.DataObject.SetData(DataFormats.Text, data);
				string caseFullFileName = adg.ContainerViewModel.ResolveViewPropertyPath("ResolvedCxsProvider.Case.CaseFullFilePath") as string;
				string applicationName = adg.ContainerViewModel.ResolveViewPropertyPath("ResolvedCxsProvider.Case.ApplicationName") as string;
				string data2 = GenerateAsiFormatContent(adg, includesHeader: false, caseFullFileName, applicationName);
				e.DataObject.SetData(DataFormats.GetDataFormat("ASI Format").Name, data2);
			}
		}

		private static string GenerateAsiFormatContent(AdsDataGrid adg, bool includesHeader, string caseFullFileName, string applicationName)
		{
			return ClipboardHelper.GetAsiSelectionGridXml(CreateCellDataPackage(adg, includesHeader), caseFullFileName, applicationName);
		}

		private static string GenerateAsiFileFormatContent(string caseFullFileName, string applicationName)
		{
			XElement xElement = new XElement("SelectionFile");
			if (!string.IsNullOrEmpty(caseFullFileName))
			{
				xElement.Add(new XElement("FileMoniker", caseFullFileName));
			}
			if (!string.IsNullOrEmpty(applicationName))
			{
				xElement.Add(new XElement("Product", applicationName));
			}
			return xElement.ToString();
		}

		private static string GenerateCsvFormatContent(string text)
		{
			return text.Replace('\t', ',');
		}

		private static string GenerateDatagridMetadataFormatContent(AdsDataGrid adg, GridControlCopyEventArgs e)
		{
			if (e.ResolvedIncludeHeader)
			{
				return "ColumnHeaderLineCount=1";
			}
			return " ";
		}

		private static List<IGridCellData> CreateCellDataPackage(AdsDataGrid adg, bool includesHeader)
		{
			List<IGridCellData> list = new List<IGridCellData>();
			int num = -1;
			int num2 = -1;
			List<int> list2 = new List<int>();
			if (adg.InternalGridControl != null && adg.InternalGridControl.DataGridControlInstance != null && adg.InternalGridControl.DataGridControlInstance.Columns != null)
			{
				foreach (DataGridColumn column in adg.InternalGridControl.DataGridControlInstance.Columns)
				{
					if (column.Visibility != Visibility.Visible)
					{
						list2.Add(column.DisplayIndex);
					}
				}
			}
			if (includesHeader)
			{
				foreach (DataColumn selectedColumn in adg.InternalGridControl.SelectedColumns)
				{
					int displayIndex = selectedColumn.DisplayIndex;
					int num3 = 0;
					foreach (int item3 in list2)
					{
						if (item3 < displayIndex)
						{
							num3++;
						}
					}
					displayIndex -= num3;
					string empty = string.Empty;
					empty = ((!(selectedColumn.Tag is AdsField adsField)) ? selectedColumn.Header : (adsField.Label + Environment.NewLine + adsField.CurrentHeaderUnits));
					CxsGridCellData item = new CxsGridCellData
					{
						TextValue = empty,
						ColumnIndex = displayIndex,
						RowIndex = 0
					};
					list.Add(item);
					num = 0;
				}
			}
			foreach (DataCellInfo totalSelectedCell in adg.InternalGridControl.TotalSelectedCells)
			{
				int num4 = totalSelectedCell.Row.DataTable.Rows.IndexOf(totalSelectedCell.Row);
				if (includesHeader)
				{
					num4++;
				}
				int displayIndex2 = totalSelectedCell.Column.DisplayIndex;
				int num5 = 0;
				foreach (int item4 in list2)
				{
					if (item4 < displayIndex2)
					{
						num5++;
					}
				}
				displayIndex2 -= num5;
				if (num == -1 || num4 < num)
				{
					num = num4;
				}
				if (num2 == -1 || displayIndex2 < num2)
				{
					num2 = displayIndex2;
				}
				string cellCxsDataPath = adg.GetCellCxsDataPath(totalSelectedCell);
				if (!string.IsNullOrEmpty(cellCxsDataPath))
				{
					cellCxsDataPath = "cxs:" + cellCxsDataPath.Replace("Top.appModelV8", "Top.appModel");
					CxsGridCellData item2 = new CxsGridCellData
					{
						Moniker = cellCxsDataPath,
						RowIndex = num4,
						ColumnIndex = displayIndex2,
						TextValue = ((totalSelectedCell.Data != null) ? totalSelectedCell.Data.ToString() : string.Empty)
					};
					list.Add(item2);
				}
			}
			foreach (IGridCellData item5 in list)
			{
				item5.RowIndex -= num;
				item5.ColumnIndex -= num2;
			}
			return list;
		}

		private static MemoryStream ConvertToStream(string value)
		{
			return new MemoryStream(Encoding.UTF8.GetBytes(value));
		}
	}
	public class ArrayProfileAccessor
	{
		private Dictionary<string, string> VariableIDs;

		private IAccessor Accessor;

		private AccessorElement AccessorElement;

		private ICxvViewDataContainer CxvViewDataContainer;

		public ArrayProfileAccessor(IAdbTop adbTop, AccessorElement arrayProfileAccessor)
		{
			Initialize(adbTop);
			RefreshArrayProfileAccessor(arrayProfileAccessor);
		}

		public ArrayProfileAccessor(IAdbTop adbTop, ICxvViewDataContainer cxvViewDataContainer)
		{
			Initialize(adbTop);
			CxvViewDataContainer = cxvViewDataContainer;
			RefreshArrayProfileAccessor();
		}

		public int GetPhysicalType(int rowIndex, string variableName)
		{
			string partialPhysicalTypePath = GetPartialPhysicalTypePath(rowIndex, variableName);
			if (!string.IsNullOrEmpty(partialPhysicalTypePath))
			{
				int result = 0;
				AccessorElement accessorElement = Accessor.ObjectAtPath(AccessorElement, partialPhysicalTypePath);
				if (accessorElement.success)
				{
					int.TryParse(accessorElement.value.ToString(), out result);
				}
				return result;
			}
			return 0;
		}

		public AccessorElement GetValueAccessor(int rowIndex, string variableName)
		{
			string partialValuePath = GetPartialValuePath(rowIndex, variableName);
			if (!string.IsNullOrEmpty(partialValuePath))
			{
				return Accessor.ObjectAtPath(AccessorElement, partialValuePath);
			}
			return null;
		}

		public string GetFullValuePath(int rowIndex, string variableName)
		{
			string variableID = GetVariableID(rowIndex, variableName);
			if (!string.IsNullOrEmpty(variableID))
			{
				return $"@main.SharedData.VarListTimeProfile.ArrayProfile.#{rowIndex}.VariableValues.{variableID}";
			}
			return string.Empty;
		}

		public string GetFullPhysicalTypePath(int rowIndex, string variableName)
		{
			string variableID = GetVariableID(rowIndex, variableName);
			if (!string.IsNullOrEmpty(variableID))
			{
				return $"@main.SharedData.VarListTimeProfile.ArrayProfile.#{rowIndex}.VariablePTypes.{variableID}";
			}
			return string.Empty;
		}

		public string GetVariableID(int rowIndex, string variableName)
		{
			if (VariableIDs.ContainsKey(variableName))
			{
				string text = VariableIDs[variableName];
				string path = $"#{rowIndex}.VariableNames.{text}";
				AccessorElement accessorElement = Accessor.ObjectAtPath(AccessorElement, path);
				if (accessorElement != null && accessorElement.success && accessorElement.value.Equals(variableName))
				{
					return text;
				}
			}
			return FindVariableID(rowIndex, variableName);
		}

		public ICollection<string> GetAllVariableNames(int rowIndex = 1)
		{
			string path = $"#{rowIndex}.VariableNames";
			AccessorElement accessorElement = Accessor.ObjectAtPath(AccessorElement, path);
			if (accessorElement != null && accessorElement.success)
			{
				int num = Accessor.NumberOfChildren(accessorElement);
				if (num != VariableIDs.Count)
				{
					ClearDictionary();
					for (int i = 0; i < num; i++)
					{
						AccessorElement accessorElement2 = Accessor.ObjectAtPath(accessorElement, $"#{i}");
						VariableIDs[accessorElement2.value.ToString()] = accessorElement2.attribute;
					}
				}
				return VariableIDs.Keys;
			}
			return new Collection<string>();
		}

		public void RefreshArrayProfileAccessor()
		{
			if (CxvViewDataContainer == null)
			{
				throw new Exception("Can't use function RefreshArrayProfileAccessor parameterless if the class wasn't instantiated with a CxvViewDataContainer");
			}
			AccessorElement arrayProfileAccessor = CxvViewDataContainer.AdbGetElement("@main.SharedData.VarListTimeProfile.ArrayProfile");
			RefreshArrayProfileAccessor(arrayProfileAccessor);
		}

		public void RefreshArrayProfileAccessor(AccessorElement arrayProfileAccessor)
		{
			AccessorElement = arrayProfileAccessor;
		}

		public void ClearDictionary()
		{
			VariableIDs.Clear();
		}

		private void Initialize(IAdbTop adbTop)
		{
			VariableIDs = new Dictionary<string, string>();
			Accessor = new Accessor(adbTop);
		}

		private string FindVariableID(int rowIndex, string variableName)
		{
			string text = string.Empty;
			string path = $"#{rowIndex}.VariableNames";
			AccessorElement accessorElement = Accessor.ObjectAtPath(AccessorElement, path);
			int num = Accessor.NumberOfChildren(accessorElement);
			for (int i = 0; i < num; i++)
			{
				AccessorElement accessorElement2 = Accessor.ObjectAtPath(accessorElement, $"#{i}");
				if (accessorElement2.value.Equals(variableName))
				{
					text = accessorElement2.attribute;
					break;
				}
			}
			AddVariableIDToDict(variableName, text);
			return text;
		}

		private string GetPartialValuePath(int rowIndex, string variableName)
		{
			string variableID = GetVariableID(rowIndex, variableName);
			if (!string.IsNullOrEmpty(variableID))
			{
				return $"#{rowIndex}.VariableValues.{variableID}";
			}
			return string.Empty;
		}

		private string GetPartialPhysicalTypePath(int rowIndex, string variableName)
		{
			string variableID = GetVariableID(rowIndex, variableName);
			if (!string.IsNullOrEmpty(variableID))
			{
				return $"#{rowIndex}.VariablePTypes.{variableID}";
			}
			return string.Empty;
		}

		private void AddVariableIDToDict(string variableName, string variableID)
		{
			if (!string.IsNullOrEmpty(variableID))
			{
				if (VariableIDs.ContainsKey(variableName))
				{
					VariableIDs[variableName] = variableID;
				}
				else
				{
					VariableIDs.Add(variableName, variableID);
				}
			}
		}
	}
	public static class ViewDataContainerExtensions
	{
		public static AccessorElement AdbGetElement(this ICxvViewDataContainer vm, string path, IAdbTopProvider adbTopProvider = null)
		{
			if (!string.IsNullOrWhiteSpace(path) && vm.UnityContainer != null)
			{
				if (adbTopProvider == null)
				{
					adbTopProvider = CxvUnityContainerExtensions.TryResolve<IAdbTopProvider>(vm.UnityContainer);
				}
				if (adbTopProvider != null)
				{
					string text = FinalizeAdsPath(vm, path);
					if (!string.IsNullOrWhiteSpace(text))
					{
						return adbTopProvider.GetAccessorElement(text);
					}
				}
			}
			return null;
		}

		private static string FinalizeAdsPath(ICxvViewDataContainer vm, string path)
		{
			if (!string.IsNullOrWhiteSpace(path) && path.Contains(".SharedData."))
			{
				string text = vm.ExpandDataPath(path);
				if (!string.IsNullOrWhiteSpace(text))
				{
					return PathGenerator.convertCXSToADSPath(text);
				}
				return null;
			}
			return path;
		}
	}
	public static class PathGenerator
	{
		public static string GetAdsIndexerPath(IAdbTop top, CxvViewModel vm, string indexer)
		{
			if (top == null)
			{
				throw new ArgumentNullException("top");
			}
			if (vm == null)
			{
				throw new ArgumentNullException("vm");
			}
			if (string.IsNullOrEmpty(indexer))
			{
				throw new ArgumentException("value cannot be null or empty.", "indexer");
			}
			return convertCXSToADSPath(vm.ExpandDataPath(indexer));
		}

		public static string GetBlockPath(CxvViewModel vm)
		{
			if (vm == null)
			{
				throw new ArgumentNullException("vm");
			}
			string result = string.Empty;
			string text = vm.ExpandDataPath("@main");
			if (text != null)
			{
				int num = text.LastIndexOf(".Subobjects.");
				if (num >= 0)
				{
					text = text.Substring(0, num);
				}
				int num2 = text.IndexOf(".Blocks.");
				result = text.Substring(num2 + 1);
			}
			return result;
		}

		public static string convertCXSToADSPath(string cxsPath)
		{
			if (string.IsNullOrEmpty(cxsPath))
			{
				return null;
			}
			if (cxsPath.StartsWith("Top.AppModelv8.blocks.", StringComparison.InvariantCultureIgnoreCase))
			{
				return ("Flowsheet.Blocks." + cxsPath.Substring("Top.AppModelv8.blocks.".Length)).Replace(".SharedData.", ".").Replace(".Data.Blocks.", ".SubFlowsheets.Simulation.Blocks.").Replace(".Data.Controllers.", ".SubFlowsheets.Simulation.Controllers.");
			}
			if (cxsPath.StartsWith("Top.AppModelv8.Controllers.", StringComparison.InvariantCultureIgnoreCase))
			{
				return ("Flowsheet.Controllers." + cxsPath.Substring("Top.AppModelv8.Controllers.".Length)).Replace(".SharedData.", ".").Replace(".Data.Controllers.", ".SubFlowsheets.Simulation.Controllers.");
			}
			if (cxsPath.StartsWith("Top.appModelV8.SharedData.", StringComparison.InvariantCultureIgnoreCase))
			{
				return cxsPath.Substring("Top.appModelV8.SharedData.".Length);
			}
			if (cxsPath.StartsWith("Top.appModelV8.", StringComparison.InvariantCultureIgnoreCase))
			{
				return cxsPath.Substring("Top.appModelV8.".Length).Replace(".SharedData.", ".");
			}
			return cxsPath;
		}

		public static IEnumerable<string> ConvertAdsCxsPathCollection(IEnumerable<string> sAdsCollection)
		{
			foreach (string item in sAdsCollection)
			{
				yield return ConvertAdsCxsPath2AspenCxs(item);
			}
		}

		public static string ConvertAdsCxsPath2AspenCxs(string sAdsCxsPath)
		{
			if (string.IsNullOrEmpty(sAdsCxsPath))
			{
				return null;
			}
			if (!sAdsCxsPath.ToLower().Contains(".shareddata."))
			{
				return sAdsCxsPath;
			}
			string text = sAdsCxsPath;
			if (text.StartsWith("appModel.SharedData.Flowsheet.", StringComparison.InvariantCultureIgnoreCase))
			{
				text = text.Replace("appModel.SharedData.Flowsheet.", "Top.appModelV8.");
			}
			else if (sAdsCxsPath.StartsWith("cxs:Top.appModelV8.SharedData.Flowsheet.", StringComparison.InvariantCultureIgnoreCase))
			{
				text = text.Replace("cxs:Top.appModelV8.SharedData.Flowsheet.", "cxs:Top.appModelV8.");
			}
			else if (sAdsCxsPath.StartsWith("cxs:Top.appModel.SharedData.Flowsheet.", StringComparison.InvariantCultureIgnoreCase))
			{
				text = text.Replace("cxs:Top.appModel.SharedData.Flowsheet.", "cxs:Top.appModel.");
			}
			else
			{
				if (!sAdsCxsPath.StartsWith("cxs:appModel.SharedData.Flowsheet.", StringComparison.InvariantCultureIgnoreCase))
				{
					return sAdsCxsPath;
				}
				text = text.Replace("cxs:appModel.SharedData.Flowsheet.", "cxs:Top.appModelV8.");
			}
			text = text.Replace("SubFlowsheets.Simulation.", "Data.");
			int num = text.LastIndexOf(".Blocks.");
			if (num != -1)
			{
				string text2 = text.Substring(num + ".Blocks.".Length);
				int num2 = text2.IndexOf(".");
				if (num2 != -1)
				{
					text2 = text2.Insert(num2 + 1, "SharedData.");
				}
				text = text.Substring(0, num + ".Blocks.".Length) + text2;
			}
			else if (text.Contains(".Sensitivity") && text.Contains(".rows.") && text.Contains("values"))
			{
				text = text.Replace(".Sensitivity.", ".Model Analysis Tools.Sensitivity.").Replace(".rows.", ".Output.SENSVAR.").Replace(".values.", ".");
			}
			return text;
		}

		public static string SimplyConvertAdsPathToCxsPath(string adsPath)
		{
			if (!string.IsNullOrWhiteSpace(adsPath))
			{
				if (adsPath.StartsWith("appModel.SharedData.Flowsheet.", StringComparison.InvariantCultureIgnoreCase))
				{
					return adsPath.Replace("appModel.SharedData.Flowsheet.", "Top.appModelV8.SharedData.Flowsheet.");
				}
				if (adsPath.StartsWith("cxs:appModel.SharedData.Flowsheet.", StringComparison.InvariantCultureIgnoreCase))
				{
					return adsPath.Replace("cxs:appModel.SharedData.Flowsheet.", "cxs:Top.appModelV8.SharedData.Flowsheet.");
				}
			}
			return adsPath;
		}
	}
}
namespace AspenTech.AspenPlus.MMControls.Ads.ViewModelProperties
