	public class AdsChildCountIndexBasisData : CxvIndexBasisBaseData
	{
		private ICxvViewDataContainer _dataContainer;

		private AdsChildCountIndexBasis _indexBasis;

		private string[] _childIdsVector;

		private IAdbTopProvider _adbTopProvider;

		public override int Count
		{
			get
			{
				if (_childIdsVector == null)
				{
					return 0;
				}
				return _childIdsVector.Length;
			}
		}

		protected ICxvViewDataContainer DataContainer
		{
			get
			{
				return _dataContainer;
			}
			set
			{
				_dataContainer = value;
			}
		}

		public AdsChildCountIndexBasis IndexBasis
		{
			get
			{
				return _indexBasis;
			}
			set
			{
				_indexBasis = value;
			}
		}

		public string[] ChildIdsVector => _childIdsVector;

		public AdsChildCountIndexBasisData(AdsChildCountIndexBasis indexBasis, ICxvViewDataContainer dataContainer)
		{
			_indexBasis = indexBasis;
			_dataContainer = dataContainer;
			_adbTopProvider = CxvUnityContainerExtensions.TryResolve<IAdbTopProvider>(_dataContainer.UnityContainer);
			IEventAggregator eventAggregator = _dataContainer.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>());
			eventAggregator.GetEvent<UpdateDisplayEvent>().Subscribe(OnUpdateDisplayEvent);
			eventAggregator.GetEvent<AplusGlobalUnitSetChangedEvent>().Subscribe(OnAplusGlobalUnitSetChangedEvent);
			eventAggregator.GetEvent<AdsDataUpdatedEvent>().Subscribe(OnAdsDataUpdatedEvent);
			RefreshChildIds();
		}

		private void RefreshChildIds()
		{
			if (string.IsNullOrEmpty(_indexBasis.DataPath))
			{
				return;
			}
			AccessorElement accessorElement = _dataContainer.AdbGetElement(_indexBasis.DataPath);
			string[] array = new string[0];
			if (_adbTopProvider != null && accessorElement != null && accessorElement.success)
			{
				IEnumerable<AccessorElement> elementChildren = _adbTopProvider.GetElementChildren(accessorElement);
				if (elementChildren != null && elementChildren.Count() != 0)
				{
					if (_indexBasis.UseChildId)
					{
						array = elementChildren.Select((AccessorElement p) => p.GetName()).ToArray();
					}
					else
					{
						List<string> list = new List<string>();
						for (int num = 0; num < elementChildren.Count(); num++)
						{
							list.Add($"#{num}");
						}
						array = list.ToArray();
					}
				}
			}
			if (_childIdsVector == null || !array.SequenceEqual(_childIdsVector))
			{
				_childIdsVector = array;
				OnCountChanged();
			}
		}

		public override object GetIndexSubstitution(int index, CxvPropertyWatch dependencies)
		{
			if (_childIdsVector == null)
			{
				RefreshChildIds();
			}
			object obj = null;
			if (_indexBasis.UseChildId && _childIdsVector != null && index >= 0 && index < _childIdsVector.Length)
			{
				return _childIdsVector[index];
			}
			return "#" + index.ToString(CultureInfo.InvariantCulture);
		}

		private void OnUpdateDisplayEvent(UpdateDisplayEventArgs args)
		{
			RefreshChildIds();
		}

		private void OnAplusGlobalUnitSetChangedEvent(AplusGlobalUnitSetChangedEventArgs args)
		{
			RefreshChildIds();
		}

		private void OnAdsDataUpdatedEvent(AdsDataUpdatedEventArgs args)
		{
			RefreshChildIds();
		}
	}
	public class AdsChildCountIndexBasis : CxvIndexBasisBase
	{
		[DefaultValue(null)]
		public string DataPath { get; set; }

		[DefaultValue(false)]
		public bool UseChildId { get; set; }

		public override CxvIndexBasisBaseData CreateData(ICxvViewDataContainer dataContainer, CxvPropertyWatch dependencies)
		{
			return new AdsChildCountIndexBasisData(this, dataContainer);
		}
	}
	public class AdsVariableData : CxvPropertyData
	{
		private const double MinimumDoubleValue = 1E-12;

		private const double MaximumDoubleValue = 1E+35;

		private IEventAggregator _eventAggregator;

		private AdsVariableProperty _property;

		private ICxvViewDataContainer _dataContainer;

		private AccessorElement _adbElement;

		private AccessorElement _unitRowElement;

		private IAdbUnitsProvider _adbUnitsProvider;

		private object _rawValue;

		private int? _unitRow;

		private string _units;

		private ObservableCollection<string> _unitsOptions;

		public string DataPath => _dataContainer.ExpandDataPath(_property.DataPath);

		public object Value
		{
			get
			{
				if (_rawValue != null && _rawValue.GetType() == typeof(double))
				{
					if (!string.IsNullOrEmpty(Units) && UnitRow.HasValue && UnitRow.Value > 0)
					{
						return GetDoubleValueToDisplay(_adbUnitsProvider.ConvertFromSI(UnitRow, (double)_rawValue, Units));
					}
					return GetDoubleValueToDisplay((double)_rawValue);
				}
				return _rawValue;
			}
			set
			{
			}
		}

		public int? UnitRow
		{
			get
			{
				return _unitRow;
			}
			private set
			{
				_unitRow = value;
				OnPropertyChanged("UnitRow");
			}
		}

		public string Units
		{
			get
			{
				if (!string.IsNullOrEmpty(_property.SelectedUnitPropertyPath))
				{
					return CxsConverter.ValueToString(_dataContainer.ResolveViewPropertyPath(_property.SelectedUnitPropertyPath));
				}
				return _units;
			}
			set
			{
				if (_units != value)
				{
					_units = value;
					OnPropertyChanged("Units");
					OnPropertyChanged("Value");
					_eventAggregator.GetEvent<AdsUnitChangedEvent>().Publish(new AdsUnitChangedEventArgs(_dataContainer.ExpandDataPath(_property.DataPath), _units));
				}
			}
		}

		public ObservableCollection<string> UnitsOptions => _unitsOptions;

		public Type ValueType
		{
			get
			{
				if (_rawValue != null)
				{
					return _rawValue.GetType();
				}
				return typeof(string);
			}
		}

		public bool IsReadOnly => true;

		public bool? IsCalculated => true;

		public string CxsItemMoniker
		{
			get
			{
				if (_adbElement != null)
				{
					return CxvObservableObject.CxsPathToMoniker(_adbElement.cxsPath);
				}
				return null;
			}
		}

		public AdsVariableData(ICxvViewDataContainer dataContainer, AdsVariableProperty property)
			: base(dataContainer, property)
		{
			_dataContainer = dataContainer;
			_property = property;
			_adbUnitsProvider = CxvUnityContainerExtensions.TryResolve<IAdbUnitsProvider>(dataContainer.UnityContainer);
			_eventAggregator = _dataContainer.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>());
			_eventAggregator.GetEvent<UpdateDisplayEvent>().Subscribe(OnUpdateDisplayEvent);
			_eventAggregator.GetEvent<AplusGlobalUnitSetChangedEvent>().Subscribe(OnAplusGlobalUnitSetChangedEvent);
			_eventAggregator.GetEvent<AdsDataUpdatedEvent>().Subscribe(OnAdsDataUpdatedEvent);
			_eventAggregator.GetEvent<AdsUnitChangedEvent>().Subscribe(OnSelectedUnitChanged);
			_eventAggregator.GetEvent<AdsVariablePropertyChangedEvent>().Subscribe(AdsVariablePropertyChangedEvent);
			RefreshData();
		}

		private void RefreshAdbElement()
		{
			_adbElement = _dataContainer.AdbGetElement(_property.DataPath);
			if (!string.IsNullOrEmpty(_property.UnitRowPath))
			{
				_unitRowElement = _dataContainer.AdbGetElement(_property.UnitRowPath);
			}
		}

		private void OnUpdateDisplayEvent(UpdateDisplayEventArgs args)
		{
			RefreshData();
		}

		private void OnAplusGlobalUnitSetChangedEvent(AplusGlobalUnitSetChangedEventArgs args)
		{
			RefreshData();
		}

		private void OnAdsDataUpdatedEvent(AdsDataUpdatedEventArgs args)
		{
			RefreshData();
		}

		private void OnSelectedUnitChanged(AdsUnitChangedEventArgs e)
		{
			if (e.DataPath != _dataContainer.ExpandDataPath(_property.DataPath) && !string.IsNullOrEmpty(_property.SelectedUnitPropertyPath))
			{
				OnPropertyChanged("Value");
			}
		}

		private void AdsVariablePropertyChangedEvent(AdsVariablePropertyChangedEventArgs e)
		{
			RefreshData();
		}

		private double? GetDoubleValueToDisplay(double? dbValue)
		{
			if (dbValue.HasValue)
			{
				if (dbValue.Value >= 1E+35)
				{
					return null;
				}
				if (Math.Abs(dbValue.Value) < 1E-12)
				{
					return 0.0;
				}
			}
			return dbValue;
		}

		private void RefreshData()
		{
			RefreshAdbElement();
			RefreshUnitsOptions();
			RefreshUnits();
			RefreshValue();
		}

		private void RefreshUnitsOptions()
		{
			if (_adbElement == null || !_adbElement.success)
			{
				UnitRow = null;
				_unitsOptions = null;
				OnPropertyChanged("UnitsOptions");
				return;
			}
			if (_property.UnitRow.HasValue)
			{
				UnitRow = _property.UnitRow;
			}
			else if (_unitRowElement != null && _unitRowElement.success)
			{
				UnitRow = CxsConverter.ValueToInt32(_unitRowElement.value);
			}
			else if (!string.IsNullOrEmpty(_property.UnitRowPropertyPath))
			{
				UnitRow = CxsConverter.ValueToInt32(_dataContainer.ResolveViewPropertyPath(_property.UnitRowPropertyPath));
			}
			else
			{
				UnitRow = _adbElement.GetUnitRow();
			}
			IEnumerable<string> unitsList = _adbUnitsProvider.GetUnitsList(_unitRow);
			ObservableCollection<string> observableCollection = new ObservableCollection<string>();
			if (unitsList != null)
			{
				foreach (string item in unitsList)
				{
					observableCollection.Add(item);
				}
			}
			_unitsOptions = observableCollection;
			OnPropertyChanged("UnitsOptions");
		}

		private void RefreshUnits()
		{
			if (_adbElement == null || !_adbElement.success)
			{
				_units = null;
				OnPropertyChanged("Units");
			}
			else
			{
				_units = _adbUnitsProvider.GetDefaultDisplayUnits(UnitRow);
				OnPropertyChanged("Units");
			}
		}

		private void RefreshValue()
		{
			if (_adbElement == null || !_adbElement.success)
			{
				_rawValue = null;
				OnPropertyChanged("Value");
			}
