		private void RefreshItemsSource()
		{
			IEnumerable<string> source = GenerateItemsSource();
			List<string> list = null;
			list = ((SortingComparer == null) ? source.ToList() : source.OrderBy((string p) => p, SortingComparer).ToList());
			if (!(ItemsSource is List<string> first))
			{
				ItemsSource = list;
			}
			else if (!first.SequenceEqual(list))
			{
				ItemsSource = list;
			}
		}

		private void RefreshSelectedItem()
		{
			if (ItemsSource == null || !ItemsSource.Any())
			{
				SelectedItem = null;
			}
			else if (SelectedItem == null || !ItemsSource.Contains(SelectedItem))
			{
				if (DefaultSelectedItem != null && ItemsSource.Contains(DefaultSelectedItem))
				{
					SelectedItem = DefaultSelectedItem;
				}
				else
				{
					SelectedItem = ItemsSource.FirstOrDefault();
				}
			}
		}

		private void RefreshHasItem()
		{
			HasItem = ItemsSource != null && ItemsSource.Any();
		}

		private IEnumerable<string> GenerateItemsSource()
		{
			if (string.IsNullOrWhiteSpace(ItemsPath) || base.AdbTopProvider == null)
			{
				yield break;
			}
			string text = ItemsPath.Trim();
			int num = text.IndexOf(".#id");
			if (num <= 0)
			{
				yield break;
			}
			string path = text.Substring(0, num).Trim();
			string text2 = FinalizeAdsPath(path);
			if (string.IsNullOrWhiteSpace(text2))
			{
				yield break;
			}
			AccessorElement accessorElement = base.AdbTopProvider.GetAccessorElement(text2);
			if (!accessorElement.success)
			{
				yield break;
			}
			string segment2 = text.Substring(num + ".#id".Length).Trim();
			if (!string.IsNullOrEmpty(segment2))
			{
				segment2 = ((segment2.FirstOrDefault() != '.') ? null : segment2.Substring(1));
			}
			bool isSegment2Empty = string.IsNullOrWhiteSpace(segment2);
			foreach (AccessorElement elementChild in base.AdbTopProvider.GetElementChildren(accessorElement))
			{
				if (isSegment2Empty)
				{
					string name = elementChild.GetName();
					if (!string.IsNullOrEmpty(name))
					{
						yield return name;
					}
				}
				else
				{
					string name2 = base.AdbTopProvider.GetAccessorElement(elementChild, segment2).GetName();
					if (!string.IsNullOrEmpty(name2))
					{
						yield return name2;
					}
				}
			}
		}
	}
