		public string FinalizeAdsPath(string path)
		{
			if (!string.IsNullOrWhiteSpace(path) && path.Contains(".SharedData."))
			{
				CxvViewModel hostViewModel = GetHostViewModel();
				if (hostViewModel != null)
				{
					string text = hostViewModel.ExpandDataPath(path);
					if (!string.IsNullOrWhiteSpace(text))
					{
						return PathGenerator.convertCXSToADSPath(text);
					}
				}
				return null;
			}
			return path;
		}

		private void SubscribeEvents(IUnityContainer container)
		{
			if (container != null)
			{
				IEventAggregator eventAggregator = container.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>());
				eventAggregator.GetEvent<UpdateDisplayEvent>().Subscribe(OnUpdateDisplayEvent);
				eventAggregator.GetEvent<AplusGlobalUnitSetChangedEvent>().Subscribe(OnAplusGlobalUnitSetChangedEvent);
				eventAggregator.GetEvent<AdsDataUpdatedEvent>().Subscribe(OnAdsDataUpdatedEvent);
			}
		}

		private void UnsubscribeEvents(IUnityContainer container)
		{
			if (container != null)
			{
				IEventAggregator eventAggregator = container.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>());
				eventAggregator.GetEvent<UpdateDisplayEvent>().Unsubscribe(OnUpdateDisplayEvent);
				eventAggregator.GetEvent<AplusGlobalUnitSetChangedEvent>().Unsubscribe(OnAplusGlobalUnitSetChangedEvent);
				eventAggregator.GetEvent<AdsDataUpdatedEvent>().Unsubscribe(OnAdsDataUpdatedEvent);
			}
		}

