	public abstract class AdsValueControl : AdsControlBase
	{
		private static class DragDropHelper
		{
			private static AdsValueControl _mouseDownControl;

			private static System.Windows.Point _mouseDownPoint;

			private static bool _isMouseMovedFlg;

			public static void DoMouseDown(AdsValueControl control, MouseButtonEventArgs args)
			{
				_mouseDownControl = control;
				_mouseDownPoint = args.GetPosition(control);
				_isMouseMovedFlg = false;
			}

			public static void DoMouseMove(AdsValueControl control, MouseEventArgs args)
			{
				if (Mouse.LeftButton != MouseButtonState.Pressed || control == null || _mouseDownControl != control || args.Handled || _isMouseMovedFlg)
				{
					return;
				}
				Vector vector = args.GetPosition(control) - _mouseDownPoint;
				if (!(Math.Abs(vector.X) > SystemParameters.MinimumHorizontalDragDistance) && !(Math.Abs(vector.Y) > SystemParameters.MinimumVerticalDragDistance))
				{
					return;
				}
				try
				{
					IDataObject dataObject = AdsControlClipboardHelper.CreateCopyDataObject(control);
					if (dataObject != null)
					{
						args.Handled = true;
						_isMouseMovedFlg = true;
						DragDrop.DoDragDrop(control, dataObject, DragDropEffects.Copy);
						_mouseDownControl = null;
					}
				}
				catch (Exception)
				{
				}
			}

			public static void DoMouseUp(AdsValueControl control, MouseButtonEventArgs args)
			{
				if (_mouseDownControl != null)
				{
					_mouseDownControl = null;
				}
				_isMouseMovedFlg = false;
			}
		}

		private static class AdsControlClipboardHelper
		{
			public static void CopyCommand_Executed(object sender, ExecutedRoutedEventArgs e)
			{
				IDataObject dataObject = CreateCopyDataObject(sender as AdsValueControl);
				if (dataObject != null)
				{
					ClipboardWrapper.SetDataObject(dataObject, copy: true);
				}
			}

			public static void CopyCommand_CanExecute(object sender, CanExecuteRoutedEventArgs e)
			{
				AdsValueControl adsValueControl = sender as AdsValueControl;
				e.CanExecute = adsValueControl.AdbElement != null && adsValueControl.AdbElement.success;
			}

			public static IDataObject CreateCopyDataObject(AdsValueControl control)
			{
				if (control.AdbElement == null || !control.AdbElement.success)
				{
					return null;
				}
				string text = null;
				string applicationName = null;
				CxvViewModel hostViewModel = control.GetHostViewModel();
				if (hostViewModel != null && hostViewModel.ResolvedCxsProvider != null && hostViewModel.ResolvedCxsProvider.Case != null)
				{
					text = hostViewModel.ResolvedCxsProvider.Case.CaseFullFilePath;
					applicationName = hostViewModel.ResolvedCxsProvider.Case.ApplicationName;
				}
				DataObject dataObject = new DataObject();
				dataObject.SetData(DataFormats.Text, CreateTextToCopy(control));
				if (!string.IsNullOrWhiteSpace(text))
				{
					MemoryStream asiFileXml = ClipboardHelper.GetAsiFileXml(text, applicationName);
					if (asiFileXml != null)
					{
						dataObject.SetData(DataFormats.GetDataFormat("ASI File Format").Name, asiFileXml);
					}
					string text2 = CreateAsiFormatPackage(control, text, applicationName);
					if (text2 != null)
					{
						dataObject.SetData(DataFormats.GetDataFormat("ASI Format").Name, text2);
					}
				}
				return dataObject;
			}

			private static string CreateTextToCopy(AdsValueControl control)
			{
				if (control.Value == null)
				{
					return string.Empty;
				}
				if (control.IsDoubleValue)
				{
					return control.DoubleValueAtDisplayUnit.ToString();
				}
				return control.Value.ToString();
			}

			private static string CreateAsiFormatPackage(AdsValueControl control, string filePath, string applicationName)
			{
				string text = control.AdbElement.GetFullCxsPath()?.Replace(".appModelV8.", ".appModel.");
				if (!string.IsNullOrWhiteSpace(text))
				{
					return ClipboardHelper.GetAsiSelectionXml(new List<string> { text }, filePath, applicationName);
				}
				return null;
			}
		}

