		private void RefreshAdbElement()
		{
			IAdbTopProvider adbTopProvider = base.AdbTopProvider;
			if (adbTopProvider == null || string.IsNullOrWhiteSpace(ValuePath))
			{
				AdbElement = null;
				return;
			}
			string text = FinalizeAdsPath(ValuePath);
			if (!string.IsNullOrWhiteSpace(text))
			{
				AdbElement = adbTopProvider.GetAccessorElement(text);
			}
			else
			{
				AdbElement = null;
			}
		}

		private void RefreshConcreteValues()
		{
			Type type = null;
			if (AdbElement != null)
			{
				type = AdbElement.GetValueType();
			}
			if (type != null)
			{
				IsStringValue = type == typeof(string);
				IsDoubleValue = type == typeof(double) || type == typeof(double?);
				IsIntegerValue = type == typeof(int) || type == typeof(int?);
				IsBooleanValue = type == typeof(bool) || type == typeof(bool?);
				if (IsStringValue)
				{
					StringValue = AdbElement.GetStringValue();
					DoubleValue = null;
					IntegerValue = null;
					BooleanValue = null;
				}
				else if (IsDoubleValue)
				{
					StringValue = null;
					DoubleValue = FixAdsDoubleValue(AdbElement.GetDoubleValue());
					IntegerValue = null;
					BooleanValue = null;
				}
				else if (IsIntegerValue)
				{
					StringValue = null;
					DoubleValue = null;
					IntegerValue = AdbElement.GetIntegerValue();
					BooleanValue = null;
				}
				else if (IsBooleanValue)
				{
					StringValue = null;
					DoubleValue = null;
					IntegerValue = null;
					BooleanValue = AdbElement.GetBooleanValue();
				}
			}
			else
			{
				bool flag = (IsIntegerValue = false);
				bool flag3 = (IsDoubleValue = flag);
				bool isBooleanValue = (IsStringValue = flag3);
				IsBooleanValue = isBooleanValue;
				StringValue = null;
				DoubleValue = null;
				IntegerValue = null;
				BooleanValue = null;
			}
		}

