		{
			AdsValueControl obj = d as AdsValueControl;
			obj.RefreshResolvedUnitRow();
			obj.RefreshConcreteValues();
			obj.RefreshValue();
			obj.OnAdbElementChanged((AccessorElement)e.OldValue, (AccessorElement)e.NewValue);
		}

