		private string GetFinalDisplayUnit()
		{
			if (!string.IsNullOrWhiteSpace(DisplayUnit))
			{
				return DisplayUnit;
			}
			if (ResolvedUnitRow != 0 && base.AdbUnitsProvider != null)
			{
