		private double? CalcualteDoubleValueAtDisplayUnit()
		{
			if (!DoubleValue.HasValue)
			{
				return null;
			}
			if (base.AdbUnitsProvider == null || ResolvedUnitRow == 0 || string.IsNullOrWhiteSpace(ResolvedDisplayUnit))
			{
				return DoubleValue;
			}
			return base.AdbUnitsProvider.ConvertFromSI(ResolvedUnitRow, DoubleValue.Value, ResolvedDisplayUnit);
		}

