		protected override void OnContextMenuOpening(ContextMenuEventArgs e)
		{
			if (base.ContextMenu == null && !SuppressDefaultContextMenu)
			{
				e.Handled = HandleDefaultContextMenuOpening();
			}
			base.OnContextMenuOpening(e);
		}

		protected virtual void OnDefaultContextMenuOpening(RoutedEventArgs<ContextMenu> e)
		{
		}

		private bool HandleDefaultContextMenuOpening()
		{
			ContextMenu contextMenu = new ContextMenu
			{
				PlacementTarget = this
			};
			contextMenu.Items.Add(new MenuItem
			{
				Icon = new System.Windows.Controls.Image
				{
					Source = ImageSourceHelper.Copy16
				},
				Command = ApplicationCommands.Copy,
				CommandTarget = this
			});
			RoutedEventArgs<ContextMenu> e = new RoutedEventArgs<ContextMenu>(contextMenu, DefaultContextMenuOpeningEvent, this);
			RaiseEvent(e);
			if (!e.Handled)
			{
				OnDefaultContextMenuOpening(e);
				if (!e.Handled && contextMenu.HasItems)
				{
					contextMenu.IsOpen = true;
					return true;
				}
			}
			return false;
		}

		public static double? FixAdsDoubleValue(double? value)
		{
			if (value.HasValue)
			{
				if (value.Value >= 1E+35)
				{
					return null;
				}
				if (Math.Abs(value.Value) < 1E-12)
				{
					return 0.0;
				}
				return value.Value;
			}
			return null;
		}
	}
