		{
			RefreshText();
			RefreshResolvedTextAlignment();
			base.OnValueChanged(oldValue, newValue);
		}

		protected override void OnDoubleValueAtDisplayUnitChanged(double? oldValue, double? newValue)
		{
			RefreshText();
			base.OnDoubleValueAtDisplayUnitChanged(oldValue, newValue);
		}

		protected void RefreshText()
		{
			Text = ResolveFinalTextToDisplay();
		}

		protected virtual string ResolveFinalTextToDisplay()
		{
			if (base.IsBooleanValue)
			{
				return base.BooleanValue.ToString();
			}
			if (base.IsDoubleValue)
			{
				double? doubleValueToDisplay = GetDoubleValueToDisplay();
				if (doubleValueToDisplay.HasValue)
				{
					return doubleValueToDisplay.Value.ToString(NumberFormat);
				}
				return null;
			}
			if (base.IsIntegerValue)
			{
				if (base.IntegerValue.HasValue)
				{
					return base.IntegerValue.Value.ToString(NumberFormat);
				}
				return null;
			}
			if (base.IsStringValue)
			{
				return base.StringValue;
			}
			if (base.Value != null)
			{
				return base.Value.ToString();
			}
			return null;
		}

		protected double? GetDoubleValueToDisplay()
		{
			return base.DoubleValueAtDisplayUnit;
		}

		private void RefreshResolvedTextAlignment()
		{
			if (TextAlignment.HasValue)
			{
				ResolvedTextAlignment = TextAlignment.Value;
			}
			else if (base.IsDoubleValue || base.IsIntegerValue)
			{
				ResolvedTextAlignment = System.Windows.TextAlignment.Right;
			}
			else
			{
				ResolvedTextAlignment = System.Windows.TextAlignment.Left;
			}
		}
	}
