		private void UpdateGridControl()
		{
			if (_gc == null)
			{
				return;
			}
			List<DataColumn> list = new List<DataColumn>();
			foreach (AdsManualLayoutColumn column in Columns)
			{
				DataColumn dataColumn = column.GenerateDataColumn();
				dataColumn.Tag = column;
				list.Add(dataColumn);
			}
			_gc.DataSource = new DataTable(list);
		}

		public void InvalidateDataTable()
		{
			if (_updateDataTableFlag || _updatingAllData)
