		private void UpdateDataTable()
		{
			if (_gc == null || _gc.DataSource == null)
			{
				return;
			}
			DataTable dataSource = _gc.DataSource;
			List<DataRow> list = new List<DataRow>();
			foreach (AdsManualLayoutRow row in Rows)
			{
				DataRow dataRow = dataSource.CreateRow();
				dataRow.Tag = row;
				row.OnTableRowCreated(dataRow);
				list.Add(dataRow);
			}
			dataSource.UpdateRows(list);
		}

