		private void UpdateAllDataPipeline(Action update = null, Action afterUpdate = null)
		{
			_updatingAllData = true;
			ObservableCollection<AdsManualLayoutColumn> columns = Columns;
			ObservableCollection<AdsManualLayoutRow> rows = Rows;
			Columns.Clear();
			Rows.Clear();
			update?.Invoke();
			_updatingAllData = false;
			UpdateParentsLayOut(columns, Columns);
			UpdateParentsLayOut(rows, Rows);
			InvalidateGridControl();
			afterUpdate?.Invoke();
		}

		private void UpdateParentsLayOut(IList pOldItems, IList pNewItems)
		{
			IEnumerable<IAdsManualLayoutElement> enumerable = pOldItems?.OfType<IAdsManualLayoutElement>();
			IEnumerable<IAdsManualLayoutElement> enumerable2 = pNewItems?.OfType<IAdsManualLayoutElement>();
			if (enumerable != null)
