				{
					item.SetParentLayout(null);
				}
			}
			if (enumerable2 == null)
			{
				return;
			}
			foreach (IAdsManualLayoutElement item2 in enumerable2)
			{
				item2.SetParentLayout(this);
			}
		}
	}
