			}
			return base.GetCxsMoniker();
		}

		private void RefreshText()
		{
			if (ConvertedValue == null)
			{
				Text = null;
			}
			else if (ConvertedValue is double num)
			{
				Text = num.ToString(NumberFormat);
			}
			else
			{
				Text = ConvertedValue.ToString();
			}
		}

		private void RefreshValue()
		{
			if (AdbElement == null)
			{
				Value = null;
				return;
			}
			Type valueType = AdbElement.GetValueType();
			if (valueType == typeof(double) || valueType == typeof(double?))
			{
				double? num = null;
				double? num2 = AdsValueControl.FixAdsDoubleValue(AdbElement.GetDoubleValue());
				if (num2.HasValue)
				{
					num = num2;
					string finalDisplayUnit = GetFinalDisplayUnit();
					if (!string.IsNullOrWhiteSpace(finalDisplayUnit))
					{
						num = base.AdbUnitsProvider.ConvertFromSI(ResolvedUnitRow, num2.Value, finalDisplayUnit);
					}
				}
				Value = num;
			}
			else
			{
				Value = AdbElement.GetValue();
			}
		}

		private void RefreshAdbElement()
		{
			IAdbTopProvider adbTopProvider = base.AdbTopProvider;
			if (adbTopProvider == null || string.IsNullOrWhiteSpace(ValuePath))
			{
				AdbElement = null;
				return;
			}
			string text = base.Row.ParentLayout.FinalizeAdsPath(ValuePath);
			if (!string.IsNullOrWhiteSpace(text))
			{
				AdbElement = adbTopProvider.GetAccessorElement(text);
			}
			else
			{
				AdbElement = null;
			}
		}

		private void RefreshValuePath()
		{
			if (string.IsNullOrWhiteSpace(ValuePathBindingPath))
			{
				ClearValue(ValuePathProperty);
				return;
			}
			BindingOperations.SetBinding(this, ValuePathProperty, new Binding($"Row.ParentLayout.DataContext.{ValuePathBindingPath}")
			{
				Source = this,
				Mode = BindingMode.OneWay
			});
		}

		private void RefreshDisplayUnitBinding()
		{
			if (FindElementInManualLayout(LinkedUnitComboElementId) is AdsUnitComboBoxElement source)
			{
				BindingOperations.SetBinding(this, DisplayUnitProperty, new Binding
				{
					Source = source,
					Path = new PropertyPath(AdsUnitComboBoxElement.SelectedUnitProperty),
					Mode = BindingMode.OneWay
				});
			}
		}

		private void RefreshResolvedUnitRow()
		{
			ResolvedUnitRow = GetFinalUnitRow();
		}

		private int GetFinalUnitRow()
		{
			if (UnitRow.HasValue)
			{
				return UnitRow.Value;
			}
			if (!string.IsNullOrWhiteSpace(UnitRowPath))
			{
				if (base.AdbTopProvider != null)
				{
					string text = base.Row.ParentLayout.FinalizeAdsPath(UnitRowPath);
					if (!string.IsNullOrWhiteSpace(text))
					{
						return base.AdbTopProvider.GetAccessorElement(text).GetIntegerValue().GetValueOrDefault();
					}
				}
				return 0;
			}
			if (AdbElement != null)
			{
				return AdbElement.GetUnitRow().GetValueOrDefault();
			}
			return 0;
		}

		private string GetFinalDisplayUnit()
		{
			if (!string.IsNullOrWhiteSpace(DisplayUnit))
			{
				return DisplayUnit;
			}
			if (ResolvedUnitRow != 0 && base.AdbUnitsProvider != null)
			{
				return base.AdbUnitsProvider.GetDefaultDisplayUnits(ResolvedUnitRow);
			}
			return null;
		}

		private void RefreshResolvedHorizontalContentAlignment()
		{
			if (HorizontalContentAlignment.HasValue)
			{
				ResolvedHorizontalContentAlignment = HorizontalContentAlignment.Value;
			}
			else if (ConvertedValue != null && (ConvertedValue is int || ConvertedValue is double))
			{
				ResolvedHorizontalContentAlignment = HorizontalAlignment.Right;
			}
			else
			{
				ResolvedHorizontalContentAlignment = HorizontalAlignment.Left;
			}
		}

		private static void OnAdbElementPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			AdsTextBlockElement obj = d as AdsTextBlockElement;
			obj.RefreshResolvedUnitRow();
			obj.RefreshValue();
		}

