		private void RefreshResolvedUnitRow()
		{
			int resolvedUnitRow = 0;
			if (UnitRow != 0)
			{
				resolvedUnitRow = UnitRow;
			}
			else if (!string.IsNullOrWhiteSpace(UnitRowPath) && base.AdbTopProvider != null)
			{
				string text = base.Row.ParentLayout.FinalizeAdsPath(UnitRowPath);
				if (!string.IsNullOrWhiteSpace(text))
				{
					resolvedUnitRow = base.AdbTopProvider.GetAccessorElement(text).GetIntegerValue().GetValueOrDefault();
				}
			}
			ResolvedUnitRow = resolvedUnitRow;
		}

		private void RefreshUnitRowBinding()
		{
			if (FindElementInManualLayout(UnitRowSourceElementId) is AdsTextBlockElement source)
			{
				BindingOperations.SetBinding(this, UnitRowProperty, new Binding
				{
					Source = source,
					Path = new PropertyPath(AdsTextBlockElement.ResolvedUnitRowProperty),
					Mode = BindingMode.OneWay
				});
			}
		}

		private void RefreshSourceElementTextBinding()
		{
			if (FindElementInManualLayout(UnitRowSourceElementId) is AdsTextBlockElement source)
			{
				BindingOperations.SetBinding(this, SourceElementTextProperty, new Binding
				{
					Source = source,
					Path = new PropertyPath(AdsTextBlockElement.TextProperty),
					Mode = BindingMode.OneWay
				});
			}
		}

		private void RefreshUnitsList()
		{
			if (ResolvedUnitRow != 0 && base.AdbUnitsProvider != null)
			{
				UnitsList = base.AdbUnitsProvider.GetUnitsList(ResolvedUnitRow);
			}
			else
			{
				UnitsList = null;
			}
		}

		private void RefreshSelectedUnit(bool updateAnyway)
		{
			if (!SuppessSourceElementCheck && !string.IsNullOrWhiteSpace(UnitRowSourceElementId) && string.IsNullOrWhiteSpace(SourceElementText))
			{
				SelectedUnit = null;
				return;
			}
			string selectedUnit = SelectedUnit;
			if (UnitsList != null && UnitsList.Any())
			{
				if (updateAnyway || !UnitsList.Contains(selectedUnit))
				{
					if (ResolvedUnitRow != 0 && base.AdbUnitsProvider != null)
					{
						SelectedUnit = base.AdbUnitsProvider.GetDefaultDisplayUnits(ResolvedUnitRow);
					}
					else
					{
						SelectedUnit = UnitsList.FirstOrDefault();
					}
				}
			}
			else
			{
				SelectedUnit = null;
			}
		}

		private void RefreshIsReadOnly()
		{
			if (UnitsList == null || !UnitsList.Any())
			{
				IsReadOnly = true;
			}
			else if (!SuppessSourceElementCheck && !string.IsNullOrWhiteSpace(UnitRowSourceElementId) && string.IsNullOrWhiteSpace(SourceElementText))
			{
				IsReadOnly = true;
			}
			else
			{
				IsReadOnly = false;
			}
		}

