		{
			UnitRowPathProperty = DependencyProperty.Register("UnitRowPath", typeof(string), typeof(AdsUnitComboBox), new FrameworkPropertyMetadata(OnUnitRowPathPropertyChanged));
			UnitRowProperty = DependencyProperty.Register("UnitRow", typeof(int), typeof(AdsUnitComboBox), new FrameworkPropertyMetadata(OnUnitRowPropertyChanged));
