			SelectedUnitProperty = DependencyProperty.Register("SelectedUnit", typeof(string), typeof(AdsUnitComboBox), new FrameworkPropertyMetadata(OnSelectedUnitPropertyChanged));
			UseUsabilityControlProperty = DependencyProperty.Register("UseUsabilityControl", typeof(bool), typeof(AdsUnitComboBox), new FrameworkPropertyMetadata(OnUseUsabilityControlPropertyChanged));
			UsabilityControlValueProperty = DependencyProperty.Register("UsabilityControlValue", typeof(double?), typeof(AdsUnitComboBox), new FrameworkPropertyMetadata(OnUsabilityControlValuePropertyChanged));
			UnitsListPropertyKey = DependencyProperty.RegisterReadOnly("UnitsList", typeof(IEnumerable<string>), typeof(AdsUnitComboBox), new FrameworkPropertyMetadata(OnUnitsListPropertyChanged));
			UnitsListProperty = UnitsListPropertyKey.DependencyProperty;
			HasUnitPropertyKey = DependencyProperty.RegisterReadOnly("HasUnit", typeof(bool), typeof(AdsUnitComboBox), new FrameworkPropertyMetadata());
			HasUnitProperty = HasUnitPropertyKey.DependencyProperty;
			SelectedUnitChangedEvent = EventManager.RegisterRoutedEvent("SelectedUnitChanged", RoutingStrategy.Bubble, typeof(RoutedPropertyChangedEventHandler<string>), typeof(AdsUnitComboBox));
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(AdsUnitComboBox), new FrameworkPropertyMetadata(typeof(AdsUnitComboBox)));
			AdsControlBase.IgnoreAdsDataUpdatedEventProperty.OverrideMetadata(typeof(AdsUnitComboBox), new FrameworkPropertyMetadata(true));
		}

		protected override void OnFirstTimeLoaded()
		{
			RefreshResolvedUnitRow();
			RefreshUnitsList();
			RefreshHasUnit();
			base.OnFirstTimeLoaded();
		}

		protected override void OnUpdateDisplay(UpdateDisplayEventArgs args)
		{
			RefreshResolvedUnitRow();
			base.OnUpdateDisplay(args);
		}

		protected override void OnAdsDataUpdated(AdsDataUpdatedEventArgs args)
		{
			RefreshResolvedUnitRow();
			base.OnAdsDataUpdated(args);
		}

		protected override void OnAplusGlobalUnitSetChanged(AplusGlobalUnitSetChangedEventArgs args)
		{
			RefreshSelectedUnit(forceUpdate: true);
			base.OnAplusGlobalUnitSetChanged(args);
		}

		protected virtual void OnSelectedUnitChanged(string oldValue, string newValue)
		{
		}

		private void RefreshResolvedUnitRow()
		{
			int resolvedUnitRow = 0;
			if (UnitRow != 0)
			{
				resolvedUnitRow = UnitRow;
			}
			else if (!string.IsNullOrWhiteSpace(UnitRowPath) && base.AdbTopProvider != null)
			{
				string text = FinalizeAdsPath(UnitRowPath);
				if (!string.IsNullOrWhiteSpace(text))
				{
					resolvedUnitRow = base.AdbTopProvider.GetAccessorElement(text).GetIntegerValue().GetValueOrDefault();
				}
			}
			ResolvedUnitRow = resolvedUnitRow;
		}

		private void RefreshUnitsList()
		{
			if (UnitRow != 0 && base.AdbUnitsProvider != null)
			{
				IEnumerable<string> unitsList = base.AdbUnitsProvider.GetUnitsList(UnitRow);
				if (unitsList != null && unitsList.Any())
				{
					UnitsList = unitsList.ToList();
					return;
				}
			}
			UnitsList = null;
		}

		private void RefreshHasUnit()
		{
			if (UseUsabilityControl && !UsabilityControlValue.HasValue)
			{
				HasUnit = false;
			}
			else
			{
				HasUnit = UnitsList != null && UnitsList.Any();
			}
		}

		private void RefreshSelectedUnit(bool forceUpdate = false)
		{
			if (UseUsabilityControl && !UsabilityControlValue.HasValue)
			{
				SelectedUnit = null;
				return;
			}
			string selectedUnit = SelectedUnit;
			if (UnitsList != null && UnitsList.Any())
			{
				if (forceUpdate || !UnitsList.Contains(selectedUnit))
				{
					if (ResolvedUnitRow != 0 && base.AdbUnitsProvider != null)
					{
						SelectedUnit = base.AdbUnitsProvider.GetDefaultDisplayUnits(ResolvedUnitRow);
					}
					else
					{
						SelectedUnit = UnitsList.FirstOrDefault();
					}
				}
			}
			else
			{
				SelectedUnit = null;
			}
		}

		private static void OnUnitRowPathPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			(d as AdsUnitComboBox).RefreshResolvedUnitRow();
		}

		private static void OnUnitRowPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			(d as AdsUnitComboBox).RefreshResolvedUnitRow();
		}

		private static void OnResolvedUnitRowPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			(d as AdsUnitComboBox).RefreshUnitsList();
		}

		private static void OnUseUsabilityControlPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			AdsUnitComboBox obj = d as AdsUnitComboBox;
			obj.RefreshSelectedUnit();
			obj.RefreshHasUnit();
		}

		private static void OnUsabilityControlValuePropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			AdsUnitComboBox obj = d as AdsUnitComboBox;
			obj.RefreshSelectedUnit();
			obj.RefreshHasUnit();
		}

		private static void OnUnitsListPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			AdsUnitComboBox obj = d as AdsUnitComboBox;
			obj.RefreshSelectedUnit();
			obj.RefreshHasUnit();
		}

		private static void OnSelectedUnitPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			AdsUnitComboBox adsUnitComboBox = d as AdsUnitComboBox;
			string oldValue = (string)e.OldValue;
			string newValue = (string)e.NewValue;
			adsUnitComboBox.OnSelectedUnitChanged(oldValue, newValue);
			adsUnitComboBox.RaiseEvent(new RoutedPropertyChangedEventArgs<string>(oldValue, newValue, SelectedUnitChangedEvent)
			{
				Source = adsUnitComboBox
			});
		}
	}
